window.FG_FLK = window.FG_FLK || [];
window.FG_FLK.push([{"id":"n0277","sections":[{"name":"","text":"中华人民共和国社会保险法\n（2010年10月28日第十一届全国人民代表大会常务委员会第十七次会议通过 根据2018年12月29日第十三届全国人民代表大会常务委员会第七次会议《关于修改〈中华人民共和国社会保险法〉的决定》修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了规范社会保险关系，维护公民参加社会保险和享受社会保险待遇的合法权益，使公民共享发展成果，促进社会和谐稳定，根据宪法，制定本法。\n第二条 国家建立基本养老保险、基本医疗保险、工伤保险、失业保险、生育保险等社会保险制度，保障公民在年老、疾病、工伤、失业、生育等情况下依法从国家和社会获得物质帮助的权利。\n第三条 社会保险制度坚持广覆盖、保基本、多层次、可持续的方针，社会保险水平应当与经济社会发展水平相适应。\n第四条 中华人民共和国境内的用人单位和个人依法缴纳社会保险费，有权查询缴费记录、个人权益记录，要求社会保险经办机构提供社会保险咨询等相关服务。\n个人依法享受社会保险待遇，有权监督本单位为其缴费情况。\n第五条 县级以上人民政府将社会保险事业纳入国民经济和社会发展规划。\n国家多渠道筹集社会保险资金。县级以上人民政府对社会保险事业给予必要的经费支持。\n国家通过税收优惠政策支持社会保险事业。\n第六条 国家对社会保险基金实行严格监管。\n国务院和省、自治区、直辖市人民政府建立健全社会保险基金监督管理制度，保障社会保险基金安全、有效运行。\n县级以上人民政府采取措施，鼓励和支持社会各方面参与社会保险基金的监督。\n第七条 国务院社会保险行政部门负责全国的社会保险管理工作，国务院其他有关部门在各自的职责范围内负责有关的社会保险工作。\n县级以上地方人民政府社会保险行政部门负责本行政区域的社会保险管理工作，县级以上地方人民政府其他有关部门在各自的职责范围内负责有关的社会保险工作。\n第八条 社会保险经办机构提供社会保险服务，负责社会保险登记、个人权益记录、社会保险待遇支付等工作。\n第九条 工会依法维护职工的合法权益，有权参与社会保险重大事项的研究，参加社会保险监督委员会，对与职工社会保险权益有关的事项进行监督。","level":1},{"name":"第二章 基本养老保险","text":"第十条 职工应当参加基本养老保险，由用人单位和职工共同缴纳基本养老保险费。\n无雇工的个体工商户、未在用人单位参加基本养老保险的非全日制从业人员以及其他灵活就业人员可以参加基本养老保险，由个人缴纳基本养老保险费。\n公务员和参照公务员法管理的工作人员养老保险的办法由国务院规定。\n第十一条 基本养老保险实行社会统筹与个人账户相结合。\n基本养老保险基金由用人单位和个人缴费以及政府补贴等组成。\n第十二条 用人单位应当按照国家规定的本单位职工工资总额的比例缴纳基本养老保险费，记入基本养老保险统筹基金。\n职工应当按照国家规定的本人工资的比例缴纳基本养老保险费，记入个人账户。\n无雇工的个体工商户、未在用人单位参加基本养老保险的非全日制从业人员以及其他灵活就业人员参加基本养老保险的，应当按照国家规定缴纳基本养老保险费，分别记入基本养老保险统筹基金和个人账户。\n第十三条 国有企业、事业单位职工参加基本养老保险前，视同缴费年限期间应当缴纳的基本养老保险费由政府承担。\n基本养老保险基金出现支付不足时，政府给予补贴。\n第十四条 个人账户不得提前支取，记账利率不得低于银行定期存款利率，免征利息税。个人死亡的，个人账户余额可以继承。\n第十五条 基本养老金由统筹养老金和个人账户养老金组成。\n基本养老金根据个人累计缴费年限、缴费工资、当地职工平均工资、个人账户金额、城镇人口平均预期寿命等因素确定。\n第十六条 参加基本养老保险的个人，达到法定退休年龄时累计缴费满十五年的，按月领取基本养老金。\n参加基本养老保险的个人，达到法定退休年龄时累计缴费不足十五年的，可以缴费至满十五年，按月领取基本养老金；也可以转入新型农村社会养老保险或者城镇居民社会养老保险，按照国务院规定享受相应的养老保险待遇。\n第十七条 参加基本养老保险的个人，因病或者非因工死亡的，其遗属可以领取丧葬补助金和抚恤金；在未达到法定退休年龄时因病或者非因工致残完全丧失劳动能力的，可以领取病残津贴。所需资金从基本养老保险基金中支付。\n第十八条 国家建立基本养老金正常调整机制。根据职工平均工资增长、物价上涨情况，适时提高基本养老保险待遇水平。\n第十九条 个人跨统筹地区就业的，其基本养老保险关系随本人转移，缴费年限累计计算。个人达到法定退休年龄时，基本养老金分段计算、统一支付。具体办法由国务院规定。\n第二十条 国家建立和完善新型农村社会养老保险制度。\n新型农村社会养老保险实行个人缴费、集体补助和政府补贴相结合。\n第二十一条 新型农村社会养老保险待遇由基础养老金和个人账户养老金组成。\n参加新型农村社会养老保险的农村居民，符合国家规定条件的，按月领取新型农村社会养老保险待遇。\n第二十二条 国家建立和完善城镇居民社会养老保险制度。\n省、自治区、直辖市人民政府根据实际情况，可以将城镇居民社会养老保险和新型农村社会养老保险合并实施。","level":1},{"name":"第三章 基本医疗保险","text":"第二十三条 职工应当参加职工基本医疗保险，由用人单位和职工按照国家规定共同缴纳基本医疗保险费。\n无雇工的个体工商户、未在用人单位参加职工基本医疗保险的非全日制从业人员以及其他灵活就业人员可以参加职工基本医疗保险，由个人按照国家规定缴纳基本医疗保险费。\n第二十四条 国家建立和完善新型农村合作医疗制度。\n新型农村合作医疗的管理办法，由国务院规定。\n第二十五条 国家建立和完善城镇居民基本医疗保险制度。\n城镇居民基本医疗保险实行个人缴费和政府补贴相结合。\n享受最低生活保障的人、丧失劳动能力的残疾人、低收入家庭六十周岁以上的老年人和未成年人等所需个人缴费部分，由政府给予补贴。\n第二十六条 职工基本医疗保险、新型农村合作医疗和城镇居民基本医疗保险的待遇标准按照国家规定执行。\n第二十七条 参加职工基本医疗保险的个人，达到法定退休年龄时累计缴费达到国家规定年限的，退休后不再缴纳基本医疗保险费，按照国家规定享受基本医疗保险待遇；未达到国家规定年限的，可以缴费至国家规定年限。\n第二十八条 符合基本医疗保险药品目录、诊疗项目、医疗服务设施标准以及急诊、抢救的医疗费用，按照国家规定从基本医疗保险基金中支付。\n第二十九条 参保人员医疗费用中应当由基本医疗保险基金支付的部分，由社会保险经办机构与医疗机构、药品经营单位直接结算。\n社会保险行政部门和卫生行政部门应当建立异地就医医疗费用结算制度，方便参保人员享受基本医疗保险待遇。\n第三十条 下列医疗费用不纳入基本医疗保险基金支付范围：\n（一）应当从工伤保险基金中支付的；\n（二）应当由第三人负担的；\n（三）应当由公共卫生负担的；\n（四）在境外就医的。\n医疗费用依法应当由第三人负担，第三人不支付或者无法确定第三人的，由基本医疗保险基金先行支付。基本医疗保险基金先行支付后，有权向第三人追偿。\n第三十一条 社会保险经办机构根据管理服务的需要，可以与医疗机构、药品经营单位签订服务协议，规范医疗服务行为。\n医疗机构应当为参保人员提供合理、必要的医疗服务。\n第三十二条 个人跨统筹地区就业的，其基本医疗保险关系随本人转移，缴费年限累计计算。","level":1},{"name":"第四章 工伤保险","text":"第三十三条 职工应当参加工伤保险，由用人单位缴纳工伤保险费，职工不缴纳工伤保险费。\n第三十四条 国家根据不同行业的工伤风险程度确定行业的差别费率，并根据使用工伤保险基金、工伤发生率等情况在每个行业内确定费率档次。行业差别费率和行业内费率档次由国务院社会保险行政部门制定，报国务院批准后公布施行。\n社会保险经办机构根据用人单位使用工伤保险基金、工伤发生率和所属行业费率档次等情况，确定用人单位缴费费率。\n第三十五条 用人单位应当按照本单位职工工资总额，根据社会保险经办机构确定的费率缴纳工伤保险费。\n第三十六条 职工因工作原因受到事故伤害或者患职业病，且经工伤认定的，享受工伤保险待遇；其中，经劳动能力鉴定丧失劳动能力的，享受伤残待遇。\n工伤认定和劳动能力鉴定应当简捷、方便。\n第三十七条 职工因下列情形之一导致本人在工作中伤亡的，不认定为工伤：\n（一）故意犯罪；\n（二）醉酒或者吸毒；\n（三）自残或者自杀；\n（四）法律、行政法规规定的其他情形。\n第三十八条 因工伤发生的下列费用，按照国家规定从工伤保险基金中支付：\n（一）治疗工伤的医疗费用和康复费用；\n（二）住院伙食补助费；\n（三）到统筹地区以外就医的交通食宿费；\n（四）安装配置伤残辅助器具所需费用；\n（五）生活不能自理的，经劳动能力鉴定委员会确认的生活护理费；\n（六）一次性伤残补助金和一至四级伤残职工按月领取的伤残津贴；\n（七）终止或者解除劳动合同时，应当享受的一次性医疗补助金；\n（八）因工死亡的，其遗属领取的丧葬补助金、供养亲属抚恤金和因工死亡补助金；\n（九）劳动能力鉴定费。\n第三十九条 因工伤发生的下列费用，按照国家规定由用人单位支付：\n（一）治疗工伤期间的工资福利；\n（二）五级、六级伤残职工按月领取的伤残津贴；\n（三）终止或者解除劳动合同时，应当享受的一次性伤残就业补助金。\n第四十条 工伤职工符合领取基本养老金条件的，停发伤残津贴，享受基本养老保险待遇。基本养老保险待遇低于伤残津贴的，从工伤保险基金中补足差额。\n第四十一条 职工所在用人单位未依法缴纳工伤保险费，发生工伤事故的，由用人单位支付工伤保险待遇。用人单位不支付的，从工伤保险基金中先行支付。\n从工伤保险基金中先行支付的工伤保险待遇应当由用人单位偿还。用人单位不偿还的，社会保险经办机构可以依照本法第六十三条的规定追偿。\n第四十二条 由于第三人的原因造成工伤，第三人不支付工伤医疗费用或者无法确定第三人的，由工伤保险基金先行支付。工伤保险基金先行支付后，有权向第三人追偿。\n第四十三条 工伤职工有下列情形之一的，停止享受工伤保险待遇：\n（一）丧失享受待遇条件的；\n（二）拒不接受劳动能力鉴定的；\n（三）拒绝治疗的。","level":1},{"name":"第五章 失业保险","text":"第四十四条 职工应当参加失业保险，由用人单位和职工按照国家规定共同缴纳失业保险费。\n第四十五条 失业人员符合下列条件的，从失业保险基金中领取失业保险金：\n（一）失业前用人单位和本人已经缴纳失业保险费满一年的；\n（二）非因本人意愿中断就业的；\n（三）已经进行失业登记，并有求职要求的。\n第四十六条 失业人员失业前用人单位和本人累计缴费满一年不足五年的，领取失业保险金的期限最长为十二个月；累计缴费满五年不足十年的，领取失业保险金的期限最长为十八个月；累计缴费十年以上的，领取失业保险金的期限最长为二十四个月。重新就业后，再次失业的，缴费时间重新计算，领取失业保险金的期限与前次失业应当领取而尚未领取的失业保险金的期限合并计算，最长不超过二十四个月。\n第四十七条 失业保险金的标准，由省、自治区、直辖市人民政府确定，不得低于城市居民最低生活保障标准。\n第四十八条 失业人员在领取失业保险金期间，参加职工基本医疗保险，享受基本医疗保险待遇。\n失业人员应当缴纳的基本医疗保险费从失业保险基金中支付，个人不缴纳基本医疗保险费。\n第四十九条 失业人员在领取失业保险金期间死亡的，参照当地对在职职工死亡的规定，向其遗属发给一次性丧葬补助金和抚恤金。所需资金从失业保险基金中支付。\n个人死亡同时符合领取基本养老保险丧葬补助金、工伤保险丧葬补助金和失业保险丧葬补助金条件的，其遗属只能选择领取其中的一项。\n第五十条 用人单位应当及时为失业人员出具终止或者解除劳动关系的证明，并将失业人员的名单自终止或者解除劳动关系之日起十五日内告知社会保险经办机构。\n失业人员应当持本单位为其出具的终止或者解除劳动关系的证明，及时到指定的公共就业服务机构办理失业登记。\n失业人员凭失业登记证明和个人身份证明，到社会保险经办机构办理领取失业保险金的手续。失业保险金领取期限自办理失业登记之日起计算。\n第五十一条 失业人员在领取失业保险金期间有下列情形之一的，停止领取失业保险金，并同时停止享受其他失业保险待遇：\n（一）重新就业的；\n（二）应征服兵役的；\n（三）移居境外的；\n（四）享受基本养老保险待遇的；\n（五）无正当理由，拒不接受当地人民政府指定部门或者机构介绍的适当工作或者提供的培训的。\n第五十二条 职工跨统筹地区就业的，其失业保险关系随本人转移，缴费年限累计计算。","level":1},{"name":"第六章 生育保险","text":"第五十三条 职工应当参加生育保险，由用人单位按照国家规定缴纳生育保险费，职工不缴纳生育保险费。\n第五十四条 用人单位已经缴纳生育保险费的，其职工享受生育保险待遇；职工未就业配偶按照国家规定享受生育医疗费用待遇。所需资金从生育保险基金中支付。\n生育保险待遇包括生育医疗费用和生育津贴。\n第五十五条 生育医疗费用包括下列各项：\n（一）生育的医疗费用；\n（二）计划生育的医疗费用；\n（三）法律、法规规定的其他项目费用。\n第五十六条 职工有下列情形之一的，可以按照国家规定享受生育津贴：\n（一）女职工生育享受产假；\n（二）享受计划生育手术休假；\n（三）法律、法规规定的其他情形。\n生育津贴按照职工所在用人单位上年度职工月平均工资计发。","level":1},{"name":"第七章 社会保险费征缴","text":"第五十七条 用人单位应当自成立之日起三十日内凭营业执照、登记证书或者单位印章，向当地社会保险经办机构申请办理社会保险登记。社会保险经办机构应当自收到申请之日起十五日内予以审核，发给社会保险登记证件。\n用人单位的社会保险登记事项发生变更或者用人单位依法终止的，应当自变更或者终止之日起三十日内，到社会保险经办机构办理变更或者注销社会保险登记。\n市场监督管理部门、民政部门和机构编制管理机关应当及时向社会保险经办机构通报用人单位的成立、终止情况，公安机关应当及时向社会保险经办机构通报个人的出生、死亡以及户口登记、迁移、注销等情况。\n第五十八条 用人单位应当自用工之日起三十日内为其职工向社会保险经办机构申请办理社会保险登记。未办理社会保险登记的，由社会保险经办机构核定其应当缴纳的社会保险费。\n自愿参加社会保险的无雇工的个体工商户、未在用人单位参加社会保险的非全日制从业人员以及其他灵活就业人员，应当向社会保险经办机构申请办理社会保险登记。\n国家建立全国统一的个人社会保障号码。个人社会保障号码为公民身份号码。\n第五十九条 县级以上人民政府加强社会保险费的征收工作。\n社会保险费实行统一征收，实施步骤和具体办法由国务院规定。\n第六十条 用人单位应当自行申报、按时足额缴纳社会保险费，非因不可抗力等法定事由不得缓缴、减免。职工应当缴纳的社会保险费由用人单位代扣代缴，用人单位应当按月将缴纳社会保险费的明细情况告知本人。\n无雇工的个体工商户、未在用人单位参加社会保险的非全日制从业人员以及其他灵活就业人员，可以直接向社会保险费征收机构缴纳社会保险费。\n第六十一条 社会保险费征收机构应当依法按时足额征收社会保险费，并将缴费情况定期告知用人单位和个人。\n第六十二条 用人单位未按规定申报应当缴纳的社会保险费数额的，按照该单位上月缴费额的百分之一百一十确定应当缴纳数额；缴费单位补办申报手续后，由社会保险费征收机构按照规定结算。\n第六十三条 用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令其限期缴纳或者补足。\n用人单位逾期仍未缴纳或者补足社会保险费的，社会保险费征收机构可以向银行和其他金融机构查询其存款账户；并可以申请县级以上有关行政部门作出划拨社会保险费的决定，书面通知其开户银行或者其他金融机构划拨社会保险费。用人单位账户余额少于应当缴纳的社会保险费的，社会保险费征收机构可以要求该用人单位提供担保，签订延期缴费协议。\n用人单位未足额缴纳社会保险费且未提供担保的，社会保险费征收机构可以申请人民法院扣押、查封、拍卖其价值相当于应当缴纳社会保险费的财产，以拍卖所得抵缴社会保险费。","level":1},{"name":"第八章 社会保险基金","text":"第六十四条 社会保险基金包括基本养老保险基金、基本医疗保险基金、工伤保险基金、失业保险基金和生育保险基金。除基本医疗保险基金与生育保险基金合并建账及核算外，其他各项社会保险基金按照社会保险险种分别建账，分账核算。社会保险基金执行国家统一的会计制度。\n社会保险基金专款专用，任何组织和个人不得侵占或者挪用。\n基本养老保险基金逐步实行全国统筹，其他社会保险基金逐步实行省级统筹，具体时间、步骤由国务院规定。\n第六十五条 社会保险基金通过预算实现收支平衡。\n县级以上人民政府在社会保险基金出现支付不足时，给予补贴。\n第六十六条 社会保险基金按照统筹层次设立预算。除基本医疗保险基金与生育保险基金预算合并编制外，其他社会保险基金预算按照社会保险项目分别编制。\n第六十七条 社会保险基金预算、决算草案的编制、审核和批准，依照法律和国务院规定执行。\n第六十八条 社会保险基金存入财政专户，具体管理办法由国务院规定。\n第六十九条 社会保险基金在保证安全的前提下，按照国务院规定投资运营实现保值增值。\n社会保险基金不得违规投资运营，不得用于平衡其他政府预算，不得用于兴建、改建办公场所和支付人员经费、运行费用、管理费用，或者违反法律、行政法规规定挪作其他用途。\n第七十条 社会保险经办机构应当定期向社会公布参加社会保险情况以及社会保险基金的收入、支出、结余和收益情况。\n第七十一条 国家设立全国社会保障基金，由中央财政预算拨款以及国务院批准的其他方式筹集的资金构成，用于社会保障支出的补充、调剂。全国社会保障基金由全国社会保障基金管理运营机构负责管理运营，在保证安全的前提下实现保值增值。\n全国社会保障基金应当定期向社会公布收支、管理和投资运营的情况。国务院财政部门、社会保险行政部门、审计机关对全国社会保障基金的收支、管理和投资运营情况实施监督。","level":1},{"name":"第九章 社会保险经办","text":"第七十二条 统筹地区设立社会保险经办机构。社会保险经办机构根据工作需要，经所在地的社会保险行政部门和机构编制管理机关批准，可以在本统筹地区设立分支机构和服务网点。\n社会保险经办机构的人员经费和经办社会保险发生的基本运行费用、管理费用，由同级财政按照国家规定予以保障。\n第七十三条 社会保险经办机构应当建立健全业务、财务、安全和风险管理制度。\n社会保险经办机构应当按时足额支付社会保险待遇。\n第七十四条 社会保险经办机构通过业务经办、统计、调查获取社会保险工作所需的数据，有关单位和个人应当及时、如实提供。\n社会保险经办机构应当及时为用人单位建立档案，完整、准确地记录参加社会保险的人员、缴费等社会保险数据，妥善保管登记、申报的原始凭证和支付结算的会计凭证。\n社会保险经办机构应当及时、完整、准确地记录参加社会保险的个人缴费和用人单位为其缴费，以及享受社会保险待遇等个人权益记录，定期将个人权益记录单免费寄送本人。\n用人单位和个人可以免费向社会保险经办机构查询、核对其缴费和享受社会保险待遇记录，要求社会保险经办机构提供社会保险咨询等相关服务。\n第七十五条 全国社会保险信息系统按照国家统一规划，由县级以上人民政府按照分级负责的原则共同建设。","level":1},{"name":"第十章 社会保险监督","text":"第七十六条 各级人民代表大会常务委员会听取和审议本级人民政府对社会保险基金的收支、管理、投资运营以及监督检查情况的专项工作报告，组织对本法实施情况的执法检查等，依法行使监督职权。\n第七十七条 县级以上人民政府社会保险行政部门应当加强对用人单位和个人遵守社会保险法律、法规情况的监督检查。\n社会保险行政部门实施监督检查时，被检查的用人单位和个人应当如实提供与社会保险有关的资料，不得拒绝检查或者谎报、瞒报。\n第七十八条 财政部门、审计机关按照各自职责，对社会保险基金的收支、管理和投资运营情况实施监督。\n第七十九条 社会保险行政部门对社会保险基金的收支、管理和投资运营情况进行监督检查，发现存在问题的，应当提出整改建议，依法作出处理决定或者向有关行政部门提出处理建议。社会保险基金检查结果应当定期向社会公布。\n社会保险行政部门对社会保险基金实施监督检查，有权采取下列措施：\n（一）查阅、记录、复制与社会保险基金收支、管理和投资运营相关的资料，对可能被转移、隐匿或者灭失的资料予以封存；\n（二）询问与调查事项有关的单位和个人，要求其对与调查事项有关的问题作出说明、提供有关证明材料；\n（三）对隐匿、转移、侵占、挪用社会保险基金的行为予以制止并责令改正。\n第八十条 统筹地区人民政府成立由用人单位代表、参保人员代表，以及工会代表、专家等组成的社会保险监督委员会，掌握、分析社会保险基金的收支、管理和投资运营情况，对社会保险工作提出咨询意见和建议，实施社会监督。\n社会保险经办机构应当定期向社会保险监督委员会汇报社会保险基金的收支、管理和投资运营情况。社会保险监督委员会可以聘请会计师事务所对社会保险基金的收支、管理和投资运营情况进行年度审计和专项审计。审计结果应当向社会公开。\n社会保险监督委员会发现社会保险基金收支、管理和投资运营中存在问题的，有权提出改正建议；对社会保险经办机构及其工作人员的违法行为，有权向有关部门提出依法处理建议。\n第八十一条 社会保险行政部门和其他有关行政部门、社会保险经办机构、社会保险费征收机构及其工作人员，应当依法为用人单位和个人的信息保密，不得以任何形式泄露。\n第八十二条 任何组织或者个人有权对违反社会保险法律、法规的行为进行举报、投诉。\n社会保险行政部门、卫生行政部门、社会保险经办机构、社会保险费征收机构和财政部门、审计机关对属于本部门、本机构职责范围的举报、投诉，应当依法处理；对不属于本部门、本机构职责范围的，应当书面通知并移交有权处理的部门、机构处理。有权处理的部门、机构应当及时处理，不得推诿。\n第八十三条 用人单位或者个人认为社会保险费征收机构的行为侵害自己合法权益的，可以依法申请行政复议或者提起行政诉讼。\n用人单位或者个人对社会保险经办机构不依法办理社会保险登记、核定社会保险费、支付社会保险待遇、办理社会保险转移接续手续或者侵害其他社会保险权益的行为，可以依法申请行政复议或者提起行政诉讼。\n个人与所在用人单位发生社会保险争议的，可以依法申请调解、仲裁，提起诉讼。用人单位侵害个人社会保险权益的，个人也可以要求社会保险行政部门或者社会保险费征收机构依法处理。","level":1},{"name":"第十一章 法律责任","text":"第八十四条 用人单位不办理社会保险登记的，由社会保险行政部门责令限期改正；逾期不改正的，对用人单位处应缴社会保险费数额一倍以上三倍以下的罚款，对其直接负责的主管人员和其他直接责任人员处五百元以上三千元以下的罚款。\n第八十五条 用人单位拒不出具终止或者解除劳动关系证明的，依照《中华人民共和国劳动合同法》的规定处理。\n第八十六条 用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令限期缴纳或者补足，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，由有关行政部门处欠缴数额一倍以上三倍以下的罚款。\n第八十七条 社会保险经办机构以及医疗机构、药品经营单位等社会保险服务机构以欺诈、伪造证明材料或者其他手段骗取社会保险基金支出的，由社会保险行政部门责令退回骗取的社会保险金，处骗取金额二倍以上五倍以下的罚款；属于社会保险服务机构的，解除服务协议；直接负责的主管人员和其他直接责任人员有执业资格的，依法吊销其执业资格。\n第八十八条 以欺诈、伪造证明材料或者其他手段骗取社会保险待遇的，由社会保险行政部门责令退回骗取的社会保险金，处骗取金额二倍以上五倍以下的罚款。\n第八十九条 社会保险经办机构及其工作人员有下列行为之一的，由社会保险行政部门责令改正；给社会保险基金、用人单位或者个人造成损失的，依法承担赔偿责任；对直接负责的主管人员和其他直接责任人员依法给予处分：\n（一）未履行社会保险法定职责的；\n（二）未将社会保险基金存入财政专户的；\n（三）克扣或者拒不按时支付社会保险待遇的；\n（四）丢失或者篡改缴费记录、享受社会保险待遇记录等社会保险数据、个人权益记录的；\n（五）有违反社会保险法律、法规的其他行为的。\n第九十条 社会保险费征收机构擅自更改社会保险费缴费基数、费率，导致少收或者多收社会保险费的，由有关行政部门责令其追缴应当缴纳的社会保险费或者退还不应当缴纳的社会保险费；对直接负责的主管人员和其他直接责任人员依法给予处分。\n第九十一条 违反本法规定，隐匿、转移、侵占、挪用社会保险基金或者违规投资运营的，由社会保险行政部门、财政部门、审计机关责令追回；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员依法给予处分。\n第九十二条 社会保险行政部门和其他有关行政部门、社会保险经办机构、社会保险费征收机构及其工作人员泄露用人单位和个人信息的，对直接负责的主管人员和其他直接责任人员依法给予处分；给用人单位或者个人造成损失的，应当承担赔偿责任。\n第九十三条 国家工作人员在社会保险管理、监督工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。\n第九十四条 违反本法规定，构成犯罪的，依法追究刑事责任。","level":1},{"name":"第十二章 附 则","text":"第九十五条 进城务工的农村居民依照本法规定参加社会保险。\n第九十六条 征收农村集体所有的土地，应当足额安排被征地农民的社会保险费，按照国务院规定将被征地农民纳入相应的社会保险制度。\n第九十七条 外国人在中国境内就业的，参照本法规定参加社会保险。\n第九十八条 本法自2011年7月1日起施行。","level":1}]},{"id":"n0278","sections":[{"name":"","text":"中华人民共和国义务教育法\n（1986年4月12日第六届全国人民代表大会第四次会议通过 2006年6月29日第十届全国人民代表大会常务委员会第二十二次会议修订 根据2015年4月24日第十二届全国人民代表大会常务委员会第十四次会议《关于修改〈中华人民共和国义务教育法〉等五部法律的决定》第一次修正 根据2018年12月29日第十三届全国人民代表大会常务委员会第七次会议《关于修改〈中华人民共和国产品质量法〉等五部法律的决定》第二次修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了保障适龄儿童、少年接受义务教育的权利，保证义务教育的实施，提高全民族素质，根据宪法和教育法，制定本法。\n第二条 国家实行九年义务教育制度。\n义务教育是国家统一实施的所有适龄儿童、少年必须接受的教育，是国家必须予以保障的公益性事业。\n实施义务教育，不收学费、杂费。\n国家建立义务教育经费保障机制，保证义务教育制度实施。\n第三条 义务教育必须贯彻国家的教育方针，实施素质教育，提高教育质量，使适龄儿童、少年在品德、智力、体质等方面全面发展，为培养有理想、有道德、有文化、有纪律的社会主义建设者和接班人奠定基础。\n第四条 凡具有中华人民共和国国籍的适龄儿童、少年，不分性别、民族、种族、家庭财产状况、宗教信仰等，依法享有平等接受义务教育的权利，并履行接受义务教育的义务。\n第五条 各级人民政府及其有关部门应当履行本法规定的各项职责，保障适龄儿童、少年接受义务教育的权利。\n适龄儿童、少年的父母或者其他法定监护人应当依法保证其按时入学接受并完成义务教育。\n依法实施义务教育的学校应当按照规定标准完成教育教学任务，保证教育教学质量。\n社会组织和个人应当为适龄儿童、少年接受义务教育创造良好的环境。\n第六条 国务院和县级以上地方人民政府应当合理配置教育资源，促进义务教育均衡发展，改善薄弱学校的办学条件，并采取措施，保障农村地区、民族地区实施义务教育，保障家庭经济困难的和残疾的适龄儿童、少年接受义务教育。\n国家组织和鼓励经济发达地区支援经济欠发达地区实施义务教育。\n第七条 义务教育实行国务院领导，省、自治区、直辖市人民政府统筹规划实施，县级人民政府为主管理的体制。\n县级以上人民政府教育行政部门具体负责义务教育实施工作；县级以上人民政府其他有关部门在各自的职责范围内负责义务教育实施工作。\n第八条 人民政府教育督导机构对义务教育工作执行法律法规情况、教育教学质量以及义务教育均衡发展状况等进行督导，督导报告向社会公布。\n第九条 任何社会组织或者个人有权对违反本法的行为向有关国家机关提出检举或者控告。\n发生违反本法的重大事件，妨碍义务教育实施，造成重大社会影响的，负有领导责任的人民政府或者人民政府教育行政部门负责人应当引咎辞职。\n第十条 对在义务教育实施工作中做出突出贡献的社会组织和个人，各级人民政府及其有关部门按照有关规定给予表彰、奖励。","level":1},{"name":"第二章 学 生","text":"第十一条 凡年满六周岁的儿童，其父母或者其他法定监护人应当送其入学接受并完成义务教育；条件不具备的地区的儿童，可以推迟到七周岁。\n适龄儿童、少年因身体状况需要延缓入学或者休学的，其父母或者其他法定监护人应当提出申请，由当地乡镇人民政府或者县级人民政府教育行政部门批准。\n第十二条 适龄儿童、少年免试入学。地方各级人民政府应当保障适龄儿童、少年在户籍所在地学校就近入学。\n父母或者其他法定监护人在非户籍所在地工作或者居住的适龄儿童、少年，在其父母或者其他法定监护人工作或者居住地接受义务教育的，当地人民政府应当为其提供平等接受义务教育的条件。具体办法由省、自治区、直辖市规定。\n县级人民政府教育行政部门对本行政区域内的军人子女接受义务教育予以保障。\n第十三条 县级人民政府教育行政部门和乡镇人民政府组织和督促适龄儿童、少年入学，帮助解决适龄儿童、少年接受义务教育的困难，采取措施防止适龄儿童、少年辍学。\n居民委员会和村民委员会协助政府做好工作，督促适龄儿童、少年入学。\n第十四条 禁止用人单位招用应当接受义务教育的适龄儿童、少年。\n根据国家有关规定经批准招收适龄儿童、少年进行文艺、体育等专业训练的社会组织，应当保证所招收的适龄儿童、少年接受义务教育；自行实施义务教育的，应当经县级人民政府教育行政部门批准。","level":1},{"name":"第三章 学 校","text":"第十五条 县级以上地方人民政府根据本行政区域内居住的适龄儿童、少年的数量和分布状况等因素，按照国家有关规定，制定、调整学校设置规划。新建居民区需要设置学校的，应当与居民区的建设同步进行。\n第十六条 学校建设，应当符合国家规定的办学标准，适应教育教学需要；应当符合国家规定的选址要求和建设标准，确保学生和教职工安全。\n第十七条 县级人民政府根据需要设置寄宿制学校，保障居住分散的适龄儿童、少年入学接受义务教育。\n第十八条 国务院教育行政部门和省、自治区、直辖市人民政府根据需要，在经济发达地区设置接收少数民族适龄儿童、少年的学校（班）。\n第十九条 县级以上地方人民政府根据需要设置相应的实施特殊教育的学校（班），对视力残疾、听力语言残疾和智力残疾的适龄儿童、少年实施义务教育。特殊教育学校（班）应当具备适应残疾儿童、少年学习、康复、生活特点的场所和设施。\n普通学校应当接收具有接受普通教育能力的残疾适龄儿童、少年随班就读，并为其学习、康复提供帮助。\n第二十条 县级以上地方人民政府根据需要，为具有预防未成年人犯罪法规定的严重不良行为的适龄少年设置专门的学校实施义务教育。\n第二十一条 对未完成义务教育的未成年犯和被采取强制性教育措施的未成年人应当进行义务教育，所需经费由人民政府予以保障。\n第二十二条 县级以上人民政府及其教育行政部门应当促进学校均衡发展，缩小学校之间办学条件的差距，不得将学校分为重点学校和非重点学校。学校不得分设重点班和非重点班。\n县级以上人民政府及其教育行政部门不得以任何名义改变或者变相改变公办学校的性质。\n第二十三条 各级人民政府及其有关部门依法维护学校周边秩序，保护学生、教师、学校的合法权益，为学校提供安全保障。\n第二十四条 学校应当建立、健全安全制度和应急机制，对学生进行安全教育，加强管理，及时消除隐患，预防发生事故。\n县级以上地方人民政府定期对学校校舍安全进行检查；对需要维修、改造的，及时予以维修、改造。\n学校不得聘用曾经因故意犯罪被依法剥夺政治权利或者其他不适合从事义务教育工作的人担任工作人员。\n第二十五条 学校不得违反国家规定收取费用，不得以向学生推销或者变相推销商品、服务等方式谋取利益。\n第二十六条 学校实行校长负责制。校长应当符合国家规定的任职条件。校长由县级人民政府教育行政部门依法聘任。\n第二十七条 对违反学校管理制度的学生，学校应当予以批评教育，不得开除。","level":1},{"name":"第四章 教 师","text":"第二十八条 教师享有法律规定的权利，履行法律规定的义务，应当为人师表，忠诚于人民的教育事业。\n全社会应当尊重教师。\n第二十九条 教师在教育教学中应当平等对待学生，关注学生的个体差异，因材施教，促进学生的充分发展。\n教师应当尊重学生的人格，不得歧视学生，不得对学生实施体罚、变相体罚或者其他侮辱人格尊严的行为，不得侵犯学生合法权益。\n第三十条 教师应当取得国家规定的教师资格。\n国家建立统一的义务教育教师职务制度。教师职务分为初级职务、中级职务和高级职务。\n第三十一条 各级人民政府保障教师工资福利和社会保险待遇，改善教师工作和生活条件；完善农村教师工资经费保障机制。\n教师的平均工资水平应当不低于当地公务员的平均工资水平。\n特殊教育教师享有特殊岗位补助津贴。在民族地区和边远贫困地区工作的教师享有艰苦贫困地区补助津贴。\n第三十二条 县级以上人民政府应当加强教师培养工作，采取措施发展教师教育。\n县级人民政府教育行政部门应当均衡配置本行政区域内学校师资力量，组织校长、教师的培训和流动，加强对薄弱学校的建设。\n第三十三条 国务院和地方各级人民政府鼓励和支持城市学校教师和高等学校毕业生到农村地区、民族地区从事义务教育工作。\n国家鼓励高等学校毕业生以志愿者的方式到农村地区、民族地区缺乏教师的学校任教。县级人民政府教育行政部门依法认定其教师资格，其任教时间计入工龄。","level":1},{"name":"第五章 教育教学","text":"第三十四条 教育教学工作应当符合教育规律和学生身心发展特点，面向全体学生，教书育人，将德育、智育、体育、美育等有机统一在教育教学活动中，注重培养学生独立思考能力、创新能力和实践能力，促进学生全面发展。\n第三十五条 国务院教育行政部门根据适龄儿童、少年身心发展的状况和实际情况，确定教学制度、教育教学内容和课程设置，改革考试制度，并改进高级中等学校招生办法，推进实施素质教育。\n学校和教师按照确定的教育教学内容和课程设置开展教育教学活动，保证达到国家规定的基本质量要求。\n国家鼓励学校和教师采用启发式教育等教育教学方法，提高教育教学质量。\n第三十六条 学校应当把德育放在首位，寓德育于教育教学之中，开展与学生年龄相适应的社会实践活动，形成学校、家庭、社会相互配合的思想道德教育体系，促进学生养成良好的思想品德和行为习惯。\n第三十七条 学校应当保证学生的课外活动时间，组织开展文化娱乐等课外活动。社会公共文化体育设施应当为学校开展课外活动提供便利。\n第三十八条 教科书根据国家教育方针和课程标准编写，内容力求精简，精选必备的基础知识、基本技能，经济实用，保证质量。\n国家机关工作人员和教科书审查人员，不得参与或者变相参与教科书的编写工作。\n第三十九条 国家实行教科书审定制度。教科书的审定办法由国务院教育行政部门规定。\n未经审定的教科书，不得出版、选用。\n第四十条 教科书价格由省、自治区、直辖市人民政府价格行政部门会同同级出版主管部门按照微利原则确定。\n第四十一条 国家鼓励教科书循环使用。","level":1},{"name":"第六章 经费保障","text":"第四十二条 国家将义务教育全面纳入财政保障范围，义务教育经费由国务院和地方各级人民政府依照本法规定予以保障。\n国务院和地方各级人民政府将义务教育经费纳入财政预算，按照教职工编制标准、工资标准和学校建设标准、学生人均公用经费标准等，及时足额拨付义务教育经费，确保学校的正常运转和校舍安全，确保教职工工资按照规定发放。\n国务院和地方各级人民政府用于实施义务教育财政拨款的增长比例应当高于财政经常性收入的增长比例，保证按照在校学生人数平均的义务教育费用逐步增长，保证教职工工资和学生人均公用经费逐步增长。\n第四十三条 学校的学生人均公用经费基本标准由国务院财政部门会同教育行政部门制定，并根据经济和社会发展状况适时调整。制定、调整学生人均公用经费基本标准，应当满足教育教学基本需要。\n省、自治区、直辖市人民政府可以根据本行政区域的实际情况，制定不低于国家标准的学校学生人均公用经费标准。\n特殊教育学校（班）学生人均公用经费标准应当高于普通学校学生人均公用经费标准。\n第四十四条 义务教育经费投入实行国务院和地方各级人民政府根据职责共同负担，省、自治区、直辖市人民政府负责统筹落实的体制。农村义务教育所需经费，由各级人民政府根据国务院的规定分项目、按比例分担。\n各级人民政府对家庭经济困难的适龄儿童、少年免费提供教科书并补助寄宿生生活费。\n义务教育经费保障的具体办法由国务院规定。\n第四十五条 地方各级人民政府在财政预算中将义务教育经费单列。\n县级人民政府编制预算，除向农村地区学校和薄弱学校倾斜外，应当均衡安排义务教育经费。\n第四十六条 国务院和省、自治区、直辖市人民政府规范财政转移支付制度，加大一般性转移支付规模和规范义务教育专项转移支付，支持和引导地方各级人民政府增加对义务教育的投入。地方各级人民政府确保将上级人民政府的义务教育转移支付资金按照规定用于义务教育。\n第四十七条 国务院和县级以上地方人民政府根据实际需要，设立专项资金，扶持农村地区、民族地区实施义务教育。\n第四十八条 国家鼓励社会组织和个人向义务教育捐赠，鼓励按照国家有关基金会管理的规定设立义务教育基金。\n第四十九条 义务教育经费严格按照预算规定用于义务教育；任何组织和个人不得侵占、挪用义务教育经费，不得向学校非法收取或者摊派费用。\n第五十条 县级以上人民政府建立健全义务教育经费的审计监督和统计公告制度。","level":1},{"name":"第七章 法律责任","text":"第五十一条 国务院有关部门和地方各级人民政府违反本法第六章的规定，未履行对义务教育经费保障职责的，由国务院或者上级地方人民政府责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。\n第五十二条 县级以上地方人民政府有下列情形之一的，由上级人民政府责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分：\n（一）未按照国家有关规定制定、调整学校的设置规划的；\n（二）学校建设不符合国家规定的办学标准、选址要求和建设标准的；\n（三）未定期对学校校舍安全进行检查，并及时维修、改造的；\n（四）未依照本法规定均衡安排义务教育经费的。\n第五十三条 县级以上人民政府或者其教育行政部门有下列情形之一的，由上级人民政府或者其教育行政部门责令限期改正、通报批评；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分：\n（一）将学校分为重点学校和非重点学校的；\n（二）改变或者变相改变公办学校性质的。\n县级人民政府教育行政部门或者乡镇人民政府未采取措施组织适龄儿童、少年入学或者防止辍学的，依照前款规定追究法律责任。\n第五十四条 有下列情形之一的，由上级人民政府或者上级人民政府教育行政部门、财政部门、价格行政部门和审计机关根据职责分工责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分：\n（一）侵占、挪用义务教育经费的；\n（二）向学校非法收取或者摊派费用的。\n第五十五条 学校或者教师在义务教育工作中违反教育法、教师法规定的，依照教育法、教师法的有关规定处罚。\n第五十六条 学校违反国家规定收取费用的，由县级人民政府教育行政部门责令退还所收费用；对直接负责的主管人员和其他直接责任人员依法给予处分。\n学校以向学生推销或者变相推销商品、服务等方式谋取利益的，由县级人民政府教育行政部门给予通报批评；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员依法给予处分。\n国家机关工作人员和教科书审查人员参与或者变相参与教科书编写的，由县级以上人民政府或者其教育行政部门根据职责权限责令限期改正，依法给予行政处分；有违法所得的，没收违法所得。\n第五十七条 学校有下列情形之一的，由县级人民政府教育行政部门责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分：\n（一）拒绝接收具有接受普通教育能力的残疾适龄儿童、少年随班就读的；\n（二）分设重点班和非重点班的；\n（三）违反本法规定开除学生的；\n（四）选用未经审定的教科书的。\n第五十八条 适龄儿童、少年的父母或者其他法定监护人无正当理由未依照本法规定送适龄儿童、少年入学接受义务教育的，由当地乡镇人民政府或者县级人民政府教育行政部门给予批评教育，责令限期改正。\n第五十九条 有下列情形之一的，依照有关法律、行政法规的规定予以处罚：\n（一）胁迫或者诱骗应当接受义务教育的适龄儿童、少年失学、辍学的；\n（二）非法招用应当接受义务教育的适龄儿童、少年的；\n（三）出版未经依法审定的教科书的。\n第六十条 违反本法规定，构成犯罪的，依法追究刑事责任。","level":1},{"name":"第八章 附 则","text":"第六十一条 对接受义务教育的适龄儿童、少年不收杂费的实施步骤，由国务院规定。\n第六十二条 社会组织或者个人依法举办的民办学校实施义务教育的，依照民办教育促进法有关规定执行；民办教育促进法未作规定的，适用本法。\n第六十三条 本法自2006年9月1日起施行。","level":1}]},{"id":"n0279","sections":[{"name":"","text":"中华人民共和国预算法\n（1994年3月22日第八届全国人民代表大会第二次会议通过 根据2014年8月31日第十二届全国人民代表大会常务委员会第十次会议《关于修改〈中华人民共和国预算法〉的决定》第一次修正 根据2018年12月29日第十三届全国人民代表大会常务委员会第七次会议《关于修改〈中华人民共和国产品质量法〉等五部法律的决定》第二次修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了规范政府收支行为，强化预算约束，加强对预算的管理和监督，建立健全全面规范、公开透明的预算制度，保障经济社会的健康发展，根据宪法，制定本法。\n第二条 预算、决算的编制、审查、批准、监督，以及预算的执行和调整，依照本法规定执行。\n第三条 国家实行一级政府一级预算，设立中央，省、自治区、直辖市，设区的市、自治州，县、自治县、不设区的市、市辖区，乡、民族乡、镇五级预算。\n全国预算由中央预算和地方预算组成。地方预算由各省、自治区、直辖市总预算组成。\n地方各级总预算由本级预算和汇总的下一级总预算组成；下一级只有本级预算的，下一级总预算即指下一级的本级预算。没有下一级预算的，总预算即指本级预算。\n第四条 预算由预算收入和预算支出组成。\n政府的全部收入和支出都应当纳入预算。\n第五条 预算包括一般公共预算、政府性基金预算、国有资本经营预算、社会保险基金预算。\n一般公共预算、政府性基金预算、国有资本经营预算、社会保险基金预算应当保持完整、独立。政府性基金预算、国有资本经营预算、社会保险基金预算应当与一般公共预算相衔接。\n第六条 一般公共预算是对以税收为主体的财政收入，安排用于保障和改善民生、推动经济社会发展、维护国家安全、维持国家机构正常运转等方面的收支预算。\n中央一般公共预算包括中央各部门（含直属单位，下同）的预算和中央对地方的税收返还、转移支付预算。\n中央一般公共预算收入包括中央本级收入和地方向中央的上解收入。中央一般公共预算支出包括中央本级支出、中央对地方的税收返还和转移支付。\n第七条 地方各级一般公共预算包括本级各部门（含直属单位，下同）的预算和税收返还、转移支付预算。\n地方各级一般公共预算收入包括地方本级收入、上级政府对本级政府的税收返还和转移支付、下级政府的上解收入。地方各级一般公共预算支出包括地方本级支出、对上级政府的上解支出、对下级政府的税收返还和转移支付。\n第八条 各部门预算由本部门及其所属各单位预算组成。\n第九条 政府性基金预算是对依照法律、行政法规的规定在一定期限内向特定对象征收、收取或者以其他方式筹集的资金，专项用于特定公共事业发展的收支预算。\n政府性基金预算应当根据基金项目收入情况和实际支出需要，按基金项目编制，做到以收定支。\n第十条 国有资本经营预算是对国有资本收益作出支出安排的收支预算。\n国有资本经营预算应当按照收支平衡的原则编制，不列赤字，并安排资金调入一般公共预算。\n第十一条 社会保险基金预算是对社会保险缴款、一般公共预算安排和其他方式筹集的资金，专项用于社会保险的收支预算。\n社会保险基金预算应当按照统筹层次和社会保险项目分别编制，做到收支平衡。\n第十二条 各级预算应当遵循统筹兼顾、勤俭节约、量力而行、讲求绩效和收支平衡的原则。\n各级政府应当建立跨年度预算平衡机制。\n第十三条 经人民代表大会批准的预算，非经法定程序，不得调整。各级政府、各部门、各单位的支出必须以经批准的预算为依据，未列入预算的不得支出。\n第十四条 经本级人民代表大会或者本级人民代表大会常务委员会批准的预算、预算调整、决算、预算执行情况的报告及报表，应当在批准后二十日内由本级政府财政部门向社会公开，并对本级政府财政转移支付安排、执行的情况以及举借债务的情况等重要事项作出说明。\n经本级政府财政部门批复的部门预算、决算及报表，应当在批复后二十日内由各部门向社会公开，并对部门预算、决算中机关运行经费的安排、使用情况等重要事项作出说明。\n各级政府、各部门、各单位应当将政府采购的情况及时向社会公开。\n本条前三款规定的公开事项，涉及国家秘密的除外。\n第十五条 国家实行中央和地方分税制。\n第十六条 国家实行财政转移支付制度。财政转移支付应当规范、公平、公开，以推进地区间基本公共服务均等化为主要目标。\n财政转移支付包括中央对地方的转移支付和地方上级政府对下级政府的转移支付，以为均衡地区间基本财力、由下级政府统筹安排使用的一般性转移支付为主体。\n按照法律、行政法规和国务院的规定可以设立专项转移支付，用于办理特定事项。建立健全专项转移支付定期评估和退出机制。市场竞争机制能够有效调节的事项不得设立专项转移支付。\n上级政府在安排专项转移支付时，不得要求下级政府承担配套资金。但是，按照国务院的规定应当由上下级政府共同承担的事项除外。\n第十七条 各级预算的编制、执行应当建立健全相互制约、相互协调的机制。\n第十八条 预算年度自公历一月一日起，至十二月三十一日止。\n第十九条 预算收入和预算支出以人民币元为计算单位。","level":1},{"name":"第二章 预算管理职权","text":"第二十条 全国人民代表大会审查中央和地方预算草案及中央和地方预算执行情况的报告；批准中央预算和中央预算执行情况的报告；改变或者撤销全国人民代表大会常务委员会关于预算、决算的不适当的决议。\n全国人民代表大会常务委员会监督中央和地方预算的执行；审查和批准中央预算的调整方案；审查和批准中央决算；撤销国务院制定的同宪法、法律相抵触的关于预算、决算的行政法规、决定和命令；撤销省、自治区、直辖市人民代表大会及其常务委员会制定的同宪法、法律和行政法规相抵触的关于预算、决算的地方性法规和决议。\n第二十一条 县级以上地方各级人民代表大会审查本级总预算草案及本级总预算执行情况的报告；批准本级预算和本级预算执行情况的报告；改变或者撤销本级人民代表大会常务委员会关于预算、决算的不适当的决议；撤销本级政府关于预算、决算的不适当的决定和命令。\n县级以上地方各级人民代表大会常务委员会监督本级总预算的执行；审查和批准本级预算的调整方案；审查和批准本级决算；撤销本级政府和下一级人民代表大会及其常务委员会关于预算、决算的不适当的决定、命令和决议。\n乡、民族乡、镇的人民代表大会审查和批准本级预算和本级预算执行情况的报告；监督本级预算的执行；审查和批准本级预算的调整方案；审查和批准本级决算；撤销本级政府关于预算、决算的不适当的决定和命令。\n第二十二条 全国人民代表大会财政经济委员会对中央预算草案初步方案及上一年预算执行情况、中央预算调整初步方案和中央决算草案进行初步审查，提出初步审查意见。\n省、自治区、直辖市人民代表大会有关专门委员会对本级预算草案初步方案及上一年预算执行情况、本级预算调整初步方案和本级决算草案进行初步审查，提出初步审查意见。\n设区的市、自治州人民代表大会有关专门委员会对本级预算草案初步方案及上一年预算执行情况、本级预算调整初步方案和本级决算草案进行初步审查，提出初步审查意见，未设立专门委员会的，由本级人民代表大会常务委员会有关工作机构研究提出意见。\n县、自治县、不设区的市、市辖区人民代表大会常务委员会对本级预算草案初步方案及上一年预算执行情况进行初步审查，提出初步审查意见。县、自治县、不设区的市、市辖区人民代表大会常务委员会有关工作机构对本级预算调整初步方案和本级决算草案研究提出意见。\n设区的市、自治州以上各级人民代表大会有关专门委员会进行初步审查、常务委员会有关工作机构研究提出意见时，应当邀请本级人民代表大会代表参加。\n对依照本条第一款至第四款规定提出的意见，本级政府财政部门应当将处理情况及时反馈。\n依照本条第一款至第四款规定提出的意见以及本级政府财政部门反馈的处理情况报告，应当印发本级人民代表大会代表。\n全国人民代表大会常务委员会和省、自治区、直辖市、设区的市、自治州人民代表大会常务委员会有关工作机构，依照本级人民代表大会常务委员会的决定，协助本级人民代表大会财政经济委员会或者有关专门委员会承担审查预算草案、预算调整方案、决算草案和监督预算执行等方面的具体工作。\n第二十三条 国务院编制中央预算、决算草案；向全国人民代表大会作关于中央和地方预算草案的报告；将省、自治区、直辖市政府报送备案的预算汇总后报全国人民代表大会常务委员会备案；组织中央和地方预算的执行；决定中央预算预备费的动用；编制中央预算调整方案；监督中央各部门和地方政府的预算执行；改变或者撤销中央各部门和地方政府关于预算、决算的不适当的决定、命令；向全国人民代表大会、全国人民代表大会常务委员会报告中央和地方预算的执行情况。\n第二十四条 县级以上地方各级政府编制本级预算、决算草案；向本级人民代表大会作关于本级总预算草案的报告；将下一级政府报送备案的预算汇总后报本级人民代表大会常务委员会备案；组织本级总预算的执行；决定本级预算预备费的动用；编制本级预算的调整方案；监督本级各部门和下级政府的预算执行；改变或者撤销本级各部门和下级政府关于预算、决算的不适当的决定、命令；向本级人民代表大会、本级人民代表大会常务委员会报告本级总预算的执行情况。\n乡、民族乡、镇政府编制本级预算、决算草案；向本级人民代表大会作关于本级预算草案的报告；组织本级预算的执行；决定本级预算预备费的动用；编制本级预算的调整方案；向本级人民代表大会报告本级预算的执行情况。\n经省、自治区、直辖市政府批准，乡、民族乡、镇本级预算草案、预算调整方案、决算草案，可以由上一级政府代编，并依照本法第二十一条的规定报乡、民族乡、镇的人民代表大会审查和批准。\n第二十五条 国务院财政部门具体编制中央预算、决算草案；具体组织中央和地方预算的执行；提出中央预算预备费动用方案；具体编制中央预算的调整方案；定期向国务院报告中央和地方预算的执行情况。\n地方各级政府财政部门具体编制本级预算、决算草案；具体组织本级总预算的执行；提出本级预算预备费动用方案；具体编制本级预算的调整方案；定期向本级政府和上一级政府财政部门报告本级总预算的执行情况。\n第二十六条 各部门编制本部门预算、决算草案；组织和监督本部门预算的执行；定期向本级政府财政部门报告预算的执行情况。\n各单位编制本单位预算、决算草案；按照国家规定上缴预算收入，安排预算支出，并接受国家有关部门的监督。","level":1},{"name":"第三章 预算收支范围","text":"第二十七条 一般公共预算收入包括各项税收收入、行政事业性收费收入、国有资源（资产）有偿使用收入、转移性收入和其他收入。\n一般公共预算支出按照其功能分类，包括一般公共服务支出，外交、公共安全、国防支出，农业、环境保护支出，教育、科技、文化、卫生、体育支出，社会保障及就业支出和其他支出。\n一般公共预算支出按照其经济性质分类，包括工资福利支出、商品和服务支出、资本性支出和其他支出。\n第二十八条 政府性基金预算、国有资本经营预算和社会保险基金预算的收支范围，按照法律、行政法规和国务院的规定执行。\n第二十九条 中央预算与地方预算有关收入和支出项目的划分、地方向中央上解收入、中央对地方税收返还或者转移支付的具体办法，由国务院规定，报全国人民代表大会常务委员会备案。\n第三十条 上级政府不得在预算之外调用下级政府预算的资金。下级政府不得挤占或者截留属于上级政府预算的资金。","level":1},{"name":"第四章 预算编制","text":"第三十一条 国务院应当及时下达关于编制下一年预算草案的通知。编制预算草案的具体事项由国务院财政部门部署。\n各级政府、各部门、各单位应当按照国务院规定的时间编制预算草案。\n第三十二条 各级预算应当根据年度经济社会发展目标、国家宏观调控总体要求和跨年度预算平衡的需要，参考上一年预算执行情况、有关支出绩效评价结果和本年度收支预测，按照规定程序征求各方面意见后，进行编制。\n各级政府依据法定权限作出决定或者制定行政措施，凡涉及增加或者减少财政收入或者支出的，应当在预算批准前提出并在预算草案中作出相应安排。\n各部门、各单位应当按照国务院财政部门制定的政府收支分类科目、预算支出标准和要求，以及绩效目标管理等预算编制规定，根据其依法履行职能和事业发展的需要以及存量资产情况，编制本部门、本单位预算草案。\n前款所称政府收支分类科目，收入分为类、款、项、目；支出按其功能分类分为类、款、项，按其经济性质分类分为类、款。\n第三十三条 省、自治区、直辖市政府应当按照国务院规定的时间，将本级总预算草案报国务院审核汇总。\n第三十四条 中央一般公共预算中必需的部分资金，可以通过举借国内和国外债务等方式筹措，举借债务应当控制适当的规模，保持合理的结构。\n对中央一般公共预算中举借的债务实行余额管理，余额的规模不得超过全国人民代表大会批准的限额。\n国务院财政部门具体负责对中央政府债务的统一管理。\n第三十五条 地方各级预算按照量入为出、收支平衡的原则编制，除本法另有规定外，不列赤字。\n经国务院批准的省、自治区、直辖市的预算中必需的建设投资的部分资金，可以在国务院确定的限额内，通过发行地方政府债券举借债务的方式筹措。举借债务的规模，由国务院报全国人民代表大会或者全国人民代表大会常务委员会批准。省、自治区、直辖市依照国务院下达的限额举借的债务，列入本级预算调整方案，报本级人民代表大会常务委员会批准。举借的债务应当有偿还计划和稳定的偿还资金来源，只能用于公益性资本支出，不得用于经常性支出。\n除前款规定外，地方政府及其所属部门不得以任何方式举借债务。\n除法律另有规定外，地方政府及其所属部门不得为任何单位和个人的债务以任何方式提供担保。\n国务院建立地方政府债务风险评估和预警机制、应急处置机制以及责任追究制度。国务院财政部门对地方政府债务实施监督。\n第三十六条 各级预算收入的编制，应当与经济社会发展水平相适应，与财政政策相衔接。\n各级政府、各部门、各单位应当依照本法规定，将所有政府收入全部列入预算，不得隐瞒、少列。\n第三十七条 各级预算支出应当依照本法规定，按其功能和经济性质分类编制。\n各级预算支出的编制，应当贯彻勤俭节约的原则，严格控制各部门、各单位的机关运行经费和楼堂馆所等基本建设支出。\n各级一般公共预算支出的编制，应当统筹兼顾，在保证基本公共服务合理需要的前提下，优先安排国家确定的重点支出。\n第三十八条 一般性转移支付应当按照国务院规定的基本标准和计算方法编制。专项转移支付应当分地区、分项目编制。\n县级以上各级政府应当将对下级政府的转移支付预计数提前下达下级政府。\n地方各级政府应当将上级政府提前下达的转移支付预计数编入本级预算。\n第三十九条 中央预算和有关地方预算中应当安排必要的资金，用于扶助革命老区、民族地区、边疆地区、贫困地区发展经济社会建设事业。\n第四十条 各级一般公共预算应当按照本级一般公共预算支出额的百分之一至百分之三设置预备费，用于当年预算执行中的自然灾害等突发事件处理增加的支出及其他难以预见的开支。\n第四十一条 各级一般公共预算按照国务院的规定可以设置预算周转金，用于本级政府调剂预算年度内季节性收支差额。\n各级一般公共预算按照国务院的规定可以设置预算稳定调节基金，用于弥补以后年度预算资金的不足。\n第四十二条 各级政府上一年预算的结转资金，应当在下一年用于结转项目的支出；连续两年未用完的结转资金，应当作为结余资金管理。\n各部门、各单位上一年预算的结转、结余资金按照国务院财政部门的规定办理。","level":1},{"name":"第五章 预算审查和批准","text":"第四十三条 中央预算由全国人民代表大会审查和批准。\n地方各级预算由本级人民代表大会审查和批准。\n第四十四条 国务院财政部门应当在每年全国人民代表大会会议举行的四十五日前，将中央预算草案的初步方案提交全国人民代表大会财政经济委员会进行初步审查。\n省、自治区、直辖市政府财政部门应当在本级人民代表大会会议举行的三十日前，将本级预算草案的初步方案提交本级人民代表大会有关专门委员会进行初步审查。\n设区的市、自治州政府财政部门应当在本级人民代表大会会议举行的三十日前，将本级预算草案的初步方案提交本级人民代表大会有关专门委员会进行初步审查，或者送交本级人民代表大会常务委员会有关工作机构征求意见。\n县、自治县、不设区的市、市辖区政府应当在本级人民代表大会会议举行的三十日前，将本级预算草案的初步方案提交本级人民代表大会常务委员会进行初步审查。\n第四十五条 县、自治县、不设区的市、市辖区、乡、民族乡、镇的人民代表大会举行会议审查预算草案前，应当采用多种形式，组织本级人民代表大会代表，听取选民和社会各界的意见。\n第四十六条 报送各级人民代表大会审查和批准的预算草案应当细化。本级一般公共预算支出，按其功能分类应当编列到项；按其经济性质分类，基本支出应当编列到款。本级政府性基金预算、国有资本经营预算、社会保险基金预算支出，按其功能分类应当编列到项。\n第四十七条 国务院在全国人民代表大会举行会议时，向大会作关于中央和地方预算草案以及中央和地方预算执行情况的报告。\n地方各级政府在本级人民代表大会举行会议时，向大会作关于总预算草案和总预算执行情况的报告。\n第四十八条 全国人民代表大会和地方各级人民代表大会对预算草案及其报告、预算执行情况的报告重点审查下列内容：\n（一）上一年预算执行情况是否符合本级人民代表大会预算决议的要求；\n（二）预算安排是否符合本法的规定；\n（三）预算安排是否贯彻国民经济和社会发展的方针政策，收支政策是否切实可行；\n（四）重点支出和重大投资项目的预算安排是否适当；\n（五）预算的编制是否完整，是否符合本法第四十六条的规定；\n（六）对下级政府的转移性支出预算是否规范、适当；\n（七）预算安排举借的债务是否合法、合理，是否有偿还计划和稳定的偿还资金来源；\n（八）与预算有关重要事项的说明是否清晰。\n第四十九条 全国人民代表大会财政经济委员会向全国人民代表大会主席团提出关于中央和地方预算草案及中央和地方预算执行情况的审查结果报告。\n省、自治区、直辖市、设区的市、自治州人民代表大会有关专门委员会，县、自治县、不设区的市、市辖区人民代表大会常务委员会，向本级人民代表大会主席团提出关于总预算草案及上一年总预算执行情况的审查结果报告。\n审查结果报告应当包括下列内容：\n（一）对上一年预算执行和落实本级人民代表大会预算决议的情况作出评价；\n（二）对本年度预算草案是否符合本法的规定，是否可行作出评价；\n（三）对本级人民代表大会批准预算草案和预算报告提出建议；\n（四）对执行年度预算、改进预算管理、提高预算绩效、加强预算监督等提出意见和建议。\n第五十条 乡、民族乡、镇政府应当及时将经本级人民代表大会批准的本级预算报上一级政府备案。县级以上地方各级政府应当及时将经本级人民代表大会批准的本级预算及下一级政府报送备案的预算汇总，报上一级政府备案。\n县级以上地方各级政府将下一级政府依照前款规定报送备案的预算汇总后，报本级人民代表大会常务委员会备案。国务院将省、自治区、直辖市政府依照前款规定报送备案的预算汇总后，报全国人民代表大会常务委员会备案。\n第五十一条 国务院和县级以上地方各级政府对下一级政府依照本法第五十条规定报送备案的预算，认为有同法律、行政法规相抵触或者有其他不适当之处，需要撤销批准预算的决议的，应当提请本级人民代表大会常务委员会审议决定。\n第五十二条 各级预算经本级人民代表大会批准后，本级政府财政部门应当在二十日内向本级各部门批复预算。各部门应当在接到本级政府财政部门批复的本部门预算后十五日内向所属各单位批复预算。\n中央对地方的一般性转移支付应当在全国人民代表大会批准预算后三十日内正式下达。中央对地方的专项转移支付应当在全国人民代表大会批准预算后九十日内正式下达。\n省、自治区、直辖市政府接到中央一般性转移支付和专项转移支付后，应当在三十日内正式下达到本行政区域县级以上各级政府。\n县级以上地方各级预算安排对下级政府的一般性转移支付和专项转移支付，应当分别在本级人民代表大会批准预算后的三十日和六十日内正式下达。\n对自然灾害等突发事件处理的转移支付，应当及时下达预算；对据实结算等特殊项目的转移支付，可以分期下达预算，或者先预付后结算。\n县级以上各级政府财政部门应当将批复本级各部门的预算和批复下级政府的转移支付预算，抄送本级人民代表大会财政经济委员会、有关专门委员会和常务委员会有关工作机构。","level":1},{"name":"第六章 预算执行","text":"第五十三条 各级预算由本级政府组织执行，具体工作由本级政府财政部门负责。\n各部门、各单位是本部门、本单位的预算执行主体，负责本部门、本单位的预算执行，并对执行结果负责。\n第五十四条 预算年度开始后，各级预算草案在本级人民代表大会批准前，可以安排下列支出：\n（一）上一年度结转的支出；\n（二）参照上一年同期的预算支出数额安排必须支付的本年度部门基本支出、项目支出，以及对下级政府的转移性支出；\n（三）法律规定必须履行支付义务的支出，以及用于自然灾害等突发事件处理的支出。\n根据前款规定安排支出的情况，应当在预算草案的报告中作出说明。\n预算经本级人民代表大会批准后，按照批准的预算执行。\n第五十五条 预算收入征收部门和单位，必须依照法律、行政法规的规定，及时、足额征收应征的预算收入。不得违反法律、行政法规规定，多征、提前征收或者减征、免征、缓征应征的预算收入，不得截留、占用或者挪用预算收入。\n各级政府不得向预算收入征收部门和单位下达收入指标。\n第五十六条 政府的全部收入应当上缴国家金库（以下简称国库），任何部门、单位和个人不得截留、占用、挪用或者拖欠。\n对于法律有明确规定或者经国务院批准的特定专用资金，可以依照国务院的规定设立财政专户。\n第五十七条 各级政府财政部门必须依照法律、行政法规和国务院财政部门的规定，及时、足额地拨付预算支出资金，加强对预算支出的管理和监督。\n各级政府、各部门、各单位的支出必须按照预算执行，不得虚假列支。\n各级政府、各部门、各单位应当对预算支出情况开展绩效评价。\n第五十八条 各级预算的收入和支出实行收付实现制。\n特定事项按照国务院的规定实行权责发生制的有关情况，应当向本级人民代表大会常务委员会报告。\n第五十九条 县级以上各级预算必须设立国库；具备条件的乡、民族乡、镇也应当设立国库。\n中央国库业务由中国人民银行经理，地方国库业务依照国务院的有关规定办理。\n各级国库应当按照国家有关规定，及时准确地办理预算收入的收纳、划分、留解、退付和预算支出的拨付。\n各级国库库款的支配权属于本级政府财政部门。除法律、行政法规另有规定外，未经本级政府财政部门同意，任何部门、单位和个人都无权冻结、动用国库库款或者以其他方式支配已入国库的库款。\n各级政府应当加强对本级国库的管理和监督，按照国务院的规定完善国库现金管理，合理调节国库资金余额。\n第六十条 已经缴入国库的资金，依照法律、行政法规的规定或者国务院的决定需要退付的，各级政府财政部门或者其授权的机构应当及时办理退付。按照规定应当由财政支出安排的事项，不得用退库处理。\n第六十一条 国家实行国库集中收缴和集中支付制度，对政府全部收入和支出实行国库集中收付管理。\n第六十二条 各级政府应当加强对预算执行的领导，支持政府财政、税务、海关等预算收入的征收部门依法组织预算收入，支持政府财政部门严格管理预算支出。\n财政、税务、海关等部门在预算执行中，应当加强对预算执行的分析；发现问题时应当及时建议本级政府采取措施予以解决。\n第六十三条 各部门、各单位应当加强对预算收入和支出的管理，不得截留或者动用应当上缴的预算收入，不得擅自改变预算支出的用途。\n第六十四条 各级预算预备费的动用方案，由本级政府财政部门提出，报本级政府决定。\n第六十五条 各级预算周转金由本级政府财政部门管理，不得挪作他用。\n第六十六条 各级一般公共预算年度执行中有超收收入的，只能用于冲减赤字或者补充预算稳定调节基金。\n各级一般公共预算的结余资金，应当补充预算稳定调节基金。\n省、自治区、直辖市一般公共预算年度执行中出现短收，通过调入预算稳定调节基金、减少支出等方式仍不能实现收支平衡的，省、自治区、直辖市政府报本级人民代表大会或者其常务委员会批准，可以增列赤字，报国务院财政部门备案，并应当在下一年度预算中予以弥补。","level":1},{"name":"第七章 预算调整","text":"第六十七条 经全国人民代表大会批准的中央预算和经地方各级人民代表大会批准的地方各级预算，在执行中出现下列情况之一的，应当进行预算调整：\n（一）需要增加或者减少预算总支出的；\n（二）需要调入预算稳定调节基金的；\n（三）需要调减预算安排的重点支出数额的；\n（四）需要增加举借债务数额的。\n第六十八条 在预算执行中，各级政府一般不制定新的增加财政收入或者支出的政策和措施，也不制定减少财政收入的政策和措施；必须作出并需要进行预算调整的，应当在预算调整方案中作出安排。\n第六十九条 在预算执行中，各级政府对于必须进行的预算调整，应当编制预算调整方案。预算调整方案应当说明预算调整的理由、项目和数额。\n在预算执行中，由于发生自然灾害等突发事件，必须及时增加预算支出的，应当先动支预备费；预备费不足支出的，各级政府可以先安排支出，属于预算调整的，列入预算调整方案。\n国务院财政部门应当在全国人民代表大会常务委员会举行会议审查和批准预算调整方案的三十日前，将预算调整初步方案送交全国人民代表大会财政经济委员会进行初步审查。\n省、自治区、直辖市政府财政部门应当在本级人民代表大会常务委员会举行会议审查和批准预算调整方案的三十日前，将预算调整初步方案送交本级人民代表大会有关专门委员会进行初步审查。\n设区的市、自治州政府财政部门应当在本级人民代表大会常务委员会举行会议审查和批准预算调整方案的三十日前，将预算调整初步方案送交本级人民代表大会有关专门委员会进行初步审查，或者送交本级人民代表大会常务委员会有关工作机构征求意见。\n县、自治县、不设区的市、市辖区政府财政部门应当在本级人民代表大会常务委员会举行会议审查和批准预算调整方案的三十日前，将预算调整初步方案送交本级人民代表大会常务委员会有关工作机构征求意见。\n中央预算的调整方案应当提请全国人民代表大会常务委员会审查和批准。县级以上地方各级预算的调整方案应当提请本级人民代表大会常务委员会审查和批准；乡、民族乡、镇预算的调整方案应当提请本级人民代表大会审查和批准。未经批准，不得调整预算。\n第七十条 经批准的预算调整方案，各级政府应当严格执行。未经本法第六十九条规定的程序，各级政府不得作出预算调整的决定。\n对违反前款规定作出的决定，本级人民代表大会、本级人民代表大会常务委员会或者上级政府应当责令其改变或者撤销。\n第七十一条 在预算执行中，地方各级政府因上级政府增加不需要本级政府提供配套资金的专项转移支付而引起的预算支出变化，不属于预算调整。\n接受增加专项转移支付的县级以上地方各级政府应当向本级人民代表大会常务委员会报告有关情况；接受增加专项转移支付的乡、民族乡、镇政府应当向本级人民代表大会报告有关情况。\n第七十二条 各部门、各单位的预算支出应当按照预算科目执行。严格控制不同预算科目、预算级次或者项目间的预算资金的调剂，确需调剂使用的，按照国务院财政部门的规定办理。\n第七十三条 地方各级预算的调整方案经批准后，由本级政府报上一级政府备案。","level":1},{"name":"第八章 决 算","text":"第七十四条 决算草案由各级政府、各部门、各单位，在每一预算年度终了后按照国务院规定的时间编制。\n编制决算草案的具体事项，由国务院财政部门部署。\n第七十五条 编制决算草案，必须符合法律、行政法规，做到收支真实、数额准确、内容完整、报送及时。\n决算草案应当与预算相对应，按预算数、调整预算数、决算数分别列出。一般公共预算支出应当按其功能分类编列到项，按其经济性质分类编列到款。\n第七十六条 各部门对所属各单位的决算草案，应当审核并汇总编制本部门的决算草案，在规定的期限内报本级政府财政部门审核。\n各级政府财政部门对本级各部门决算草案审核后发现有不符合法律、行政法规规定的，有权予以纠正。\n第七十七条 国务院财政部门编制中央决算草案，经国务院审计部门审计后，报国务院审定，由国务院提请全国人民代表大会常务委员会审查和批准。\n县级以上地方各级政府财政部门编制本级决算草案，经本级政府审计部门审计后，报本级政府审定，由本级政府提请本级人民代表大会常务委员会审查和批准。\n乡、民族乡、镇政府编制本级决算草案，提请本级人民代表大会审查和批准。\n第七十八条 国务院财政部门应当在全国人民代表大会常务委员会举行会议审查和批准中央决算草案的三十日前，将上一年度中央决算草案提交全国人民代表大会财政经济委员会进行初步审查。\n省、自治区、直辖市政府财政部门应当在本级人民代表大会常务委员会举行会议审查和批准本级决算草案的三十日前，将上一年度本级决算草案提交本级人民代表大会有关专门委员会进行初步审查。\n设区的市、自治州政府财政部门应当在本级人民代表大会常务委员会举行会议审查和批准本级决算草案的三十日前，将上一年度本级决算草案提交本级人民代表大会有关专门委员会进行初步审查，或者送交本级人民代表大会常务委员会有关工作机构征求意见。\n县、自治县、不设区的市、市辖区政府财政部门应当在本级人民代表大会常务委员会举行会议审查和批准本级决算草案的三十日前，将上一年度本级决算草案送交本级人民代表大会常务委员会有关工作机构征求意见。\n全国人民代表大会财政经济委员会和省、自治区、直辖市、设区的市、自治州人民代表大会有关专门委员会，向本级人民代表大会常务委员会提出关于本级决算草案的审查结果报告。\n第七十九条 县级以上各级人民代表大会常务委员会和乡、民族乡、镇人民代表大会对本级决算草案，重点审查下列内容：\n（一）预算收入情况；\n（二）支出政策实施情况和重点支出、重大投资项目资金的使用及绩效情况；\n（三）结转资金的使用情况；\n（四）资金结余情况；\n（五）本级预算调整及执行情况；\n（六）财政转移支付安排执行情况；\n（七）经批准举借债务的规模、结构、使用、偿还等情况；\n（八）本级预算周转金规模和使用情况；\n（九）本级预备费使用情况；\n（十）超收收入安排情况，预算稳定调节基金的规模和使用情况；\n（十一）本级人民代表大会批准的预算决议落实情况；\n（十二）其他与决算有关的重要情况。\n县级以上各级人民代表大会常务委员会应当结合本级政府提出的上一年度预算执行和其他财政收支的审计工作报告，对本级决算草案进行审查。\n第八十条 各级决算经批准后，财政部门应当在二十日内向本级各部门批复决算。各部门应当在接到本级政府财政部门批复的本部门决算后十五日内向所属单位批复决算。\n第八十一条 地方各级政府应当将经批准的决算及下一级政府上报备案的决算汇总，报上一级政府备案。\n县级以上各级政府应当将下一级政府报送备案的决算汇总后，报本级人民代表大会常务委员会备案。\n第八十二条 国务院和县级以上地方各级政府对下一级政府依照本法第八十一条规定报送备案的决算，认为有同法律、行政法规相抵触或者有其他不适当之处，需要撤销批准该项决算的决议的，应当提请本级人民代表大会常务委员会审议决定；经审议决定撤销的，该下级人民代表大会常务委员会应当责成本级政府依照本法规定重新编制决算草案，提请本级人民代表大会常务委员会审查和批准。","level":1},{"name":"第九章 监 督","text":"第八十三条 全国人民代表大会及其常务委员会对中央和地方预算、决算进行监督。\n县级以上地方各级人民代表大会及其常务委员会对本级和下级预算、决算进行监督。\n乡、民族乡、镇人民代表大会对本级预算、决算进行监督。\n第八十四条 各级人民代表大会和县级以上各级人民代表大会常务委员会有权就预算、决算中的重大事项或者特定问题组织调查，有关的政府、部门、单位和个人应当如实反映情况和提供必要的材料。\n第八十五条 各级人民代表大会和县级以上各级人民代表大会常务委员会举行会议时，人民代表大会代表或者常务委员会组成人员，依照法律规定程序就预算、决算中的有关问题提出询问或者质询，受询问或者受质询的有关的政府或者财政部门必须及时给予答复。\n第八十六条 国务院和县级以上地方各级政府应当在每年六月至九月期间向本级人民代表大会常务委员会报告预算执行情况。\n第八十七条 各级政府监督下级政府的预算执行；下级政府应当定期向上一级政府报告预算执行情况。\n第八十八条 各级政府财政部门负责监督本级各部门及其所属各单位预算管理有关工作，并向本级政府和上一级政府财政部门报告预算执行情况。\n第八十九条 县级以上政府审计部门依法对预算执行、决算实行审计监督。\n对预算执行和其他财政收支的审计工作报告应当向社会公开。\n第九十条 政府各部门负责监督检查所属各单位的预算执行，及时向本级政府财政部门反映本部门预算执行情况，依法纠正违反预算的行为。\n第九十一条 公民、法人或者其他组织发现有违反本法的行为，可以依法向有关国家机关进行检举、控告。\n接受检举、控告的国家机关应当依法进行处理，并为检举人、控告人保密。任何单位或者个人不得压制和打击报复检举人、控告人。","level":1},{"name":"第十章 法律责任","text":"第九十二条 各级政府及有关部门有下列行为之一的，责令改正，对负有直接责任的主管人员和其他直接责任人员追究行政责任：\n（一）未依照本法规定，编制、报送预算草案、预算调整方案、决算草案和部门预算、决算以及批复预算、决算的；\n（二）违反本法规定，进行预算调整的；\n（三）未依照本法规定对有关预算事项进行公开和说明的；\n（四）违反规定设立政府性基金项目和其他财政收入项目的；\n（五）违反法律、法规规定使用预算预备费、预算周转金、预算稳定调节基金、超收收入的；\n（六）违反本法规定开设财政专户的。\n第九十三条 各级政府及有关部门、单位有下列行为之一的，责令改正，对负有直接责任的主管人员和其他直接责任人员依法给予降级、撤职、开除的处分：\n（一）未将所有政府收入和支出列入预算或者虚列收入和支出的；\n（二）违反法律、行政法规的规定，多征、提前征收或者减征、免征、缓征应征预算收入的；\n（三）截留、占用、挪用或者拖欠应当上缴国库的预算收入的；\n（四）违反本法规定，改变预算支出用途的；\n（五）擅自改变上级政府专项转移支付资金用途的；\n（六）违反本法规定拨付预算支出资金，办理预算收入收纳、划分、留解、退付，或者违反本法规定冻结、动用国库库款或者以其他方式支配已入国库库款的。\n第九十四条 各级政府、各部门、各单位违反本法规定举借债务或者为他人债务提供担保，或者挪用重点支出资金，或者在预算之外及超预算标准建设楼堂馆所的，责令改正，对负有直接责任的主管人员和其他直接责任人员给予撤职、开除的处分。\n第九十五条 各级政府有关部门、单位及其工作人员有下列行为之一的，责令改正，追回骗取、使用的资金，有违法所得的没收违法所得，对单位给予警告或者通报批评；对负有直接责任的主管人员和其他直接责任人员依法给予处分：\n（一）违反法律、法规的规定，改变预算收入上缴方式的；\n（二）以虚报、冒领等手段骗取预算资金的；\n（三）违反规定扩大开支范围、提高开支标准的；\n（四）其他违反财政管理规定的行为。\n第九十六条 本法第九十二条、第九十三条、第九十四条、第九十五条所列违法行为，其他法律对其处理、处罚另有规定的，依照其规定。\n违反本法规定，构成犯罪的，依法追究刑事责任。","level":1},{"name":"第十一章 附 则","text":"第九十七条 各级政府财政部门应当按年度编制以权责发生制为基础的政府综合财务报告，报告政府整体财务状况、运行情况和财政中长期可持续性，报本级人民代表大会常务委员会备案。\n第九十八条 国务院根据本法制定实施条例。\n第九十九条 民族自治地方的预算管理，依照民族区域自治法的有关规定执行；民族区域自治法没有规定的，依照本法和国务院的有关规定执行。\n第一百条 省、自治区、直辖市人民代表大会或者其常务委员会根据本法，可以制定有关预算审查监督的决定或者地方性法规。\n第一百零一条 本法自1995年1月1日起施行。1991年10月21日国务院发布的《国家预算管理条例》同时废止。","level":1}]},{"id":"n0280","sections":[{"name":"","text":"中华人民共和国职业病防治法\n（2001年10月27日第九届全国人民代表大会常务委员会第二十四次会议通过 根据2011年12月31日第十一届全国人民代表大会常务委员会第二十四次会议《关于修改〈中华人民共和国职业病防治法〉的决定》第一次修正 根据2016年7月2日第十二届全国人民代表大会常务委员会第二十一次会议《关于修改〈中华人民共和国节约能源法〉等六部法律的决定》第二次修正 根据2017年11月4日第十二届全国人民代表大会常务委员会第三十次会议《关于修改〈中华人民共和国会计法〉等十一部法律的决定》第三次修正 根据2018年12月29日第十三届全国人民代表大会常务委员会第七次会议《关于修改〈中华人民共和国劳动法〉等七部法律的决定》第四次修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了预防、控制和消除职业病危害，防治职业病，保护劳动者健康及其相关权益，促进经济社会发展，根据宪法，制定本法。\n第二条 本法适用于中华人民共和国领域内的职业病防治活动。\n本法所称职业病，是指企业、事业单位和个体经济组织等用人单位的劳动者在职业活动中，因接触粉尘、放射性物质和其他有毒、有害因素而引起的疾病。\n职业病的分类和目录由国务院卫生行政部门会同国务院劳动保障行政部门制定、调整并公布。\n第三条 职业病防治工作坚持预防为主、防治结合的方针，建立用人单位负责、行政机关监管、行业自律、职工参与和社会监督的机制，实行分类管理、综合治理。\n第四条 劳动者依法享有职业卫生保护的权利。\n用人单位应当为劳动者创造符合国家职业卫生标准和卫生要求的工作环境和条件，并采取措施保障劳动者获得职业卫生保护。\n工会组织依法对职业病防治工作进行监督，维护劳动者的合法权益。用人单位制定或者修改有关职业病防治的规章制度，应当听取工会组织的意见。\n第五条 用人单位应当建立、健全职业病防治责任制，加强对职业病防治的管理，提高职业病防治水平，对本单位产生的职业病危害承担责任。\n第六条 用人单位的主要负责人对本单位的职业病防治工作全面负责。\n第七条 用人单位必须依法参加工伤保险。\n国务院和县级以上地方人民政府劳动保障行政部门应当加强对工伤保险的监督管理，确保劳动者依法享受工伤保险待遇。\n第八条 国家鼓励和支持研制、开发、推广、应用有利于职业病防治和保护劳动者健康的新技术、新工艺、新设备、新材料，加强对职业病的机理和发生规律的基础研究，提高职业病防治科学技术水平；积极采用有效的职业病防治技术、工艺、设备、材料；限制使用或者淘汰职业病危害严重的技术、工艺、设备、材料。\n国家鼓励和支持职业病医疗康复机构的建设。\n第九条 国家实行职业卫生监督制度。\n国务院卫生行政部门、劳动保障行政部门依照本法和国务院确定的职责，负责全国职业病防治的监督管理工作。国务院有关部门在各自的职责范围内负责职业病防治的有关监督管理工作。\n县级以上地方人民政府卫生行政部门、劳动保障行政部门依据各自职责，负责本行政区域内职业病防治的监督管理工作。县级以上地方人民政府有关部门在各自的职责范围内负责职业病防治的有关监督管理工作。\n县级以上人民政府卫生行政部门、劳动保障行政部门（以下统称职业卫生监督管理部门）应当加强沟通，密切配合，按照各自职责分工，依法行使职权，承担责任。\n第十条 国务院和县级以上地方人民政府应当制定职业病防治规划，将其纳入国民经济和社会发展计划，并组织实施。\n县级以上地方人民政府统一负责、领导、组织、协调本行政区域的职业病防治工作，建立健全职业病防治工作体制、机制，统一领导、指挥职业卫生突发事件应对工作；加强职业病防治能力建设和服务体系建设，完善、落实职业病防治工作责任制。\n乡、民族乡、镇的人民政府应当认真执行本法，支持职业卫生监督管理部门依法履行职责。\n第十一条 县级以上人民政府职业卫生监督管理部门应当加强对职业病防治的宣传教育，普及职业病防治的知识，增强用人单位的职业病防治观念，提高劳动者的职业健康意识、自我保护意识和行使职业卫生保护权利的能力。\n第十二条 有关防治职业病的国家职业卫生标准，由国务院卫生行政部门组织制定并公布。\n国务院卫生行政部门应当组织开展重点职业病监测和专项调查，对职业健康风险进行评估，为制定职业卫生标准和职业病防治政策提供科学依据。\n县级以上地方人民政府卫生行政部门应当定期对本行政区域的职业病防治情况进行统计和调查分析。\n第十三条 任何单位和个人有权对违反本法的行为进行检举和控告。有关部门收到相关的检举和控告后，应当及时处理。\n对防治职业病成绩显著的单位和个人，给予奖励。","level":1},{"name":"第二章 前期预防","text":"第十四条 用人单位应当依照法律、法规要求，严格遵守国家职业卫生标准，落实职业病预防措施，从源头上控制和消除职业病危害。\n第十五条 产生职业病危害的用人单位的设立除应当符合法律、行政法规规定的设立条件外，其工作场所还应当符合下列职业卫生要求：\n（一）职业病危害因素的强度或者浓度符合国家职业卫生标准；\n（二）有与职业病危害防护相适应的设施；\n（三）生产布局合理，符合有害与无害作业分开的原则；\n（四）有配套的更衣间、洗浴间、孕妇休息间等卫生设施；\n（五）设备、工具、用具等设施符合保护劳动者生理、心理健康的要求；\n（六）法律、行政法规和国务院卫生行政部门关于保护劳动者健康的其他要求。\n第十六条 国家建立职业病危害项目申报制度。\n用人单位工作场所存在职业病目录所列职业病的危害因素的，应当及时、如实向所在地卫生行政部门申报危害项目，接受监督。\n职业病危害因素分类目录由国务院卫生行政部门制定、调整并公布。职业病危害项目申报的具体办法由国务院卫生行政部门制定。\n第十七条 新建、扩建、改建建设项目和技术改造、技术引进项目（以下统称建设项目）可能产生职业病危害的，建设单位在可行性论证阶段应当进行职业病危害预评价。\n医疗机构建设项目可能产生放射性职业病危害的，建设单位应当向卫生行政部门提交放射性职业病危害预评价报告。卫生行政部门应当自收到预评价报告之日起三十日内，作出审核决定并书面通知建设单位。未提交预评价报告或者预评价报告未经卫生行政部门审核同意的，不得开工建设。\n职业病危害预评价报告应当对建设项目可能产生的职业病危害因素及其对工作场所和劳动者健康的影响作出评价，确定危害类别和职业病防护措施。\n建设项目职业病危害分类管理办法由国务院卫生行政部门制定。\n第十八条 建设项目的职业病防护设施所需费用应当纳入建设项目工程预算，并与主体工程同时设计，同时施工，同时投入生产和使用。\n建设项目的职业病防护设施设计应当符合国家职业卫生标准和卫生要求；其中，医疗机构放射性职业病危害严重的建设项目的防护设施设计，应当经卫生行政部门审查同意后，方可施工。\n建设项目在竣工验收前，建设单位应当进行职业病危害控制效果评价。\n医疗机构可能产生放射性职业病危害的建设项目竣工验收时，其放射性职业病防护设施经卫生行政部门验收合格后，方可投入使用；其他建设项目的职业病防护设施应当由建设单位负责依法组织验收，验收合格后，方可投入生产和使用。卫生行政部门应当加强对建设单位组织的验收活动和验收结果的监督核查。\n第十九条 国家对从事放射性、高毒、高危粉尘等作业实行特殊管理。具体管理办法由国务院制定。","level":1},{"name":"第三章 劳动过程中的防护与管理","text":"第二十条 用人单位应当采取下列职业病防治管理措施：\n（一）设置或者指定职业卫生管理机构或者组织，配备专职或者兼职的职业卫生管理人员，负责本单位的职业病防治工作；\n（二）制定职业病防治计划和实施方案；\n（三）建立、健全职业卫生管理制度和操作规程；\n（四）建立、健全职业卫生档案和劳动者健康监护档案；\n（五）建立、健全工作场所职业病危害因素监测及评价制度；\n（六）建立、健全职业病危害事故应急救援预案。\n第二十一条 用人单位应当保障职业病防治所需的资金投入，不得挤占、挪用，并对因资金投入不足导致的后果承担责任。\n第二十二条 用人单位必须采用有效的职业病防护设施，并为劳动者提供个人使用的职业病防护用品。\n用人单位为劳动者个人提供的职业病防护用品必须符合防治职业病的要求；不符合要求的，不得使用。\n第二十三条 用人单位应当优先采用有利于防治职业病和保护劳动者健康的新技术、新工艺、新设备、新材料，逐步替代职业病危害严重的技术、工艺、设备、材料。\n第二十四条 产生职业病危害的用人单位，应当在醒目位置设置公告栏，公布有关职业病防治的规章制度、操作规程、职业病危害事故应急救援措施和工作场所职业病危害因素检测结果。\n对产生严重职业病危害的作业岗位，应当在其醒目位置，设置警示标识和中文警示说明。警示说明应当载明产生职业病危害的种类、后果、预防以及应急救治措施等内容。\n第二十五条 对可能发生急性职业损伤的有毒、有害工作场所，用人单位应当设置报警装置，配置现场急救用品、冲洗设备、应急撤离通道和必要的泄险区。\n对放射工作场所和放射性同位素的运输、贮存，用人单位必须配置防护设备和报警装置，保证接触放射线的工作人员佩戴个人剂量计。\n对职业病防护设备、应急救援设施和个人使用的职业病防护用品，用人单位应当进行经常性的维护、检修，定期检测其性能和效果，确保其处于正常状态，不得擅自拆除或者停止使用。\n第二十六条 用人单位应当实施由专人负责的职业病危害因素日常监测，并确保监测系统处于正常运行状态。\n用人单位应当按照国务院卫生行政部门的规定，定期对工作场所进行职业病危害因素检测、评价。检测、评价结果存入用人单位职业卫生档案，定期向所在地卫生行政部门报告并向劳动者公布。\n职业病危害因素检测、评价由依法设立的取得国务院卫生行政部门或者设区的市级以上地方人民政府卫生行政部门按照职责分工给予资质认可的职业卫生技术服务机构进行。职业卫生技术服务机构所作检测、评价应当客观、真实。\n发现工作场所职业病危害因素不符合国家职业卫生标准和卫生要求时，用人单位应当立即采取相应治理措施，仍然达不到国家职业卫生标准和卫生要求的，必须停止存在职业病危害因素的作业；职业病危害因素经治理后，符合国家职业卫生标准和卫生要求的，方可重新作业。\n第二十七条 职业卫生技术服务机构依法从事职业病危害因素检测、评价工作，接受卫生行政部门的监督检查。卫生行政部门应当依法履行监督职责。\n第二十八条 向用人单位提供可能产生职业病危害的设备的，应当提供中文说明书，并在设备的醒目位置设置警示标识和中文警示说明。警示说明应当载明设备性能、可能产生的职业病危害、安全操作和维护注意事项、职业病防护以及应急救治措施等内容。\n第二十九条 向用人单位提供可能产生职业病危害的化学品、放射性同位素和含有放射性物质的材料的，应当提供中文说明书。说明书应当载明产品特性、主要成份、存在的有害因素、可能产生的危害后果、安全使用注意事项、职业病防护以及应急救治措施等内容。产品包装应当有醒目的警示标识和中文警示说明。贮存上述材料的场所应当在规定的部位设置危险物品标识或者放射性警示标识。\n国内首次使用或者首次进口与职业病危害有关的化学材料，使用单位或者进口单位按照国家规定经国务院有关部门批准后，应当向国务院卫生行政部门报送该化学材料的毒性鉴定以及经有关部门登记注册或者批准进口的文件等资料。\n进口放射性同位素、射线装置和含有放射性物质的物品的，按照国家有关规定办理。\n第三十条 任何单位和个人不得生产、经营、进口和使用国家明令禁止使用的可能产生职业病危害的设备或者材料。\n第三十一条 任何单位和个人不得将产生职业病危害的作业转移给不具备职业病防护条件的单位和个人。不具备职业病防护条件的单位和个人不得接受产生职业病危害的作业。\n第三十二条 用人单位对采用的技术、工艺、设备、材料，应当知悉其产生的职业病危害，对有职业病危害的技术、工艺、设备、材料隐瞒其危害而采用的，对所造成的职业病危害后果承担责任。\n第三十三条 用人单位与劳动者订立劳动合同（含聘用合同，下同）时，应当将工作过程中可能产生的职业病危害及其后果、职业病防护措施和待遇等如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗。\n劳动者在已订立劳动合同期间因工作岗位或者工作内容变更，从事与所订立劳动合同中未告知的存在职业病危害的作业时，用人单位应当依照前款规定，向劳动者履行如实告知的义务，并协商变更原劳动合同相关条款。\n用人单位违反前两款规定的，劳动者有权拒绝从事存在职业病危害的作业，用人单位不得因此解除与劳动者所订立的劳动合同。\n第三十四条 用人单位的主要负责人和职业卫生管理人员应当接受职业卫生培训，遵守职业病防治法律、法规，依法组织本单位的职业病防治工作。\n用人单位应当对劳动者进行上岗前的职业卫生培训和在岗期间的定期职业卫生培训，普及职业卫生知识，督促劳动者遵守职业病防治法律、法规、规章和操作规程，指导劳动者正确使用职业病防护设备和个人使用的职业病防护用品。\n劳动者应当学习和掌握相关的职业卫生知识，增强职业病防范意识，遵守职业病防治法律、法规、规章和操作规程，正确使用、维护职业病防护设备和个人使用的职业病防护用品，发现职业病危害事故隐患应当及时报告。\n劳动者不履行前款规定义务的，用人单位应当对其进行教育。\n第三十五条 对从事接触职业病危害的作业的劳动者，用人单位应当按照国务院卫生行政部门的规定组织上岗前、在岗期间和离岗时的职业健康检查，并将检查结果书面告知劳动者。职业健康检查费用由用人单位承担。\n用人单位不得安排未经上岗前职业健康检查的劳动者从事接触职业病危害的作业；不得安排有职业禁忌的劳动者从事其所禁忌的作业；对在职业健康检查中发现有与所从事的职业相关的健康损害的劳动者，应当调离原工作岗位，并妥善安置；对未进行离岗前职业健康检查的劳动者不得解除或者终止与其订立的劳动合同。\n职业健康检查应当由取得《医疗机构执业许可证》的医疗卫生机构承担。卫生行政部门应当加强对职业健康检查工作的规范管理，具体管理办法由国务院卫生行政部门制定。\n第三十六条 用人单位应当为劳动者建立职业健康监护档案，并按照规定的期限妥善保存。\n职业健康监护档案应当包括劳动者的职业史、职业病危害接触史、职业健康检查结果和职业病诊疗等有关个人健康资料。\n劳动者离开用人单位时，有权索取本人职业健康监护档案复印件，用人单位应当如实、无偿提供，并在所提供的复印件上签章。\n第三十七条 发生或者可能发生急性职业病危害事故时，用人单位应当立即采取应急救援和控制措施，并及时报告所在地卫生行政部门和有关部门。卫生行政部门接到报告后，应当及时会同有关部门组织调查处理；必要时，可以采取临时控制措施。卫生行政部门应当组织做好医疗救治工作。\n对遭受或者可能遭受急性职业病危害的劳动者，用人单位应当及时组织救治、进行健康检查和医学观察，所需费用由用人单位承担。\n第三十八条 用人单位不得安排未成年工从事接触职业病危害的作业；不得安排孕期、哺乳期的女职工从事对本人和胎儿、婴儿有危害的作业。\n第三十九条 劳动者享有下列职业卫生保护权利：\n（一）获得职业卫生教育、培训；\n（二）获得职业健康检查、职业病诊疗、康复等职业病防治服务；\n（三）了解工作场所产生或者可能产生的职业病危害因素、危害后果和应当采取的职业病防护措施；\n（四）要求用人单位提供符合防治职业病要求的职业病防护设施和个人使用的职业病防护用品，改善工作条件；\n（五）对违反职业病防治法律、法规以及危及生命健康的行为提出批评、检举和控告；\n（六）拒绝违章指挥和强令进行没有职业病防护措施的作业；\n（七）参与用人单位职业卫生工作的民主管理，对职业病防治工作提出意见和建议。\n用人单位应当保障劳动者行使前款所列权利。因劳动者依法行使正当权利而降低其工资、福利等待遇或者解除、终止与其订立的劳动合同的，其行为无效。\n第四十条 工会组织应当督促并协助用人单位开展职业卫生宣传教育和培训，有权对用人单位的职业病防治工作提出意见和建议，依法代表劳动者与用人单位签订劳动安全卫生专项集体合同，与用人单位就劳动者反映的有关职业病防治的问题进行协调并督促解决。\n工会组织对用人单位违反职业病防治法律、法规，侵犯劳动者合法权益的行为，有权要求纠正；产生严重职业病危害时，有权要求采取防护措施，或者向政府有关部门建议采取强制性措施；发生职业病危害事故时，有权参与事故调查处理；发现危及劳动者生命健康的情形时，有权向用人单位建议组织劳动者撤离危险现场，用人单位应当立即作出处理。\n第四十一条 用人单位按照职业病防治要求，用于预防和治理职业病危害、工作场所卫生检测、健康监护和职业卫生培训等费用，按照国家有关规定，在生产成本中据实列支。\n第四十二条 职业卫生监督管理部门应当按照职责分工，加强对用人单位落实职业病防护管理措施情况的监督检查，依法行使职权，承担责任。","level":1},{"name":"第四章 职业病诊断与职业病病人保障","text":"第四十三条 职业病诊断应当由取得《医疗机构执业许可证》的医疗卫生机构承担。卫生行政部门应当加强对职业病诊断工作的规范管理，具体管理办法由国务院卫生行政部门制定。\n承担职业病诊断的医疗卫生机构还应当具备下列条件：\n（一）具有与开展职业病诊断相适应的医疗卫生技术人员；\n（二）具有与开展职业病诊断相适应的仪器、设备；\n（三）具有健全的职业病诊断质量管理制度。\n承担职业病诊断的医疗卫生机构不得拒绝劳动者进行职业病诊断的要求。\n第四十四条 劳动者可以在用人单位所在地、本人户籍所在地或者经常居住地依法承担职业病诊断的医疗卫生机构进行职业病诊断。\n第四十五条 职业病诊断标准和职业病诊断、鉴定办法由国务院卫生行政部门制定。职业病伤残等级的鉴定办法由国务院劳动保障行政部门会同国务院卫生行政部门制定。\n第四十六条 职业病诊断，应当综合分析下列因素：\n（一）病人的职业史；\n（二）职业病危害接触史和工作场所职业病危害因素情况；\n（三）临床表现以及辅助检查结果等。\n没有证据否定职业病危害因素与病人临床表现之间的必然联系的，应当诊断为职业病。\n职业病诊断证明书应当由参与诊断的取得职业病诊断资格的执业医师签署，并经承担职业病诊断的医疗卫生机构审核盖章。\n第四十七条 用人单位应当如实提供职业病诊断、鉴定所需的劳动者职业史和职业病危害接触史、工作场所职业病危害因素检测结果等资料；卫生行政部门应当监督检查和督促用人单位提供上述资料；劳动者和有关机构也应当提供与职业病诊断、鉴定有关的资料。\n职业病诊断、鉴定机构需要了解工作场所职业病危害因素情况时，可以对工作场所进行现场调查，也可以向卫生行政部门提出，卫生行政部门应当在十日内组织现场调查。用人单位不得拒绝、阻挠。\n第四十八条 职业病诊断、鉴定过程中，用人单位不提供工作场所职业病危害因素检测结果等资料的，诊断、鉴定机构应当结合劳动者的临床表现、辅助检查结果和劳动者的职业史、职业病危害接触史，并参考劳动者的自述、卫生行政部门提供的日常监督检查信息等，作出职业病诊断、鉴定结论。\n劳动者对用人单位提供的工作场所职业病危害因素检测结果等资料有异议，或者因劳动者的用人单位解散、破产，无用人单位提供上述资料的，诊断、鉴定机构应当提请卫生行政部门进行调查，卫生行政部门应当自接到申请之日起三十日内对存在异议的资料或者工作场所职业病危害因素情况作出判定；有关部门应当配合。\n第四十九条 职业病诊断、鉴定过程中，在确认劳动者职业史、职业病危害接触史时，当事人对劳动关系、工种、工作岗位或者在岗时间有争议的，可以向当地的劳动人事争议仲裁委员会申请仲裁；接到申请的劳动人事争议仲裁委员会应当受理，并在三十日内作出裁决。\n当事人在仲裁过程中对自己提出的主张，有责任提供证据。劳动者无法提供由用人单位掌握管理的与仲裁主张有关的证据的，仲裁庭应当要求用人单位在指定期限内提供；用人单位在指定期限内不提供的，应当承担不利后果。\n劳动者对仲裁裁决不服的，可以依法向人民法院提起诉讼。\n用人单位对仲裁裁决不服的，可以在职业病诊断、鉴定程序结束之日起十五日内依法向人民法院提起诉讼；诉讼期间，劳动者的治疗费用按照职业病待遇规定的途径支付。\n第五十条 用人单位和医疗卫生机构发现职业病病人或者疑似职业病病人时，应当及时向所在地卫生行政部门报告。确诊为职业病的，用人单位还应当向所在地劳动保障行政部门报告。接到报告的部门应当依法作出处理。\n第五十一条 县级以上地方人民政府卫生行政部门负责本行政区域内的职业病统计报告的管理工作，并按照规定上报。\n第五十二条 当事人对职业病诊断有异议的，可以向作出诊断的医疗卫生机构所在地地方人民政府卫生行政部门申请鉴定。\n职业病诊断争议由设区的市级以上地方人民政府卫生行政部门根据当事人的申请，组织职业病诊断鉴定委员会进行鉴定。\n当事人对设区的市级职业病诊断鉴定委员会的鉴定结论不服的，可以向省、自治区、直辖市人民政府卫生行政部门申请再鉴定。\n第五十三条 职业病诊断鉴定委员会由相关专业的专家组成。\n省、自治区、直辖市人民政府卫生行政部门应当设立相关的专家库，需要对职业病争议作出诊断鉴定时，由当事人或者当事人委托有关卫生行政部门从专家库中以随机抽取的方式确定参加诊断鉴定委员会的专家。\n职业病诊断鉴定委员会应当按照国务院卫生行政部门颁布的职业病诊断标准和职业病诊断、鉴定办法进行职业病诊断鉴定，向当事人出具职业病诊断鉴定书。职业病诊断、鉴定费用由用人单位承担。\n第五十四条 职业病诊断鉴定委员会组成人员应当遵守职业道德，客观、公正地进行诊断鉴定，并承担相应的责任。职业病诊断鉴定委员会组成人员不得私下接触当事人，不得收受当事人的财物或者其他好处，与当事人有利害关系的，应当回避。\n人民法院受理有关案件需要进行职业病鉴定时，应当从省、自治区、直辖市人民政府卫生行政部门依法设立的相关的专家库中选取参加鉴定的专家。\n第五十五条 医疗卫生机构发现疑似职业病病人时，应当告知劳动者本人并及时通知用人单位。\n用人单位应当及时安排对疑似职业病病人进行诊断；在疑似职业病病人诊断或者医学观察期间，不得解除或者终止与其订立的劳动合同。\n疑似职业病病人在诊断、医学观察期间的费用，由用人单位承担。\n第五十六条 用人单位应当保障职业病病人依法享受国家规定的职业病待遇。\n用人单位应当按照国家有关规定，安排职业病病人进行治疗、康复和定期检查。\n用人单位对不适宜继续从事原工作的职业病病人，应当调离原岗位，并妥善安置。\n用人单位对从事接触职业病危害的作业的劳动者，应当给予适当岗位津贴。\n第五十七条 职业病病人的诊疗、康复费用，伤残以及丧失劳动能力的职业病病人的社会保障，按照国家有关工伤保险的规定执行。\n第五十八条 职业病病人除依法享有工伤保险外，依照有关民事法律，尚有获得赔偿的权利的，有权向用人单位提出赔偿要求。\n第五十九条 劳动者被诊断患有职业病，但用人单位没有依法参加工伤保险的，其医疗和生活保障由该用人单位承担。\n第六十条 职业病病人变动工作单位，其依法享有的待遇不变。\n用人单位在发生分立、合并、解散、破产等情形时，应当对从事接触职业病危害的作业的劳动者进行健康检查，并按照国家有关规定妥善安置职业病病人。\n第六十一条 用人单位已经不存在或者无法确认劳动关系的职业病病人，可以向地方人民政府医疗保障、民政部门申请医疗救助和生活等方面的救助。\n地方各级人民政府应当根据本地区的实际情况，采取其他措施，使前款规定的职业病病人获得医疗救治。","level":1},{"name":"第五章 监督检查","text":"第六十二条 县级以上人民政府职业卫生监督管理部门依照职业病防治法律、法规、国家职业卫生标准和卫生要求，依据职责划分，对职业病防治工作进行监督检查。\n第六十三条 卫生行政部门履行监督检查职责时，有权采取下列措施：\n（一）进入被检查单位和职业病危害现场，了解情况，调查取证；\n（二）查阅或者复制与违反职业病防治法律、法规的行为有关的资料和采集样品；\n（三）责令违反职业病防治法律、法规的单位和个人停止违法行为。\n第六十四条 发生职业病危害事故或者有证据证明危害状态可能导致职业病危害事故发生时，卫生行政部门可以采取下列临时控制措施：\n（一）责令暂停导致职业病危害事故的作业；\n（二）封存造成职业病危害事故或者可能导致职业病危害事故发生的材料和设备；\n（三）组织控制职业病危害事故现场。\n在职业病危害事故或者危害状态得到有效控制后，卫生行政部门应当及时解除控制措施。\n第六十五条 职业卫生监督执法人员依法执行职务时，应当出示监督执法证件。\n职业卫生监督执法人员应当忠于职守，秉公执法，严格遵守执法规范；涉及用人单位的秘密的，应当为其保密。\n第六十六条 职业卫生监督执法人员依法执行职务时，被检查单位应当接受检查并予以支持配合，不得拒绝和阻碍。\n第六十七条 卫生行政部门及其职业卫生监督执法人员履行职责时，不得有下列行为：\n（一）对不符合法定条件的，发给建设项目有关证明文件、资质证明文件或者予以批准；\n（二）对已经取得有关证明文件的，不履行监督检查职责；\n（三）发现用人单位存在职业病危害的，可能造成职业病危害事故，不及时依法采取控制措施；\n（四）其他违反本法的行为。\n第六十八条 职业卫生监督执法人员应当依法经过资格认定。\n职业卫生监督管理部门应当加强队伍建设，提高职业卫生监督执法人员的政治、业务素质，依照本法和其他有关法律、法规的规定，建立、健全内部监督制度，对其工作人员执行法律、法规和遵守纪律的情况，进行监督检查。","level":1},{"name":"第六章 法律责任","text":"第六十九条 建设单位违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正；逾期不改正的，处十万元以上五十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令停建、关闭：\n（一）未按照规定进行职业病危害预评价的；\n（二）医疗机构可能产生放射性职业病危害的建设项目未按照规定提交放射性职业病危害预评价报告，或者放射性职业病危害预评价报告未经卫生行政部门审核同意，开工建设的；\n（三）建设项目的职业病防护设施未按照规定与主体工程同时设计、同时施工、同时投入生产和使用的；\n（四）建设项目的职业病防护设施设计不符合国家职业卫生标准和卫生要求，或者医疗机构放射性职业病危害严重的建设项目的防护设施设计未经卫生行政部门审查同意擅自施工的；\n（五）未按照规定对职业病防护设施进行职业病危害控制效果评价的；\n（六）建设项目竣工投入生产和使用前，职业病防护设施未按照规定验收合格的。\n第七十条 违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正；逾期不改正的，处十万元以下的罚款：\n（一）工作场所职业病危害因素检测、评价结果没有存档、上报、公布的；\n（二）未采取本法第二十条规定的职业病防治管理措施的；\n（三）未按照规定公布有关职业病防治的规章制度、操作规程、职业病危害事故应急救援措施的；\n（四）未按照规定组织劳动者进行职业卫生培训，或者未对劳动者个人职业病防护采取指导、督促措施的；\n（五）国内首次使用或者首次进口与职业病危害有关的化学材料，未按照规定报送毒性鉴定资料以及经有关部门登记注册或者批准进口的文件的。\n第七十一条 用人单位违反本法规定，有下列行为之一的，由卫生行政部门责令限期改正，给予警告，可以并处五万元以上十万元以下的罚款：\n（一）未按照规定及时、如实向卫生行政部门申报产生职业病危害的项目的；\n（二）未实施由专人负责的职业病危害因素日常监测，或者监测系统不能正常监测的；\n（三）订立或者变更劳动合同时，未告知劳动者职业病危害真实情况的；\n（四）未按照规定组织职业健康检查、建立职业健康监护档案或者未将检查结果书面告知劳动者的；\n（五）未依照本法规定在劳动者离开用人单位时提供职业健康监护档案复印件的。\n第七十二条 用人单位违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正，逾期不改正的，处五万元以上二十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭：\n（一）工作场所职业病危害因素的强度或者浓度超过国家职业卫生标准的；\n（二）未提供职业病防护设施和个人使用的职业病防护用品，或者提供的职业病防护设施和个人使用的职业病防护用品不符合国家职业卫生标准和卫生要求的；\n（三）对职业病防护设备、应急救援设施和个人使用的职业病防护用品未按照规定进行维护、检修、检测，或者不能保持正常运行、使用状态的；\n（四）未按照规定对工作场所职业病危害因素进行检测、评价的；\n（五）工作场所职业病危害因素经治理仍然达不到国家职业卫生标准和卫生要求时，未停止存在职业病危害因素的作业的；\n（六）未按照规定安排职业病病人、疑似职业病病人进行诊治的；\n（七）发生或者可能发生急性职业病危害事故时，未立即采取应急救援和控制措施或者未按照规定及时报告的；\n（八）未按照规定在产生严重职业病危害的作业岗位醒目位置设置警示标识和中文警示说明的；\n（九）拒绝职业卫生监督管理部门监督检查的；\n（十）隐瞒、伪造、篡改、毁损职业健康监护档案、工作场所职业病危害因素检测评价结果等相关资料，或者拒不提供职业病诊断、鉴定所需资料的；\n（十一）未按照规定承担职业病诊断、鉴定费用和职业病病人的医疗、生活保障费用的。\n第七十三条 向用人单位提供可能产生职业病危害的设备、材料，未按照规定提供中文说明书或者设置警示标识和中文警示说明的，由卫生行政部门责令限期改正，给予警告，并处五万元以上二十万元以下的罚款。\n第七十四条 用人单位和医疗卫生机构未按照规定报告职业病、疑似职业病的，由有关主管部门依据职责分工责令限期改正，给予警告，可以并处一万元以下的罚款；弄虚作假的，并处二万元以上五万元以下的罚款；对直接负责的主管人员和其他直接责任人员，可以依法给予降级或者撤职的处分。\n第七十五条 违反本法规定，有下列情形之一的，由卫生行政部门责令限期治理，并处五万元以上三十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭：\n（一）隐瞒技术、工艺、设备、材料所产生的职业病危害而采用的；\n（二）隐瞒本单位职业卫生真实情况的；\n（三）可能发生急性职业损伤的有毒、有害工作场所、放射工作场所或者放射性同位素的运输、贮存不符合本法第二十五条规定的；\n（四）使用国家明令禁止使用的可能产生职业病危害的设备或者材料的；\n（五）将产生职业病危害的作业转移给没有职业病防护条件的单位和个人，或者没有职业病防护条件的单位和个人接受产生职业病危害的作业的；\n（六）擅自拆除、停止使用职业病防护设备或者应急救援设施的；\n（七）安排未经职业健康检查的劳动者、有职业禁忌的劳动者、未成年工或者孕期、哺乳期女职工从事接触职业病危害的作业或者禁忌作业的；\n（八）违章指挥和强令劳动者进行没有职业病防护措施的作业的。\n第七十六条 生产、经营或者进口国家明令禁止使用的可能产生职业病危害的设备或者材料的，依照有关法律、行政法规的规定给予处罚。\n第七十七条 用人单位违反本法规定，已经对劳动者生命健康造成严重损害的，由卫生行政部门责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭，并处十万元以上五十万元以下的罚款。\n第七十八条 用人单位违反本法规定，造成重大职业病危害事故或者其他严重后果，构成犯罪的，对直接负责的主管人员和其他直接责任人员，依法追究刑事责任。\n第七十九条 未取得职业卫生技术服务资质认可擅自从事职业卫生技术服务的，由卫生行政部门责令立即停止违法行为，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上十倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上五万元以下的罚款；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职或者开除的处分。\n第八十条 从事职业卫生技术服务的机构和承担职业病诊断的医疗卫生机构违反本法规定，有下列行为之一的，由卫生行政部门责令立即停止违法行为，给予警告，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上五倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上二万元以下的罚款；情节严重的，由原认可或者登记机关取消其相应的资格；对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职或者开除的处分；构成犯罪的，依法追究刑事责任：\n（一）超出资质认可或者诊疗项目登记范围从事职业卫生技术服务或者职业病诊断的；\n（二）不按照本法规定履行法定职责的；\n（三）出具虚假证明文件的。\n第八十一条 职业病诊断鉴定委员会组成人员收受职业病诊断争议当事人的财物或者其他好处的，给予警告，没收收受的财物，可以并处三千元以上五万元以下的罚款，取消其担任职业病诊断鉴定委员会组成人员的资格，并从省、自治区、直辖市人民政府卫生行政部门设立的专家库中予以除名。\n第八十二条 卫生行政部门不按照规定报告职业病和职业病危害事故的，由上一级行政部门责令改正，通报批评，给予警告；虚报、瞒报的，对单位负责人、直接负责的主管人员和其他直接责任人员依法给予降级、撤职或者开除的处分。\n第八十三条 县级以上地方人民政府在职业病防治工作中未依照本法履行职责，本行政区域出现重大职业病危害事故、造成严重社会影响的，依法对直接负责的主管人员和其他直接责任人员给予记大过直至开除的处分。\n县级以上人民政府职业卫生监督管理部门不履行本法规定的职责，滥用职权、玩忽职守、徇私舞弊，依法对直接负责的主管人员和其他直接责任人员给予记大过或者降级的处分；造成职业病危害事故或者其他严重后果的，依法给予撤职或者开除的处分。\n第八十四条 违反本法规定，构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附 则","text":"第八十五条 本法下列用语的含义：\n职业病危害，是指对从事职业活动的劳动者可能导致职业病的各种危害。职业病危害因素包括：职业活动中存在的各种有害的化学、物理、生物因素以及在作业过程中产生的其他职业有害因素。\n职业禁忌，是指劳动者从事特定职业或者接触特定职业病危害因素时，比一般职业人群更易于遭受职业病危害和罹患职业病或者可能导致原有自身疾病病情加重，或者在从事作业过程中诱发可能导致对他人生命健康构成危险的疾病的个人特殊生理或者病理状态。\n第八十六条 本法第二条规定的用人单位以外的单位，产生职业病危害的，其职业病防治活动可以参照本法执行。\n劳务派遣用工单位应当履行本法规定的用人单位的义务。\n中国人民解放军参照执行本法的办法，由国务院、中央军事委员会制定。\n第八十七条 对医疗机构放射性职业病危害控制的监督管理，由卫生行政部门依照本法的规定实施。\n第八十八条 本法自2002年5月1日起施行。","level":1}]},{"id":"n0281","sections":[{"name":"","text":"中华人民共和国耕地占用税法\n（2018年12月29日第十三届全国人民代表大会常务委员会第七次会议通过）\n第一条 为了合理利用土地资源，加强土地管理，保护耕地，制定本法。\n第二条 在中华人民共和国境内占用耕地建设建筑物、构筑物或者从事非农业建设的单位和个人，为耕地占用税的纳税人，应当依照本法规定缴纳耕地占用税。\n占用耕地建设农田水利设施的，不缴纳耕地占用税。\n本法所称耕地，是指用于种植农作物的土地。\n第三条 耕地占用税以纳税人实际占用的耕地面积为计税依据，按照规定的适用税额一次性征收，应纳税额为纳税人实际占用的耕地面积（平方米）乘以适用税额。\n第四条 耕地占用税的税额如下：\n（一）人均耕地不超过一亩的地区（以县、自治县、不设区的市、市辖区为单位，下同），每平方米为十元至五十元；\n（二）人均耕地超过一亩但不超过二亩的地区，每平方米为八元至四十元；\n（三）人均耕地超过二亩但不超过三亩的地区，每平方米为六元至三十元；\n（四）人均耕地超过三亩的地区，每平方米为五元至二十五元。\n各地区耕地占用税的适用税额，由省、自治区、直辖市人民政府根据人均耕地面积和经济发展等情况，在前款规定的税额幅度内提出，报同级人民代表大会常务委员会决定，并报全国人民代表大会常务委员会和国务院备案。各省、自治区、直辖市耕地占用税适用税额的平均水平，不得低于本法所附《各省、自治区、直辖市耕地占用税平均税额表》规定的平均税额。\n第五条 在人均耕地低于零点五亩的地区，省、自治区、直辖市可以根据当地经济发展情况，适当提高耕地占用税的适用税额，但提高的部分不得超过本法第四条第二款确定的适用税额的百分之五十。具体适用税额按照本法第四条第二款规定的程序确定。\n第六条 占用基本农田的，应当按照本法第四条第二款或者第五条确定的当地适用税额，加按百分之一百五十征收。\n第七条 军事设施、学校、幼儿园、社会福利机构、医疗机构占用耕地，免征耕地占用税。\n铁路线路、公路线路、飞机场跑道、停机坪、港口、航道、水利工程占用耕地，减按每平方米二元的税额征收耕地占用税。\n农村居民在规定用地标准以内占用耕地新建自用住宅，按照当地适用税额减半征收耕地占用税；其中农村居民经批准搬迁，新建自用住宅占用耕地不超过原宅基地面积的部分，免征耕地占用税。\n农村烈士遗属、因公牺牲军人遗属、残疾军人以及符合农村最低生活保障条件的农村居民，在规定用地标准以内新建自用住宅，免征耕地占用税。\n根据国民经济和社会发展的需要，国务院可以规定免征或者减征耕地占用税的其他情形，报全国人民代表大会常务委员会备案。\n第八条 依照本法第七条第一款、第二款规定免征或者减征耕地占用税后，纳税人改变原占地用途，不再属于免征或者减征耕地占用税情形的，应当按照当地适用税额补缴耕地占用税。\n第九条 耕地占用税由税务机关负责征收。\n第十条 耕地占用税的纳税义务发生时间为纳税人收到自然资源主管部门办理占用耕地手续的书面通知的当日。纳税人应当自纳税义务发生之日起三十日内申报缴纳耕地占用税。\n自然资源主管部门凭耕地占用税完税凭证或者免税凭证和其他有关文件发放建设用地批准书。\n第十一条 纳税人因建设项目施工或者地质勘查临时占用耕地，应当依照本法的规定缴纳耕地占用税。纳税人在批准临时占用耕地期满之日起一年内依法复垦，恢复种植条件的，全额退还已经缴纳的耕地占用税。\n第十二条 占用园地、林地、草地、农田水利用地、养殖水面、渔业水域滩涂以及其他农用地建设建筑物、构筑物或者从事非农业建设的，依照本法的规定缴纳耕地占用税。\n占用前款规定的农用地的，适用税额可以适当低于本地区按照本法第四条第二款确定的适用税额，但降低的部分不得超过百分之五十。具体适用税额由省、自治区、直辖市人民政府提出，报同级人民代表大会常务委员会决定，并报全国人民代表大会常务委员会和国务院备案。\n占用本条第一款规定的农用地建设直接为农业生产服务的生产设施的，不缴纳耕地占用税。\n第十三条 税务机关应当与相关部门建立耕地占用税涉税信息共享机制和工作配合机制。县级以上地方人民政府自然资源、农业农村、水利等相关部门应当定期向税务机关提供农用地转用、临时占地等信息，协助税务机关加强耕地占用税征收管理。\n税务机关发现纳税人的纳税申报数据资料异常或者纳税人未按照规定期限申报纳税的，可以提请相关部门进行复核，相关部门应当自收到税务机关复核申请之日起三十日内向税务机关出具复核意见。\n第十四条 耕地占用税的征收管理，依照本法和《中华人民共和国税收征收管理法》的规定执行。\n第十五条 纳税人、税务机关及其工作人员违反本法规定的，依照《中华人民共和国税收征收管理法》和有关法律法规的规定追究法律责任。\n第十六条 本法自2019年9月1日起施行。2007年12月1日国务院公布的《中华人民共和国耕地占用税暂行条例》同时废止。\n附：\n各省、自治区、直辖市耕地占用税平均税率表\n省、自治区、直辖市\t平均税额（元/平方米）\n上海\t45\n北京\t40\n天津\t35\n江苏、浙江、福建、广东\t30\n辽宁、湖北、湖南\t25\n河北、安徽、江西、山东、河南、重庆、四川\t22.5\n广西、海南、贵州、云南、陕西\t20\n山西、吉林、黑龙江\t17.5\n内蒙古、西藏、甘肃、青海、宁夏、新疆\t12.5","level":0}]},{"id":"n0282","sections":[{"name":"","text":"中华人民共和国车辆购置税法\n（2018年12月29日第十三届全国人民代表大会常务委员会第七次会议通过）\n第一条 在中华人民共和国境内购置汽车、有轨电车、汽车挂车、排气量超过一百五十毫升的摩托车（以下统称应税车辆）的单位和个人，为车辆购置税的纳税人，应当依照本法规定缴纳车辆购置税。\n第二条 本法所称购置，是指以购买、进口、自产、受赠、获奖或者其他方式取得并自用应税车辆的行为。\n第三条 车辆购置税实行一次性征收。购置已征车辆购置税的车辆，不再征收车辆购置税。\n第四条 车辆购置税的税率为百分之十。\n第五条 车辆购置税的应纳税额按照应税车辆的计税价格乘以税率计算。\n第六条 应税车辆的计税价格，按照下列规定确定：\n（一）纳税人购买自用应税车辆的计税价格，为纳税人实际支付给销售者的全部价款，不包括增值税税款；\n（二）纳税人进口自用应税车辆的计税价格，为关税完税价格加上关税和消费税；\n（三）纳税人自产自用应税车辆的计税价格，按照纳税人生产的同类应税车辆的销售价格确定，不包括增值税税款；\n（四）纳税人以受赠、获奖或者其他方式取得自用应税车辆的计税价格，按照购置应税车辆时相关凭证载明的价格确定，不包括增值税税款。\n第七条 纳税人申报的应税车辆计税价格明显偏低，又无正当理由的，由税务机关依照《中华人民共和国税收征收管理法》的规定核定其应纳税额。\n第八条 纳税人以外汇结算应税车辆价款的，按照申报纳税之日的人民币汇率中间价折合成人民币计算缴纳税款。\n第九条 下列车辆免征车辆购置税：\n（一）依照法律规定应当予以免税的外国驻华使馆、领事馆和国际组织驻华机构及其有关人员自用的车辆；\n（二）中国人民解放军和中国人民武装警察部队列入装备订货计划的车辆；\n（三）悬挂应急救援专用号牌的国家综合性消防救援车辆；\n（四）设有固定装置的非运输专用作业车辆；\n（五）城市公交企业购置的公共汽电车辆。\n根据国民经济和社会发展的需要，国务院可以规定减征或者其他免征车辆购置税的情形，报全国人民代表大会常务委员会备案。\n第十条 车辆购置税由税务机关负责征收。\n第十一条 纳税人购置应税车辆，应当向车辆登记地的主管税务机关申报缴纳车辆购置税；购置不需要办理车辆登记的应税车辆的，应当向纳税人所在地的主管税务机关申报缴纳车辆购置税。\n第十二条 车辆购置税的纳税义务发生时间为纳税人购置应税车辆的当日。纳税人应当自纳税义务发生之日起六十日内申报缴纳车辆购置税。\n第十三条 纳税人应当在向公安机关交通管理部门办理车辆注册登记前，缴纳车辆购置税。\n公安机关交通管理部门办理车辆注册登记，应当根据税务机关提供的应税车辆完税或者免税电子信息对纳税人申请登记的车辆信息进行核对，核对无误后依法办理车辆注册登记。\n第十四条 免税、减税车辆因转让、改变用途等原因不再属于免税、减税范围的，纳税人应当在办理车辆转移登记或者变更登记前缴纳车辆购置税。计税价格以免税、减税车辆初次办理纳税申报时确定的计税价格为基准，每满一年扣减百分之十。\n第十五条 纳税人将已征车辆购置税的车辆退回车辆生产企业或者销售企业的，可以向主管税务机关申请退还车辆购置税。退税额以已缴税款为基准，自缴纳税款之日至申请退税之日，每满一年扣减百分之十。\n第十六条 税务机关和公安、商务、海关、工业和信息化等部门应当建立应税车辆信息共享和工作配合机制，及时交换应税车辆和纳税信息资料。\n第十七条 车辆购置税的征收管理，依照本法和《中华人民共和国税收征收管理法》的规定执行。\n第十八条 纳税人、税务机关及其工作人员违反本法规定的，依照《中华人民共和国税收征收管理法》和有关法律法规的规定追究法律责任。\n第十九条 本法自2019年7月1日起施行。2000年10月22日国务院公布的《中华人民共和国车辆购置税暂行条例》同时废止。","level":0}]},{"id":"n0283","sections":[{"name":"","text":"中华人民共和国车船税法\n（2011年2月25日第十一届全国人民代表大会常务委员会第十九次会议通过 根据2019年4月23日第十三届全国人民代表大会常务委员会第十次会议《关于修改〈中华人民共和国建筑法〉等八部法律的决定》修正）\n第一条 在中华人民共和国境内属于本法所附《车船税税目税额表》规定的车辆、船舶（以下简称车船）的所有人或者管理人，为车船税的纳税人，应当依照本法缴纳车船税。\n第二条 车船的适用税额依照本法所附《车船税税目税额表》执行。\n车辆的具体适用税额由省、自治区、直辖市人民政府依照本法所附《车船税税目税额表》规定的税额幅度和国务院的规定确定。\n船舶的具体适用税额由国务院在本法所附《车船税税目税额表》规定的税额幅度内确定。\n第三条 下列车船免征车船税：\n（一）捕捞、养殖渔船；\n（二）军队、武装警察部队专用的车船；\n（三）警用车船；\n（四）悬挂应急救援专用号牌的国家综合性消防救援车辆和国家综合性消防救援专用船舶；\n（五）依照法律规定应当予以免税的外国驻华使领馆、国际组织驻华代表机构及其有关人员的车船。\n第四条 对节约能源、使用新能源的车船可以减征或者免征车船税；对受严重自然灾害影响纳税困难以及有其他特殊原因确需减税、免税的，可以减征或者免征车船税。具体办法由国务院规定，并报全国人民代表大会常务委员会备案。\n第五条 省、自治区、直辖市人民政府根据当地实际情况，可以对公共交通车船，农村居民拥有并主要在农村地区使用的摩托车、三轮汽车和低速载货汽车定期减征或者免征车船税。\n第六条 从事机动车第三者责任强制保险业务的保险机构为机动车车船税的扣缴义务人，应当在收取保险费时依法代收车船税，并出具代收税款凭证。\n第七条 车船税的纳税地点为车船的登记地或者车船税扣缴义务人所在地。依法不需要办理登记的车船，车船税的纳税地点为车船的所有人或者管理人所在地。\n第八条 车船税纳税义务发生时间为取得车船所有权或者管理权的当月。\n第九条 车船税按年申报缴纳。具体申报纳税期限由省、自治区、直辖市人民政府规定。\n第十条 公安、交通运输、农业、渔业等车船登记管理部门、船舶检验机构和车船税扣缴义务人的行业主管部门应当在提供车船有关信息等方面，协助税务机关加强车船税的征收管理。\n车辆所有人或者管理人在申请办理车辆相关登记、定期检验手续时，应当向公安机关交通管理部门提交依法纳税或者免税证明。公安机关交通管理部门核查后办理相关手续。\n第十一条 车船税的征收管理，依照本法和《中华人民共和国税收征收管理法》的规定执行。\n第十二条 国务院根据本法制定实施条例。\n第十三条 本法自2012年1月1日起施行。2006年12月29日国务院公布的《中华人民共和国车船税暂行条例》同时废止。\n附：\n车船税税目税额表\n税目\t计税单位\t年基准税额\t备注\n容量（排气量）分档〕乘用车〔按发动机汽缸\t1. 0升（含）以下的\t每辆\t60元至360元\t核定载客人数9人（含）以下\n1. 0升以上至1.6升（含）的 300元至540元\n1. 6升以上至2.0升（含）的\t每辆\t360元至660元\n2. 0升以上至2.5升（含）的 660元至1200元\n2. 5升以上至3.0升（含）的 1200元至2400元\n3. 0升以上至4.0升（含）的 2400元至3600元\n4. 0升以上的 3600元至5400元\n商用车\t客车\t每辆\t480元至1440元\t核定载客人数9人以上，包括电车\n货车\t整备质量每吨\t16元至120元\t包括半挂牵引车、三轮汽车和低速载货汽车等\n挂车 整备质量每吨\t按照货车税额的50％计算\n其他车辆\t专用作业车\t整备质量每吨\t16元至120元\t不包括拖拉机\n轮式专用机械车 16元至120元\n摩托车 每辆\t36元至180元\n船舶\t机动船舶\t净吨位每吨\t3元至6元\t拖船、非机动驳船分别按照机动船舶税额的50％计算\n游艇\t艇身长度每米\t600元至2000元","level":0}]},{"id":"n0284","sections":[{"name":"","text":"中华人民共和国城乡规划法\n（2007年10月28日第十届全国人民代表大会常务委员会第三十次会议通过 根据2015年4月24日第十二届全国人民代表大会常务委员会第十四次会议《关于修改〈中华人民共和国港口法〉等七部法律的决定》第一次修正 根据2019年4月23日第十三届全国人民代表大会常务委员会第十次会议《关于修改〈中华人民共和国建筑法〉等八部法律的决定》第二次修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强城乡规划管理，协调城乡空间布局，改善人居环境，促进城乡经济社会全面协调可持续发展，制定本法。\n第二条 制定和实施城乡规划，在规划区内进行建设活动，必须遵守本法。\n本法所称城乡规划，包括城镇体系规划、城市规划、镇规划、乡规划和村庄规划。城市规划、镇规划分为总体规划和详细规划。详细规划分为控制性详细规划和修建性详细规划。\n本法所称规划区，是指城市、镇和村庄的建成区以及因城乡建设和发展需要，必须实行规划控制的区域。规划区的具体范围由有关人民政府在组织编制的城市总体规划、镇总体规划、乡规划和村庄规划中，根据城乡经济社会发展水平和统筹城乡发展的需要划定。\n第三条 城市和镇应当依照本法制定城市规划和镇规划。城市、镇规划区内的建设活动应当符合规划要求。\n县级以上地方人民政府根据本地农村经济社会发展水平，按照因地制宜、切实可行的原则，确定应当制定乡规划、村庄规划的区域。在确定区域内的乡、村庄，应当依照本法制定规划，规划区内的乡、村庄建设应当符合规划要求。\n县级以上地方人民政府鼓励、指导前款规定以外的区域的乡、村庄制定和实施乡规划、村庄规划。\n第四条 制定和实施城乡规划，应当遵循城乡统筹、合理布局、节约土地、集约发展和先规划后建设的原则，改善生态环境，促进资源、能源节约和综合利用，保护耕地等自然资源和历史文化遗产，保持地方特色、民族特色和传统风貌，防止污染和其他公害，并符合区域人口发展、国防建设、防灾减灾和公共卫生、公共安全的需要。\n在规划区内进行建设活动，应当遵守土地管理、自然资源和环境保护等法律、法规的规定。\n县级以上地方人民政府应当根据当地经济社会发展的实际，在城市总体规划、镇总体规划中合理确定城市、镇的发展规模、步骤和建设标准。\n第五条 城市总体规划、镇总体规划以及乡规划和村庄规划的编制，应当依据国民经济和社会发展规划，并与土地利用总体规划相衔接。\n第六条 各级人民政府应当将城乡规划的编制和管理经费纳入本级财政预算。\n第七条 经依法批准的城乡规划，是城乡建设和规划管理的依据，未经法定程序不得修改。\n第八条 城乡规划组织编制机关应当及时公布经依法批准的城乡规划。但是，法律、行政法规规定不得公开的内容除外。\n第九条 任何单位和个人都应当遵守经依法批准并公布的城乡规划，服从规划管理，并有权就涉及其利害关系的建设活动是否符合规划的要求向城乡规划主管部门查询。\n任何单位和个人都有权向城乡规划主管部门或者其他有关部门举报或者控告违反城乡规划的行为。城乡规划主管部门或者其他有关部门对举报或者控告，应当及时受理并组织核查、处理。\n第十条 国家鼓励采用先进的科学技术，增强城乡规划的科学性，提高城乡规划实施及监督管理的效能。\n第十一条 国务院城乡规划主管部门负责全国的城乡规划管理工作。\n县级以上地方人民政府城乡规划主管部门负责本行政区域内的城乡规划管理工作。","level":1},{"name":"第二章 城乡规划的制定","text":"第十二条 国务院城乡规划主管部门会同国务院有关部门组织编制全国城镇体系规划，用于指导省域城镇体系规划、城市总体规划的编制。\n全国城镇体系规划由国务院城乡规划主管部门报国务院审批。\n第十三条 省、自治区人民政府组织编制省域城镇体系规划，报国务院审批。\n省域城镇体系规划的内容应当包括：城镇空间布局和规模控制，重大基础设施的布局，为保护生态环境、资源等需要严格控制的区域。\n第十四条 城市人民政府组织编制城市总体规划。\n直辖市的城市总体规划由直辖市人民政府报国务院审批。省、自治区人民政府所在地的城市以及国务院确定的城市的总体规划，由省、自治区人民政府审查同意后，报国务院审批。其他城市的总体规划，由城市人民政府报省、自治区人民政府审批。\n第十五条 县人民政府组织编制县人民政府所在地镇的总体规划，报上一级人民政府审批。其他镇的总体规划由镇人民政府组织编制，报上一级人民政府审批。\n第十六条 省、自治区人民政府组织编制的省域城镇体系规划，城市、县人民政府组织编制的总体规划，在报上一级人民政府审批前，应当先经本级人民代表大会常务委员会审议，常务委员会组成人员的审议意见交由本级人民政府研究处理。\n镇人民政府组织编制的镇总体规划，在报上一级人民政府审批前，应当先经镇人民代表大会审议，代表的审议意见交由本级人民政府研究处理。\n规划的组织编制机关报送审批省域城镇体系规划、城市总体规划或者镇总体规划，应当将本级人民代表大会常务委员会组成人员或者镇人民代表大会代表的审议意见和根据审议意见修改规划的情况一并报送。\n第十七条 城市总体规划、镇总体规划的内容应当包括：城市、镇的发展布局，功能分区，用地布局，综合交通体系，禁止、限制和适宜建设的地域范围，各类专项规划等。\n规划区范围、规划区内建设用地规模、基础设施和公共服务设施用地、水源地和水系、基本农田和绿化用地、环境保护、自然与历史文化遗产保护以及防灾减灾等内容，应当作为城市总体规划、镇总体规划的强制性内容。\n城市总体规划、镇总体规划的规划期限一般为二十年。城市总体规划还应当对城市更长远的发展作出预测性安排。\n第十八条 乡规划、村庄规划应当从农村实际出发，尊重村民意愿，体现地方和农村特色。\n乡规划、村庄规划的内容应当包括：规划区范围，住宅、道路、供水、排水、供电、垃圾收集、畜禽养殖场所等农村生产、生活服务设施、公益事业等各项建设的用地布局、建设要求，以及对耕地等自然资源和历史文化遗产保护、防灾减灾等的具体安排。乡规划还应当包括本行政区域内的村庄发展布局。\n第十九条 城市人民政府城乡规划主管部门根据城市总体规划的要求，组织编制城市的控制性详细规划，经本级人民政府批准后，报本级人民代表大会常务委员会和上一级人民政府备案。\n第二十条 镇人民政府根据镇总体规划的要求，组织编制镇的控制性详细规划，报上一级人民政府审批。县人民政府所在地镇的控制性详细规划，由县人民政府城乡规划主管部门根据镇总体规划的要求组织编制，经县人民政府批准后，报本级人民代表大会常务委员会和上一级人民政府备案。\n第二十一条 城市、县人民政府城乡规划主管部门和镇人民政府可以组织编制重要地块的修建性详细规划。修建性详细规划应当符合控制性详细规划。\n第二十二条 乡、镇人民政府组织编制乡规划、村庄规划，报上一级人民政府审批。村庄规划在报送审批前，应当经村民会议或者村民代表会议讨论同意。\n第二十三条 首都的总体规划、详细规划应当统筹考虑中央国家机关用地布局和空间安排的需要。\n第二十四条 城乡规划组织编制机关应当委托具有相应资质等级的单位承担城乡规划的具体编制工作。\n从事城乡规划编制工作应当具备下列条件，并经国务院城乡规划主管部门或者省、自治区、直辖市人民政府城乡规划主管部门依法审查合格，取得相应等级的资质证书后，方可在资质等级许可的范围内从事城乡规划编制工作：\n（一）有法人资格；\n（二）有规定数量的经相关行业协会注册的规划师；\n（三）有规定数量的相关专业技术人员；\n（四）有相应的技术装备；\n（五）有健全的技术、质量、财务管理制度。\n编制城乡规划必须遵守国家有关标准。\n第二十五条 编制城乡规划，应当具备国家规定的勘察、测绘、气象、地震、水文、环境等基础资料。\n县级以上地方人民政府有关主管部门应当根据编制城乡规划的需要，及时提供有关基础资料。\n第二十六条 城乡规划报送审批前，组织编制机关应当依法将城乡规划草案予以公告，并采取论证会、听证会或者其他方式征求专家和公众的意见。公告的时间不得少于三十日。\n组织编制机关应当充分考虑专家和公众的意见，并在报送审批的材料中附具意见采纳情况及理由。\n第二十七条 省域城镇体系规划、城市总体规划、镇总体规划批准前，审批机关应当组织专家和有关部门进行审查。","level":1},{"name":"第三章 城乡规划的实施","text":"第二十八条 地方各级人民政府应当根据当地经济社会发展水平，量力而行，尊重群众意愿，有计划、分步骤地组织实施城乡规划。\n第二十九条 城市的建设和发展，应当优先安排基础设施以及公共服务设施的建设，妥善处理新区开发与旧区改建的关系，统筹兼顾进城务工人员生活和周边农村经济社会发展、村民生产与生活的需要。\n镇的建设和发展，应当结合农村经济社会发展和产业结构调整，优先安排供水、排水、供电、供气、道路、通信、广播电视等基础设施和学校、卫生院、文化站、幼儿园、福利院等公共服务设施的建设，为周边农村提供服务。\n乡、村庄的建设和发展，应当因地制宜、节约用地，发挥村民自治组织的作用，引导村民合理进行建设，改善农村生产、生活条件。\n第三十条 城市新区的开发和建设，应当合理确定建设规模和时序，充分利用现有市政基础设施和公共服务设施，严格保护自然资源和生态环境，体现地方特色。\n在城市总体规划、镇总体规划确定的建设用地范围以外，不得设立各类开发区和城市新区。\n第三十一条 旧城区的改建，应当保护历史文化遗产和传统风貌，合理确定拆迁和建设规模，有计划地对危房集中、基础设施落后等地段进行改建。\n历史文化名城、名镇、名村的保护以及受保护建筑物的维护和使用，应当遵守有关法律、行政法规和国务院的规定。\n第三十二条 城乡建设和发展，应当依法保护和合理利用风景名胜资源，统筹安排风景名胜区及周边乡、镇、村庄的建设。\n风景名胜区的规划、建设和管理，应当遵守有关法律、行政法规和国务院的规定。\n第三十三条 城市地下空间的开发和利用，应当与经济和技术发展水平相适应，遵循统筹安排、综合开发、合理利用的原则，充分考虑防灾减灾、人民防空和通信等需要，并符合城市规划，履行规划审批手续。\n第三十四条 城市、县、镇人民政府应当根据城市总体规划、镇总体规划、土地利用总体规划和年度计划以及国民经济和社会发展规划，制定近期建设规划，报总体规划审批机关备案。\n近期建设规划应当以重要基础设施、公共服务设施和中低收入居民住房建设以及生态环境保护为重点内容，明确近期建设的时序、发展方向和空间布局。近期建设规划的规划期限为五年。\n第三十五条 城乡规划确定的铁路、公路、港口、机场、道路、绿地、输配电设施及输电线路走廊、通信设施、广播电视设施、管道设施、河道、水库、水源地、自然保护区、防汛通道、消防通道、核电站、垃圾填埋场及焚烧厂、污水处理厂和公共服务设施的用地以及其他需要依法保护的用地，禁止擅自改变用途。\n第三十六条 按照国家规定需要有关部门批准或者核准的建设项目，以划拨方式提供国有土地使用权的，建设单位在报送有关部门批准或者核准前，应当向城乡规划主管部门申请核发选址意见书。\n前款规定以外的建设项目不需要申请选址意见书。\n第三十七条 在城市、镇规划区内以划拨方式提供国有土地使用权的建设项目，经有关部门批准、核准、备案后，建设单位应当向城市、县人民政府城乡规划主管部门提出建设用地规划许可申请，由城市、县人民政府城乡规划主管部门依据控制性详细规划核定建设用地的位置、面积、允许建设的范围，核发建设用地规划许可证。\n建设单位在取得建设用地规划许可证后，方可向县级以上地方人民政府土地主管部门申请用地，经县级以上人民政府审批后，由土地主管部门划拨土地。\n第三十八条 在城市、镇规划区内以出让方式提供国有土地使用权的，在国有土地使用权出让前，城市、县人民政府城乡规划主管部门应当依据控制性详细规划，提出出让地块的位置、使用性质、开发强度等规划条件，作为国有土地使用权出让合同的组成部分。未确定规划条件的地块，不得出让国有土地使用权。\n以出让方式取得国有土地使用权的建设项目，建设单位在取得建设项目的批准、核准、备案文件和签订国有土地使用权出让合同后，向城市、县人民政府城乡规划主管部门领取建设用地规划许可证。\n城市、县人民政府城乡规划主管部门不得在建设用地规划许可证中，擅自改变作为国有土地使用权出让合同组成部分的规划条件。\n第三十九条 规划条件未纳入国有土地使用权出让合同的，该国有土地使用权出让合同无效；对未取得建设用地规划许可证的建设单位批准用地的，由县级以上人民政府撤销有关批准文件；占用土地的，应当及时退回；给当事人造成损失的，应当依法给予赔偿。\n第四十条 在城市、镇规划区内进行建筑物、构筑物、道路、管线和其他工程建设的，建设单位或者个人应当向城市、县人民政府城乡规划主管部门或者省、自治区、直辖市人民政府确定的镇人民政府申请办理建设工程规划许可证。\n申请办理建设工程规划许可证，应当提交使用土地的有关证明文件、建设工程设计方案等材料。需要建设单位编制修建性详细规划的建设项目，还应当提交修建性详细规划。对符合控制性详细规划和规划条件的，由城市、县人民政府城乡规划主管部门或者省、自治区、直辖市人民政府确定的镇人民政府核发建设工程规划许可证。\n城市、县人民政府城乡规划主管部门或者省、自治区、直辖市人民政府确定的镇人民政府应当依法将经审定的修建性详细规划、建设工程设计方案的总平面图予以公布。\n第四十一条 在乡、村庄规划区内进行乡镇企业、乡村公共设施和公益事业建设的，建设单位或者个人应当向乡、镇人民政府提出申请，由乡、镇人民政府报城市、县人民政府城乡规划主管部门核发乡村建设规划许可证。\n在乡、村庄规划区内使用原有宅基地进行农村村民住宅建设的规划管理办法，由省、自治区、直辖市制定。\n在乡、村庄规划区内进行乡镇企业、乡村公共设施和公益事业建设以及农村村民住宅建设，不得占用农用地；确需占用农用地的，应当依照《中华人民共和国土地管理法》有关规定办理农用地转用审批手续后，由城市、县人民政府城乡规划主管部门核发乡村建设规划许可证。\n建设单位或者个人在取得乡村建设规划许可证后，方可办理用地审批手续。\n第四十二条 城乡规划主管部门不得在城乡规划确定的建设用地范围以外作出规划许可。\n第四十三条 建设单位应当按照规划条件进行建设；确需变更的，必须向城市、县人民政府城乡规划主管部门提出申请。变更内容不符合控制性详细规划的，城乡规划主管部门不得批准。城市、县人民政府城乡规划主管部门应当及时将依法变更后的规划条件通报同级土地主管部门并公示。\n建设单位应当及时将依法变更后的规划条件报有关人民政府土地主管部门备案。\n第四十四条 在城市、镇规划区内进行临时建设的，应当经城市、县人民政府城乡规划主管部门批准。临时建设影响近期建设规划或者控制性详细规划的实施以及交通、市容、安全等的，不得批准。\n临时建设应当在批准的使用期限内自行拆除。\n临时建设和临时用地规划管理的具体办法，由省、自治区、直辖市人民政府制定。\n第四十五条 县级以上地方人民政府城乡规划主管部门按照国务院规定对建设工程是否符合规划条件予以核实。未经核实或者经核实不符合规划条件的，建设单位不得组织竣工验收。\n建设单位应当在竣工验收后六个月内向城乡规划主管部门报送有关竣工验收资料。","level":1},{"name":"第四章 城乡规划的修改","text":"第四十六条 省域城镇体系规划、城市总体规划、镇总体规划的组织编制机关，应当组织有关部门和专家定期对规划实施情况进行评估，并采取论证会、听证会或者其他方式征求公众意见。组织编制机关应当向本级人民代表大会常务委员会、镇人民代表大会和原审批机关提出评估报告并附具征求意见的情况。\n第四十七条 有下列情形之一的，组织编制机关方可按照规定的权限和程序修改省域城镇体系规划、城市总体规划、镇总体规划：\n（一）上级人民政府制定的城乡规划发生变更，提出修改规划要求的；\n（二）行政区划调整确需修改规划的；\n（三）因国务院批准重大建设工程确需修改规划的；\n（四）经评估确需修改规划的；\n（五）城乡规划的审批机关认为应当修改规划的其他情形。\n修改省域城镇体系规划、城市总体规划、镇总体规划前，组织编制机关应当对原规划的实施情况进行总结，并向原审批机关报告；修改涉及城市总体规划、镇总体规划强制性内容的，应当先向原审批机关提出专题报告，经同意后，方可编制修改方案。\n修改后的省域城镇体系规划、城市总体规划、镇总体规划，应当依照本法第十三条、第十四条、第十五条和第十六条规定的审批程序报批。\n第四十八条 修改控制性详细规划的，组织编制机关应当对修改的必要性进行论证，征求规划地段内利害关系人的意见，并向原审批机关提出专题报告，经原审批机关同意后，方可编制修改方案。修改后的控制性详细规划，应当依照本法第十九条、第二十条规定的审批程序报批。控制性详细规划修改涉及城市总体规划、镇总体规划的强制性内容的，应当先修改总体规划。\n修改乡规划、村庄规划的，应当依照本法第二十二条规定的审批程序报批。\n第四十九条 城市、县、镇人民政府修改近期建设规划的，应当将修改后的近期建设规划报总体规划审批机关备案。\n第五十条 在选址意见书、建设用地规划许可证、建设工程规划许可证或者乡村建设规划许可证发放后，因依法修改城乡规划给被许可人合法权益造成损失的，应当依法给予补偿。\n经依法审定的修建性详细规划、建设工程设计方案的总平面图不得随意修改；确需修改的，城乡规划主管部门应当采取听证会等形式，听取利害关系人的意见；因修改给利害关系人合法权益造成损失的，应当依法给予补偿。","level":1},{"name":"第五章 监督检查","text":"第五十一条 县级以上人民政府及其城乡规划主管部门应当加强对城乡规划编制、审批、实施、修改的监督检查。\n第五十二条 地方各级人民政府应当向本级人民代表大会常务委员会或者乡、镇人民代表大会报告城乡规划的实施情况，并接受监督。\n第五十三条 县级以上人民政府城乡规划主管部门对城乡规划的实施情况进行监督检查，有权采取以下措施：\n（一）要求有关单位和人员提供与监督事项有关的文件、资料，并进行复制；\n（二）要求有关单位和人员就监督事项涉及的问题作出解释和说明，并根据需要进入现场进行勘测；\n（三）责令有关单位和人员停止违反有关城乡规划的法律、法规的行为。\n城乡规划主管部门的工作人员履行前款规定的监督检查职责，应当出示执法证件。被监督检查的单位和人员应当予以配合，不得妨碍和阻挠依法进行的监督检查活动。\n第五十四条 监督检查情况和处理结果应当依法公开，供公众查阅和监督。\n第五十五条 城乡规划主管部门在查处违反本法规定的行为时，发现国家机关工作人员依法应当给予行政处分的，应当向其任免机关或者监察机关提出处分建议。\n第五十六条 依照本法规定应当给予行政处罚，而有关城乡规划主管部门不给予行政处罚的，上级人民政府城乡规划主管部门有权责令其作出行政处罚决定或者建议有关人民政府责令其给予行政处罚。\n第五十七条 城乡规划主管部门违反本法规定作出行政许可的，上级人民政府城乡规划主管部门有权责令其撤销或者直接撤销该行政许可。因撤销行政许可给当事人合法权益造成损失的，应当依法给予赔偿。","level":1},{"name":"第六章 法律责任","text":"第五十八条 对依法应当编制城乡规划而未组织编制，或者未按法定程序编制、审批、修改城乡规划的，由上级人民政府责令改正，通报批评；对有关人民政府负责人和其他直接责任人员依法给予处分。\n第五十九条 城乡规划组织编制机关委托不具有相应资质等级的单位编制城乡规划的，由上级人民政府责令改正，通报批评；对有关人民政府负责人和其他直接责任人员依法给予处分。\n第六十条 镇人民政府或者县级以上人民政府城乡规划主管部门有下列行为之一的，由本级人民政府、上级人民政府城乡规划主管部门或者监察机关依据职权责令改正，通报批评；对直接负责的主管人员和其他直接责任人员依法给予处分：\n（一）未依法组织编制城市的控制性详细规划、县人民政府所在地镇的控制性详细规划的；\n（二）超越职权或者对不符合法定条件的申请人核发选址意见书、建设用地规划许可证、建设工程规划许可证、乡村建设规划许可证的；\n（三）对符合法定条件的申请人未在法定期限内核发选址意见书、建设用地规划许可证、建设工程规划许可证、乡村建设规划许可证的；\n（四）未依法对经审定的修建性详细规划、建设工程设计方案的总平面图予以公布的；\n（五）同意修改修建性详细规划、建设工程设计方案的总平面图前未采取听证会等形式听取利害关系人的意见的；\n（六）发现未依法取得规划许可或者违反规划许可的规定在规划区内进行建设的行为，而不予查处或者接到举报后不依法处理的。\n第六十一条 县级以上人民政府有关部门有下列行为之一的，由本级人民政府或者上级人民政府有关部门责令改正，通报批评；对直接负责的主管人员和其他直接责任人员依法给予处分：\n（一）对未依法取得选址意见书的建设项目核发建设项目批准文件的；\n（二）未依法在国有土地使用权出让合同中确定规划条件或者改变国有土地使用权出让合同中依法确定的规划条件的；\n（三）对未依法取得建设用地规划许可证的建设单位划拨国有土地使用权的。\n第六十二条 城乡规划编制单位有下列行为之一的，由所在地城市、县人民政府城乡规划主管部门责令限期改正，处合同约定的规划编制费一倍以上二倍以下的罚款；情节严重的，责令停业整顿，由原发证机关降低资质等级或者吊销资质证书；造成损失的，依法承担赔偿责任：\n（一）超越资质等级许可的范围承揽城乡规划编制工作的；\n（二）违反国家有关标准编制城乡规划的。\n未依法取得资质证书承揽城乡规划编制工作的，由县级以上地方人民政府城乡规划主管部门责令停止违法行为，依照前款规定处以罚款；造成损失的，依法承担赔偿责任。\n以欺骗手段取得资质证书承揽城乡规划编制工作的，由原发证机关吊销资质证书，依照本条第一款规定处以罚款；造成损失的，依法承担赔偿责任。\n第六十三条 城乡规划编制单位取得资质证书后，不再符合相应的资质条件的，由原发证机关责令限期改正；逾期不改正的，降低资质等级或者吊销资质证书。\n第六十四条 未取得建设工程规划许可证或者未按照建设工程规划许可证的规定进行建设的，由县级以上地方人民政府城乡规划主管部门责令停止建设；尚可采取改正措施消除对规划实施的影响的，限期改正，处建设工程造价百分之五以上百分之十以下的罚款；无法采取改正措施消除影响的，限期拆除，不能拆除的，没收实物或者违法收入，可以并处建设工程造价百分之十以下的罚款。\n第六十五条 在乡、村庄规划区内未依法取得乡村建设规划许可证或者未按照乡村建设规划许可证的规定进行建设的，由乡、镇人民政府责令停止建设、限期改正；逾期不改正的，可以拆除。\n第六十六条 建设单位或者个人有下列行为之一的，由所在地城市、县人民政府城乡规划主管部门责令限期拆除，可以并处临时建设工程造价一倍以下的罚款：\n（一）未经批准进行临时建设的；\n（二）未按照批准内容进行临时建设的；\n（三）临时建筑物、构筑物超过批准期限不拆除的。\n第六十七条 建设单位未在建设工程竣工验收后六个月内向城乡规划主管部门报送有关竣工验收资料的，由所在地城市、县人民政府城乡规划主管部门责令限期补报；逾期不补报的，处一万元以上五万元以下的罚款。\n第六十八条 城乡规划主管部门作出责令停止建设或者限期拆除的决定后，当事人不停止建设或者逾期不拆除的，建设工程所在地县级以上地方人民政府可以责成有关部门采取查封施工现场、强制拆除等措施。\n第六十九条 违反本法规定，构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附 则","text":"第七十条 本法自2008年1月1日起施行。《中华人民共和国城市规划法》同时废止。","level":1}]},{"id":"n0285","sections":[{"name":"","text":"中华人民共和国电子签名法\n（2004年8月28日第十届全国人民代表大会常务委员会第十一次会议通过 根据2015年4月24日第十二届全国人民代表大会常务委员会第十四次会议《关于修改〈中华人民共和国电力法〉等六部法律的决定》第一次修正 根据2019年4月23日第十三届全国人民代表大会常务委员会第十次会议《关于修改〈中华人民共和国建筑法〉等八部法律的决定》第二次修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了规范电子签名行为，确立电子签名的法律效力，维护有关各方的合法权益，制定本法。\n第二条 本法所称电子签名，是指数据电文中以电子形式所含、所附用于识别签名人身份并表明签名人认可其中内容的数据。\n本法所称数据电文，是指以电子、光学、磁或者类似手段生成、发送、接收或者储存的信息。\n第三条 民事活动中的合同或者其他文件、单证等文书，当事人可以约定使用或者不使用电子签名、数据电文。\n当事人约定使用电子签名、数据电文的文书，不得仅因为其采用电子签名、数据电文的形式而否定其法律效力。\n前款规定不适用下列文书：\n（一）涉及婚姻、收养、继承等人身关系的；\n（二）涉及停止供水、供热、供气等公用事业服务的；\n（三）法律、行政法规规定的不适用电子文书的其他情形。","level":1},{"name":"第二章 数据电文","text":"第四条 能够有形地表现所载内容，并可以随时调取查用的数据电文，视为符合法律、法规要求的书面形式。\n第五条 符合下列条件的数据电文，视为满足法律、法规规定的原件形式要求：\n（一）能够有效地表现所载内容并可供随时调取查用；\n（二）能够可靠地保证自最终形成时起，内容保持完整、未被更改。但是，在数据电文上增加背书以及数据交换、储存和显示过程中发生的形式变化不影响数据电文的完整性。\n第六条 符合下列条件的数据电文，视为满足法律、法规规定的文件保存要求：\n（一）能够有效地表现所载内容并可供随时调取查用；\n（二）数据电文的格式与其生成、发送或者接收时的格式相同，或者格式不相同但是能够准确表现原来生成、发送或者接收的内容；\n（三）能够识别数据电文的发件人、收件人以及发送、接收的时间。\n第七条 数据电文不得仅因为其是以电子、光学、磁或者类似手段生成、发送、接收或者储存的而被拒绝作为证据使用。\n第八条 审查数据电文作为证据的真实性，应当考虑以下因素：\n（一）生成、储存或者传递数据电文方法的可靠性；\n（二）保持内容完整性方法的可靠性；\n（三）用以鉴别发件人方法的可靠性；\n（四）其他相关因素。\n第九条 数据电文有下列情形之一的，视为发件人发送：\n（一）经发件人授权发送的；\n（二）发件人的信息系统自动发送的；\n（三）收件人按照发件人认可的方法对数据电文进行验证后结果相符的。\n当事人对前款规定的事项另有约定的，从其约定。\n第十条 法律、行政法规规定或者当事人约定数据电文需要确认收讫的，应当确认收讫。发件人收到收件人的收讫确认时，数据电文视为已经收到。\n第十一条 数据电文进入发件人控制之外的某个信息系统的时间，视为该数据电文的发送时间。\n收件人指定特定系统接收数据电文的，数据电文进入该特定系统的时间，视为该数据电文的接收时间；未指定特定系统的，数据电文进入收件人的任何系统的首次时间，视为该数据电文的接收时间。\n当事人对数据电文的发送时间、接收时间另有约定的，从其约定。\n第十二条 发件人的主营业地为数据电文的发送地点，收件人的主营业地为数据电文的接收地点。没有主营业地的，其经常居住地为发送或者接收地点。\n当事人对数据电文的发送地点、接收地点另有约定的，从其约定。","level":1},{"name":"第三章 电子签名与认证","text":"第十三条 电子签名同时符合下列条件的，视为可靠的电子签名：\n（一）电子签名制作数据用于电子签名时，属于电子签名人专有；\n（二）签署时电子签名制作数据仅由电子签名人控制；\n（三）签署后对电子签名的任何改动能够被发现；\n（四）签署后对数据电文内容和形式的任何改动能够被发现。\n当事人也可以选择使用符合其约定的可靠条件的电子签名。\n第十四条 可靠的电子签名与手写签名或者盖章具有同等的法律效力。\n第十五条 电子签名人应当妥善保管电子签名制作数据。电子签名人知悉电子签名制作数据已经失密或者可能已经失密时，应当及时告知有关各方，并终止使用该电子签名制作数据。\n第十六条 电子签名需要第三方认证的，由依法设立的电子认证服务提供者提供认证服务。\n第十七条 提供电子认证服务，应当具备下列条件：\n（一）取得企业法人资格；\n（二）具有与提供电子认证服务相适应的专业技术人员和管理人员；\n（三）具有与提供电子认证服务相适应的资金和经营场所；\n（四）具有符合国家安全标准的技术和设备；\n（五）具有国家密码管理机构同意使用密码的证明文件；\n（六）法律、行政法规规定的其他条件。\n第十八条 从事电子认证服务，应当向国务院信息产业主管部门提出申请，并提交符合本法第十七条规定条件的相关材料。国务院信息产业主管部门接到申请后经依法审查，征求国务院商务主管部门等有关部门的意见后，自接到申请之日起四十五日内作出许可或者不予许可的决定。予以许可的，颁发电子认证许可证书；不予许可的，应当书面通知申请人并告知理由。\n取得认证资格的电子认证服务提供者，应当按照国务院信息产业主管部门的规定在互联网上公布其名称、许可证号等信息。\n第十九条 电子认证服务提供者应当制定、公布符合国家有关规定的电子认证业务规则，并向国务院信息产业主管部门备案。\n电子认证业务规则应当包括责任范围、作业操作规范、信息安全保障措施等事项。\n第二十条 电子签名人向电子认证服务提供者申请电子签名认证证书，应当提供真实、完整和准确的信息。\n电子认证服务提供者收到电子签名认证证书申请后，应当对申请人的身份进行查验，并对有关材料进行审查。\n第二十一条 电子认证服务提供者签发的电子签名认证证书应当准确无误，并应当载明下列内容：\n（一）电子认证服务提供者名称；\n（二）证书持有人名称；\n（三）证书序列号；\n（四）证书有效期；\n（五）证书持有人的电子签名验证数据；\n（六）电子认证服务提供者的电子签名；\n（七）国务院信息产业主管部门规定的其他内容。\n第二十二条 电子认证服务提供者应当保证电子签名认证证书内容在有效期内完整、准确，并保证电子签名依赖方能够证实或者了解电子签名认证证书所载内容及其他有关事项。\n第二十三条 电子认证服务提供者拟暂停或者终止电子认证服务的，应当在暂停或者终止服务九十日前，就业务承接及其他有关事项通知有关各方。\n电子认证服务提供者拟暂停或者终止电子认证服务的，应当在暂停或者终止服务六十日前向国务院信息产业主管部门报告，并与其他电子认证服务提供者就业务承接进行协商，作出妥善安排。\n电子认证服务提供者未能就业务承接事项与其他电子认证服务提供者达成协议的，应当申请国务院信息产业主管部门安排其他电子认证服务提供者承接其业务。\n电子认证服务提供者被依法吊销电子认证许可证书的，其业务承接事项的处理按照国务院信息产业主管部门的规定执行。\n第二十四条 电子认证服务提供者应当妥善保存与认证相关的信息，信息保存期限至少为电子签名认证证书失效后五年。\n第二十五条 国务院信息产业主管部门依照本法制定电子认证服务业的具体管理办法，对电子认证服务提供者依法实施监督管理。\n第二十六条 经国务院信息产业主管部门根据有关协议或者对等原则核准后，中华人民共和国境外的电子认证服务提供者在境外签发的电子签名认证证书与依照本法设立的电子认证服务提供者签发的电子签名认证证书具有同等的法律效力。","level":1},{"name":"第四章 法律责任","text":"第二十七条 电子签名人知悉电子签名制作数据已经失密或者可能已经失密未及时告知有关各方、并终止使用电子签名制作数据，未向电子认证服务提供者提供真实、完整和准确的信息，或者有其他过错，给电子签名依赖方、电子认证服务提供者造成损失的，承担赔偿责任。\n第二十八条 电子签名人或者电子签名依赖方因依据电子认证服务提供者提供的电子签名认证服务从事民事活动遭受损失，电子认证服务提供者不能证明自己无过错的，承担赔偿责任。\n第二十九条 未经许可提供电子认证服务的，由国务院信息产业主管部门责令停止违法行为；有违法所得的，没收违法所得；违法所得三十万元以上的，处违法所得一倍以上三倍以下的罚款；没有违法所得或者违法所得不足三十万元的，处十万元以上三十万元以下的罚款。\n第三十条 电子认证服务提供者暂停或者终止电子认证服务，未在暂停或者终止服务六十日前向国务院信息产业主管部门报告的，由国务院信息产业主管部门对其直接负责的主管人员处一万元以上五万元以下的罚款。\n第三十一条 电子认证服务提供者不遵守认证业务规则、未妥善保存与认证相关的信息，或者有其他违法行为的，由国务院信息产业主管部门责令限期改正；逾期未改正的，吊销电子认证许可证书，其直接负责的主管人员和其他直接责任人员十年内不得从事电子认证服务。吊销电子认证许可证书的，应当予以公告并通知工商行政管理部门。\n第三十二条 伪造、冒用、盗用他人的电子签名，构成犯罪的，依法追究刑事责任；给他人造成损失的，依法承担民事责任。\n第三十三条 依照本法负责电子认证服务业监督管理工作的部门的工作人员，不依法履行行政许可、监督管理职责的，依法给予行政处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第五章 附 则","text":"第三十四条 本法中下列用语的含义：\n（一）电子签名人，是指持有电子签名制作数据并以本人身份或者以其所代表的人的名义实施电子签名的人；\n（二）电子签名依赖方，是指基于对电子签名认证证书或者电子签名的信赖从事有关活动的人；\n（三）电子签名认证证书，是指可证实电子签名人与电子签名制作数据有联系的数据电文或者其他电子记录；\n（四）电子签名制作数据，是指在电子签名过程中使用的，将电子签名与电子签名人可靠地联系起来的字符、编码等数据；\n（五）电子签名验证数据，是指用于验证电子签名的数据，包括代码、口令、算法或者公钥等。\n第三十五条 国务院或者国务院规定的部门可以依据本法制定政务活动和其他社会活动中使用电子签名、数据电文的具体办法。\n第三十六条 本法自2005年4月1日起施行。","level":1}]},{"id":"n0286","sections":[{"name":"","text":"中华人民共和国法官法\n（1995年2月28日第八届全国人民代表大会常务委员会第十二次会议通过 根据2001年6月30日第九届全国人民代表大会常务委员会第二十二次会议《关于修改〈中华人民共和国法官法〉的决定》第一次修正 根据2017年9月1日第十二届全国人民代表大会常务委员会第二十九次会议《关于修改〈中华人民共和国法官法〉等八部法律的决定》第二次修正 2019年4月23日第十三届全国人民代表大会常务委员会第十次会议修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了全面推进高素质法官队伍建设，加强对法官的管理和监督，维护法官合法权益，保障人民法院依法独立行使审判权，保障法官依法履行职责，保障司法公正，根据宪法，制定本法。\n第二条 法官是依法行使国家审判权的审判人员，包括最高人民法院、地方各级人民法院和军事法院等专门人民法院的院长、副院长、审判委员会委员、庭长、副庭长和审判员。\n第三条 法官必须忠实执行宪法和法律，维护社会公平正义，全心全意为人民服务。\n第四条 法官应当公正对待当事人和其他诉讼参与人，对一切个人和组织在适用法律上一律平等。\n第五条 法官应当勤勉尽责，清正廉明，恪守职业道德。\n第六条 法官审判案件，应当以事实为根据，以法律为准绳，秉持客观公正的立场。\n第七条 法官依法履行职责，受法律保护，不受行政机关、社会团体和个人的干涉。","level":1},{"name":"第二章 法官的职责、义务和权利","text":"第八条 法官的职责：\n（一）依法参加合议庭审判或者独任审判刑事、民事、行政诉讼以及国家赔偿等案件；\n（二）依法办理引渡、司法协助等案件；\n（三）法律规定的其他职责。\n法官在职权范围内对所办理的案件负责。\n第九条 人民法院院长、副院长、审判委员会委员、庭长、副庭长除履行审判职责外，还应当履行与其职务相适应的职责。\n第十条 法官应当履行下列义务：\n（一）严格遵守宪法和法律；\n（二）秉公办案，不得徇私枉法；\n（三）依法保障当事人和其他诉讼参与人的诉讼权利；\n（四）维护国家利益、社会公共利益，维护个人和组织的合法权益；\n（五）保守国家秘密和审判工作秘密，对履行职责中知悉的商业秘密和个人隐私予以保密；\n（六）依法接受法律监督和人民群众监督；\n（七）通过依法办理案件以案释法，增强全民法治观念，推进法治社会建设；\n（八）法律规定的其他义务。\n第十一条 法官享有下列权利：\n（一）履行法官职责应当具有的职权和工作条件；\n（二）非因法定事由、非经法定程序，不被调离、免职、降职、辞退或者处分；\n（三）履行法官职责应当享有的职业保障和福利待遇；\n（四）人身、财产和住所安全受法律保护；\n（五）提出申诉或者控告；\n（六）法律规定的其他权利。","level":1},{"name":"第三章 法官的条件和遴选","text":"第十二条 担任法官必须具备下列条件：\n（一）具有中华人民共和国国籍；\n（二）拥护中华人民共和国宪法，拥护中国共产党领导和社会主义制度；\n（三）具有良好的政治、业务素质和道德品行；\n（四）具有正常履行职责的身体条件；\n（五）具备普通高等学校法学类本科学历并获得学士及以上学位；或者普通高等学校非法学类本科及以上学历并获得法律硕士、法学硕士及以上学位；或者普通高等学校非法学类本科及以上学历，获得其他相应学位，并具有法律专业知识；\n（六）从事法律工作满五年。其中获得法律硕士、法学硕士学位，或者获得法学博士学位的，从事法律工作的年限可以分别放宽至四年、三年；\n（七）初任法官应当通过国家统一法律职业资格考试取得法律职业资格。\n适用前款第五项规定的学历条件确有困难的地方，经最高人民法院审核确定，在一定期限内，可以将担任法官的学历条件放宽为高等学校本科毕业。\n第十三条 下列人员不得担任法官：\n（一）因犯罪受过刑事处罚的；\n（二）被开除公职的；\n（三）被吊销律师、公证员执业证书或者被仲裁委员会除名的；\n（四）有法律规定的其他情形的。\n第十四条 初任法官采用考试、考核的办法，按照德才兼备的标准，从具备法官条件的人员中择优提出人选。\n人民法院的院长应当具有法学专业知识和法律职业经历。副院长、审判委员会委员应当从法官、检察官或者其他具备法官条件的人员中产生。\n第十五条 人民法院可以根据审判工作需要，从律师或者法学教学、研究人员等从事法律职业的人员中公开选拔法官。\n除应当具备法官任职条件外，参加公开选拔的律师应当实际执业不少于五年，执业经验丰富，从业声誉良好，参加公开选拔的法学教学、研究人员应当具有中级以上职称，从事教学、研究工作五年以上，有突出研究能力和相应研究成果。\n第十六条 省、自治区、直辖市设立法官遴选委员会，负责初任法官人选专业能力的审核。\n省级法官遴选委员会的组成人员应当包括地方各级人民法院法官代表、其他从事法律职业的人员和有关方面代表，其中法官代表不少于三分之一。\n省级法官遴选委员会的日常工作由高级人民法院的内设职能部门承担。\n遴选最高人民法院法官应当设立最高人民法院法官遴选委员会，负责法官人选专业能力的审核。\n第十七条 初任法官一般到基层人民法院任职。上级人民法院法官一般逐级遴选；最高人民法院和高级人民法院法官可以从下两级人民法院遴选。参加上级人民法院遴选的法官应当在下级人民法院担任法官一定年限，并具有遴选职位相关工作经历。","level":1},{"name":"第四章 法官的任免","text":"第十八条 法官的任免，依照宪法和法律规定的任免权限和程序办理。\n最高人民法院院长由全国人民代表大会选举和罢免，副院长、审判委员会委员、庭长、副庭长和审判员，由院长提请全国人民代表大会常务委员会任免。\n最高人民法院巡回法庭庭长、副庭长，由院长提请全国人民代表大会常务委员会任免。\n地方各级人民法院院长由本级人民代表大会选举和罢免，副院长、审判委员会委员、庭长、副庭长和审判员，由院长提请本级人民代表大会常务委员会任免。\n在省、自治区内按地区设立的和在直辖市内设立的中级人民法院的院长，由省、自治区、直辖市人民代表大会常务委员会根据主任会议的提名决定任免，副院长、审判委员会委员、庭长、副庭长和审判员，由高级人民法院院长提请省、自治区、直辖市人民代表大会常务委员会任免。\n新疆生产建设兵团各级人民法院、专门人民法院的院长、副院长、审判委员会委员、庭长、副庭长和审判员，依照全国人民代表大会常务委员会的有关规定任免。\n第十九条 法官在依照法定程序产生后，在就职时应当公开进行宪法宣誓。\n第二十条 法官有下列情形之一的，应当依法提请免除其法官职务：\n（一）丧失中华人民共和国国籍的；\n（二）调出所任职人民法院的；\n（三）职务变动不需要保留法官职务的，或者本人申请免除法官职务经批准的；\n（四）经考核不能胜任法官职务的；\n（五）因健康原因长期不能履行职务的；\n（六）退休的；\n（七）辞职或者依法应当予以辞退的；\n（八）因违纪违法不宜继续任职的。\n第二十一条 发现违反本法规定的条件任命法官的，任命机关应当撤销该项任命；上级人民法院发现下级人民法院法官的任命违反本法规定的条件的，应当建议下级人民法院依法提请任命机关撤销该项任命。\n第二十二条 法官不得兼任人民代表大会常务委员会的组成人员，不得兼任行政机关、监察机关、检察机关的职务，不得兼任企业或者其他营利性组织、事业单位的职务，不得兼任律师、仲裁员和公证员。\n第二十三条 法官之间有夫妻关系、直系血亲关系、三代以内旁系血亲以及近姻亲关系的，不得同时担任下列职务：\n（一）同一人民法院的院长、副院长、审判委员会委员、庭长、副庭长；\n（二）同一人民法院的院长、副院长和审判员；\n（三）同一审判庭的庭长、副庭长、审判员；\n（四）上下相邻两级人民法院的院长、副院长。\n第二十四条 法官的配偶、父母、子女有下列情形之一的，法官应当实行任职回避：\n（一）担任该法官所任职人民法院辖区内律师事务所的合伙人或者设立人的；\n（二）在该法官所任职人民法院辖区内以律师身份担任诉讼代理人、辩护人，或者为诉讼案件当事人提供其他有偿法律服务的。","level":1},{"name":"第五章 法官的管理","text":"第二十五条 法官实行员额制管理。法官员额根据案件数量、经济社会发展情况、人口数量和人民法院审级等因素确定，在省、自治区、直辖市内实行总量控制、动态管理，优先考虑基层人民法院和案件数量多的人民法院办案需要。\n法官员额出现空缺的，应当按照程序及时补充。\n最高人民法院法官员额由最高人民法院商有关部门确定。\n第二十六条 法官实行单独职务序列管理。\n法官等级分为十二级，依次为首席大法官、一级大法官、二级大法官、一级高级法官、二级高级法官、三级高级法官、四级高级法官、一级法官、二级法官、三级法官、四级法官、五级法官。\n第二十七条 最高人民法院院长为首席大法官。\n第二十八条 法官等级的确定，以法官德才表现、业务水平、审判工作实绩和工作年限等为依据。\n法官等级晋升采取按期晋升和择优选升相结合的方式，特别优秀或者工作特殊需要的一线办案岗位法官可以特别选升。\n第二十九条 法官的等级设置、确定和晋升的具体办法，由国家另行规定。\n第三十条 初任法官实行统一职前培训制度。\n第三十一条 对法官应当有计划地进行政治、理论和业务培训。\n法官的培训应当理论联系实际、按需施教、讲求实效。\n第三十二条 法官培训情况，作为法官任职、等级晋升的依据之一。\n第三十三条 法官培训机构按照有关规定承担培训法官的任务。\n第三十四条 法官申请辞职，应当由本人书面提出，经批准后，依照法律规定的程序免除其职务。\n第三十五条 辞退法官应当依照法律规定的程序免除其职务。\n辞退法官应当按照管理权限决定。辞退决定应当以书面形式通知被辞退的法官，并列明作出决定的理由和依据。\n第三十六条 法官从人民法院离任后两年内，不得以律师身份担任诉讼代理人或者辩护人。\n法官从人民法院离任后，不得担任原任职法院办理案件的诉讼代理人或者辩护人，但是作为当事人的监护人或者近亲属代理诉讼或者进行辩护的除外。\n法官被开除后，不得担任诉讼代理人或者辩护人，但是作为当事人的监护人或者近亲属代理诉讼或者进行辩护的除外。\n第三十七条 法官因工作需要，经单位选派或者批准，可以在高等学校、科研院所协助开展实践性教学、研究工作，并遵守国家有关规定。","level":1},{"name":"第六章 法官的考核、奖励和惩戒","text":"第三十八条 人民法院设立法官考评委员会，负责对本院法官的考核工作。\n第三十九条 法官考评委员会的组成人员为五至九人。\n法官考评委员会主任由本院院长担任。\n第四十条 对法官的考核，应当全面、客观、公正，实行平时考核和年度考核相结合。\n第四十一条 对法官的考核内容包括：审判工作实绩、职业道德、专业水平、工作能力、审判作风。重点考核审判工作实绩。\n第四十二条 年度考核结果分为优秀、称职、基本称职和不称职四个等次。\n考核结果作为调整法官等级、工资以及法官奖惩、免职、降职、辞退的依据。\n第四十三条 考核结果以书面形式通知法官本人。法官对考核结果如果有异议，可以申请复核。\n第四十四条 法官在审判工作中有显著成绩和贡献的，或者有其他突出事迹的，应当给予奖励。\n第四十五条 法官有下列表现之一的，应当给予奖励：\n（一）公正司法，成绩显著的；\n（二）总结审判实践经验成果突出，对审判工作有指导作用的；\n（三）在办理重大案件、处理突发事件和承担专项重要工作中，做出显著成绩和贡献的；\n（四）对审判工作提出改革建议被采纳，效果显著的；\n（五）提出司法建议被采纳或者开展法治宣传、指导调解组织调解各类纠纷，效果显著的；\n（六）有其他功绩的。\n法官的奖励按照有关规定办理。\n第四十六条 法官有下列行为之一的，应当给予处分；构成犯罪的，依法追究刑事责任：\n（一）贪污受贿、徇私舞弊、枉法裁判的；\n（二）隐瞒、伪造、变造、故意损毁证据、案件材料的；\n（三）泄露国家秘密、审判工作秘密、商业秘密或者个人隐私的；\n（四）故意违反法律法规办理案件的；\n（五）因重大过失导致裁判结果错误并造成严重后果的；\n（六）拖延办案，贻误工作的；\n（七）利用职权为自己或者他人谋取私利的；\n（八）接受当事人及其代理人利益输送，或者违反有关规定会见当事人及其代理人的；\n（九）违反有关规定从事或者参与营利性活动，在企业或者其他营利性组织中兼任职务的；\n（十）有其他违纪违法行为的。\n法官的处分按照有关规定办理。\n第四十七条 法官涉嫌违纪违法，已经被立案调查、侦查，不宜继续履行职责的，按照管理权限和规定的程序暂时停止其履行职务。\n第四十八条 最高人民法院和省、自治区、直辖市设立法官惩戒委员会，负责从专业角度审查认定法官是否存在本法第四十六条第四项、第五项规定的违反审判职责的行为，提出构成故意违反职责、存在重大过失、存在一般过失或者没有违反职责等审查意见。法官惩戒委员会提出审查意见后，人民法院依照有关规定作出是否予以惩戒的决定，并给予相应处理。\n法官惩戒委员会由法官代表、其他从事法律职业的人员和有关方面代表组成，其中法官代表不少于半数。\n最高人民法院法官惩戒委员会、省级法官惩戒委员会的日常工作，由相关人民法院的内设职能部门承担。\n第四十九条 法官惩戒委员会审议惩戒事项时，当事法官有权申请有关人员回避，有权进行陈述、举证、辩解。\n第五十条 法官惩戒委员会作出的审查意见应当送达当事法官。当事法官对审查意见有异议的，可以向惩戒委员会提出，惩戒委员会应当对异议及其理由进行审查，作出决定。\n第五十一条 法官惩戒委员会审议惩戒事项的具体程序，由最高人民法院商有关部门确定。","level":1},{"name":"第七章 法官的职业保障","text":"第五十二条 人民法院设立法官权益保障委员会，维护法官合法权益，保障法官依法履行职责。\n第五十三条 除下列情形外，不得将法官调离审判岗位：\n（一）按规定需要任职回避的；\n（二）按规定实行任职交流的；\n（三）因机构调整、撤销、合并或者缩减编制员额需要调整工作的；\n（四）因违纪违法不适合在审判岗位工作的；\n（五）法律规定的其他情形。\n第五十四条 任何单位或者个人不得要求法官从事超出法定职责范围的事务。\n对任何干涉法官办理案件的行为，法官有权拒绝并予以全面如实记录和报告；有违纪违法情形的，由有关机关根据情节轻重追究有关责任人员、行为人的责任。\n第五十五条 法官的职业尊严和人身安全受法律保护。\n任何单位和个人不得对法官及其近亲属打击报复。\n对法官及其近亲属实施报复陷害、侮辱诽谤、暴力侵害、威胁恐吓、滋事骚扰等违法犯罪行为的，应当依法从严惩治。\n第五十六条 法官因依法履行职责遭受不实举报、诬告陷害、侮辱诽谤，致使名誉受到损害的，人民法院应当会同有关部门及时澄清事实，消除不良影响，并依法追究相关单位或者个人的责任。\n第五十七条 法官因依法履行职责，本人及其近亲属人身安全面临危险的，人民法院、公安机关应当对法官及其近亲属采取人身保护、禁止特定人员接触等必要保护措施。\n第五十八条 法官实行与其职责相适应的工资制度，按照法官等级享有国家规定的工资待遇，并建立与公务员工资同步调整机制。\n法官的工资制度，根据审判工作特点，由国家另行规定。\n第五十九条 法官实行定期增资制度。\n经年度考核确定为优秀、称职的，可以按照规定晋升工资档次。\n第六十条 法官享受国家规定的津贴、补贴、奖金、保险和福利待遇。\n第六十一条 法官因公致残的，享受国家规定的伤残待遇。法官因公牺牲、因公死亡或者病故的，其亲属享受国家规定的抚恤和优待。\n第六十二条 法官的退休制度，根据审判工作特点，由国家另行规定。\n第六十三条 法官退休后，享受国家规定的养老金和其他待遇。\n第六十四条 对于国家机关及其工作人员侵犯本法第十一条规定的法官权利的行为，法官有权提出控告。\n第六十五条 对法官处分或者人事处理错误的，应当及时予以纠正；造成名誉损害的，应当恢复名誉、消除影响、赔礼道歉；造成经济损失的，应当赔偿。对打击报复的直接责任人员，应当依法追究其责任。","level":1},{"name":"第八章 附 则","text":"第六十六条 国家对初任法官实行统一法律职业资格考试制度，由国务院司法行政部门商最高人民法院等有关部门组织实施。\n第六十七条 人民法院的法官助理在法官指导下负责审查案件材料、草拟法律文书等审判辅助事务。\n人民法院应当加强法官助理队伍建设，为法官遴选储备人才。\n第六十八条 有关法官的权利、义务和管理制度，本法已有规定的，适用本法的规定；本法未作规定的，适用公务员管理的相关法律法规。\n第六十九条 本法自2019年10月1日起施行。","level":1}]},{"id":"n0287","sections":[{"name":"","text":"中华人民共和国行政许可法\n（2003年8月27日第十届全国人民代表大会常务委员会第四次会议通过 根据2019年4月23日第十三届全国人民代表大会常务委员会第十次会议《关于修改〈中华人民共和国建筑法〉等八部法律的决定》修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了规范行政许可的设定和实施，保护公民、法人和其他组织的合法权益，维护公共利益和社会秩序，保障和监督行政机关有效实施行政管理，根据宪法，制定本法。\n第二条 本法所称行政许可，是指行政机关根据公民、法人或者其他组织的申请，经依法审查，准予其从事特定活动的行为。\n第三条 行政许可的设定和实施，适用本法。\n有关行政机关对其他机关或者对其直接管理的事业单位的人事、财务、外事等事项的审批，不适用本法。\n第四条 设定和实施行政许可，应当依照法定的权限、范围、条件和程序。\n第五条 设定和实施行政许可，应当遵循公开、公平、公正、非歧视的原则。\n有关行政许可的规定应当公布；未经公布的，不得作为实施行政许可的依据。行政许可的实施和结果，除涉及国家秘密、商业秘密或者个人隐私的外，应当公开。未经申请人同意，行政机关及其工作人员、参与专家评审等的人员不得披露申请人提交的商业秘密、未披露信息或者保密商务信息，法律另有规定或者涉及国家安全、重大社会公共利益的除外；行政机关依法公开申请人前述信息的，允许申请人在合理期限内提出异议。\n符合法定条件、标准的，申请人有依法取得行政许可的平等权利，行政机关不得歧视任何人。\n第六条 实施行政许可，应当遵循便民的原则，提高办事效率，提供优质服务。\n第七条 公民、法人或者其他组织对行政机关实施行政许可，享有陈述权、申辩权；有权依法申请行政复议或者提起行政诉讼；其合法权益因行政机关违法实施行政许可受到损害的，有权依法要求赔偿。\n第八条 公民、法人或者其他组织依法取得的行政许可受法律保护，行政机关不得擅自改变已经生效的行政许可。\n行政许可所依据的法律、法规、规章修改或者废止，或者准予行政许可所依据的客观情况发生重大变化的，为了公共利益的需要，行政机关可以依法变更或者撤回已经生效的行政许可。由此给公民、法人或者其他组织造成财产损失的，行政机关应当依法给予补偿。\n第九条 依法取得的行政许可，除法律、法规规定依照法定条件和程序可以转让的外，不得转让。\n第十条 县级以上人民政府应当建立健全对行政机关实施行政许可的监督制度，加强对行政机关实施行政许可的监督检查。\n行政机关应当对公民、法人或者其他组织从事行政许可事项的活动实施有效监督。","level":1},{"name":"第二章 行政许可的设定","text":"第十一条 设定行政许可，应当遵循经济和社会发展规律，有利于发挥公民、法人或者其他组织的积极性、主动性，维护公共利益和社会秩序，促进经济、社会和生态环境协调发展。\n第十二条 下列事项可以设定行政许可：\n（一）直接涉及国家安全、公共安全、经济宏观调控、生态环境保护以及直接关系人身健康、生命财产安全等特定活动，需要按照法定条件予以批准的事项；\n（二）有限自然资源开发利用、公共资源配置以及直接关系公共利益的特定行业的市场准入等，需要赋予特定权利的事项；\n（三）提供公众服务并且直接关系公共利益的职业、行业，需要确定具备特殊信誉、特殊条件或者特殊技能等资格、资质的事项；\n（四）直接关系公共安全、人身健康、生命财产安全的重要设备、设施、产品、物品，需要按照技术标准、技术规范，通过检验、检测、检疫等方式进行审定的事项；\n（五）企业或者其他组织的设立等，需要确定主体资格的事项；\n（六）法律、行政法规规定可以设定行政许可的其他事项。\n第十三条 本法第十二条所列事项，通过下列方式能够予以规范的，可以不设行政许可：\n（一）公民、法人或者其他组织能够自主决定的；\n（二）市场竞争机制能够有效调节的；\n（三）行业组织或者中介机构能够自律管理的；\n（四）行政机关采用事后监督等其他行政管理方式能够解决的。\n第十四条 本法第十二条所列事项，法律可以设定行政许可。尚未制定法律的，行政法规可以设定行政许可。\n必要时，国务院可以采用发布决定的方式设定行政许可。实施后，除临时性行政许可事项外，国务院应当及时提请全国人民代表大会及其常务委员会制定法律，或者自行制定行政法规。\n第十五条 本法第十二条所列事项，尚未制定法律、行政法规的，地方性法规可以设定行政许可；尚未制定法律、行政法规和地方性法规的，因行政管理的需要，确需立即实施行政许可的，省、自治区、直辖市人民政府规章可以设定临时性的行政许可。临时性的行政许可实施满一年需要继续实施的，应当提请本级人民代表大会及其常务委员会制定地方性法规。\n地方性法规和省、自治区、直辖市人民政府规章，不得设定应当由国家统一确定的公民、法人或者其他组织的资格、资质的行政许可；不得设定企业或者其他组织的设立登记及其前置性行政许可。其设定的行政许可，不得限制其他地区的个人或者企业到本地区从事生产经营和提供服务，不得限制其他地区的商品进入本地区市场。\n第十六条 行政法规可以在法律设定的行政许可事项范围内，对实施该行政许可作出具体规定。\n地方性法规可以在法律、行政法规设定的行政许可事项范围内，对实施该行政许可作出具体规定。\n规章可以在上位法设定的行政许可事项范围内，对实施该行政许可作出具体规定。\n法规、规章对实施上位法设定的行政许可作出的具体规定，不得增设行政许可；对行政许可条件作出的具体规定，不得增设违反上位法的其他条件。\n第十七条 除本法第十四条、第十五条规定的外，其他规范性文件一律不得设定行政许可。\n第十八条 设定行政许可，应当规定行政许可的实施机关、条件、程序、期限。\n第十九条 起草法律草案、法规草案和省、自治区、直辖市人民政府规章草案，拟设定行政许可的，起草单位应当采取听证会、论证会等形式听取意见，并向制定机关说明设定该行政许可的必要性、对经济和社会可能产生的影响以及听取和采纳意见的情况。\n第二十条 行政许可的设定机关应当定期对其设定的行政许可进行评价；对已设定的行政许可，认为通过本法第十三条所列方式能够解决的，应当对设定该行政许可的规定及时予以修改或者废止。\n行政许可的实施机关可以对已设定的行政许可的实施情况及存在的必要性适时进行评价，并将意见报告该行政许可的设定机关。\n公民、法人或者其他组织可以向行政许可的设定机关和实施机关就行政许可的设定和实施提出意见和建议。\n第二十一条 省、自治区、直辖市人民政府对行政法规设定的有关经济事务的行政许可，根据本行政区域经济和社会发展情况，认为通过本法第十三条所列方式能够解决的，报国务院批准后，可以在本行政区域内停止实施该行政许可。","level":1},{"name":"第三章 行政许可的实施机关","text":"第二十二条 行政许可由具有行政许可权的行政机关在其法定职权范围内实施。\n第二十三条 法律、法规授权的具有管理公共事务职能的组织，在法定授权范围内，以自己的名义实施行政许可。被授权的组织适用本法有关行政机关的规定。\n第二十四条 行政机关在其法定职权范围内，依照法律、法规、规章的规定，可以委托其他行政机关实施行政许可。委托机关应当将受委托行政机关和受委托实施行政许可的内容予以公告。\n委托行政机关对受委托行政机关实施行政许可的行为应当负责监督，并对该行为的后果承担法律责任。\n受委托行政机关在委托范围内，以委托行政机关名义实施行政许可；不得再委托其他组织或者个人实施行政许可。\n第二十五条 经国务院批准，省、自治区、直辖市人民政府根据精简、统一、效能的原则，可以决定一个行政机关行使有关行政机关的行政许可权。\n第二十六条 行政许可需要行政机关内设的多个机构办理的，该行政机关应当确定一个机构统一受理行政许可申请，统一送达行政许可决定。\n行政许可依法由地方人民政府两个以上部门分别实施的，本级人民政府可以确定一个部门受理行政许可申请并转告有关部门分别提出意见后统一办理，或者组织有关部门联合办理、集中办理。\n第二十七条 行政机关实施行政许可，不得向申请人提出购买指定商品、接受有偿服务等不正当要求。\n行政机关工作人员办理行政许可，不得索取或者收受申请人的财物，不得谋取其他利益。\n第二十八条 对直接关系公共安全、人身健康、生命财产安全的设备、设施、产品、物品的检验、检测、检疫，除法律、行政法规规定由行政机关实施的外，应当逐步由符合法定条件的专业技术组织实施。专业技术组织及其有关人员对所实施的检验、检测、检疫结论承担法律责任。","level":1},{"name":"第四章 行政许可的实施程序","text":"","level":1},{"name":"第一节 申请与受理","text":"第二十九条 公民、法人或者其他组织从事特定活动，依法需要取得行政许可的，应当向行政机关提出申请。申请书需要采用格式文本的，行政机关应当向申请人提供行政许可申请书格式文本。申请书格式文本中不得包含与申请行政许可事项没有直接关系的内容。\n申请人可以委托代理人提出行政许可申请。但是，依法应当由申请人到行政机关办公场所提出行政许可申请的除外。\n行政许可申请可以通过信函、电报、电传、传真、电子数据交换和电子邮件等方式提出。\n第三十条 行政机关应当将法律、法规、规章规定的有关行政许可的事项、依据、条件、数量、程序、期限以及需要提交的全部材料的目录和申请书示范文本等在办公场所公示。\n申请人要求行政机关对公示内容予以说明、解释的，行政机关应当说明、解释，提供准确、可靠的信息。\n第三十一条 申请人申请行政许可，应当如实向行政机关提交有关材料和反映真实情况，并对其申请材料实质内容的真实性负责。行政机关不得要求申请人提交与其申请的行政许可事项无关的技术资料和其他材料。\n行政机关及其工作人员不得以转让技术作为取得行政许可的条件；不得在实施行政许可的过程中，直接或者间接地要求转让技术。\n第三十二条 行政机关对申请人提出的行政许可申请，应当根据下列情况分别作出处理：\n（一）申请事项依法不需要取得行政许可的，应当即时告知申请人不受理；\n（二）申请事项依法不属于本行政机关职权范围的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请；\n（三）申请材料存在可以当场更正的错误的，应当允许申请人当场更正；\n（四）申请材料不齐全或者不符合法定形式的，应当当场或者在五日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理；\n（五）申请事项属于本行政机关职权范围，申请材料齐全、符合法定形式，或者申请人按照本行政机关的要求提交全部补正申请材料的，应当受理行政许可申请。\n行政机关受理或者不予受理行政许可申请，应当出具加盖本行政机关专用印章和注明日期的书面凭证。\n第三十三条 行政机关应当建立和完善有关制度，推行电子政务，在行政机关的网站上公布行政许可事项，方便申请人采取数据电文等方式提出行政许可申请；应当与其他行政机关共享有关行政许可信息，提高办事效率。","level":2},{"name":"第二节 审查与决定","text":"第三十四条 行政机关应当对申请人提交的申请材料进行审查。\n申请人提交的申请材料齐全、符合法定形式，行政机关能够当场作出决定的，应当当场作出书面的行政许可决定。\n根据法定条件和程序，需要对申请材料的实质内容进行核实的，行政机关应当指派两名以上工作人员进行核查。\n第三十五条 依法应当先经下级行政机关审查后报上级行政机关决定的行政许可，下级行政机关应当在法定期限内将初步审查意见和全部申请材料直接报送上级行政机关。上级行政机关不得要求申请人重复提供申请材料。\n第三十六条 行政机关对行政许可申请进行审查时，发现行政许可事项直接关系他人重大利益的，应当告知该利害关系人。申请人、利害关系人有权进行陈述和申辩。行政机关应当听取申请人、利害关系人的意见。\n第三十七条 行政机关对行政许可申请进行审查后，除当场作出行政许可决定的外，应当在法定期限内按照规定程序作出行政许可决定。\n第三十八条 申请人的申请符合法定条件、标准的，行政机关应当依法作出准予行政许可的书面决定。\n行政机关依法作出不予行政许可的书面决定的，应当说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。\n第三十九条 行政机关作出准予行政许可的决定，需要颁发行政许可证件的，应当向申请人颁发加盖本行政机关印章的下列行政许可证件：\n（一）许可证、执照或者其他许可证书；\n（二）资格证、资质证或者其他合格证书；\n（三）行政机关的批准文件或者证明文件；\n（四）法律、法规规定的其他行政许可证件。\n行政机关实施检验、检测、检疫的，可以在检验、检测、检疫合格的设备、设施、产品、物品上加贴标签或者加盖检验、检测、检疫印章。\n第四十条 行政机关作出的准予行政许可决定，应当予以公开，公众有权查阅。\n第四十一条 法律、行政法规设定的行政许可，其适用范围没有地域限制的，申请人取得的行政许可在全国范围内有效。","level":2},{"name":"第三节 期 限","text":"第四十二条 除可以当场作出行政许可决定的外，行政机关应当自受理行政许可申请之日起二十日内作出行政许可决定。二十日内不能作出决定的，经本行政机关负责人批准，可以延长十日，并应当将延长期限的理由告知申请人。但是，法律、法规另有规定的，依照其规定。\n依照本法第二十六条的规定，行政许可采取统一办理或者联合办理、集中办理的，办理的时间不得超过四十五日；四十五日内不能办结的，经本级人民政府负责人批准，可以延长十五日，并应当将延长期限的理由告知申请人。\n第四十三条 依法应当先经下级行政机关审查后报上级行政机关决定的行政许可，下级行政机关应当自其受理行政许可申请之日起二十日内审查完毕。但是，法律、法规另有规定的，依照其规定。\n第四十四条 行政机关作出准予行政许可的决定，应当自作出决定之日起十日内向申请人颁发、送达行政许可证件，或者加贴标签、加盖检验、检测、检疫印章。\n第四十五条 行政机关作出行政许可决定，依法需要听证、招标、拍卖、检验、检测、检疫、鉴定和专家评审的，所需时间不计算在本节规定的期限内。行政机关应当将所需时间书面告知申请人。","level":2},{"name":"第四节 听 证","text":"第四十六条 法律、法规、规章规定实施行政许可应当听证的事项，或者行政机关认为需要听证的其他涉及公共利益的重大行政许可事项，行政机关应当向社会公告，并举行听证。\n第四十七条 行政许可直接涉及申请人与他人之间重大利益关系的，行政机关在作出行政许可决定前，应当告知申请人、利害关系人享有要求听证的权利；申请人、利害关系人在被告知听证权利之日起五日内提出听证申请的，行政机关应当在二十日内组织听证。\n申请人、利害关系人不承担行政机关组织听证的费用。\n第四十八条 听证按照下列程序进行：\n（一）行政机关应当于举行听证的七日前将举行听证的时间、地点通知申请人、利害关系人，必要时予以公告；\n（二）听证应当公开举行；\n（三）行政机关应当指定审查该行政许可申请的工作人员以外的人员为听证主持人，申请人、利害关系人认为主持人与该行政许可事项有直接利害关系的，有权申请回避；\n（四）举行听证时，审查该行政许可申请的工作人员应当提供审查意见的证据、理由，申请人、利害关系人可以提出证据，并进行申辩和质证；\n（五）听证应当制作笔录，听证笔录应当交听证参加人确认无误后签字或者盖章。\n行政机关应当根据听证笔录，作出行政许可决定。","level":2},{"name":"第五节 变更与延续","text":"第四十九条 被许可人要求变更行政许可事项的，应当向作出行政许可决定的行政机关提出申请；符合法定条件、标准的，行政机关应当依法办理变更手续。\n第五十条 被许可人需要延续依法取得的行政许可的有效期的，应当在该行政许可有效期届满三十日前向作出行政许可决定的行政机关提出申请。但是，法律、法规、规章另有规定的，依照其规定。\n行政机关应当根据被许可人的申请，在该行政许可有效期届满前作出是否准予延续的决定；逾期未作决定的，视为准予延续。","level":2},{"name":"第六节 特别规定","text":"第五十一条 实施行政许可的程序，本节有规定的，适用本节规定；本节没有规定的，适用本章其他有关规定。\n第五十二条 国务院实施行政许可的程序，适用有关法律、行政法规的规定。\n第五十三条 实施本法第十二条第二项所列事项的行政许可的，行政机关应当通过招标、拍卖等公平竞争的方式作出决定。但是，法律、行政法规另有规定的，依照其规定。\n行政机关通过招标、拍卖等方式作出行政许可决定的具体程序，依照有关法律、行政法规的规定。\n行政机关按照招标、拍卖程序确定中标人、买受人后，应当作出准予行政许可的决定，并依法向中标人、买受人颁发行政许可证件。\n行政机关违反本条规定，不采用招标、拍卖方式，或者违反招标、拍卖程序，损害申请人合法权益的，申请人可以依法申请行政复议或者提起行政诉讼。\n第五十四条 实施本法第十二条第三项所列事项的行政许可，赋予公民特定资格，依法应当举行国家考试的，行政机关根据考试成绩和其他法定条件作出行政许可决定；赋予法人或者其他组织特定的资格、资质的，行政机关根据申请人的专业人员构成、技术条件、经营业绩和管理水平等的考核结果作出行政许可决定。但是，法律、行政法规另有规定的，依照其规定。\n公民特定资格的考试依法由行政机关或者行业组织实施，公开举行。行政机关或者行业组织应当事先公布资格考试的报名条件、报考办法、考试科目以及考试大纲。但是，不得组织强制性的资格考试的考前培训，不得指定教材或者其他助考材料。\n第五十五条 实施本法第十二条第四项所列事项的行政许可的，应当按照技术标准、技术规范依法进行检验、检测、检疫，行政机关根据检验、检测、检疫的结果作出行政许可决定。\n行政机关实施检验、检测、检疫，应当自受理申请之日起五日内指派两名以上工作人员按照技术标准、技术规范进行检验、检测、检疫。不需要对检验、检测、检疫结果作进一步技术分析即可认定设备、设施、产品、物品是否符合技术标准、技术规范的，行政机关应当当场作出行政许可决定。\n行政机关根据检验、检测、检疫结果，作出不予行政许可决定的，应当书面说明不予行政许可所依据的技术标准、技术规范。\n第五十六条 实施本法第十二条第五项所列事项的行政许可，申请人提交的申请材料齐全、符合法定形式的，行政机关应当当场予以登记。需要对申请材料的实质内容进行核实的，行政机关依照本法第三十四条第三款的规定办理。\n第五十七条 有数量限制的行政许可，两个或者两个以上申请人的申请均符合法定条件、标准的，行政机关应当根据受理行政许可申请的先后顺序作出准予行政许可的决定。但是，法律、行政法规另有规定的，依照其规定。","level":2},{"name":"第五章 行政许可的费用","text":"第五十八条 行政机关实施行政许可和对行政许可事项进行监督检查，不得收取任何费用。但是，法律、行政法规另有规定的，依照其规定。\n行政机关提供行政许可申请书格式文本，不得收费。\n行政机关实施行政许可所需经费应当列入本行政机关的预算，由本级财政予以保障，按照批准的预算予以核拨。\n第五十九条 行政机关实施行政许可，依照法律、行政法规收取费用的，应当按照公布的法定项目和标准收费；所收取的费用必须全部上缴国库，任何机关或者个人不得以任何形式截留、挪用、私分或者变相私分。财政部门不得以任何形式向行政机关返还或者变相返还实施行政许可所收取的费用。","level":1},{"name":"第六章 监督检查","text":"第六十条 上级行政机关应当加强对下级行政机关实施行政许可的监督检查，及时纠正行政许可实施中的违法行为。\n第六十一条 行政机关应当建立健全监督制度，通过核查反映被许可人从事行政许可事项活动情况的有关材料，履行监督责任。\n行政机关依法对被许可人从事行政许可事项的活动进行监督检查时，应当将监督检查的情况和处理结果予以记录，由监督检查人员签字后归档。公众有权查阅行政机关监督检查记录。\n行政机关应当创造条件，实现与被许可人、其他有关行政机关的计算机档案系统互联，核查被许可人从事行政许可事项活动情况。\n第六十二条 行政机关可以对被许可人生产经营的产品依法进行抽样检查、检验、检测，对其生产经营场所依法进行实地检查。检查时，行政机关可以依法查阅或者要求被许可人报送有关材料；被许可人应当如实提供有关情况和材料。\n行政机关根据法律、行政法规的规定，对直接关系公共安全、人身健康、生命财产安全的重要设备、设施进行定期检验。对检验合格的，行政机关应当发给相应的证明文件。\n第六十三条 行政机关实施监督检查，不得妨碍被许可人正常的生产经营活动，不得索取或者收受被许可人的财物，不得谋取其他利益。\n第六十四条 被许可人在作出行政许可决定的行政机关管辖区域外违法从事行政许可事项活动的，违法行为发生地的行政机关应当依法将被许可人的违法事实、处理结果抄告作出行政许可决定的行政机关。\n第六十五条 个人和组织发现违法从事行政许可事项的活动，有权向行政机关举报，行政机关应当及时核实、处理。\n第六十六条 被许可人未依法履行开发利用自然资源义务或者未依法履行利用公共资源义务的，行政机关应当责令限期改正；被许可人在规定期限内不改正的，行政机关应当依照有关法律、行政法规的规定予以处理。\n第六十七条 取得直接关系公共利益的特定行业的市场准入行政许可的被许可人，应当按照国家规定的服务标准、资费标准和行政机关依法规定的条件，向用户提供安全、方便、稳定和价格合理的服务，并履行普遍服务的义务；未经作出行政许可决定的行政机关批准，不得擅自停业、歇业。\n被许可人不履行前款规定的义务的，行政机关应当责令限期改正，或者依法采取有效措施督促其履行义务。\n第六十八条 对直接关系公共安全、人身健康、生命财产安全的重要设备、设施，行政机关应当督促设计、建造、安装和使用单位建立相应的自检制度。\n行政机关在监督检查时，发现直接关系公共安全、人身健康、生命财产安全的重要设备、设施存在安全隐患的，应当责令停止建造、安装和使用，并责令设计、建造、安装和使用单位立即改正。\n第六十九条 有下列情形之一的，作出行政许可决定的行政机关或者其上级行政机关，根据利害关系人的请求或者依据职权，可以撤销行政许可：\n（一）行政机关工作人员滥用职权、玩忽职守作出准予行政许可决定的；\n（二）超越法定职权作出准予行政许可决定的；\n（三）违反法定程序作出准予行政许可决定的；\n（四）对不具备申请资格或者不符合法定条件的申请人准予行政许可的；\n（五）依法可以撤销行政许可的其他情形。\n被许可人以欺骗、贿赂等不正当手段取得行政许可的，应当予以撤销。\n依照前两款的规定撤销行政许可，可能对公共利益造成重大损害的，不予撤销。\n依照本条第一款的规定撤销行政许可，被许可人的合法权益受到损害的，行政机关应当依法给予赔偿。依照本条第二款的规定撤销行政许可的，被许可人基于行政许可取得的利益不受保护。\n第七十条 有下列情形之一的，行政机关应当依法办理有关行政许可的注销手续：\n（一）行政许可有效期届满未延续的；\n（二）赋予公民特定资格的行政许可，该公民死亡或者丧失行为能力的；\n（三）法人或者其他组织依法终止的；\n（四）行政许可依法被撤销、撤回，或者行政许可证件依法被吊销的；\n（五）因不可抗力导致行政许可事项无法实施的；\n（六）法律、法规规定的应当注销行政许可的其他情形。","level":1},{"name":"第七章 法律责任","text":"第七十一条 违反本法第十七条规定设定的行政许可，有关机关应当责令设定该行政许可的机关改正，或者依法予以撤销。\n第七十二条 行政机关及其工作人员违反本法的规定，有下列情形之一的，由其上级行政机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分：\n（一）对符合法定条件的行政许可申请不予受理的；\n（二）不在办公场所公示依法应当公示的材料的；\n（三）在受理、审查、决定行政许可过程中，未向申请人、利害关系人履行法定告知义务的；\n（四）申请人提交的申请材料不齐全、不符合法定形式，不一次告知申请人必须补正的全部内容的；\n（五）违法披露申请人提交的商业秘密、未披露信息或者保密商务信息的；\n（六）以转让技术作为取得行政许可的条件，或者在实施行政许可的过程中直接或者间接地要求转让技术的；\n（七）未依法说明不受理行政许可申请或者不予行政许可的理由的；\n（八）依法应当举行听证而不举行听证的。\n第七十三条 行政机关工作人员办理行政许可、实施监督检查，索取或者收受他人财物或者谋取其他利益，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。\n第七十四条 行政机关实施行政许可，有下列情形之一的，由其上级行政机关或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任：\n（一）对不符合法定条件的申请人准予行政许可或者超越法定职权作出准予行政许可决定的；\n（二）对符合法定条件的申请人不予行政许可或者不在法定期限内作出准予行政许可决定的；\n（三）依法应当根据招标、拍卖结果或者考试成绩择优作出准予行政许可决定，未经招标、拍卖或者考试，或者不根据招标、拍卖结果或者考试成绩择优作出准予行政许可决定的。\n第七十五条 行政机关实施行政许可，擅自收费或者不按照法定项目和标准收费的，由其上级行政机关或者监察机关责令退还非法收取的费用；对直接负责的主管人员和其他直接责任人员依法给予行政处分。\n截留、挪用、私分或者变相私分实施行政许可依法收取的费用的，予以追缴；对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。\n第七十六条 行政机关违法实施行政许可，给当事人的合法权益造成损害的，应当依照国家赔偿法的规定给予赔偿。\n第七十七条 行政机关不依法履行监督职责或者监督不力，造成严重后果的，由其上级行政机关或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。\n第七十八条 行政许可申请人隐瞒有关情况或者提供虚假材料申请行政许可的，行政机关不予受理或者不予行政许可，并给予警告；行政许可申请属于直接关系公共安全、人身健康、生命财产安全事项的，申请人在一年内不得再次申请该行政许可。\n第七十九条 被许可人以欺骗、贿赂等不正当手段取得行政许可的，行政机关应当依法给予行政处罚；取得的行政许可属于直接关系公共安全、人身健康、生命财产安全事项的，申请人在三年内不得再次申请该行政许可；构成犯罪的，依法追究刑事责任。\n第八十条 被许可人有下列行为之一的，行政机关应当依法给予行政处罚；构成犯罪的，依法追究刑事责任：\n（一）涂改、倒卖、出租、出借行政许可证件，或者以其他形式非法转让行政许可的；\n（二）超越行政许可范围进行活动的；\n（三）向负责监督检查的行政机关隐瞒有关情况、提供虚假材料或者拒绝提供反映其活动情况的真实材料的；\n（四）法律、法规、规章规定的其他违法行为。\n第八十一条 公民、法人或者其他组织未经行政许可，擅自从事依法应当取得行政许可的活动的，行政机关应当依法采取措施予以制止，并依法给予行政处罚；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第八章 附 则","text":"第八十二条 本法规定的行政机关实施行政许可的期限以工作日计算，不含法定节假日。\n第八十三条 本法自2004年7月1日起施行。\n本法施行前有关行政许可的规定，制定机关应当依照本法规定予以清理；不符合本法规定的，自本法施行之日起停止执行。","level":1}]},{"id":"n0288","sections":[{"name":"","text":"中华人民共和国检察官法\n（1995年2月28日第八届全国人民代表大会常务委员会第十二次会议通过 根据2001年6月30日第九届全国人民代表大会常务委员会第二十二次会议《关于修改〈中华人民共和国检察官法〉的决定》第一次修正 根据2017年9月1日第十二届全国人民代表大会常务委员会第二十九次会议《关于修改〈中华人民共和国法官法〉等八部法律的决定》第二次修正 2019年4月23日第十三届全国人民代表大会常务委员会第十次会议修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了全面推进高素质检察官队伍建设，加强对检察官的管理和监督，维护检察官合法权益，保障人民检察院依法独立行使检察权，保障检察官依法履行职责，保障司法公正，根据宪法，制定本法。\n第二条 检察官是依法行使国家检察权的检察人员，包括最高人民检察院、地方各级人民检察院和军事检察院等专门人民检察院的检察长、副检察长、检察委员会委员和检察员。\n第三条 检察官必须忠实执行宪法和法律，维护社会公平正义，全心全意为人民服务。\n第四条 检察官应当勤勉尽责，清正廉明，恪守职业道德。\n第五条 检察官履行职责，应当以事实为根据，以法律为准绳，秉持客观公正的立场。\n检察官办理刑事案件，应当严格坚持罪刑法定原则，尊重和保障人权，既要追诉犯罪，也要保障无罪的人不受刑事追究。\n第六条 检察官依法履行职责，受法律保护，不受行政机关、社会团体和个人的干涉。","level":1},{"name":"第二章 检察官的职责、义务和权利","text":"第七条 检察官的职责：\n（一）对法律规定由人民检察院直接受理的刑事案件进行侦查；\n（二）对刑事案件进行审查逮捕、审查起诉，代表国家进行公诉；\n（三）开展公益诉讼工作；\n（四）开展对刑事、民事、行政诉讼活动的监督工作；\n（五）法律规定的其他职责。\n检察官对其职权范围内就案件作出的决定负责。\n第八条 人民检察院检察长、副检察长、检察委员会委员除履行检察职责外，还应当履行与其职务相适应的职责。\n第九条 检察官在检察长领导下开展工作，重大办案事项由检察长决定。检察长可以将部分职权委托检察官行使，可以授权检察官签发法律文书。\n第十条 检察官应当履行下列义务：\n（一）严格遵守宪法和法律；\n（二）秉公办案，不得徇私枉法；\n（三）依法保障当事人和其他诉讼参与人的诉讼权利；\n（四）维护国家利益、社会公共利益，维护个人和组织的合法权益；\n（五）保守国家秘密和检察工作秘密，对履行职责中知悉的商业秘密和个人隐私予以保密；\n（六）依法接受法律监督和人民群众监督；\n（七）通过依法办理案件以案释法，增强全民法治观念，推进法治社会建设；\n（八）法律规定的其他义务。\n第十一条 检察官享有下列权利：\n（一）履行检察官职责应当具有的职权和工作条件；\n（二）非因法定事由、非经法定程序，不被调离、免职、降职、辞退或者处分；\n（三）履行检察官职责应当享有的职业保障和福利待遇；\n（四）人身、财产和住所安全受法律保护；\n（五）提出申诉或者控告；\n（六）法律规定的其他权利。","level":1},{"name":"第三章 检察官的条件和遴选","text":"第十二条 担任检察官必须具备下列条件：\n（一）具有中华人民共和国国籍；\n（二）拥护中华人民共和国宪法，拥护中国共产党领导和社会主义制度；\n（三）具有良好的政治、业务素质和道德品行；\n（四）具有正常履行职责的身体条件；\n（五）具备普通高等学校法学类本科学历并获得学士及以上学位；或者普通高等学校非法学类本科及以上学历并获得法律硕士、法学硕士及以上学位；或者普通高等学校非法学类本科及以上学历，获得其他相应学位，并具有法律专业知识；\n（六）从事法律工作满五年。其中获得法律硕士、法学硕士学位，或者获得法学博士学位的，从事法律工作的年限可以分别放宽至四年、三年；\n（七）初任检察官应当通过国家统一法律职业资格考试取得法律职业资格。\n适用前款第五项规定的学历条件确有困难的地方，经最高人民检察院审核确定，在一定期限内，可以将担任检察官的学历条件放宽为高等学校本科毕业。\n第十三条 下列人员不得担任检察官：\n（一）因犯罪受过刑事处罚的；\n（二）被开除公职的；\n（三）被吊销律师、公证员执业证书或者被仲裁委员会除名的；\n（四）有法律规定的其他情形的。\n第十四条 初任检察官采用考试、考核的办法，按照德才兼备的标准，从具备检察官条件的人员中择优提出人选。\n人民检察院的检察长应当具有法学专业知识和法律职业经历。副检察长、检察委员会委员应当从检察官、法官或者其他具备检察官条件的人员中产生。\n第十五条 人民检察院可以根据检察工作需要，从律师或者法学教学、研究人员等从事法律职业的人员中公开选拔检察官。\n除应当具备检察官任职条件外，参加公开选拔的律师应当实际执业不少于五年，执业经验丰富，从业声誉良好，参加公开选拔的法学教学、研究人员应当具有中级以上职称，从事教学、研究工作五年以上，有突出研究能力和相应研究成果。\n第十六条 省、自治区、直辖市设立检察官遴选委员会，负责初任检察官人选专业能力的审核。\n省级检察官遴选委员会的组成人员应当包括地方各级人民检察院检察官代表、其他从事法律职业的人员和有关方面代表，其中检察官代表不少于三分之一。\n省级检察官遴选委员会的日常工作由省级人民检察院的内设职能部门承担。\n遴选最高人民检察院检察官应当设立最高人民检察院检察官遴选委员会，负责检察官人选专业能力的审核。\n第十七条 初任检察官一般到基层人民检察院任职。上级人民检察院检察官一般逐级遴选；最高人民检察院和省级人民检察院检察官可以从下两级人民检察院遴选。参加上级人民检察院遴选的检察官应当在下级人民检察院担任检察官一定年限，并具有遴选职位相关工作经历。","level":1},{"name":"第四章 检察官的任免","text":"第十八条 检察官的任免，依照宪法和法律规定的任免权限和程序办理。\n最高人民检察院检察长由全国人民代表大会选举和罢免，副检察长、检察委员会委员和检察员，由检察长提请全国人民代表大会常务委员会任免。\n地方各级人民检察院检察长由本级人民代表大会选举和罢免，副检察长、检察委员会委员和检察员，由检察长提请本级人民代表大会常务委员会任免。\n地方各级人民检察院检察长的任免，须报上一级人民检察院检察长提请本级人民代表大会常务委员会批准。\n省、自治区、直辖市人民检察院分院检察长、副检察长、检察委员会委员和检察员，由省、自治区、直辖市人民检察院检察长提请本级人民代表大会常务委员会任免。\n省级人民检察院和设区的市级人民检察院依法设立作为派出机构的人民检察院的检察长、副检察长、检察委员会委员和检察员，由派出的人民检察院检察长提请本级人民代表大会常务委员会任免。\n新疆生产建设兵团各级人民检察院、专门人民检察院的检察长、副检察长、检察委员会委员和检察员，依照全国人民代表大会常务委员会的有关规定任免。\n第十九条 检察官在依照法定程序产生后，在就职时应当公开进行宪法宣誓。\n第二十条 检察官有下列情形之一的，应当依法提请免除其检察官职务：\n（一）丧失中华人民共和国国籍的；\n（二）调出所任职人民检察院的；\n（三）职务变动不需要保留检察官职务的，或者本人申请免除检察官职务经批准的；\n（四）经考核不能胜任检察官职务的；\n（五）因健康原因长期不能履行职务的；\n（六）退休的；\n（七）辞职或者依法应当予以辞退的；\n（八）因违纪违法不宜继续任职的。\n第二十一条 对于不具备本法规定条件或者违反法定程序被选举为人民检察院检察长的，上一级人民检察院检察长有权提请本级人民代表大会常务委员会不批准。\n第二十二条 发现违反本法规定的条件任命检察官的，任命机关应当撤销该项任命；上级人民检察院发现下级人民检察院检察官的任命违反本法规定的条件的，应当要求下级人民检察院依法提请任命机关撤销该项任命。\n第二十三条 检察官不得兼任人民代表大会常务委员会的组成人员，不得兼任行政机关、监察机关、审判机关的职务，不得兼任企业或者其他营利性组织、事业单位的职务，不得兼任律师、仲裁员和公证员。\n第二十四条 检察官之间有夫妻关系、直系血亲关系、三代以内旁系血亲以及近姻亲关系的，不得同时担任下列职务：\n（一）同一人民检察院的检察长、副检察长、检察委员会委员；\n（二）同一人民检察院的检察长、副检察长和检察员；\n（三）同一业务部门的检察员；\n（四）上下相邻两级人民检察院的检察长、副检察长。\n第二十五条 检察官的配偶、父母、子女有下列情形之一的，检察官应当实行任职回避：\n（一）担任该检察官所任职人民检察院辖区内律师事务所的合伙人或者设立人的；\n（二）在该检察官所任职人民检察院辖区内以律师身份担任诉讼代理人、辩护人，或者为诉讼案件当事人提供其他有偿法律服务的。","level":1},{"name":"第五章 检察官的管理","text":"第二十六条 检察官实行员额制管理。检察官员额根据案件数量、经济社会发展情况、人口数量和人民检察院层级等因素确定，在省、自治区、直辖市内实行总量控制、动态管理，优先考虑基层人民检察院和案件数量多的人民检察院办案需要。\n检察官员额出现空缺的，应当按照程序及时补充。\n最高人民检察院检察官员额由最高人民检察院商有关部门确定。\n第二十七条 检察官实行单独职务序列管理。\n检察官等级分为十二级，依次为首席大检察官、一级大检察官、二级大检察官、一级高级检察官、二级高级检察官、三级高级检察官、四级高级检察官、一级检察官、二级检察官、三级检察官、四级检察官、五级检察官。\n第二十八条 最高人民检察院检察长为首席大检察官。\n第二十九条 检察官等级的确定，以检察官德才表现、业务水平、检察工作实绩和工作年限等为依据。\n检察官等级晋升采取按期晋升和择优选升相结合的方式，特别优秀或者工作特殊需要的一线办案岗位检察官可以特别选升。\n第三十条 检察官的等级设置、确定和晋升的具体办法，由国家另行规定。\n第三十一条 初任检察官实行统一职前培训制度。\n第三十二条 对检察官应当有计划地进行政治、理论和业务培训。\n检察官的培训应当理论联系实际、按需施教、讲求实效。\n第三十三条 检察官培训情况，作为检察官任职、等级晋升的依据之一。\n第三十四条 检察官培训机构按照有关规定承担培训检察官的任务。\n第三十五条 检察官申请辞职，应当由本人书面提出，经批准后，依照法律规定的程序免除其职务。\n第三十六条 辞退检察官应当依照法律规定的程序免除其职务。\n辞退检察官应当按照管理权限决定。辞退决定应当以书面形式通知被辞退的检察官，并列明作出决定的理由和依据。\n第三十七条 检察官从人民检察院离任后两年内，不得以律师身份担任诉讼代理人或者辩护人。\n检察官从人民检察院离任后，不得担任原任职检察院办理案件的诉讼代理人或者辩护人，但是作为当事人的监护人或者近亲属代理诉讼或者进行辩护的除外。\n检察官被开除后，不得担任诉讼代理人或者辩护人，但是作为当事人的监护人或者近亲属代理诉讼或者进行辩护的除外。\n第三十八条 检察官因工作需要，经单位选派或者批准，可以在高等学校、科研院所协助开展实践性教学、研究工作，并遵守国家有关规定。","level":1},{"name":"第六章 检察官的考核、奖励和惩戒","text":"第三十九条 人民检察院设立检察官考评委员会，负责对本院检察官的考核工作。\n第四十条 检察官考评委员会的组成人员为五至九人。\n检察官考评委员会主任由本院检察长担任。\n第四十一条 对检察官的考核，应当全面、客观、公正，实行平时考核和年度考核相结合。\n第四十二条 对检察官的考核内容包括：检察工作实绩、职业道德、专业水平、工作能力、工作作风。重点考核检察工作实绩。\n第四十三条 年度考核结果分为优秀、称职、基本称职和不称职四个等次。\n考核结果作为调整检察官等级、工资以及检察官奖惩、免职、降职、辞退的依据。\n第四十四条 考核结果以书面形式通知检察官本人。检察官对考核结果如果有异议，可以申请复核。\n第四十五条 检察官在检察工作中有显著成绩和贡献的，或者有其他突出事迹的，应当给予奖励。\n第四十六条 检察官有下列表现之一的，应当给予奖励：\n（一）公正司法，成绩显著的；\n（二）总结检察实践经验成果突出，对检察工作有指导作用的；\n（三）在办理重大案件、处理突发事件和承担专项重要工作中，做出显著成绩和贡献的；\n（四）对检察工作提出改革建议被采纳，效果显著的；\n（五）提出检察建议被采纳或者开展法治宣传、解决各类纠纷，效果显著的；\n（六）有其他功绩的。\n检察官的奖励按照有关规定办理。\n第四十七条 检察官有下列行为之一的，应当给予处分；构成犯罪的，依法追究刑事责任：\n（一）贪污受贿、徇私枉法、刑讯逼供的；\n（二）隐瞒、伪造、变造、故意损毁证据、案件材料的；\n（三）泄露国家秘密、检察工作秘密、商业秘密或者个人隐私的；\n（四）故意违反法律法规办理案件的；\n（五）因重大过失导致案件错误并造成严重后果的；\n（六）拖延办案，贻误工作的；\n（七）利用职权为自己或者他人谋取私利的；\n（八）接受当事人及其代理人利益输送，或者违反有关规定会见当事人及其代理人的；\n（九）违反有关规定从事或者参与营利性活动，在企业或者其他营利性组织中兼任职务的；\n（十）有其他违纪违法行为的。\n检察官的处分按照有关规定办理。\n第四十八条 检察官涉嫌违纪违法，已经被立案调查、侦查，不宜继续履行职责的，按照管理权限和规定的程序暂时停止其履行职务。\n第四十九条 最高人民检察院和省、自治区、直辖市设立检察官惩戒委员会，负责从专业角度审查认定检察官是否存在本法第四十七条第四项、第五项规定的违反检察职责的行为，提出构成故意违反职责、存在重大过失、存在一般过失或者没有违反职责等审查意见。检察官惩戒委员会提出审查意见后，人民检察院依照有关规定作出是否予以惩戒的决定，并给予相应处理。\n检察官惩戒委员会由检察官代表、其他从事法律职业的人员和有关方面代表组成，其中检察官代表不少于半数。\n最高人民检察院检察官惩戒委员会、省级检察官惩戒委员会的日常工作，由相关人民检察院的内设职能部门承担。\n第五十条 检察官惩戒委员会审议惩戒事项时，当事检察官有权申请有关人员回避，有权进行陈述、举证、辩解。\n第五十一条 检察官惩戒委员会作出的审查意见应当送达当事检察官。当事检察官对审查意见有异议的，可以向惩戒委员会提出，惩戒委员会应当对异议及其理由进行审查，作出决定。\n第五十二条 检察官惩戒委员会审议惩戒事项的具体程序，由最高人民检察院商有关部门确定。","level":1},{"name":"第七章 检察官的职业保障","text":"第五十三条 人民检察院设立检察官权益保障委员会，维护检察官合法权益，保障检察官依法履行职责。\n第五十四条 除下列情形外，不得将检察官调离检察业务岗位：\n（一）按规定需要任职回避的；\n（二）按规定实行任职交流的；\n（三）因机构调整、撤销、合并或者缩减编制员额需要调整工作的；\n（四）因违纪违法不适合在检察业务岗位工作的；\n（五）法律规定的其他情形。\n第五十五条 任何单位或者个人不得要求检察官从事超出法定职责范围的事务。\n对任何干涉检察官办理案件的行为，检察官有权拒绝并予以全面如实记录和报告；有违纪违法情形的，由有关机关根据情节轻重追究有关责任人员、行为人的责任。\n第五十六条 检察官的职业尊严和人身安全受法律保护。\n任何单位和个人不得对检察官及其近亲属打击报复。\n对检察官及其近亲属实施报复陷害、侮辱诽谤、暴力侵害、威胁恐吓、滋事骚扰等违法犯罪行为的，应当依法从严惩治。\n第五十七条 检察官因依法履行职责遭受不实举报、诬告陷害、侮辱诽谤，致使名誉受到损害的，人民检察院应当会同有关部门及时澄清事实，消除不良影响，并依法追究相关单位或者个人的责任。\n第五十八条 检察官因依法履行职责，本人及其近亲属人身安全面临危险的，人民检察院、公安机关应当对检察官及其近亲属采取人身保护、禁止特定人员接触等必要保护措施。\n第五十九条 检察官实行与其职责相适应的工资制度，按照检察官等级享有国家规定的工资待遇，并建立与公务员工资同步调整机制。\n检察官的工资制度，根据检察工作特点，由国家另行规定。\n第六十条 检察官实行定期增资制度。\n经年度考核确定为优秀、称职的，可以按照规定晋升工资档次。\n第六十一条 检察官享受国家规定的津贴、补贴、奖金、保险和福利待遇。\n第六十二条 检察官因公致残的，享受国家规定的伤残待遇。检察官因公牺牲、因公死亡或者病故的，其亲属享受国家规定的抚恤和优待。\n第六十三条 检察官的退休制度，根据检察工作特点，由国家另行规定。\n第六十四条 检察官退休后，享受国家规定的养老金和其他待遇。\n第六十五条 对于国家机关及其工作人员侵犯本法第十一条规定的检察官权利的行为，检察官有权提出控告。\n第六十六条 对检察官处分或者人事处理错误的，应当及时予以纠正；造成名誉损害的，应当恢复名誉、消除影响、赔礼道歉；造成经济损失的，应当赔偿。对打击报复的直接责任人员，应当依法追究其责任。","level":1},{"name":"第八章 附 则","text":"第六十七条 国家对初任检察官实行统一法律职业资格考试制度，由国务院司法行政部门商最高人民检察院等有关部门组织实施。\n第六十八条 人民检察院的检察官助理在检察官指导下负责审查案件材料、草拟法律文书等检察辅助事务。\n人民检察院应当加强检察官助理队伍建设，为检察官遴选储备人才。\n第六十九条 有关检察官的权利、义务和管理制度，本法已有规定的，适用本法的规定；本法未作规定的，适用公务员管理的相关法律法规。\n第七十条 本法自2019年10月1日起施行。","level":1}]},{"id":"n0289","sections":[{"name":"","text":"中华人民共和国建筑法\n（1997年11月1日第八届全国人民代表大会常务委员会第二十八次会议通过 根据2011年4月22日第十一届全国人民代表大会常务委员会第二十次会议《关于修改〈中华人民共和国建筑法〉的决定》第一次修正 根据2019年4月23日第十三届全国人民代表大会常务委员会第十次会议《关于修改〈中华人民共和国建筑法〉等八部法律的决定》第二次修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强对建筑活动的监督管理，维护建筑市场秩序，保证建筑工程的质量和安全，促进建筑业健康发展，制定本法。\n第二条 在中华人民共和国境内从事建筑活动，实施对建筑活动的监督管理，应当遵守本法。\n本法所称建筑活动，是指各类房屋建筑及其附属设施的建造和与其配套的线路、管道、设备的安装活动。\n第三条 建筑活动应当确保建筑工程质量和安全，符合国家的建筑工程安全标准。\n第四条 国家扶持建筑业的发展，支持建筑科学技术研究，提高房屋建筑设计水平，鼓励节约能源和保护环境，提倡采用先进技术、先进设备、先进工艺、新型建筑材料和现代管理方式。\n第五条 从事建筑活动应当遵守法律、法规，不得损害社会公共利益和他人的合法权益。\n任何单位和个人都不得妨碍和阻挠依法进行的建筑活动。\n第六条 国务院建设行政主管部门对全国的建筑活动实施统一监督管理。","level":1},{"name":"第二章 建筑许可","text":"","level":1},{"name":"第一节 建筑工程施工许可","text":"第七条 建筑工程开工前，建设单位应当按照国家有关规定向工程所在地县级以上人民政府建设行政主管部门申请领取施工许可证；但是，国务院建设行政主管部门确定的限额以下的小型工程除外。\n按照国务院规定的权限和程序批准开工报告的建筑工程，不再领取施工许可证。\n第八条 申请领取施工许可证，应当具备下列条件：\n（一）已经办理该建筑工程用地批准手续；\n（二）依法应当办理建设工程规划许可证的，已经取得建设工程规划许可证；\n（三）需要拆迁的，其拆迁进度符合施工要求；\n（四）已经确定建筑施工企业；\n（五）有满足施工需要的资金安排、施工图纸及技术资料；\n（六）有保证工程质量和安全的具体措施。\n建设行政主管部门应当自收到申请之日起七日内，对符合条件的申请颁发施工许可证。\n第九条 建设单位应当自领取施工许可证之日起三个月内开工。因故不能按期开工的，应当向发证机关申请延期；延期以两次为限，每次不超过三个月。既不开工又不申请延期或者超过延期时限的，施工许可证自行废止。\n第十条 在建的建筑工程因故中止施工的，建设单位应当自中止施工之日起一个月内，向发证机关报告，并按照规定做好建筑工程的维护管理工作。\n建筑工程恢复施工时，应当向发证机关报告；中止施工满一年的工程恢复施工前，建设单位应当报发证机关核验施工许可证。\n第十一条 按照国务院有关规定批准开工报告的建筑工程，因故不能按期开工或者中止施工的，应当及时向批准机关报告情况。因故不能按期开工超过六个月的，应当重新办理开工报告的批准手续。","level":2},{"name":"第二节 从业资格","text":"第十二条 从事建筑活动的建筑施工企业、勘察单位、设计单位和工程监理单位，应当具备下列条件：\n（一）有符合国家规定的注册资本；\n（二）有与其从事的建筑活动相适应的具有法定执业资格的专业技术人员；\n（三）有从事相关建筑活动所应有的技术装备；\n（四）法律、行政法规规定的其他条件。\n第十三条 从事建筑活动的建筑施工企业、勘察单位、设计单位和工程监理单位，按照其拥有的注册资本、专业技术人员、技术装备和已完成的建筑工程业绩等资质条件，划分为不同的资质等级，经资质审查合格，取得相应等级的资质证书后，方可在其资质等级许可的范围内从事建筑活动。\n第十四条 从事建筑活动的专业技术人员，应当依法取得相应的执业资格证书，并在执业资格证书许可的范围内从事建筑活动。","level":2},{"name":"第三章 建筑工程发包与承包","text":"","level":1},{"name":"第一节 一般规定","text":"第十五条 建筑工程的发包单位与承包单位应当依法订立书面合同，明确双方的权利和义务。\n发包单位和承包单位应当全面履行合同约定的义务。不按照合同约定履行义务的，依法承担违约责任。\n第十六条 建筑工程发包与承包的招标投标活动，应当遵循公开、公正、平等竞争的原则，择优选择承包单位。\n建筑工程的招标投标，本法没有规定的，适用有关招标投标法律的规定。\n第十七条 发包单位及其工作人员在建筑工程发包中不得收受贿赂、回扣或者索取其他好处。\n承包单位及其工作人员不得利用向发包单位及其工作人员行贿、提供回扣或者给予其他好处等不正当手段承揽工程。\n第十八条 建筑工程造价应当按照国家有关规定，由发包单位与承包单位在合同中约定。公开招标发包的，其造价的约定，须遵守招标投标法律的规定。\n发包单位应当按照合同的约定，及时拨付工程款项。","level":2},{"name":"第二节 发 包","text":"第十九条 建筑工程依法实行招标发包，对不适于招标发包的可以直接发包。\n第二十条 建筑工程实行公开招标的，发包单位应当依照法定程序和方式，发布招标公告，提供载有招标工程的主要技术要求、主要的合同条款、评标的标准和方法以及开标、评标、定标的程序等内容的招标文件。\n开标应当在招标文件规定的时间、地点公开进行。开标后应当按照招标文件规定的评标标准和程序对标书进行评价、比较，在具备相应资质条件的投标者中，择优选定中标者。\n第二十一条 建筑工程招标的开标、评标、定标由建设单位依法组织实施，并接受有关行政主管部门的监督。\n第二十二条 建筑工程实行招标发包的，发包单位应当将建筑工程发包给依法中标的承包单位。建筑工程实行直接发包的，发包单位应当将建筑工程发包给具有相应资质条件的承包单位。\n第二十三条 政府及其所属部门不得滥用行政权力，限定发包单位将招标发包的建筑工程发包给指定的承包单位。\n第二十四条 提倡对建筑工程实行总承包，禁止将建筑工程肢解发包。\n建筑工程的发包单位可以将建筑工程的勘察、设计、施工、设备采购一并发包给一个工程总承包单位，也可以将建筑工程勘察、设计、施工、设备采购的一项或者多项发包给一个工程总承包单位；但是，不得将应当由一个承包单位完成的建筑工程肢解成若干部分发包给几个承包单位。\n第二十五条 按照合同约定，建筑材料、建筑构配件和设备由工程承包单位采购的，发包单位不得指定承包单位购入用于工程的建筑材料、建筑构配件和设备或者指定生产厂、供应商。","level":2},{"name":"第三节 承 包","text":"第二十六条 承包建筑工程的单位应当持有依法取得的资质证书，并在其资质等级许可的业务范围内承揽工程。\n禁止建筑施工企业超越本企业资质等级许可的业务范围或者以任何形式用其他建筑施工企业的名义承揽工程。禁止建筑施工企业以任何形式允许其他单位或者个人使用本企业的资质证书、营业执照，以本企业的名义承揽工程。\n第二十七条 大型建筑工程或者结构复杂的建筑工程，可以由两个以上的承包单位联合共同承包。共同承包的各方对承包合同的履行承担连带责任。\n两个以上不同资质等级的单位实行联合共同承包的，应当按照资质等级低的单位的业务许可范围承揽工程。\n第二十八条 禁止承包单位将其承包的全部建筑工程转包给他人，禁止承包单位将其承包的全部建筑工程肢解以后以分包的名义分别转包给他人。\n第二十九条 建筑工程总承包单位可以将承包工程中的部分工程发包给具有相应资质条件的分包单位；但是，除总承包合同中约定的分包外，必须经建设单位认可。施工总承包的，建筑工程主体结构的施工必须由总承包单位自行完成。\n建筑工程总承包单位按照总承包合同的约定对建设单位负责；分包单位按照分包合同的约定对总承包单位负责。总承包单位和分包单位就分包工程对建设单位承担连带责任。\n禁止总承包单位将工程分包给不具备相应资质条件的单位。禁止分包单位将其承包的工程再分包。","level":2},{"name":"第四章 建筑工程监理","text":"第三十条 国家推行建筑工程监理制度。\n国务院可以规定实行强制监理的建筑工程的范围。\n第三十一条 实行监理的建筑工程，由建设单位委托具有相应资质条件的工程监理单位监理。建设单位与其委托的工程监理单位应当订立书面委托监理合同。\n第三十二条 建筑工程监理应当依照法律、行政法规及有关的技术标准、设计文件和建筑工程承包合同，对承包单位在施工质量、建设工期和建设资金使用等方面，代表建设单位实施监督。\n工程监理人员认为工程施工不符合工程设计要求、施工技术标准和合同约定的，有权要求建筑施工企业改正。\n工程监理人员发现工程设计不符合建筑工程质量标准或者合同约定的质量要求的，应当报告建设单位要求设计单位改正。\n第三十三条 实施建筑工程监理前，建设单位应当将委托的工程监理单位、监理的内容及监理权限，书面通知被监理的建筑施工企业。\n第三十四条 工程监理单位应当在其资质等级许可的监理范围内，承担工程监理业务。\n工程监理单位应当根据建设单位的委托，客观、公正地执行监理任务。\n工程监理单位与被监理工程的承包单位以及建筑材料、建筑构配件和设备供应单位不得有隶属关系或者其他利害关系。\n工程监理单位不得转让工程监理业务。\n第三十五条 工程监理单位不按照委托监理合同的约定履行监理义务，对应当监督检查的项目不检查或者不按照规定检查，给建设单位造成损失的，应当承担相应的赔偿责任。\n工程监理单位与承包单位串通，为承包单位谋取非法利益，给建设单位造成损失的，应当与承包单位承担连带赔偿责任。","level":1},{"name":"第五章 建筑安全生产管理","text":"第三十六条 建筑工程安全生产管理必须坚持安全第一、预防为主的方针，建立健全安全生产的责任制度和群防群治制度。\n第三十七条 建筑工程设计应当符合按照国家规定制定的建筑安全规程和技术规范，保证工程的安全性能。\n第三十八条 建筑施工企业在编制施工组织设计时，应当根据建筑工程的特点制定相应的安全技术措施；对专业性较强的工程项目，应当编制专项安全施工组织设计，并采取安全技术措施。\n第三十九条 建筑施工企业应当在施工现场采取维护安全、防范危险、预防火灾等措施；有条件的，应当对施工现场实行封闭管理。\n施工现场对毗邻的建筑物、构筑物和特殊作业环境可能造成损害的，建筑施工企业应当采取安全防护措施。\n第四十条 建设单位应当向建筑施工企业提供与施工现场相关的地下管线资料，建筑施工企业应当采取措施加以保护。\n第四十一条 建筑施工企业应当遵守有关环境保护和安全生产的法律、法规的规定，采取控制和处理施工现场的各种粉尘、废气、废水、固体废物以及噪声、振动对环境的污染和危害的措施。\n第四十二条 有下列情形之一的，建设单位应当按照国家有关规定办理申请批准手续：\n（一）需要临时占用规划批准范围以外场地的；\n（二）可能损坏道路、管线、电力、邮电通讯等公共设施的；\n（三）需要临时停水、停电、中断道路交通的；\n（四）需要进行爆破作业的；\n（五）法律、法规规定需要办理报批手续的其他情形。\n第四十三条 建设行政主管部门负责建筑安全生产的管理，并依法接受劳动行政主管部门对建筑安全生产的指导和监督。\n第四十四条 建筑施工企业必须依法加强对建筑安全生产的管理，执行安全生产责任制度，采取有效措施，防止伤亡和其他安全生产事故的发生。\n建筑施工企业的法定代表人对本企业的安全生产负责。\n第四十五条 施工现场安全由建筑施工企业负责。实行施工总承包的，由总承包单位负责。分包单位向总承包单位负责，服从总承包单位对施工现场的安全生产管理。\n第四十六条 建筑施工企业应当建立健全劳动安全生产教育培训制度，加强对职工安全生产的教育培训；未经安全生产教育培训的人员，不得上岗作业。\n第四十七条 建筑施工企业和作业人员在施工过程中，应当遵守有关安全生产的法律、法规和建筑行业安全规章、规程，不得违章指挥或者违章作业。作业人员有权对影响人身健康的作业程序和作业条件提出改进意见，有权获得安全生产所需的防护用品。作业人员对危及生命安全和人身健康的行为有权提出批评、检举和控告。\n第四十八条 建筑施工企业应当依法为职工参加工伤保险缴纳工伤保险费。鼓励企业为从事危险作业的职工办理意外伤害保险，支付保险费。\n第四十九条 涉及建筑主体和承重结构变动的装修工程，建设单位应当在施工前委托原设计单位或者具有相应资质条件的设计单位提出设计方案；没有设计方案的，不得施工。\n第五十条 房屋拆除应当由具备保证安全条件的建筑施工单位承担，由建筑施工单位负责人对安全负责。\n第五十一条 施工中发生事故时，建筑施工企业应当采取紧急措施减少人员伤亡和事故损失，并按照国家有关规定及时向有关部门报告。","level":1},{"name":"第六章 建筑工程质量管理","text":"第五十二条 建筑工程勘察、设计、施工的质量必须符合国家有关建筑工程安全标准的要求，具体管理办法由国务院规定。\n有关建筑工程安全的国家标准不能适应确保建筑安全的要求时，应当及时修订。\n第五十三条 国家对从事建筑活动的单位推行质量体系认证制度。从事建筑活动的单位根据自愿原则可以向国务院产品质量监督管理部门或者国务院产品质量监督管理部门授权的部门认可的认证机构申请质量体系认证。经认证合格的，由认证机构颁发质量体系认证证书。\n第五十四条 建设单位不得以任何理由，要求建筑设计单位或者建筑施工企业在工程设计或者施工作业中，违反法律、行政法规和建筑工程质量、安全标准，降低工程质量。\n建筑设计单位和建筑施工企业对建设单位违反前款规定提出的降低工程质量的要求，应当予以拒绝。\n第五十五条 建筑工程实行总承包的，工程质量由工程总承包单位负责，总承包单位将建筑工程分包给其他单位的，应当对分包工程的质量与分包单位承担连带责任。分包单位应当接受总承包单位的质量管理。\n第五十六条 建筑工程的勘察、设计单位必须对其勘察、设计的质量负责。勘察、设计文件应当符合有关法律、行政法规的规定和建筑工程质量、安全标准、建筑工程勘察、设计技术规范以及合同的约定。设计文件选用的建筑材料、建筑构配件和设备，应当注明其规格、型号、性能等技术指标，其质量要求必须符合国家规定的标准。\n第五十七条 建筑设计单位对设计文件选用的建筑材料、建筑构配件和设备，不得指定生产厂、供应商。\n第五十八条 建筑施工企业对工程的施工质量负责。\n建筑施工企业必须按照工程设计图纸和施工技术标准施工，不得偷工减料。工程设计的修改由原设计单位负责，建筑施工企业不得擅自修改工程设计。\n第五十九条 建筑施工企业必须按照工程设计要求、施工技术标准和合同的约定，对建筑材料、建筑构配件和设备进行检验，不合格的不得使用。\n第六十条 建筑物在合理使用寿命内，必须确保地基基础工程和主体结构的质量。\n建筑工程竣工时，屋顶、墙面不得留有渗漏、开裂等质量缺陷；对已发现的质量缺陷，建筑施工企业应当修复。\n第六十一条 交付竣工验收的建筑工程，必须符合规定的建筑工程质量标准，有完整的工程技术经济资料和经签署的工程保修书，并具备国家规定的其他竣工条件。\n建筑工程竣工经验收合格后，方可交付使用；未经验收或者验收不合格的，不得交付使用。\n第六十二条 建筑工程实行质量保修制度。\n建筑工程的保修范围应当包括地基基础工程、主体结构工程、屋面防水工程和其他土建工程，以及电气管线、上下水管线的安装工程，供热、供冷系统工程等项目；保修的期限应当按照保证建筑物合理寿命年限内正常使用，维护使用者合法权益的原则确定。具体的保修范围和最低保修期限由国务院规定。\n第六十三条 任何单位和个人对建筑工程的质量事故、质量缺陷都有权向建设行政主管部门或者其他有关部门进行检举、控告、投诉。","level":1},{"name":"第七章 法律责任","text":"第六十四条 违反本法规定，未取得施工许可证或者开工报告未经批准擅自施工的，责令改正，对不符合开工条件的责令停止施工，可以处以罚款。\n第六十五条 发包单位将工程发包给不具有相应资质条件的承包单位的，或者违反本法规定将建筑工程肢解发包的，责令改正，处以罚款。\n超越本单位资质等级承揽工程的，责令停止违法行为，处以罚款，可以责令停业整顿，降低资质等级；情节严重的，吊销资质证书；有违法所得的，予以没收。\n未取得资质证书承揽工程的，予以取缔，并处罚款；有违法所得的，予以没收。\n以欺骗手段取得资质证书的，吊销资质证书，处以罚款；构成犯罪的，依法追究刑事责任。\n第六十六条 建筑施工企业转让、出借资质证书或者以其他方式允许他人以本企业的名义承揽工程的，责令改正，没收违法所得，并处罚款，可以责令停业整顿，降低资质等级；情节严重的，吊销资质证书。对因该项承揽工程不符合规定的质量标准造成的损失，建筑施工企业与使用本企业名义的单位或者个人承担连带赔偿责任。\n第六十七条 承包单位将承包的工程转包的，或者违反本法规定进行分包的，责令改正，没收违法所得，并处罚款，可以责令停业整顿，降低资质等级；情节严重的，吊销资质证书。\n承包单位有前款规定的违法行为的，对因转包工程或者违法分包的工程不符合规定的质量标准造成的损失，与接受转包或者分包的单位承担连带赔偿责任。\n第六十八条 在工程发包与承包中索贿、受贿、行贿，构成犯罪的，依法追究刑事责任；不构成犯罪的，分别处以罚款，没收贿赂的财物，对直接负责的主管人员和其他直接责任人员给予处分。\n对在工程承包中行贿的承包单位，除依照前款规定处罚外，可以责令停业整顿，降低资质等级或者吊销资质证书。\n第六十九条 工程监理单位与建设单位或者建筑施工企业串通，弄虚作假、降低工程质量的，责令改正，处以罚款，降低资质等级或者吊销资质证书；有违法所得的，予以没收；造成损失的，承担连带赔偿责任；构成犯罪的，依法追究刑事责任。\n工程监理单位转让监理业务的，责令改正，没收违法所得，可以责令停业整顿，降低资质等级；情节严重的，吊销资质证书。\n第七十条 违反本法规定，涉及建筑主体或者承重结构变动的装修工程擅自施工的，责令改正，处以罚款；造成损失的，承担赔偿责任；构成犯罪的，依法追究刑事责任。\n第七十一条 建筑施工企业违反本法规定，对建筑安全事故隐患不采取措施予以消除的，责令改正，可以处以罚款；情节严重的，责令停业整顿，降低资质等级或者吊销资质证书；构成犯罪的，依法追究刑事责任。\n建筑施工企业的管理人员违章指挥、强令职工冒险作业，因而发生重大伤亡事故或者造成其他严重后果的，依法追究刑事责任。\n第七十二条 建设单位违反本法规定，要求建筑设计单位或者建筑施工企业违反建筑工程质量、安全标准，降低工程质量的，责令改正，可以处以罚款；构成犯罪的，依法追究刑事责任。\n第七十三条 建筑设计单位不按照建筑工程质量、安全标准进行设计的，责令改正，处以罚款；造成工程质量事故的，责令停业整顿，降低资质等级或者吊销资质证书，没收违法所得，并处罚款；造成损失的，承担赔偿责任；构成犯罪的，依法追究刑事责任。\n第七十四条 建筑施工企业在施工中偷工减料的，使用不合格的建筑材料、建筑构配件和设备的，或者有其他不按照工程设计图纸或者施工技术标准施工的行为的，责令改正，处以罚款；情节严重的，责令停业整顿，降低资质等级或者吊销资质证书；造成建筑工程质量不符合规定的质量标准的，负责返工、修理，并赔偿因此造成的损失；构成犯罪的，依法追究刑事责任。\n第七十五条 建筑施工企业违反本法规定，不履行保修义务或者拖延履行保修义务的，责令改正，可以处以罚款，并对在保修期内因屋顶、墙面渗漏、开裂等质量缺陷造成的损失，承担赔偿责任。\n第七十六条 本法规定的责令停业整顿、降低资质等级和吊销资质证书的行政处罚，由颁发资质证书的机关决定；其他行政处罚，由建设行政主管部门或者有关部门依照法律和国务院规定的职权范围决定。\n依照本法规定被吊销资质证书的，由工商行政管理部门吊销其营业执照。\n第七十七条 违反本法规定，对不具备相应资质等级条件的单位颁发该等级资质证书的，由其上级机关责令收回所发的资质证书，对直接负责的主管人员和其他直接责任人员给予行政处分；构成犯罪的，依法追究刑事责任。\n第七十八条 政府及其所属部门的工作人员违反本法规定，限定发包单位将招标发包的工程发包给指定的承包单位的，由上级机关责令改正；构成犯罪的，依法追究刑事责任。\n第七十九条 负责颁发建筑工程施工许可证的部门及其工作人员对不符合施工条件的建筑工程颁发施工许可证的，负责工程质量监督检查或者竣工验收的部门及其工作人员对不合格的建筑工程出具质量合格文件或者按合格工程验收的，由上级机关责令改正，对责任人员给予行政处分；构成犯罪的，依法追究刑事责任；造成损失的，由该部门承担相应的赔偿责任。\n第八十条 在建筑物的合理使用寿命内，因建筑工程质量不合格受到损害的，有权向责任者要求赔偿。","level":1},{"name":"第八章 附 则","text":"第八十一条 本法关于施工许可、建筑施工企业资质审查和建筑工程发包、承包、禁止转包，以及建筑工程监理、建筑工程安全和质量管理的规定，适用于其他专业建筑工程的建筑活动，具体办法由国务院规定。\n第八十二条 建设行政主管部门和其他有关部门在对建筑活动实施监督管理中，除按照国务院有关规定收取费用外，不得收取其他费用。\n第八十三条 省、自治区、直辖市人民政府确定的小型房屋建筑工程的建筑活动，参照本法执行。\n依法核定作为文物保护的纪念建筑物和古建筑等的修缮，依照文物保护的有关法律规定执行。\n抢险救灾及其他临时性房屋建筑和农民自建低层住宅的建筑活动，不适用本法。\n第八十四条 军用房屋建筑工程建筑活动的具体管理办法，由国务院、中央军事委员会依据本法制定。\n第八十五条 本法自1998年3月1日起施行。","level":1}]},{"id":"n0290","sections":[{"name":"","text":"中华人民共和国商标法\n（1982年8月23日第五届全国人民代表大会常务委员会第二十四次会议通过 根据1993年2月22日第七届全国人民代表大会常务委员会第三十次会议《关于修改〈中华人民共和国商标法〉的决定》第一次修正 根据2001年10月27日第九届全国人民代表大会常务委员会第二十四次会议《关于修改〈中华人民共和国商标法〉的决定》第二次修正 根据2013年8月30日第十二届全国人民代表大会常务委员会第四次会议《关于修改〈中华人民共和国商标法〉的决定》第三次修正 根据2019年4月23日第十三届全国人民代表大会常务委员会第十次会议《关于修改〈中华人民共和国建筑法〉等八部法律的决定》第四次修正）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强商标管理，保护商标专用权，促使生产、经营者保证商品和服务质量，维护商标信誉，以保障消费者和生产、经营者的利益，促进社会主义市场经济的发展，特制定本法。\n第二条 国务院工商行政管理部门商标局主管全国商标注册和管理的工作。\n国务院工商行政管理部门设立商标评审委员会，负责处理商标争议事宜。\n第三条 经商标局核准注册的商标为注册商标，包括商品商标、服务商标和集体商标、证明商标；商标注册人享有商标专用权，受法律保护。\n本法所称集体商标，是指以团体、协会或者其他组织名义注册，供该组织成员在商事活动中使用，以表明使用者在该组织中的成员资格的标志。\n本法所称证明商标，是指由对某种商品或者服务具有监督能力的组织所控制，而由该组织以外的单位或者个人使用于其商品或者服务，用以证明该商品或者服务的原产地、原料、制造方法、质量或者其他特定品质的标志。\n集体商标、证明商标注册和管理的特殊事项，由国务院工商行政管理部门规定。\n第四条 自然人、法人或者其他组织在生产经营活动中，对其商品或者服务需要取得商标专用权的，应当向商标局申请商标注册。不以使用为目的的恶意商标注册申请，应当予以驳回。\n本法有关商品商标的规定，适用于服务商标。\n第五条 两个以上的自然人、法人或者其他组织可以共同向商标局申请注册同一商标，共同享有和行使该商标专用权。\n第六条 法律、行政法规规定必须使用注册商标的商品，必须申请商标注册，未经核准注册的，不得在市场销售。\n第七条 申请注册和使用商标，应当遵循诚实信用原则。\n商标使用人应当对其使用商标的商品质量负责。各级工商行政管理部门应当通过商标管理，制止欺骗消费者的行为。\n第八条 任何能够将自然人、法人或者其他组织的商品与他人的商品区别开的标志，包括文字、图形、字母、数字、三维标志、颜色组合和声音等，以及上述要素的组合，均可以作为商标申请注册。\n第九条 申请注册的商标，应当有显著特征，便于识别，并不得与他人在先取得的合法权利相冲突。\n商标注册人有权标明“注册商标”或者注册标记。\n第十条 下列标志不得作为商标使用：\n（一）同中华人民共和国的国家名称、国旗、国徽、国歌、军旗、军徽、军歌、勋章等相同或者近似的，以及同中央国家机关的名称、标志、所在地特定地点的名称或者标志性建筑物的名称、图形相同的；\n（二）同外国的国家名称、国旗、国徽、军旗等相同或者近似的，但经该国政府同意的除外；\n（三）同政府间国际组织的名称、旗帜、徽记等相同或者近似的，但经该组织同意或者不易误导公众的除外；\n（四）与表明实施控制、予以保证的官方标志、检验印记相同或者近似的，但经授权的除外；\n（五）同“红十字”、“红新月”的名称、标志相同或者近似的；\n（六）带有民族歧视性的；\n（七）带有欺骗性，容易使公众对商品的质量等特点或者产地产生误认的；\n（八）有害于社会主义道德风尚或者有其他不良影响的。\n县级以上行政区划的地名或者公众知晓的外国地名，不得作为商标。但是，地名具有其他含义或者作为集体商标、证明商标组成部分的除外；已经注册的使用地名的商标继续有效。\n第十一条 下列标志不得作为商标注册：\n（一）仅有本商品的通用名称、图形、型号的；\n（二）仅直接表示商品的质量、主要原料、功能、用途、重量、数量及其他特点的；\n（三）其他缺乏显著特征的。\n前款所列标志经过使用取得显著特征，并便于识别的，可以作为商标注册。\n第十二条 以三维标志申请注册商标的，仅由商品自身的性质产生的形状、为获得技术效果而需有的商品形状或者使商品具有实质性价值的形状，不得注册。\n第十三条 为相关公众所熟知的商标，持有人认为其权利受到侵害时，可以依照本法规定请求驰名商标保护。\n就相同或者类似商品申请注册的商标是复制、摹仿或者翻译他人未在中国注册的驰名商标，容易导致混淆的，不予注册并禁止使用。\n就不相同或者不相类似商品申请注册的商标是复制、摹仿或者翻译他人已经在中国注册的驰名商标，误导公众，致使该驰名商标注册人的利益可能受到损害的，不予注册并禁止使用。\n第十四条 驰名商标应当根据当事人的请求，作为处理涉及商标案件需要认定的事实进行认定。认定驰名商标应当考虑下列因素：\n（一）相关公众对该商标的知晓程度；\n（二）该商标使用的持续时间；\n（三）该商标的任何宣传工作的持续时间、程度和地理范围；\n（四）该商标作为驰名商标受保护的记录；\n（五）该商标驰名的其他因素。\n在商标注册审查、工商行政管理部门查处商标违法案件过程中，当事人依照本法第十三条规定主张权利的，商标局根据审查、处理案件的需要，可以对商标驰名情况作出认定。\n在商标争议处理过程中，当事人依照本法第十三条规定主张权利的，商标评审委员会根据处理案件的需要，可以对商标驰名情况作出认定。\n在商标民事、行政案件审理过程中，当事人依照本法第十三条规定主张权利的，最高人民法院指定的人民法院根据审理案件的需要，可以对商标驰名情况作出认定。\n生产、经营者不得将“驰名商标”字样用于商品、商品包装或者容器上，或者用于广告宣传、展览以及其他商业活动中。\n第十五条 未经授权，代理人或者代表人以自己的名义将被代理人或者被代表人的商标进行注册，被代理人或者被代表人提出异议的，不予注册并禁止使用。\n就同一种商品或者类似商品申请注册的商标与他人在先使用的未注册商标相同或者近似，申请人与该他人具有前款规定以外的合同、业务往来关系或者其他关系而明知该他人商标存在，该他人提出异议的，不予注册。\n第十六条 商标中有商品的地理标志，而该商品并非来源于该标志所标示的地区，误导公众的，不予注册并禁止使用；但是，已经善意取得注册的继续有效。\n前款所称地理标志，是指标示某商品来源于某地区，该商品的特定质量、信誉或者其他特征，主要由该地区的自然因素或者人文因素所决定的标志。\n第十七条 外国人或者外国企业在中国申请商标注册的，应当按其所属国和中华人民共和国签订的协议或者共同参加的国际条约办理，或者按对等原则办理。\n第十八条 申请商标注册或者办理其他商标事宜，可以自行办理，也可以委托依法设立的商标代理机构办理。\n外国人或者外国企业在中国申请商标注册和办理其他商标事宜的，应当委托依法设立的商标代理机构办理。\n第十九条 商标代理机构应当遵循诚实信用原则，遵守法律、行政法规，按照被代理人的委托办理商标注册申请或者其他商标事宜；对在代理过程中知悉的被代理人的商业秘密，负有保密义务。\n委托人申请注册的商标可能存在本法规定不得注册情形的，商标代理机构应当明确告知委托人。\n商标代理机构知道或者应当知道委托人申请注册的商标属于本法第四条、第十五条和第三十二条规定情形的，不得接受其委托。\n商标代理机构除对其代理服务申请商标注册外，不得申请注册其他商标。\n第二十条 商标代理行业组织应当按照章程规定，严格执行吸纳会员的条件，对违反行业自律规范的会员实行惩戒。商标代理行业组织对其吸纳的会员和对会员的惩戒情况，应当及时向社会公布。\n第二十一条 商标国际注册遵循中华人民共和国缔结或者参加的有关国际条约确立的制度，具体办法由国务院规定。","level":1},{"name":"第二章 商标注册的申请","text":"第二十二条 商标注册申请人应当按规定的商品分类表填报使用商标的商品类别和商品名称，提出注册申请。\n商标注册申请人可以通过一份申请就多个类别的商品申请注册同一商标。\n商标注册申请等有关文件，可以以书面方式或者数据电文方式提出。\n第二十三条 注册商标需要在核定使用范围之外的商品上取得商标专用权的，应当另行提出注册申请。\n第二十四条 注册商标需要改变其标志的，应当重新提出注册申请。\n第二十五条 商标注册申请人自其商标在外国第一次提出商标注册申请之日起六个月内，又在中国就相同商品以同一商标提出商标注册申请的，依照该外国同中国签订的协议或者共同参加的国际条约，或者按照相互承认优先权的原则，可以享有优先权。\n依照前款要求优先权的，应当在提出商标注册申请的时候提出书面声明，并且在三个月内提交第一次提出的商标注册申请文件的副本；未提出书面声明或者逾期未提交商标注册申请文件副本的，视为未要求优先权。\n第二十六条 商标在中国政府主办的或者承认的国际展览会展出的商品上首次使用的，自该商品展出之日起六个月内，该商标的注册申请人可以享有优先权。\n依照前款要求优先权的，应当在提出商标注册申请的时候提出书面声明，并且在三个月内提交展出其商品的展览会名称、在展出商品上使用该商标的证据、展出日期等证明文件；未提出书面声明或者逾期未提交证明文件的，视为未要求优先权。\n第二十七条 为申请商标注册所申报的事项和所提供的材料应当真实、准确、完整。","level":1},{"name":"第三章 商标注册的审查和核准","text":"第二十八条 对申请注册的商标，商标局应当自收到商标注册申请文件之日起九个月内审查完毕，符合本法有关规定的，予以初步审定公告。\n第二十九条 在审查过程中，商标局认为商标注册申请内容需要说明或者修正的，可以要求申请人做出说明或者修正。申请人未做出说明或者修正的，不影响商标局做出审查决定。\n第三十条 申请注册的商标，凡不符合本法有关规定或者同他人在同一种商品或者类似商品上已经注册的或者初步审定的商标相同或者近似的，由商标局驳回申请，不予公告。\n第三十一条 两个或者两个以上的商标注册申请人，在同一种商品或者类似商品上，以相同或者近似的商标申请注册的，初步审定并公告申请在先的商标；同一天申请的，初步审定并公告使用在先的商标，驳回其他人的申请，不予公告。\n第三十二条 申请商标注册不得损害他人现有的在先权利，也不得以不正当手段抢先注册他人已经使用并有一定影响的商标。\n第三十三条 对初步审定公告的商标，自公告之日起三个月内，在先权利人、利害关系人认为违反本法第十三条第二款和第三款、第十五条、第十六条第一款、第三十条、第三十一条、第三十二条规定的，或者任何人认为违反本法第四条、第十条、第十一条、第十二条、第十九条第四款规定的，可以向商标局提出异议。公告期满无异议的，予以核准注册，发给商标注册证，并予公告。\n第三十四条 对驳回申请、不予公告的商标，商标局应当书面通知商标注册申请人。商标注册申请人不服的，可以自收到通知之日起十五日内向商标评审委员会申请复审。商标评审委员会应当自收到申请之日起九个月内做出决定，并书面通知申请人。有特殊情况需要延长的，经国务院工商行政管理部门批准，可以延长三个月。当事人对商标评审委员会的决定不服的，可以自收到通知之日起三十日内向人民法院起诉。\n第三十五条 对初步审定公告的商标提出异议的，商标局应当听取异议人和被异议人陈述事实和理由，经调查核实后，自公告期满之日起十二个月内做出是否准予注册的决定，并书面通知异议人和被异议人。有特殊情况需要延长的，经国务院工商行政管理部门批准，可以延长六个月。\n商标局做出准予注册决定的，发给商标注册证，并予公告。异议人不服的，可以依照本法第四十四条、第四十五条的规定向商标评审委员会请求宣告该注册商标无效。\n商标局做出不予注册决定，被异议人不服的，可以自收到通知之日起十五日内向商标评审委员会申请复审。商标评审委员会应当自收到申请之日起十二个月内做出复审决定，并书面通知异议人和被异议人。有特殊情况需要延长的，经国务院工商行政管理部门批准，可以延长六个月。被异议人对商标评审委员会的决定不服的，可以自收到通知之日起三十日内向人民法院起诉。人民法院应当通知异议人作为第三人参加诉讼。\n商标评审委员会在依照前款规定进行复审的过程中，所涉及的在先权利的确定必须以人民法院正在审理或者行政机关正在处理的另一案件的结果为依据的，可以中止审查。中止原因消除后，应当恢复审查程序。\n第三十六条 法定期限届满，当事人对商标局做出的驳回申请决定、不予注册决定不申请复审或者对商标评审委员会做出的复审决定不向人民法院起诉的，驳回申请决定、不予注册决定或者复审决定生效。\n经审查异议不成立而准予注册的商标，商标注册申请人取得商标专用权的时间自初步审定公告三个月期满之日起计算。自该商标公告期满之日起至准予注册决定做出前，对他人在同一种或者类似商品上使用与该商标相同或者近似的标志的行为不具有追溯力；但是，因该使用人的恶意给商标注册人造成的损失，应当给予赔偿。\n第三十七条 对商标注册申请和商标复审申请应当及时进行审查。\n第三十八条 商标注册申请人或者注册人发现商标申请文件或者注册文件有明显错误的，可以申请更正。商标局依法在其职权范围内作出更正，并通知当事人。\n前款所称更正错误不涉及商标申请文件或者注册文件的实质性内容。","level":1},{"name":"第四章 注册商标的续展、变更、转让和使用许可","text":"第三十九条 注册商标的有效期为十年，自核准注册之日起计算。\n第四十条 注册商标有效期满，需要继续使用的，商标注册人应当在期满前十二个月内按照规定办理续展手续；在此期间未能办理的，可以给予六个月的宽展期。每次续展注册的有效期为十年，自该商标上一届有效期满次日起计算。期满未办理续展手续的，注销其注册商标。\n商标局应当对续展注册的商标予以公告。\n第四十一条 注册商标需要变更注册人的名义、地址或者其他注册事项的，应当提出变更申请。\n第四十二条 转让注册商标的，转让人和受让人应当签订转让协议，并共同向商标局提出申请。受让人应当保证使用该注册商标的商品质量。\n转让注册商标的，商标注册人对其在同一种商品上注册的近似的商标，或者在类似商品上注册的相同或者近似的商标，应当一并转让。\n对容易导致混淆或者有其他不良影响的转让，商标局不予核准，书面通知申请人并说明理由。\n转让注册商标经核准后，予以公告。受让人自公告之日起享有商标专用权。\n第四十三条 商标注册人可以通过签订商标使用许可合同，许可他人使用其注册商标。许可人应当监督被许可人使用其注册商标的商品质量。被许可人应当保证使用该注册商标的商品质量。\n经许可使用他人注册商标的，必须在使用该注册商标的商品上标明被许可人的名称和商品产地。\n许可他人使用其注册商标的，许可人应当将其商标使用许可报商标局备案，由商标局公告。商标使用许可未经备案不得对抗善意第三人。","level":1},{"name":"第五章 注册商标的无效宣告","text":"第四十四条 已经注册的商标，违反本法第四条、第十条、第十一条、第十二条、第十九条第四款规定的，或者是以欺骗手段或者其他不正当手段取得注册的，由商标局宣告该注册商标无效；其他单位或者个人可以请求商标评审委员会宣告该注册商标无效。\n商标局做出宣告注册商标无效的决定，应当书面通知当事人。当事人对商标局的决定不服的，可以自收到通知之日起十五日内向商标评审委员会申请复审。商标评审委员会应当自收到申请之日起九个月内做出决定，并书面通知当事人。有特殊情况需要延长的，经国务院工商行政管理部门批准，可以延长三个月。当事人对商标评审委员会的决定不服的，可以自收到通知之日起三十日内向人民法院起诉。\n其他单位或者个人请求商标评审委员会宣告注册商标无效的，商标评审委员会收到申请后，应当书面通知有关当事人，并限期提出答辩。商标评审委员会应当自收到申请之日起九个月内做出维持注册商标或者宣告注册商标无效的裁定，并书面通知当事人。有特殊情况需要延长的，经国务院工商行政管理部门批准，可以延长三个月。当事人对商标评审委员会的裁定不服的，可以自收到通知之日起三十日内向人民法院起诉。人民法院应当通知商标裁定程序的对方当事人作为第三人参加诉讼。\n第四十五条 已经注册的商标，违反本法第十三条第二款和第三款、第十五条、第十六条第一款、第三十条、第三十一条、第三十二条规定的，自商标注册之日起五年内，在先权利人或者利害关系人可以请求商标评审委员会宣告该注册商标无效。对恶意注册的，驰名商标所有人不受五年的时间限制。\n商标评审委员会收到宣告注册商标无效的申请后，应当书面通知有关当事人，并限期提出答辩。商标评审委员会应当自收到申请之日起十二个月内做出维持注册商标或者宣告注册商标无效的裁定，并书面通知当事人。有特殊情况需要延长的，经国务院工商行政管理部门批准，可以延长六个月。当事人对商标评审委员会的裁定不服的，可以自收到通知之日起三十日内向人民法院起诉。人民法院应当通知商标裁定程序的对方当事人作为第三人参加诉讼。\n商标评审委员会在依照前款规定对无效宣告请求进行审查的过程中，所涉及的在先权利的确定必须以人民法院正在审理或者行政机关正在处理的另一案件的结果为依据的，可以中止审查。中止原因消除后，应当恢复审查程序。\n第四十六条 法定期限届满，当事人对商标局宣告注册商标无效的决定不申请复审或者对商标评审委员会的复审决定、维持注册商标或者宣告注册商标无效的裁定不向人民法院起诉的，商标局的决定或者商标评审委员会的复审决定、裁定生效。\n第四十七条 依照本法第四十四条、第四十五条的规定宣告无效的注册商标，由商标局予以公告，该注册商标专用权视为自始即不存在。\n宣告注册商标无效的决定或者裁定，对宣告无效前人民法院做出并已执行的商标侵权案件的判决、裁定、调解书和工商行政管理部门做出并已执行的商标侵权案件的处理决定以及已经履行的商标转让或者使用许可合同不具有追溯力。但是，因商标注册人的恶意给他人造成的损失，应当给予赔偿。\n依照前款规定不返还商标侵权赔偿金、商标转让费、商标使用费，明显违反公平原则的，应当全部或者部分返还。","level":1},{"name":"第六章 商标使用的管理","text":"第四十八条 本法所称商标的使用，是指将商标用于商品、商品包装或者容器以及商品交易文书上，或者将商标用于广告宣传、展览以及其他商业活动中，用于识别商品来源的行为。\n第四十九条 商标注册人在使用注册商标的过程中，自行改变注册商标、注册人名义、地址或者其他注册事项的，由地方工商行政管理部门责令限期改正；期满不改正的，由商标局撤销其注册商标。\n注册商标成为其核定使用的商品的通用名称或者没有正当理由连续三年不使用的，任何单位或者个人可以向商标局申请撤销该注册商标。商标局应当自收到申请之日起九个月内做出决定。有特殊情况需要延长的，经国务院工商行政管理部门批准，可以延长三个月。\n第五十条 注册商标被撤销、被宣告无效或者期满不再续展的，自撤销、宣告无效或者注销之日起一年内，商标局对与该商标相同或者近似的商标注册申请，不予核准。\n第五十一条 违反本法第六条规定的，由地方工商行政管理部门责令限期申请注册，违法经营额五万元以上的，可以处违法经营额百分之二十以下的罚款，没有违法经营额或者违法经营额不足五万元的，可以处一万元以下的罚款。\n第五十二条 将未注册商标冒充注册商标使用的，或者使用未注册商标违反本法第十条规定的，由地方工商行政管理部门予以制止，限期改正，并可以予以通报，违法经营额五万元以上的，可以处违法经营额百分之二十以下的罚款，没有违法经营额或者违法经营额不足五万元的，可以处一万元以下的罚款。\n第五十三条 违反本法第十四条第五款规定的，由地方工商行政管理部门责令改正，处十万元罚款。\n第五十四条 对商标局撤销或者不予撤销注册商标的决定，当事人不服的，可以自收到通知之日起十五日内向商标评审委员会申请复审。商标评审委员会应当自收到申请之日起九个月内做出决定，并书面通知当事人。有特殊情况需要延长的，经国务院工商行政管理部门批准，可以延长三个月。当事人对商标评审委员会的决定不服的，可以自收到通知之日起三十日内向人民法院起诉。\n第五十五条 法定期限届满，当事人对商标局做出的撤销注册商标的决定不申请复审或者对商标评审委员会做出的复审决定不向人民法院起诉的，撤销注册商标的决定、复审决定生效。\n被撤销的注册商标，由商标局予以公告，该注册商标专用权自公告之日起终止。","level":1},{"name":"第七章 注册商标专用权的保护","text":"第五十六条 注册商标的专用权，以核准注册的商标和核定使用的商品为限。\n第五十七条 有下列行为之一的，均属侵犯注册商标专用权：\n（一）未经商标注册人的许可，在同一种商品上使用与其注册商标相同的商标的；\n（二）未经商标注册人的许可，在同一种商品上使用与其注册商标近似的商标，或者在类似商品上使用与其注册商标相同或者近似的商标，容易导致混淆的；\n（三）销售侵犯注册商标专用权的商品的；\n（四）伪造、擅自制造他人注册商标标识或者销售伪造、擅自制造的注册商标标识的；\n（五）未经商标注册人同意，更换其注册商标并将该更换商标的商品又投入市场的；\n（六）故意为侵犯他人商标专用权行为提供便利条件，帮助他人实施侵犯商标专用权行为的；\n（七）给他人的注册商标专用权造成其他损害的。\n第五十八条 将他人注册商标、未注册的驰名商标作为企业名称中的字号使用，误导公众，构成不正当竞争行为的，依照《中华人民共和国反不正当竞争法》处理。\n第五十九条 注册商标中含有的本商品的通用名称、图形、型号，或者直接表示商品的质量、主要原料、功能、用途、重量、数量及其他特点，或者含有的地名，注册商标专用权人无权禁止他人正当使用。\n三维标志注册商标中含有的商品自身的性质产生的形状、为获得技术效果而需有的商品形状或者使商品具有实质性价值的形状，注册商标专用权人无权禁止他人正当使用。\n商标注册人申请商标注册前，他人已经在同一种商品或者类似商品上先于商标注册人使用与注册商标相同或者近似并有一定影响的商标的，注册商标专用权人无权禁止该使用人在原使用范围内继续使用该商标，但可以要求其附加适当区别标识。\n第六十条 有本法第五十七条所列侵犯注册商标专用权行为之一，引起纠纷的，由当事人协商解决；不愿协商或者协商不成的，商标注册人或者利害关系人可以向人民法院起诉，也可以请求工商行政管理部门处理。\n工商行政管理部门处理时，认定侵权行为成立的，责令立即停止侵权行为，没收、销毁侵权商品和主要用于制造侵权商品、伪造注册商标标识的工具，违法经营额五万元以上的，可以处违法经营额五倍以下的罚款，没有违法经营额或者违法经营额不足五万元的，可以处二十五万元以下的罚款。对五年内实施两次以上商标侵权行为或者有其他严重情节的，应当从重处罚。销售不知道是侵犯注册商标专用权的商品，能证明该商品是自己合法取得并说明提供者的，由工商行政管理部门责令停止销售。\n对侵犯商标专用权的赔偿数额的争议，当事人可以请求进行处理的工商行政管理部门调解，也可以依照《中华人民共和国民事诉讼法》向人民法院起诉。经工商行政管理部门调解，当事人未达成协议或者调解书生效后不履行的，当事人可以依照《中华人民共和国民事诉讼法》向人民法院起诉。\n第六十一条 对侵犯注册商标专用权的行为，工商行政管理部门有权依法查处；涉嫌犯罪的，应当及时移送司法机关依法处理。\n第六十二条 县级以上工商行政管理部门根据已经取得的违法嫌疑证据或者举报，对涉嫌侵犯他人注册商标专用权的行为进行查处时，可以行使下列职权：\n（一）询问有关当事人，调查与侵犯他人注册商标专用权有关的情况；\n（二）查阅、复制当事人与侵权活动有关的合同、发票、账簿以及其他有关资料；\n（三）对当事人涉嫌从事侵犯他人注册商标专用权活动的场所实施现场检查；\n（四）检查与侵权活动有关的物品；对有证据证明是侵犯他人注册商标专用权的物品，可以查封或者扣押。\n工商行政管理部门依法行使前款规定的职权时，当事人应当予以协助、配合，不得拒绝、阻挠。\n在查处商标侵权案件过程中，对商标权属存在争议或者权利人同时向人民法院提起商标侵权诉讼的，工商行政管理部门可以中止案件的查处。中止原因消除后，应当恢复或者终结案件查处程序。\n第六十三条 侵犯商标专用权的赔偿数额，按照权利人因被侵权所受到的实际损失确定；实际损失难以确定的，可以按照侵权人因侵权所获得的利益确定；权利人的损失或者侵权人获得的利益难以确定的，参照该商标许可使用费的倍数合理确定。对恶意侵犯商标专用权，情节严重的，可以在按照上述方法确定数额的一倍以上五倍以下确定赔偿数额。赔偿数额应当包括权利人为制止侵权行为所支付的合理开支。\n人民法院为确定赔偿数额，在权利人已经尽力举证，而与侵权行为相关的账簿、资料主要由侵权人掌握的情况下，可以责令侵权人提供与侵权行为相关的账簿、资料；侵权人不提供或者提供虚假的账簿、资料的，人民法院可以参考权利人的主张和提供的证据判定赔偿数额。\n权利人因被侵权所受到的实际损失、侵权人因侵权所获得的利益、注册商标许可使用费难以确定的，由人民法院根据侵权行为的情节判决给予五百万元以下的赔偿。\n人民法院审理商标纠纷案件，应权利人请求，对属于假冒注册商标的商品，除特殊情况外，责令销毁；对主要用于制造假冒注册商标的商品的材料、工具，责令销毁，且不予补偿；或者在特殊情况下，责令禁止前述材料、工具进入商业渠道，且不予补偿。\n假冒注册商标的商品不得在仅去除假冒注册商标后进入商业渠道。\n第六十四条 注册商标专用权人请求赔偿，被控侵权人以注册商标专用权人未使用注册商标提出抗辩的，人民法院可以要求注册商标专用权人提供此前三年内实际使用该注册商标的证据。注册商标专用权人不能证明此前三年内实际使用过该注册商标，也不能证明因侵权行为受到其他损失的，被控侵权人不承担赔偿责任。\n销售不知道是侵犯注册商标专用权的商品，能证明该商品是自己合法取得并说明提供者的，不承担赔偿责任。\n第六十五条 商标注册人或者利害关系人有证据证明他人正在实施或者即将实施侵犯其注册商标专用权的行为，如不及时制止将会使其合法权益受到难以弥补的损害的，可以依法在起诉前向人民法院申请采取责令停止有关行为和财产保全的措施。\n第六十六条 为制止侵权行为，在证据可能灭失或者以后难以取得的情况下，商标注册人或者利害关系人可以依法在起诉前向人民法院申请保全证据。\n第六十七条 未经商标注册人许可，在同一种商品上使用与其注册商标相同的商标，构成犯罪的，除赔偿被侵权人的损失外，依法追究刑事责任。\n伪造、擅自制造他人注册商标标识或者销售伪造、擅自制造的注册商标标识，构成犯罪的，除赔偿被侵权人的损失外，依法追究刑事责任。\n销售明知是假冒注册商标的商品，构成犯罪的，除赔偿被侵权人的损失外，依法追究刑事责任。\n第六十八条 商标代理机构有下列行为之一的，由工商行政管理部门责令限期改正，给予警告，处一万元以上十万元以下的罚款；对直接负责的主管人员和其他直接责任人员给予警告，处五千元以上五万元以下的罚款；构成犯罪的，依法追究刑事责任：\n（一）办理商标事宜过程中，伪造、变造或者使用伪造、变造的法律文件、印章、签名的；\n（二）以诋毁其他商标代理机构等手段招徕商标代理业务或者以其他不正当手段扰乱商标代理市场秩序的；\n（三）违反本法第四条、第十九条第三款和第四款规定的。\n商标代理机构有前款规定行为的，由工商行政管理部门记入信用档案；情节严重的，商标局、商标评审委员会并可以决定停止受理其办理商标代理业务，予以公告。\n商标代理机构违反诚实信用原则，侵害委托人合法利益的，应当依法承担民事责任，并由商标代理行业组织按照章程规定予以惩戒。\n对恶意申请商标注册的，根据情节给予警告、罚款等行政处罚；对恶意提起商标诉讼的，由人民法院依法给予处罚。\n第六十九条 从事商标注册、管理和复审工作的国家机关工作人员必须秉公执法，廉洁自律，忠于职守，文明服务。\n商标局、商标评审委员会以及从事商标注册、管理和复审工作的国家机关工作人员不得从事商标代理业务和商品生产经营活动。\n第七十条 工商行政管理部门应当建立健全内部监督制度，对负责商标注册、管理和复审工作的国家机关工作人员执行法律、行政法规和遵守纪律的情况，进行监督检查。\n第七十一条 从事商标注册、管理和复审工作的国家机关工作人员玩忽职守、滥用职权、徇私舞弊，违法办理商标注册、管理和复审事项，收受当事人财物，牟取不正当利益，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。","level":1},{"name":"第八章 附 则","text":"第七十二条 申请商标注册和办理其他商标事宜的，应当缴纳费用，具体收费标准另定。\n第七十三条 本法自1983年3月1日起施行。1963年4月10日国务院公布的《商标管理条例》同时废止；其他有关商标管理的规定，凡与本法抵触的，同时失效。\n本法施行前已经注册的商标继续有效。","level":1}]},{"id":"n0291","sections":[{"name":"","text":"中华人民共和国疫苗管理法\n（2019年6月29日第十三届全国人民代表大会常务委员会第十一次会议通过）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强疫苗管理，保证疫苗质量和供应，规范预防接种，促进疫苗行业发展，保障公众健康，维护公共卫生安全，制定本法。\n第二条 在中华人民共和国境内从事疫苗研制、生产、流通和预防接种及其监督管理活动，适用本法。本法未作规定的，适用《中华人民共和国药品管理法》、《中华人民共和国传染病防治法》等法律、行政法规的规定。\n本法所称疫苗，是指为预防、控制疾病的发生、流行，用于人体免疫接种的预防性生物制品，包括免疫规划疫苗和非免疫规划疫苗。\n第三条 国家对疫苗实行最严格的管理制度，坚持安全第一、风险管理、全程管控、科学监管、社会共治。\n第四条 国家坚持疫苗产品的战略性和公益性。\n国家支持疫苗基础研究和应用研究，促进疫苗研制和创新，将预防、控制重大疾病的疫苗研制、生产和储备纳入国家战略。\n国家制定疫苗行业发展规划和产业政策，支持疫苗产业发展和结构优化，鼓励疫苗生产规模化、集约化，不断提升疫苗生产工艺和质量水平。\n第五条 疫苗上市许可持有人应当加强疫苗全生命周期质量管理，对疫苗的安全性、有效性和质量可控性负责。\n从事疫苗研制、生产、流通和预防接种活动的单位和个人，应当遵守法律、法规、规章、标准和规范，保证全过程信息真实、准确、完整和可追溯，依法承担责任，接受社会监督。\n第六条 国家实行免疫规划制度。\n居住在中国境内的居民，依法享有接种免疫规划疫苗的权利，履行接种免疫规划疫苗的义务。政府免费向居民提供免疫规划疫苗。\n县级以上人民政府及其有关部门应当保障适龄儿童接种免疫规划疫苗。监护人应当依法保证适龄儿童按时接种免疫规划疫苗。\n第七条 县级以上人民政府应当将疫苗安全工作和预防接种工作纳入本级国民经济和社会发展规划，加强疫苗监督管理能力建设，建立健全疫苗监督管理工作机制。\n县级以上地方人民政府对本行政区域疫苗监督管理工作负责，统一领导、组织、协调本行政区域疫苗监督管理工作。\n第八条 国务院药品监督管理部门负责全国疫苗监督管理工作。国务院卫生健康主管部门负责全国预防接种监督管理工作。国务院其他有关部门在各自职责范围内负责与疫苗有关的监督管理工作。\n省、自治区、直辖市人民政府药品监督管理部门负责本行政区域疫苗监督管理工作。设区的市级、县级人民政府承担药品监督管理职责的部门（以下称药品监督管理部门）负责本行政区域疫苗监督管理工作。县级以上地方人民政府卫生健康主管部门负责本行政区域预防接种监督管理工作。县级以上地方人民政府其他有关部门在各自职责范围内负责与疫苗有关的监督管理工作。\n第九条 国务院和省、自治区、直辖市人民政府建立部门协调机制，统筹协调疫苗监督管理有关工作，定期分析疫苗安全形势，加强疫苗监督管理，保障疫苗供应。\n第十条 国家实行疫苗全程电子追溯制度。\n国务院药品监督管理部门会同国务院卫生健康主管部门制定统一的疫苗追溯标准和规范，建立全国疫苗电子追溯协同平台，整合疫苗生产、流通和预防接种全过程追溯信息，实现疫苗可追溯。\n疫苗上市许可持有人应当建立疫苗电子追溯系统，与全国疫苗电子追溯协同平台相衔接，实现生产、流通和预防接种全过程最小包装单位疫苗可追溯、可核查。\n疾病预防控制机构、接种单位应当依法如实记录疫苗流通、预防接种等情况，并按照规定向全国疫苗电子追溯协同平台提供追溯信息。\n第十一条 疫苗研制、生产、检验等过程中应当建立健全生物安全管理制度，严格控制生物安全风险，加强菌毒株等病原微生物的生物安全管理，保护操作人员和公众的健康，保证菌毒株等病原微生物用途合法、正当。\n疫苗研制、生产、检验等使用的菌毒株和细胞株，应当明确历史、生物学特征、代次，建立详细档案，保证来源合法、清晰、可追溯；来源不明的，不得使用。\n第十二条 各级人民政府及其有关部门、疾病预防控制机构、接种单位、疫苗上市许可持有人和疫苗行业协会等应当通过全国儿童预防接种日等活动定期开展疫苗安全法律、法规以及预防接种知识等的宣传教育、普及工作。\n新闻媒体应当开展疫苗安全法律、法规以及预防接种知识等的公益宣传，并对疫苗违法行为进行舆论监督。有关疫苗的宣传报道应当全面、科学、客观、公正。\n第十三条 疫苗行业协会应当加强行业自律，建立健全行业规范，推动行业诚信体系建设，引导和督促会员依法开展生产经营等活动。","level":1},{"name":"第二章 疫苗研制和注册","text":"第十四条 国家根据疾病流行情况、人群免疫状况等因素，制定相关研制规划，安排必要资金，支持多联多价等新型疫苗的研制。\n国家组织疫苗上市许可持有人、科研单位、医疗卫生机构联合攻关，研制疾病预防、控制急需的疫苗。\n第十五条 国家鼓励疫苗上市许可持有人加大研制和创新资金投入，优化生产工艺，提升质量控制水平，推动疫苗技术进步。\n第十六条 开展疫苗临床试验，应当经国务院药品监督管理部门依法批准。\n疫苗临床试验应当由符合国务院药品监督管理部门和国务院卫生健康主管部门规定条件的三级医疗机构或者省级以上疾病预防控制机构实施或者组织实施。\n国家鼓励符合条件的医疗机构、疾病预防控制机构等依法开展疫苗临床试验。\n第十七条 疫苗临床试验申办者应当制定临床试验方案，建立临床试验安全监测与评价制度，审慎选择受试者，合理设置受试者群体和年龄组，并根据风险程度采取有效措施，保护受试者合法权益。\n第十八条 开展疫苗临床试验，应当取得受试者的书面知情同意；受试者为无民事行为能力人的，应当取得其监护人的书面知情同意；受试者为限制民事行为能力人的，应当取得本人及其监护人的书面知情同意。\n第十九条 在中国境内上市的疫苗应当经国务院药品监督管理部门批准，取得药品注册证书；申请疫苗注册，应当提供真实、充分、可靠的数据、资料和样品。\n对疾病预防、控制急需的疫苗和创新疫苗，国务院药品监督管理部门应当予以优先审评审批。\n第二十条 应对重大突发公共卫生事件急需的疫苗或者国务院卫生健康主管部门认定急需的其他疫苗，经评估获益大于风险的，国务院药品监督管理部门可以附条件批准疫苗注册申请。\n出现特别重大突发公共卫生事件或者其他严重威胁公众健康的紧急事件，国务院卫生健康主管部门根据传染病预防、控制需要提出紧急使用疫苗的建议，经国务院药品监督管理部门组织论证同意后可以在一定范围和期限内紧急使用。\n第二十一条 国务院药品监督管理部门在批准疫苗注册申请时，对疫苗的生产工艺、质量控制标准和说明书、标签予以核准。\n国务院药品监督管理部门应当在其网站上及时公布疫苗说明书、标签内容。","level":1},{"name":"第三章 疫苗生产和批签发","text":"第二十二条 国家对疫苗生产实行严格准入制度。\n从事疫苗生产活动，应当经省级以上人民政府药品监督管理部门批准，取得药品生产许可证。\n从事疫苗生产活动，除符合《中华人民共和国药品管理法》规定的从事药品生产活动的条件外，还应当具备下列条件：\n（一）具备适度规模和足够的产能储备；\n（二）具有保证生物安全的制度和设施、设备；\n（三）符合疾病预防、控制需要。\n疫苗上市许可持有人应当具备疫苗生产能力；超出疫苗生产能力确需委托生产的，应当经国务院药品监督管理部门批准。接受委托生产的，应当遵守本法规定和国家有关规定，保证疫苗质量。\n第二十三条 疫苗上市许可持有人的法定代表人、主要负责人应当具有良好的信用记录，生产管理负责人、质量管理负责人、质量受权人等关键岗位人员应当具有相关专业背景和从业经历。\n疫苗上市许可持有人应当加强对前款规定人员的培训和考核，及时将其任职和变更情况向省、自治区、直辖市人民政府药品监督管理部门报告。\n第二十四条 疫苗应当按照经核准的生产工艺和质量控制标准进行生产和检验，生产全过程应当符合药品生产质量管理规范的要求。\n疫苗上市许可持有人应当按照规定对疫苗生产全过程和疫苗质量进行审核、检验。\n第二十五条 疫苗上市许可持有人应当建立完整的生产质量管理体系，持续加强偏差管理，采用信息化手段如实记录生产、检验过程中形成的所有数据，确保生产全过程持续符合法定要求。\n第二十六条 国家实行疫苗批签发制度。\n每批疫苗销售前或者进口时，应当经国务院药品监督管理部门指定的批签发机构按照相关技术要求进行审核、检验。符合要求的，发给批签发证明；不符合要求的，发给不予批签发通知书。\n不予批签发的疫苗不得销售，并应当由省、自治区、直辖市人民政府药品监督管理部门监督销毁；不予批签发的进口疫苗应当由口岸所在地药品监督管理部门监督销毁或者依法进行其他处理。\n国务院药品监督管理部门、批签发机构应当及时公布上市疫苗批签发结果，供公众查询。\n第二十七条 申请疫苗批签发应当按照规定向批签发机构提供批生产及检验记录摘要等资料和同批号产品等样品。进口疫苗还应当提供原产地证明、批签发证明；在原产地免予批签发的，应当提供免予批签发证明。\n第二十八条 预防、控制传染病疫情或者应对突发事件急需的疫苗，经国务院药品监督管理部门批准，免予批签发。\n第二十九条 疫苗批签发应当逐批进行资料审核和抽样检验。疫苗批签发检验项目和检验频次应当根据疫苗质量风险评估情况进行动态调整。\n对疫苗批签发申请资料或者样品的真实性有疑问，或者存在其他需要进一步核实的情况的，批签发机构应当予以核实，必要时应当采用现场抽样检验等方式组织开展现场核实。\n第三十条 批签发机构在批签发过程中发现疫苗存在重大质量风险的，应当及时向国务院药品监督管理部门和省、自治区、直辖市人民政府药品监督管理部门报告。\n接到报告的部门应当立即对疫苗上市许可持有人进行现场检查，根据检查结果通知批签发机构对疫苗上市许可持有人的相关产品或者所有产品不予批签发或者暂停批签发，并责令疫苗上市许可持有人整改。疫苗上市许可持有人应当立即整改，并及时将整改情况向责令其整改的部门报告。\n第三十一条 对生产工艺偏差、质量差异、生产过程中的故障和事故以及采取的措施，疫苗上市许可持有人应当如实记录，并在相应批产品申请批签发的文件中载明；可能影响疫苗质量的，疫苗上市许可持有人应当立即采取措施，并向省、自治区、直辖市人民政府药品监督管理部门报告。","level":1},{"name":"第四章 疫苗流通","text":"第三十二条 国家免疫规划疫苗由国务院卫生健康主管部门会同国务院财政部门等组织集中招标或者统一谈判，形成并公布中标价格或者成交价格，各省、自治区、直辖市实行统一采购。\n国家免疫规划疫苗以外的其他免疫规划疫苗、非免疫规划疫苗由各省、自治区、直辖市通过省级公共资源交易平台组织采购。\n第三十三条 疫苗的价格由疫苗上市许可持有人依法自主合理制定。疫苗的价格水平、差价率、利润率应当保持在合理幅度。\n第三十四条 省级疾病预防控制机构应当根据国家免疫规划和本行政区域疾病预防、控制需要，制定本行政区域免疫规划疫苗使用计划，并按照国家有关规定向组织采购疫苗的部门报告，同时报省、自治区、直辖市人民政府卫生健康主管部门备案。\n第三十五条 疫苗上市许可持有人应当按照采购合同约定，向疾病预防控制机构供应疫苗。\n疾病预防控制机构应当按照规定向接种单位供应疫苗。\n疾病预防控制机构以外的单位和个人不得向接种单位供应疫苗，接种单位不得接收该疫苗。\n第三十六条 疫苗上市许可持有人应当按照采购合同约定，向疾病预防控制机构或者疾病预防控制机构指定的接种单位配送疫苗。\n疫苗上市许可持有人、疾病预防控制机构自行配送疫苗应当具备疫苗冷链储存、运输条件，也可以委托符合条件的疫苗配送单位配送疫苗。\n疾病预防控制机构配送非免疫规划疫苗可以收取储存、运输费用，具体办法由国务院财政部门会同国务院价格主管部门制定，收费标准由省、自治区、直辖市人民政府价格主管部门会同财政部门制定。\n第三十七条 疾病预防控制机构、接种单位、疫苗上市许可持有人、疫苗配送单位应当遵守疫苗储存、运输管理规范，保证疫苗质量。\n疫苗在储存、运输全过程中应当处于规定的温度环境，冷链储存、运输应当符合要求，并定时监测、记录温度。\n疫苗储存、运输管理规范由国务院药品监督管理部门、国务院卫生健康主管部门共同制定。\n第三十八条 疫苗上市许可持有人在销售疫苗时，应当提供加盖其印章的批签发证明复印件或者电子文件；销售进口疫苗的，还应当提供加盖其印章的进口药品通关单复印件或者电子文件。\n疾病预防控制机构、接种单位在接收或者购进疫苗时，应当索取前款规定的证明文件，并保存至疫苗有效期满后不少于五年备查。\n第三十九条 疫苗上市许可持有人应当按照规定，建立真实、准确、完整的销售记录，并保存至疫苗有效期满后不少于五年备查。\n疾病预防控制机构、接种单位、疫苗配送单位应当按照规定，建立真实、准确、完整的接收、购进、储存、配送、供应记录，并保存至疫苗有效期满后不少于五年备查。\n疾病预防控制机构、接种单位接收或者购进疫苗时，应当索取本次运输、储存全过程温度监测记录，并保存至疫苗有效期满后不少于五年备查；对不能提供本次运输、储存全过程温度监测记录或者温度控制不符合要求的，不得接收或者购进，并应当立即向县级以上地方人民政府药品监督管理部门、卫生健康主管部门报告。\n第四十条 疾病预防控制机构、接种单位应当建立疫苗定期检查制度，对存在包装无法识别、储存温度不符合要求、超过有效期等问题的疫苗，采取隔离存放、设置警示标志等措施，并按照国务院药品监督管理部门、卫生健康主管部门、生态环境主管部门的规定处置。疾病预防控制机构、接种单位应当如实记录处置情况，处置记录应当保存至疫苗有效期满后不少于五年备查。","level":1},{"name":"第五章 预防接种","text":"第四十一条 国务院卫生健康主管部门制定国家免疫规划；国家免疫规划疫苗种类由国务院卫生健康主管部门会同国务院财政部门拟订，报国务院批准后公布。\n国务院卫生健康主管部门建立国家免疫规划专家咨询委员会，并会同国务院财政部门建立国家免疫规划疫苗种类动态调整机制。\n省、自治区、直辖市人民政府在执行国家免疫规划时，可以根据本行政区域疾病预防、控制需要，增加免疫规划疫苗种类，报国务院卫生健康主管部门备案并公布。\n第四十二条 国务院卫生健康主管部门应当制定、公布预防接种工作规范，强化预防接种规范化管理。\n国务院卫生健康主管部门应当制定、公布国家免疫规划疫苗的免疫程序和非免疫规划疫苗的使用指导原则。\n省、自治区、直辖市人民政府卫生健康主管部门应当结合本行政区域实际情况制定接种方案，并报国务院卫生健康主管部门备案。\n第四十三条 各级疾病预防控制机构应当按照各自职责，开展与预防接种相关的宣传、培训、技术指导、监测、评价、流行病学调查、应急处置等工作。\n第四十四条 接种单位应当具备下列条件：\n（一）取得医疗机构执业许可证；\n（二）具有经过县级人民政府卫生健康主管部门组织的预防接种专业培训并考核合格的医师、护士或者乡村医生；\n（三）具有符合疫苗储存、运输管理规范的冷藏设施、设备和冷藏保管制度。\n县级以上地方人民政府卫生健康主管部门指定符合条件的医疗机构承担责任区域内免疫规划疫苗接种工作。符合条件的医疗机构可以承担非免疫规划疫苗接种工作，并应当报颁发其医疗机构执业许可证的卫生健康主管部门备案。\n接种单位应当加强内部管理，开展预防接种工作应当遵守预防接种工作规范、免疫程序、疫苗使用指导原则和接种方案。\n各级疾病预防控制机构应当加强对接种单位预防接种工作的技术指导和疫苗使用的管理。\n第四十五条 医疗卫生人员实施接种，应当告知受种者或者其监护人所接种疫苗的品种、作用、禁忌、不良反应以及现场留观等注意事项，询问受种者的健康状况以及是否有接种禁忌等情况，并如实记录告知和询问情况。受种者或者其监护人应当如实提供受种者的健康状况和接种禁忌等情况。有接种禁忌不能接种的，医疗卫生人员应当向受种者或者其监护人提出医学建议，并如实记录提出医学建议情况。\n医疗卫生人员在实施接种前，应当按照预防接种工作规范的要求，检查受种者健康状况、核查接种禁忌，查对预防接种证，检查疫苗、注射器的外观、批号、有效期，核对受种者的姓名、年龄和疫苗的品名、规格、剂量、接种部位、接种途径，做到受种者、预防接种证和疫苗信息相一致，确认无误后方可实施接种。\n医疗卫生人员应当对符合接种条件的受种者实施接种。受种者在现场留观期间出现不良反应的，医疗卫生人员应当按照预防接种工作规范的要求，及时采取救治等措施。\n第四十六条 医疗卫生人员应当按照国务院卫生健康主管部门的规定，真实、准确、完整记录疫苗的品种、上市许可持有人、最小包装单位的识别信息、有效期、接种时间、实施接种的医疗卫生人员、受种者等接种信息，确保接种信息可追溯、可查询。接种记录应当保存至疫苗有效期满后不少于五年备查。\n第四十七条 国家对儿童实行预防接种证制度。在儿童出生后一个月内，其监护人应当到儿童居住地承担预防接种工作的接种单位或者出生医院为其办理预防接种证。接种单位或者出生医院不得拒绝办理。监护人应当妥善保管预防接种证。\n预防接种实行居住地管理，儿童离开原居住地期间，由现居住地承担预防接种工作的接种单位负责对其实施接种。\n预防接种证的格式由国务院卫生健康主管部门规定。\n第四十八条 儿童入托、入学时，托幼机构、学校应当查验预防接种证，发现未按照规定接种免疫规划疫苗的，应当向儿童居住地或者托幼机构、学校所在地承担预防接种工作的接种单位报告，并配合接种单位督促其监护人按照规定补种。疾病预防控制机构应当为托幼机构、学校查验预防接种证等提供技术指导。\n儿童入托、入学预防接种证查验办法由国务院卫生健康主管部门会同国务院教育行政部门制定。\n第四十九条 接种单位接种免疫规划疫苗不得收取任何费用。\n接种单位接种非免疫规划疫苗，除收取疫苗费用外，还可以收取接种服务费。接种服务费的收费标准由省、自治区、直辖市人民政府价格主管部门会同财政部门制定。\n第五十条 县级以上地方人民政府卫生健康主管部门根据传染病监测和预警信息，为预防、控制传染病暴发、流行，报经本级人民政府决定，并报省级以上人民政府卫生健康主管部门备案，可以在本行政区域进行群体性预防接种。\n需要在全国范围或者跨省、自治区、直辖市范围内进行群体性预防接种的，应当由国务院卫生健康主管部门决定。\n作出群体性预防接种决定的县级以上地方人民政府或者国务院卫生健康主管部门应当组织有关部门做好人员培训、宣传教育、物资调用等工作。\n任何单位和个人不得擅自进行群体性预防接种。\n第五十一条 传染病暴发、流行时，县级以上地方人民政府或者其卫生健康主管部门需要采取应急接种措施的，依照法律、行政法规的规定执行。","level":1},{"name":"第六章 异常反应监测和处理","text":"第五十二条 预防接种异常反应，是指合格的疫苗在实施规范接种过程中或者实施规范接种后造成受种者机体组织器官、功能损害，相关各方均无过错的药品不良反应。\n下列情形不属于预防接种异常反应：\n（一）因疫苗本身特性引起的接种后一般反应；\n（二）因疫苗质量问题给受种者造成的损害；\n（三）因接种单位违反预防接种工作规范、免疫程序、疫苗使用指导原则、接种方案给受种者造成的损害；\n（四）受种者在接种时正处于某种疾病的潜伏期或者前驱期，接种后偶合发病；\n（五）受种者有疫苗说明书规定的接种禁忌，在接种前受种者或者其监护人未如实提供受种者的健康状况和接种禁忌等情况，接种后受种者原有疾病急性复发或者病情加重；\n（六）因心理因素发生的个体或者群体的心因性反应。\n第五十三条 国家加强预防接种异常反应监测。预防接种异常反应监测方案由国务院卫生健康主管部门会同国务院药品监督管理部门制定。\n第五十四条 接种单位、医疗机构等发现疑似预防接种异常反应的，应当按照规定向疾病预防控制机构报告。\n疫苗上市许可持有人应当设立专门机构，配备专职人员，主动收集、跟踪分析疑似预防接种异常反应，及时采取风险控制措施，将疑似预防接种异常反应向疾病预防控制机构报告，将质量分析报告提交省、自治区、直辖市人民政府药品监督管理部门。\n第五十五条 对疑似预防接种异常反应，疾病预防控制机构应当按照规定及时报告，组织调查、诊断，并将调查、诊断结论告知受种者或者其监护人。对调查、诊断结论有争议的，可以根据国务院卫生健康主管部门制定的鉴定办法申请鉴定。\n因预防接种导致受种者死亡、严重残疾，或者群体性疑似预防接种异常反应等对社会有重大影响的疑似预防接种异常反应，由设区的市级以上人民政府卫生健康主管部门、药品监督管理部门按照各自职责组织调查、处理。\n第五十六条 国家实行预防接种异常反应补偿制度。实施接种过程中或者实施接种后出现受种者死亡、严重残疾、器官组织损伤等损害，属于预防接种异常反应或者不能排除的，应当给予补偿。补偿范围实行目录管理，并根据实际情况进行动态调整。\n接种免疫规划疫苗所需的补偿费用，由省、自治区、直辖市人民政府财政部门在预防接种经费中安排；接种非免疫规划疫苗所需的补偿费用，由相关疫苗上市许可持有人承担。国家鼓励通过商业保险等多种形式对预防接种异常反应受种者予以补偿。\n预防接种异常反应补偿应当及时、便民、合理。预防接种异常反应补偿范围、标准、程序由国务院规定，省、自治区、直辖市制定具体实施办法。","level":1},{"name":"第七章 疫苗上市后管理","text":"第五十七条 疫苗上市许可持有人应当建立健全疫苗全生命周期质量管理体系，制定并实施疫苗上市后风险管理计划，开展疫苗上市后研究，对疫苗的安全性、有效性和质量可控性进行进一步确证。\n对批准疫苗注册申请时提出进一步研究要求的疫苗，疫苗上市许可持有人应当在规定期限内完成研究；逾期未完成研究或者不能证明其获益大于风险的，国务院药品监督管理部门应当依法处理，直至注销该疫苗的药品注册证书。\n第五十八条 疫苗上市许可持有人应当对疫苗进行质量跟踪分析，持续提升质量控制标准，改进生产工艺，提高生产工艺稳定性。\n生产工艺、生产场地、关键设备等发生变更的，应当进行评估、验证，按照国务院药品监督管理部门有关变更管理的规定备案或者报告；变更可能影响疫苗安全性、有效性和质量可控性的，应当经国务院药品监督管理部门批准。\n第五十九条 疫苗上市许可持有人应当根据疫苗上市后研究、预防接种异常反应等情况持续更新说明书、标签，并按照规定申请核准或者备案。\n国务院药品监督管理部门应当在其网站上及时公布更新后的疫苗说明书、标签内容。\n第六十条 疫苗上市许可持有人应当建立疫苗质量回顾分析和风险报告制度，每年将疫苗生产流通、上市后研究、风险管理等情况按照规定如实向国务院药品监督管理部门报告。\n第六十一条 国务院药品监督管理部门可以根据实际情况，责令疫苗上市许可持有人开展上市后评价或者直接组织开展上市后评价。\n对预防接种异常反应严重或者其他原因危害人体健康的疫苗，国务院药品监督管理部门应当注销该疫苗的药品注册证书。\n第六十二条 国务院药品监督管理部门可以根据疾病预防、控制需要和疫苗行业发展情况，组织对疫苗品种开展上市后评价，发现该疫苗品种的产品设计、生产工艺、安全性、有效性或者质量可控性明显劣于预防、控制同种疾病的其他疫苗品种的，应当注销该品种所有疫苗的药品注册证书并废止相应的国家药品标准。","level":1},{"name":"第八章 保障措施","text":"第六十三条 县级以上人民政府应当将疫苗安全工作、购买免疫规划疫苗和预防接种工作以及信息化建设等所需经费纳入本级政府预算，保证免疫规划制度的实施。\n县级人民政府按照国家有关规定对从事预防接种工作的乡村医生和其他基层医疗卫生人员给予补助。\n国家根据需要对经济欠发达地区的预防接种工作给予支持。省、自治区、直辖市人民政府和设区的市级人民政府应当对经济欠发达地区的县级人民政府开展与预防接种相关的工作给予必要的经费补助。\n第六十四条 省、自治区、直辖市人民政府根据本行政区域传染病流行趋势，在国务院卫生健康主管部门确定的传染病预防、控制项目范围内，确定本行政区域与预防接种相关的项目，并保证项目的实施。\n第六十五条 国务院卫生健康主管部门根据各省、自治区、直辖市国家免疫规划疫苗使用计划，向疫苗上市许可持有人提供国家免疫规划疫苗需求信息，疫苗上市许可持有人根据疫苗需求信息合理安排生产。\n疫苗存在供应短缺风险时，国务院卫生健康主管部门、国务院药品监督管理部门提出建议，国务院工业和信息化主管部门、国务院财政部门应当采取有效措施，保障疫苗生产、供应。\n疫苗上市许可持有人应当依法组织生产，保障疫苗供应；疫苗上市许可持有人停止疫苗生产的，应当及时向国务院药品监督管理部门或者省、自治区、直辖市人民政府药品监督管理部门报告。\n第六十六条 国家将疫苗纳入战略物资储备，实行中央和省级两级储备。\n国务院工业和信息化主管部门、财政部门会同国务院卫生健康主管部门、公安部门、市场监督管理部门和药品监督管理部门，根据疾病预防、控制和公共卫生应急准备的需要，加强储备疫苗的产能、产品管理，建立动态调整机制。\n第六十七条 各级财政安排用于预防接种的经费应当专款专用，任何单位和个人不得挪用、挤占。\n有关单位和个人使用预防接种的经费应当依法接受审计机关的审计监督。\n第六十八条 国家实行疫苗责任强制保险制度。\n疫苗上市许可持有人应当按照规定投保疫苗责任强制保险。因疫苗质量问题造成受种者损害的，保险公司在承保的责任限额内予以赔付。\n疫苗责任强制保险制度的具体实施办法，由国务院药品监督管理部门会同国务院卫生健康主管部门、保险监督管理机构等制定。\n第六十九条 传染病暴发、流行时，相关疫苗上市许可持有人应当及时生产和供应预防、控制传染病的疫苗。交通运输单位应当优先运输预防、控制传染病的疫苗。县级以上人民政府及其有关部门应当做好组织、协调、保障工作。","level":1},{"name":"第九章 监督管理","text":"第七十条 药品监督管理部门、卫生健康主管部门按照各自职责对疫苗研制、生产、流通和预防接种全过程进行监督管理，监督疫苗上市许可持有人、疾病预防控制机构、接种单位等依法履行义务。\n药品监督管理部门依法对疫苗研制、生产、储存、运输以及预防接种中的疫苗质量进行监督检查。卫生健康主管部门依法对免疫规划制度的实施、预防接种活动进行监督检查。\n药品监督管理部门应当加强对疫苗上市许可持有人的现场检查；必要时，可以对为疫苗研制、生产、流通等活动提供产品或者服务的单位和个人进行延伸检查；有关单位和个人应当予以配合，不得拒绝和隐瞒。\n第七十一条 国家建设中央和省级两级职业化、专业化药品检查员队伍，加强对疫苗的监督检查。\n省、自治区、直辖市人民政府药品监督管理部门选派检查员入驻疫苗上市许可持有人。检查员负责监督检查药品生产质量管理规范执行情况，收集疫苗质量风险和违法违规线索，向省、自治区、直辖市人民政府药品监督管理部门报告情况并提出建议，对派驻期间的行为负责。\n第七十二条 疫苗质量管理存在安全隐患，疫苗上市许可持有人等未及时采取措施消除的，药品监督管理部门可以采取责任约谈、限期整改等措施。\n严重违反药品相关质量管理规范的，药品监督管理部门应当责令暂停疫苗生产、销售、配送，立即整改；整改完成后，经药品监督管理部门检查符合要求的，方可恢复生产、销售、配送。\n药品监督管理部门应当建立疫苗上市许可持有人及其相关人员信用记录制度，纳入全国信用信息共享平台，按照规定公示其严重失信信息，实施联合惩戒。\n第七十三条 疫苗存在或者疑似存在质量问题的，疫苗上市许可持有人、疾病预防控制机构、接种单位应当立即停止销售、配送、使用，必要时立即停止生产，按照规定向县级以上人民政府药品监督管理部门、卫生健康主管部门报告。卫生健康主管部门应当立即组织疾病预防控制机构和接种单位采取必要的应急处置措施，同时向上级人民政府卫生健康主管部门报告。药品监督管理部门应当依法采取查封、扣押等措施。对已经销售的疫苗，疫苗上市许可持有人应当及时通知相关疾病预防控制机构、疫苗配送单位、接种单位，按照规定召回，如实记录召回和通知情况，疾病预防控制机构、疫苗配送单位、接种单位应当予以配合。\n未依照前款规定停止生产、销售、配送、使用或者召回疫苗的，县级以上人民政府药品监督管理部门、卫生健康主管部门应当按照各自职责责令停止生产、销售、配送、使用或者召回疫苗。\n疫苗上市许可持有人、疾病预防控制机构、接种单位发现存在或者疑似存在质量问题的疫苗，不得瞒报、谎报、缓报、漏报，不得隐匿、伪造、毁灭有关证据。\n第七十四条 疫苗上市许可持有人应当建立信息公开制度，按照规定在其网站上及时公开疫苗产品信息、说明书和标签、药品相关质量管理规范执行情况、批签发情况、召回情况、接受检查和处罚情况以及投保疫苗责任强制保险情况等信息。\n第七十五条 国务院药品监督管理部门会同国务院卫生健康主管部门等建立疫苗质量、预防接种等信息共享机制。\n省级以上人民政府药品监督管理部门、卫生健康主管部门等应当按照科学、客观、及时、公开的原则，组织疫苗上市许可持有人、疾病预防控制机构、接种单位、新闻媒体、科研单位等，就疫苗质量和预防接种等信息进行交流沟通。\n第七十六条 国家实行疫苗安全信息统一公布制度。\n疫苗安全风险警示信息、重大疫苗安全事故及其调查处理信息和国务院确定需要统一公布的其他疫苗安全信息，由国务院药品监督管理部门会同有关部门公布。全国预防接种异常反应报告情况，由国务院卫生健康主管部门会同国务院药品监督管理部门统一公布。未经授权不得发布上述信息。公布重大疫苗安全信息，应当及时、准确、全面，并按照规定进行科学评估，作出必要的解释说明。\n县级以上人民政府药品监督管理部门发现可能误导公众和社会舆论的疫苗安全信息，应当立即会同卫生健康主管部门及其他有关部门、专业机构、相关疫苗上市许可持有人等进行核实、分析，并及时公布结果。\n任何单位和个人不得编造、散布虚假疫苗安全信息。\n第七十七条 任何单位和个人有权依法了解疫苗信息，对疫苗监督管理工作提出意见、建议。\n任何单位和个人有权向卫生健康主管部门、药品监督管理部门等部门举报疫苗违法行为，对卫生健康主管部门、药品监督管理部门等部门及其工作人员未依法履行监督管理职责的情况有权向本级或者上级人民政府及其有关部门、监察机关举报。有关部门、机关应当及时核实、处理；对查证属实的举报，按照规定给予举报人奖励；举报人举报所在单位严重违法行为，查证属实的，给予重奖。\n第七十八条 县级以上人民政府应当制定疫苗安全事件应急预案，对疫苗安全事件分级、处置组织指挥体系与职责、预防预警机制、处置程序、应急保障措施等作出规定。\n疫苗上市许可持有人应当制定疫苗安全事件处置方案，定期检查各项防范措施的落实情况，及时消除安全隐患。\n发生疫苗安全事件，疫苗上市许可持有人应当立即向国务院药品监督管理部门或者省、自治区、直辖市人民政府药品监督管理部门报告；疾病预防控制机构、接种单位、医疗机构应当立即向县级以上人民政府卫生健康主管部门、药品监督管理部门报告。药品监督管理部门应当会同卫生健康主管部门按照应急预案的规定，成立疫苗安全事件处置指挥机构，开展医疗救治、风险控制、调查处理、信息发布、解释说明等工作，做好补种等善后处置工作。因质量问题造成的疫苗安全事件的补种费用由疫苗上市许可持有人承担。\n有关单位和个人不得瞒报、谎报、缓报、漏报疫苗安全事件，不得隐匿、伪造、毁灭有关证据。","level":1},{"name":"第十章 法律责任","text":"第七十九条 违反本法规定，构成犯罪的，依法从重追究刑事责任。\n第八十条 生产、销售的疫苗属于假药的，由省级以上人民政府药品监督管理部门没收违法所得和违法生产、销售的疫苗以及专门用于违法生产疫苗的原料、辅料、包装材料、设备等物品，责令停产停业整顿，吊销药品注册证书，直至吊销药品生产许可证等，并处违法生产、销售疫苗货值金额十五倍以上五十倍以下的罚款，货值金额不足五十万元的，按五十万元计算。\n生产、销售的疫苗属于劣药的，由省级以上人民政府药品监督管理部门没收违法所得和违法生产、销售的疫苗以及专门用于违法生产疫苗的原料、辅料、包装材料、设备等物品，责令停产停业整顿，并处违法生产、销售疫苗货值金额十倍以上三十倍以下的罚款，货值金额不足五十万元的，按五十万元计算；情节严重的，吊销药品注册证书，直至吊销药品生产许可证等。\n生产、销售的疫苗属于假药，或者生产、销售的疫苗属于劣药且情节严重的，由省级以上人民政府药品监督管理部门对法定代表人、主要负责人、直接负责的主管人员和关键岗位人员以及其他责任人员，没收违法行为发生期间自本单位所获收入，并处所获收入一倍以上十倍以下的罚款，终身禁止从事药品生产经营活动，由公安机关处五日以上十五日以下拘留。\n第八十一条 有下列情形之一的，由省级以上人民政府药品监督管理部门没收违法所得和违法生产、销售的疫苗以及专门用于违法生产疫苗的原料、辅料、包装材料、设备等物品，责令停产停业整顿，并处违法生产、销售疫苗货值金额十五倍以上五十倍以下的罚款，货值金额不足五十万元的，按五十万元计算；情节严重的，吊销药品相关批准证明文件，直至吊销药品生产许可证等，对法定代表人、主要负责人、直接负责的主管人员和关键岗位人员以及其他责任人员，没收违法行为发生期间自本单位所获收入，并处所获收入百分之五十以上十倍以下的罚款，十年内直至终身禁止从事药品生产经营活动，由公安机关处五日以上十五日以下拘留：\n（一）申请疫苗临床试验、注册、批签发提供虚假数据、资料、样品或者有其他欺骗行为；\n（二）编造生产、检验记录或者更改产品批号；\n（三）疾病预防控制机构以外的单位或者个人向接种单位供应疫苗；\n（四）委托生产疫苗未经批准；\n（五）生产工艺、生产场地、关键设备等发生变更按照规定应当经批准而未经批准；\n（六）更新疫苗说明书、标签按照规定应当经核准而未经核准。\n第八十二条 除本法另有规定的情形外，疫苗上市许可持有人或者其他单位违反药品相关质量管理规范的，由县级以上人民政府药品监督管理部门责令改正，给予警告；拒不改正的，处二十万元以上五十万元以下的罚款；情节严重的，处五十万元以上三百万元以下的罚款，责令停产停业整顿，直至吊销药品相关批准证明文件、药品生产许可证等，对法定代表人、主要负责人、直接负责的主管人员和关键岗位人员以及其他责任人员，没收违法行为发生期间自本单位所获收入，并处所获收入百分之五十以上五倍以下的罚款，十年内直至终身禁止从事药品生产经营活动。\n第八十三条 违反本法规定，疫苗上市许可持有人有下列情形之一的，由省级以上人民政府药品监督管理部门责令改正，给予警告；拒不改正的，处二十万元以上五十万元以下的罚款；情节严重的，责令停产停业整顿，并处五十万元以上二百万元以下的罚款：\n（一）未按照规定建立疫苗电子追溯系统；\n（二）法定代表人、主要负责人和生产管理负责人、质量管理负责人、质量受权人等关键岗位人员不符合规定条件或者未按照规定对其进行培训、考核；\n（三）未按照规定报告或者备案；\n（四）未按照规定开展上市后研究，或者未按照规定设立机构、配备人员主动收集、跟踪分析疑似预防接种异常反应；\n（五）未按照规定投保疫苗责任强制保险；\n（六）未按照规定建立信息公开制度。\n第八十四条 违反本法规定，批签发机构有下列情形之一的，由国务院药品监督管理部门责令改正，给予警告，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告直至降级处分：\n（一）未按照规定进行审核和检验；\n（二）未及时公布上市疫苗批签发结果；\n（三）未按照规定进行核实；\n（四）发现疫苗存在重大质量风险未按照规定报告。\n违反本法规定，批签发机构未按照规定发给批签发证明或者不予批签发通知书的，由国务院药品监督管理部门责令改正，给予警告，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予降级或者撤职处分；情节严重的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予开除处分。\n第八十五条 疾病预防控制机构、接种单位、疫苗上市许可持有人、疫苗配送单位违反疫苗储存、运输管理规范有关冷链储存、运输要求的，由县级以上人民政府药品监督管理部门责令改正，给予警告，对违法储存、运输的疫苗予以销毁，没收违法所得；拒不改正的，对接种单位、疫苗上市许可持有人、疫苗配送单位处二十万元以上一百万元以下的罚款；情节严重的，对接种单位、疫苗上市许可持有人、疫苗配送单位处违法储存、运输疫苗货值金额十倍以上三十倍以下的罚款，货值金额不足十万元的，按十万元计算，责令疫苗上市许可持有人、疫苗配送单位停产停业整顿，直至吊销药品相关批准证明文件、药品生产许可证等，对疫苗上市许可持有人、疫苗配送单位的法定代表人、主要负责人、直接负责的主管人员和关键岗位人员以及其他责任人员依照本法第八十二条规定给予处罚。\n疾病预防控制机构、接种单位有前款规定违法行为的，由县级以上人民政府卫生健康主管部门对主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告直至撤职处分，责令负有责任的医疗卫生人员暂停一年以上十八个月以下执业活动；造成严重后果的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予开除处分，并可以吊销接种单位的接种资格，由原发证部门吊销负有责任的医疗卫生人员的执业证书。\n第八十六条 疾病预防控制机构、接种单位、疫苗上市许可持有人、疫苗配送单位有本法第八十五条规定以外的违反疫苗储存、运输管理规范行为的，由县级以上人民政府药品监督管理部门责令改正，给予警告，没收违法所得；拒不改正的，对接种单位、疫苗上市许可持有人、疫苗配送单位处十万元以上三十万元以下的罚款；情节严重的，对接种单位、疫苗上市许可持有人、疫苗配送单位处违法储存、运输疫苗货值金额三倍以上十倍以下的罚款，货值金额不足十万元的，按十万元计算。\n疾病预防控制机构、接种单位有前款规定违法行为的，县级以上人民政府卫生健康主管部门可以对主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告直至撤职处分，责令负有责任的医疗卫生人员暂停六个月以上一年以下执业活动；造成严重后果的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予开除处分，由原发证部门吊销负有责任的医疗卫生人员的执业证书。\n第八十七条 违反本法规定，疾病预防控制机构、接种单位有下列情形之一的，由县级以上人民政府卫生健康主管部门责令改正，给予警告，没收违法所得；情节严重的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告直至撤职处分，责令负有责任的医疗卫生人员暂停一年以上十八个月以下执业活动；造成严重后果的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予开除处分，由原发证部门吊销负有责任的医疗卫生人员的执业证书：\n（一）未按照规定供应、接收、采购疫苗；\n（二）接种疫苗未遵守预防接种工作规范、免疫程序、疫苗使用指导原则、接种方案；\n（三）擅自进行群体性预防接种。\n第八十八条 违反本法规定，疾病预防控制机构、接种单位有下列情形之一的，由县级以上人民政府卫生健康主管部门责令改正，给予警告；情节严重的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告直至撤职处分，责令负有责任的医疗卫生人员暂停六个月以上一年以下执业活动；造成严重后果的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予开除处分，由原发证部门吊销负有责任的医疗卫生人员的执业证书：\n（一）未按照规定提供追溯信息；\n（二）接收或者购进疫苗时未按照规定索取并保存相关证明文件、温度监测记录；\n（三）未按照规定建立并保存疫苗接收、购进、储存、配送、供应、接种、处置记录；\n（四）未按照规定告知、询问受种者或者其监护人有关情况。\n第八十九条 疾病预防控制机构、接种单位、医疗机构未按照规定报告疑似预防接种异常反应、疫苗安全事件等，或者未按照规定对疑似预防接种异常反应组织调查、诊断等的，由县级以上人民政府卫生健康主管部门责令改正，给予警告；情节严重的，对接种单位、医疗机构处五万元以上五十万元以下的罚款，对疾病预防控制机构、接种单位、医疗机构的主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告直至撤职处分；造成严重后果的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予开除处分，由原发证部门吊销负有责任的医疗卫生人员的执业证书。\n第九十条 疾病预防控制机构、接种单位违反本法规定收取费用的，由县级以上人民政府卫生健康主管部门监督其将违法收取的费用退还给原缴费的单位或者个人，并由县级以上人民政府市场监督管理部门依法给予处罚。\n第九十一条 违反本法规定，未经县级以上地方人民政府卫生健康主管部门指定擅自从事免疫规划疫苗接种工作、从事非免疫规划疫苗接种工作不符合条件或者未备案的，由县级以上人民政府卫生健康主管部门责令改正，给予警告，没收违法所得和违法持有的疫苗，责令停业整顿，并处十万元以上一百万元以下的罚款，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予处分。\n违反本法规定，疾病预防控制机构、接种单位以外的单位或者个人擅自进行群体性预防接种的，由县级以上人民政府卫生健康主管部门责令改正，没收违法所得和违法持有的疫苗，并处违法持有的疫苗货值金额十倍以上三十倍以下的罚款，货值金额不足五万元的，按五万元计算。\n第九十二条 监护人未依法保证适龄儿童按时接种免疫规划疫苗的，由县级人民政府卫生健康主管部门批评教育，责令改正。\n托幼机构、学校在儿童入托、入学时未按照规定查验预防接种证，或者发现未按照规定接种的儿童后未向接种单位报告的，由县级以上地方人民政府教育行政部门责令改正，给予警告，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予处分。\n第九十三条 编造、散布虚假疫苗安全信息，或者在接种单位寻衅滋事，构成违反治安管理行为的，由公安机关依法给予治安管理处罚。\n报纸、期刊、广播、电视、互联网站等传播媒介编造、散布虚假疫苗安全信息的，由有关部门依法给予处罚，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予处分。\n第九十四条 县级以上地方人民政府在疫苗监督管理工作中有下列情形之一的，对直接负责的主管人员和其他直接责任人员依法给予降级或者撤职处分；情节严重的，依法给予开除处分；造成严重后果的，其主要负责人应当引咎辞职：\n（一）履行职责不力，造成严重不良影响或者重大损失；\n（二）瞒报、谎报、缓报、漏报疫苗安全事件；\n（三）干扰、阻碍对疫苗违法行为或者疫苗安全事件的调查；\n（四）本行政区域发生特别重大疫苗安全事故，或者连续发生重大疫苗安全事故。\n第九十五条 药品监督管理部门、卫生健康主管部门等部门在疫苗监督管理工作中有下列情形之一的，对直接负责的主管人员和其他直接责任人员依法给予降级或者撤职处分；情节严重的，依法给予开除处分；造成严重后果的，其主要负责人应当引咎辞职：\n（一）未履行监督检查职责，或者发现违法行为不及时查处；\n（二）擅自进行群体性预防接种；\n（三）瞒报、谎报、缓报、漏报疫苗安全事件；\n（四）干扰、阻碍对疫苗违法行为或者疫苗安全事件的调查；\n（五）泄露举报人的信息；\n（六）接到疑似预防接种异常反应相关报告，未按照规定组织调查、处理；\n（七）其他未履行疫苗监督管理职责的行为，造成严重不良影响或者重大损失。\n第九十六条 因疫苗质量问题造成受种者损害的，疫苗上市许可持有人应当依法承担赔偿责任。\n疾病预防控制机构、接种单位因违反预防接种工作规范、免疫程序、疫苗使用指导原则、接种方案，造成受种者损害的，应当依法承担赔偿责任。","level":1},{"name":"第十一章 附 则","text":"第九十七条 本法下列用语的含义是：\n免疫规划疫苗，是指居民应当按照政府的规定接种的疫苗，包括国家免疫规划确定的疫苗，省、自治区、直辖市人民政府在执行国家免疫规划时增加的疫苗，以及县级以上人民政府或者其卫生健康主管部门组织的应急接种或者群体性预防接种所使用的疫苗。\n非免疫规划疫苗，是指由居民自愿接种的其他疫苗。\n疫苗上市许可持有人，是指依法取得疫苗药品注册证书和药品生产许可证的企业。\n第九十八条 国家鼓励疫苗生产企业按照国际采购要求生产、出口疫苗。\n出口的疫苗应当符合进口国（地区）的标准或者合同要求。\n第九十九条 出入境预防接种及所需疫苗的采购，由国境卫生检疫机关商国务院财政部门另行规定。\n第一百条 本法自2019年12月1日起施行。","level":1}]},{"id":"n0292","sections":[{"name":"","text":"政务院关于中央人民政府所属各机关\n发表公报及公告性文件的办法\n(1950年发布)\n本院于一九四九年十二月九日颁布了关于统一发布中央人民政府及其所属各机关重要新闻的暂行办法，该办法规定：一切公告及公告性的新闻，均由新华通讯社统一发布。现为进一步加强新闻发表的效果及其准确性，特指定：凡属中央人民政府及其所属各机关的一切公告及公告性新闻，均应交由新华通讯社发布，并由《人民日报》负责刊载；如各种报刊所发表的文字有出入时，应以新华通讯社发布、《人民日报》刊载的文字为准。其办法如下：\n一、关于法令者：\n1．凡公告全国人民周知的重要法令，经政务院核定交新华通讯社发布后，《人民日报》应按其内容和重要性分别在各版发表；如有必要按一定日期刊出者，由政务院秘书厅注明。\n2．次要的法令如因《人民日报》篇幅拥挤得增刊发表；其中如有注明限期者必须如期刊出；未注明限期者，从接到稿件之日起，必须在一周之内刊出。\n3．仅与一部分人或一部分地区有关的法令，而无普遍周知之意义者，除由政务院指定新华通讯社通知有关地方的报纸全文发表外，得由《人民日报》在增刊发表或摘要发表。\n二、关于报告者：\n1．凡政务院指定要《人民日报》发表的重要报告，《人民日报》应依其内容性质和重要性分别在各版刊载，或增刊刊载。其有限期者，应如期发表。\n2．一般的工作总结报告等，得由《人民日报》摘要写成新闻或改为论文等形式发表；但因发布机关的工作需要而提出要求时，亦得由《人民日报》在增刊上全文发表。\n三、关于任命名单者：\n1．凡中央人民政府委员会会议通过的任命名单(连同履历)，《人民日报》应于一周内增刊全部发表。\n2．政务院政务会议通过的任命名单，一般的不在《人民日报》上发表；其重要者，经政务院批注，《人民日报》应照批注日期在新闻版或增刊上发表。","level":0}]},{"id":"n0293","sections":[{"name":"","text":"公安机关组织管理条例\n(2006年11月1日国务院第154次常务会议通过 2006年11月13日中华人民共和国国务院令第479号公布 自2007年1月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了规范公安机关组织管理，保障公安机关及其人民警察依法履行职责，根据《中华人民共和国公务员法》、《中华人民共和国人民警察法》，制定本条例。\n第二条 公安机关是人民民主专政的重要工具，人民警察是武装性质的国家治安行政力量和刑事司法力量，承担依法预防、制止和惩治违法犯罪活动，保护人民，服务经济社会发展，维护国家安全，维护社会治安秩序的职责。\n第三条 公安部在国务院领导下，主管全国的公安工作，是全国公安工作的领导、指挥机关。\n县级以上地方人民政府公安机关在本级人民政府领导下，负责本行政区域的公安工作，是本行政区域公安工作的领导、指挥机关。\n第四条 公安机关实行行政首长负责制。","level":1},{"name":"第二章 公安机关的设置","text":"第五条 县级以上人民政府公安机关依照法律、行政法规规定的权限和程序设置。\n第六条 设区的市公安局根据工作需要设置公安分局。市、县、自治县公安局根据工作需要设置公安派出所。\n公安分局和公安派出所的设立、撤销，按照规定的权限和程序审批。\n第七条 县级以上地方人民政府公安机关和公安分局内设机构分为综合管理机构和执法勤务机构。\n执法勤务机构实行队建制，称为总队、支队、大队、中队。\n第八条 县级以上地方人民政府公安机关和公安分局内设机构的设立、撤销，按照国家规定的权限和程序审批。\n第九条 看守所、拘留所、戒毒所、收容教育所依照法律、行政法规的规定设置。","level":1},{"name":"第三章 公安机关人民警察职务","text":"第十条 公安机关人民警察职务分为警官职务、警员职务和警务技术职务。\n第十一条 公安机关履行警务指挥职责的人民警察实行警官职务序列。\n公安机关领导成员和内设综合管理机构警官职务由高至低为：省部级正职、省部级副职、厅局级正职、厅局级副职、县处级正职、县处级副职、乡科级正职、乡科级副职。\n公安机关内设执法勤务机构警官职务由高至低为：总队长、副总队长、支队长、副支队长、大队长、副大队长、中队长、副中队长。\n县级以上地方人民政府公安机关派出机构、内设执法勤务机构和不设区的市、县、自治县公安局根据工作需要，可以设置主管政治工作的政治委员、教导员、指导员等警官职务。\n第十二条 公安机关履行警务执行职责的人民警察实行警员职务序列。\n公安机关及其内设综合管理机构警员职务由高至低为：巡视员、副巡视员、调研员、副调研员、主任科员、副主任科员、科员、办事员。\n公安机关内设执法勤务机构警员职务由高至低为：一级警长、二级警长、三级警长、四级警长、一级警员、二级警员、三级警员。\n第十三条 公安机关从事警务技术工作的人民警察实行警务技术职务序列。\n警务技术职务的设置，按照国家规定执行。\n第十四条 公安机关人民警察的级别，根据所任职务及其德才表现、工作实绩和资历确定。\n第十五条 公安机关人民警察职务与级别的对应关系，由国务院另行规定。\n第十六条 公安机关人民警察任职，应当符合国家规定的任职资格条件。\n第十七条 县级以上地方人民政府公安机关正职领导职务的提名，应当事先征得上一级公安机关的同意。\n县级以上地方人民政府公安机关副职领导职务的任免，应当事先征求上一级公安机关的意见。\n第十八条 公安机关内设机构警官职务、警员职务的任免，由本公安机关按照干部管理权限决定或者报批。\n公安分局领导成员职务以及公安派出所警官职务、警员职务的任免，由派出公安分局、公安派出所的公安机关决定。","level":1},{"name":"第四章 公安机关的编制和经费","text":"第十九条 公安机关人民警察使用的国家行政编制，实行专项管理。\n第二十条 公安部根据工作需要，向国务院机构编制管理机关提出公安机关编制的规划和调整编制的意见，由国务院机构编制管理机关审核，按照规定的权限和程序审批。\n第二十一条 省、自治区、直辖市人民政府根据工作需要，可以向国务院机构编制管理机关提出调整公安机关编制的申请。\n国务院机构编制管理机关对省、自治区、直辖市人民政府调整公安机关编制的申请，征求公安部意见后进行审核，按照规定的权限和程序审批。\n第二十二条 公安机关根据工作需要，经中央公务员主管部门或者省、自治区、直辖市公务员主管部门批准，可以对专业性较强的职位和辅助性职位实行聘任制。但是，对公安执法职位或者涉及国家秘密的职位，不实行聘任制。\n第二十三条 公安机关应当按照国家规定，将各项罚没收入和行政事业性收费收入全额上缴财政。\n县级以上人民政府按照国家规定的经费项目和标准，将公安机关经费列入财政预算，实行全额保障，并对经济困难地区的公安工作给予必要的经费支持。","level":1},{"name":"第五章 公安机关人民警察管理","text":"第二十四条 公安机关录用人民警察实行考试录用制度。\n公安机关录用的人民警察应当符合国家规定的条件。\n第二十五条 公安部机关及其实行公务员制度的直属机构人民警察录用考试，由中央公务员主管部门负责组织。\n县级以上地方人民政府公安机关人民警察录用考试，由省、自治区、直辖市公务员主管部门负责组织。县级以上地方人民政府公安机关按照国家规定，承担相应的录用工作。\n第二十六条 调任、转任到公安机关担任人民警察职务的，应当符合担任公安机关人民警察的条件和拟任职位所要求的资格条件。\n公安机关应当对调任、转任人选进行严格考察，并按照管理权限审批。必要时，可以对调任人选进行考试。\n第二十七条 公安机关人民警察实行警衔制度。公安机关授予警衔的人员应当是使用国家专项编制的在职人员。\n第二十八条 公安机关按照管理权限对人民警察进行考核。\n考核结果作为调整公安机关人民警察职务、级别、工资以及辞退、奖励、培训的依据。\n第二十九条 公安机关人民警察应当经过公安院校等人民警察培训机构培训并考试、考核合格，方可任职、晋升职务、授予警衔、晋升警衔。\n公安机关应当组织人民警察接受国家规定的培训。\n第三十条 公安机关人民警察有下列情形之一的，应当予以辞退：\n(一)在年度考核中，连续两年被确定为不称职的；\n(二)不胜任现职工作，又不接受其他安排的；\n(三)因所在公安机关调整、撤销、合并或者缩减编制员额需要调整工作，本人拒绝合理安排的；\n(四)不履行人民警察义务，不遵守人民警察纪律，经教育仍无转变，不适合继续在公安机关工作，又不宜给予开除处分的；\n(五)旷工或者因公外出、请假期满无正当理由逾期不归连续超过15天，或者1年内累计超过30天的。\n第三十一条 公安机关人民警察有下列情形之一的，不得辞退：\n(一)因公致残，被确认丧失或者部分丧失工作能力的；\n(二)患病或者负伤，在规定的医疗期内的；\n(三)女性人民警察在孕期、产假、哺乳期内的；\n(四)法律、行政法规规定的其他不得辞退的情形。\n第三十二条 公安机关人民警察个人或者集体在工作中表现突出，有显著成绩和特殊贡献的，应当根据国家规定给予奖励。\n奖励分为：嘉奖、记三等功、记二等功、记一等功、授予荣誉称号。\n对受奖励的公安机关人民警察，可以根据国家规定提前晋升警衔，并给予一次性奖金或者其他待遇。\n拟以国务院名义授予荣誉称号的，由人事部审核后报国务院审批；拟授予全国公安系统一级英雄模范称号的，由人事部会同公安部审批；拟授予全国公安系统二级英雄模范称号的，由公安部依据国家有关规定审批。\n第三十三条 公安机关人民警察违法违纪的，应当根据国家规定给予处分；构成犯罪的，依法追究刑事责任。\n处分分为：警告、记过、记大过、降级、撤职、开除。\n对受处分的公安机关人民警察，根据国家规定降低警衔或者取消警衔。\n对公安机关人民警察的处分由任免机关或者监察机关决定。\n第三十四条 公安机关人民警察对涉及本人的人事处理决定不服，或者认为有关部门及其领导人员侵犯其合法权益的，可以依法申请复核，提出申诉或者控告。","level":1},{"name":"第六章 公安机关人民警察待遇","text":"第三十五条 公安机关人民警察享受国家规定的符合其职业特点的工资待遇。\n第三十六条 公安机关人民警察实行国家规定的保险制度，保障其在退休、患病、工伤、生育、失业等情况下获得帮助和补偿。\n第三十七条 公安机关人民警察因公致残的，应当享受必要的治疗、康复，其中被评定残疾的人员享受国家规定的抚恤和优待。\n公安机关人民警察因公牺牲或者病故的，其家属享受国家规定的抚恤和优待。\n第三十八条 公安机关人民警察实行国家规定的工时制度和休假制度。\n公安机关人民警察在法定工作日之外工作的，应当补休；不能补休的，应当给予补助，具体办法由人事部会同财政部规定。\n第三十九条 公安机关人民警察达到国家规定的退休年龄或者完全丧失工作能力的，应当退休。\n公安机关人民警察符合国家规定的提前退休条件的，本人自愿提出申请，经任免机关批准，可以提前退休。\n第四十条 公安机关人民警察退休后，享受国家规定的退休金和其他福利待遇。","level":1},{"name":"第七章 附则","text":"第四十一条 新疆生产建设兵团的公安机关和经批准参照《中华人民共和国公务员法》管理的公安机关所属事业单位的组织管理，适用本条例。\n第四十二条 本条例自2007年1月1日起施行。","level":1}]},{"id":"n0294","sections":[{"name":"","text":"海关工作人员使用武器和警械的规定\n(1989年5月11日国务院批准 1989年6月19日海关总署、公安部令第7号发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》修订)\n第一条 为保证海关工作人员依法使用武器和警械，履行职责，根据《中华人民共和国海关法》第六条的规定，制定本规定。\n第二条 海关工作人员使用的武器和警械，经当地公安机关同意后由海关总署统一配发。海关工作人员执行缉私任务时，应当依照本规定使用武器和警械。\n海关工作人员使用的武器和警械包括：轻型枪支、电警棍、手铐及其他经批准列装的武器和警械。\n第三条 配发给海关的武器和警械一律公用，不配发个人专用的武器和警械。\n海关工作人员持枪执行缉私任务时，应当随身携带当地公安机关核发的持枪证或者持枪通行证。\n第四条 海关工作人员执行缉私任务，遇有下列情形之一的，可以开枪射击：\n(一)追缉逃跑的走私团伙或者遭遇武装掩护走私，非开枪不足以制服时；\n(二)走私分子或者走私嫌疑人以暴力抗拒检查，抢夺武器或者警械，威胁海关工作人员生命安全，非开枪不能自卫时；\n(三)走私分子或者走私嫌疑人以暴力劫夺查扣的走私货物、物品和其他证据，非开枪不能制止时。\n第五条 海关工作人员执行缉私任务，遇有下列情形之一的，可以使用警械：\n(一)走私分子或者走私嫌疑人以暴力抗拒检查或者逃跑时；\n(二)走私分子或者走私嫌疑人以暴力抗拒查扣走私货物、物品和其他证据时；\n(三)执行缉私任务受到袭击需要自卫时；\n(四)遇有其他需要使用警械的情形时。\n第六条 海关工作人员使用武器或者警械时，应当以制服对方为限度。海关工作人员依照本规定第四条的规定开枪射击时，除特别紧迫的情况外，应当先口头警告或者鸣枪警告，对方一有畏服表现，应当立即停止射击。开枪射击造成人员伤亡的，应当保护现场，并立即向上级海关和当地公安机关报告。\n第七条 海关工作人员违反本规定，滥用武器或者警械的，应当根据情节，依法追究有关人员的责任。\n第八条 本规定自发布之日起施行。","level":0}]},{"id":"n0295","sections":[{"name":"","text":"中华人民共和国\n渔港水域交通安全管理条例\n(1989年7月3日中华人民共和国国务院令第38号发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2017年10月7日《国务院关于修改部分行政法规的决定》第二次修订 根据2019年3月2日《国务院关于修改部分行政法规的决定》第三次修订)\n第一条 根据《中华人民共和国海上交通安全法》第四十八条的规定，制定本条例。\n第二条 本条例适用于在中华人民共和国沿海以渔业为主的渔港和渔港水域(以下简称“渔港”和“渔港水域”)航行、停泊、作业的船舶、设施和人员以及船舶、设施的所有者、经营者。\n第三条 中华人民共和国渔政渔港监督管理机关是对渔港水域交通安全实施监督管理的主管机关，并负责沿海水域渔业船舶之间交通事故的调查处理。\n第四条 本条例下列用语的含义是：\n渔港是指主要为渔业生产服务和供渔业船舶停泊、避风、装卸渔获物和补充渔需物资的人工港口或者自然港湾。\n渔港水域是指渔港的港池、锚地、避风湾和航道。\n渔业船舶是指从事渔业生产的船舶以及属于水产系统为渔业生产服务的船舶，包括捕捞船、养殖船、水产运销船、冷藏加工船、油船、供应船、渔业指导船、科研调查船、教学实习船、渔港工程船、拖轮、交通船、驳船、渔政船和渔监船。\n第五条 对渔港认定有不同意见的，依照港口隶属关系由县级以上人民政府确定。\n第六条 船舶进出渔港必须遵守渔港管理章程以及国际海上避碰规则，并依照规定向渔政渔港监督管理机关报告，接受安全检查。\n渔港内的船舶必须服从渔政渔港监督管理机关对水域交通安全秩序的管理。\n第七条 船舶在渔港内停泊、避风和装卸物资，不得损坏渔港的设施装备；造成损坏的应当向渔政渔港监督管理机关报告，并承担赔偿责任。\n第八条 船舶在渔港内装卸易燃、易爆、有毒等危险货物，必须遵守国家关于危险货物管理的规定，并事先向渔政渔港监督管理机关提出申请，经批准后在指定的安全地点装卸。\n第九条 在渔港内新建、改建、扩建各种设施，或者进行其他水上、水下施工作业，除依照国家规定履行审批手续外，应当报请渔政渔港监督管理机关批准。渔政渔港监督管理机关批准后，应当事先发布航行通告。\n第十条 在渔港内的航道、港池、锚地和停泊区，禁止从事有碍海上交通安全的捕捞、养殖等生产活动。\n第十一条 国家公务船舶在执行公务时进出渔港，经通报渔政渔港监督管理机关，可免于检查。渔政渔港监督管理机关应当对执行海上巡视任务的国家公务船舶的靠岸、停泊和补给提供方便。\n第十二条 渔业船舶在向渔政渔港监督管理机关申请船舶登记，并取得渔业船舶国籍证书或者渔业船舶登记证书后，方可悬挂中华人民共和国国旗航行。\n第十三条 渔业船舶必须经船舶检验部门检验合格，取得船舶技术证书，方可从事渔业生产。\n第十四条 渔业船舶的船长、轮机长、驾驶员、轮机员、电机员、无线电报务员、话务员，必须经渔政渔港监督管理机关考核合格，取得职务证书，其他人员应当经过相应的专业训练。\n第十五条 地方各级人民政府应当加强本行政区域内渔业船舶船员的技术培训工作。国营、集体所有的渔业船舶，其船员的技术培训由渔业船舶所属单位负责；个人所有的渔业船舶，其船员的技术培训由当地人民政府渔业行政主管部门负责。\n第十六条 渔业船舶之间发生交通事故，应当向就近的渔政渔港监督管理机关报告，并在进入第一个港口48小时之内向渔政渔港监督管理机关递交事故报告书和有关材料，接受调查处理。\n第十七条 渔政渔港监督管理机关对渔港水域内的交通事故和其他沿海水域渔业船舶之间的交通事故，应当及时查明原因，判明责任，作出处理决定。\n第十八条 渔港内的船舶、设施有下列情形之一的，渔政渔港监督管理机关有权禁止其离港，或者令其停航、改航、停止作业：\n(一)违反中华人民共和国法律、法规或者规章的；\n(二)处于不适航或者不适拖状态的；\n(三)发生交通事故，手续未清的；\n(四)未向渔政渔港监督管理机关或者有关部门交付应当承担的费用，也未提供担保的；\n(五)渔政渔港监督管理机关认为有其他妨害或者可能妨害海上交通安全的。\n第十九条 渔港内的船舶、设施发生事故，对海上交通安全造成或者可能造成危害，渔政渔港监督管理机关有权对其采取强制性处置措施。\n第二十条 船舶进出渔港依照规定应当向渔政渔港监督管理机关报告而未报告的，或者在渔港内不服从渔政渔港监督管理机关对水域交通安全秩序管理的，由渔政渔港监督管理机关责令改正，可以并处警告、罚款；情节严重的，扣留或者吊销船长职务证书(扣留职务证书时间最长不超过6个月，下同)。\n第二十一条 违反本条例规定，有下列行为之一的，由渔政渔港监督管理机关责令停止违法行为，可以并处警告、罚款；造成损失的，应当承担赔偿责任；对直接责任人员由其所在单位或者上级主管机关给予行政处分：\n(一)未经渔政渔港监督管理机关批准或者未按照批准文件的规定，在渔港内装卸易燃、易爆、有毒等危险货物的；\n(二)未经渔政渔港监督管理机关批准，在渔港内新建、改建、扩建各种设施或者进行其他水上、水下施工作业的；\n(三)在渔港内的航道、港池、锚地和停泊区从事有碍海上交通安全的捕捞、养殖等生产活动的。\n第二十二条 违反本条例规定，未持有船舶证书或者未配齐船员的，由渔政渔港监督管理机关责令改正，可以并处罚款。\n第二十三条 违反本条例规定，不执行渔政渔港监督管理机关作出的离港、停航、改航、停止作业的决定，或者在执行中违反上述决定的，由渔政渔港监督管理机关责令改正，可以并处警告、罚款；情节严重的，扣留或者吊销船长职务证书。\n第二十四条 当事人对渔政渔港监督管理机关作出的行政处罚决定不服的，可以在接到处罚通知之日起15日内向人民法院起诉；期满不起诉又不履行的，由渔政渔港监督管理机关申请人民法院强制执行。\n第二十五条 因渔港水域内发生的交通事故或者其他沿海水域发生的渔业船舶之间的交通事故引起的民事纠纷，可以由渔政渔港监督管理机关调解处理；调解不成或者不愿意调解的，当事人可以向人民法院起诉。\n第二十六条 拒绝、阻碍渔政渔港监督管理工作人员依法执行公务，应当给予治安管理处罚的，由公安机关依照《中华人民共和国治安管理处罚法》有关规定处罚；构成犯罪的，由司法机关依法追究刑事责任。\n第二十七条 渔政渔港监督管理工作人员，在渔港和渔港水域交通安全监督管理工作中，玩忽职守，滥用职权、徇私舞弊的，由其所在单位或者上级主管机关给予行政处分；构成犯罪的，由司法机关依法追究刑事责任。\n第二十八条 本条例实施细则由农业农村部制定。\n第二十九条 本条例自1989年8月1日起施行。","level":0}]},{"id":"n0296","sections":[{"name":"","text":"期货交易管理条例\n(2007年3月6日中华人民共和国国务院令第489号公布 根据2012年10月24日《国务院关于修改〈期货交易管理条例〉的决定》第一次修订 根据2013年7月18日《国务院关于废止和修改部分行政法规的决定》第二次修订 根据2016年2月6日《国务院关于修改部分行政法规的决定》第三次修订 根据2017年3月1日《国务院关于修改和废止部分行政法规的决定》第四次修订)","level":0},{"name":"第一章 总则","text":"第一条 为了规范期货交易行为，加强对期货交易的监督管理，维护期货市场秩序，防范风险，保护期货交易各方的合法权益和社会公共利益，促进期货市场积极稳妥发展，制定本条例。\n第二条 任何单位和个人从事期货交易及其相关活动，应当遵守本条例。\n本条例所称期货交易，是指采用公开的集中交易方式或者国务院期货监督管理机构批准的其他方式进行的以期货合约或者期权合约为交易标的的交易活动。\n本条例所称期货合约，是指期货交易场所统一制定的、规定在将来某一特定的时间和地点交割一定数量标的物的标准化合约。期货合约包括商品期货合约和金融期货合约及其他期货合约。\n本条例所称期权合约，是指期货交易场所统一制定的、规定买方有权在将来某一时间以特定价格买入或者卖出约定标的物(包括期货合约)的标准化合约。\n第三条 从事期货交易活动，应当遵循公开、公平、公正和诚实信用的原则。禁止欺诈、内幕交易和操纵期货交易价格等违法行为。\n第四条 期货交易应当在依照本条例第六条第一款规定设立的期货交易所、国务院批准的或者国务院期货监督管理机构批准的其他期货交易场所进行。\n禁止在前款规定的期货交易场所之外进行期货交易。\n第五条 国务院期货监督管理机构对期货市场实行集中统一的监督管理。\n国务院期货监督管理机构派出机构依照本条例的有关规定和国务院期货监督管理机构的授权，履行监督管理职责。","level":1},{"name":"第二章 期货交易所","text":"第六条 设立期货交易所，由国务院期货监督管理机构审批。\n未经国务院批准或者国务院期货监督管理机构批准，任何单位或者个人不得设立期货交易场所或者以任何形式组织期货交易及其相关活动。\n第七条 期货交易所不以营利为目的，按照其章程的规定实行自律管理。期货交易所以其全部财产承担民事责任。期货交易所的负责人由国务院期货监督管理机构任免。\n期货交易所的管理办法由国务院期货监督管理机构制定。\n第八条 期货交易所会员应当是在中华人民共和国境内登记注册的企业法人或者其他经济组织。\n期货交易所可以实行会员分级结算制度。实行会员分级结算制度的期货交易所会员由结算会员和非结算会员组成。\n第九条 有《中华人民共和国公司法》第一百四十六条规定的情形或者下列情形之一的，不得担任期货交易所的负责人、财务会计人员：\n(一)因违法行为或者违纪行为被解除职务的期货交易所、证券交易所、证券登记结算机构的负责人，或者期货公司、证券公司的董事、监事、高级管理人员，以及国务院期货监督管理机构规定的其他人员，自被解除职务之日起未逾5年；\n(二)因违法行为或者违纪行为被撤销资格的律师、注册会计师或者投资咨询机构、财务顾问机构、资信评级机构、资产评估机构、验证机构的专业人员，自被撤销资格之日起未逾5年。\n第十条 期货交易所应当依照本条例和国务院期货监督管理机构的规定，建立、健全各项规章制度，加强对交易活动的风险控制和对会员以及交易所工作人员的监督管理。期货交易所履行下列职责：\n(一)提供交易的场所、设施和服务；\n(二)设计合约，安排合约上市；\n(三)组织并监督交易、结算和交割；\n(四)为期货交易提供集中履约担保；\n(五)按照章程和交易规则对会员进行监督管理；\n(六)国务院期货监督管理机构规定的其他职责。\n期货交易所不得直接或者间接参与期货交易。未经国务院期货监督管理机构审核并报国务院批准，期货交易所不得从事信托投资、股票投资、非自用不动产投资等与其职责无关的业务。\n第十一条 期货交易所应当按照国家有关规定建立、健全下列风险管理制度：\n(一)保证金制度；\n(二)当日无负债结算制度；\n(三)涨跌停板制度；\n(四)持仓限额和大户持仓报告制度；\n(五)风险准备金制度；\n(六)国务院期货监督管理机构规定的其他风险管理制度。\n实行会员分级结算制度的期货交易所，还应当建立、健全结算担保金制度。\n第十二条 当期货市场出现异常情况时，期货交易所可以按照其章程规定的权限和程序，决定采取下列紧急措施，并应当立即报告国务院期货监督管理机构：\n(一)提高保证金；\n(二)调整涨跌停板幅度；\n(三)限制会员或者客户的最大持仓量；\n(四)暂时停止交易；\n(五)采取其他紧急措施。\n前款所称异常情况，是指在交易中发生操纵期货交易价格的行为或者发生不可抗拒的突发事件以及国务院期货监督管理机构规定的其他情形。\n异常情况消失后，期货交易所应当及时取消紧急措施。\n第十三条 期货交易所办理下列事项，应当经国务院期货监督管理机构批准：\n(一)制定或者修改章程、交易规则；\n(二)上市、中止、取消或者恢复交易品种；\n(三)国务院期货监督管理机构规定的其他事项。\n国务院期货监督管理机构批准期货交易所上市新的交易品种，应当征求国务院有关部门的意见。\n第十四条 期货交易所的所得收益按照国家有关规定管理和使用，但应当首先用于保证期货交易场所、设施的运行和改善。","level":1},{"name":"第三章 期货公司","text":"第十五条 期货公司是依照《中华人民共和国公司法》和本条例规定设立的经营期货业务的金融机构。设立期货公司，应当在公司登记机关登记注册，并经国务院期货监督管理机构批准。\n未经国务院期货监督管理机构批准，任何单位或者个人不得设立或者变相设立期货公司，经营期货业务。\n第十六条 申请设立期货公司，应当符合《中华人民共和国公司法》的规定，并具备下列条件：\n(一)注册资本最低限额为人民币3000万元；\n(二)董事、监事、高级管理人员具备任职条件，从业人员具有期货从业资格；\n(三)有符合法律、行政法规规定的公司章程；\n(四)主要股东以及实际控制人具有持续盈利能力，信誉良好，最近3年无重大违法违规记录；\n(五)有合格的经营场所和业务设施；\n(六)有健全的风险管理和内部控制制度；\n(七)国务院期货监督管理机构规定的其他条件。\n国务院期货监督管理机构根据审慎监管原则和各项业务的风险程度，可以提高注册资本最低限额。注册资本应当是实缴资本。股东应当以货币或者期货公司经营必需的非货币财产出资，货币出资比例不得低于85%。\n国务院期货监督管理机构应当在受理期货公司设立申请之日起6个月内，根据审慎监管原则进行审查，作出批准或者不批准的决定。\n未经国务院期货监督管理机构批准，任何单位和个人不得委托或者接受他人委托持有或者管理期货公司的股权。\n第十七条 期货公司业务实行许可制度，由国务院期货监督管理机构按照其商品期货、金融期货业务种类颁发许可证。期货公司除申请经营境内期货经纪业务外，还可以申请经营境外期货经纪、期货投资咨询以及国务院期货监督管理机构规定的其他期货业务。\n期货公司不得从事与期货业务无关的活动，法律、行政法规或者国务院期货监督管理机构另有规定的除外。\n期货公司不得从事或者变相从事期货自营业务。\n期货公司不得为其股东、实际控制人或者其他关联人提供融资，不得对外担保。\n第十八条 期货公司从事经纪业务，接受客户委托，以自己的名义为客户进行期货交易，交易结果由客户承担。\n第十九条 期货公司办理下列事项，应当经国务院期货监督管理机构批准：\n(一)合并、分立、停业、解散或者破产；\n(二)变更业务范围；\n(三)变更注册资本且调整股权结构；\n(四)新增持有5%以上股权的股东或者控股股东发生变化；\n(五)国务院期货监督管理机构规定的其他事项。\n前款第三项、第五项所列事项，国务院期货监督管理机构应当自受理申请之日起20日内作出批准或者不批准的决定；前款所列其他事项，国务院期货监督管理机构应当自受理申请之日起2个月内作出批准或者不批准的决定。\n第二十条 期货公司或者其分支机构有《中华人民共和国行政许可法》第七十条规定的情形或者下列情形之一的，国务院期货监督管理机构应当依法办理期货业务许可证注销手续：\n(一)营业执照被公司登记机关依法注销；\n(二)成立后无正当理由超过3个月未开始营业，或者开业后无正当理由停业连续3个月以上；\n(三)主动提出注销申请；\n(四)国务院期货监督管理机构规定的其他情形。\n期货公司在注销期货业务许可证前，应当结清相关期货业务，并依法返还客户的保证金和其他资产。期货公司分支机构在注销经营许可证前，应当终止经营活动，妥善处理客户资产。\n第二十一条 期货公司应当建立、健全并严格执行业务管理规则、风险管理制度，遵守信息披露制度，保障客户保证金的存管安全，按照期货交易所的规定，向期货交易所报告大户名单、交易情况。\n第二十二条 其他期货经营机构从事期货投资咨询业务，应当遵守国务院期货监督管理机构的规定。","level":1},{"name":"第四章 期货交易基本规则","text":"第二十三条 在期货交易所进行期货交易的，应当是期货交易所会员。\n符合规定条件的境外机构，可以在期货交易所从事特定品种的期货交易。具体办法由国务院期货监督管理机构制定。\n第二十四条 期货公司接受客户委托为其进行期货交易，应当事先向客户出示风险说明书，经客户签字确认后，与客户签订书面合同。期货公司不得未经客户委托或者不按照客户委托内容，擅自进行期货交易。\n期货公司不得向客户作获利保证；不得在经纪业务中与客户约定分享利益或者共担风险。\n第二十五条 下列单位和个人不得从事期货交易，期货公司不得接受其委托为其进行期货交易：\n(一)国家机关和事业单位；\n(二)国务院期货监督管理机构、期货交易所、期货保证金安全存管监控机构和期货业协会的工作人员；\n(三)证券、期货市场禁止进入者；\n(四)未能提供开户证明材料的单位和个人；\n(五)国务院期货监督管理机构规定不得从事期货交易的其他单位和个人。\n第二十六条 客户可以通过书面、电话、互联网或者国务院期货监督管理机构规定的其他方式，向期货公司下达交易指令。客户的交易指令应当明确、全面。\n期货公司不得隐瞒重要事项或者使用其他不正当手段诱骗客户发出交易指令。\n第二十七条 期货交易所应当及时公布上市品种合约的成交量、成交价、持仓量、最高价与最低价、开盘价与收盘价和其他应当公布的即时行情，并保证即时行情的真实、准确。期货交易所不得发布价格预测信息。\n未经期货交易所许可，任何单位和个人不得发布期货交易即时行情。\n第二十八条 期货交易应当严格执行保证金制度。期货交易所向会员、期货公司向客户收取的保证金，不得低于国务院期货监督管理机构、期货交易所规定的标准，并应当与自有资金分开，专户存放。\n期货交易所向会员收取的保证金，属于会员所有，除用于会员的交易结算外，严禁挪作他用。\n期货公司向客户收取的保证金，属于客户所有，除下列可划转的情形外，严禁挪作他用：\n(一)依据客户的要求支付可用资金；\n(二)为客户交存保证金，支付手续费、税款；\n(三)国务院期货监督管理机构规定的其他情形。\n第二十九条 期货公司应当为每一个客户单独开立专门账户、设置交易编码，不得混码交易。\n第三十条 期货公司经营期货经纪业务又同时经营其他期货业务的，应当严格执行业务分离和资金分离制度，不得混合操作。\n第三十一条 期货交易所、期货公司、非期货公司结算会员应当按照国务院期货监督管理机构、财政部门的规定提取、管理和使用风险准备金，不得挪用。\n第三十二条 期货交易的收费项目、收费标准和管理办法由国务院有关主管部门统一制定并公布。\n第三十三条 期货交易的结算，由期货交易所统一组织进行。\n期货交易所实行当日无负债结算制度。期货交易所应当在当日及时将结算结果通知会员。\n期货公司根据期货交易所的结算结果对客户进行结算，并应当将结算结果按照与客户约定的方式及时通知客户。客户应当及时查询并妥善处理自己的交易持仓。\n第三十四条 期货交易所会员的保证金不足时，应当及时追加保证金或者自行平仓。会员未在期货交易所规定的时间内追加保证金或者自行平仓的，期货交易所应当将该会员的合约强行平仓，强行平仓的有关费用和发生的损失由该会员承担。\n客户保证金不足时，应当及时追加保证金或者自行平仓。客户未在期货公司规定的时间内及时追加保证金或者自行平仓的，期货公司应当将该客户的合约强行平仓，强行平仓的有关费用和发生的损失由该客户承担。\n第三十五条 期货交易的交割，由期货交易所统一组织进行。\n交割仓库由期货交易所指定。期货交易所不得限制实物交割总量，并应当与交割仓库签订协议，明确双方的权利和义务。交割仓库不得有下列行为：\n(一)出具虚假仓单；\n(二)违反期货交易所业务规则，限制交割商品的入库、出库；\n(三)泄露与期货交易有关的商业秘密；\n(四)违反国家有关规定参与期货交易；\n(五)国务院期货监督管理机构规定的其他行为。\n第三十六条 会员在期货交易中违约的，期货交易所先以该会员的保证金承担违约责任；保证金不足的，期货交易所应当以风险准备金和自有资金代为承担违约责任，并由此取得对该会员的相应追偿权。\n客户在期货交易中违约的，期货公司先以该客户的保证金承担违约责任；保证金不足的，期货公司应当以风险准备金和自有资金代为承担违约责任，并由此取得对该客户的相应追偿权。\n第三十七条 实行会员分级结算制度的期货交易所，应当向结算会员收取结算担保金。期货交易所只对结算会员结算，收取和追收保证金，以结算担保金、风险准备金、自有资金代为承担违约责任，以及采取其他相关措施；对非结算会员的结算、收取和追收保证金、代为承担违约责任，以及采取其他相关措施，由结算会员执行。\n第三十八条 期货交易所、期货公司和非期货公司结算会员应当保证期货交易、结算、交割资料的完整和安全。\n第三十九条 任何单位或者个人不得编造、传播有关期货交易的虚假信息，不得恶意串通、联手买卖或者以其他方式操纵期货交易价格。\n第四十条 任何单位或者个人不得违规使用信贷资金、财政资金进行期货交易。\n银行业金融机构从事期货交易融资或者担保业务的资格，由国务院银行业监督管理机构批准。\n第四十一条 国有以及国有控股企业进行境内外期货交易，应当遵循套期保值的原则，严格遵守国务院国有资产监督管理机构以及其他有关部门关于企业以国有资产进入期货市场的有关规定。\n第四十二条 境外期货项下购汇、结汇以及外汇收支，应当符合国家外汇管理有关规定。\n境内单位或者个人从事境外期货交易的办法，由国务院期货监督管理机构会同国务院商务主管部门、国有资产监督管理机构、银行业监督管理机构、外汇管理部门等有关部门制订，报国务院批准后施行。","level":1},{"name":"第五章 期货业协会","text":"第四十三条 期货业协会是期货业的自律性组织，是社会团体法人。\n期货公司以及其他专门从事期货经营的机构应当加入期货业协会，并缴纳会员费。\n第四十四条 期货业协会的权力机构为全体会员组成的会员大会。\n期货业协会的章程由会员大会制定，并报国务院期货监督管理机构备案。\n期货业协会设理事会。理事会成员按照章程的规定选举产生。\n第四十五条 期货业协会履行下列职责：\n(一)教育和组织会员遵守期货法律法规和政策；\n(二)制定会员应当遵守的行业自律性规则，监督、检查会员行为，对违反协会章程和自律性规则的，按照规定给予纪律处分；\n(三)负责期货从业人员资格的认定、管理以及撤销工作；\n(四)受理客户与期货业务有关的投诉，对会员之间、会员与客户之间发生的纠纷进行调解；\n(五)依法维护会员的合法权益，向国务院期货监督管理机构反映会员的建议和要求；\n(六)组织期货从业人员的业务培训，开展会员间的业务交流；\n(七)组织会员就期货业的发展、运作以及有关内容进行研究；\n(八)期货业协会章程规定的其他职责。\n期货业协会的业务活动应当接受国务院期货监督管理机构的指导和监督。","level":1},{"name":"第六章 监督管理","text":"第四十六条 国务院期货监督管理机构对期货市场实施监督管理，依法履行下列职责：\n(一)制定有关期货市场监督管理的规章、规则，并依法行使审批权；\n(二)对品种的上市、交易、结算、交割等期货交易及其相关活动，进行监督管理；\n(三)对期货交易所、期货公司及其他期货经营机构、非期货公司结算会员、期货保证金安全存管监控机构、期货保证金存管银行、交割仓库等市场相关参与者的期货业务活动，进行监督管理；\n(四)制定期货从业人员的资格标准和管理办法，并监督实施；\n(五)监督检查期货交易的信息公开情况；\n(六)对期货业协会的活动进行指导和监督；\n(七)对违反期货市场监督管理法律、行政法规的行为进行查处；\n(八)开展与期货市场监督管理有关的国际交流、合作活动；\n(九)法律、行政法规规定的其他职责。\n第四十七条 国务院期货监督管理机构依法履行职责，可以采取下列措施：\n(一)对期货交易所、期货公司及其他期货经营机构、非期货公司结算会员、期货保证金安全存管监控机构和交割仓库进行现场检查；\n(二)进入涉嫌违法行为发生场所调查取证；\n(三)询问当事人和与被调查事件有关的单位和个人，要求其对与被调查事件有关的事项作出说明；\n(四)查阅、复制与被调查事件有关的财产权登记等资料；\n(五)查阅、复制当事人和与被调查事件有关的单位和个人的期货交易记录、财务会计资料以及其他相关文件和资料；对可能被转移、隐匿或者毁损的文件和资料，可以予以封存；\n(六)查询与被调查事件有关的单位的保证金账户和银行账户；\n(七)在调查操纵期货交易价格、内幕交易等重大期货违法行为时，经国务院期货监督管理机构主要负责人批准，可以限制被调查事件当事人的期货交易，但限制的时间不得超过15个交易日；案情复杂的，可以延长至30个交易日；\n(八)法律、行政法规规定的其他措施。\n第四十八条 期货交易所、期货公司及其他期货经营机构、期货保证金安全存管监控机构，应当向国务院期货监督管理机构报送财务会计报告、业务资料和其他有关资料。\n对期货公司及其他期货经营机构报送的年度报告，国务院期货监督管理机构应当指定专人进行审核，并制作审核报告。审核人员应当在审核报告上签字。审核中发现问题的，国务院期货监督管理机构应当及时采取相应措施。\n必要时，国务院期货监督管理机构可以要求非期货公司结算会员、交割仓库，以及期货公司股东、实际控制人或者其他关联人报送相关资料。\n第四十九条 国务院期货监督管理机构依法履行职责，进行监督检查或者调查时，被检查、调查的单位和个人应当配合，如实提供有关文件和资料，不得拒绝、阻碍和隐瞒；其他有关部门和单位应当给予支持和配合。\n第五十条 国家根据期货市场发展的需要，设立期货投资者保障基金。\n期货投资者保障基金的筹集、管理和使用的具体办法，由国务院期货监督管理机构会同国务院财政部门制定。\n第五十一条 国务院期货监督管理机构应当建立、健全保证金安全存管监控制度，设立期货保证金安全存管监控机构。\n客户和期货交易所、期货公司及其他期货经营机构、非期货公司结算会员以及期货保证金存管银行，应当遵守国务院期货监督管理机构有关保证金安全存管监控的规定。\n第五十二条 期货保证金安全存管监控机构依照有关规定对保证金安全实施监控，进行每日稽核，发现问题应当立即报告国务院期货监督管理机构。国务院期货监督管理机构应当根据不同情况，依照本条例有关规定及时处理。\n第五十三条 国务院期货监督管理机构对期货交易所和期货保证金安全存管监控机构的董事、监事、高级管理人员，实行资格管理制度。\n第五十四条 国务院期货监督管理机构应当制定期货公司持续性经营规则，对期货公司的净资本与净资产的比例，净资本与境内期货经纪、境外期货经纪等业务规模的比例，流动资产与流动负债的比例等风险监管指标作出规定；对期货公司及其分支机构的经营条件、风险管理、内部控制、保证金存管、关联交易等方面提出要求。\n第五十五条 期货公司及其分支机构不符合持续性经营规则或者出现经营风险的，国务院期货监督管理机构可以对期货公司及其董事、监事和高级管理人员采取谈话、提示、记入信用记录等监管措施或者责令期货公司限期整改，并对其整改情况进行检查验收。\n期货公司逾期未改正，其行为严重危及期货公司的稳健运行、损害客户合法权益，或者涉嫌严重违法违规正在被国务院期货监督管理机构调查的，国务院期货监督管理机构可以区别情形，对其采取下列措施：\n(一)限制或者暂停部分期货业务；\n(二)停止批准新增业务；\n(三)限制分配红利，限制向董事、监事、高级管理人员支付报酬、提供福利；\n(四)限制转让财产或者在财产上设定其他权利；\n(五)责令更换董事、监事、高级管理人员或者有关业务部门、分支机构的负责人员，或者限制其权利；\n(六)限制期货公司自有资金或者风险准备金的调拨和使用；\n(七)责令控股股东转让股权或者限制有关股东行使股东权利。\n对经过整改符合有关法律、行政法规规定以及持续性经营规则要求的期货公司，国务院期货监督管理机构应当自验收完毕之日起3日内解除对其采取的有关措施。\n对经过整改仍未达到持续性经营规则要求，严重影响正常经营的期货公司，国务院期货监督管理机构有权撤销其部分或者全部期货业务许可、关闭其分支机构。\n第五十六条 期货公司违法经营或者出现重大风险，严重危害期货市场秩序、损害客户利益的，国务院期货监督管理机构可以对该期货公司采取责令停业整顿、指定其他机构托管或者接管等监管措施。经国务院期货监督管理机构批准，可以对该期货公司直接负责的董事、监事、高级管理人员和其他直接责任人员采取以下措施：\n(一)通知出境管理机关依法阻止其出境；\n(二)申请司法机关禁止其转移、转让或者以其他方式处分财产，或者在财产上设定其他权利。\n第五十七条 期货公司的股东有虚假出资或者抽逃出资行为的，国务院期货监督管理机构应当责令其限期改正，并可责令其转让所持期货公司的股权。\n在股东按照前款要求改正违法行为、转让所持期货公司的股权前，国务院期货监督管理机构可以限制其股东权利。\n第五十八条 当期货市场出现异常情况时，国务院期货监督管理机构可以采取必要的风险处置措施。\n第五十九条 期货公司的交易软件、结算软件，应当满足期货公司审慎经营和风险管理以及国务院期货监督管理机构有关保证金安全存管监控规定的要求。期货公司的交易软件、结算软件不符合要求的，国务院期货监督管理机构有权要求期货公司予以改进或者更换。\n国务院期货监督管理机构可以要求期货公司的交易软件、结算软件的供应商提供该软件的相关资料，供应商应当予以配合。国务院期货监督管理机构对供应商提供的相关资料负有保密义务。\n第六十条 期货公司涉及重大诉讼、仲裁，或者股权被冻结或者用于担保，以及发生其他重大事件时，期货公司及其相关股东、实际控制人应当自该事件发生之日起5日内向国务院期货监督管理机构提交书面报告。\n第六十一条 会计师事务所、律师事务所、资产评估机构等中介服务机构向期货交易所和期货公司等市场相关参与者提供相关服务时，应当遵守期货法律、行政法规以及国家有关规定，并按照国务院期货监督管理机构的要求提供相关资料。\n第六十二条 国务院期货监督管理机构应当与有关部门建立监督管理的信息共享和协调配合机制。\n国务院期货监督管理机构可以和其他国家或者地区的期货监督管理机构建立监督管理合作机制，实施跨境监督管理。\n第六十三条 国务院期货监督管理机构、期货交易所、期货保证金安全存管监控机构和期货保证金存管银行等相关单位的工作人员，应当忠于职守，依法办事，公正廉洁，保守国家秘密和有关当事人的商业秘密，不得利用职务便利牟取不正当的利益。","level":1},{"name":"第七章 法律责任","text":"第六十四条 期货交易所、非期货公司结算会员有下列行为之一的，责令改正，给予警告，没收违法所得：\n(一)违反规定接纳会员的；\n(二)违反规定收取手续费的；\n(三)违反规定使用、分配收益的；\n(四)不按照规定公布即时行情的，或者发布价格预测信息的；\n(五)不按照规定向国务院期货监督管理机构履行报告义务的；\n(六)不按照规定向国务院期货监督管理机构报送有关文件、资料的；\n(七)不按照规定建立、健全结算担保金制度的；\n(八)不按照规定提取、管理和使用风险准备金的；\n(九)违反国务院期货监督管理机构有关保证金安全存管监控规定的；\n(十)限制会员实物交割总量的；\n(十一)任用不具备资格的期货从业人员的；\n(十二)违反国务院期货监督管理机构规定的其他行为。\n有前款所列行为之一的，对直接负责的主管人员和其他直接责任人员给予纪律处分，处1万元以上10万元以下的罚款。\n有本条第一款第二项所列行为的，应当责令退还多收取的手续费。\n期货保证金安全存管监控机构有本条第一款第五项、第六项、第九项、第十一项、第十二项所列行为的，依照本条第一款、第二款的规定处罚、处分。期货保证金存管银行有本条第一款第九项、第十二项所列行为的，依照本条第一款、第二款的规定处罚、处分。\n第六十五条 期货交易所有下列行为之一的，责令改正，给予警告，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不满10万元的，并处10万元以上50万元以下的罚款；情节严重的，责令停业整顿：\n(一)未经批准，擅自办理本条例第十三条所列事项的；\n(二)允许会员在保证金不足的情况下进行期货交易的；\n(三)直接或者间接参与期货交易，或者违反规定从事与其职责无关的业务的；\n(四)违反规定收取保证金，或者挪用保证金的；\n(五)伪造、涂改或者不按照规定保存期货交易、结算、交割资料的；\n(六)未建立或者未执行当日无负债结算、涨跌停板、持仓限额和大户持仓报告制度的；\n(七)拒绝或者妨碍国务院期货监督管理机构监督检查的；\n(八)违反国务院期货监督管理机构规定的其他行为。\n有前款所列行为之一的，对直接负责的主管人员和其他直接责任人员给予纪律处分，处1万元以上10万元以下的罚款。\n非期货公司结算会员有本条第一款第二项、第四项至第八项所列行为之一的，依照本条第一款、第二款的规定处罚、处分。\n期货保证金安全存管监控机构有本条第一款第三项、第七项、第八项所列行为的，依照本条第一款、第二款的规定处罚、处分。\n第六十六条 期货公司有下列行为之一的，责令改正，给予警告，没收违法所得，并处违法所得1倍以上3倍以下的罚款；没有违法所得或者违法所得不满10万元的，并处10万元以上30万元以下的罚款；情节严重的，责令停业整顿或者吊销期货业务许可证：\n(一)接受不符合规定条件的单位或者个人委托的；\n(二)允许客户在保证金不足的情况下进行期货交易的；\n(三)未经批准，擅自办理本条例第十九条所列事项的；\n(四)违反规定从事与期货业务无关的活动的；\n(五)从事或者变相从事期货自营业务的；\n(六)为其股东、实际控制人或者其他关联人提供融资，或者对外担保的；\n(七)违反国务院期货监督管理机构有关保证金安全存管监控规定的；\n(八)不按照规定向国务院期货监督管理机构履行报告义务或者报送有关文件、资料的；\n(九)交易软件、结算软件不符合期货公司审慎经营和风险管理以及国务院期货监督管理机构有关保证金安全存管监控规定的要求的；\n(十)不按照规定提取、管理和使用风险准备金的；\n(十一)伪造、涂改或者不按照规定保存期货交易、结算、交割资料的；\n(十二)任用不具备资格的期货从业人员的；\n(十三)伪造、变造、出租、出借、买卖期货业务许可证或者经营许可证的；\n(十四)进行混码交易的；\n(十五)拒绝或者妨碍国务院期货监督管理机构监督检查的；\n(十六)违反国务院期货监督管理机构规定的其他行为。\n期货公司有前款所列行为之一的，对直接负责的主管人员和其他直接责任人员给予警告，并处1万元以上5万元以下的罚款；情节严重的，暂停或者撤销期货从业人员资格。\n期货公司之外的其他期货经营机构有本条第一款第八项、第十二项、第十三项、第十五项、第十六项所列行为的，依照本条第一款、第二款的规定处罚。\n期货公司的股东、实际控制人或者其他关联人未经批准擅自委托他人或者接受他人委托持有或者管理期货公司股权的，拒不配合国务院期货监督管理机构的检查，拒不按照规定履行报告义务、提供有关信息和资料，或者报送、提供的信息和资料有虚假记载、误导性陈述或者重大遗漏的，依照本条第一款、第二款的规定处罚。\n第六十七条 期货公司有下列欺诈客户行为之一的，责令改正，给予警告，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不满10万元的，并处10万元以上50万元以下的罚款；情节严重的，责令停业整顿或者吊销期货业务许可证：\n(一)向客户作获利保证或者不按照规定向客户出示风险说明书的；\n(二)在经纪业务中与客户约定分享利益、共担风险的；\n(三)不按照规定接受客户委托或者不按照客户委托内容擅自进行期货交易的；\n(四)隐瞒重要事项或者使用其他不正当手段，诱骗客户发出交易指令的；\n(五)向客户提供虚假成交回报的；\n(六)未将客户交易指令下达到期货交易所的；\n(七)挪用客户保证金的；\n(八)不按照规定在期货保证金存管银行开立保证金账户，或者违规划转客户保证金的；\n(九)国务院期货监督管理机构规定的其他欺诈客户的行为。\n期货公司有前款所列行为之一的，对直接负责的主管人员和其他直接责任人员给予警告，并处1万元以上10万元以下的罚款；情节严重的，暂停或者撤销期货从业人员资格。\n任何单位或者个人编造并且传播有关期货交易的虚假信息，扰乱期货交易市场的，依照本条第一款、第二款的规定处罚。\n第六十八条 期货公司及其他期货经营机构、非期货公司结算会员、期货保证金存管银行提供虚假申请文件或者采取其他欺诈手段隐瞒重要事实骗取期货业务许可的，撤销其期货业务许可，没收违法所得。\n第六十九条 期货交易内幕信息的知情人或者非法获取期货交易内幕信息的人，在对期货交易价格有重大影响的信息尚未公开前，利用内幕信息从事期货交易，或者向他人泄露内幕信息，使他人利用内幕信息进行期货交易的，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不满10万元的，处10万元以上50万元以下的罚款。单位从事内幕交易的，还应当对直接负责的主管人员和其他直接责任人员给予警告，并处3万元以上30万元以下的罚款。\n国务院期货监督管理机构、期货交易所和期货保证金安全存管监控机构的工作人员进行内幕交易的，从重处罚。\n第七十条 任何单位或者个人有下列行为之一，操纵期货交易价格的，责令改正，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不满20万元的，处20万元以上100万元以下的罚款：\n(一)单独或者合谋，集中资金优势、持仓优势或者利用信息优势联合或者连续买卖合约，操纵期货交易价格的；\n(二)蓄意串通，按事先约定的时间、价格和方式相互进行期货交易，影响期货交易价格或者期货交易量的；\n(三)以自己为交易对象，自买自卖，影响期货交易价格或者期货交易量的；\n(四)为影响期货市场行情囤积现货的；\n(五)国务院期货监督管理机构规定的其他操纵期货交易价格的行为。\n单位有前款所列行为之一的，对直接负责的主管人员和其他直接责任人员给予警告，并处1万元以上10万元以下的罚款。\n第七十一条 交割仓库有本条例第三十五条第二款所列行为之一的，责令改正，给予警告，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不满10万元的，并处10万元以上50万元以下的罚款；情节严重的，责令期货交易所暂停或者取消其交割仓库资格。对直接负责的主管人员和其他直接责任人员给予警告，并处1万元以上10万元以下的罚款。\n第七十二条 国有以及国有控股企业违反本条例和国务院国有资产监督管理机构以及其他有关部门关于企业以国有资产进入期货市场的有关规定进行期货交易，或者单位、个人违规使用信贷资金、财政资金进行期货交易的，给予警告，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不满10万元的，并处10万元以上50万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予降级直至开除的纪律处分。\n第七十三条 境内单位或者个人违反规定从事境外期货交易的，责令改正，给予警告，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不满20万元的，并处20万元以上100万元以下的罚款；情节严重的，暂停其境外期货交易。对单位直接负责的主管人员和其他直接责任人员给予警告，并处1万元以上10万元以下的罚款。\n第七十四条 非法设立期货交易场所或者以其他形式组织期货交易活动的，由所在地县级以上地方人民政府予以取缔，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不满20万元的，处20万元以上100万元以下的罚款。对单位直接负责的主管人员和其他直接责任人员给予警告，并处1万元以上10万元以下的罚款。\n非法设立期货公司及其他期货经营机构，或者擅自从事期货业务的，予以取缔，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不满20万元的，处20万元以上100万元以下的罚款。对单位直接负责的主管人员和其他直接责任人员给予警告，并处1万元以上10万元以下的罚款。\n第七十五条 期货公司的交易软件、结算软件供应商拒不配合国务院期货监督管理机构调查，或者未按照规定向国务院期货监督管理机构提供相关软件资料，或者提供的软件资料有虚假、重大遗漏的，责令改正，处3万元以上10万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处1万元以上5万元以下的罚款。\n第七十六条 会计师事务所、律师事务所、资产评估机构等中介服务机构未勤勉尽责，所出具的文件有虚假记载、误导性陈述或者重大遗漏的，责令改正，没收业务收入，暂停或者撤销相关业务许可，并处业务收入1倍以上5倍以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处3万元以上10万元以下的罚款。\n第七十七条 任何单位或者个人违反本条例规定，情节严重的，由国务院期货监督管理机构宣布该个人、该单位或者该单位的直接责任人员为期货市场禁止进入者。\n第七十八条 国务院期货监督管理机构、期货交易所、期货保证金安全存管监控机构和期货保证金存管银行等相关单位的工作人员，泄露知悉的国家秘密或者会员、客户商业秘密，或者徇私舞弊、玩忽职守、滥用职权、收受贿赂的，依法给予行政处分或者纪律处分。\n第七十九条 违反本条例规定，构成犯罪的，依法追究刑事责任。\n第八十条 对本条例规定的违法行为的行政处罚，除本条例已有规定的外，由国务院期货监督管理机构决定；涉及其他有关部门法定职权的，国务院期货监督管理机构应当会同其他有关部门处理；属于其他有关部门法定职权的，国务院期货监督管理机构应当移交其他有关部门处理。","level":1},{"name":"第八章 附则","text":"第八十一条 本条例下列用语的含义：\n(一)商品期货合约，是指以农产品、工业品、能源和其他商品及其相关指数产品为标的物的期货合约。\n(二)金融期货合约，是指以有价证券、利率、汇率等金融产品及其相关指数产品为标的物的期货合约。\n(三)保证金，是指期货交易者按照规定交纳的资金或者提交的价值稳定、流动性强的标准仓单、国债等有价证券，用于结算和保证履约。\n(四)结算，是指根据期货交易所公布的结算价格对交易双方的交易结果进行的资金清算和划转。\n(五)交割，是指合约到期时，按照期货交易所的规则和程序，交易双方通过该合约所载标的物所有权的转移，或者按照规定结算价格进行现金差价结算，了结到期未平仓合约的过程。\n(六)平仓，是指期货交易者买入或者卖出与其所持合约的品种、数量和交割月份相同但交易方向相反的合约，了结期货交易的行为。\n(七)持仓量，是指期货交易者所持有的未平仓合约的数量。\n(八)持仓限额，是指期货交易所对期货交易者的持仓量规定的最高数额。\n(九)标准仓单，是指交割仓库开具并经期货交易所认定的标准化提货凭证。\n(十)涨跌停板，是指合约在1个交易日中的交易价格不得高于或者低于规定的涨跌幅度，超出该涨跌幅度的报价将被视为无效，不能成交。\n(十一)内幕信息，是指可能对期货交易价格产生重大影响的尚未公开的信息，包括：国务院期货监督管理机构以及其他相关部门制定的对期货交易价格可能发生重大影响的政策，期货交易所作出的可能对期货交易价格发生重大影响的决定，期货交易所会员、客户的资金和交易动向以及国务院期货监督管理机构认定的对期货交易价格有显著影响的其他重要信息。\n(十二)内幕信息的知情人员，是指由于其管理地位、监督地位或者职业地位，或者作为雇员、专业顾问履行职务，能够接触或者获得内幕信息的人员，包括：期货交易所的管理人员以及其他由于任职可获取内幕信息的从业人员，国务院期货监督管理机构和其他有关部门的工作人员以及国务院期货监督管理机构规定的其他人员。\n第八十二条 国务院期货监督管理机构可以批准设立期货专门结算机构，专门履行期货交易所的结算以及相关职责，并承担相应法律责任。\n第八十三条 境外机构在境内设立、收购或者参股期货经营机构，以及境外期货经营机构在境内设立分支机构(含代表处)的管理办法，由国务院期货监督管理机构会同国务院商务主管部门、外汇管理部门等有关部门制订，报国务院批准后施行。\n第八十四条 在期货交易所之外的国务院期货监督管理机构批准的交易场所进行的期货交易，依照本条例的有关规定执行。\n第八十五条 不属于期货交易的商品或者金融产品的其他交易活动，由国家有关部门监督管理，不适用本条例。\n第八十六条 本条例自2007年4月15日起施行。1999年6月2日国务院发布的《期货交易管理暂行条例》同时废止。","level":1}]},{"id":"n0297","sections":[{"name":"","text":"中华人民共和国监控化学品管理条例\n(1995年12月27日中华人民共和国国务院令第190号发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》修订)\n第一条 为了加强对监控化学品的管理，保障公民的人身安全和保护环境，制定本条例。\n第二条 在中华人民共和国境内从事监控化学品的生产、经营和使用活动，必须遵守本条例。\n第三条 本条例所称监控化学品，是指下列各类化学品：\n第一类：可作为化学武器的化学品；\n第二类：可作为生产化学武器前体的化学品；\n第三类：可作为生产化学武器主要原料的化学品；\n第四类：除炸药和纯碳氢化合物外的特定有机化学品。\n前款各类监控化学品的名录由国务院化学工业主管部门提出，报国务院批准后公布。\n第四条 国务院化学工业主管部门负责全国监控化学品的管理工作。省、自治区、直辖市人民政府化学工业主管部门负责本行政区域内监控化学品的管理工作。\n第五条 生产、经营或者使用监控化学品的，应当依照本条例和国家有关规定向国务院化学工业主管部门或者省、自治区、直辖市人民政府化学工业主管部门申报生产、经营或者使用监控化学品的有关资料、数据和使用目的，接受化学工业主管部门的检查监督。\n第六条 国家严格控制第一类监控化学品的生产。\n为科研、医疗、制造药物或者防护目的需要生产第一类监控化学品的，应当报国务院化学工业主管部门批准，并在国务院化学工业主管部门指定的小型设施中生产。\n严禁在未经国务院化学工业主管部门指定的设施中生产第一类监控化学品。\n第七条 国家对第二类、第三类监控化学品和第四类监控化学品中含磷、硫、氟的特定有机化学品的生产，实行特别许可制度；未经特别许可的，任何单位和个人均不得生产。特别许可办法，由国务院化学工业主管部门制定。\n第八条 新建、扩建或者改建用于生产第二类、第三类监控化学品和第四类监控化学品中含磷、硫、氟的特定有机化学品的设施，应当向所在地省、自治区、直辖市人民政府化学工业主管部门提出申请，经省、自治区、直辖市人民政府化学工业主管部门审查签署意见，报国务院化学工业主管部门批准后，方可开工建设；工程竣工后，经所在地省、自治区、直辖市人民政府化学工业主管部门验收合格，并报国务院化学工业主管部门批准后，方可投产使用。\n新建、扩建或者改建用于生产第四类监控化学品中不含磷、硫、氟的特定有机化学品的设施，应当在开工生产前向所在地省、自治区、直辖市人民政府化学工业主管部门备案。\n第九条 监控化学品应当在专用的化工仓库中储存，并设专人管理。监控化学品的储存条件应当符合国家有关规定。\n第十条 储存监控化学品的单位，应当建立严格的出库、入库检查制度和登记制度；发现丢失、被盗时，应当立即报告当地公安机关和所在地省、自治区、直辖市人民政府化学工业主管部门；省、自治区、直辖市人民政府化学工业主管部门应当积极配合公安机关进行查处。\n第十一条 对变质或者过期失效的监控化学品，应当及时处理。处理方案报所在地省、自治区、直辖市人民政府化学工业主管部门批准后实施。\n第十二条 为科研、医疗、制造药物或者防护目的需要使用第一类监控化学品的，应当向国务院化学工业主管部门提出申请，经国务院化学工业主管部门审查批准后，凭批准文件同国务院化学工业主管部门指定的生产单位签订合同，并将合同副本报送国务院化学工业主管部门备案。\n第十三条 需要使用第二类监控化学品的，应当向所在地省、自治区、直辖市人民政府化学工业主管部门提出申请，经省、自治区、直辖市人民政府化学工业主管部门审查批准后，凭批准文件同国务院化学工业主管部门指定的经销单位签订合同，并将合同副本报送所在地省、自治区、直辖市人民政府化学工业主管部门备案。\n第十四条 国务院化学工业主管部门会同国务院对外经济贸易主管部门指定的单位(以下简称被指定单位)，可以从事第一类监控化学品和第二类、第三类监控化学品及其生产技术、专用设备的进出口业务。\n需要进口或者出口第一类监控化学品和第二类、第三类监控化学品及其生产技术、专用设备的，应当委托被指定单位代理进口或者出口。除被指定单位外，任何单位和个人均不得从事这类进出口业务。\n第十五条 国家严格控制第一类监控化学品的进口和出口。非为科研、医疗、制造药物或者防护目的，不得进口第一类监控化学品。\n接受委托进口第一类监控化学品的被指定单位，应当向国务院化学工业主管部门提出申请，并提交产品最终用途的说明和证明；经国务院化学工业主管部门审查签署意见后，报国务院审查批准。被指定单位凭国务院的批准文件向国务院对外经济贸易主管部门申请领取进口许可证。\n第十六条 接受委托进口第二类、第三类监控化学品及其生产技术、专用设备的被指定单位，应当向国务院化学工业主管部门提出申请，并提交所进口的化学品、生产技术或者专用设备最终用途的说明和证明；经国务院化学工业主管部门审查批准后，被指定单位凭国务院化学工业主管部门的批准文件向国务院对外经济贸易主管部门申请领取进口许可证。\n第十七条 接受委托出口第一类监控化学品的被指定单位，应当向国务院化学工业主管部门提出申请，并提交进口国政府或者政府委托机构出具的所进口的化学品仅用于科研、医疗、制造药物或者防护目的和不转口第三国的保证书；经国务院化学工业主管部门审查签署意见后，报国务院审查批准。被指定单位凭国务院的批准文件向国务院对外经济贸易主管部门申请领取出口许可证。\n第十八条 接受委托出口第二类、第三类监控化学品及其生产技术、专用设备的被指定单位，应当向国务院化学工业主管部门提出申请，并提交进口国政府或者政府委托机构出具的所进口的化学品、生产技术、专用设备不用于生产化学武器和不转口第三国的保证书；经国务院化学工业主管部门审查批准后，被指定单位凭国务院化学工业主管部门的批准文件向国务院对外经济贸易主管部门申请领取出口许可证。\n第十九条 使用监控化学品的，应当与其申报的使用目的相一致；需要改变使用目的的，应当报原审批机关批准。\n第二十条 使用第一类、第二类监控化学品的，应当按照国家有关规定，定期向所在地省、自治区、直辖市人民政府化学工业主管部门报告消耗此类监控化学品的数量和使用此类监控化学品生产最终产品的数量。\n第二十一条 违反本条例规定，生产监控化学品的，由省、自治区、直辖市人民政府化学工业主管部门责令限期改正；逾期不改正的，可以处20万元以下的罚款；情节严重的，可以提请省、自治区、直辖市人民政府责令停产整顿。\n第二十二条 违反本条例规定，使用监控化学品的，由省、自治区、直辖市人民政府化学工业主管部门责令限期改正；逾期不改正的，可以处5万元以下的罚款。\n第二十三条 违反本条例规定，经营监控化学品的，由省、自治区、直辖市人民政府化学工业主管部门没收其违法经营的监控化学品和违法所得，可以并处违法经营额1倍以上2倍以下的罚款。\n第二十四条 违反本条例规定，隐瞒、拒报有关监控化学品的资料、数据，或者妨碍、阻挠化学工业主管部门依照本条例的规定履行检查监督职责的，由省、自治区、直辖市人民政府化学工业主管部门处以5万元以下的罚款。\n第二十五条 违反本条例规定，构成违反治安管理行为的，依照《中华人民共和国治安管理处罚法》的有关规定处罚；构成犯罪的，依法追究刑事责任。\n第二十六条 在本条例施行前已经从事生产、经营或者使用监控化学品的，应当依照本条例的规定，办理有关手续。\n第二十七条 本条例自发布之日起施行。","level":0}]},{"id":"n0298","sections":[{"name":"","text":"中华人民共和国保障措施条例\n(2001年11月26日中华人民共和国国务院令第330号公布 根据2004年3月31日《国务院关于修改〈中华人民共和国保障措施条例〉的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了促进对外贸易健康发展，根据《中华人民共和国对外贸易法》的有关规定，制定本条例。\n第二条 进口产品数量增加，并对生产同类产品或者直接竞争产品的国内产业造成严重损害或者严重损害威胁(以下除特别指明外，统称损害)的，依照本条例的规定进行调查，采取保障措施。","level":1},{"name":"第二章 调查","text":"第三条 与国内产业有关的自然人、法人或者其他组织(以下统称申请人)，可以依照本条例的规定，向商务部提出采取保障措施的书面申请。\n商务部应当及时对申请人的申请进行审查，决定立案调查或者不立案调查。\n第四条 商务部没有收到采取保障措施的书面申请，但有充分证据认为国内产业因进口产品数量增加而受到损害的，可以决定立案调查。\n第五条 立案调查的决定，由商务部予以公告。\n商务部应当将立案调查的决定及时通知世界贸易组织保障措施委员会(以下简称保障措施委员会)。\n第六条 对进口产品数量增加及损害的调查和确定，由商务部负责；其中，涉及农产品的保障措施国内产业损害调查，由商务部会同农业部进行。\n第七条 进口产品数量增加，是指进口产品数量的绝对增加或者与国内生产相比的相对增加。\n第八条 在确定进口产品数量增加对国内产业造成的损害时，应当审查下列相关因素：\n(一)进口产品的绝对和相对增长率与增长量；\n(二)增加的进口产品在国内市场中所占的份额；\n(三)进口产品对国内产业的影响，包括对国内产业在产量、销售水平、市场份额、生产率、设备利用率、利润与亏损、就业等方面的影响；\n(四)造成国内产业损害的其他因素。\n对严重损害威胁的确定，应当依据事实，不能仅依据指控、推测或者极小的可能性。\n在确定进口产品数量增加对国内产业造成的损害时，不得将进口增加以外的因素对国内产业造成的损害归因于进口增加。\n第九条 在调查期间，商务部应当及时公布对案情的详细分析和审查的相关因素等。\n第十条 国内产业，是指中华人民共和国国内同类产品或者直接竞争产品的全部生产者，或者其总产量占国内同类产品或者直接竞争产品全部总产量的主要部分的生产者。\n第十一条 商务部应当根据客观的事实和证据，确定进口产品数量增加与国内产业的损害之间是否存在因果关系。\n第十二条 商务部应当为进口经营者、出口经营者和其他利害关系方提供陈述意见和论据的机会。\n调查可以采用调查问卷的方式，也可以采用听证会或者其他方式。\n第十三条 调查中获得的有关资料，资料提供方认为需要保密的，商务部可以按保密资料处理。\n保密申请有理由的，应当对资料提供方提供的资料按保密资料处理，同时要求资料提供方提供一份非保密的该资料概要。\n按保密资料处理的资料，未经资料提供方同意，不得泄露。\n第十四条 进口产品数量增加、损害的调查结果及其理由的说明，由商务部予以公布。\n商务部应当将调查结果及有关情况及时通知保障措施委员会。\n第十五条 商务部根据调查结果，可以作出初裁决定，也可以直接作出终裁决定，并予以公告。","level":1},{"name":"第三章 保障措施","text":"第十六条 有明确证据表明进口产品数量增加，在不采取临时保障措施将对国内产业造成难以补救的损害的紧急情况下，可以作出初裁决定，并采取临时保障措施。\n临时保障措施采取提高关税的形式。\n第十七条 采取临时保障措施，由商务部提出建议，国务院关税税则委员会根据商务部的建议作出决定，由商务部予以公告。海关自公告规定实施之日起执行。\n在采取临时保障措施前，商务部应当将有关情况通知保障措施委员会。\n第十八条 临时保障措施的实施期限，自临时保障措施决定公告规定实施之日起，不超过200天。\n第十九条 终裁决定确定进口产品数量增加，并由此对国内产业造成损害的，可以采取保障措施。实施保障措施应当符合公共利益。\n保障措施可以采取提高关税、数量限制等形式。\n第二十条 保障措施采取提高关税形式的，由商务部提出建议，国务院关税税则委员会根据商务部的建议作出决定，由商务部予以公告；采取数量限制形式的，由商务部作出决定并予以公告。海关自公告规定实施之日起执行。\n商务部应当将采取保障措施的决定及有关情况及时通知保障措施委员会。\n第二十一条 采取数量限制措施的，限制后的进口量不得低于最近3个有代表性年度的平均进口量；但是，有正当理由表明为防止或者补救严重损害而有必要采取不同水平的数量限制措施的除外。\n采取数量限制措施，需要在有关出口国(地区)或者原产国(地区)之间进行数量分配的，商务部可以与有关出口国(地区)或者原产国(地区)就数量的分配进行磋商。\n第二十二条 保障措施应当针对正在进口的产品实施，不区分产品来源国(地区)。\n第二十三条 采取保障措施应当限于防止、补救严重损害并便利调整国内产业所必要的范围内。\n第二十四条 在采取保障措施前，商务部应当为与有关产品的出口经营者有实质利益的国家(地区)政府提供磋商的充分机会。\n第二十五条 终裁决定确定不采取保障措施的，已征收的临时关税应当予以退还。","level":1},{"name":"第四章 保障措施的期限与复审","text":"第二十六条 保障措施的实施期限不超过4年。\n符合下列条件的，保障措施的实施期限可以适当延长：\n(一)按照本条例规定的程序确定保障措施对于防止或者补救严重损害仍然有必要；\n(二)有证据表明相关国内产业正在进行调整；\n(三)已经履行有关对外通知、磋商的义务；\n(四)延长后的措施不严于延长前的措施。\n一项保障措施的实施期限及其延长期限，最长不超过10年。\n第二十七条 保障措施实施期限超过1年的，应当在实施期间内按固定时间间隔逐步放宽。\n第二十八条 保障措施实施期限超过3年的，商务部应当在实施期间内对该项措施进行中期复审。\n复审的内容包括保障措施对国内产业的影响、国内产业的调整情况等。\n第二十九条 保障措施属于提高关税的，商务部应当根据复审结果，依照本条例的规定，提出保留、取消或者加快放宽提高关税措施的建议，国务院关税税则委员会根据商务部的建议作出决定，由商务部予以公告；保障措施属于数量限制或者其他形式的，商务部应当根据复审结果，依照本条例的规定，作出保留、取消或者加快放宽数量限制措施的决定并予以公告。\n第三十条 对同一进口产品再次采取保障措施的，与前次采取保障措施的时间间隔应当不短于前次采取保障措施的实施期限，并且至少为2年。\n符合下列条件的，对一产品实施的期限为180天或者少于180天的保障措施，不受前款限制：\n(一)自对该进口产品实施保障措施之日起，已经超过1年；\n(二)自实施该保障措施之日起5年内，未对同一产品实施2次以上保障措施。","level":1},{"name":"第五章 附则","text":"第三十一条 任何国家(地区)对中华人民共和国的出口产品采取歧视性保障措施的，中华人民共和国可以根据实际情况对该国家(地区)采取相应的措施。\n第三十二条 商务部负责与保障措施有关的对外磋商、通知和争端解决事宜。\n第三十三条 商务部可以根据本条例制定具体实施办法。\n第三十四条 本条例自2002年1月1日起施行。","level":1}]},{"id":"n0299","sections":[{"name":"","text":"人体器官移植条例\n(2007年3月21日国务院第171次常务会议通过 2007年3月31日中华人民共和国国务院令第491号公布 自2007年5月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了规范人体器官移植，保证医疗质量，保障人体健康，维护公民的合法权益，制定本条例。\n第二条 在中华人民共和国境内从事人体器官移植，适用本条例；从事人体细胞和角膜、骨髓等人体组织移植，不适用本条例。\n本条例所称人体器官移植，是指摘取人体器官捐献人具有特定功能的心脏、肺脏、肝脏、肾脏或者胰腺等器官的全部或者部分，将其植入接受人身体以代替其病损器官的过程。\n第三条 任何组织或者个人不得以任何形式买卖人体器官，不得从事与买卖人体器官有关的活动。\n第四条 国务院卫生主管部门负责全国人体器官移植的监督管理工作。县级以上地方人民政府卫生主管部门负责本行政区域人体器官移植的监督管理工作。\n各级红十字会依法参与人体器官捐献的宣传等工作。\n第五条 任何组织或者个人对违反本条例规定的行为，有权向卫生主管部门和其他有关部门举报；对卫生主管部门和其他有关部门未依法履行监督管理职责的行为，有权向本级人民政府、上级人民政府有关部门举报。接到举报的人民政府、卫生主管部门和其他有关部门对举报应当及时核实、处理，并将处理结果向举报人通报。\n第六条 国家通过建立人体器官移植工作体系，开展人体器官捐献的宣传、推动工作，确定人体器官移植预约者名单，组织协调人体器官的使用。","level":1},{"name":"第二章 人体器官的捐献","text":"第七条 人体器官捐献应当遵循自愿、无偿的原则。\n公民享有捐献或者不捐献其人体器官的权利；任何组织或者个人不得强迫、欺骗或者利诱他人捐献人体器官。\n第八条 捐献人体器官的公民应当具有完全民事行为能力。公民捐献其人体器官应当有书面形式的捐献意愿，对已经表示捐献其人体器官的意愿，有权予以撤销。\n公民生前表示不同意捐献其人体器官的，任何组织或者个人不得捐献、摘取该公民的人体器官；公民生前未表示不同意捐献其人体器官的，该公民死亡后，其配偶、成年子女、父母可以以书面形式共同表示同意捐献该公民人体器官的意愿。\n第九条 任何组织或者个人不得摘取未满18周岁公民的活体器官用于移植。\n第十条 活体器官的接受人限于活体器官捐献人的配偶、直系血亲或者三代以内旁系血亲，或者有证据证明与活体器官捐献人存在因帮扶等形成亲情关系的人员。","level":1},{"name":"第三章 人体器官的移植","text":"第十一条 医疗机构从事人体器官移植，应当依照《医疗机构管理条例》的规定，向所在地省、自治区、直辖市人民政府卫生主管部门申请办理人体器官移植诊疗科目登记。\n医疗机构从事人体器官移植，应当具备下列条件：\n(一)有与从事人体器官移植相适应的执业医师和其他医务人员；\n(二)有满足人体器官移植所需要的设备、设施；\n(三)有由医学、法学、伦理学等方面专家组成的人体器官移植技术临床应用与伦理委员会，该委员会中从事人体器官移植的医学专家不超过委员人数的1/4；\n(四)有完善的人体器官移植质量监控等管理制度。\n第十二条 省、自治区、直辖市人民政府卫生主管部门进行人体器官移植诊疗科目登记，除依据本条例第十一条规定的条件外，还应当考虑本行政区域人体器官移植的医疗需求和合法的人体器官来源情况。\n省、自治区、直辖市人民政府卫生主管部门应当及时公布已经办理人体器官移植诊疗科目登记的医疗机构名单。\n第十三条 已经办理人体器官移植诊疗科目登记的医疗机构不再具备本条例第十一条规定条件的，应当停止从事人体器官移植，并向原登记部门报告。原登记部门应当自收到报告之日起2日内注销该医疗机构的人体器官移植诊疗科目登记，并予以公布。\n第十四条 省级以上人民政府卫生主管部门应当定期组织专家根据人体器官移植手术成功率、植入的人体器官和术后患者的长期存活率，对医疗机构的人体器官移植临床应用能力进行评估，并及时公布评估结果；对评估不合格的，由原登记部门撤销人体器官移植诊疗科目登记。具体办法由国务院卫生主管部门制订。\n第十五条 医疗机构及其医务人员从事人体器官移植，应当遵守伦理原则和人体器官移植技术管理规范。\n第十六条 实施人体器官移植手术的医疗机构及其医务人员应当对人体器官捐献人进行医学检查，对接受人因人体器官移植感染疾病的风险进行评估，并采取措施，降低风险。\n第十七条 在摘取活体器官前或者尸体器官捐献人死亡前，负责人体器官移植的执业医师应当向所在医疗机构的人体器官移植技术临床应用与伦理委员会提出摘取人体器官审查申请。\n人体器官移植技术临床应用与伦理委员会不同意摘取人体器官的，医疗机构不得做出摘取人体器官的决定，医务人员不得摘取人体器官。\n第十八条 人体器官移植技术临床应用与伦理委员会收到摘取人体器官审查申请后，应当对下列事项进行审查，并出具同意或者不同意的书面意见：\n(一)人体器官捐献人的捐献意愿是否真实；\n(二)有无买卖或者变相买卖人体器官的情形；\n(三)人体器官的配型和接受人的适应症是否符合伦理原则和人体器官移植技术管理规范。\n经2/3以上委员同意，人体器官移植技术临床应用与伦理委员会方可出具同意摘取人体器官的书面意见。\n第十九条 从事人体器官移植的医疗机构及其医务人员摘取活体器官前，应当履行下列义务：\n(一)向活体器官捐献人说明器官摘取手术的风险、术后注意事项、可能发生的并发症及其预防措施等，并与活体器官捐献人签署知情同意书；\n(二)查验活体器官捐献人同意捐献其器官的书面意愿、活体器官捐献人与接受人存在本条例第十条规定关系的证明材料；\n(三)确认除摘取器官产生的直接后果外不会损害活体器官捐献人其他正常的生理功能。\n从事人体器官移植的医疗机构应当保存活体器官捐献人的医学资料，并进行随访。\n第二十条 摘取尸体器官，应当在依法判定尸体器官捐献人死亡后进行。从事人体器官移植的医务人员不得参与捐献人的死亡判定。\n从事人体器官移植的医疗机构及其医务人员应当尊重死者的尊严；对摘取器官完毕的尸体，应当进行符合伦理原则的医学处理，除用于移植的器官以外，应当恢复尸体原貌。\n第二十一条 从事人体器官移植的医疗机构实施人体器官移植手术，除向接受人收取下列费用外，不得收取或者变相收取所移植人体器官的费用：\n(一)摘取和植入人体器官的手术费；\n(二)保存和运送人体器官的费用；\n(三)摘取、植入人体器官所发生的药费、检验费、医用耗材费。\n前款规定费用的收取标准，依照有关法律、行政法规的规定确定并予以公布。\n第二十二条 申请人体器官移植手术患者的排序，应当符合医疗需要，遵循公平、公正和公开的原则。具体办法由国务院卫生主管部门制订。\n第二十三条 从事人体器官移植的医务人员应当对人体器官捐献人、接受人和申请人体器官移植手术的患者的个人资料保密。\n第二十四条 从事人体器官移植的医疗机构应当定期将实施人体器官移植的情况向所在地省、自治区、直辖市人民政府卫生主管部门报告。具体办法由国务院卫生主管部门制订。","level":1},{"name":"第四章 法律责任","text":"第二十五条 违反本条例规定，有下列情形之一，构成犯罪的，依法追究刑事责任：\n(一)未经公民本人同意摘取其活体器官的；\n(二)公民生前表示不同意捐献其人体器官而摘取其尸体器官的；\n(三)摘取未满18周岁公民的活体器官的。\n第二十六条 违反本条例规定，买卖人体器官或者从事与买卖人体器官有关活动的，由设区的市级以上地方人民政府卫生主管部门依照职责分工没收违法所得，并处交易额8倍以上10倍以下的罚款；医疗机构参与上述活动的，还应当对负有责任的主管人员和其他直接责任人员依法给予处分，并由原登记部门撤销该医疗机构人体器官移植诊疗科目登记，该医疗机构3年内不得再申请人体器官移植诊疗科目登记；医务人员参与上述活动的，由原发证部门吊销其执业证书。\n国家工作人员参与买卖人体器官或者从事与买卖人体器官有关活动的，由有关国家机关依据职权依法给予撤职、开除的处分。\n第二十七条 医疗机构未办理人体器官移植诊疗科目登记，擅自从事人体器官移植的，依照《医疗机构管理条例》的规定予以处罚。\n实施人体器官移植手术的医疗机构及其医务人员违反本条例规定，未对人体器官捐献人进行医学检查或者未采取措施，导致接受人因人体器官移植手术感染疾病的，依照《医疗事故处理条例》的规定予以处罚。\n从事人体器官移植的医务人员违反本条例规定，泄露人体器官捐献人、接受人或者申请人体器官移植手术患者个人资料的，依照《执业医师法》或者国家有关护士管理的规定予以处罚。\n违反本条例规定，给他人造成损害的，应当依法承担民事责任。\n违反本条例第二十一条规定收取费用的，依照价格管理的法律、行政法规的规定予以处罚。\n第二十八条 医务人员有下列情形之一的，依法给予处分；情节严重的，由县级以上地方人民政府卫生主管部门依照职责分工暂停其6个月以上1年以下执业活动；情节特别严重的，由原发证部门吊销其执业证书：\n(一)未经人体器官移植技术临床应用与伦理委员会审查同意摘取人体器官的；\n(二)摘取活体器官前未依照本条例第十九条的规定履行说明、查验、确认义务的；\n(三)对摘取器官完毕的尸体未进行符合伦理原则的医学处理，恢复尸体原貌的。\n第二十九条 医疗机构有下列情形之一的，对负有责任的主管人员和其他直接责任人员依法给予处分；情节严重的，由原登记部门撤销该医疗机构人体器官移植诊疗科目登记，该医疗机构3年内不得再申请人体器官移植诊疗科目登记：\n(一)不再具备本条例第十一条规定条件，仍从事人体器官移植的；\n(二)未经人体器官移植技术临床应用与伦理委员会审查同意，做出摘取人体器官的决定，或者胁迫医务人员违反本条例规定摘取人体器官的；\n(三)有本条例第二十八条第(二)项、第(三)项列举的情形的。\n医疗机构未定期将实施人体器官移植的情况向所在地省、自治区、直辖市人民政府卫生主管部门报告的，由所在地省、自治区、直辖市人民政府卫生主管部门责令限期改正；逾期不改正的，对负有责任的主管人员和其他直接责任人员依法给予处分。\n第三十条 从事人体器官移植的医务人员参与尸体器官捐献人的死亡判定的，由县级以上地方人民政府卫生主管部门依照职责分工暂停其6个月以上1年以下执业活动；情节严重的，由原发证部门吊销其执业证书。\n第三十一条 国家机关工作人员在人体器官移植监督管理工作中滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。","level":1},{"name":"第五章 附则","text":"第三十二条 本条例自2007年5月1日起施行。","level":1}]},{"id":"n0300","sections":[{"name":"","text":"石油地震勘探损害补偿规定\n(1989年9月26日国务院批准 1989年10月17日中华人民共和国能源部令第1号发布 自发布之日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了做好石油地震勘探损害补偿工作，正确处理国家、集体、个人三者利益关系，确保石油勘探工作的顺利进行，制定本规定。\n第二条 本规定适用于中华人民共和国陆地(包括岛屿、海滩、水深五米的浅海在内)石油地震勘探作业和作业地震波的损害补偿。\n第三条 石油地震勘探是沿一定测线通过式作业，在测线每个观测点上通过时间不超过四十八小时，在特殊情况下不超过九十六小时的，免于办理临时用地手续。\n第四条 石油地震勘探按照实际损害程度由地震作业队给予受损害的个人或者单位一次性补偿，补偿费用应当及时支付。任何单位或者个人不得截留、回扣补偿费用，或者向地震作业队索要补偿费用之外的费用或者实物。\n第五条 地震作业队的主管部门，应当在开工前三十日内将本年度的石油地震勘探施工设计和作业计划向作业区所在地的县级人民政府有关主管部门报告，取得支持和帮助。县级人民政府有关主管部门应当在地震作业队作业前将作业区的地面、地下设施、农田作物等有关资料提供给地震作业队主管部门。\n第六条 地震作业队的作业，应当按照国家有关规定在城市区、工矿区、居民点、车站、码头、港口、铁路、军用基地、人防工程、大中型桥涵、水利工程、电力设施、输油输气管线、国家测量标志、重点文物、通讯设施、广播设施的安全距离之外放炮。特殊情况下，如需在上述安全距离内放炮作业，地震作业队应当征得有关部门同意，采取安全措施后，方可施工。\n第七条 当事人双方对石油地震勘探损害补偿问题发生纠纷时，首先应当协商解决，协商不成的，提请当地县级人民政府及其指定的部门调解处理；对调解处理决定不服的，任何一方可在接到处理决定之日起十五日内向所在地人民法院起诉，但在调解和诉讼期间，应当保证地震作业队正常作业。","level":1},{"name":"第二章 石油地震勘探作业损害补偿","text":"第八条 石油地震勘探作业(以下简称地震作业)车辆沿测线通过农田，对粮食作物和其他经济作物造成损害的，作物受害量以当地县级人民政府统计部门前三年上报国家产量的年平均数、实际损害面积和实际损害程度计算；作物补偿价格按国家规定的价格和当地市场价格的加权平均值计算，其加权平均值参照定购合同等因素，由双方协商确定，作业车辆损害农田面积以实际碾压宽度和长度计算。\n第九条 地震作业车辆沿测线通过造成的农田地面设施损害，根据实际损害程度，由双方协商，给予适当补偿。\n第十条 地震作业对封冻期的青苗损害的补偿标准，按作业车辆实际碾压损害程度确定，一般不超过对该地非封冻期作物损害补偿标准的百分之三十，但个别地方青苗碾压严重的，经当事人双方认定，可酌情提高补偿标准。封冻期的具体期限由当地省级以上人民政府确定。\n第十一条 地震作业对无封冻期的已耕待种地造成损害的，应按照作业车辆实际碾压面积，参照当地劳务费用和机耕费用的标准补偿复耕费。\n第十二条 地震作业对牧区人工种植的草场造成损害的，应按照草场实际损害面积和亩产量，及当地省级人民政府规定的牧草收购价格，予以补偿。\n对已承包给个人或集体的天然草场造成损害的，应根据该天然草场的实际产草情况和损害程度，由当事人双方协商补偿办法。补偿费的标准，由当地省级人民政府确定。\n第十三条 地震作业对竹木造成损害的，应对实际损害株数逐株计算，进行补偿。竹木补偿标准由当地省级人民政府确定，被损竹木归原竹木所有者。\n第十四条 地震作业后的炮眼，应当由地震作业队负责回填。地震作业队不回填的，应按照当地省级人民政府规定的标准，支付炮眼回填劳务费。","level":1},{"name":"第三章 地震作业地震波造成损害的补偿","text":"第十五条 地震作业队井中放炮，对其地震作业地震波(以下简称地震波)造成损害的补偿范围规定如下：\n(一)对土坯结构和砖、土坯混合结构的房屋、窑洞、厂房、正常生产的砖窑，炸药量在一至三公斤，地震波损害的补偿范围为距炮点半径四十米以内，炸药量在四至六公斤，地震波损害的补偿范围为距炮点半径五十米以内；炸药量在七至十公斤，地震波损害的补偿范围为距炮点半径七十米以内；炸药量在十一至十五公斤，地震波损害的补偿范围为距炮点半径八十米以内。\n(二)对混凝土结构的厂房建筑、机井、一般桥梁和水闸的地震波损害的补偿范围，比照本条(一)项规定的范围缩小四分之一。\n第十六条 在地震波损害的补偿范围内的地面设施，根据地震作业放炮后所造成的损害的程度，参考原造价和使用年限计算补偿费用，予以补偿。\n第十七条 对地震波损害补偿范围内的机井的损害补偿，由当事人双方共同核实损害程度，并参照当地县级人民政府有关部门提供的机井档案资料、造价、使用年限，计算补偿费用予以补偿。\n第十八条 在海滩和浅海区进行地震作业，应当采用非炸药震源；在陆地进行地震作业，应当尽量避开鱼塘或养殖场。\n必须在鱼塘或养殖场内及其附近地区进行地震作业的，炮眼井底至鱼塘或养殖场水底的深度不得小于五米，炸药量不得大于十公斤。\n因地震作业对鱼类和其它水产类造成损害的，应当根据实际损害情况给予一次性补偿，具体补偿办法由国务院石油工业主管部门和农业主管部门另行规定。","level":1},{"name":"第四章 不予补偿的范围","text":"第十九条 地震作业队在没有种植农作物的荒岭、荒坡、荒地、荒漠，以及封冻期的无种植耕地、草原进行石油勘探地震作业的，不予补偿，但对作业区的耕地应当负责复垦，恢复利用。\n第二十条 地震作业队在国家和集体所有的闲置地，没有承包的沙滩、沙漠、河滩、湖滩、海滩、森林中的空地进行地震作业的，不予补偿。\n第二十一条 地震作业队主管部门向地震作业区所在地人民政府提交作业计划后，任何单位和个人故意在作业线上抢种作物、苗木和突击设置地面设施的，其在地震作业后受到损害的，地震作业队不予补偿。","level":1},{"name":"第五章 罚则","text":"第二十二条 地震作业队违反第六条规定，擅自在安全距离内放炮的，应当根据国家有关法律、法规由有关部门对地震作业队责任人员追究行政责任或民事责任；对情节严重构成犯罪的，依法追究其刑事责任。\n第二十三条 有下列行为之一的单位和个人，视其情节轻重，由当地人民政府有关部门依法给予行政处罚，并责令其赔偿造成的损失；构成犯罪的，由司法部门依法追究刑事责任：\n(一)扣押、损坏、偷盗地震作业队的设备和器材的；\n(二)采取挖路、放水、扣车、扣人、围攻及殴打地震作业人员、煽动群众起哄闹事、阻碍地震作业队正常施工作业的；\n(三)采用欺骗的方法，利用损害补偿敲诈勒索的。\n第二十四条 违反第四条规定，截留、回扣补偿费用的单位和个人，由监察部门责令其退回被截留、回扣的补偿费用，并可予以行政处罚。","level":1},{"name":"第六章 附则","text":"第二十五条 其它行业和部门因地震勘探作业所造成的损害，可参照本规定进行补偿。\n第二十六条 本规定由国务院石油工业主管部门负责解释。\n第二十七条 本规定自发布之日起施行。","level":1}]},{"id":"n0301","sections":[{"name":"","text":"中华人民共和国外汇管理条例\n(1996年1月29日中华人民共和国国务院令第193号发布 根据1997年1月14日《国务院关于修改〈中华人民共和国外汇管理条例〉的决定》修订 2008年8月1日国务院第20次常务会议修订通过 2008年8月5日中华人民共和国国务院令第532号公布 自公布之日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了加强外汇管理，促进国际收支平衡，促进国民经济健康发展，制定本条例。\n第二条 国务院外汇管理部门及其分支机构(以下统称外汇管理机关)依法履行外汇管理职责，负责本条例的实施。\n第三条 本条例所称外汇，是指下列以外币表示的可以用作国际清偿的支付手段和资产：\n(一)外币现钞，包括纸币、铸币；\n(二)外币支付凭证或者支付工具，包括票据、银行存款凭证、银行卡等；\n(三)外币有价证券，包括债券、股票等；\n(四)特别提款权；\n(五)其他外汇资产。\n第四条 境内机构、境内个人的外汇收支或者外汇经营活动，以及境外机构、境外个人在境内的外汇收支或者外汇经营活动，适用本条例。\n第五条 国家对经常性国际支付和转移不予限制。\n第六条 国家实行国际收支统计申报制度。\n国务院外汇管理部门应当对国际收支进行统计、监测，定期公布国际收支状况。\n第七条 经营外汇业务的金融机构应当按照国务院外汇管理部门的规定为客户开立外汇账户，并通过外汇账户办理外汇业务。\n经营外汇业务的金融机构应当依法向外汇管理机关报送客户的外汇收支及账户变动情况。\n第八条 中华人民共和国境内禁止外币流通，并不得以外币计价结算，但国家另有规定的除外。\n第九条 境内机构、境内个人的外汇收入可以调回境内或者存放境外；调回境内或者存放境外的条件、期限等，由国务院外汇管理部门根据国际收支状况和外汇管理的需要作出规定。\n第十条 国务院外汇管理部门依法持有、管理、经营国家外汇储备，遵循安全、流动、增值的原则。\n第十一条 国际收支出现或者可能出现严重失衡，以及国民经济出现或者可能出现严重危机时，国家可以对国际收支采取必要的保障、控制等措施。","level":1},{"name":"第二章 经常项目外汇管理","text":"第十二条 经常项目外汇收支应当具有真实、合法的交易基础。经营结汇、售汇业务的金融机构应当按照国务院外汇管理部门的规定，对交易单证的真实性及其与外汇收支的一致性进行合理审查。\n外汇管理机关有权对前款规定事项进行监督检查。\n第十三条 经常项目外汇收入，可以按照国家有关规定保留或者卖给经营结汇、售汇业务的金融机构。\n第十四条 经常项目外汇支出，应当按照国务院外汇管理部门关于付汇与购汇的管理规定，凭有效单证以自有外汇支付或者向经营结汇、售汇业务的金融机构购汇支付。\n第十五条 携带、申报外币现钞出入境的限额，由国务院外汇管理部门规定。","level":1},{"name":"第三章 资本项目外汇管理","text":"第十六条 境外机构、境外个人在境内直接投资，经有关主管部门批准后，应当到外汇管理机关办理登记。\n境外机构、境外个人在境内从事有价证券或者衍生产品发行、交易，应当遵守国家关于市场准入的规定，并按照国务院外汇管理部门的规定办理登记。\n第十七条 境内机构、境内个人向境外直接投资或者从事境外有价证券、衍生产品发行、交易，应当按照国务院外汇管理部门的规定办理登记。国家规定需要事先经有关主管部门批准或者备案的，应当在外汇登记前办理批准或者备案手续。\n第十八条 国家对外债实行规模管理。借用外债应当按照国家有关规定办理，并到外汇管理机关办理外债登记。\n国务院外汇管理部门负责全国的外债统计与监测，并定期公布外债情况。\n第十九条 提供对外担保，应当向外汇管理机关提出申请，由外汇管理机关根据申请人的资产负债等情况作出批准或者不批准的决定；国家规定其经营范围需经有关主管部门批准的，应当在向外汇管理机关提出申请前办理批准手续。申请人签订对外担保合同后，应当到外汇管理机关办理对外担保登记。\n经国务院批准为使用外国政府或者国际金融组织贷款进行转贷提供对外担保的，不适用前款规定。\n第二十条 银行业金融机构在经批准的经营范围内可以直接向境外提供商业贷款。其他境内机构向境外提供商业贷款，应当向外汇管理机关提出申请，外汇管理机关根据申请人的资产负债等情况作出批准或者不批准的决定；国家规定其经营范围需经有关主管部门批准的，应当在向外汇管理机关提出申请前办理批准手续。\n向境外提供商业贷款，应当按照国务院外汇管理部门的规定办理登记。\n第二十一条 资本项目外汇收入保留或者卖给经营结汇、售汇业务的金融机构，应当经外汇管理机关批准，但国家规定无需批准的除外。\n第二十二条 资本项目外汇支出，应当按照国务院外汇管理部门关于付汇与购汇的管理规定，凭有效单证以自有外汇支付或者向经营结汇、售汇业务的金融机构购汇支付。国家规定应当经外汇管理机关批准的，应当在外汇支付前办理批准手续。\n依法终止的外商投资企业，按照国家有关规定进行清算、纳税后，属于外方投资者所有的人民币，可以向经营结汇、售汇业务的金融机构购汇汇出。\n第二十三条 资本项目外汇及结汇资金，应当按照有关主管部门及外汇管理机关批准的用途使用。外汇管理机关有权对资本项目外汇及结汇资金使用和账户变动情况进行监督检查。","level":1},{"name":"第四章 金融机构外汇业务管理","text":"第二十四条 金融机构经营或者终止经营结汇、售汇业务，应当经外汇管理机关批准；经营或者终止经营其他外汇业务，应当按照职责分工经外汇管理机关或者金融业监督管理机构批准。\n第二十五条 外汇管理机关对金融机构外汇业务实行综合头寸管理，具体办法由国务院外汇管理部门制定。\n第二十六条 金融机构的资本金、利润以及因本外币资产不匹配需要进行人民币与外币间转换的，应当经外汇管理机关批准。","level":1},{"name":"第五章 人民币汇率和外汇市场管理","text":"第二十七条 人民币汇率实行以市场供求为基础的、有管理的浮动汇率制度。\n第二十八条 经营结汇、售汇业务的金融机构和符合国务院外汇管理部门规定条件的其他机构，可以按照国务院外汇管理部门的规定在银行间外汇市场进行外汇交易。\n第二十九条 外汇市场交易应当遵循公开、公平、公正和诚实信用的原则。\n第三十条 外汇市场交易的币种和形式由国务院外汇管理部门规定。\n第三十一条 国务院外汇管理部门依法监督管理全国的外汇市场。\n第三十二条 国务院外汇管理部门可以根据外汇市场的变化和货币政策的要求，依法对外汇市场进行调节。","level":1},{"name":"第六章 监督管理","text":"第三十三条 外汇管理机关依法履行职责，有权采取下列措施：\n(一)对经营外汇业务的金融机构进行现场检查；\n(二)进入涉嫌外汇违法行为发生场所调查取证；\n(三)询问有外汇收支或者外汇经营活动的机构和个人，要求其对与被调查外汇违法事件直接有关的事项作出说明；\n(四)查阅、复制与被调查外汇违法事件直接有关的交易单证等资料；\n(五)查阅、复制被调查外汇违法事件的当事人和直接有关的单位、个人的财务会计资料及相关文件，对可能被转移、隐匿或者毁损的文件和资料，可以予以封存；\n(六)经国务院外汇管理部门或者省级外汇管理机关负责人批准，查询被调查外汇违法事件的当事人和直接有关的单位、个人的账户，但个人储蓄存款账户除外；\n(七)对有证据证明已经或者可能转移、隐匿违法资金等涉案财产或者隐匿、伪造、毁损重要证据的，可以申请人民法院冻结或者查封。\n有关单位和个人应当配合外汇管理机关的监督检查，如实说明有关情况并提供有关文件、资料，不得拒绝、阻碍和隐瞒。\n第三十四条 外汇管理机关依法进行监督检查或者调查，监督检查或者调查的人员不得少于2人，并应当出示证件。监督检查、调查的人员少于2人或者未出示证件的，被监督检查、调查的单位和个人有权拒绝。\n第三十五条 有外汇经营活动的境内机构，应当按照国务院外汇管理部门的规定报送财务会计报告、统计报表等资料。\n第三十六条 经营外汇业务的金融机构发现客户有外汇违法行为的，应当及时向外汇管理机关报告。\n第三十七条 国务院外汇管理部门为履行外汇管理职责，可以从国务院有关部门、机构获取所必需的信息，国务院有关部门、机构应当提供。\n国务院外汇管理部门应当向国务院有关部门、机构通报外汇管理工作情况。\n第三十八条 任何单位和个人都有权举报外汇违法行为。\n外汇管理机关应当为举报人保密，并按照规定对举报人或者协助查处外汇违法行为有功的单位和个人给予奖励。","level":1},{"name":"第七章 法律责任","text":"第三十九条 有违反规定将境内外汇转移境外，或者以欺骗手段将境内资本转移境外等逃汇行为的，由外汇管理机关责令限期调回外汇，处逃汇金额30%以下的罚款；情节严重的，处逃汇金额30%以上等值以下的罚款；构成犯罪的，依法追究刑事责任。\n第四十条 有违反规定以外汇收付应当以人民币收付的款项，或者以虚假、无效的交易单证等向经营结汇、售汇业务的金融机构骗购外汇等非法套汇行为的，由外汇管理机关责令对非法套汇资金予以回兑，处非法套汇金额30%以下的罚款；情节严重的，处非法套汇金额30%以上等值以下的罚款；构成犯罪的，依法追究刑事责任。\n第四十一条 违反规定将外汇汇入境内的，由外汇管理机关责令改正，处违法金额30%以下的罚款；情节严重的，处违法金额30%以上等值以下的罚款。\n非法结汇的，由外汇管理机关责令对非法结汇资金予以回兑，处违法金额30%以下的罚款。\n第四十二条 违反规定携带外汇出入境的，由外汇管理机关给予警告，可以处违法金额20%以下的罚款。法律、行政法规规定由海关予以处罚的，从其规定。\n第四十三条 有擅自对外借款、在境外发行债券或者提供对外担保等违反外债管理行为的，由外汇管理机关给予警告，处违法金额30%以下的罚款。\n第四十四条 违反规定，擅自改变外汇或者结汇资金用途的，由外汇管理机关责令改正，没收违法所得，处违法金额30%以下的罚款；情节严重的，处违法金额30%以上等值以下的罚款。\n有违反规定以外币在境内计价结算或者划转外汇等非法使用外汇行为的，由外汇管理机关责令改正，给予警告，可以处违法金额30%以下的罚款。\n第四十五条 私自买卖外汇、变相买卖外汇、倒买倒卖外汇或者非法介绍买卖外汇数额较大的，由外汇管理机关给予警告，没收违法所得，处违法金额30%以下的罚款；情节严重的，处违法金额30%以上等值以下的罚款；构成犯罪的，依法追究刑事责任。\n第四十六条 未经批准擅自经营结汇、售汇业务的，由外汇管理机关责令改正，有违法所得的，没收违法所得，违法所得50万元以上的，并处违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不足50万元的，处50万元以上200万元以下的罚款；情节严重的，由有关主管部门责令停业整顿或者吊销业务许可证；构成犯罪的，依法追究刑事责任。\n未经批准经营结汇、售汇业务以外的其他外汇业务的，由外汇管理机关或者金融业监督管理机构依照前款规定予以处罚。\n第四十七条 金融机构有下列情形之一的，由外汇管理机关责令限期改正，没收违法所得，并处20万元以上100万元以下的罚款；情节严重或者逾期不改正的，由外汇管理机关责令停止经营相关业务：\n(一)办理经常项目资金收付，未对交易单证的真实性及其与外汇收支的一致性进行合理审查的；\n(二)违反规定办理资本项目资金收付的；\n(三)违反规定办理结汇、售汇业务的；\n(四)违反外汇业务综合头寸管理的；\n(五)违反外汇市场交易管理的。\n第四十八条 有下列情形之一的，由外汇管理机关责令改正，给予警告，对机构可以处30万元以下的罚款，对个人可以处5万元以下的罚款：\n(一)未按照规定进行国际收支统计申报的；\n(二)未按照规定报送财务会计报告、统计报表等资料的；\n(三)未按照规定提交有效单证或者提交的单证不真实的；\n(四)违反外汇账户管理规定的；\n(五)违反外汇登记管理规定的；\n(六)拒绝、阻碍外汇管理机关依法进行监督检查或者调查的。\n第四十九条 境内机构违反外汇管理规定的，除依照本条例给予处罚外，对直接负责的主管人员和其他直接责任人员，应当给予处分；对金融机构负有直接责任的董事、监事、高级管理人员和其他直接责任人员给予警告，处5万元以上50万元以下的罚款；构成犯罪的，依法追究刑事责任。\n第五十条 外汇管理机关工作人员徇私舞弊、滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。\n第五十一条 当事人对外汇管理机关作出的具体行政行为不服的，可以依法申请行政复议；对行政复议决定仍不服的，可以依法向人民法院提起行政诉讼。","level":1},{"name":"第八章 附则","text":"第五十二条 本条例下列用语的含义：\n(一)境内机构，是指中华人民共和国境内的国家机关、企业、事业单位、社会团体、部队等，外国驻华外交领事机构和国际组织驻华代表机构除外。\n(二)境内个人，是指中国公民和在中华人民共和国境内连续居住满1年的外国人，外国驻华外交人员和国际组织驻华代表除外。\n(三)经常项目，是指国际收支中涉及货物、服务、收益及经常转移的交易项目等。\n(四)资本项目，是指国际收支中引起对外资产和负债水平发生变化的交易项目，包括资本转移、直接投资、证券投资、衍生产品及贷款等。\n第五十三条 非金融机构经营结汇、售汇业务，应当由国务院外汇管理部门批准，具体管理办法由国务院外汇管理部门另行制定。\n第五十四条 本条例自公布之日起施行。","level":1}]},{"id":"n0302","sections":[{"name":"","text":"中华人民共和国进口计量器具\n监督管理办法\n(1989年10月11日国务院批准 1989年11月4日国家技术监督局发布 根据2016年2月6日《国务院关于修改部分行政法规的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为加强进口计量器具的监督管理，根据《中华人民共和国计量法》和《中华人民共和国计量法实施细则》的有关规定，制定本办法。\n第二条 任何单位和个人进口计量器具，以及外商(含外国制造商、经销商，下同)或其代理人在中国销售计量器具，都必须遵守本办法。\n第三条 进口计量器具的监督管理，由国务院计量行政部门主管，具体实施由国务院和地方有关部门分工负责。","level":1},{"name":"第二章 进口计量器具的型式批准","text":"第四条 凡进口或外商在中国境内销售列入本办法所附《中华人民共和国进口计量器具型式审查目录》内的计量器具的，应向国务院计量行政部门申请办理型式批准。\n属进口的，由外商申请型式批准。\n属外商在中国境内销售的，由外商或其代理人申请型式批准。\n国务院计量行政部门可根据情况变化对《中华人民共和国进口计量器具型式审查目录》作个别调整。\n第五条 外商或其代理人申请型式批准，须向国务院计量行政部门递交型式批准申请书、计量器具样机照片和必要的技术资料。\n国务院计量行政部门应根据外商或其代理人递交的资料进行计量法制审查。\n第六条 国务院计量行政部门接受申请后，负责安排授权的技术机构进行定型鉴定，并通知外商或其代理人向承担定型鉴定的技术机构提供样机和以下技术资料：\n(一)计量器具的技术说明书；\n(二)计量器具的总装图、结构图和电路图；\n(三)技术标准文件和检验方法；\n(四)样机测试报告；\n(五)使用说明书。\n定型鉴定所需的样机由外商或其代理人无偿提供。海关凭国务院计量行政部门的保函验放并免收关税。样机经鉴定后退还申请人。\n第七条 定型鉴定按鉴定大纲进行。鉴定大纲由承担鉴定的技术机构，根据国务院计量行政部门发布的《计量器具定型鉴定技术规范》的要求制定。主要内容包括：外观检查、计量性能考核以及安全性、环境适应性、可靠性和寿命试验等。\n第八条 定型鉴定的结果由承担鉴定的技术机构报国务院计量行政部门审核。经审核合格的，由国务院计量行政部门向申请人颁发《中华人民共和国进口计量器具型式批准证书》，并准予在相应的计量器具和包装上使用中华人民共和国进口计量器具型式批准的标志和编号。\n第九条 承担定型鉴定的技术机构及其工作人员，对申请人提供的技术资料必须保密。\n第十条 有下列情况之一的，经国务院计量行政部门同意，可申请办理临时型式批准，具体办法由国务院计量行政部门规定：\n(一)展览会留购的；\n(二)确属急需的；\n(三)销售量极少的；\n(四)国内暂无定型鉴定能力的。\n第十一条 外国制造的计量器具经我国型式批准后，由国务院计量行政部门予以公布。","level":1},{"name":"第三章 进口计量器具的审批","text":"第十二条 申请进口计量器具，按国家关于进口商品的规定程序进行审批。\n负责审批的有关主管部门和归口审查部门，应对申请进口《中华人民共和国依法管理的计量器具目录》内的计量器具进行法定计量单位的审查，对申请进口本办法第四条规定的计量器具审查是否经过型式批准。经审查不合规定的，审批部门不得批准进口，外贸经营单位不得办理订货手续。\n海关对进口计量器具凭审批部门的批件验放。\n第十三条 因特殊需要，申请进口非法定计量单位的计量器具和国务院禁止使用的其他计量器具，须经省、自治区、直辖市人民政府计量行政部门批准。\n第十四条 申请进口非法定计量单位的计量器具和国务院禁止使用的其他计量器具的单位，应向省、自治区、直辖市人民政府计量行政部门提供以下材料和文件：\n(一)申请报告；\n(二)计量器具的性能及技术指标；\n(三)计量器具的照片和使用说明；\n(四)本单位上级主管部门的批件。","level":1},{"name":"第四章 法律责任","text":"第十五条 违反本办法规定，进口非法定计量单位的计量器具或国务院禁止使用的其他计量器具的，按照《中华人民共和国计量法实施细则》第四十四条规定追究法律责任。\n第十六条 违反本办法第四条规定，进口或销售未经国务院计量行政部门型式批准的计量器具的，计量行政部门有权封存其计量器具，责令其补办型式批准手续，并可处以相当于进口或销售额百分之三十以下的罚款。\n第十七条 承担进口计量器具定型鉴定的技术机构违反本办法第九条规定的，按照《中华人民共和国计量法实施细则》第五十八条规定追究法律责任。","level":1},{"name":"第五章 附则","text":"第十八条 引进成套设备中配套的计量器具以及不以销售为目的的计量器具的监督管理，按国家有关规定办理。\n第十九条 与本办法有关的申请书、证书和标志式样，由国务院计量行政部门统一制定。\n第二十条 申请进口计量器具的型式批准和定型鉴定，应按国家有关规定缴纳费用。\n第二十一条 进口用于统一量值的标准物质的监督管理，可参照本办法执行。\n第二十二条 本办法由国务院计量行政部门负责解释。\n第二十三条 本办法自发布之日起施行。\n附：\n中华人民共和国进口计量器具型式审查目录\n1．衡器(含天平)\n2．传感器\n3．声级计\n4．三坐标测量机\n5．表面粗糙度测量仪\n6．大地测量仪器\n7．热量计\n8．流量计(含水表、煤气表)\n9．压力计(含血压计)\n10．温度计\n11．数字电压表\n12．场强计\n13．心、脑电图仪(机)\n14．有害气体、粉尘、水质污染监测仪\n15．电离辐射防护仪\n16．分光光度计(含紫外、红外、可见光光度计)\n17．气相、液相色谱仪\n18．温度、水分测量仪","level":1}]},{"id":"n0303","sections":[{"name":"","text":"化妆品卫生监督条例\n(1989年9月26日国务院批准 1989年11月13日卫生部令第3号发布 根据2019年3月2日《国务院关于修改部分行政法规的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为加强化妆品的卫生监督，保证化妆品的卫生质量和使用安全，保障消费者健康，制定本条例。\n第二条 本条例所称的化妆品，是指以涂擦、喷洒或者其他类似的方法，散布于人体表面任何部位(皮肤、毛发、指甲、口唇等)，以达到清洁、消除不良气味、护肤、美容和修饰目的的日用化学工业产品。\n第三条 国家实行化妆品卫生监督制度。国务院化妆品监督管理部门主管全国化妆品的卫生监督工作，县以上地方各级人民政府的化妆品监督管理部门主管本辖区内化妆品的卫生监督工作。\n第四条 凡从事化妆品生产、经营的单位和个人都必须遵守本条例。","level":1},{"name":"第二章 化妆品生产的卫生监督","text":"第五条 对化妆品生产企业实行化妆品生产许可证制度。\n化妆品生产许可证由省、自治区、直辖市化妆品监督管理部门批准并颁发。化妆品生产许可证有效期五年。\n未取得化妆品生产许可证的单位，不得从事化妆品生产。\n第六条 化妆品生产企业必须符合下列卫生要求：\n(一)生产企业应当建在清洁区域内，与有毒、有害场所保持符合卫生要求的间距。\n(二)生产企业厂房的建筑应当坚固、清洁。车间内天花板、墙壁、地面应当采用光洁建筑材料，应当具有良好的采光(或照明)，并应当具有防止和消除鼠害和其他有害昆虫及其孳生条件的设施和措施。\n(三)生产企业应当设有与产品品种、数量相适应的化妆品原料、加工、包装、贮存等厂房或场所。\n(四)生产车间应当有适合产品特点的相应的生产设施，工艺规程应当符合卫生要求。\n(五)生产企业必须具有能对所生产的化妆品进行微生物检验的仪器设备和检验人员。\n第七条 直接从事化妆品生产的人员，必须每年进行健康检查，取得健康证后方可从事化妆品的生产活动。\n凡患有手癣、指甲癣、手部湿疹、发生于手部的银屑病或者鳞屑、渗出性皮肤病以及患有痢疾、伤寒、病毒性肝炎、活动性肺结核等传染病的人员，不得直接从事化妆品生产活动。\n第八条 生产化妆品所需的原料、辅料以及直接接触化妆品的容器和包装材料必须符合国家卫生标准。\n第九条 使用化妆品新原料生产化妆品，必须经国务院化妆品监督管理部门批准。\n化妆品新原料是指在国内首次使用于化妆品生产的天然或人工原料。\n第十条 生产特殊用途的化妆品，必须经国务院化妆品监督管理部门批准，取得批准文号后方可生产。\n特殊用途化妆品是指用于育发、染发、烫发、脱毛、美乳、健美、除臭、祛斑、防晒的化妆品。\n第十一条 生产企业在化妆品投放市场前，必须按照国家《化妆品卫生标准》对产品进行卫生质量检验，对质量合格的产品应当附有合格标记。未经检验或者不符合卫生标准的产品不得出厂。\n第十二条 化妆品标签上应当注明产品名称、厂名，并注明生产企业化妆品生产许可证编号；小包装或者说明书上应当注明生产日期和有效使用期限。特殊用途的化妆品，还应当注明批准文号。对可能引起不良反应的化妆品，说明书上应当注明使用方法、注意事项。\n化妆品标签、小包装或者说明书上不得注有适应症，不得宣传疗效，不得使用医疗术语。","level":1},{"name":"第三章 化妆品经营的卫生监督","text":"第十三条 化妆品经营单位和个人不得销售下列化妆品：\n(一)未取得化妆品生产许可证的企业所生产的化妆品；\n(二)无质量合格标记的化妆品；\n(三)标签、小包装或者说明书不符合本条例第十二条规定的化妆品；\n(四)未取得批准文号的特殊用途化妆品；\n(五)超过使用期限的化妆品。\n第十四条 化妆品的广告宣传不得有下列内容：\n(一)化妆品名称、制法、效用或者性能有虚假夸大的；\n(二)使用他人名义保证或以暗示方法使人误解其效用的；\n(三)宣传医疗作用的。\n第十五条 首次进口的特殊用途化妆品，进口单位必须提供该化妆品的说明书、质量标准、检验方法等有关资料和样品以及出口国(地区)批准生产的证明文件，经国务院化妆品监督管理部门批准，方可签订进口合同。首次进口的其他化妆品，应当按照规定备案。\n第十六条 进口的化妆品，必须经国家商检部门检验；检验合格的，方准进口。\n个人自用进口的少量化妆品，按照海关规定办理进口手续。","level":1},{"name":"第四章 化妆品卫生监督机构与职责","text":"第十七条 各级化妆品监督管理部门行使化妆品卫生监督职责。\n第十八条 国务院化妆品监督管理部门聘请科研、医疗、生产、卫生管理等有关专家组成化妆品安全性评审组，对特殊用途的化妆品和化妆品新原料进行安全性评审，对化妆品引起的重大事故进行技术鉴定。\n第十九条 各级化妆品监督管理部门设化妆品卫生监督员，对化妆品实施卫生监督。\n化妆品卫生监督员，由省、自治区、直辖市化妆品监督管理部门和国务院化妆品监督管理部门，从符合条件的卫生专业人员中聘任，并发给其证章和证件。\n第二十条 化妆品卫生监督员在实施化妆品卫生监督时，应当佩戴证章，出示证件。\n化妆品卫生监督员对生产企业提供的技术资料应当负责保密。\n第二十一条 化妆品卫生监督员有权按照国家规定向生产企业和经营单位抽检样品，索取与卫生监督有关的安全性资料，任何单位不得拒绝、隐瞒和提供假材料。\n第二十二条 各级化妆品监督管理部门和化妆品卫生监督员不得以技术咨询、技术服务等方式参与生产、销售化妆品，不得监制化妆品。\n第二十三条 对因使用化妆品引起不良反应的病例，各医疗单位应当向当地化妆品监督管理部门报告。","level":1},{"name":"第五章 罚则","text":"第二十四条 未取得化妆品生产许可证的企业擅自生产化妆品的，责令该企业停产，没收产品及违法所得，并且可以处违法所得三到五倍的罚款。\n第二十五条 生产未取得批准文号的特殊用途的化妆品，或者使用化妆品禁用原料和未经批准的化妆品新原料的，没收产品及违法所得，处违法所得三到五倍的罚款，并且可以责令该企业停产或者吊销化妆品生产许可证。\n第二十六条 违反本条例规定，进口或者销售未经批准或者检验的进口化妆品的，没收产品及违法所得，并且可以处违法所得三到五倍的罚款。\n对已取得批准文号的生产特殊用途化妆品的企业，违反本条例规定，情节严重的，可以撤销产品的批准文号。\n第二十七条 生产或者销售不符合国家《化妆品卫生标准》的化妆品的，没收产品及违法所得，并且可以处违法所得三到五倍的罚款。\n第二十八条 对违反本条例其他有关规定的，处以警告，责令限期改进；情节严重的，对生产企业，可以责令该企业停产或者吊销化妆品生产许可证，对经营单位，可以责令其停止经营，没收违法所得，并且可以处违法所得二到三倍的罚款。\n第二十九条 本条例规定的行政处罚，由县级以上化妆品监督管理部门决定。违反本条例第十四条有关广告管理的行政处罚，由市场监督管理部门决定。\n吊销化妆品生产许可证的处罚由省、自治区、直辖市化妆品监督管理部门决定；撤销特殊用途化妆品批准文号的处罚由国务院化妆品监督管理部门决定。\n罚款及没收违法所得全部上交国库。没收的产品，由化妆品监督管理部门监督处理。\n第三十条 当事人对化妆品监督管理部门的行政处罚决定不服的，可以在收到通知书次日起十五日内向上一级化妆品监督管理部门申请复议。上一级化妆品监督管理部门应当在三十日内给予答复。当事人对上一级化妆品监督管理部门复议决定不服的，可以在收到复议通知书次日起十五日内向人民法院起诉。但对化妆品监督管理部门所作出的没收产品及责令停产的处罚决定必须立即执行。当事人对处罚决定不执行，逾期又不起诉的，化妆品监督管理部门可以申请人民法院强制执行。\n第三十一条 对违反本条例造成人体损伤或者发生中毒事故的，有直接责任的生产企业和经营单位或者个人应负损害赔偿责任。\n对造成严重后果，构成犯罪的，由司法机关依法追究刑事责任。\n第三十二条 化妆品卫生监督员滥用职权，营私舞弊以及泄露企业提供的技术资料的，由化妆品监督管理部门给予行政处分，造成严重后果，构成犯罪的，由司法机关依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第三十三条 中国人民解放军所属单位生产的投放市场的化妆品的卫生监督，依照本条例执行。\n第三十四条 本条例的实施细则由国务院化妆品监督管理部门制定。\n第三十五条 本条例自1990年1月1日起施行。","level":1}]},{"id":"n0304","sections":[{"name":"","text":"农民专业合作社登记管理条例\n(2007年5月28日中华人民共和国国务院令第498号公布 根据2014年2月19日《国务院关于废止和修改部分行政法规的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了确认农民专业合作社的法人资格，规范农民专业合作社登记行为，依据《中华人民共和国农民专业合作社法》，制定本条例。\n第二条 农民专业合作社的设立、变更和注销，应当依照《中华人民共和国农民专业合作社法》和本条例的规定办理登记。\n申请办理农民专业合作社登记，申请人应当对申请材料的真实性负责。\n第三条 农民专业合作社经登记机关依法登记，领取农民专业合作社法人营业执照(以下简称营业执照)，取得法人资格。未经依法登记，不得以农民专业合作社名义从事经营活动。\n第四条 工商行政管理部门是农民专业合作社登记机关。国务院工商行政管理部门负责全国的农民专业合作社登记管理工作。\n农民专业合作社由所在地的县(市)、区工商行政管理部门登记。\n国务院工商行政管理部门可以对规模较大或者跨地区的农民专业合作社的登记管辖做出特别规定。","level":1},{"name":"第二章 登记事项","text":"第五条 农民专业合作社的登记事项包括：\n(一)名称；\n(二)住所；\n(三)成员出资总额；\n(四)业务范围；\n(五)法定代表人姓名。\n第六条 农民专业合作社的名称应当含有“专业合作社”字样，并符合国家有关企业名称登记管理的规定。\n第七条 农民专业合作社的住所是其主要办事机构所在地。\n第八条 农民专业合作社成员可以用货币出资，也可以用实物、知识产权等能够用货币估价并可以依法转让的非货币财产作价出资。成员以非货币财产出资的，由全体成员评估作价。成员不得以劳务、信用、自然人姓名、商誉、特许经营权或者设定担保的财产等作价出资。\n成员的出资额以及出资总额应当以人民币表示。成员出资额之和为成员出资总额。\n第九条 农民专业合作社以其成员为主要服务对象，业务范围可以有农业生产资料购买，农产品销售、加工、运输、贮藏以及与农业生产经营有关的技术、信息等服务。\n农民专业合作社的业务范围由其章程规定。\n第十条 农民专业合作社理事长为农民专业合作社的法定代表人。","level":1},{"name":"第三章 设立登记","text":"第十一条 申请设立农民专业合作社，应当由全体设立人指定的代表或者委托的代理人向登记机关提交下列文件：\n(一)设立登记申请书；\n(二)全体设立人签名、盖章的设立大会纪要；\n(三)全体设立人签名、盖章的章程；\n(四)法定代表人、理事的任职文件和身份证明；\n(五)载明成员的姓名或者名称、出资方式、出资额以及成员出资总额，并经全体出资成员签名、盖章予以确认的出资清单；\n(六)载明成员的姓名或者名称、公民身份号码或者登记证书号码和住所的成员名册，以及成员身份证明；\n(七)能够证明农民专业合作社对其住所享有使用权的住所使用证明；\n(八)全体设立人指定代表或者委托代理人的证明。\n农民专业合作社的业务范围有属于法律、行政法规或者国务院规定在登记前须经批准的项目的，应当提交有关批准文件。\n第十二条 农民专业合作社章程含有违反《中华人民共和国农民专业合作社法》以及有关法律、行政法规规定的内容的，登记机关应当要求农民专业合作社做相应修改。\n第十三条 具有民事行为能力的公民，以及从事与农民专业合作社业务直接有关的生产经营活动的企业、事业单位或者社会团体，能够利用农民专业合作社提供的服务，承认并遵守农民专业合作社章程，履行章程规定的入社手续的，可以成为农民专业合作社的成员。但是，具有管理公共事务职能的单位不得加入农民专业合作社。\n第十四条 农民专业合作社应当有5名以上的成员，其中农民至少应当占成员总数的80%。\n成员总数20人以下的，可以有1个企业、事业单位或者社会团体成员；成员总数超过20人的，企业、事业单位和社会团体成员不得超过成员总数的5%。\n第十五条 农民专业合作社的成员为农民的，成员身份证明为农业人口户口簿；无农业人口户口簿的，成员身份证明为居民身份证和土地承包经营权证或者村民委员会(居民委员会)出具的身份证明。\n农民专业合作社的成员不属于农民的，成员身份证明为居民身份证。\n农民专业合作社的成员为企业、事业单位或者社会团体的，成员身份证明为企业法人营业执照或者其他登记证书。\n第十六条 申请人提交的登记申请材料齐全、符合法定形式，登记机关能够当场登记的，应予当场登记，发给营业执照。\n除前款规定情形外，登记机关应当自受理申请之日起20日内，做出是否登记的决定。予以登记的，发给营业执照；不予登记的，应当给予书面答复，并说明理由。\n营业执照签发日期为农民专业合作社成立日期。\n第十七条 营业执照分为正本和副本，正本和副本具有同等法律效力。\n营业执照正本应当置于农民专业合作社住所的醒目位置。\n国家推行电子营业执照。电子营业执照与纸质营业执照具有同等法律效力。\n第十八条 营业执照遗失或者毁坏的，农民专业合作社应当申请补领。\n任何单位和个人不得伪造、变造、出租、出借、转让营业执照。\n第十九条 农民专业合作社的登记文书格式，营业执照的正本、副本样式以及电子营业执照标准，由国务院工商行政管理部门制定。","level":1},{"name":"第四章 变更登记和注销登记","text":"第二十条 农民专业合作社的名称、住所、成员出资总额、业务范围、法定代表人姓名发生变更的，应当自做出变更决定之日起30日内向原登记机关申请变更登记，并提交下列文件：\n(一)法定代表人签署的变更登记申请书；\n(二)成员大会或者成员代表大会做出的变更决议；\n(三)法定代表人签署的修改后的章程或者章程修正案；\n(四)法定代表人指定代表或者委托代理人的证明。\n第二十一条 农民专业合作社变更业务范围涉及法律、行政法规或者国务院规定须经批准的项目的，应当自批准之日起30日内申请变更登记，并提交有关批准文件。\n农民专业合作社的业务范围属于法律、行政法规或者国务院规定在登记前须经批准的项目有下列情形之一的，应当自事由发生之日起30日内申请变更登记或者依照本条例的规定办理注销登记：\n(一)许可证或者其他批准文件被吊销、撤销的；\n(二)许可证或者其他批准文件有效期届满的。\n第二十二条 农民专业合作社成员发生变更的，应当自本财务年度终了之日起30日内，将法定代表人签署的修改后的成员名册报送登记机关备案。其中，新成员入社的还应当提交新成员的身份证明。\n农民专业合作社因成员发生变更，使农民成员低于法定比例的，应当自事由发生之日起6个月内采取吸收新的农民成员入社等方式使农民成员达到法定比例。\n第二十三条 农民专业合作社修改章程未涉及登记事项的，应当自做出修改决定之日起30日内，将法定代表人签署的修改后的章程或者章程修正案报送登记机关备案。\n第二十四条 变更登记事项涉及营业执照变更的，登记机关应当换发营业执照。\n第二十五条 成立清算组的农民专业合作社应当自清算结束之日起30日内，由清算组全体成员指定的代表或者委托的代理人向原登记机关申请注销登记，并提交下列文件：\n(一)清算组负责人签署的注销登记申请书；\n(二)农民专业合作社依法做出的解散决议，农民专业合作社依法被吊销营业执照或者被撤销的文件，人民法院的破产裁定、解散裁判文书；\n(三)成员大会、成员代表大会或者人民法院确认的清算报告；\n(四)营业执照；\n(五)清算组全体成员指定代表或者委托代理人的证明。\n因合并、分立而解散的农民专业合作社，应当自做出解散决议之日起30日内，向原登记机关申请注销登记，并提交法定代表人签署的注销登记申请书、成员大会或者成员代表大会做出的解散决议以及债务清偿或者债务担保情况的说明、营业执照和法定代表人指定代表或者委托代理人的证明。\n经登记机关注销登记，农民专业合作社终止。","level":1},{"name":"第五章 法律责任","text":"第二十六条 提交虚假材料或者采取其他欺诈手段取得农民专业合作社登记的，由登记机关责令改正；情节严重的，撤销农民专业合作社登记。\n第二十七条 农民专业合作社有下列行为之一的，由登记机关责令改正；情节严重的，吊销营业执照：\n(一)登记事项发生变更，未申请变更登记的；\n(二)因成员发生变更，使农民成员低于法定比例满6个月的；\n(三)从事业务范围以外的经营活动的；\n(四)变造、出租、出借、转让营业执照的。\n第二十八条 农民专业合作社有下列行为之一的，由登记机关责令改正：\n(一)未依法将修改后的成员名册报送登记机关备案的；\n(二)未依法将修改后的章程或者章程修正案报送登记机关备案的。\n第二十九条 登记机关对不符合规定条件的农民专业合作社登记申请予以登记，或者对符合规定条件的登记申请不予登记的，对直接负责的主管人员和其他直接责任人员，依法给予处分。","level":1},{"name":"第六章 附则","text":"第三十条 农民专业合作社可以设立分支机构，并比照本条例有关农民专业合作社登记的规定，向分支机构所在地登记机关申请办理登记。农民专业合作社分支机构不具有法人资格。\n农民专业合作社分支机构有违法行为的，适用本条例的规定进行处罚。\n第三十一条 登记机关办理农民专业合作社登记不得收费。\n第三十二条 建立农民专业合作社年度报告制度。农民专业合作社年度报告办法由国务院工商行政管理部门制定。\n第三十三条 本条例施行前设立的农民专业合作社，应当自本条例施行之日起1年内依法办理登记。\n第三十四条 本条例自2007年7月1日起施行。","level":1}]},{"id":"n0305","sections":[{"name":"","text":"法规规章备案条例\n(2001年12月14日中华人民共和国国务院令第337号公布 自2002年1月1日起施行)\n第一条 为了维护社会主义法制的统一，加强对法规、规章的监督，根据立法法的有关规定，制定本条例。\n第二条 本条例所称法规，是指省、自治区、直辖市和较大的市的人民代表大会及其常务委员会依照法定职权和程序制定的地方性法规，经济特区所在地的省、市的人民代表大会及其常务委员会依照法定职权和程序制定的经济特区法规，以及自治州、自治县的人民代表大会依照法定职权和程序制定的自治条例和单行条例。\n本条例所称规章，包括部门规章和地方政府规章。部门规章，是指国务院各部、各委员会、中国人民银行、审计署和具有行政管理职能的直属机构(以下简称国务院部门)根据法律和国务院的行政法规、决定、命令，在本部门的职权范围内依照《规章制定程序条例》制定的规章。地方政府规章，是指省、自治区、直辖市和较大的市的人民政府根据法律、行政法规和本省、自治区、直辖市的地方性法规，依照《规章制定程序条例》制定的规章。\n第三条 法规、规章公布后，应当自公布之日起30日内，依照下列规定报送备案：\n(一)地方性法规、自治州和自治县的自治条例和单行条例由省、自治区、直辖市的人民代表大会常务委员会报国务院备案；\n(二)部门规章由国务院部门报国务院备案，两个或者两个以上部门联合制定的规章，由主办的部门报国务院备案；\n(三)省、自治区、直辖市人民政府规章由省、自治区、直辖市人民政府报国务院备案；\n(四)较大的市的人民政府规章由较大的市的人民政府报国务院备案，同时报省、自治区人民政府备案；\n(五)经济特区法规由经济特区所在地的省、市的人民代表大会常务委员会报国务院备案。\n第四条 国务院部门，省、自治区、直辖市和较大的市的人民政府应当依法履行规章备案职责，加强对规章备案工作的组织领导。\n国务院部门法制机构，省、自治区、直辖市人民政府和较大的市的人民政府法制机构，具体负责本部门、本地方的规章备案工作。\n第五条 国务院法制机构依照本条例的规定负责国务院的法规、规章备案工作，履行备案审查监督职责。\n第六条 依照本条例报送国务院备案的法规、规章，径送国务院法制机构。\n报送法规备案，按照全国人民代表大会常务委员会关于法规备案的有关规定执行。\n报送规章备案，应当提交备案报告、规章文本和说明，并按照规定的格式装订成册，一式十份。\n报送法规、规章备案，具备条件的，应当同时报送法规、规章的电子文本。\n第七条 报送法规、规章备案，符合本条例第二条和第六条第二款、第三款规定的，国务院法制机构予以备案登记；不符合第二条规定的，不予备案登记；符合第二条规定但不符合第六条第二款、第三款规定的，暂缓办理备案登记。\n暂缓办理备案登记的，由国务院法制机构通知制定机关补充报送备案或者重新报送备案；补充或者重新报送备案符合规定的，予以备案登记。\n第八条 经备案登记的法规、规章，由国务院法制机构按月公布目录。\n编辑出版法规、规章汇编的范围，应当以公布的法规、规章目录为准。\n第九条 国家机关、社会团体、企业事业组织、公民认为地方性法规同行政法规相抵触的，或者认为规章以及国务院各部门、省、自治区、直辖市和较大的市的人民政府发布的其他具有普遍约束力的行政决定、命令同法律、行政法规相抵触的，可以向国务院书面提出审查建议，由国务院法制机构研究并提出处理意见，按照规定程序处理。\n第十条 国务院法制机构对报送国务院备案的法规、规章，就下列事项进行审查：\n(一)是否超越权限；\n(二)下位法是否违反上位法的规定；\n(三)地方性法规与部门规章之间或者不同规章之间对同一事项的规定不一致，是否应当改变或者撤销一方的或者双方的规定；\n(四)规章的规定是否适当；\n(五)是否违背法定程序。\n第十一条 国务院法制机构审查法规、规章时，认为需要有关的国务院部门或者地方人民政府提出意见的，有关的机关应当在规定期限内回复；认为需要法规、规章的制定机关说明有关情况的，有关的制定机关应当在规定期限内予以说明。\n第十二条 经审查，地方性法规同行政法规相抵触的，由国务院提请全国人民代表大会常务委员会处理。\n第十三条 地方性法规与部门规章之间对同一事项的规定不一致的，由国务院法制机构提出处理意见，报国务院依照立法法第八十六条第一款第(二)项的规定处理。\n第十四条 经审查，规章超越权限，违反法律、行政法规的规定，或者其规定不适当的，由国务院法制机构建议制定机关自行纠正；或者由国务院法制机构提出处理意见报国务院决定，并通知制定机关。\n第十五条 部门规章之间、部门规章与地方政府规章之间对同一事项的规定不一致的，由国务院法制机构进行协调；经协调不能取得一致意见的，由国务院法制机构提出处理意见报国务院决定，并通知制定机关。\n第十六条 对《规章制定程序条例》第二条第二款、第八条第二款规定的无效规章，国务院法制机构不予备案，并通知制定机关。\n规章在制定技术上存在问题的，国务院法制机构可以向制定机关提出处理意见，由制定机关自行处理。\n第十七条 规章的制定机关应当自接到本条例第十四条、第十五条、第十六条规定的通知之日起30日内，将处理情况报国务院法制机构。\n第十八条 根据本条例第十五条作出的处理结果，可以作为对最高人民法院依照行政诉讼法第五十三条送请国务院解释或者裁决的答复。\n第十九条 法规、规章的制定机关应当于每年1月底前将上一年所制定的法规、规章目录报国务院法制机构。\n第二十条 对于不报送规章备案或者不按时报送规章备案的，由国务院法制机构通知制定机关，限期报送；逾期仍不报送的，给予通报，并责令限期改正。\n第二十一条 省、自治区、直辖市人民政府应当依法加强对下级行政机关发布的规章和其他具有普遍约束力的行政决定、命令的监督，依照本条例的有关规定，建立相关的备案审查制度，维护社会主义法制的统一，保证法律、法规的正确实施。\n第二十二条 本条例自2002年1月1日起施行。1990年2月18日国务院发布的《法规、规章备案规定》同时废止。","level":0}]},{"id":"n0306","sections":[{"name":"","text":"军用饮食供应站供水站管理办法\n(1989年10月4日国务院、中央军委批准 1989年11月17日民政部、总后勤部令第1号发布 根据2019年3月2日《国务院关于修改部分行政法规的决定》修订)\n第一条 为了加强军用饮食供应站、军用供水站(以下统称军供站)的管理，保障军队平时、战时在运输途中的饮食饮水供应，制定本办法。\n第二条 军供站是人民政府支援过往部队的组织机构和战备设施，在人民政府领导下，由退役军人事务部门负责管理。\n第三条 军供站的任务是保障成批过往的部队、入伍的新兵、退伍的老兵和支前民兵、民工等在运输途中的饮食饮水的供应以及军运马匹的草料和饮水的供应。\n第四条 军供站由省、自治区、直辖市人民政府根据军区的要求，在铁路、公路、水路沿线设置。\n第五条 军供站分为常设站和临时站。常设站设置在主要铁路和公路干线的大站、水路的重要港口等军事运输繁忙地方；临时站设置在大批或者紧急军事运输任务需要的地方，任务完成后即行撤销。\n第六条 常设军用饮食供应站的基本建设项目应当有厨房、餐厅、仓库、锅炉房、办公室、宿舍、厕所、汽车库、平场、盥洗设施，并根据需要设置遛马场和饮马设备。常设军用供水站的基本建设项目应当有锅炉房、办公室、宿舍、厕所、盥洗设施。\n第七条 军供站的基本建设、设施维修、设备购置和用于过往部队接待工作的经费，军供站固定编制人员的工资、福利费和公用经费，按照国家规定的开支渠道，由地方财政安排解决。\n第八条 常设军供站应当有少量固定编制的人员，其名额由省、自治区、直辖市人民政府根据军供站的军供任务和所处战略位置的需要确定，并在省、自治区、直辖市的行政编制总额中解决。\n遇到大批军供任务，军供站工作人员不足时，由当地人民政府临时抽调人员协助工作。\n第九条 国家在新建、改建车站和港口时，铁路、交通部门应当根据总后勤部军事交通部的要求，将军供站列入工程计划之内一并修建。工程竣工后，铁路、交通部门应当将军供站移交给人民政府的退役军人事务部门。退役军人事务部门对军供站的房屋和设备负责维修。\n第十条 中国人民解放军派驻铁路、交通部门的军事代表办事处负责对军供站的业务指导。在有大批军供任务时，军事交通部门应当向军供站预先通报供应任务和注意事项，并指定专人与军供站保持联系。必要时，应当派遣军事代表常驻军供站协助工作。\n第十一条 军供站应当根据有关法律、法规，经常对工作人员进行保卫和保密教育，建立、健全保卫和保密工作制度。\n第十二条 军供站按照正规化建设要求，实现工作制度化、程序化、标准化，加强对工作人员的思想教育和业务培训，不断提高应变能力和快速保障能力，做好军供工作。\n第十三条 对军供站供应工作的基本要求：\n(一)军供站应当根据供应通报和军事代表的要求，做到保质保量供应，保证部队按时用餐、用水；\n(二)军供站必须严格执行食品卫生的法律、法规，做好供应部队的饮食饮水的检查工作，防止食物中毒；\n(三)军供站应当贯彻勤俭办事的精神，厉行节约，反对铺张浪费，并建立严格的财务制度和物资管理制度，防止贪污、盗窃和挪用供应部队的物资等违法行为。每次供应任务完成后，军供站应当按照供应成本向部队核收伙食费、粮票及马料票、马草用款。\n第十四条 军供站所在地人民政府的有关部门负责做好下列工作：\n(一)商业、粮食、供销、煤炭等部门，分别负责保证供应过往部队所需的主副食品、燃料、必要生活用品和马草、马料，并按国家和有关部门规定，在品种和价格等方面实行优待。\n(二)卫生部门负责过往部队的饮食饮水的检验和伤病员的急救等工作，对不能随部队行动的伤病员负责收治。留在当地医院治疗的伤病员的医疗费、伙食费、归队差旅费和死亡丧葬费，由当地的武装部门垫支后，向所在军区的后勤部门实报实销。\n(三)铁路、交通部门负责解决铁路、公路、水路沿线的军供站的供电、通信、给水等设备。\n(四)交通部门应当按照对行政机关的有关规定减免军供站编制内的机动车辆的养路费。\n(五)公安部门负责军供站周围的治安管理、交通管理和保卫、保密工作，防止可能发生的破坏活动。\n第十五条 部队应当尊重地方工作人员，遵守军供站的供应制度和规定，凭供应通报就餐，并如数交付伙食费和粮票。使用马草马料，应如数交付马料票、马草用款。损坏餐具等物品应当照价赔偿。\n第十六条 军供站在保证完成军供任务的前提下，实行平战结合，可以利用现有设施，为部队服务，为社会服务。\n第十七条 本办法由退役军人事务部和总后勤部共同解释。\n第十八条 本办法自发布之日起施行。一九六五年四月七日国务院批转总参谋部、内务部制定的《军用饮食供应站、供水站组织管理暂行办法》同时废止。","level":0}]},{"id":"n0307","sections":[{"name":"","text":"民用核安全设备监督管理条例\n(2007年7月11日中华人民共和国国务院令第500号公布 根据2016年2月6日《国务院关于修改部分行政法规的决定》第一次修订 根据2019年3月2日《国务院关于修改部分行政法规的决定》第二次修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强对民用核安全设备的监督管理，保证民用核设施的安全运行，预防核事故，保障工作人员和公众的健康，保护环境，促进核能事业的顺利发展，制定本条例。\n第二条 本条例所称民用核安全设备，是指在民用核设施中使用的执行核安全功能的设备，包括核安全机械设备和核安全电气设备。\n民用核安全设备目录由国务院核安全监管部门商国务院有关部门制定并发布。\n第三条 民用核安全设备设计、制造、安装和无损检验活动适用本条例。\n民用核安全设备运离民用核设施现场进行的维修活动，适用民用核安全设备制造活动的有关规定。\n第四条 国务院核安全监管部门对民用核安全设备设计、制造、安装和无损检验活动实施监督管理。\n国务院核行业主管部门和其他有关部门依照本条例和国务院规定的职责分工负责有关工作。\n第五条 民用核安全设备设计、制造、安装和无损检验单位，应当建立健全责任制度，加强质量管理，并对其所从事的民用核安全设备设计、制造、安装和无损检验活动承担全面责任。\n民用核设施营运单位，应当对在役的民用核安全设备进行检查、试验、检验和维修，并对民用核安全设备的使用和运行安全承担全面责任。\n第六条 民用核安全设备设计、制造、安装和无损检验活动应当符合国家有关产业政策。\n国家鼓励民用核安全设备设计、制造、安装和无损检验的科学技术研究，提高安全水平。\n第七条 任何单位和个人对违反本条例规定的行为，有权向国务院核安全监管部门举报。国务院核安全监管部门接到举报，应当及时调查处理，并为举报人保密。","level":1},{"name":"第二章 标准","text":"第八条 民用核安全设备标准是从事民用核安全设备设计、制造、安装和无损检验活动的技术依据。\n第九条 国家建立健全民用核安全设备标准体系。制定民用核安全设备标准，应当充分考虑民用核安全设备的技术发展和使用要求，结合我国的工业基础和技术水平，做到安全可靠、技术成熟、经济合理。\n民用核安全设备标准包括国家标准、行业标准和企业标准。\n第十条 涉及核安全基本原则和技术要求的民用核安全设备国家标准，由国务院核安全监管部门组织拟定，由国务院标准化主管部门和国务院核安全监管部门联合发布；其他的民用核安全设备国家标准，由国务院核行业主管部门组织拟定，经国务院核安全监管部门认可，由国务院标准化主管部门发布。\n民用核安全设备行业标准，由国务院核行业主管部门组织拟定，经国务院核安全监管部门认可，由国务院核行业主管部门发布，并报国务院标准化主管部门备案。\n制定民用核安全设备国家标准和行业标准，应当充分听取有关部门和专家的意见。\n第十一条 尚未制定相应国家标准和行业标准的，民用核安全设备设计、制造、安装和无损检验单位应当采用经国务院核安全监管部门认可的标准。","level":1},{"name":"第三章 许可","text":"第十二条 民用核安全设备设计、制造、安装和无损检验单位应当依照本条例规定申请领取许可证。\n第十三条 申请领取民用核安全设备设计、制造、安装或者无损检验许可证的单位，应当具备下列条件：\n(一)具有法人资格；\n(二)有与拟从事活动相关或者相近的工作业绩，并且满5年以上；\n(三)有与拟从事活动相适应的、经考核合格的专业技术人员，其中从事民用核安全设备焊接和无损检验活动的专业技术人员应当取得相应的资格证书；\n(四)有与拟从事活动相适应的工作场所、设施和装备；\n(五)有健全的管理制度和完善的质量保证体系，以及符合核安全监督管理规定的质量保证大纲。\n申请领取民用核安全设备制造许可证或者安装许可证的单位，还应当制作有代表性的模拟件。\n第十四条 申请领取民用核安全设备设计、制造、安装或者无损检验许可证的单位，应当向国务院核安全监管部门提出书面申请，并提交符合本条例第十三条规定条件的证明材料。\n第十五条 国务院核安全监管部门应当自受理申请之日起45个工作日内完成审查，并对符合条件的颁发许可证，予以公告；对不符合条件的，书面通知申请单位并说明理由。\n国务院核安全监管部门在审查过程中，应当组织专家进行技术评审，并征求国务院核行业主管部门和其他有关部门的意见。技术评审所需时间不计算在前款规定的期限内。\n第十六条 民用核安全设备设计、制造、安装和无损检验许可证应当载明下列内容：\n(一)单位名称、地址和法定代表人；\n(二)准予从事的活动种类和范围；\n(三)有效期限；\n(四)发证机关、发证日期和证书编号。\n第十七条 民用核安全设备设计、制造、安装和无损检验单位变更单位名称、地址或者法定代表人的，应当自变更工商登记之日起20日内，向国务院核安全监管部门申请办理许可证变更手续。\n民用核安全设备设计、制造、安装和无损检验单位变更许可证规定的活动种类或者范围的，应当按照原申请程序向国务院核安全监管部门重新申请领取许可证。\n第十八条 民用核安全设备设计、制造、安装和无损检验许可证有效期为5年。\n许可证有效期届满，民用核安全设备设计、制造、安装和无损检验单位需要继续从事相关活动的，应当于许可证有效期届满6个月前，向国务院核安全监管部门提出延续申请。\n国务院核安全监管部门应当在许可证有效期届满前作出是否准予延续的决定；逾期未作决定的，视为准予延续。\n第十九条 禁止无许可证擅自从事或者不按照许可证规定的活动种类和范围从事民用核安全设备设计、制造、安装和无损检验活动。\n禁止委托未取得相应许可证的单位进行民用核安全设备设计、制造、安装和无损检验活动。\n禁止伪造、变造、转让许可证。","level":1},{"name":"第四章 设计、制造、安装和无损检验","text":"第二十条 民用核安全设备设计、制造、安装和无损检验单位，应当提高核安全意识，建立完善的质量保证体系，确保民用核安全设备的质量和可靠性。\n民用核设施营运单位，应当对民用核安全设备设计、制造、安装和无损检验活动进行质量管理和过程控制，做好监造和验收工作。\n第二十一条 民用核安全设备设计、制造、安装和无损检验单位，应当根据其质量保证大纲和民用核设施营运单位的要求，在民用核安全设备设计、制造、安装和无损检验活动开始前编制项目质量保证分大纲，并经民用核设施营运单位审查同意。\n第二十二条 民用核安全设备设计单位，应当在设计活动开始30日前，将下列文件报国务院核安全监管部门备案：\n(一)项目设计质量保证分大纲和程序清单；\n(二)设计内容和设计进度计划；\n(三)设计遵循的标准和规范目录清单，设计中使用的计算机软件清单；\n(四)设计验证活动清单。\n第二十三条 民用核安全设备制造、安装单位，应当在制造、安装活动开始30日前，将下列文件报国务院核安全监管部门备案：\n(一)项目制造、安装质量保证分大纲和程序清单；\n(二)制造、安装技术规格书；\n(三)分包项目清单；\n(四)制造、安装质量计划。\n第二十四条 民用核安全设备设计、制造、安装和无损检验单位，不得将国务院核安全监管部门确定的关键工艺环节分包给其他单位。\n第二十五条 民用核安全设备制造、安装、无损检验单位和民用核设施营运单位，应当聘用取得民用核安全设备焊工、焊接操作工和无损检验人员资格证书的人员进行民用核安全设备焊接和无损检验活动。\n民用核安全设备焊工、焊接操作工和无损检验人员由国务院核安全监管部门核准颁发资格证书。\n民用核安全设备焊工、焊接操作工和无损检验人员在民用核安全设备焊接和无损检验活动中，应当严格遵守操作规程。\n第二十六条 民用核安全设备无损检验单位应当客观、准确地出具无损检验结果报告。无损检验结果报告经取得相应资格证书的无损检验人员签字方为有效。\n民用核安全设备无损检验单位和无损检验人员对无损检验结果报告负责。\n第二十七条 民用核安全设备设计单位应当对其设计进行设计验证。设计验证由未参与原设计的专业人员进行。\n设计验证可以采用设计评审、鉴定试验或者不同于设计中使用的计算方法的其他计算方法等形式。\n第二十八条 民用核安全设备制造、安装单位应当对民用核安全设备的制造、安装质量进行检验。未经检验或者经检验不合格的，不得交付验收。\n第二十九条 民用核设施营运单位应当对民用核安全设备质量进行验收。有下列情形之一的，不得验收通过：\n(一)不能按照质量保证要求证明质量受控的；\n(二)出现重大质量问题未处理完毕的。\n第三十条 民用核安全设备设计、制造、安装和无损检验单位，应当对本单位所从事的民用核安全设备设计、制造、安装和无损检验活动进行年度评估，并于每年4月1日前向国务院核安全监管部门提交上一年度的评估报告。\n评估报告应当包括本单位工作场所、设施、装备和人员等变动情况，质量保证体系实施情况，重大质量问题处理情况以及国务院核安全监管部门和民用核设施营运单位提出的整改要求落实情况等内容。\n民用核安全设备设计、制造、安装和无损检验单位对本单位在民用核安全设备设计、制造、安装和无损检验活动中出现的重大质量问题，应当立即采取处理措施，并向国务院核安全监管部门报告。","level":1},{"name":"第五章 进出口","text":"第三十一条 为中华人民共和国境内民用核设施进行民用核安全设备设计、制造、安装和无损检验活动的境外单位，应当具备下列条件：\n(一)遵守中华人民共和国的法律、行政法规和核安全监督管理规定；\n(二)已取得所在国核安全监管部门规定的相应资质；\n(三)使用的民用核安全设备设计、制造、安装和无损检验技术是成熟的或者经过验证的；\n(四)采用中华人民共和国的民用核安全设备国家标准、行业标准或者国务院核安全监管部门认可的标准。\n第三十二条 为中华人民共和国境内民用核设施进行民用核安全设备设计、制造、安装和无损检验活动的境外单位，应当事先到国务院核安全监管部门办理注册登记手续。国务院核安全监管部门应当将境外单位注册登记情况抄送国务院核行业主管部门和其他有关部门。\n注册登记的具体办法由国务院核安全监管部门制定。\n第三十三条 国务院核安全监管部门及其所属的检验机构应当依法对进口的民用核安全设备进行安全检验。\n进口的民用核安全设备在安全检验合格后，由海关进行商品检验。\n第三十四条 国务院核安全监管部门根据需要，可以对境外单位为中华人民共和国境内民用核设施进行的民用核安全设备设计、制造、安装和无损检验活动实施核安全监督检查。\n第三十五条 民用核设施营运单位应当在对外贸易合同中约定有关民用核安全设备监造、装运前检验和监装等方面的要求。\n第三十六条 民用核安全设备的出口管理依照有关法律、行政法规的规定执行。","level":1},{"name":"第六章 监督检查","text":"第三十七条 国务院核安全监管部门及其派出机构，依照本条例规定对民用核安全设备设计、制造、安装和无损检验活动进行监督检查。监督检查分为例行检查和非例行检查。\n第三十八条 国务院核安全监管部门及其派出机构在进行监督检查时，有权采取下列措施：\n(一)向被检查单位的法定代表人和其他有关人员调查、了解情况；\n(二)进入被检查单位进行现场调查或者核查；\n(三)查阅、复制相关文件、记录以及其他有关资料；\n(四)要求被检查单位提交有关情况说明或者后续处理报告；\n(五)对有证据表明可能存在重大质量问题的民用核安全设备或者其主要部件，予以暂时封存。\n被检查单位应当予以配合，如实反映情况，提供必要资料，不得拒绝和阻碍。\n第三十九条 国务院核安全监管部门及其派出机构在进行监督检查时，应当对检查的内容、发现的问题以及处理情况作出记录，并由监督检查人员和被检查单位的有关负责人签字确认。被检查单位的有关负责人拒绝签字的，监督检查人员应当将有关情况记录在案。\n第四十条 民用核安全设备监督检查人员在进行监督检查时，应当出示证件，并为被检查单位保守技术秘密和业务秘密。\n民用核安全设备监督检查人员不得滥用职权侵犯企业的合法权益，或者利用职务上的便利索取、收受财物。\n民用核安全设备监督检查人员不得从事或者参与民用核安全设备经营活动。\n第四十一条 国务院核安全监管部门发现民用核安全设备设计、制造、安装和无损检验单位有不符合发证条件的情形的，应当责令其限期整改。\n第四十二条 国务院核行业主管部门应当加强对本行业民用核设施营运单位的管理，督促本行业民用核设施营运单位遵守法律、行政法规和核安全监督管理规定。","level":1},{"name":"第七章 法律责任","text":"第四十三条 国务院核安全监管部门及其民用核安全设备监督检查人员有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予处分；直接负责的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任：\n(一)不依照本条例规定颁发许可证的；\n(二)发现违反本条例规定的行为不予查处，或者接到举报后不依法处理的；\n(三)滥用职权侵犯企业的合法权益，或者利用职务上的便利索取、收受财物的；\n(四)从事或者参与民用核安全设备经营活动的；\n(五)在民用核安全设备监督管理工作中有其他违法行为的。\n第四十四条 无许可证擅自从事民用核安全设备设计、制造、安装和无损检验活动的，由国务院核安全监管部门责令停止违法行为，处50万元以上100万元以下的罚款；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员，处2万元以上10万元以下的罚款。\n第四十五条 民用核安全设备设计、制造、安装和无损检验单位不按照许可证规定的活动种类和范围从事民用核安全设备设计、制造、安装和无损检验活动的，由国务院核安全监管部门责令停止违法行为，限期改正，处10万元以上50万元以下的罚款；有违法所得的，没收违法所得；逾期不改正的，暂扣或者吊销许可证，对直接负责的主管人员和其他直接责任人员，处2万元以上10万元以下的罚款。\n第四十六条 民用核安全设备设计、制造、安装和无损检验单位变更单位名称、地址或者法定代表人，未依法办理许可证变更手续的，由国务院核安全监管部门责令限期改正；逾期不改正的，暂扣或者吊销许可证。\n第四十七条 单位伪造、变造、转让许可证的，由国务院核安全监管部门收缴伪造、变造的许可证或者吊销许可证，处10万元以上50万元以下的罚款；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员，处2万元以上10万元以下的罚款；构成违反治安管理行为的，由公安机关依法予以治安处罚；构成犯罪的，依法追究刑事责任。\n第四十八条 民用核安全设备设计、制造、安装和无损检验单位未按照民用核安全设备标准进行民用核安全设备设计、制造、安装和无损检验活动的，由国务院核安全监管部门责令停止违法行为，限期改正，禁止使用相关设计、设备，处10万元以上50万元以下的罚款；有违法所得的，没收违法所得；逾期不改正的，暂扣或者吊销许可证，对直接负责的主管人员和其他直接责任人员，处2万元以上10万元以下的罚款。\n第四十九条 民用核安全设备设计、制造、安装和无损检验单位有下列行为之一的，由国务院核安全监管部门责令停止违法行为，限期改正，处10万元以上50万元以下的罚款；逾期不改正的，暂扣或者吊销许可证，对直接负责的主管人员和其他直接责任人员，处2万元以上10万元以下的罚款：\n(一)委托未取得相应许可证的单位进行民用核安全设备设计、制造、安装和无损检验活动的；\n(二)聘用未取得相应资格证书的人员进行民用核安全设备焊接和无损检验活动的；\n(三)将国务院核安全监管部门确定的关键工艺环节分包给其他单位的。\n第五十条 民用核安全设备设计、制造、安装和无损检验单位对本单位在民用核安全设备设计、制造、安装和无损检验活动中出现的重大质量问题，未按照规定采取处理措施并向国务院核安全监管部门报告的，由国务院核安全监管部门责令停止民用核安全设备设计、制造、安装和无损检验活动，限期改正，处5万元以上20万元以下的罚款；逾期不改正的，暂扣或者吊销许可证，对直接负责的主管人员和其他直接责任人员，处2万元以上10万元以下的罚款。\n第五十一条 民用核安全设备设计、制造、安装和无损检验单位有下列行为之一的，由国务院核安全监管部门责令停止民用核安全设备设计、制造、安装和无损检验活动，限期改正；逾期不改正的，处5万元以上20万元以下的罚款，暂扣或者吊销许可证：\n(一)未按照规定编制项目质量保证分大纲并经民用核设施营运单位审查同意的；\n(二)在民用核安全设备设计、制造和安装活动开始前，未按照规定将有关文件报国务院核安全监管部门备案的；\n(三)未按照规定进行年度评估并向国务院核安全监管部门提交评估报告的。\n第五十二条 民用核安全设备无损检验单位出具虚假无损检验结果报告的，由国务院核安全监管部门处10万元以上50万元以下的罚款，吊销许可证；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员，处2万元以上10万元以下的罚款；构成犯罪的，依法追究刑事责任。\n第五十三条 民用核安全设备焊工、焊接操作工违反操作规程导致严重焊接质量问题的，由国务院核安全监管部门吊销其资格证书。\n第五十四条 民用核安全设备无损检验人员违反操作规程导致无损检验结果报告严重错误的，由国务院核安全监管部门吊销其资格证书。\n第五十五条 民用核安全设备设计单位未按照规定进行设计验证，或者民用核安全设备制造、安装单位未按照规定进行质量检验以及经检验不合格即交付验收的，由国务院核安全监管部门责令限期改正，处10万元以上50万元以下的罚款；有违法所得的，没收违法所得；逾期不改正的，吊销许可证，对直接负责的主管人员和其他直接责任人员，处2万元以上10万元以下的罚款。\n第五十六条 民用核设施营运单位有下列行为之一的，由国务院核安全监管部门责令限期改正，处100万元以上500万元以下的罚款；逾期不改正的，吊销其核设施建造许可证或者核设施运行许可证，对直接负责的主管人员和其他直接责任人员，处2万元以上10万元以下的罚款：\n(一)委托未取得相应许可证的单位进行民用核安全设备设计、制造、安装和无损检验活动的；\n(二)对不能按照质量保证要求证明质量受控，或者出现重大质量问题未处理完毕的民用核安全设备予以验收通过的。\n第五十七条 民用核安全设备设计、制造、安装和无损检验单位被责令限期整改，逾期不整改或者经整改仍不符合发证条件的，由国务院核安全监管部门暂扣或者吊销许可证。\n第五十八条 拒绝或者阻碍国务院核安全监管部门及其派出机构监督检查的，由国务院核安全监管部门责令限期改正；逾期不改正或者在接受监督检查时弄虚作假的，暂扣或者吊销许可证。\n第五十九条 违反本条例规定，被依法吊销许可证的单位，自吊销许可证之日起1年内不得重新申请领取许可证。","level":1},{"name":"第八章 附则","text":"第六十条 申请领取民用核安全设备设计、制造、安装或者无损检验许可证的单位，应当按照国家有关规定缴纳技术评审的费用。\n第六十一条 本条例下列用语的含义：\n(一)核安全机械设备，包括执行核安全功能的压力容器、钢制安全壳(钢衬里)、储罐、热交换器、泵、风机和压缩机、阀门、闸门、管道(含热交换器传热管)和管配件、膨胀节、波纹管、法兰、堆内构件、控制棒驱动机构、支承件、机械贯穿件以及上述设备的铸锻件等。\n(二)核安全电气设备，包括执行核安全功能的传感器(包括探测器和变送器)、电缆、机柜(包括机箱和机架)、控制台屏、显示仪表、应急柴油发电机组、蓄电池(组)、电动机、阀门驱动装置、电气贯穿件等。\n第六十二条 本条例自2008年1月1日起施行。","level":1}]},{"id":"n0308","sections":[{"name":"","text":"计算机软件保护条例\n(2001年12月20日中华人民共和国国务院令第339号公布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2013年1月30日《国务院关于修改〈计算机软件保护条例〉的决定》第二次修订)","level":0},{"name":"第一章 总则","text":"第一条 为了保护计算机软件著作权人的权益，调整计算机软件在开发、传播和使用中发生的利益关系，鼓励计算机软件的开发与应用，促进软件产业和国民经济信息化的发展，根据《中华人民共和国著作权法》，制定本条例。\n第二条 本条例所称计算机软件(以下简称软件)，是指计算机程序及其有关文档。\n第三条 本条例下列用语的含义：\n(一)计算机程序，是指为了得到某种结果而可以由计算机等具有信息处理能力的装置执行的代码化指令序列，或者可以被自动转换成代码化指令序列的符号化指令序列或者符号化语句序列。同一计算机程序的源程序和目标程序为同一作品。\n(二)文档，是指用来描述程序的内容、组成、设计、功能规格、开发情况、测试结果及使用方法的文字资料和图表等，如程序设计说明书、流程图、用户手册等。\n(三)软件开发者，是指实际组织开发、直接进行开发，并对开发完成的软件承担责任的法人或者其他组织；或者依靠自己具有的条件独立完成软件开发，并对软件承担责任的自然人。\n(四)软件著作权人，是指依照本条例的规定，对软件享有著作权的自然人、法人或者其他组织。\n第四条 受本条例保护的软件必须由开发者独立开发，并已固定在某种有形物体上。\n第五条 中国公民、法人或者其他组织对其所开发的软件，不论是否发表，依照本条例享有著作权。\n外国人、无国籍人的软件首先在中国境内发行的，依照本条例享有著作权。\n外国人、无国籍人的软件，依照其开发者所属国或者经常居住地国同中国签订的协议或者依照中国参加的国际条约享有的著作权，受本条例保护。\n第六条 本条例对软件著作权的保护不延及开发软件所用的思想、处理过程、操作方法或者数学概念等。\n第七条 软件著作权人可以向国务院著作权行政管理部门认定的软件登记机构办理登记。软件登记机构发放的登记证明文件是登记事项的初步证明。\n办理软件登记应当缴纳费用。软件登记的收费标准由国务院著作权行政管理部门会同国务院价格主管部门规定。","level":1},{"name":"第二章 软件著作权","text":"第八条 软件著作权人享有下列各项权利：\n(一)发表权，即决定软件是否公之于众的权利；\n(二)署名权，即表明开发者身份，在软件上署名的权利；\n(三)修改权，即对软件进行增补、删节，或者改变指令、语句顺序的权利；\n(四)复制权，即将软件制作一份或者多份的权利；\n(五)发行权，即以出售或者赠与方式向公众提供软件的原件或者复制件的权利；\n(六)出租权，即有偿许可他人临时使用软件的权利，但是软件不是出租的主要标的的除外；\n(七)信息网络传播权，即以有线或者无线方式向公众提供软件，使公众可以在其个人选定的时间和地点获得软件的权利；\n(八)翻译权，即将原软件从一种自然语言文字转换成另一种自然语言文字的权利；\n(九)应当由软件著作权人享有的其他权利。\n软件著作权人可以许可他人行使其软件著作权，并有权获得报酬。\n软件著作权人可以全部或者部分转让其软件著作权，并有权获得报酬。\n第九条 软件著作权属于软件开发者，本条例另有规定的除外。\n如无相反证明，在软件上署名的自然人、法人或者其他组织为开发者。\n第十条 由两个以上的自然人、法人或者其他组织合作开发的软件，其著作权的归属由合作开发者签订书面合同约定。无书面合同或者合同未作明确约定，合作开发的软件可以分割使用的，开发者对各自开发的部分可以单独享有著作权；但是，行使著作权时，不得扩展到合作开发的软件整体的著作权。合作开发的软件不能分割使用的，其著作权由各合作开发者共同享有，通过协商一致行使；不能协商一致，又无正当理由的，任何一方不得阻止他方行使除转让权以外的其他权利，但是所得收益应当合理分配给所有合作开发者。\n第十一条 接受他人委托开发的软件，其著作权的归属由委托人与受托人签订书面合同约定；无书面合同或者合同未作明确约定的，其著作权由受托人享有。\n第十二条 由国家机关下达任务开发的软件，著作权的归属与行使由项目任务书或者合同规定；项目任务书或者合同中未作明确规定的，软件著作权由接受任务的法人或者其他组织享有。\n第十三条 自然人在法人或者其他组织中任职期间所开发的软件有下列情形之一的，该软件著作权由该法人或者其他组织享有，该法人或者其他组织可以对开发软件的自然人进行奖励：\n(一)针对本职工作中明确指定的开发目标所开发的软件；\n(二)开发的软件是从事本职工作活动所预见的结果或者自然的结果；\n(三)主要使用了法人或者其他组织的资金、专用设备、未公开的专门信息等物质技术条件所开发并由法人或者其他组织承担责任的软件。\n第十四条 软件著作权自软件开发完成之日起产生。\n自然人的软件著作权，保护期为自然人终生及其死亡后50年，截止于自然人死亡后第50年的12月31日；软件是合作开发的，截止于最后死亡的自然人死亡后第50年的12月31日。\n法人或者其他组织的软件著作权，保护期为50年，截止于软件首次发表后第50年的12月31日，但软件自开发完成之日起50年内未发表的，本条例不再保护。\n第十五条 软件著作权属于自然人的，该自然人死亡后，在软件著作权的保护期内，软件著作权的继承人可以依照《中华人民共和国继承法》的有关规定，继承本条例第八条规定的除署名权以外的其他权利。\n软件著作权属于法人或者其他组织的，法人或者其他组织变更、终止后，其著作权在本条例规定的保护期内由承受其权利义务的法人或者其他组织享有；没有承受其权利义务的法人或者其他组织的，由国家享有。\n第十六条 软件的合法复制品所有人享有下列权利：\n(一)根据使用的需要把该软件装入计算机等具有信息处理能力的装置内；\n(二)为了防止复制品损坏而制作备份复制品。这些备份复制品不得通过任何方式提供给他人使用，并在所有人丧失该合法复制品的所有权时，负责将备份复制品销毁；\n(三)为了把该软件用于实际的计算机应用环境或者改进其功能、性能而进行必要的修改；但是，除合同另有约定外，未经该软件著作权人许可，不得向任何第三方提供修改后的软件。\n第十七条 为了学习和研究软件内含的设计思想和原理，通过安装、显示、传输或者存储软件等方式使用软件的，可以不经软件著作权人许可，不向其支付报酬。","level":1},{"name":"第三章 软件著作权的许可使用和转让","text":"第十八条 许可他人行使软件著作权的，应当订立许可使用合同。\n许可使用合同中软件著作权人未明确许可的权利，被许可人不得行使。\n第十九条 许可他人专有行使软件著作权的，当事人应当订立书面合同。\n没有订立书面合同或者合同中未明确约定为专有许可的，被许可行使的权利应当视为非专有权利。\n第二十条 转让软件著作权的，当事人应当订立书面合同。\n第二十一条 订立许可他人专有行使软件著作权的许可合同，或者订立转让软件著作权合同，可以向国务院著作权行政管理部门认定的软件登记机构登记。\n第二十二条 中国公民、法人或者其他组织向外国人许可或者转让软件著作权的，应当遵守《中华人民共和国技术进出口管理条例》的有关规定。","level":1},{"name":"第四章 法律责任","text":"第二十三条 除《中华人民共和国著作权法》或者本条例另有规定外，有下列侵权行为的，应当根据情况，承担停止侵害、消除影响、赔礼道歉、赔偿损失等民事责任：\n(一)未经软件著作权人许可，发表或者登记其软件的；\n(二)将他人软件作为自己的软件发表或者登记的；\n(三)未经合作者许可，将与他人合作开发的软件作为自己单独完成的软件发表或者登记的；\n(四)在他人软件上署名或者更改他人软件上的署名的；\n(五)未经软件著作权人许可，修改、翻译其软件的；\n(六)其他侵犯软件著作权的行为。\n第二十四条 除《中华人民共和国著作权法》、本条例或者其他法律、行政法规另有规定外，未经软件著作权人许可，有下列侵权行为的，应当根据情况，承担停止侵害、消除影响、赔礼道歉、赔偿损失等民事责任；同时损害社会公共利益的，由著作权行政管理部门责令停止侵权行为，没收违法所得，没收、销毁侵权复制品，可以并处罚款；情节严重的，著作权行政管理部门并可以没收主要用于制作侵权复制品的材料、工具、设备等；触犯刑律的，依照刑法关于侵犯著作权罪、销售侵权复制品罪的规定，依法追究刑事责任：\n(一)复制或者部分复制著作权人的软件的；\n(二)向公众发行、出租、通过信息网络传播著作权人的软件的；\n(三)故意避开或者破坏著作权人为保护其软件著作权而采取的技术措施的；\n(四)故意删除或者改变软件权利管理电子信息的；\n(五)转让或者许可他人行使著作权人的软件著作权的。\n有前款第一项或者第二项行为的，可以并处每件100元或者货值金额1倍以上5倍以下的罚款；有前款第三项、第四项或者第五项行为的，可以并处20万元以下的罚款。\n第二十五条 侵犯软件著作权的赔偿数额，依照《中华人民共和国著作权法》第四十九条的规定确定。\n第二十六条 软件著作权人有证据证明他人正在实施或者即将实施侵犯其权利的行为，如不及时制止，将会使其合法权益受到难以弥补的损害的，可以依照《中华人民共和国著作权法》第五十条的规定，在提起诉讼前向人民法院申请采取责令停止有关行为和财产保全的措施。\n第二十七条 为了制止侵权行为，在证据可能灭失或者以后难以取得的情况下，软件著作权人可以依照《中华人民共和国著作权法》第五十一条的规定，在提起诉讼前向人民法院申请保全证据。\n第二十八条 软件复制品的出版者、制作者不能证明其出版、制作有合法授权的，或者软件复制品的发行者、出租者不能证明其发行、出租的复制品有合法来源的，应当承担法律责任。\n第二十九条 软件开发者开发的软件，由于可供选用的表达方式有限而与已经存在的软件相似的，不构成对已经存在的软件的著作权的侵犯。\n第三十条 软件的复制品持有人不知道也没有合理理由应当知道该软件是侵权复制品的，不承担赔偿责任；但是，应当停止使用、销毁该侵权复制品。如果停止使用并销毁该侵权复制品将给复制品使用人造成重大损失的，复制品使用人可以在向软件著作权人支付合理费用后继续使用。\n第三十一条 软件著作权侵权纠纷可以调解。\n软件著作权合同纠纷可以依据合同中的仲裁条款或者事后达成的书面仲裁协议，向仲裁机构申请仲裁。\n当事人没有在合同中订立仲裁条款，事后又没有书面仲裁协议的，可以直接向人民法院提起诉讼。","level":1},{"name":"第五章 附则","text":"第三十二条 本条例施行前发生的侵权行为，依照侵权行为发生时的国家有关规定处理。\n第三十三条 本条例自2002年1月1日起施行。1991年6月4日国务院发布的《计算机软件保护条例》同时废止。","level":1}]},{"id":"n0309","sections":[{"name":"","text":"铁路交通事故应急救援和\n调查处理条例\n(2007年7月11日中华人民共和国国务院令第501号公布 根据2012年11月9日《国务院关于修改和废止部分行政法规的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强铁路交通事故的应急救援工作，规范铁路交通事故调查处理，减少人员伤亡和财产损失，保障铁路运输安全和畅通，根据《中华人民共和国铁路法》和其他有关法律的规定，制定本条例。\n第二条 铁路机车车辆在运行过程中与行人、机动车、非机动车、牲畜及其他障碍物相撞，或者铁路机车车辆发生冲突、脱轨、火灾、爆炸等影响铁路正常行车的铁路交通事故(以下简称事故)的应急救援和调查处理，适用本条例。\n第三条 国务院铁路主管部门应当加强铁路运输安全监督管理，建立健全事故应急救援和调查处理的各项制度，按照国家规定的权限和程序，负责组织、指挥、协调事故的应急救援和调查处理工作。\n第四条 铁路管理机构应当加强日常的铁路运输安全监督检查，指导、督促铁路运输企业落实事故应急救援的各项规定，按照规定的权限和程序，组织、参与、协调本辖区内事故的应急救援和调查处理工作。\n第五条 国务院其他有关部门和有关地方人民政府应当按照各自的职责和分工，组织、参与事故的应急救援和调查处理工作。\n第六条 铁路运输企业和其他有关单位、个人应当遵守铁路运输安全管理的各项规定，防止和避免事故的发生。\n事故发生后，铁路运输企业和其他有关单位应当及时、准确地报告事故情况，积极开展应急救援工作，减少人员伤亡和财产损失，尽快恢复铁路正常行车。\n第七条 任何单位和个人不得干扰、阻碍事故应急救援、铁路线路开通、列车运行和事故调查处理。","level":1},{"name":"第二章 事故等级","text":"第八条 根据事故造成的人员伤亡、直接经济损失、列车脱轨辆数、中断铁路行车时间等情形，事故等级分为特别重大事故、重大事故、较大事故和一般事故。\n第九条 有下列情形之一的，为特别重大事故：\n(一)造成30人以上死亡，或者100人以上重伤(包括急性工业中毒，下同)，或者1亿元以上直接经济损失的；\n(二)繁忙干线客运列车脱轨18辆以上并中断铁路行车48小时以上的；\n(三)繁忙干线货运列车脱轨60辆以上并中断铁路行车48小时以上的。\n第十条 有下列情形之一的，为重大事故：\n(一)造成10人以上30人以下死亡，或者50人以上100人以下重伤，或者5000万元以上1亿元以下直接经济损失的；\n(二)客运列车脱轨18辆以上的；\n(三)货运列车脱轨60辆以上的；\n(四)客运列车脱轨2辆以上18辆以下，并中断繁忙干线铁路行车24小时以上或者中断其他线路铁路行车48小时以上的；\n(五)货运列车脱轨6辆以上60辆以下，并中断繁忙干线铁路行车24小时以上或者中断其他线路铁路行车48小时以上的。\n第十一条 有下列情形之一的，为较大事故：\n(一)造成3人以上10人以下死亡，或者10人以上50人以下重伤，或者1000万元以上5000万元以下直接经济损失的；\n(二)客运列车脱轨2辆以上18辆以下的；\n(三)货运列车脱轨6辆以上60辆以下的；\n(四)中断繁忙干线铁路行车6小时以上的；\n(五)中断其他线路铁路行车10小时以上的。\n第十二条 造成3人以下死亡，或者10人以下重伤，或者1000万元以下直接经济损失的，为一般事故。\n除前款规定外，国务院铁路主管部门可以对一般事故的其他情形作出补充规定。\n第十三条 本章所称的“以上”包括本数，所称的“以下”不包括本数。","level":1},{"name":"第三章 事故报告","text":"第十四条 事故发生后，事故现场的铁路运输企业工作人员或者其他人员应当立即报告邻近铁路车站、列车调度员或者公安机关。有关单位和人员接到报告后，应当立即将事故情况报告事故发生地铁路管理机构。\n第十五条 铁路管理机构接到事故报告，应当尽快核实有关情况，并立即报告国务院铁路主管部门；对特别重大事故、重大事故，国务院铁路主管部门应当立即报告国务院并通报国家安全生产监督管理等有关部门。\n发生特别重大事故、重大事故、较大事故或者有人员伤亡的一般事故，铁路管理机构还应当通报事故发生地县级以上地方人民政府及其安全生产监督管理部门。\n第十六条 事故报告应当包括下列内容：\n(一)事故发生的时间、地点、区间(线名、公里、米)、事故相关单位和人员；\n(二)发生事故的列车种类、车次、部位、计长、机车型号、牵引辆数、吨数；\n(三)承运旅客人数或者货物品名、装载情况；\n(四)人员伤亡情况，机车车辆、线路设施、道路车辆的损坏情况，对铁路行车的影响情况；\n(五)事故原因的初步判断；\n(六)事故发生后采取的措施及事故控制情况；\n(七)具体救援请求。\n事故报告后出现新情况的，应当及时补报。\n第十七条 国务院铁路主管部门、铁路管理机构和铁路运输企业应当向社会公布事故报告值班电话，受理事故报告和举报。","level":1},{"name":"第四章 事故应急救援","text":"第十八条 事故发生后，列车司机或者运转车长应当立即停车，采取紧急处置措施；对无法处置的，应当立即报告邻近铁路车站、列车调度员进行处置。\n为保障铁路旅客安全或者因特殊运输需要不宜停车的，可以不停车；但是，列车司机或者运转车长应当立即将事故情况报告邻近铁路车站、列车调度员，接到报告的邻近铁路车站、列车调度员应当立即进行处置。\n第十九条 事故造成中断铁路行车的，铁路运输企业应当立即组织抢修，尽快恢复铁路正常行车；必要时，铁路运输调度指挥部门应当调整运输径路，减少事故影响。\n第二十条 事故发生后，国务院铁路主管部门、铁路管理机构、事故发生地县级以上地方人民政府或者铁路运输企业应当根据事故等级启动相应的应急预案；必要时，成立现场应急救援机构。\n第二十一条 现场应急救援机构根据事故应急救援工作的实际需要，可以借用有关单位和个人的设施、设备和其他物资。借用单位使用完毕应当及时归还，并支付适当费用；造成损失的，应当赔偿。\n有关单位和个人应当积极支持、配合救援工作。\n第二十二条 事故造成重大人员伤亡或者需要紧急转移、安置铁路旅客和沿线居民的，事故发生地县级以上地方人民政府应当及时组织开展救治和转移、安置工作。\n第二十三条 国务院铁路主管部门、铁路管理机构或者事故发生地县级以上地方人民政府根据事故救援的实际需要，可以请求当地驻军、武装警察部队参与事故救援。\n第二十四条 有关单位和个人应当妥善保护事故现场以及相关证据，并在事故调查组成立后将相关证据移交事故调查组。因事故救援、尽快恢复铁路正常行车需要改变事故现场的，应当做出标记、绘制现场示意图、制作现场视听资料，并做出书面记录。\n任何单位和个人不得破坏事故现场，不得伪造、隐匿或者毁灭相关证据。\n第二十五条 事故中死亡人员的尸体经法定机构鉴定后，应当及时通知死者家属认领；无法查找死者家属的，按照国家有关规定处理。","level":1},{"name":"第五章 事故调查处理","text":"第二十六条 特别重大事故由国务院或者国务院授权的部门组织事故调查组进行调查。\n重大事故由国务院铁路主管部门组织事故调查组进行调查。\n较大事故和一般事故由事故发生地铁路管理机构组织事故调查组进行调查；国务院铁路主管部门认为必要时，可以组织事故调查组对较大事故和一般事故进行调查。\n根据事故的具体情况，事故调查组由有关人民政府、公安机关、安全生产监督管理部门、监察机关等单位派人组成，并应当邀请人民检察院派人参加。事故调查组认为必要时，可以聘请有关专家参与事故调查。\n第二十七条 事故调查组应当按照国家有关规定开展事故调查，并在下列调查期限内向组织事故调查组的机关或者铁路管理机构提交事故调查报告：\n(一)特别重大事故的调查期限为60日；\n(二)重大事故的调查期限为30日；\n(三)较大事故的调查期限为20日；\n(四)一般事故的调查期限为10日。\n事故调查期限自事故发生之日起计算。\n第二十八条 事故调查处理，需要委托有关机构进行技术鉴定或者对铁路设备、设施及其他财产损失状况以及中断铁路行车造成的直接经济损失进行评估的，事故调查组应当委托具有国家规定资质的机构进行技术鉴定或者评估。技术鉴定或者评估所需时间不计入事故调查期限。\n第二十九条 事故调查报告形成后，报经组织事故调查组的机关或者铁路管理机构同意，事故调查组工作即告结束。组织事故调查组的机关或者铁路管理机构应当自事故调查组工作结束之日起15日内，根据事故调查报告，制作事故认定书。\n事故认定书是事故赔偿、事故处理以及事故责任追究的依据。\n第三十条 事故责任单位和有关人员应当认真吸取事故教训，落实防范和整改措施，防止事故再次发生。\n国务院铁路主管部门、铁路管理机构以及其他有关行政机关应当对事故责任单位和有关人员落实防范和整改措施的情况进行监督检查。\n第三十一条 事故的处理情况，除依法应当保密的外，应当由组织事故调查组的机关或者铁路管理机构向社会公布。","level":1},{"name":"第六章 事故赔偿","text":"第三十二条 事故造成人身伤亡的，铁路运输企业应当承担赔偿责任；但是人身伤亡是不可抗力或者受害人自身原因造成的，铁路运输企业不承担赔偿责任。\n违章通过平交道口或者人行过道，或者在铁路线路上行走、坐卧造成的人身伤亡，属于受害人自身的原因造成的人身伤亡。\n第三十三条 事故造成铁路旅客人身伤亡和自带行李损失的，铁路运输企业对每名铁路旅客人身伤亡的赔偿责任限额为人民币15万元，对每名铁路旅客自带行李损失的赔偿责任限额为人民币2000元。\n铁路运输企业与铁路旅客可以书面约定高于前款规定的赔偿责任限额。(2012年11月9日删除)\n第三十四条 事故造成铁路运输企业承运的货物、包裹、行李损失的，铁路运输企业应当依照《中华人民共和国铁路法》的规定承担赔偿责任。\n第三十五条 除本条例第三十三条、第三十四条的规定外，事故造成其他人身伤亡或者财产损失的，依照国家有关法律、行政法规的规定赔偿。\n第三十六条 事故当事人对事故损害赔偿有争议的，可以通过协商解决，或者请求组织事故调查组的机关或者铁路管理机构组织调解，也可以直接向人民法院提起民事诉讼。","level":1},{"name":"第七章 法律责任","text":"第三十七条 铁路运输企业及其职工违反法律、行政法规的规定，造成事故的，由国务院铁路主管部门或者铁路管理机构依法追究行政责任。\n第三十八条 违反本条例的规定，铁路运输企业及其职工不立即组织救援，或者迟报、漏报、瞒报、谎报事故的，对单位，由国务院铁路主管部门或者铁路管理机构处10万元以上50万元以下的罚款；对个人，由国务院铁路主管部门或者铁路管理机构处4000元以上2万元以下的罚款；属于国家工作人员的，依法给予处分；构成犯罪的，依法追究刑事责任。\n第三十九条 违反本条例的规定，国务院铁路主管部门、铁路管理机构以及其他行政机关未立即启动应急预案，或者迟报、漏报、瞒报、谎报事故的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。\n第四十条 违反本条例的规定，干扰、阻碍事故救援、铁路线路开通、列车运行和事故调查处理的，对单位，由国务院铁路主管部门或者铁路管理机构处4万元以上20万元以下的罚款；对个人，由国务院铁路主管部门或者铁路管理机构处2000元以上1万元以下的罚款；情节严重的，对单位，由国务院铁路主管部门或者铁路管理机构处20万元以上100万元以下的罚款；对个人，由国务院铁路主管部门或者铁路管理机构处1万元以上5万元以下的罚款；属于国家工作人员的，依法给予处分；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第八章 附则","text":"第四十一条 本条例于2007年9月1日起施行。1979年7月16日国务院批准发布的《火车与其他车辆碰撞和铁路路外人员伤亡事故处理暂行规定》和1994年8月13日国务院批准发布的《铁路旅客运输损害赔偿规定》同时废止。","level":1}]},{"id":"n0310","sections":[{"name":"","text":"中华人民共和国海上交通事故调查处理条例\n(1990年1月11日国务院批准 1990年3月3日交通部令第14号发布 自发布之日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了加强海上交通安全管理，及时调查处理海上交通事故，根据《中华人民共和国海上交通安全法》的有关规定，制定本条例。\n第二条 中华人民共和国港务监督机构是本条例的实施机关。\n第三条 本条例适用于船舶、设施在中华人民共和国沿海水域内发生的海上交通事故。\n以渔业为主的渔港水域内发生的海上交通事故和沿海水域内渔业船舶之间、军用船舶之间发生的海上交通事故的调查处理，国家法律、行政法规另有专门规定的，从其规定。\n第四条 本条例所称海上交通事故是指船舶、设施发生的下列事故：\n(一)碰撞、触碰或浪损；\n(二)触礁或搁浅；\n(三)火灾或爆炸；\n(四)沉没；\n(五)在航行中发生影响适航性能的机件或重要属具的损坏或灭失；\n(六)其他引起财产损失和人身伤亡的海上交通事故。","level":1},{"name":"第二章 报告","text":"第五条 船舶、设施发生海上交通事故，必须立即用甚高频电话、无线电报或其他有效手段向就近港口的港务监督报告。报告的内容应当包括：船舶或设施的名称、呼号、国籍、起迄港，船舶或设施的所有人或经营人名称，事故发生的时间、地点、海况以及船舶、设施的损害程度、救助要求等。\n第六条 船舶、设施发生海上交通事故，除应按第五条规定立即提出扼要报告外，还必须按下列规定向港务监督提交《海上交通事故报告书》和必要的文书资料：\n(一)船舶、设施在港区水域内发生海上交通事故，必须在事故发生后二十四小时内向当地港务监督提交。\n(二)船舶、设施在港区水域以外的沿海水域发生海上交通事故，船舶必须在到达中华人民共和国的第一个港口后四十八小时内向港务监督提交；设施必须在事故发生后四十八小时内用电报向就近港口的港务监督报告《海上交通事故报告书》要求的内容。\n(三)引航员在引领船舶的过程中发生海上交通事故，应当在返港后二十四小时内向当地港务监督提交《海上交通事故报告书》。\n前款(一)、(二)项因特殊情况不能按规定时间提交《海上交通事故报告书》的，在征得港务监督同意后可予以适当延迟。\n第七条 《海上交通事故报告书》应当如实写明下列情况：\n(一)船舶、设施概况和主要性能数据；\n(二)船舶、设施所有人或经营人的名称、地址；\n(三)事故发生的时间和地点；\n(四)事故发生时的气象和海况；\n(五)事故发生的详细经过(碰撞事故应附相对运动示意图)；\n(六)损害情况(附船舶、设施受损部位简图。难以在规定时间内查清的，应于检验后补报)；\n(七)船舶、设施沉没的，其沉没概位；\n(八)与事故有关的其他情况。\n第八条 海上交通事故报告必须真实，不得隐瞒或捏造。\n第九条 因海上交通事故致使船舶、设施发生损害，船长、设施负责人应申请中国当地或船舶第一到达港地的检验部门进行检验或鉴定，并应将检验报告副本送交港务监督备案。\n前款检验、鉴定事项，港务监督可委托有关单位或部门进行，其费用由船舶、设施所有人或经营人承担。\n船舶、设施发生火灾、爆炸等事故，船长、设施负责人必须申请公安消防监督机关鉴定，并将鉴定书副本送交港务监督备案。","level":1},{"name":"第三章 调查","text":"第十条 在港区水域内发生的海上交通事故，由港区地的港务监督进行调查。\n在港区水域外发生的海上交通事故，由就近港口的港务监督或船舶到达的中华人民共和国的第一个港口的港务监督进行调查。必要时，由中华人民共和国港务监督局指定的港务监督进行调查。\n港务监督认为必要时，可以通知有关机关和社会组织参加事故调查。\n第十一条 港务监督在接到事故报告后，应及时进行调查。调查应客观、全面，不受事故当事人提供材料的限制。根据调查工作的需要，港务监督有权：\n(一)询问有关人员；\n(二)要求被调查人员提供书面材料和证明；\n(三)要求有关当事人提供航海日志、轮机日志、车钟记录、报务日志、航向记录、海图、船舶资料、航行设备仪器的性能以及其他必要的原始文书资料；\n(四)检查船舶、设施及有关设备的证书、人员证书和核实事故发生前船舶的适航状态、设施的技术状态；\n(五)检查船舶、设施及其货物的损害情况和人员伤亡情况；\n(六)勘查事故现场，搜集有关物证。\n港务监督在调查中，可以使用录音、照相、录相等设备，并可采取法律允许的其他调查手段。\n第十二条 被调查人必须接受调查，如实陈述事故的有关情节，并提供真实的文书资料。\n港务监督人员在执行调查任务时，应当向被调查人员出示证件。\n第十三条 港务监督因调查海上交通事故的需要，可以令当事船舶驶抵指定地点接受调查。当事船舶在不危及自身安全的情况下，未经港务监督同意，不得离开指定地点。\n第十四条 港务监督的海上交通事故调查材料，公安机关、国家安全机关、监察机关、检察机关、审判机关和海事仲裁委员会及法律规定的其他机关和人员因办案需要可以查阅、摘录或复制，审判机关确因开庭需要可以借用。","level":1},{"name":"第四章 处理","text":"第十五条 港务监督应当根据对海上交通事故的调查，作出《海上交通事故调查报告书》，查明事故发生的原因，判明当事人的责任；构成重大事故的，通报当地检察机关。\n第十六条 《海上交通事故调查报告书》应包括以下内容：\n(一)船舶、设施的概况和主要数据；\n(二)船舶、设施所有人或经营人的名称和地址；\n(三)事故发生的时间、地点、过程、气象海况、损害情况等；\n(四)事故发生的原因及依据；\n(五)当事人各方的责任及依据；\n(六)其他有关情况。\n第十七条 对海上交通事故的发生负有责任的人员，港务监督可以根据其责任的性质和程度依法给予下列处罚：\n(一)对中国籍船员、引航员或设施上的工作人员，可以给予警告、罚款或扣留、吊销职务证书；\n(二)对外国籍船员或设施上的工作人员，可以给予警告、罚款或将其过失通报其所属国家的主管机关。\n第十八条 对海上交通事故的发生负有责任的人员及船舶、设施的所有人或经营人，需要追究其行政责任的，由港务监督提交其主管机关或行政监察机关处理；构成犯罪的，由司法机关依法追究刑事责任。\n第十九条 根据海上交通事故发生的原因，港务监督可责令有关船舶、设施的所有人、经营人限期加强对所属船舶、设施的安全管理。对拒不加强安全管理或在限期内达不到安全要求的，港务监督有权责令其停航、改航、停止作业，并可采取其他必要的强制性处置措施。","level":1},{"name":"第五章 调解","text":"第二十条 对船舶、设施发生海上交通事故引起的民事侵权赔偿纠纷，当事人可以申请港务监督调解。\n调解必须遵循自愿、公平的原则，不得强迫。\n第二十一条 前条民事纠纷，凡已向海事法院起诉或申请海事仲裁机构仲裁的，当事人不得再申请港务监督调解。\n第二十二条 调解由当事人各方在事故发生之日起三十日内向负责该事故调查的港务监督提交书面申请。港务监督要求提供担保的，当事人应附经济赔偿担保证明文件。\n第二十三条 经调解达成协议的，港务监督应制作调解书。调解书应当写明当事人的姓名或名称、住所、法定代表人或代理人的姓名及职务、纠纷的主要事实、当事人的责任、协议的内容、调解费的承担、调解协议履行的期限。调解书由当事人各方共同签字，并经港务监督盖印确认。调解书应交当事方各持一份，港务监督留存一份。\n第二十四条 调解达成协议的，当事人各方应当自动履行。达成协议后当事人翻悔的或逾期不履行协议的，视为调解不成。\n第二十五条 凡向港务监督申请调解的民事纠纷，当事人中途不愿调解的，应当向港务监督递交撤销调解的书面申请，并通知对方当事人。\n第二十六条 港务监督自收到调解申请书之日起三个月内未能使当事人各方达成调解协议的，可以宣布调解不成。\n第二十七条 不愿意调解或调解不成的，当事人可以向海事法院起诉或申请海事仲裁机构仲裁。\n第二十八条 凡申请港务监督调解的，应向港务监督缴纳调解费。调解的收费标准，由交通部会同国家物价局、财政部制定。\n经调解达成协议的，调解费用按当事人过失比例或约定的数额分摊；调解不成的，由当事人各方平均分摊。","level":1},{"name":"第六章 罚则","text":"第二十九条 违反本条例规定，有下列行为之一的，港务监督可视情节对有关当事人(自然人)处以警告或者二百元以下罚款；对船舶所有人、经营人处以警告或者五千元以下罚款：\n(一)未按规定的时间向港务监督报告事故或提交《海上交通事故报告书》或本条例第三十二条要求的判决书、裁决书、调解书的副本的；\n(二)未按港务监督要求驶往指定地点，或在未出现危及船舶安全的情况下未经港务监督同意擅自驶离指定地点的；\n(三)事故报告或《海上交通事故报告书》的内容不符合规定要求或不真实，影响调查工作进行或给有关部门造成损失的；\n(四)违反第九条规定，影响事故调查的；\n(五)拒绝接受调查或无理阻挠、干扰港务监督进行调查的；\n(六)在受调查时故意隐瞒事实或提供虚假证明的。\n前款第(五)、(六)项行为构成犯罪的，由司法机关依法追究刑事责任。\n第三十条 对违反本条例规定，玩忽职守、滥用职权、营私舞弊、索贿受贿的港务监督人员，由行政监察机关或其所在单位给予行政处分；构成犯罪的，由司法机关依法追究刑事责任。\n第三十一条 当事人对港务监督依据本条例给予的处罚不服的，可以依法向人民法院提起行政诉讼。","level":1},{"name":"第七章 特别规定","text":"第三十二条 中国籍船舶在中华人民共和国沿海水域以外发生的海上交通事故，其所有人或经营人应当向船籍港的港务监督报告，并于事故发生之日起六十日内提交《海上交通事故报告书》。如果事故在国外诉讼、仲裁或调解，船舶所有人或经营人应在诉讼、仲裁或调解结束后六十日内将判决书、裁决书或调解书的副本或影印件报船籍港的港务监督备案。\n第三十三条 派往外国籍船舶任职的持有中华人民共和国船员职务证书的中国籍船员对海上交通事故的发生负有责任的，其派出单位应当在事故发生之日起六十日内向签发该职务证书的港务监督提交《海上交通事故报告书》。\n本条第一款和第三十二条的海上交通事故的调查处理，按本条例的有关规定办理。","level":1},{"name":"第八章 附则","text":"第三十四条 对违反海上交通安全管理法规进行违章操作，虽未造成直接的交通事故，但构成重大潜在事故隐患的，港务监督可以依据本条例进行调查和处罚。\n第三十五条 因海上交通事故产生的海洋环境污染，按照我国海洋环境保护的有关法律、法规处理。\n第三十六条 本条例由交通部负责解释。\n第三十七条 本条例自发布之日起施行。","level":1}]},{"id":"n0311","sections":[{"name":"","text":"中华人民共和国\n非机动船舶海上安全航行暂行规则\n(1958年3月17日国务院批准 1958年4月19日交通部、水产部发布 自1958年7月1日起施行)\n第一条 凡使用人力、风力、拖力的非机动船，在海上从事运输、捕鱼或者其他工作，都应当遵守本规则。\n在港区内航行的时候，应当遵守各该港港章的规定。\n第二条 非机动船在夜间航行、锚泊的时候，应当在容易被看见的地方，悬挂明亮的白光环照灯一盏。如果因为天气恶劣或者受设备的限制，不能固定悬挂白光环照灯，必须将灯点好放在手边，以备应用；在与他船接近的时候，应当及早显示灯光或者手电筒的白色闪光或者火光，以防碰撞。\n非机动船已经设置红绿舷灯、尾灯或者使用合色灯的，仍应继续使用。\n第三条 非机动渔船，在白昼捕鱼的时候，应当在容易被看见的地方，悬挂竹篮一只，当发现他船驶近的时候，应当用适当信号指示渔具延伸方向；使用流网的渔船，还要在流网延伸末端的浮子上，系小红旗一面；在夜间捕鱼的时候，应当在容易被看见的地方，悬挂明亮的白光环照灯一盏，当发现他船驶近的时候，向渔具延伸方向，显示另一白光。\n第四条 非机动船在有雾、下雪、暴风雨或者其他任何视线不清楚的情况下，不论白昼或者夜间，都应当执行下列规定：\n(1)在航行的时候，应当每隔约1分钟，连续发放雾号响声(如敲锣、敲梆、敲煤油桶、吹螺、吹雾角、吹喇叭等)约5秒钟；\n(2)在锚泊的时候，如果听到来船雾号响声，应当有间隔地、急促地发放响声，以引起来船注意，直到驶过为止；\n(3)在捕鱼的时候，也应当依照前两项的规定执行。\n第五条 两艘帆船相互驶近，如有碰撞的危险，应当依照下列规定避让：\n(1)顺风船应当避让逆风打抢、掉抢的船；\n(2)左舷受风打抢的船应当避让右舷受风打抢的船；\n(3)两船都是顺风，而在不同的船舷受风的时候左舷受风的船应当避让右舷受风的船；\n(4)两船都是顺风，而在同一船舷受风的时候，上风船应当避让下风船；\n(5)船尾受风的船应当避让其它船舷受风的船。\n第六条 在航行中的非机动船，应当避让用网、曳绳钓或者拖网进行捕鱼作业的非机动渔船。\n第七条 非机动船应当避让下列的机动船：\n(1)从事起捞、安放海底电线或者航行标志的机动船；\n(2)从事测量或者水下工作的机动船；\n(3)操纵失灵的机动船；\n(4)用拖网捕鱼的机动船；\n(5)被追越的机动船。\n第八条 非机动船与机动船相互驶近，如有碰撞危险，机动船应当避让非机动船。\n第九条 非机动船在海上遇难，需要他船或者岸上援救的时候，应当显示下列信号：\n(1)用任何雾号器具连续不断发放响声；\n(2)连续不断燃放火光；\n(3)将衣服张开，挂上桅顶。\n第十条 本规则经国务院批准后，由交通部、水产部联合发布施行。","level":0}]},{"id":"n0312","sections":[{"name":"","text":"城市道路管理条例\n(1996年6月4日中华人民共和国国务院令第198号发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2017年3月1日《国务院关于修改和废止部分行政法规的决定》第二次修订 根据2019年3月24日《国务院关于修改部分行政法规的决定》第三次修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强城市道路管理，保障城市道路完好，充分发挥城市道路功能，促进城市经济和社会发展，制定本条例。\n第二条 本条例所称城市道路，是指城市供车辆、行人通行的，具备一定技术条件的道路、桥梁及其附属设施。\n第三条 本条例适用于城市道路规划、建设、养护、维修和路政管理。\n第四条 城市道路管理实行统一规划、配套建设、协调发展和建设、养护、管理并重的原则。\n第五条 国家鼓励和支持城市道路科学技术研究，推广先进技术，提高城市道路管理的科学技术水平。\n第六条 国务院建设行政主管部门主管全国城市道路管理工作。\n省、自治区人民政府城市建设行政主管部门主管本行政区域内的城市道路管理工作。\n县级以上城市人民政府市政工程行政主管部门主管本行政区域内的城市道路管理工作。","level":1},{"name":"第二章 规划和建设","text":"第七条 县级以上城市人民政府应当组织市政工程、城市规划、公安交通等部门，根据城市总体规划编制城市道路发展规划。\n市政工程行政主管部门应当根据城市道路发展规划，制定城市道路年度建设计划，经城市人民政府批准后实施。\n第八条 城市道路建设资金可以按照国家有关规定，采取政府投资、集资、国内外贷款、国有土地有偿使用收入、发行债券等多种渠道筹集。\n第九条 城市道路的建设应当符合城市道路技术规范。\n第十条 政府投资建设城市道路的，应当根据城市道路发展规划和年度建设计划，由市政工程行政主管部门组织建设。\n单位投资建设城市道路的，应当符合城市道路发展规划。\n城市住宅小区、开发区内的道路建设，应当分别纳入住宅小区、开发区的开发建设计划配套建设。\n第十一条 国家鼓励国内外企业和其他组织以及个人按照城市道路发展规划，投资建设城市道路。\n第十二条 城市供水、排水、燃气、热力、供电、通信、消防等依附于城市道路的各种管线、杆线等设施的建设计划，应当与城市道路发展规划和年度建设计划相协调，坚持先地下、后地上的施工原则，与城市道路同步建设。\n第十三条 新建的城市道路与铁路干线相交的，应当根据需要在城市规划中预留立体交通设施的建设位置。\n城市道路与铁路相交的道口建设应当符合国家有关技术规范，并根据需要逐步建设立体交通设施。建设立体交通设施所需投资，按照国家规定由有关部门协商确定。\n第十四条 建设跨越江河的桥梁和隧道，应当符合国家规定的防洪、通航标准和其他有关技术规范。\n第十五条 县级以上城市人民政府应当有计划地按照城市道路技术规范改建、拓宽城市道路和公路的结合部，公路行政主管部门可以按照国家有关规定在资金上给予补助。\n第十六条 承担城市道路设计、施工的单位，应当具有相应的资质等级，并按照资质等级承担相应的城市道路的设计、施工任务。\n第十七条 城市道路的设计、施工，应当严格执行国家和地方规定的城市道路设计、施工的技术规范。\n城市道路施工，实行工程质量监督制度。\n城市道路工程竣工，经验收合格后，方可交付使用；未经验收或者验收不合格的，不得交付使用。\n第十八条 城市道路实行工程质量保修制度。城市道路的保修期为1年，自交付使用之日起计算。保修期内出现工程质量问题，由有关责任单位负责保修。\n第十九条 市政工程行政主管部门对利用贷款或者集资建设的大型桥梁、隧道等，可以在一定期限内向过往车辆(军用车辆除外)收取通行费，用于偿还贷款或者集资款，不得挪作他用。\n收取通行费的范围和期限，由省、自治区、直辖市人民政府规定。","level":1},{"name":"第三章 养护和维修","text":"第二十条 市政工程行政主管部门对其组织建设和管理的城市道路，按照城市道路的等级、数量及养护和维修的定额，逐年核定养护、维修经费，统一安排养护、维修资金。\n第二十一条 承担城市道路养护、维修的单位，应当严格执行城市道路养护、维修的技术规范，定期对城市道路进行养护、维修，确保养护、维修工程的质量。\n市政工程行政主管部门负责对养护、维修工程的质量进行监督检查，保障城市道路完好。\n第二十二条 市政工程行政主管部门组织建设和管理的道路，由其委托的城市道路养护、维修单位负责养护、维修。单位投资建设和管理的道路，由投资建设的单位或者其委托的单位负责养护、维修。城市住宅小区、开发区内的道路，由建设单位或者其委托的单位负责养护、维修。\n第二十三条 设在城市道路上的各类管线的检查井、箱盖或者城市道路附属设施，应当符合城市道路养护规范。因缺损影响交通和安全时，有关产权单位应当及时补缺或者修复。\n第二十四条 城市道路的养护、维修工程应当按照规定的期限修复竣工，并在养护、维修工程施工现场设置明显标志和安全防围设施，保障行人和交通车辆安全。\n第二十五条 城市道路养护、维修的专用车辆应当使用统一标志；执行任务时，在保证交通安全畅通的情况下，不受行驶路线和行驶方向的限制。","level":1},{"name":"第四章 路政管理","text":"第二十六条 市政工程行政主管部门执行路政管理的人员执行公务，应当按照有关规定佩戴标志，持证上岗。\n第二十七条 城市道路范围内禁止下列行为：\n(一)擅自占用或者挖掘城市道路；\n(二)履带车、铁轮车或者超重、超高、超长车辆擅自在城市道路上行驶；\n(三)机动车在桥梁或者非指定的城市道路上试刹车；\n(四)擅自在城市道路上建设建筑物、构筑物；\n(五)在桥梁上架设压力在4公斤/平方厘米(0.4兆帕)以上的煤气管道、10千伏以上的高压电力线和其他易燃易爆管线；\n(六)擅自在桥梁或者路灯设施上设置广告牌或者其他挂浮物；\n(七)其他损害、侵占城市道路的行为。\n第二十八条 履带车、铁轮车或者超重、超高、超长车辆需要在城市道路上行驶的，事先须征得市政工程行政主管部门同意，并按照公安交通管理部门指定的时间、路线行驶。\n军用车辆执行任务需要在城市道路上行驶的，可以不受前款限制，但是应当按照规定采取安全保护措施。\n第二十九条 依附于城市道路建设各种管线、杆线等设施的，应当经市政工程行政主管部门批准，方可建设。\n第三十条 未经市政工程行政主管部门和公安交通管理部门批准，任何单位或者个人不得占用或者挖掘城市道路。\n第三十一条 因特殊情况需要临时占用城市道路的，须经市政工程行政主管部门和公安交通管理部门批准，方可按照规定占用。\n经批准临时占用城市道路的，不得损坏城市道路；占用期满后，应当及时清理占用现场，恢复城市道路原状；损坏城市道路的，应当修复或者给予赔偿。\n第三十二条 城市人民政府应当严格控制占用城市道路作为集贸市场。\n第三十三条 因工程建设需要挖掘城市道路的，应当提交城市规划部门批准签发的文件和有关设计文件，经市政工程行政主管部门和公安交通管理部门批准，方可按照规定挖掘。\n新建、扩建、改建的城市道路交付使用后5年内、大修的城市道路竣工后3年内不得挖掘；因特殊情况需要挖掘的，须经县级以上城市人民政府批准。\n第三十四条 埋设在城市道路下的管线发生故障需要紧急抢修的，可以先行破路抢修，并同时通知市政工程行政主管部门和公安交通管理部门，在24小时内按照规定补办批准手续。\n第三十五条 经批准挖掘城市道路的，应当在施工现场设置明显标志和安全防围设施；竣工后，应当及时清理现场，通知市政工程行政主管部门检查验收。\n第三十六条 经批准占用或者挖掘城市道路的，应当按照批准的位置、面积、期限占用或者挖掘。需要移动位置、扩大面积、延长时间的，应当提前办理变更审批手续。\n第三十七条 占用或者挖掘由市政工程行政主管部门管理的城市道路的，应当向市政工程行政主管部门交纳城市道路占用费或者城市道路挖掘修复费。\n城市道路占用费的收费标准，由省、自治区人民政府的建设行政主管部门、直辖市人民政府的市政工程行政主管部门拟订，报同级财政、物价主管部门核定；城市道路挖掘修复费的收费标准，由省、自治区人民政府的建设行政主管部门、直辖市人民政府的市政工程行政主管部门制定，报同级财政、物价主管部门备案。\n第三十八条 根据城市建设或者其他特殊需要，市政工程行政主管部门可以对临时占用城市道路的单位或者个人决定缩小占用面积、缩短占用时间或者停止占用，并根据具体情况退还部分城市道路占用费。","level":1},{"name":"第五章 罚则","text":"第三十九条 违反本条例的规定，有下列行为之一的，由市政工程行政主管部门责令停止设计、施工，限期改正，可以并处3万元以下的罚款；已经取得设计、施工资格证书，情节严重的，提请原发证机关吊销设计、施工资格证书：\n(一)未取得设计、施工资格或者未按照资质等级承担城市道路的设计、施工任务的；\n(二)未按照城市道路设计、施工技术规范设计、施工的；\n(三)未按照设计图纸施工或者擅自修改图纸的。\n第四十条 违反本条例第十七条规定，擅自使用未经验收或者验收不合格的城市道路的，由市政工程行政主管部门责令限期改正，给予警告，可以并处工程造价2%以下的罚款。\n第四十一条 承担城市道路养护、维修的单位违反本条例的规定，未定期对城市道路进行养护、维修或者未按照规定的期限修复竣工，并拒绝接受市政工程行政主管部门监督、检查的，由市政工程行政主管部门责令限期改正，给予警告；对负有直接责任的主管人员和其他直接责任人员，依法给予行政处分。\n第四十二条 违反本条例第二十七条规定，或者有下列行为之一的，由市政工程行政主管部门或者其他有关部门责令限期改正，可以处以2万元以下的罚款；造成损失的，应当依法承担赔偿责任：\n(一)未对设在城市道路上的各种管线的检查井、箱盖或者城市道路附属设施的缺损及时补缺或者修复的；\n(二)未在城市道路施工现场设置明显标志和安全防围设施的；\n(三)占用城市道路期满或者挖掘城市道路后，不及时清理现场的；\n(四)依附于城市道路建设各种管线、杆线等设施，不按照规定办理批准手续的；\n(五)紧急抢修埋设在城市道路下的管线，不按照规定补办批准手续的；\n(六)未按照批准的位置、面积、期限占用或者挖掘城市道路，或者需要移动位置、扩大面积、延长时间，未提前办理变更审批手续的。\n第四十三条 违反本条例，构成犯罪的，由司法机关依法追究刑事责任；尚不构成犯罪，应当给予治安管理处罚的，依照治安管理处罚法的规定给予处罚。\n第四十四条 市政工程行政主管部门人员玩忽职守、滥用职权、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。","level":1},{"name":"第六章 附则","text":"第四十五条 本条例自1996年10月1日起施行。","level":1}]},{"id":"n0313","sections":[{"name":"","text":"中华人民共和国涉外海洋科学研究管理规定\n(1996年6月18日中华人民共和国国务院令第199号发布 自1996年10月1日起施行)\n第一条 为了加强对在中华人民共和国管辖海域内进行涉外海洋科学研究活动的管理，促进海洋科学研究的国际交流与合作，维护国家安全和海洋权益，制定本规定。\n第二条 本规定适用于国际组织、外国的组织和个人(以下简称外方)为和平目的，单独或者与中华人民共和国的组织(以下简称中方)合作，使用船舶或者其他运载工具、设施，在中华人民共和国内海、领海以及中华人民共和国管辖的其他海域内进行的对海洋环境和海洋资源等的调查研究活动。但是，海洋矿产资源(包括海洋石油资源)勘查、海洋渔业资源调查和国家重点保护的海洋野生动物考察等活动，适用中华人民共和国有关法律、行政法规的规定。\n第三条 中华人民共和国国家海洋行政主管部门(以下简称国家海洋行政主管部门)及其派出机构或者其委托的机构，对在中华人民共和国管辖海域内进行的涉外海洋科学研究活动，依照本规定实施管理。\n国务院其他有关部门根据国务院规定的职责，协同国家海洋行政主管部门对在中华人民共和国管辖海域内进行的涉外海洋科学研究活动实施管理。\n第四条 在中华人民共和国内海、领海内，外方进行海洋科学研究活动，应当采用与中方合作的方式。在中华人民共和国管辖的其他海域内，外方可以单独或者与中方合作进行海洋科学研究活动。\n外方单独或者与中方合作进行海洋科学研究活动，须经国家海洋行政主管部门批准或者由国家海洋行政主管部门报请国务院批准，并遵守中华人民共和国的有关法律、法规。\n第五条 外方与中方合作进行海洋科学研究活动的，中方应当在海洋科学研究计划预定开始日期6个月前，向国家海洋行政主管部门提出书面申请，并按照规定提交海洋科学研究计划和其他有关说明材料。\n外方单独进行海洋科学研究活动的，应当在海洋科学研究计划预定开始日期6个月前，通过外交途径向国家海洋行政主管部门提出书面申请，并按照规定提交海洋科学研究计划和其他有关说明材料。\n国家海洋行政主管部门收到海洋科学研究申请后，应当会同外交部、军事主管部门以及国务院其他有关部门进行审查，在4个月内作出批准或者不批准的决定，或者提出审查意见报请国务院决定。\n第六条 经批准进行涉外海洋科学研究活动的，申请人应当在各航次开始之日2个月前，将海上船只活动计划报国家海洋行政主管部门审批。国家海洋行政主管部门应当自收到海上船只活动计划之日起1个月内作出批准或者不批准的决定，并书面通知申请人，同时通报国务院有关部门。\n第七条 有关中外双方或者外方应当按照经批准的海洋科学研究计划和海上船只活动计划进行海洋科学研究活动；海洋科学研究计划或者海上船只活动计划在执行过程中需要作重大修改的，应当征得国家海洋行政主管部门同意。\n因不可抗力不能执行经批准的海洋科学研究计划或者海上船只活动计划的，有关中外双方或者外方应当及时报告国家海洋行政主管部门；在不可抗力消失后，可以恢复执行、修改计划或者中止执行计划。\n第八条 进行涉外海洋科学研究活动的，不得将有害物质引入海洋环境，不得擅自钻探或者使用炸药作业。\n第九条 中外合作使用外国籍调查船在中华人民共和国内海、领海内进行海洋科学研究活动的，作业船舶应当于格林威治时间每天00时和08时，向国家海洋行政主管部门报告船位及船舶活动情况。外方单独或者中外合作使用外国籍调查船在中华人民共和国管辖的其他海域内进行海洋科学研究活动的，作业船舶应当于格林威治时间每天02时，向国家海洋行政主管部门报告船位及船舶活动情况。\n国家海洋行政主管部门或者其派出机构、其委托的机构可以对前款外国籍调查船进行海上监视或者登船检查。\n第十条 中外合作在中华人民共和国内海、领海内进行海洋科学研究活动所获得的原始资料和样品，归中华人民共和国所有，参加合作研究的外方可以依照合同约定无偿使用。\n中外合作在中华人民共和国管辖的其他海域内进行海洋科学研究活动所获得的原始资料和样品，在不违反中华人民共和国有关法律、法规和有关规定的前提下，由中外双方按照协议分享，都可以无偿使用。\n外方单独进行海洋科学研究活动所获得的原始资料和样品，中华人民共和国的有关组织可以无偿使用；外方应当向国家海洋行政主管部门无偿提供所获得的资料的复制件和可分样品。\n未经国家海洋行政主管部门以及国务院其他有关部门同意，有关中外双方或者外方不得公开发表或者转让在中华人民共和国管辖海域内进行海洋科学研究活动所获得的原始资料和样品。\n第十一条 外方单独或者中外合作进行的海洋科学研究活动结束后，所使用的外国籍调查船应当接受国家海洋行政主管部门或者其派出机构、其委托的机构检查。\n第十二条 中外合作进行的海洋科学研究活动结束后，中方应当将研究成果和资料目录抄报国家海洋行政主管部门和国务院有关部门。\n外方单独进行的海洋科学研究活动结束后，应当向国家海洋行政主管部门提供该项活动所获得的资料或者复制件和样品或者可分样品，并及时提供有关阶段性研究成果以及最后研究成果和结论。\n第十三条 违反本规定进行涉外海洋科学研究活动的，由国家海洋行政主管部门或者其派出机构、其委托的机构责令停止该项活动，可以没收违法活动器具、没收违法获得的资料和样品，可以单处或者并处5万元人民币以下的罚款。\n违反本规定造成重大损失或者引起严重后果，构成犯罪的，依法追究刑事责任。\n第十四条 中华人民共和国缔结或者参加的国际条约与本规定有不同规定的，适用该国际条约的规定；但是，中华人民共和国声明保留的条款除外。\n第十五条 本规定自1996年10月1日起施行。","level":0}]},{"id":"n0314","sections":[{"name":"","text":"煤炭送货办法\n(煤炭工业部、铁道部修订 1965年12月6日国务院批转 自1966年1月1日起施行)\n实行煤炭送货办法，是煤炭工业部门和铁路、交通部门贯彻执行“发展经济，保障供给”方针，保证完成国家煤炭分配计划，更好地为用煤单位服务的一项重要措施。\n自1956年实行送货以来，对于保证用煤单位的需要，节约人力、物力和财力，促进社会主义建设事业的发展，起了积极作用。但是也还存在一些问题，主要是有些单位，全心全意为用煤单位服务的思想不够明确；在处理企业之间的关系上，强调制约，忽视促进，缺乏严格要求自己的精神和实事求是的态度。\n做好送货工作，在产、运、需三方面，都应当加强为生产、为人民服务的思想，反对单纯营利观点；树立全局观点，反对本位主义；提倡互谅互助、协商办事，反对斤斤计较、互相扯皮。\n煤矿和铁路、交通部门的各级领导干部，必须经常深入实际，深入群众，加强督促检查，主动征求用煤单位意见，及时总结和交流经验，认真改进工作，保证按时、按质、按量地发运煤炭，力求为用煤单位服务得越来越好。\n按时发运\n第一条 煤矿和铁路、交通部门，必须加强协作，密切配合，千方百计地采取措施，保证用煤单位按时收到煤炭。\n第二条 煤矿应当根据订货合同，编制煤炭月度运输计划，并办理托运手续。\n铁路部门和煤矿，应当根据煤炭月度运输计划、用煤单位需用煤炭的缓急情况和卸车、储存能力，共同编制旬、日装车方案，做到对大户均衡发运，对小户定旬发运，保证全面地完成计划。\n第三条 用煤单位遇有特殊情况，提出推迟或者提前发运煤炭的时候，煤矿和铁路、交通部门，应当共同设法，尽量满足这种要求。\n煤矿和铁路、交通部门遇有特殊情况，不能按照计划发运煤炭的时候，必须主动与用煤单位或其上级主管部门研究解决办法，尽量避免给用煤单位造成困难。\n保证质量\n第四条 煤矿必须认真贯彻“质量第一”的方针，努力提高煤炭的质量，不断降低煤炭中的灰分、全水分、含矸率和块煤限下率，保证按照订货合同中规定的品种、规格、质量标准发运煤炭。\n第五条 煤矿发运的煤炭的质量，应当批批合格。但是，灰分和全水分，按批检查的时候，分别允许有百分之零点五和百分之一(绝对值)的波动系数，全月平均都不准有波动系数。\n第六条 煤矿在发煤以前，必须按照国家规定的办法严格进行质量检查，发现不符合第五条规定的，不准装车外运；已经运出的，必须主动赔偿用煤单位的损失。灰分低于规定标准的，征得用煤单位同意后，可以增收价款。全水分、含矸率和块煤限下率低于规定标准的，不增收价款。\n第七条 煤矿应当根据用煤单位的要求，提交煤炭质量化验单。\n保证重量\n第八条 煤矿和铁路、交通部门，必须切实负责，积极采取措施，保证发运的煤炭，重量准确，在运输和换装过程中不抛撒丢失。\n第九条 铁路部门和有专用铁道的企业，对于送到煤矿的车皮，应当保证车体完整，技术状态良好，清扫干净，关牢车门；对于装载出口煤炭需要原车过轨的车皮，还必须保证符合过轨的条件。煤矿发现车皮不符合上述要求的时候，应当通知铁路部门或有专用铁道的企业及时改进，或者在力所能及的情况下主动帮助处理。\n铁路部门应当定期校正车皮的标记自重，保证准确。有轨道衡的煤矿、港口和用煤单位，应当根据铁路部门的要求，尽量帮助校正。\n棚车和平车禁止装煤。砂石车一般不准装煤；但是，对于到达煤矿和煤矿所在车站卸空的砂石车，应当加以利用。\n第十条 煤矿装车，应当按照车皮标记载重装足；如果装到车帮高度仍然达不到标记载重，可以超出车帮起脊装载，但是必须确保车辆运行时不溜失煤炭。起脊高度由路矿双方商定。煤炭的价款和运费，都按实际装载量计算。\n第十一条 煤矿发运煤炭的重量，应当用轨道衡衡量；没有轨道衡的煤矿，用检尺测量方法计算，但是应当有计划地安装轨道衡。\n用轨道衡衡量重量的煤矿，应当每半年请检衡机构检衡一次。没有合格证的轨道衡，不准使用。\n用检尺测量方法计算重量的煤矿，应当每季测定一次煤炭的容积比重。如果用煤单位反映重量不准，煤矿应当及时进行检查，原因在于比重的，必须立即重新测定，并自测定的次日起执行；主管的煤炭工业管理局(公司)认为必要时，应当派人检查处理，或者邀请有关用煤单位协同煤矿测定比重。\n第十二条 用轨道衡衡量重量的，车皮自重以标记自重为准；装煤重量，除按规定可以少装或多装的以外，应当与标记载重符合，不够的必须添足，超过的必须卸下。装好以后，在煤车的顶面上洒石灰浆作为标记；或者进行平车，以煤车顶面的平整状态作为标记。在货物运单内，煤矿必须填明煤炭的矿别、品种、级别、并加盖“衡”字章。\n用检尺测量方法计算重量的，煤矿必须切实做好量车、划线、平车工作，以煤车顶面的平整状态作为标记。在货物运单内，煤矿必须填明实际装载煤炭的长、宽、高度和煤炭的容积比重、矿别、品种、级别。\n第十三条 煤矿装车，必须做到四个一样：黑夜和白天装的一样；坏天气和好天气装的一样；领导不在场和领导在场装的一样；没人检查和有人检查装的一样。\n煤矿应当建立严格的检查制度。所有装好的煤车，都必须经检查人员确认重量准确后，才可以办理托运手续。\n第十四条 车站对于煤矿装好的煤车，必须逐车检查。合格的，与煤矿办理交接手续；不合格的，应当提出要求，经煤矿改善后再办交接手续。\n通过验收，促进工作\n第十五条 煤车到站后，用煤单位可以采取抽查的办法对煤炭的重量和质量进行验收。通过验收，发现问题，找出原因，分清责任，改进工作。\n煤矿和铁路、交通部门，对于用煤单位提出的意见，必须认真对待，严肃处理，吸取教训，采取措施，切实改进。\n第十六条 到站的煤车，标记状态发生变化的，车站应当会同用煤单位进行复查。短少的重量，由铁路部门赔偿。\n到站的煤车，标记状态没有变化的，用煤单位可以进行抽查。对于货物运单上有“衡”字章的煤车，必须用轨道衡衡量；没有“衡”字章的煤车，用量线方法计算，或者用轨道衡衡量，也可以用磅秤检斤。短少的重量，由煤矿补发煤炭，或者退还价款和运费。用轨道衡和量线方法抽查的时候，车站必须派员参加，抽查费由责任单位负担。用磅秤抽查的时候，由用煤单位自行过磅，抽查费自行负担。\n第十七条 煤炭的质量，以煤矿的化验和测定结果为准。但是，用煤单位认为必要的时候，可以派员到煤矿进行检查，也可以在到站进行抽查。抽查的时候，灰分按照国家规定的办法，采样、制样、化验；含矸率整车拣选；块煤限下率整车筛选，但是为了避免筛选造成破碎损失，应当尽量协商处理。抽查结果，质量不合格的，煤矿应当负责赔偿。\n用煤单位为抽查煤炭质量支付的各种费用，除筛选费由责任单位担负以外，其余一律自行负担。\n第十八条 煤矿对于水陆联运煤炭的质量和重量，负责到第一个换装港口的车站；对于出口煤炭的质量和重量，负责到国境车站。\n第十九条 用煤单位对于品种不符合合同规定的煤炭，应当领取卸车，妥为保管，并及时通知煤矿设法处理。\n第二十条 用煤单位要求煤矿赔偿重量短少和质量不合格的损失，都以实际抽查的部分为限，不得以抽查结果推算全部。\n按期付款\n第二十一条 用煤单位必须按期付款。但遇有下列情形之一的时候，可以拒付价款和运费的一部或全部：\n一、煤矿托收的款额计算错误的，可以拒付多算的款额；\n二、煤矿发煤品种与订货合同规定不符的，可以拒付价款和运费；\n三、煤矿发煤的数量超过月度运输计划较多，造成积压的，可以拒付超发部分的价款和运费。\n第二十二条 煤炭的价款和运费(包括煤矿垫付运费的利息和未计入煤价的铁路专用线费、调车费)，按照银行的规定办理结算。\n银行应当督促用煤单位按期承付煤矿托收的价款和运费；对于不按照第二十一条规定承付的用煤单位，应当从其存款中扣收。\n其他\n第二十三条 煤矿实行送货，应当经过批准。煤炭工业部所属煤矿，由主管的煤炭工业管理局(公司)商得有关铁路局同意后，报请煤炭工业部和铁道部批准；地方煤矿，由所在省、自治区、直辖市主管厅(局)商得有关铁路局同意后，报请省、自治区、直辖市人民委员会批准。\n第二十四条 本办法的实施细则，由煤炭工业部、铁道部、交通部另行制定。","level":0}]},{"id":"n0315","sections":[{"name":"","text":"现役军人和人民武装警察\n居民身份证申领发放办法\n(2007年10月21日中华人民共和国国务院、中华人民共和国中央军事委员会令第510号公布 自2008年1月1日起施行)\n第一条 为了规范现役军人、人民武装警察居民身份证的申领和发放，依照《中华人民共和国居民身份证法》的有关规定，制定本办法。\n第二条 现役军人、人民武装警察居民身份证的申领和发放，适用本办法。\n第三条 现役军人、人民武装警察居民身份证登记项目包括：姓名、性别、民族、出生日期、长期固定住址、公民身份号码、本人相片、证件的有效期和签发机关。\n第四条 现役军人、人民武装警察居民身份证登记项目内容，以本人档案记载内容和公安机关编制的公民身份号码为基础，由本人所在团级以上单位统一组织文字信息和人像信息的采集、录入、审核。\n第五条 现役军人、人民武装警察申请领取、换领、补领居民身份证，应当填写《现役军人、人民武装警察居民身份证申领登记表》，由本人所在团级以上单位向本人长期固定住址所在地的县级人民政府公安机关代为申请。\n第六条 现役军人、人民武装警察居民身份证由本人长期固定住址所在地的县级人民政府公安机关签发。\n第七条 现役军人、人民武装警察申请领取、换领、补领居民身份证的，公安机关应当依照《中华人民共和国居民身份证法》第十二条第一款的规定办理。\n第八条 现役军人、人民武装警察在服役前已经领取居民身份证，服役期间居民身份证仍在有效期内的，不再换领新证；但是，应当向其所在团级以上单位登记备案。\n第九条 现役军人、人民武装警察申请领取临时居民身份证的，由本人所在团级以上单位代为申请；公安机关应当依照《中华人民共和国临时居民身份证管理办法》的规定办理。\n第十条 军队、武装警察部队团级以上单位代现役军人、人民武装警察领取居民身份证、临时居民身份证后，应当及时发给本人。\n第十一条 现役军人、人民武装警察从事有关社会活动，需要证明公民身份的，凭居民身份证证明；执行任务、办理公务、享受抚恤优待等，需要证明现役军人或者人民武装警察身份的，凭军队、武装警察部队制发的身份证件证明。\n第十二条 军队、武装警察部队团级以上单位应当建立健全所属人员居民身份证的申领登记、备案等制度；在所属人员的本人档案中，应当载明其公民身份号码。\n第十三条 公安机关、军队、武装警察部队及其有关人员，在现役军人、人民武装警察居民身份证申领和发放工作中，对所涉及的国家秘密和知悉的个人信息，应当予以保密。\n第十四条 现役军人、人民武装警察有下列行为之一的，依照《中国人民解放军纪律条令》的有关规定，给予处分：\n(一)使用虚假证明材料骗领居民身份证的；\n(二)出租、出借、转让居民身份证的；\n(三)非法扣押他人居民身份证的；\n(四)冒用他人居民身份证或者使用骗领的居民身份证的；\n(五)购买、出售、使用伪造、变造的居民身份证的。\n对伪造、变造的居民身份证和骗领的居民身份证予以收缴。\n第十五条 现役军人、人民武装警察伪造、变造居民身份证的，依法追究刑事责任。\n现役军人、人民武装警察有本办法第十四条所列行为之一，从事犯罪活动的，依法追究刑事责任。\n第十六条 军队、武装警察部队有关人员在现役军人、人民武装警察居民身份证申领和发放工作中有下列行为之一的，依照《中国人民解放军纪律条令》的有关规定，给予处分；构成犯罪的，依法追究刑事责任：\n(一)对居民身份证登记项目审查不严，致使登记信息失实造成严重后果的；\n(二)利用办理居民身份证工作的便利，收受财物或者谋取其他利益的；\n(三)故意提供居民身份证登记项目虚假信息的；\n(四)泄露国家秘密或者个人信息的。\n公安机关人民警察在现役军人、人民武装警察居民身份证申领和发放工作中有前款第(四)项行为的，依法给予处分；构成犯罪的，依法追究刑事责任。\n第十七条 军队、武装警察部队管理的离休退休干部和待移交人民政府安置的离休退休干部、退休士官居民身份证的申领和发放，依照本办法执行。\n第十八条 本办法自2008年1月1日起施行。","level":0}]},{"id":"n0316","sections":[{"name":"","text":"保护海底电缆规定\n(1973年5月30日发布)\n(一) 保护海底电缆是加强海防建设的重要措施。各舰艇部队、交通航运、水产打捞、海洋调查、沿海社队等有关部门，要经常教育所属人员明确保护海底电缆的重要意义，提高警惕，严防破坏。\n(二) 舰艇、商船、外轮等舰船锚泊，捕捞作业，要避开敷设有海底电缆的禁区抛锚(靠近码头的海缆登陆区可搞水面浮体标志)。海底勘察和码头建筑等大型工程要事先和当地驻军领导机关联系，以便采取相应措施，妥善解决。\n(三) 船锚或捕捞工具，因意外钩到海底电缆时，应将电缆慢慢提到水面，取下船锚(或钩挂物)，查其确无损伤后把电缆放进海中；电缆提不到水面时，不得将电缆拖断或砍断，必要时可放弃船锚(或钩挂物)。\n(四) 钩到或损伤电缆均要在该处做好水面浮体标志，并将位置和受损情况及时报告当地政府领导机关，或有关部门负责处理。\n(五) 任何单位、船只和个人，不得擅自打捞、切断、撤收和盗窃海底电缆，否则以破坏论处。\n海底电缆遭受损伤或破坏后，当地公安、武装部门应大力协助使用单位，迅速查清原因。如因工作失职或措施不当而造成损坏者，损坏单位应负责赔偿并对肇事者进行批评教育，情节严重者应给予处分。","level":0}]},{"id":"n0317","sections":[{"name":"","text":"中国人民解放军驻铁路、\n水路沿线交通部门军事代表条例\n(国务院、中央军委 1978年6月29日)\n第一条 交通运输是国民经济的先行，是国防建设的重要组成部分。组织良好的军事 运输，对保证革命战争胜利具有重要作用。为使军队与铁路、水路交通部门密切协同，加 强国防交通建设和战时交通保障，完成平时、战时的军事运输任务，特在铁路、水路沿线 交通部门(以下简称铁路、水路部门)实行派驻军事代表制度，设置军事代表办事处。\n第二条 军事代表办事处，是中国人民解放军派出遂行军事交通任务的代表，也是铁 路、水路部门党委完成军事运输任务和做好交通战备、战时交通保障工作的助手。\n第三条 军事代表办事处，要在党的一元化领导下，贯彻军、政、民运输统一指挥， 铁、水、公路综合运用，运输、抢修、防护紧密结合的方针，依靠铁路、水路部门，依靠 部队，依靠地方政府和广大人民群众，努力做好各项工作。\n第四条 军事代表办事处的任务\n(一)坚决贯彻执行中共中央、国务院、中央军委关于国防交通建设和军事运输的方 针、政策和指示。\n(二)计划、组织、指挥铁路、水路军事运输。组织铁路、水路部门和部队的协同， 保证迅速、准确、保密、安全、节约地完成军事运输任务。\n(三)根据总部和军区的意图，研究战时交通保障方案，向铁路、水路及有关部门提 出军事要求，并参与有关工作。\n(四)协助部队编制战备输送方案和进行输送训练。会同铁路、水路部门编制和落实 战备输送保障方案。\n(五)掌握有关交通运输情况，搜集研究有关交通资料。\n(六)审核、结算并指导部队正确使用军事交通费。\n(七)参与新建铁路军事专用线的设计审查和验收，检查指导铁路军事专用线的维修 管理。\n(八)协助地方政府有关部门做好铁路、水路沿线军用饮食供应站的工作。\n(九)协同车站、港口管理零星军人的运送事宜。\n(十)执行中国人民解放军《纪律条令》规定的有关任务。\n第五条 军事代表办事处的设置\n(一)在铁路局、分局、主要车站派设驻局、分局、车站(地区)三级军事代表办事 处，分别相当于师、团、营级单位。\n(二)根据工作需要，在沿海、长江、内河的港航部门派设相应的师、团、营级军事 代表办事处。在港航部门较多的地区，设置地区的师或团级军事代表办事处，其机构驻在 其中的一个港航部门。\n(三)军事代表办事处由军区或总部派出，称为“中国人民解放军驻×××军事代表 办事处”。其机构设置、撤销，由军区提出建议，上报审批。\n(四)师、团级军事代表办事处配主任、政治委员。师级军事代表办事处设科和政治 处。团级军事代表办事处配参谋和必要的政治、行政工作人员。营级军事代表办事处配主 任、参谋。\n(五)军事代表办事处的后勤保障、军用通信，由军队负责。\n第六条 军事代表办事处的领导关系\n(一)军事代表办事处受军队派出机关领导，同时接受驻在的铁路、水路部门党委的 领导。\n(二)各级军事代表办事处的党政、业务工作实行逐级垂直领导。\n(三)师、团级军事代表办事处，由驻在的铁路、水路部门党委书记兼任第一政治委 员。铁路、水路部门党委应将派驻的军事代表办事处的主要负责同志选入党委(或常委) 。\n(四)铁路、水路部门党委应积极领导和组织完成军事交通任务。军事代表办事处应 主动向铁路、水路部门党委请求报告工作，转达派出机关布置的任务和要求。\n第七条 军事代表办事处与当地政府的关系\n(一)军事代表办事处要主动向当地政府请示报告有关工作，取得领导和支持。地方 政府应关心和支持军事代表办事处的工作，提供有关交通资料，吸收他们参加有关的工作 和活动。\n(二)军事代表办事处应及时向当地政府开设的军用饮食供应站提出供应任务。军用 饮食供应站应接受军事代表办事处对供应工作的指导，及时准确、保质保量地完成供应任 务。\n第八条 军事代表办事处与铁路、水路部门的关系\n(一)军事代表办事处应和铁路、水路部门团结一致，互相配合，密切协商，主动通 报情况，共同完成任务。\n(二)军事代表办事处应关心和支持铁路、水路部门的生产建设，积极参加有关活动 ，听取他们的意见和建议，遵守铁路、水路部门的规章制度。\n(三)铁路、水路部门应积极支持军事代表办事处的工作，吸收他们参加有关会议， 听取他们关于军事运输、交通战备和战时交通保障方面的要求和建议，征求他们对长远规 划、基本建设、车船制造等有关方面的意见，执行军事运输规章制度，严守军事机密。\n(四)铁路、水路部门要关心军事代表办事处的工作、学习和生活，提供必要的工作 条件。免费提供办公房舍、办公设备和通信设备，提供有关文件资料，发给与其干部相同 规定的公用免费乘车、乘船凭证，协助解决住房、医疗等生活问题。\n(五)车站、港口应根据军事代表办事处的要求，保证执行紧急或特殊任务的零星军 人乘车、乘船的需要。\n第九条 军事代表办事处与部队的关系\n(一)军事代表办事处要熟悉管内驻军有关情况，帮助部队搞好军事运输工作，向部 队宣传有关运输的政策和规定，介绍情况，尽力解决部队运输中的困难。\n(二)部队在组织实施军事运输时，应接受军事代表办事处的指导，与军事代表办事 处主动联系，及时向他们反映有关情况，听取他们的意见和要求，接受其传达的上级命令 和指示。\n(三)军事代表办事处和执行铁路、水路抢修、防护任务的部队，要密切联系，互通 情况，搞好协同。\n(四)驻车站、港口军事代表办事处，在执行《纪律条令》规定的任务时，受卫戍、 警备区或担任当地警备勤务的驻军的领导。派到车站、港口执勤的分队应与军事代表办事 处取得联系。\n第十条 对军事代表办事处的要求\n(一)努力学习马列著作和毛主席著作，充分发挥党组织的核心领导作用，搞好军事 代表办事处的革命化建设。\n(二)保持和发扬我党我军的优良传统，虚心向铁路、水路部门和人民群众学习，严 格执行三大纪律八项注意，搞好军政、军民团结。\n(三)树立全局观念、政策观念，正确处理平时与战时、民运与军运、国民经济建设 与国防交通建设的关系，全心全意为部队服务，为战争服务。\n(四)发扬一不怕苦、二不怕死的革命精神，谦虚谨慎、积极主动、准确及时、认真 负责地做好本职工作。\n(五)努力学习军事和铁路、水路有关业务知识，认真研究现代战争中军事交通保障 的课题，提高军事素质，精通职业务，做到又红又专。\n(六)保持高度的革命警惕，严守国家军事机密，增强战备观念，时刻准备打仗。","level":0}]},{"id":"n0318","sections":[{"name":"","text":"外国公司船舶运输\n收入征税办法\n(1996年9月18日国务院批准 1996年10月24日财政部、国家税务总局发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》修订)\n第一条 为了加强对外国公司以船舶从事国际海运业务从中国取得运输收入的税收管理，根据《中华人民共和国税收征收管理法》、《中华人民共和国营业税暂行条例》以及企业所得税相关法律的规定，制定本办法。\n第二条 外国公司以船舶从中国港口运载旅客、货物或者邮件出境的，所取得的运输收入、所得，依照本办法缴纳营业税、企业所得税。\n第三条 外国公司以船舶从中国港口运载旅客、货物或者邮件出境的，取得运输收入的承运人为纳税人。纳税人包括：\n(一)买方派船的期租船，以外国租船公司为纳税人；\n(二)程租船，以外国船东为纳税人；\n(三)中国租用的外国籍船舶再以期租方式转租给外国公司的，以外国公司为纳税人；\n(四)外国公司期租的中国籍船舶，以外国公司为纳税人；\n(五)其他外国籍船舶，以其船公司为纳税人。\n依法经批准经营外轮代理业务的公司(以下简称外轮代理人)为应纳税款的扣缴义务人。\n第四条 纳税人的应纳税额，按照每次从中国港口运载旅客、货物或者邮件出境取得的收入总额，依照4.65%的综合计征率计征，其中营业税为3%，企业所得税为1.65%。\n第五条 本办法第四条所称收入总额，是指纳税人经营的船舶每次运载从中国港口始发旅客、货物或者邮件到达目的地的客运收入和货运收入的总和，不得扣除任何费用或者支出。客运收入包括船票收入以及逾重行李运费、餐费、保险费、服务费和娱乐费等。货运收入包括基本运费以及各项附加费等收入。\n第六条 外国公司以船舶到中国港口运载旅客、货物或者邮件出境的，在将承运人的地址、船舶悬挂的国旗、客运情况、运货种类、运量以及到港日期通知外轮代理人的同时，应当将运费率等通知外轮代理人。\n第七条 外国公司以船舶到中国港口运载旅客、货物或者邮件出境，委托外轮代理人计算并代收运费的，外轮代理人应当在收取运费后，按照本办法第四条规定的综合计征率，直接从纳税人的收入总额中代扣应纳税款。\n第八条 外国公司以船舶到中国港口运载旅客、货物或者邮件出境，不通过外轮代理人代收运费的，外轮代理人应当根据本办法第四条规定的综合计征率计算预计税款，并通知纳税人在船舶抵港前将预计税款与港口使用费备用金一并汇达，由外轮代理人代收税款。\n外国公司以船舶运载旅客、货物或者邮件出境后，外轮代理人应当在电告纳税人该船舶实际运载的出境旅客人数、货物或者邮件数量的同时，通知其向税务机关报告运输收入总额和应纳税额，并附运费结算凭证。纳税人向税务机关报告和缴纳税款的期限不得超过船舶离港之日起60日。\n第九条 外轮代理人应当将按照本办法第七条、第八条规定代扣、代收的税款，自代扣代收之日起10日内，将实收税款缴入国库，并在次月15日前向港口所在地税务机关报送上月外轮代理业务情况一览表、运费结算情况统计报表、《代扣代缴、代收代缴外轮运输收入税收报告表》等资料。\n第十条 纳税人不能完整、准确地提供本办法第六条、第八条规定的资料，不能正确计算收入总额的，外轮代理人应当及时报告港口所在地税务机关。港口所在地税务机关可以会同外轮代理人，参照国际间相同或者类似情况下运载旅客或者货物的通常价格，或者根据我国有关部门制订的运费率表，核定纳税人的收入总额，并据以征税。\n第十一条 外国公司以同一艘船舶在中国几个港口运载旅客、货物或者邮件出境的，应当按照其在各港口运载旅客、货物或者邮件的运输收入，分别在各起运港征税。但是，同一艘程租船连续在中国几个港口运载货物或者邮件出境，其运费收入采取净包干方法的，全部运输收入应当在运载货物或者邮件的第一港口征税；采取包干运费并加收增港附加费方法的，其包干运费收入应当在运载货物或者邮件的第一港口征税，增港附加费收入应当分别在货物或者邮件起运港征税。\n第十二条 在中国港口运载旅客、货物或者邮件出境，经由另一国或者地区转运到目的地的，营业税按照纳税人全程运费减去付给后续运输企业运费后的余额计征，企业所得税按照提单全程运输收入总额计征。\n第十三条 外轮代理人按照本办法代扣、代收税款时，税务机关应当按照有关规定付给扣缴义务人代扣、代收手续费。\n第十四条 纳税人、扣缴义务人未按照本办法履行义务的，依照《中华人民共和国税收征收管理法》及其实施细则的有关规定处罚。\n第十五条 外轮代理人填报的《代扣代缴、代收代缴外轮运输收入税收报告表》由国家税务总局统一印制。\n第十六条 香港、澳门、台湾的公司以船舶从境内港口运载旅客、货物或者邮件出境的，所取得的运输收入、所得，除另有规定外，比照本办法征税。\n第十七条 中华人民共和国同外国缔结的有关协定规定减税或者免税的，按照协定规定执行。\n前款所称协定，是指关于对所得(和财产)避免双重征税和防止偷漏税的协定、互免海运企业运输业务收入税收协定、海运协定以及其他有关协定或者换文。\n第十八条 外国公司以船舶到中国港口运载旅客、货物或者邮件出境，所取得的运输收入、所得，按照本办法第十七条规定的协定可以享受减税或者免税的，应当按照本办法第六条的规定提供有关情况，税务机关分别情况查验下列证明文件：\n(一)按照协定规定，船舶运输收入、所得仅由企业的实际管理机构或者总机构所在缔约国征税的，或者收入来源国应对缔约国对方居民公司经营国际运输业务取得的收入、所得减税或者免税的，外国公司应当提供缔约国税务主管当局出具的该公司实际管理机构、总机构或者居民公司所在地的证明文件；\n(二)按照协定规定，收入来源国应当对悬挂缔约国对方国旗的商船或者由缔约国对方航运企业经营悬挂第三国国旗的商船取得的运输收入、所得减税或者免税的，外国公司应当提供缔约国对方航运主管部门出具的证明文件。\n不能提供有关证明文件的，不得享受减税或者免税待遇。\n第十九条 本办法自发布之日起施行。经国务院批准、财政部1974年6月发布的《关于对外国籍轮船运输收入的征税规定》同时废止。","level":0}]},{"id":"n0319","sections":[{"name":"","text":"武器装备科研生产许可管理条例\n(2008年3月6日中华人民共和国国务院、中华人民共和国中央军事委员会令第521号公布 自2008年4月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了维护武器装备科研生产秩序，加强武器装备科研生产安全保密管理，保证武器装备质量合格稳定，满足国防建设的需要，制定本条例。\n第二条 国家对列入武器装备科研生产许可目录(以下简称许可目录)的武器装备科研生产活动实行许可管理。但是，专门的武器装备科学研究活动除外。\n许可目录由国务院国防科技工业主管部门会同中国人民解放军总装备部(以下简称总装备部)和军工电子行业主管部门共同制定，并适时调整。许可目录的制定和调整，应当征求国务院有关部门和军队有关部门的意见。\n武器装备科研生产许可，应当在许可目录所确定的范围内实行分类管理。\n第三条 未取得武器装备科研生产许可，不得从事许可目录所列的武器装备科研生产活动。但是，经国务院、中央军事委员会批准的除外。\n第四条 武器装备科研生产许可管理，应当遵循统筹兼顾、合理布局、鼓励竞争、安全保密的原则。\n第五条 国务院国防科技工业主管部门，依照本条例规定对全国的武器装备科研生产许可实施监督管理。\n总装备部协同国务院国防科技工业主管部门对全国的武器装备科研生产许可实施监督管理。\n省、自治区、直辖市人民政府负责国防科技工业管理的部门，依照本条例规定对本行政区域的武器装备科研生产许可实施监督管理。\n第六条 取得武器装备科研生产许可的单位，应当在许可范围内从事武器装备科研生产活动，按照国家要求或者合同约定提供合格的科研成果和武器装备。","level":1},{"name":"第二章 许可程序","text":"第七条 申请武器装备科研生产许可的单位，应当符合下列条件：\n(一)具有法人资格；\n(二)有与申请从事的武器装备科研生产活动相适应的专业技术人员；\n(三)有与申请从事的武器装备科研生产活动相适应的科研生产条件和检验检测、试验手段；\n(四)有与申请从事的武器装备科研生产活动相适应的技术和工艺；\n(五)经评定合格的质量管理体系；\n(六)与申请从事的武器装备科研生产活动相适应的安全生产条件；\n(七)有与申请从事的武器装备科研生产活动相适应的保密资格。\n第八条 申请武器装备科研生产许可的单位，应当向所在地的省、自治区、直辖市人民政府负责国防科技工业管理的部门提出申请。\n许可目录规定应当向国务院国防科技工业主管部门申请武器装备科研生产许可的，应当直接向国务院国防科技工业主管部门提出申请，并将申请材料同时报送总装备部。\n第九条 国务院国防科技工业主管部门和省、自治区、直辖市人民政府负责国防科技工业管理的部门收到申请后，应当依照《中华人民共和国行政许可法》规定的程序办理。\n第十条 省、自治区、直辖市人民政府负责国防科技工业管理的部门组织对申请单位进行审查，应当征求中国人民解放军派驻的军事代表机构(以下简称军事代表机构)的意见，并自受理申请之日起30日内完成审查，将审查意见和全部申请材料报送国务院国防科技工业主管部门，同时报送总装备部。\n第十一条 国务院国防科技工业主管部门受理申请后，应当进行审查，并自受理申请之日起60日内或者自收到省、自治区、直辖市人民政府负责国防科技工业管理的部门报送的审查意见和全部申请材料之日起30日内，做出决定。做出准予许可决定的，应当自做出决定之日起10日内向提出申请的单位颁发武器装备科研生产许可证；做出不准予许可决定的，应当书面通知提出申请的单位，并说明理由。\n国务院国防科技工业主管部门在做出决定前，应当书面征求总装备部的意见，总装备部应当在10日内回复意见。\n第十二条 国务院国防科技工业主管部门根据国家武器装备科研生产能力布局的要求，按照武器装备科研生产的实际需要，经征求总装备部意见，可以对有特殊要求的武器装备科研生产许可做出数量限制。\n第十三条 武器装备科研生产许可证应当载明单位名称、法定代表人、许可专业或者产品名称、证书编号、发证日期、有效期等相关内容。\n武器装备科研生产许可证格式由国务院国防科技工业主管部门规定。\n第十四条 取得武器装备科研生产许可的单位应当妥善保管武器装备科研生产许可证，严格保密管理，不得泄露武器装备科研生产许可证载明的相关内容。\n第十五条 取得武器装备科研生产许可的单位应当在武器装备科研生产合同、产品出厂证书上标注武器装备科研生产许可证编号。\n第十六条 任何单位和个人不得伪造、变造武器装备科研生产许可证。取得武器装备科研生产许可的单位不得出租、出借或者以其他方式转让武器装备科研生产许可证。\n第十七条 国务院国防科技工业主管部门和省、自治区、直辖市人民政府负责国防科技工业管理的部门，应当将办理武器装备科研生产许可的有关材料及时归档，并妥善保存，严格保密。\n第十八条 取得武器装备科研生产许可并承担武器装备科研生产任务的单位，应当接受军事代表机构的监督。","level":1},{"name":"第三章 保密管理","text":"第十九条 取得武器装备科研生产许可的单位应当遵守国家保密法律、法规和有关规定，建立健全保密管理制度，按照积极防范、突出重点、严格标准、明确责任的原则，对落实保密管理制度的情况进行定期或者不定期的检查，及时研究解决保密工作中的问题。\n第二十条 取得武器装备科研生产许可的单位应当建立保密管理领导责任制，其主要负责人应当加强对本单位保密工作的组织领导，切实履行保密职责和义务。\n第二十一条 取得武器装备科研生产许可的单位应当设立保密工作机构，配备保密管理人员。\n保密管理人员应当熟悉国家保密法律、法规和有关规定，具备保密管理工作能力，掌握保密技术基础知识，并经过必要的培训、考核。\n第二十二条 取得武器装备科研生产许可的单位应当与承担武器装备科研生产任务的涉及国家秘密人员签订岗位保密责任书，明确岗位保密责任，并对其进行经常性的保密教育培训。\n涉及国家秘密人员应当熟悉国家保密法律、法规和有关规定，严格按照岗位保密责任书的要求，履行保密义务。\n第二十三条 取得武器装备科研生产许可的单位应当依照国家保密法律、法规和有关规定，制作、收发、传递、使用、复制、保存和销毁国家秘密载体，严格控制接触国家秘密载体的人员范围。\n第二十四条 取得武器装备科研生产许可的单位应当采取措施，在涉及国家秘密的要害部门、部位设置安全可靠的保密防护设施。\n第二十五条 取得武器装备科研生产许可的单位应当依照国家保密法律、法规和有关规定对涉及国家秘密的计算机和信息系统采取安全保密防护措施，不得使用无安全保密保障的设备处理、传输、存储国家秘密信息。\n第二十六条 取得武器装备科研生产许可的单位举办涉及国家秘密的重大会议或者活动，应当制订专项保密工作方案，并确定专人负责保密工作。涉及国家秘密的会议必须在有安全保密保障措施的场所进行，并严格控制与会人员的范围。\n第二十七条 取得武器装备科研生产许可的单位在对外交流、合作和谈判等活动中，应当保守国家秘密，对外提供有关文件资料和实物样品，必须按照规定的程序事先经过批准。\n第二十八条 取得武器装备科研生产许可的单位应当依照国家保密法律、法规和有关规定建立保密档案制度，对涉及国家秘密人员的管理、泄密事件查处等情况进行记录，及时归档，并对涉及国家秘密的档案实施有效管理。","level":1},{"name":"第四章 法律责任","text":"第二十九条 未依照本条例规定申请取得武器装备科研生产许可，擅自从事许可目录范围内武器装备科研生产活动的，责令停止违法行为，没收违法生产的产品，并处违法生产产品货值金额1倍以上3倍以下罚款；有违法所得的，没收违法所得。\n第三十条 取得武器装备科研生产许可的单位，出租、出借或者以其他方式转让武器装备科研生产许可证的，处10万元罚款；情节严重的，吊销武器装备科研生产许可证。违法接受并使用他人提供的武器装备科研生产许可证的，责令停止武器装备生产活动，没收违法生产的产品，并处违法生产产品货值金额1倍以上3倍以下罚款；有违法所得的，没收违法所得。\n第三十一条 伪造、变造武器装备科研生产许可证的，责令停止违法行为，处10万元罚款；有违法所得的，没收违法所得。\n第三十二条 以欺骗、贿赂等不正当手段取得武器装备科研生产许可的，处5万元以上20万元以下罚款，并依照《中华人民共和国行政许可法》的有关规定处理。\n第三十三条 国务院国防科技工业主管部门和省、自治区、直辖市人民政府负责国防科技工业管理的部门及其工作人员违反本条例规定，有下列情形之一的，由同级监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分：\n(一)对符合本条例规定条件的申请不予受理的；\n(二)未依法说明不准予许可的理由的。\n第三十四条 国务院国防科技工业主管部门和省、自治区、直辖市人民政府负责国防科技工业管理的部门有下列情形之一的，由同级监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分：\n(一)对不符合本条例规定条件的申请人准予许可或者超越法定职权做出准予许可决定的；\n(二)对符合本条例规定条件的申请人不准予许可或者不在法定期限内做出准予许可决定的；\n(三)发现未依照本条例规定申请取得武器装备科研生产许可而擅自从事列入许可目录的武器装备科研生产活动，不及时依法查处的。\n第三十五条 取得武器装备科研生产许可的单位违反本条例第十九条、第二十条、第二十一条、第二十二条、第二十八条规定的，责令限期改正；逾期未改正的，处5万元以上20万元以下罚款，对直接负责的主管人员和其他直接责任人员依法给予处分。\n第三十六条 取得武器装备科研生产许可的单位违反本条例第二十三条、第二十四条、第二十五条、第二十六条、第二十七条规定的，责令改正，处5万元以上20万元以下罚款，对直接负责的主管人员和其他直接责任人员依法给予处分；情节严重的，责令停业整顿直至吊销武器装备科研生产许可证。\n第三十七条 取得武器装备科研生产许可的单位违反本条例规定，被吊销武器装备科研生产许可证的，在3年内不得再次申请武器装备科研生产许可。\n第三十八条 本条例规定的行政处罚，由国务院国防科技工业主管部门实施。\n第三十九条 违反本条例规定，构成犯罪的，依法追究刑事责任。","level":1},{"name":"第五章 附则","text":"第四十条 依照本条例规定实施武器装备科研生产许可，不得收取任何费用。\n第四十一条 本条例施行前已经从事武器装备科研生产活动的单位应当自本条例施行之日起，在国务院国防科技工业主管部门规定的期限内，依照本条例规定申请取得武器装备科研生产许可。\n第四十二条 军工电子行业科研生产许可管理，由其主管部门参照本条例规定执行。\n第四十三条 本条例自2008年4月1日起施行。","level":1}]},{"id":"n0320","sections":[{"name":"","text":"中华人民共和国进出境动植物\n检疫法实施条例\n(1996年12月2日中华人民共和国国务院令第206号发布 自1997年1月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 根据《中华人民共和国进出境动植物检疫法》(以下简称进出境动植物检疫法)的规定，制定本条例。\n第二条 下列各物，依照进出境动植物检疫法和本条例的规定实施检疫：\n(一)进境、出境、过境的动植物、动植物产品和其他检疫物；\n(二)装载动植物、动植物产品和其他检疫物的装载容器、包装物、铺垫材料；\n(三)来自动植物疫区的运输工具；\n(四)进境拆解的废旧船舶；\n(五)有关法律、行政法规、国际条约规定或者贸易合同约定应当实施进出境动植物检疫的其他货物、物品。\n第三条 国务院农业行政主管部门主管全国进出境动植物检疫工作。\n中华人民共和国动植物检疫局(以下简称国家动植物检疫局)统一管理全国进出境动植物检疫工作，收集国内外重大动植物疫情，负责国际间进出境动植物检疫的合作与交流。\n国家动植物检疫局在对外开放的口岸和进出境动植物检疫业务集中的地点设立的口岸动植物检疫机关，依照进出境动植物检疫法和本条例的规定，实施进出境动植物检疫。\n第四条 国(境)外发生重大动植物疫情并可能传入中国时，根据情况采取下列紧急预防措施：\n(一)国务院可以对相关边境区域采取控制措施，必要时下令禁止来自动植物疫区的运输工具进境或者封锁有关口岸；\n(二)国务院农业行政主管部门可以公布禁止从动植物疫情流行的国家和地区进境的动植物、动植物产品和其他检疫物的名录；\n(三)有关口岸动植物检疫机关可以对可能受病虫害污染的本条例第二条所列进境各物采取紧急检疫处理措施；\n(四)受动植物疫情威胁地区的地方人民政府可以立即组织有关部门制定并实施应急方案，同时向上级人民政府和国家动植物检疫局报告。\n邮电、运输部门对重大动植物疫情报告和送检材料应当优先传送。\n第五条 享有外交、领事特权与豁免的外国机构和人员公用或者自用的动植物、动植物产品和其他检疫物进境，应当依照进出境动植物检疫法和本条例的规定实施检疫；口岸动植物检疫机关查验时，应当遵守有关法律的规定。\n第六条 海关依法配合口岸动植物检疫机关，对进出境动植物、动植物产品和其他检疫物实行监管。具体办法由国务院农业行政主管部门会同海关总署制定。\n第七条 进出境动植物检疫法所称动植物疫区和动植物疫情流行的国家与地区的名录，由国务院农业行政主管部门确定并公布。\n第八条 对贯彻执行进出境动植物检疫法和本条例做出显著成绩的单位和个人，给予奖励。","level":1},{"name":"第二章 检疫审批","text":"第九条 输入动物、动物产品和进出境动植物检疫法第五条第一款所列禁止进境物的检疫审批，由国家动植物检疫局或者其授权的口岸动植物检疫机关负责。\n输入植物种子、种苗及其他繁殖材料的检疫审批，由植物检疫条例规定的机关负责。\n第十条 符合下列条件的，方可办理进境检疫审批手续：\n(一)输出国家或者地区无重大动植物疫情；\n(二)符合中国有关动植物检疫法律、法规、规章的规定；\n(三)符合中国与输出国家或者地区签订的有关双边检疫协定(含检疫协议、备忘录等，下同)。\n第十一条 检疫审批手续应当在贸易合同或者协议签订前办妥。\n第十二条 携带、邮寄植物种子、种苗及其他繁殖材料进境的，必须事先提出申请，办理检疫审批手续；因特殊情况无法事先办理的，携带人或者邮寄人应当在口岸补办检疫审批手续，经审批机关同意并经检疫合格后方准进境。\n第十三条 要求运输动物过境的，货主或者其代理人必须事先向国家动植物检疫局提出书面申请，提交输出国家或者地区政府动植物检疫机关出具的疫情证明、输入国家或者地区政府动植物检疫机关出具的准许该动物进境的证件，并说明拟过境的路线，国家动植物检疫局审查同意后，签发《动物过境许可证》。\n第十四条 因科学研究等特殊需要，引进进出境动植物检疫法第五条第一款所列禁止进境物的，办理禁止进境物特许检疫审批手续时，货主、物主或者其代理人必须提交书面申请，说明其数量、用途、引进方式、进境后的防疫措施，并附具有关口岸动植物检疫机关签署的意见。\n第十五条 办理进境检疫审批手续后，有下列情况之一的，货主、物主或者其代理人应当重新申请办理检疫审批手续：\n(一)变更进境物的品种或者数量的；\n(二)变更输出国家或者地区的；\n(三)变更进境口岸的；\n(四)超过检疫审批有效期的。","level":1},{"name":"第三章 进境检疫","text":"第十六条 进出境动植物检疫法第十一条所称中国法定的检疫要求，是指中国的法律、行政法规和国务院农业行政主管部门规定的动植物检疫要求。\n第十七条 国家对向中国输出动植物产品的国外生产、加工、存放单位，实行注册登记制度。具体办法由国务院农业行政主管部门制定。\n第十八条 输入动植物、动植物产品和其他检疫物的，货主或者其代理人应当在进境前或者进境时向进境口岸动植物检疫机关报检。属于调离海关监管区检疫的，运达指定地点时，货主或者其代理人应当通知有关口岸动植物检疫机关。属于转关货物的，货主或者其代理人应当在进境时向进境口岸动植物检疫机关申报；到达指运地时，应当向指运地口岸动植物检疫机关报检。\n输入种畜禽及其精液、胚胎的，应当在进境前30日报检；输入其他动物的，应当在进境前15日报检；输入植物种子、种苗及其他繁殖材料的，应当在进境前7日报检。\n动植物性包装物、铺垫材料进境时，货主或者其代理人应当及时向口岸动植物检疫机关申报；动植物检疫机关可以根据具体情况对申报物实施检疫。\n前款所称动植物性包装物、铺垫材料，是指直接用作包装物、铺垫材料的动物产品和植物、植物产品。\n第十九条 向口岸动植物检疫机关报检时，应当填写报检单，并提交输出国家或者地区政府动植物检疫机关出具的检疫证书、产地证书和贸易合同、信用证、发票等单证；依法应当办理检疫审批手续的，还应当提交检疫审批单。无输出国家或者地区政府动植物检疫机关出具的有效检疫证书，或者未依法办理检疫审批手续的，口岸动植物检疫机关可以根据具体情况，作退回或者销毁处理。\n第二十条 输入的动植物、动植物产品和其他检疫物运达口岸时，检疫人员可以到运输工具上和货物现场实施检疫，核对货、证是否相符，并可以按照规定采取样品。承运人、货主或者其代理人应当向检疫人员提供装载清单和有关资料。\n第二十一条 装载动物的运输工具抵达口岸时，上下运输工具或者接近动物的人员，应当接受口岸动植物检疫机关实施的防疫消毒，并执行其采取的其他现场预防措施。\n第二十二条 检疫人员应当按照下列规定实施现场检疫：\n(一)动物：检查有无疫病的临床症状。发现疑似感染传染病或者已死亡的动物时，在货主或者押运人的配合下查明情况，立即处理。动物的铺垫材料、剩余饲料和排泄物等，由货主或者其代理人在检疫人员的监督下，作除害处理。\n(二)动物产品：检查有无腐败变质现象，容器、包装是否完好。符合要求的，允许卸离运输工具。发现散包、容器破裂的，由货主或者其代理人负责整理完好，方可卸离运输工具。根据情况，对运输工具的有关部位及装载动物产品的容器、外表包装、铺垫材料、被污染场地等进行消毒处理。需要实施实验室检疫的，按照规定采取样品。对易滋生植物害虫或者混藏杂草种子的动物产品，同时实施植物检疫。\n(三)植物、植物产品：检查货物和包装物有无病虫害，并按照规定采取样品。发现病虫害并有扩散可能时，及时对该批货物、运输工具和装卸现场采取必要的防疫措施。对来自动物传染病疫区或者易带动物传染病和寄生虫病病原体并用作动物饲料的植物产品，同时实施动物检疫。\n(四)动植物性包装物、铺垫材料：检查是否携带病虫害、混藏杂草种子、沾带土壤，并按照规定采取样品。\n(五)其他检疫物：检查包装是否完好及是否被病虫害污染。发现破损或者被病虫害污染时，作除害处理。\n第二十三条 对船舶、火车装运的大宗动植物产品，应当就地分层检查；限于港口、车站的存放条件，不能就地检查的，经口岸动植物检疫机关同意，也可以边卸载边疏运，将动植物产品运往指定的地点存放。在卸货过程中经检疫发现疫情时，应当立即停止卸货，由货主或者其代理人按照口岸动植物检疫机关的要求，对已卸和未卸货物作除害处理，并采取防止疫情扩散的措施；对被病虫害污染的装卸工具和场地，也应当作除害处理。\n第二十四条 输入种用大中家畜的，应当在国家动植物检疫局设立的动物隔离检疫场所隔离检疫45日；输入其他动物的，应当在口岸动植物检疫机关指定的动物隔离检疫场所隔离检疫30日。动物隔离检疫场所管理办法，由国务院农业行政主管部门制定。\n第二十五条 进境的同一批动植物产品分港卸货时，口岸动植物检疫机关只对本港卸下的货物进行检疫，先期卸货港的口岸动植物检疫机关应当将检疫及处理情况及时通知其他分卸港的口岸动植物检疫机关；需要对外出证的，由卸毕港的口岸动植物检疫机关汇总后统一出具检疫证书。\n在分卸港实施检疫中发现疫情并必须进行船上熏蒸、消毒时，由该分卸港的口岸动植物检疫机关统一出具检疫证书，并及时通知其他分卸港的口岸动植物检疫机关。\n第二十六条 对输入的动植物、动植物产品和其他检疫物，按照中国的国家标准、行业标准以及国家动植物检疫局的有关规定实施检疫。\n第二十七条 输入动植物、动植物产品和其他检疫物，经检疫合格的，由口岸动植物检疫机关在报关单上加盖印章或者签发《检疫放行通知单》；需要调离进境口岸海关监管区检疫的，由进境口岸动植物检疫机关签发《检疫调离通知单》。货主或者其代理人凭口岸动植物检疫机关在报关单上加盖的印章或者签发的《检疫放行通知单》、《检疫调离通知单》办理报关、运递手续。海关对输入的动植物、动植物产品和其他检疫物，凭口岸动植物检疫机关在报关单上加盖的印章或者签发的《检疫放行通知单》、《检疫调离通知单》验放。运输、邮电部门凭单运递，运递期间国内其他检疫机关不再检疫。\n第二十八条 输入动植物、动植物产品和其他检疫物，经检疫不合格的，由口岸动植物检疫机关签发《检疫处理通知单》，通知货主或者其代理人在口岸动植物检疫机关的监督和技术指导下，作除害处理；需要对外索赔的，由口岸动植物检疫机关出具检疫证书。\n第二十九条 国家动植物检疫局根据检疫需要，并商输出动植物、动植物产品国家或者地区政府有关机关同意，可以派检疫人员进行预检、监装或者产地疫情调查。\n第三十条 海关、边防等部门截获的非法进境的动植物、动植物产品和其他检疫物，应当就近交由口岸动植物检疫机关检疫。","level":1},{"name":"第四章 出境检疫","text":"第三十一条 货主或者其代理人依法办理动植物、动植物产品和其他检疫物的出境报检手续时，应当提供贸易合同或者协议。\n第三十二条 对输入国要求中国对向其输出的动植物、动植物产品和其他检疫物的生产、加工、存放单位注册登记的，口岸动植物检疫机关可以实行注册登记，并报国家动植物检疫局备案。\n第三十三条 输出动物，出境前需经隔离检疫的，在口岸动植物检疫机关指定的隔离场所检疫。输出植物、动植物产品和其他检疫物的，在仓库或者货场实施检疫；根据需要，也可以在生产、加工过程中实施检疫。\n待检出境植物、动植物产品和其他检疫物，应当数量齐全、包装完好、堆放整齐、唛头标记明显。\n第三十四条 输出动植物、动植物产品和其他检疫物的检疫依据：\n(一)输入国家或者地区和中国有关动植物检疫规定；\n(二)双边检疫协定；\n(三)贸易合同中订明的检疫要求。\n第三十五条 经启运地口岸动植物检疫机关检疫合格的动植物、动植物产品和其他检疫物，运达出境口岸时，按照下列规定办理：\n(一)动物应当经出境口岸动植物检疫机关临床检疫或者复检；\n(二)植物、动植物产品和其他检疫物从启运地随原运输工具出境的，由出境口岸动植物检疫机关验证放行；改换运输工具出境的，换证放行；\n(三)植物、动植物产品和其他检疫物到达出境口岸后拼装的，因变更输入国家或者地区而有不同检疫要求的，或者超过规定的检疫有效期的，应当重新报检。\n第三十六条 输出动植物、动植物产品和其他检疫物，经启运地口岸动植物检疫机关检疫合格的，运往出境口岸时，运输、邮电部门凭启运地口岸动植物检疫机关签发的检疫单证运递，国内其他检疫机关不再检疫。","level":1},{"name":"第五章 过境检疫","text":"第三十七条 运输动植物、动植物产品和其他检疫物过境(含转运，下同)的，承运人或者押运人应当持货运单和输出国家或者地区政府动植物检疫机关出具的证书，向进境口岸动植物检疫机关报检；运输动物过境的，还应当同时提交国家动植物检疫局签发的《动物过境许可证》。\n第三十八条 过境动物运达进境口岸时，由进境口岸动植物检疫机关对运输工具、容器的外表进行消毒并对动物进行临床检疫，经检疫合格的，准予过境。进境口岸动植物检疫机关可以派检疫人员监运至出境口岸，出境口岸动植物检疫机关不再检疫。\n第三十九条 装载过境植物、动植物产品和其他检疫物的运输工具和包装物、装载容器必须完好。经口岸动植物检疫机关检查，发现运输工具或者包装物、装载容器有可能造成途中散漏的，承运人或者押运人应当按照口岸动植物检疫机关的要求，采取密封措施；无法采取密封措施的，不准过境。","level":1},{"name":"第六章 携带、邮寄物检疫","text":"第四十条 携带、邮寄植物种子、种苗及其他繁殖材料进境，未依法办理检疫审批手续的，由口岸动植物检疫机关作退回或者销毁处理。邮件作退回处理的，由口岸动植物检疫机关在邮件及发递单上批注退回原因；邮件作销毁处理的，由口岸动植物检疫机关签发通知单，通知寄件人。\n第四十一条 携带动植物、动植物产品和其他检疫物进境的，进境时必须向海关申报并接受口岸动植物检疫机关检疫。海关应当将申报或者查获的动植物、动植物产品和其他检疫物及时交由口岸动植物检疫机关检疫。未经检疫的，不得携带进境。\n第四十二条 口岸动植物检疫机关可以在港口、机场、车站的旅客通道、行李提取处等现场进行检查，对可能携带动植物、动植物产品和其他检疫物而未申报的，可以进行查询并抽检其物品，必要时可以开包(箱)检查。\n旅客进出境检查现场应当设立动植物检疫台位和标志。\n第四十三条 携带动物进境的，必须持有输出动物的国家或者地区政府动植物检疫机关出具的检疫证书，经检疫合格后放行；携带犬、猫等宠物进境的，还必须持有疫苗接种证书。没有检疫证书、疫苗接种证书的，由口岸动植物检疫机关作限期退回或者没收销毁处理。作限期退回处理的，携带人必须在规定的时间内持口岸动植物检疫机关签发的截留凭证，领取并携带出境；逾期不领取的，作自动放弃处理。\n携带植物、动植物产品和其他检疫物进境，经现场检疫合格的，当场放行；需要作实验室检疫或者隔离检疫的，由口岸动植物检疫机关签发截留凭证。截留检疫合格的，携带人持截留凭证向口岸动植物检疫机关领回；逾期不领回的，作自动放弃处理。\n禁止携带、邮寄进出境动植物检疫法第二十九条规定的名录所列动植物、动植物产品和其他检疫物进境。\n第四十四条 邮寄进境的动植物、动植物产品和其他检疫物，由口岸动植物检疫机关在国际邮件互换局(含国际邮件快递公司及其他经营国际邮件的单位，以下简称邮局)实施检疫。邮局应当提供必要的工作条件。\n经现场检疫合格的，由口岸动植物检疫机关加盖检疫放行章，交邮局运递。需要作实验室检疫或者隔离检疫的，口岸动植物检疫机关应当向邮局办理交接手续；检疫合格的，加盖检疫放行章，交邮局运递。\n第四十五条 携带、邮寄进境的动植物、动植物产品和其他检疫物，经检疫不合格又无有效方法作除害处理的，作退回或者销毁处理，并签发《检疫处理通知单》交携带人、寄件人。","level":1},{"name":"第七章 运输工具检疫","text":"第四十六条 口岸动植物检疫机关对来自动植物疫区的船舶、飞机、火车，可以登船、登机、登车实施现场检疫。有关运输工具负责人应当接受检疫人员的询问并在询问记录上签字，提供运行日志和装载货物的情况，开启舱室接受检疫。\n口岸动植物检疫机关应当对前款运输工具可能隐藏病虫害的餐车、配餐间、厨房、储藏室、食品舱等动植物产品存放、使用场所和泔水、动植物性废弃物的存放场所以及集装箱箱体等区域或者部位，实施检疫；必要时，作防疫消毒处理。\n第四十七条 来自动植物疫区的船舶、飞机、火车，经检疫发现有进出境动植物检疫法第十八条规定的名录所列病虫害的，必须作熏蒸、消毒或者其他除害处理。发现有禁止进境的动植物、动植物产品和其他检疫物的，必须作封存或者销毁处理；作封存处理的，在中国境内停留或者运行期间，未经口岸动植物检疫机关许可，不得启封动用。对运输工具上的泔水、动植物性废弃物及其存放场所、容器，应当在口岸动植物检疫机关的监督下作除害处理。\n第四十八条 来自动植物疫区的进境车辆，由口岸动植物检疫机关作防疫消毒处理。装载进境动植物、动植物产品和其他检疫物的车辆，经检疫发现病虫害的，连同货物一并作除害处理。装运供应香港、澳门地区的动物的回空车辆，实施整车防疫消毒。\n第四十九条 进境拆解的废旧船舶，由口岸动植物检疫机关实施检疫。发现病虫害的，在口岸动植物检疫机关监督下作除害处理。发现有禁止进境的动植物、动植物产品和其他检疫物的，在口岸动植物检疫机关的监督下作销毁处理。\n第五十条 来自动植物疫区的进境运输工具经检疫或者经消毒处理合格后，运输工具负责人或者其代理人要求出证的，由口岸动植物检疫机关签发《运输工具检疫证书》或者《运输工具消毒证书》。\n第五十一条 进境、过境运输工具在中国境内停留期间，交通员工和其他人员不得将所装载的动植物、动植物产品和其他检疫物带离运输工具；需要带离时，应当向口岸动植物检疫机关报检。\n第五十二条 装载动物出境的运输工具，装载前应当在口岸动植物检疫机关监督下进行消毒处理。\n装载植物、动植物产品和其他检疫物出境的运输工具，应当符合国家有关动植物防疫和检疫的规定。发现危险性病虫害或者超过规定标准的一般性病虫害的，作除害处理后方可装运。","level":1},{"name":"第八章 检疫监督","text":"第五十三条 国家动植物检疫局和口岸动植物检疫机关对进出境动植物、动植物产品的生产、加工、存放过程，实行检疫监督制度。具体办法由国务院农业行政主管部门制定。\n第五十四条 进出境动物和植物种子、种苗及其他繁殖材料，需要隔离饲养、隔离种植的，在隔离期间，应当接受口岸动植物检疫机关的检疫监督。\n第五十五条 从事进出境动植物检疫熏蒸、消毒处理业务的单位和人员，必须经口岸动植物检疫机关考核合格。\n口岸动植物检疫机关对熏蒸、消毒工作进行监督、指导，并负责出具熏蒸、消毒证书。\n第五十六条 口岸动植物检疫机关可以根据需要，在机场、港口、车站、仓库、加工厂、农场等生产、加工、存放进出境动植物、动植物产品和其他检疫物的场所实施动植物疫情监测，有关单位应当配合。\n未经口岸动植物检疫机关许可，不得移动或者损坏动植物疫情监测器具。\n第五十七条 口岸动植物检疫机关根据需要，可以对运载进出境动植物、动植物产品和其他检疫物的运输工具、装载容器加施动植物检疫封识或者标志；未经口岸动植物检疫机关许可，不得开拆或者损毁检疫封识、标志。\n动植物检疫封识和标志由国家动植物检疫局统一制发。\n第五十八条 进境动植物、动植物产品和其他检疫物，装载动植物、动植物产品和其他检疫物的装载容器、包装物，运往保税区(含保税工厂、保税仓库等)的，在进境口岸依法实施检疫；口岸动植物检疫机关可以根据具体情况实施检疫监督；经加工复运出境的，依照进出境动植物检疫法和本条例有关出境检疫的规定办理。","level":1},{"name":"第九章 法律责任","text":"第五十九条 有下列违法行为之一的，由口岸动植物检疫机关处5000元以下的罚款：\n(一)未报检或者未依法办理检疫审批手续或者未按检疫审批的规定执行的；\n(二)报检的动植物、动植物产品和其他检疫物与实际不符的。\n有前款第(二)项所列行为，已取得检疫单证的，予以吊销。\n第六十条 有下列违法行为之一的，由口岸动植物检疫机关处3000元以上3万元以下的罚款：\n(一)未经口岸动植物检疫机关许可擅自将进境、过境动植物、动植物产品和其他检疫物卸离运输工具或者运递的；\n(二)擅自调离或者处理在口岸动植物检疫机关指定的隔离场所中隔离检疫的动植物的；\n(三)擅自开拆过境动植物、动植物产品和其他检疫物的包装，或者擅自开拆、损毁动植物检疫封识或者标志的；\n(四)擅自抛弃过境动物的尸体、排泄物、铺垫材料或者其他废弃物，或者未按规定处理运输工具上的泔水、动植物性废弃物的。\n第六十一条 依照本条例第十七条、第三十二条的规定注册登记的生产、加工、存放动植物、动植物产品和其他检疫物的单位，进出境的上述物品经检疫不合格的，除依照本条例有关规定作退回、销毁或者除害处理外，情节严重的，由口岸动植物检疫机关注销注册登记。\n第六十二条 有下列违法行为之一的，依法追究刑事责任；尚不构成犯罪或者犯罪情节显著轻微依法不需要判处刑罚的，由口岸动植物检疫机关处2万元以上5万元以下的罚款：\n(一)引起重大动植物疫情的；\n(二)伪造、变造动植物检疫单证、印章、标志、封识的。\n第六十三条 从事进出境动植物检疫熏蒸、消毒处理业务的单位和人员，不按照规定进行熏蒸和消毒处理的，口岸动植物检疫机关可以视情节取消其熏蒸、消毒资格。","level":1},{"name":"第十章 附则","text":"第六十四条 进出境动植物检疫法和本条例下列用语的含义：\n(一)“植物种子、种苗及其他繁殖材料”，是指栽培、野生的可供繁殖的植物全株或者部分，如植株、苗木(含试管苗)、果实、种子、砧木、接穗、插条、叶片、芽体、块根、块茎、鳞茎、球茎、花粉、细胞培养材料等；\n(二)“装载容器”，是指可以多次使用、易受病虫害污染并用于装载进出境货物的容器，如笼、箱、桶、筐等；\n(三)“其他有害生物”，是指动物传染病、寄生虫病和植物危险性病、虫、杂草以外的各种为害动植物的生物有机体、病原微生物，以及软体类、啮齿类、螨类、多足虫类动物和危险性病虫的中间寄主、媒介生物等；\n(四)“检疫证书”，是指动植物检疫机关出具的关于动植物、动植物产品和其他检疫物健康或者卫生状况的具有法律效力的文件，如《动物检疫证书》、《植物检疫证书》、《动物健康证书》、《兽医卫生证书》、《熏蒸/消毒证书》等。\n第六十五条 对进出境动植物、动植物产品和其他检疫物因实施检疫或者按照规定作熏蒸、消毒、退回、销毁等处理所需费用或者招致的损失，由货主、物主或者其代理人承担。\n第六十六条 口岸动植物检疫机关依法实施检疫，需要采取样品时，应当出具采样凭单；验余的样品，货主、物主或者其代理人应当在规定的期限内领回；逾期不领回的，由口岸动植物检疫机关按照规定处理。\n第六十七条 贸易性动物产品出境的检疫机关，由国务院根据情况规定。\n第六十八条 本条例自1997年1月1日起施行。","level":1}]},{"id":"n0321","sections":[{"name":"","text":"中华人民共和国乡村集体所有制企业条例\n(1990年6月3日中华人民共和国国务院令第59号发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了保障乡村集体所有制企业的合法权益，引导其健康发展，制定本条例。\n第二条 本条例适用于由乡(含镇，下同)村(含村民小组，下同)农民集体举办的企业。\n农业生产合作社、农村供销合作社、农村信用社不适用本条例。\n第三条 乡村集体所有制企业是我国社会主义公有制经济的组成部分。\n国家对乡村集体所有制企业实行积极扶持，合理规划，正确引导，加强管理的方针。\n第四条 乡村集体所有制企业的主要任务是：发展商品生产和服务业，满足社会日益增长的物质和文化生活的需要；调整农村产业结构，合理利用农村劳动力；支援农业生产和农村建设，增加国家财政和农民的收入；积极发展出口创汇生产；为大工业配套和服务。\n第五条 国家保护乡村集体所有制企业的合法权益，禁止任何组织和个人侵犯其财产。\n第六条 乡村集体所有制企业实行自主经营，独立核算，自负盈亏。\n乡村集体所有制企业实行多种形式的经营责任制。\n乡村集体所有制企业可以在不改变集体所有制性质的前提下，吸收投资入股。\n第七条 国家鼓励和扶持乡村集体所有制企业采用先进适用的科学技术和经营管理方法，加速企业现代化。\n第八条 国家鼓励和保护乡村集体所有制企业依照平等互利、自愿协商、等价有偿的原则，进行多种形式的经济技术合作。\n第九条 国家鼓励和支持乡村集体所有制企业依法利用自然资源，因地制宜发展符合国家产业政策和市场需要的产业和产品，增加社会有效供给。\n第十条 乡村集体所有制企业经依法审查，具备法人条件的，登记后取得法人资格，厂长(经理)为企业的法定代表人。\n第十一条 乡村集体所有制企业职工有返回其所属的农民集体经济组织从事农业生产的权利。\n第十二条 国务院乡镇企业行政主管部门主管全国乡村集体所有制企业。地方人民政府乡镇企业行政主管部门主管本行政区域内的乡村集体所有制企业(以下简称企业)。","level":1},{"name":"第二章 企业的设立、变更和终止","text":"第十三条 设立企业应当具备下列条件：\n(一)产品和提供的服务为社会所需要，并符合国家法律、法规和政策规定；\n(二)有自己的名称、组织机构和生产经营场所；\n(三)有确定的经营范围；\n(四)有与生产经营和服务规模相适应的资金、设备、从业人员和必要的原材料条件；\n(五)有必要的劳动卫生、安全生产条件和环境保护措施；\n(六)符合当地乡村建设规划，合理利用土地。\n第十四条 设立企业必须依照法律、法规，经乡级人民政府审核后，报请县级人民政府乡镇企业主管部门以及法律、法规规定的有关部门批准，持有关批准文件向企业所在地工商行政管理机关办理登记，经核准领取《企业法人营业执照》或者《营业执照》后始得营业，并向税务机关办理税务登记。\n企业应当在核准登记的经营范围内从事生产经营活动。\n第十五条 企业分立、合并、迁移、停业、终止以及改变名称、经营范围等，须经原批准企业设立的机关核准，向当地工商行政管理机关和税务机关办理变更或者注销登记，并通知开户银行。\n第十六条 企业分立、合并、停业或者终止时，必须保护其财产，依法清理债权、债务。\n第十七条 企业破产应当进行破产清算，法人以企业的财产对企业债权人清偿债务。","level":1},{"name":"第三章 企业的所有者和经营者","text":"第十八条 企业财产属于举办该企业的乡或者村范围内的全体农民集体所有，由乡或者村的农民大会(农民代表会议)或者代表全体农民的集体经济组织行使企业财产的所有权。\n企业实行承包、租赁制或者与其他所有制企业联营的，企业财产的所有权不变。\n第十九条 企业所有者依法决定企业的经营方向、经营形式、厂长(经理)人选或者选聘方式，依法决定企业税后利润在其与企业之间的具体分配比例，有权作出关于企业分立、合并、迁移、停业、终止、申请破产等决议。\n企业所有者应当为企业的生产、供应、销售提供服务，并尊重企业的自主权。\n第二十条 实行承包或者租赁制的企业，企业所有者应当采取公开招标方式确定经营者，不具备条件的，也可以采取招聘、推荐等方式选用经营者。\n招标可以在企业内部或者企业外部进行。投标者可以是经营集团或者个人。经营集团中标后，必须确定企业经营者。\n企业所有者应当对投标者全面评审，择优选定。\n第二十一条 实行承包或者租赁制的企业，企业经营者应当具备下列条件：\n(一)坚持四项基本原则和改革开放，遵纪守法；\n(二)必要的文化知识和专业技术知识；\n(三)必要的企业经营管理能力；\n(四)提供必要的财产担保或者保证人；\n(五)企业所有者提供的其他合法条件。\n第二十二条 企业经营者是企业的厂长(经理)。企业实行厂长(经理)负责制。厂长(经理)对企业全面负责，代表企业行使职权。\n第二十三条 实行承包或者租赁制的企业，订立承包或者租赁合同时，应当坚持平等、自愿、协商的原则，兼顾国家、集体和个人的利益。","level":1},{"name":"第四章 企业的权利和义务","text":"第二十四条 企业在生产经营活动中享有下列权利：\n(一)占有和使用企业资产，依照国家规定筹集资金；\n(二)在核准登记的范围内自主安排生产经营活动；\n(三)确定企业内部机构设置和人员配备；依法招聘、辞退职工，并确定工资形式和奖惩办法；\n(四)有权自行销售本企业的产品，但国务院另有规定的除外；\n(五)有权自行确定本企业的产品价格、劳务价格，但国务院规定由物价部门和有关主管部门控制价格的除外；\n(六)自愿参加行业协会和产品评比；\n(七)依照国家规定自愿参加各种招标、投标活动，申请产品定点生产，取得生产许可证；\n(八)自主订立经济合同，开展经济技术合作；\n(九)依法开发和利用自然资源；\n(十)依法利用外资、引进先进技术和设备，开展进出口贸易等涉外经济活动，并依照国家规定提留企业的外汇收入；\n(十一)拒绝摊派和非法罚款，但法律、法规规定应当提供财力、物力、人力的除外。\n第二十五条 企业在生产经营活动中应当履行下列义务：\n(一)依法缴纳税金；\n(二)依照国家以及省、自治区、直辖市人民政府的规定，上交支农资金和管理费；\n(三)依法建立健全财务会计、审计、统计等制度，按期编报财务、统计报表；\n(四)保护自然资源和环境，防止和治理污染；\n(五)努力降低原材料和能源消耗，发展符合国家产业政策的产品；\n(六)做好劳动保护工作，实行安全生产；\n(七)保证产品质量和服务质量；\n(八)依法履行合同；\n(九)对职工进行政治思想、科学文化、技术业务和职业道德等方面的教育；\n(十)遵守法律、法规和政策的其他规定。","level":1},{"name":"第五章 企业的管理","text":"第二十六条 企业职工有参加企业民主管理，对厂长(经理)和其他管理人员提出批评和控告的权利。\n企业职工大会或者职工代表大会有权对企业经营管理中的问题提出意见和建议，评议、监督厂长(经理)和其他管理人员，维护职工的合法权益。\n第二十七条 企业应当兼顾国家、集体和个人的利益，合理安排积累与消费的比例，对职工实行各尽所能、按劳分配的原则。\n男工与女工应当同工同酬。\n第二十八条 企业招用职工应当依法签订劳动合同，实行灵活的用工形式和办法。\n对技术要求高的企业，应当逐步形成专业化的技术职工队伍。\n第二十九条 企业不得招用未满16周岁的童工。\n第三十条 企业对从事高度危险作业的职工，必须依照国家规定向保险公司投保。\n有条件的企业，应当参照国家有关规定实行职工社会保险。\n第三十一条 企业发生劳动争议，可以依照《中华人民共和国劳动争议调解仲裁法》处理。\n第三十二条 企业税后利润，留给企业的部分不应低于60%，由企业自主安排，主要用作增加生产发展基金，进行技术改造和扩大再生产，适当增加福利基金和奖励基金。\n企业税后利润交给企业所有者的部分，主要用于扶持农业基本建设、农业技术服务、农村公益事业、企业更新改造或者发展新企业。\n第三十三条 企业应当根据国家有关规定，加强本企业的各项基础管理和合同管理。","level":1},{"name":"第六章 企业与政府有关部门的关系","text":"第三十四条 各级人民政府乡镇企业行政主管部门根据国家的法律、法规和政策，加强对企业的指导、管理、监督、协调和服务：\n(一)监督检查企业执行国家法律、法规和政策；\n(二)制订企业发展规划，协同有关部门制定农村剩余劳动力就业规划；\n(三)会同有关部门指导企业的计划、统计、财务、审计、价格、物资、质量、设备、技术、劳动、安全生产、环境保护等管理工作；\n(四)组织和指导企业的技术进步、职工教育和培训；\n(五)向企业提供经济、技术咨询和信息服务；\n(六)协调企业与有关方面的关系，帮助企业开展经济技术合作；\n(七)总结推广企业发展的经验；\n(八)组织和指导企业的思想政治工作，促进企业的社会主义精神文明建设。\n第三十五条 各级人民政府有关行业管理部门应当根据国家的产业政策和行业发展规划，对企业的发展方向进行指导和监督；对企业开展技术指导、人才培训和经济、技术信息服务；指导、帮助和监督企业开展劳动保护、环境保护等工作。\n第三十六条 政府有关部门应当为符合国家产业政策，经济和社会效益好的企业创造发展条件：\n(一)对企业所需的能源、原材料、资金等，计划、物资、金融等部门应当积极帮助解决；生产纳入国家指令性计划的产品所需的能源、原材料等，由安排生产任务的部门和单位组织供应；(2011年1月8日删除)\n(二)根据国家有关规定，对生产名、优产品和出口创汇产品的企业，应当在信贷、能源、原材料和运输等方面给予扶持；\n(三)为企业培训、招用专业技术人才和引进先进技术创造条件。","level":1},{"name":"第七章 奖励与处罚","text":"第三十七条 对在企业经营管理、科技进步、劳动保护、环境保护和思想政治工作等方面作出显著成绩的企业和个人，由人民政府给予奖励。\n第三十八条 企业产品质量达不到国家规定标准的，企业所有者和企业主管部门应当责令其限期整顿，经整顿无效者，应当责令其停产或者转产，直至建议有关机关撤销生产许可证，吊销营业执照。\n企业因生产、销售前款所指的产品，给用户和消费者造成财产损失、人身损害的，应当承担赔偿责任；构成犯罪的，依法追究刑事责任。\n第三十九条 企业厂长(经理)侵犯职工合法权益，情节严重的，由企业所有者给予行政处分；构成犯罪的，依法追究刑事责任。\n第四十条 对向企业摊派的单位和个人，企业可以向审计机关或者其他有关部门控告、检举。经审计机关确认是摊派行为的，由审计机关通知摊派单位停止摊派行为，限期退回摊派财物；对摊派单位的负责人和直接责任人员，监察机关或者有关主管部门可以根据情节轻重，给予行政处分。\n第四十一条 政府部门的工作人员玩忽职守、滥用职权，使企业合法权益遭受损害的，由其所在单位或者上级主管机关给予行政处分；构成犯罪的，依法追究刑事责任。\n第四十二条 企业违反财政、税收、劳动、工商行政、价格、资源、环境保护等法律、法规的，依照有关法律、法规处理。","level":1},{"name":"第八章 附则","text":"第四十三条 本条例由国务院乡镇企业行政主管部门负责解释，并组织实施。\n第四十四条 省、自治区、直辖市人民政府可以根据本条例制定实施办法。\n第四十五条 本条例自1990年7月1日起施行。","level":1}]},{"id":"n0322","sections":[{"name":"","text":"危险化学品安全管理条例\n(2002年1月26日中华人民共和国国务院令第344号公布 2011年2月16日国务院第144次常务会议修订通过 根据2013年12月7日《国务院关于修改部分行政法规的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强危险化学品的安全管理，预防和减少危险化学品事故，保障人民群众生命财产安全，保护环境，制定本条例。\n第二条 危险化学品生产、储存、使用、经营和运输的安全管理，适用本条例。\n废弃危险化学品的处置，依照有关环境保护的法律、行政法规和国家有关规定执行。\n第三条 本条例所称危险化学品，是指具有毒害、腐蚀、爆炸、燃烧、助燃等性质，对人体、设施、环境具有危害的剧毒化学品和其他化学品。\n危险化学品目录，由国务院安全生产监督管理部门会同国务院工业和信息化、公安、环境保护、卫生、质量监督检验检疫、交通运输、铁路、民用航空、农业主管部门，根据化学品危险特性的鉴别和分类标准确定、公布，并适时调整。\n第四条 危险化学品安全管理，应当坚持安全第一、预防为主、综合治理的方针，强化和落实企业的主体责任。\n生产、储存、使用、经营、运输危险化学品的单位(以下统称危险化学品单位)的主要负责人对本单位的危险化学品安全管理工作全面负责。\n危险化学品单位应当具备法律、行政法规规定和国家标准、行业标准要求的安全条件，建立、健全安全管理规章制度和岗位安全责任制度，对从业人员进行安全教育、法制教育和岗位技术培训。从业人员应当接受教育和培训，考核合格后上岗作业；对有资格要求的岗位，应当配备依法取得相应资格的人员。\n第五条 任何单位和个人不得生产、经营、使用国家禁止生产、经营、使用的危险化学品。\n国家对危险化学品的使用有限制性规定的，任何单位和个人不得违反限制性规定使用危险化学品。\n第六条 对危险化学品的生产、储存、使用、经营、运输实施安全监督管理的有关部门(以下统称负有危险化学品安全监督管理职责的部门)，依照下列规定履行职责：\n(一)安全生产监督管理部门负责危险化学品安全监督管理综合工作，组织确定、公布、调整危险化学品目录，对新建、改建、扩建生产、储存危险化学品(包括使用长输管道输送危险化学品，下同)的建设项目进行安全条件审查，核发危险化学品安全生产许可证、危险化学品安全使用许可证和危险化学品经营许可证，并负责危险化学品登记工作。\n(二)公安机关负责危险化学品的公共安全管理，核发剧毒化学品购买许可证、剧毒化学品道路运输通行证，并负责危险化学品运输车辆的道路交通安全管理。\n(三)质量监督检验检疫部门负责核发危险化学品及其包装物、容器(不包括储存危险化学品的固定式大型储罐，下同)生产企业的工业产品生产许可证，并依法对其产品质量实施监督，负责对进出口危险化学品及其包装实施检验。\n(四)环境保护主管部门负责废弃危险化学品处置的监督管理，组织危险化学品的环境危害性鉴定和环境风险程度评估，确定实施重点环境管理的危险化学品，负责危险化学品环境管理登记和新化学物质环境管理登记；依照职责分工调查相关危险化学品环境污染事故和生态破坏事件，负责危险化学品事故现场的应急环境监测。\n(五)交通运输主管部门负责危险化学品道路运输、水路运输的许可以及运输工具的安全管理，对危险化学品水路运输安全实施监督，负责危险化学品道路运输企业、水路运输企业驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员的资格认定。铁路监管部门负责危险化学品铁路运输及其运输工具的安全管理。民用航空主管部门负责危险化学品航空运输以及航空运输企业及其运输工具的安全管理。\n(六)卫生主管部门负责危险化学品毒性鉴定的管理，负责组织、协调危险化学品事故受伤人员的医疗卫生救援工作。\n(七)工商行政管理部门依据有关部门的许可证件，核发危险化学品生产、储存、经营、运输企业营业执照，查处危险化学品经营企业违法采购危险化学品的行为。\n(八)邮政管理部门负责依法查处寄递危险化学品的行为。\n第七条 负有危险化学品安全监督管理职责的部门依法进行监督检查，可以采取下列措施：\n(一)进入危险化学品作业场所实施现场检查，向有关单位和人员了解情况，查阅、复制有关文件、资料；\n(二)发现危险化学品事故隐患，责令立即消除或者限期消除；\n(三)对不符合法律、行政法规、规章规定或者国家标准、行业标准要求的设施、设备、装置、器材、运输工具，责令立即停止使用；\n(四)经本部门主要负责人批准，查封违法生产、储存、使用、经营危险化学品的场所，扣押违法生产、储存、使用、经营、运输的危险化学品以及用于违法生产、使用、运输危险化学品的原材料、设备、运输工具；\n(五)发现影响危险化学品安全的违法行为，当场予以纠正或者责令限期改正。\n负有危险化学品安全监督管理职责的部门依法进行监督检查，监督检查人员不得少于2人，并应当出示执法证件；有关单位和个人对依法进行的监督检查应当予以配合，不得拒绝、阻碍。\n第八条 县级以上人民政府应当建立危险化学品安全监督管理工作协调机制，支持、督促负有危险化学品安全监督管理职责的部门依法履行职责，协调、解决危险化学品安全监督管理工作中的重大问题。\n负有危险化学品安全监督管理职责的部门应当相互配合、密切协作，依法加强对危险化学品的安全监督管理。\n第九条 任何单位和个人对违反本条例规定的行为，有权向负有危险化学品安全监督管理职责的部门举报。负有危险化学品安全监督管理职责的部门接到举报，应当及时依法处理；对不属于本部门职责的，应当及时移送有关部门处理。\n第十条 国家鼓励危险化学品生产企业和使用危险化学品从事生产的企业采用有利于提高安全保障水平的先进技术、工艺、设备以及自动控制系统，鼓励对危险化学品实行专门储存、统一配送、集中销售。","level":1},{"name":"第二章 生产、储存安全","text":"第十一条 国家对危险化学品的生产、储存实行统筹规划、合理布局。\n国务院工业和信息化主管部门以及国务院其他有关部门依据各自职责，负责危险化学品生产、储存的行业规划和布局。\n地方人民政府组织编制城乡规划，应当根据本地区的实际情况，按照确保安全的原则，规划适当区域专门用于危险化学品的生产、储存。\n第十二条 新建、改建、扩建生产、储存危险化学品的建设项目(以下简称建设项目)，应当由安全生产监督管理部门进行安全条件审查。\n建设单位应当对建设项目进行安全条件论证，委托具备国家规定的资质条件的机构对建设项目进行安全评价，并将安全条件论证和安全评价的情况报告报建设项目所在地设区的市级以上人民政府安全生产监督管理部门；安全生产监督管理部门应当自收到报告之日起45日内作出审查决定，并书面通知建设单位。具体办法由国务院安全生产监督管理部门制定。\n新建、改建、扩建储存、装卸危险化学品的港口建设项目，由港口行政管理部门按照国务院交通运输主管部门的规定进行安全条件审查。\n第十三条 生产、储存危险化学品的单位，应当对其铺设的危险化学品管道设置明显标志，并对危险化学品管道定期检查、检测。\n进行可能危及危险化学品管道安全的施工作业，施工单位应当在开工的7日前书面通知管道所属单位，并与管道所属单位共同制定应急预案，采取相应的安全防护措施。管道所属单位应当指派专门人员到现场进行管道安全保护指导。\n第十四条 危险化学品生产企业进行生产前，应当依照《安全生产许可证条例》的规定，取得危险化学品安全生产许可证。\n生产列入国家实行生产许可证制度的工业产品目录的危险化学品的企业，应当依照《中华人民共和国工业产品生产许可证管理条例》的规定，取得工业产品生产许可证。\n负责颁发危险化学品安全生产许可证、工业产品生产许可证的部门，应当将其颁发许可证的情况及时向同级工业和信息化主管部门、环境保护主管部门和公安机关通报。\n第十五条 危险化学品生产企业应当提供与其生产的危险化学品相符的化学品安全技术说明书，并在危险化学品包装(包括外包装件)上粘贴或者拴挂与包装内危险化学品相符的化学品安全标签。化学品安全技术说明书和化学品安全标签所载明的内容应当符合国家标准的要求。\n危险化学品生产企业发现其生产的危险化学品有新的危险特性的，应当立即公告，并及时修订其化学品安全技术说明书和化学品安全标签。\n第十六条 生产实施重点环境管理的危险化学品的企业，应当按照国务院环境保护主管部门的规定，将该危险化学品向环境中释放等相关信息向环境保护主管部门报告。环境保护主管部门可以根据情况采取相应的环境风险控制措施。\n第十七条 危险化学品的包装应当符合法律、行政法规、规章的规定以及国家标准、行业标准的要求。\n危险化学品包装物、容器的材质以及危险化学品包装的型式、规格、方法和单件质量(重量)，应当与所包装的危险化学品的性质和用途相适应。\n第十八条 生产列入国家实行生产许可证制度的工业产品目录的危险化学品包装物、容器的企业，应当依照《中华人民共和国工业产品生产许可证管理条例》的规定，取得工业产品生产许可证；其生产的危险化学品包装物、容器经国务院质量监督检验检疫部门认定的检验机构检验合格，方可出厂销售。\n运输危险化学品的船舶及其配载的容器，应当按照国家船舶检验规范进行生产，并经海事管理机构认定的船舶检验机构检验合格，方可投入使用。\n对重复使用的危险化学品包装物、容器，使用单位在重复使用前应当进行检查；发现存在安全隐患的，应当维修或者更换。使用单位应当对检查情况作出记录，记录的保存期限不得少于2年。\n第十九条 危险化学品生产装置或者储存数量构成重大危险源的危险化学品储存设施(运输工具加油站、加气站除外)，与下列场所、设施、区域的距离应当符合国家有关规定：\n(一)居住区以及商业中心、公园等人员密集场所；\n(二)学校、医院、影剧院、体育场(馆)等公共设施；\n(三)饮用水源、水厂以及水源保护区；\n(四)车站、码头(依法经许可从事危险化学品装卸作业的除外)、机场以及通信干线、通信枢纽、铁路线路、道路交通干线、水路交通干线、地铁风亭以及地铁站出入口；\n(五)基本农田保护区、基本草原、畜禽遗传资源保护区、畜禽规模化养殖场(养殖小区)、渔业水域以及种子、种畜禽、水产苗种生产基地；\n(六)河流、湖泊、风景名胜区、自然保护区；\n(七)军事禁区、军事管理区；\n(八)法律、行政法规规定的其他场所、设施、区域。\n已建的危险化学品生产装置或者储存数量构成重大危险源的危险化学品储存设施不符合前款规定的，由所在地设区的市级人民政府安全生产监督管理部门会同有关部门监督其所属单位在规定期限内进行整改；需要转产、停产、搬迁、关闭的，由本级人民政府决定并组织实施。\n储存数量构成重大危险源的危险化学品储存设施的选址，应当避开地震活动断层和容易发生洪灾、地质灾害的区域。\n本条例所称重大危险源，是指生产、储存、使用或者搬运危险化学品，且危险化学品的数量等于或者超过临界量的单元(包括场所和设施)。\n第二十条 生产、储存危险化学品的单位，应当根据其生产、储存的危险化学品的种类和危险特性，在作业场所设置相应的监测、监控、通风、防晒、调温、防火、灭火、防爆、泄压、防毒、中和、防潮、防雷、防静电、防腐、防泄漏以及防护围堤或者隔离操作等安全设施、设备，并按照国家标准、行业标准或者国家有关规定对安全设施、设备进行经常性维护、保养，保证安全设施、设备的正常使用。\n生产、储存危险化学品的单位，应当在其作业场所和安全设施、设备上设置明显的安全警示标志。\n第二十一条 生产、储存危险化学品的单位，应当在其作业场所设置通信、报警装置，并保证处于适用状态。\n第二十二条 生产、储存危险化学品的企业，应当委托具备国家规定的资质条件的机构，对本企业的安全生产条件每3年进行一次安全评价，提出安全评价报告。安全评价报告的内容应当包括对安全生产条件存在的问题进行整改的方案。\n生产、储存危险化学品的企业，应当将安全评价报告以及整改方案的落实情况报所在地县级人民政府安全生产监督管理部门备案。在港区内储存危险化学品的企业，应当将安全评价报告以及整改方案的落实情况报港口行政管理部门备案。\n第二十三条 生产、储存剧毒化学品或者国务院公安部门规定的可用于制造爆炸物品的危险化学品(以下简称易制爆危险化学品)的单位，应当如实记录其生产、储存的剧毒化学品、易制爆危险化学品的数量、流向，并采取必要的安全防范措施，防止剧毒化学品、易制爆危险化学品丢失或者被盗；发现剧毒化学品、易制爆危险化学品丢失或者被盗的，应当立即向当地公安机关报告。\n生产、储存剧毒化学品、易制爆危险化学品的单位，应当设置治安保卫机构，配备专职治安保卫人员。\n第二十四条 危险化学品应当储存在专用仓库、专用场地或者专用储存室(以下统称专用仓库)内，并由专人负责管理；剧毒化学品以及储存数量构成重大危险源的其他危险化学品，应当在专用仓库内单独存放，并实行双人收发、双人保管制度。\n危险化学品的储存方式、方法以及储存数量应当符合国家标准或者国家有关规定。\n第二十五条 储存危险化学品的单位应当建立危险化学品出入库核查、登记制度。\n对剧毒化学品以及储存数量构成重大危险源的其他危险化学品，储存单位应当将其储存数量、储存地点以及管理人员的情况，报所在地县级人民政府安全生产监督管理部门(在港区内储存的，报港口行政管理部门)和公安机关备案。\n第二十六条 危险化学品专用仓库应当符合国家标准、行业标准的要求，并设置明显的标志。储存剧毒化学品、易制爆危险化学品的专用仓库，应当按照国家有关规定设置相应的技术防范设施。\n储存危险化学品的单位应当对其危险化学品专用仓库的安全设施、设备定期进行检测、检验。\n第二十七条 生产、储存危险化学品的单位转产、停产、停业或者解散的，应当采取有效措施，及时、妥善处置其危险化学品生产装置、储存设施以及库存的危险化学品，不得丢弃危险化学品；处置方案应当报所在地县级人民政府安全生产监督管理部门、工业和信息化主管部门、环境保护主管部门和公安机关备案。安全生产监督管理部门应当会同环境保护主管部门和公安机关对处置情况进行监督检查，发现未依照规定处置的，应当责令其立即处置。","level":1},{"name":"第三章 使用安全","text":"第二十八条 使用危险化学品的单位，其使用条件(包括工艺)应当符合法律、行政法规的规定和国家标准、行业标准的要求，并根据所使用的危险化学品的种类、危险特性以及使用量和使用方式，建立、健全使用危险化学品的安全管理规章制度和安全操作规程，保证危险化学品的安全使用。\n第二十九条 使用危险化学品从事生产并且使用量达到规定数量的化工企业(属于危险化学品生产企业的除外，下同)，应当依照本条例的规定取得危险化学品安全使用许可证。\n前款规定的危险化学品使用量的数量标准，由国务院安全生产监督管理部门会同国务院公安部门、农业主管部门确定并公布。\n第三十条 申请危险化学品安全使用许可证的化工企业，除应当符合本条例第二十八条的规定外，还应当具备下列条件：\n(一)有与所使用的危险化学品相适应的专业技术人员；\n(二)有安全管理机构和专职安全管理人员；\n(三)有符合国家规定的危险化学品事故应急预案和必要的应急救援器材、设备；\n(四)依法进行了安全评价。\n第三十一条 申请危险化学品安全使用许可证的化工企业，应当向所在地设区的市级人民政府安全生产监督管理部门提出申请，并提交其符合本条例第三十条规定条件的证明材料。设区的市级人民政府安全生产监督管理部门应当依法进行审查，自收到证明材料之日起45日内作出批准或者不予批准的决定。予以批准的，颁发危险化学品安全使用许可证；不予批准的，书面通知申请人并说明理由。\n安全生产监督管理部门应当将其颁发危险化学品安全使用许可证的情况及时向同级环境保护主管部门和公安机关通报。\n第三十二条 本条例第十六条关于生产实施重点环境管理的危险化学品的企业的规定，适用于使用实施重点环境管理的危险化学品从事生产的企业；第二十条、第二十一条、第二十三条第一款、第二十七条关于生产、储存危险化学品的单位的规定，适用于使用危险化学品的单位；第二十二条关于生产、储存危险化学品的企业的规定，适用于使用危险化学品从事生产的企业。","level":1},{"name":"第四章 经营安全","text":"第三十三条 国家对危险化学品经营(包括仓储经营，下同)实行许可制度。未经许可，任何单位和个人不得经营危险化学品。\n依法设立的危险化学品生产企业在其厂区范围内销售本企业生产的危险化学品，不需要取得危险化学品经营许可。\n依照《中华人民共和国港口法》的规定取得港口经营许可证的港口经营人，在港区内从事危险化学品仓储经营，不需要取得危险化学品经营许可。\n第三十四条 从事危险化学品经营的企业应当具备下列条件：\n(一)有符合国家标准、行业标准的经营场所，储存危险化学品的，还应当有符合国家标准、行业标准的储存设施；\n(二)从业人员经过专业技术培训并经考核合格；\n(三)有健全的安全管理规章制度；\n(四)有专职安全管理人员；\n(五)有符合国家规定的危险化学品事故应急预案和必要的应急救援器材、设备；\n(六)法律、法规规定的其他条件。\n第三十五条 从事剧毒化学品、易制爆危险化学品经营的企业，应当向所在地设区的市级人民政府安全生产监督管理部门提出申请，从事其他危险化学品经营的企业，应当向所在地县级人民政府安全生产监督管理部门提出申请(有储存设施的，应当向所在地设区的市级人民政府安全生产监督管理部门提出申请)。申请人应当提交其符合本条例第三十四条规定条件的证明材料。设区的市级人民政府安全生产监督管理部门或者县级人民政府安全生产监督管理部门应当依法进行审查，并对申请人的经营场所、储存设施进行现场核查，自收到证明材料之日起30日内作出批准或者不予批准的决定。予以批准的，颁发危险化学品经营许可证；不予批准的，书面通知申请人并说明理由。\n设区的市级人民政府安全生产监督管理部门和县级人民政府安全生产监督管理部门应当将其颁发危险化学品经营许可证的情况及时向同级环境保护主管部门和公安机关通报。\n申请人持危险化学品经营许可证向工商行政管理部门办理登记手续后，方可从事危险化学品经营活动。法律、行政法规或者国务院规定经营危险化学品还需要经其他有关部门许可的，申请人向工商行政管理部门办理登记手续时还应当持相应的许可证件。\n第三十六条 危险化学品经营企业储存危险化学品的，应当遵守本条例第二章关于储存危险化学品的规定。危险化学品商店内只能存放民用小包装的危险化学品。\n第三十七条 危险化学品经营企业不得向未经许可从事危险化学品生产、经营活动的企业采购危险化学品，不得经营没有化学品安全技术说明书或者化学品安全标签的危险化学品。\n第三十八条 依法取得危险化学品安全生产许可证、危险化学品安全使用许可证、危险化学品经营许可证的企业，凭相应的许可证件购买剧毒化学品、易制爆危险化学品。民用爆炸物品生产企业凭民用爆炸物品生产许可证购买易制爆危险化学品。\n前款规定以外的单位购买剧毒化学品的，应当向所在地县级人民政府公安机关申请取得剧毒化学品购买许可证；购买易制爆危险化学品的，应当持本单位出具的合法用途说明。\n个人不得购买剧毒化学品(属于剧毒化学品的农药除外)和易制爆危险化学品。\n第三十九条 申请取得剧毒化学品购买许可证，申请人应当向所在地县级人民政府公安机关提交下列材料：\n(一)营业执照或者法人证书(登记证书)的复印件；\n(二)拟购买的剧毒化学品品种、数量的说明；\n(三)购买剧毒化学品用途的说明；\n(四)经办人的身份证明。\n县级人民政府公安机关应当自收到前款规定的材料之日起3日内，作出批准或者不予批准的决定。予以批准的，颁发剧毒化学品购买许可证；不予批准的，书面通知申请人并说明理由。\n剧毒化学品购买许可证管理办法由国务院公安部门制定。\n第四十条 危险化学品生产企业、经营企业销售剧毒化学品、易制爆危险化学品，应当查验本条例第三十八条第一款、第二款规定的相关许可证件或者证明文件，不得向不具有相关许可证件或者证明文件的单位销售剧毒化学品、易制爆危险化学品。对持剧毒化学品购买许可证购买剧毒化学品的，应当按照许可证载明的品种、数量销售。\n禁止向个人销售剧毒化学品(属于剧毒化学品的农药除外)和易制爆危险化学品。\n第四十一条 危险化学品生产企业、经营企业销售剧毒化学品、易制爆危险化学品，应当如实记录购买单位的名称、地址、经办人的姓名、身份证号码以及所购买的剧毒化学品、易制爆危险化学品的品种、数量、用途。销售记录以及经办人的身份证明复印件、相关许可证件复印件或者证明文件的保存期限不得少于1年。\n剧毒化学品、易制爆危险化学品的销售企业、购买单位应当在销售、购买后5日内，将所销售、购买的剧毒化学品、易制爆危险化学品的品种、数量以及流向信息报所在地县级人民政府公安机关备案，并输入计算机系统。\n第四十二条 使用剧毒化学品、易制爆危险化学品的单位不得出借、转让其购买的剧毒化学品、易制爆危险化学品；因转产、停产、搬迁、关闭等确需转让的，应当向具有本条例第三十八条第一款、第二款规定的相关许可证件或者证明文件的单位转让，并在转让后将有关情况及时向所在地县级人民政府公安机关报告。","level":1},{"name":"第五章 运输安全","text":"第四十三条 从事危险化学品道路运输、水路运输的，应当分别依照有关道路运输、水路运输的法律、行政法规的规定，取得危险货物道路运输许可、危险货物水路运输许可，并向工商行政管理部门办理登记手续。\n危险化学品道路运输企业、水路运输企业应当配备专职安全管理人员。\n第四十四条 危险化学品道路运输企业、水路运输企业的驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员应当经交通运输主管部门考核合格，取得从业资格。具体办法由国务院交通运输主管部门制定。\n危险化学品的装卸作业应当遵守安全作业标准、规程和制度，并在装卸管理人员的现场指挥或者监控下进行。水路运输危险化学品的集装箱装箱作业应当在集装箱装箱现场检查员的指挥或者监控下进行，并符合积载、隔离的规范和要求；装箱作业完毕后，集装箱装箱现场检查员应当签署装箱证明书。\n第四十五条 运输危险化学品，应当根据危险化学品的危险特性采取相应的安全防护措施，并配备必要的防护用品和应急救援器材。\n用于运输危险化学品的槽罐以及其他容器应当封口严密，能够防止危险化学品在运输过程中因温度、湿度或者压力的变化发生渗漏、洒漏；槽罐以及其他容器的溢流和泄压装置应当设置准确、起闭灵活。\n运输危险化学品的驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员，应当了解所运输的危险化学品的危险特性及其包装物、容器的使用要求和出现危险情况时的应急处置方法。\n第四十六条 通过道路运输危险化学品的，托运人应当委托依法取得危险货物道路运输许可的企业承运。\n第四十七条 通过道路运输危险化学品的，应当按照运输车辆的核定载质量装载危险化学品，不得超载。\n危险化学品运输车辆应当符合国家标准要求的安全技术条件，并按照国家有关规定定期进行安全技术检验。\n危险化学品运输车辆应当悬挂或者喷涂符合国家标准要求的警示标志。\n第四十八条 通过道路运输危险化学品的，应当配备押运人员，并保证所运输的危险化学品处于押运人员的监控之下。\n运输危险化学品途中因住宿或者发生影响正常运输的情况，需要较长时间停车的，驾驶人员、押运人员应当采取相应的安全防范措施；运输剧毒化学品或者易制爆危险化学品的，还应当向当地公安机关报告。\n第四十九条 未经公安机关批准，运输危险化学品的车辆不得进入危险化学品运输车辆限制通行的区域。危险化学品运输车辆限制通行的区域由县级人民政府公安机关划定，并设置明显的标志。\n第五十条 通过道路运输剧毒化学品的，托运人应当向运输始发地或者目的地县级人民政府公安机关申请剧毒化学品道路运输通行证。\n申请剧毒化学品道路运输通行证，托运人应当向县级人民政府公安机关提交下列材料：\n(一)拟运输的剧毒化学品品种、数量的说明；\n(二)运输始发地、目的地、运输时间和运输路线的说明；\n(三)承运人取得危险货物道路运输许可、运输车辆取得营运证以及驾驶人员、押运人员取得上岗资格的证明文件；\n(四)本条例第三十八条第一款、第二款规定的购买剧毒化学品的相关许可证件，或者海关出具的进出口证明文件。\n县级人民政府公安机关应当自收到前款规定的材料之日起7日内，作出批准或者不予批准的决定。予以批准的，颁发剧毒化学品道路运输通行证；不予批准的，书面通知申请人并说明理由。\n剧毒化学品道路运输通行证管理办法由国务院公安部门制定。\n第五十一条 剧毒化学品、易制爆危险化学品在道路运输途中丢失、被盗、被抢或者出现流散、泄漏等情况的，驾驶人员、押运人员应当立即采取相应的警示措施和安全措施，并向当地公安机关报告。公安机关接到报告后，应当根据实际情况立即向安全生产监督管理部门、环境保护主管部门、卫生主管部门通报。有关部门应当采取必要的应急处置措施。\n第五十二条 通过水路运输危险化学品的，应当遵守法律、行政法规以及国务院交通运输主管部门关于危险货物水路运输安全的规定。\n第五十三条 海事管理机构应当根据危险化学品的种类和危险特性，确定船舶运输危险化学品的相关安全运输条件。\n拟交付船舶运输的化学品的相关安全运输条件不明确的，货物所有人或者代理人应当委托相关技术机构进行评估，明确相关安全运输条件并经海事管理机构确认后，方可交付船舶运输。\n第五十四条 禁止通过内河封闭水域运输剧毒化学品以及国家规定禁止通过内河运输的其他危险化学品。\n前款规定以外的内河水域，禁止运输国家规定禁止通过内河运输的剧毒化学品以及其他危险化学品。\n禁止通过内河运输的剧毒化学品以及其他危险化学品的范围，由国务院交通运输主管部门会同国务院环境保护主管部门、工业和信息化主管部门、安全生产监督管理部门，根据危险化学品的危险特性、危险化学品对人体和水环境的危害程度以及消除危害后果的难易程度等因素规定并公布。\n第五十五条 国务院交通运输主管部门应当根据危险化学品的危险特性，对通过内河运输本条例第五十四条规定以外的危险化学品(以下简称通过内河运输危险化学品)实行分类管理，对各类危险化学品的运输方式、包装规范和安全防护措施等分别作出规定并监督实施。\n第五十六条 通过内河运输危险化学品，应当由依法取得危险货物水路运输许可的水路运输企业承运，其他单位和个人不得承运。托运人应当委托依法取得危险货物水路运输许可的水路运输企业承运，不得委托其他单位和个人承运。\n第五十七条 通过内河运输危险化学品，应当使用依法取得危险货物适装证书的运输船舶。水路运输企业应当针对所运输的危险化学品的危险特性，制定运输船舶危险化学品事故应急救援预案，并为运输船舶配备充足、有效的应急救援器材和设备。\n通过内河运输危险化学品的船舶，其所有人或者经营人应当取得船舶污染损害责任保险证书或者财务担保证明。船舶污染损害责任保险证书或者财务担保证明的副本应当随船携带。\n第五十八条 通过内河运输危险化学品，危险化学品包装物的材质、型式、强度以及包装方法应当符合水路运输危险化学品包装规范的要求。国务院交通运输主管部门对单船运输的危险化学品数量有限制性规定的，承运人应当按照规定安排运输数量。\n第五十九条 用于危险化学品运输作业的内河码头、泊位应当符合国家有关安全规范，与饮用水取水口保持国家规定的距离。有关管理单位应当制定码头、泊位危险化学品事故应急预案，并为码头、泊位配备充足、有效的应急救援器材和设备。\n用于危险化学品运输作业的内河码头、泊位，经交通运输主管部门按照国家有关规定验收合格后方可投入使用。\n第六十条 船舶载运危险化学品进出内河港口，应当将危险化学品的名称、危险特性、包装以及进出港时间等事项，事先报告海事管理机构。海事管理机构接到报告后，应当在国务院交通运输主管部门规定的时间内作出是否同意的决定，通知报告人，同时通报港口行政管理部门。定船舶、定航线、定货种的船舶可以定期报告。\n在内河港口内进行危险化学品的装卸、过驳作业，应当将危险化学品的名称、危险特性、包装和作业的时间、地点等事项报告港口行政管理部门。港口行政管理部门接到报告后，应当在国务院交通运输主管部门规定的时间内作出是否同意的决定，通知报告人，同时通报海事管理机构。\n载运危险化学品的船舶在内河航行，通过过船建筑物的，应当提前向交通运输主管部门申报，并接受交通运输主管部门的管理。\n第六十一条 载运危险化学品的船舶在内河航行、装卸或者停泊，应当悬挂专用的警示标志，按照规定显示专用信号。\n载运危险化学品的船舶在内河航行，按照国务院交通运输主管部门的规定需要引航的，应当申请引航。\n第六十二条 载运危险化学品的船舶在内河航行，应当遵守法律、行政法规和国家其他有关饮用水水源保护的规定。内河航道发展规划应当与依法经批准的饮用水水源保护区划定方案相协调。\n第六十三条 托运危险化学品的，托运人应当向承运人说明所托运的危险化学品的种类、数量、危险特性以及发生危险情况的应急处置措施，并按照国家有关规定对所托运的危险化学品妥善包装，在外包装上设置相应的标志。\n运输危险化学品需要添加抑制剂或者稳定剂的，托运人应当添加，并将有关情况告知承运人。\n第六十四条 托运人不得在托运的普通货物中夹带危险化学品，不得将危险化学品匿报或者谎报为普通货物托运。\n任何单位和个人不得交寄危险化学品或者在邮件、快件内夹带危险化学品，不得将危险化学品匿报或者谎报为普通物品交寄。邮政企业、快递企业不得收寄危险化学品。\n对涉嫌违反本条第一款、第二款规定的，交通运输主管部门、邮政管理部门可以依法开拆查验。\n第六十五条 通过铁路、航空运输危险化学品的安全管理，依照有关铁路、航空运输的法律、行政法规、规章的规定执行。","level":1},{"name":"第六章 危险化学品登记与事故应急救援","text":"第六十六条 国家实行危险化学品登记制度，为危险化学品安全管理以及危险化学品事故预防和应急救援提供技术、信息支持。\n第六十七条 危险化学品生产企业、进口企业，应当向国务院安全生产监督管理部门负责危险化学品登记的机构(以下简称危险化学品登记机构)办理危险化学品登记。\n危险化学品登记包括下列内容：\n(一)分类和标签信息；\n(二)物理、化学性质；\n(三)主要用途；\n(四)危险特性；\n(五)储存、使用、运输的安全要求；\n(六)出现危险情况的应急处置措施。\n对同一企业生产、进口的同一品种的危险化学品，不进行重复登记。危险化学品生产企业、进口企业发现其生产、进口的危险化学品有新的危险特性的，应当及时向危险化学品登记机构办理登记内容变更手续。\n危险化学品登记的具体办法由国务院安全生产监督管理部门制定。\n第六十八条 危险化学品登记机构应当定期向工业和信息化、环境保护、公安、卫生、交通运输、铁路、质量监督检验检疫等部门提供危险化学品登记的有关信息和资料。\n第六十九条 县级以上地方人民政府安全生产监督管理部门应当会同工业和信息化、环境保护、公安、卫生、交通运输、铁路、质量监督检验检疫等部门，根据本地区实际情况，制定危险化学品事故应急预案，报本级人民政府批准。\n第七十条 危险化学品单位应当制定本单位危险化学品事故应急预案，配备应急救援人员和必要的应急救援器材、设备，并定期组织应急救援演练。\n危险化学品单位应当将其危险化学品事故应急预案报所在地设区的市级人民政府安全生产监督管理部门备案。\n第七十一条 发生危险化学品事故，事故单位主要负责人应当立即按照本单位危险化学品应急预案组织救援，并向当地安全生产监督管理部门和环境保护、公安、卫生主管部门报告；道路运输、水路运输过程中发生危险化学品事故的，驾驶人员、船员或者押运人员还应当向事故发生地交通运输主管部门报告。\n第七十二条 发生危险化学品事故，有关地方人民政府应当立即组织安全生产监督管理、环境保护、公安、卫生、交通运输等有关部门，按照本地区危险化学品事故应急预案组织实施救援，不得拖延、推诿。\n有关地方人民政府及其有关部门应当按照下列规定，采取必要的应急处置措施，减少事故损失，防止事故蔓延、扩大：\n(一)立即组织营救和救治受害人员，疏散、撤离或者采取其他措施保护危害区域内的其他人员；\n(二)迅速控制危害源，测定危险化学品的性质、事故的危害区域及危害程度；\n(三)针对事故对人体、动植物、土壤、水源、大气造成的现实危害和可能产生的危害，迅速采取封闭、隔离、洗消等措施；\n(四)对危险化学品事故造成的环境污染和生态破坏状况进行监测、评估，并采取相应的环境污染治理和生态修复措施。\n第七十三条 有关危险化学品单位应当为危险化学品事故应急救援提供技术指导和必要的协助。\n第七十四条 危险化学品事故造成环境污染的，由设区的市级以上人民政府环境保护主管部门统一发布有关信息。","level":1},{"name":"第七章 法律责任","text":"第七十五条 生产、经营、使用国家禁止生产、经营、使用的危险化学品的，由安全生产监督管理部门责令停止生产、经营、使用活动，处20万元以上50万元以下的罚款，有违法所得的，没收违法所得；构成犯罪的，依法追究刑事责任。\n有前款规定行为的，安全生产监督管理部门还应当责令其对所生产、经营、使用的危险化学品进行无害化处理。\n违反国家关于危险化学品使用的限制性规定使用危险化学品的，依照本条第一款的规定处理。\n第七十六条 未经安全条件审查，新建、改建、扩建生产、储存危险化学品的建设项目的，由安全生产监督管理部门责令停止建设，限期改正；逾期不改正的，处50万元以上100万元以下的罚款；构成犯罪的，依法追究刑事责任。\n未经安全条件审查，新建、改建、扩建储存、装卸危险化学品的港口建设项目的，由港口行政管理部门依照前款规定予以处罚。\n第七十七条 未依法取得危险化学品安全生产许可证从事危险化学品生产，或者未依法取得工业产品生产许可证从事危险化学品及其包装物、容器生产的，分别依照《安全生产许可证条例》、《中华人民共和国工业产品生产许可证管理条例》的规定处罚。\n违反本条例规定，化工企业未取得危险化学品安全使用许可证，使用危险化学品从事生产的，由安全生产监督管理部门责令限期改正，处10万元以上20万元以下的罚款；逾期不改正的，责令停产整顿。\n违反本条例规定，未取得危险化学品经营许可证从事危险化学品经营的，由安全生产监督管理部门责令停止经营活动，没收违法经营的危险化学品以及违法所得，并处10万元以上20万元以下的罚款；构成犯罪的，依法追究刑事责任。\n第七十八条 有下列情形之一的，由安全生产监督管理部门责令改正，可以处5万元以下的罚款；拒不改正的，处5万元以上10万元以下的罚款；情节严重的，责令停产停业整顿：\n(一)生产、储存危险化学品的单位未对其铺设的危险化学品管道设置明显的标志，或者未对危险化学品管道定期检查、检测的；\n(二)进行可能危及危险化学品管道安全的施工作业，施工单位未按照规定书面通知管道所属单位，或者未与管道所属单位共同制定应急预案、采取相应的安全防护措施，或者管道所属单位未指派专门人员到现场进行管道安全保护指导的；\n(三)危险化学品生产企业未提供化学品安全技术说明书，或者未在包装(包括外包装件)上粘贴、拴挂化学品安全标签的；\n(四)危险化学品生产企业提供的化学品安全技术说明书与其生产的危险化学品不相符，或者在包装(包括外包装件)粘贴、拴挂的化学品安全标签与包装内危险化学品不相符，或者化学品安全技术说明书、化学品安全标签所载明的内容不符合国家标准要求的；\n(五)危险化学品生产企业发现其生产的危险化学品有新的危险特性不立即公告，或者不及时修订其化学品安全技术说明书和化学品安全标签的；\n(六)危险化学品经营企业经营没有化学品安全技术说明书和化学品安全标签的危险化学品的；\n(七)危险化学品包装物、容器的材质以及包装的型式、规格、方法和单件质量(重量)与所包装的危险化学品的性质和用途不相适应的；\n(八)生产、储存危险化学品的单位未在作业场所和安全设施、设备上设置明显的安全警示标志，或者未在作业场所设置通信、报警装置的；\n(九)危险化学品专用仓库未设专人负责管理，或者对储存的剧毒化学品以及储存数量构成重大危险源的其他危险化学品未实行双人收发、双人保管制度的；\n(十)储存危险化学品的单位未建立危险化学品出入库核查、登记制度的；\n(十一)危险化学品专用仓库未设置明显标志的；\n(十二)危险化学品生产企业、进口企业不办理危险化学品登记，或者发现其生产、进口的危险化学品有新的危险特性不办理危险化学品登记内容变更手续的。\n从事危险化学品仓储经营的港口经营人有前款规定情形的，由港口行政管理部门依照前款规定予以处罚。储存剧毒化学品、易制爆危险化学品的专用仓库未按照国家有关规定设置相应的技术防范设施的，由公安机关依照前款规定予以处罚。\n生产、储存剧毒化学品、易制爆危险化学品的单位未设置治安保卫机构、配备专职治安保卫人员的，依照《企业事业单位内部治安保卫条例》的规定处罚。\n第七十九条 危险化学品包装物、容器生产企业销售未经检验或者经检验不合格的危险化学品包装物、容器的，由质量监督检验检疫部门责令改正，处10万元以上20万元以下的罚款，有违法所得的，没收违法所得；拒不改正的，责令停产停业整顿；构成犯罪的，依法追究刑事责任。\n将未经检验合格的运输危险化学品的船舶及其配载的容器投入使用的，由海事管理机构依照前款规定予以处罚。\n第八十条 生产、储存、使用危险化学品的单位有下列情形之一的，由安全生产监督管理部门责令改正，处5万元以上10万元以下的罚款；拒不改正的，责令停产停业整顿直至由原发证机关吊销其相关许可证件，并由工商行政管理部门责令其办理经营范围变更登记或者吊销其营业执照；有关责任人员构成犯罪的，依法追究刑事责任：\n(一)对重复使用的危险化学品包装物、容器，在重复使用前不进行检查的；\n(二)未根据其生产、储存的危险化学品的种类和危险特性，在作业场所设置相关安全设施、设备，或者未按照国家标准、行业标准或者国家有关规定对安全设施、设备进行经常性维护、保养的；\n(三)未依照本条例规定对其安全生产条件定期进行安全评价的；\n(四)未将危险化学品储存在专用仓库内，或者未将剧毒化学品以及储存数量构成重大危险源的其他危险化学品在专用仓库内单独存放的；\n(五)危险化学品的储存方式、方法或者储存数量不符合国家标准或者国家有关规定的；\n(六)危险化学品专用仓库不符合国家标准、行业标准的要求的；\n(七)未对危险化学品专用仓库的安全设施、设备定期进行检测、检验的。\n从事危险化学品仓储经营的港口经营人有前款规定情形的，由港口行政管理部门依照前款规定予以处罚。\n第八十一条 有下列情形之一的，由公安机关责令改正，可以处1万元以下的罚款；拒不改正的，处1万元以上5万元以下的罚款：\n(一)生产、储存、使用剧毒化学品、易制爆危险化学品的单位不如实记录生产、储存、使用的剧毒化学品、易制爆危险化学品的数量、流向的；\n(二)生产、储存、使用剧毒化学品、易制爆危险化学品的单位发现剧毒化学品、易制爆危险化学品丢失或者被盗，不立即向公安机关报告的；\n(三)储存剧毒化学品的单位未将剧毒化学品的储存数量、储存地点以及管理人员的情况报所在地县级人民政府公安机关备案的；\n(四)危险化学品生产企业、经营企业不如实记录剧毒化学品、易制爆危险化学品购买单位的名称、地址、经办人的姓名、身份证号码以及所购买的剧毒化学品、易制爆危险化学品的品种、数量、用途，或者保存销售记录和相关材料的时间少于1年的；\n(五)剧毒化学品、易制爆危险化学品的销售企业、购买单位未在规定的时限内将所销售、购买的剧毒化学品、易制爆危险化学品的品种、数量以及流向信息报所在地县级人民政府公安机关备案的；\n(六)使用剧毒化学品、易制爆危险化学品的单位依照本条例规定转让其购买的剧毒化学品、易制爆危险化学品，未将有关情况向所在地县级人民政府公安机关报告的。\n生产、储存危险化学品的企业或者使用危险化学品从事生产的企业未按照本条例规定将安全评价报告以及整改方案的落实情况报安全生产监督管理部门或者港口行政管理部门备案，或者储存危险化学品的单位未将其剧毒化学品以及储存数量构成重大危险源的其他危险化学品的储存数量、储存地点以及管理人员的情况报安全生产监督管理部门或者港口行政管理部门备案的，分别由安全生产监督管理部门或者港口行政管理部门依照前款规定予以处罚。\n生产实施重点环境管理的危险化学品的企业或者使用实施重点环境管理的危险化学品从事生产的企业未按照规定将相关信息向环境保护主管部门报告的，由环境保护主管部门依照本条第一款的规定予以处罚。\n第八十二条 生产、储存、使用危险化学品的单位转产、停产、停业或者解散，未采取有效措施及时、妥善处置其危险化学品生产装置、储存设施以及库存的危险化学品，或者丢弃危险化学品的，由安全生产监督管理部门责令改正，处5万元以上10万元以下的罚款；构成犯罪的，依法追究刑事责任。\n生产、储存、使用危险化学品的单位转产、停产、停业或者解散，未依照本条例规定将其危险化学品生产装置、储存设施以及库存危险化学品的处置方案报有关部门备案的，分别由有关部门责令改正，可以处1万元以下的罚款；拒不改正的，处1万元以上5万元以下的罚款。\n第八十三条 危险化学品经营企业向未经许可违法从事危险化学品生产、经营活动的企业采购危险化学品的，由工商行政管理部门责令改正，处10万元以上20万元以下的罚款；拒不改正的，责令停业整顿直至由原发证机关吊销其危险化学品经营许可证，并由工商行政管理部门责令其办理经营范围变更登记或者吊销其营业执照。\n第八十四条 危险化学品生产企业、经营企业有下列情形之一的，由安全生产监督管理部门责令改正，没收违法所得，并处10万元以上20万元以下的罚款；拒不改正的，责令停产停业整顿直至吊销其危险化学品安全生产许可证、危险化学品经营许可证，并由工商行政管理部门责令其办理经营范围变更登记或者吊销其营业执照：\n(一)向不具有本条例第三十八条第一款、第二款规定的相关许可证件或者证明文件的单位销售剧毒化学品、易制爆危险化学品的；\n(二)不按照剧毒化学品购买许可证载明的品种、数量销售剧毒化学品的；\n(三)向个人销售剧毒化学品(属于剧毒化学品的农药除外)、易制爆危险化学品的。\n不具有本条例第三十八条第一款、第二款规定的相关许可证件或者证明文件的单位购买剧毒化学品、易制爆危险化学品，或者个人购买剧毒化学品(属于剧毒化学品的农药除外)、易制爆危险化学品的，由公安机关没收所购买的剧毒化学品、易制爆危险化学品，可以并处5000元以下的罚款。\n使用剧毒化学品、易制爆危险化学品的单位出借或者向不具有本条例第三十八条第一款、第二款规定的相关许可证件的单位转让其购买的剧毒化学品、易制爆危险化学品，或者向个人转让其购买的剧毒化学品(属于剧毒化学品的农药除外)、易制爆危险化学品的，由公安机关责令改正，处10万元以上20万元以下的罚款；拒不改正的，责令停产停业整顿。\n第八十五条 未依法取得危险货物道路运输许可、危险货物水路运输许可，从事危险化学品道路运输、水路运输的，分别依照有关道路运输、水路运输的法律、行政法规的规定处罚。\n第八十六条 有下列情形之一的，由交通运输主管部门责令改正，处5万元以上10万元以下的罚款；拒不改正的，责令停产停业整顿；构成犯罪的，依法追究刑事责任：\n(一)危险化学品道路运输企业、水路运输企业的驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员未取得从业资格上岗作业的；\n(二)运输危险化学品，未根据危险化学品的危险特性采取相应的安全防护措施，或者未配备必要的防护用品和应急救援器材的；\n(三)使用未依法取得危险货物适装证书的船舶，通过内河运输危险化学品的；\n(四)通过内河运输危险化学品的承运人违反国务院交通运输主管部门对单船运输的危险化学品数量的限制性规定运输危险化学品的；\n(五)用于危险化学品运输作业的内河码头、泊位不符合国家有关安全规范，或者未与饮用水取水口保持国家规定的安全距离，或者未经交通运输主管部门验收合格投入使用的；\n(六)托运人不向承运人说明所托运的危险化学品的种类、数量、危险特性以及发生危险情况的应急处置措施，或者未按照国家有关规定对所托运的危险化学品妥善包装并在外包装上设置相应标志的；\n(七)运输危险化学品需要添加抑制剂或者稳定剂，托运人未添加或者未将有关情况告知承运人的。\n第八十七条 有下列情形之一的，由交通运输主管部门责令改正，处10万元以上20万元以下的罚款，有违法所得的，没收违法所得；拒不改正的，责令停产停业整顿；构成犯罪的，依法追究刑事责任：\n(一)委托未依法取得危险货物道路运输许可、危险货物水路运输许可的企业承运危险化学品的；\n(二)通过内河封闭水域运输剧毒化学品以及国家规定禁止通过内河运输的其他危险化学品的；\n(三)通过内河运输国家规定禁止通过内河运输的剧毒化学品以及其他危险化学品的；\n(四)在托运的普通货物中夹带危险化学品，或者将危险化学品谎报或者匿报为普通货物托运的。\n在邮件、快件内夹带危险化学品，或者将危险化学品谎报为普通物品交寄的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。\n邮政企业、快递企业收寄危险化学品的，依照《中华人民共和国邮政法》的规定处罚。\n第八十八条 有下列情形之一的，由公安机关责令改正，处5万元以上10万元以下的罚款；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任：\n(一)超过运输车辆的核定载质量装载危险化学品的；\n(二)使用安全技术条件不符合国家标准要求的车辆运输危险化学品的；\n(三)运输危险化学品的车辆未经公安机关批准进入危险化学品运输车辆限制通行的区域的；\n(四)未取得剧毒化学品道路运输通行证，通过道路运输剧毒化学品的。\n第八十九条 有下列情形之一的，由公安机关责令改正，处1万元以上5万元以下的罚款；构成违反治安管理行为的，依法给予治安管理处罚：\n(一)危险化学品运输车辆未悬挂或者喷涂警示标志，或者悬挂或者喷涂的警示标志不符合国家标准要求的；\n(二)通过道路运输危险化学品，不配备押运人员的；\n(三)运输剧毒化学品或者易制爆危险化学品途中需要较长时间停车，驾驶人员、押运人员不向当地公安机关报告的；\n(四)剧毒化学品、易制爆危险化学品在道路运输途中丢失、被盗、被抢或者发生流散、泄露等情况，驾驶人员、押运人员不采取必要的警示措施和安全措施，或者不向当地公安机关报告的。\n第九十条 对发生交通事故负有全部责任或者主要责任的危险化学品道路运输企业，由公安机关责令消除安全隐患，未消除安全隐患的危险化学品运输车辆，禁止上道路行驶。\n第九十一条 有下列情形之一的，由交通运输主管部门责令改正，可以处1万元以下的罚款；拒不改正的，处1万元以上5万元以下的罚款：\n(一)危险化学品道路运输企业、水路运输企业未配备专职安全管理人员的；\n(二)用于危险化学品运输作业的内河码头、泊位的管理单位未制定码头、泊位危险化学品事故应急救援预案，或者未为码头、泊位配备充足、有效的应急救援器材和设备的。\n第九十二条 有下列情形之一的，依照《中华人民共和国内河交通安全管理条例》的规定处罚：\n(一)通过内河运输危险化学品的水路运输企业未制定运输船舶危险化学品事故应急救援预案，或者未为运输船舶配备充足、有效的应急救援器材和设备的；\n(二)通过内河运输危险化学品的船舶的所有人或者经营人未取得船舶污染损害责任保险证书或者财务担保证明的；\n(三)船舶载运危险化学品进出内河港口，未将有关事项事先报告海事管理机构并经其同意的；\n(四)载运危险化学品的船舶在内河航行、装卸或者停泊，未悬挂专用的警示标志，或者未按照规定显示专用信号，或者未按照规定申请引航的。\n未向港口行政管理部门报告并经其同意，在港口内进行危险化学品的装卸、过驳作业的，依照《中华人民共和国港口法》的规定处罚。\n第九十三条 伪造、变造或者出租、出借、转让危险化学品安全生产许可证、工业产品生产许可证，或者使用伪造、变造的危险化学品安全生产许可证、工业产品生产许可证的，分别依照《安全生产许可证条例》、《中华人民共和国工业产品生产许可证管理条例》的规定处罚。\n伪造、变造或者出租、出借、转让本条例规定的其他许可证，或者使用伪造、变造的本条例规定的其他许可证的，分别由相关许可证的颁发管理机关处10万元以上20万元以下的罚款，有违法所得的，没收违法所得；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。\n第九十四条 危险化学品单位发生危险化学品事故，其主要负责人不立即组织救援或者不立即向有关部门报告的，依照《生产安全事故报告和调查处理条例》的规定处罚。\n危险化学品单位发生危险化学品事故，造成他人人身伤害或者财产损失的，依法承担赔偿责任。\n第九十五条 发生危险化学品事故，有关地方人民政府及其有关部门不立即组织实施救援，或者不采取必要的应急处置措施减少事故损失，防止事故蔓延、扩大的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。\n第九十六条 负有危险化学品安全监督管理职责的部门的工作人员，在危险化学品安全监督管理工作中滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。","level":1},{"name":"第八章 附则","text":"第九十七条 监控化学品、属于危险化学品的药品和农药的安全管理，依照本条例的规定执行；法律、行政法规另有规定的，依照其规定。\n民用爆炸物品、烟花爆竹、放射性物品、核能物质以及用于国防科研生产的危险化学品的安全管理，不适用本条例。\n法律、行政法规对燃气的安全管理另有规定的，依照其规定。\n危险化学品容器属于特种设备的，其安全管理依照有关特种设备安全的法律、行政法规的规定执行。\n第九十八条 危险化学品的进出口管理，依照有关对外贸易的法律、行政法规、规章的规定执行；进口的危险化学品的储存、使用、经营、运输的安全管理，依照本条例的规定执行。\n危险化学品环境管理登记和新化学物质环境管理登记，依照有关环境保护的法律、行政法规、规章的规定执行。危险化学品环境管理登记，按照国家有关规定收取费用。\n第九十九条 公众发现、捡拾的无主危险化学品，由公安机关接收。公安机关接收或者有关部门依法没收的危险化学品，需要进行无害化处理的，交由环境保护主管部门组织其认定的专业单位进行处理，或者交由有关危险化学品生产企业进行处理。处理所需费用由国家财政负担。\n第一百条 化学品的危险特性尚未确定的，由国务院安全生产监督管理部门、国务院环境保护主管部门、国务院卫生主管部门分别负责组织对该化学品的物理危险性、环境危害性、毒理特性进行鉴定。根据鉴定结果，需要调整危险化学品目录的，依照本条例第三条第二款的规定办理。\n第一百零一条 本条例施行前已经使用危险化学品从事生产的化工企业，依照本条例规定需要取得危险化学品安全使用许可证的，应当在国务院安全生产监督管理部门规定的期限内，申请取得危险化学品安全使用许可证。\n第一百零二条 本条例自2011年12月1日起施行。","level":1}]},{"id":"n0323","sections":[{"name":"","text":"血液制品管理条例\n(1996年12月30日中华人民共和国国务院令第208号发布 根据2016年2月6日《国务院关于修改部分行政法规的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强血液制品管理，预防和控制经血液途径传播的疾病，保证血液制品的质量，根据药品管理法和传染病防治法，制定本条例。\n第二条 本条例适用于在中华人民共和国境内从事原料血浆的采集、供应以及血液制品的生产、经营活动。\n第三条 国务院卫生行政部门对全国的原料血浆的采集、供应和血液制品的生产、经营活动实施监督管理。\n县级以上地方各级人民政府卫生行政部门对本行政区域内的原料血浆的采集、供应和血液制品的生产、经营活动，依照本条例第三十条规定的职责实施监督管理。","level":1},{"name":"第二章 原料血浆的管理","text":"第四条 国家实行单采血浆站统一规划、设置的制度。\n国务院卫生行政部门根据核准的全国生产用原料血浆的需求，对单采血浆站的布局、数量和规模制定总体规划。省、自治区、直辖市人民政府卫生行政部门根据总体规划制定本行政区域内单采血浆站设置规划和采集血浆的区域规划，并报国务院卫生行政部门备案。\n第五条 单采血浆站由血液制品生产单位设置或者由县级人民政府卫生行政部门设置，专门从事单采血浆活动，具有独立法人资格。其他任何单位和个人不得从事单采血浆活动。\n第六条 设置单采血浆站，必须具备下列条件：\n(一)符合单采血浆站布局、数量、规模的规划；\n(二)具有与所采集原料血浆相适应的卫生专业技术人员；\n(三)具有与所采集原料血浆相适应的场所及卫生环境；\n(四)具有识别供血浆者的身份识别系统；\n(五)具有与所采集原料血浆相适应的单采血浆机械及其他设施；\n(六)具有对所采集原料血浆进行质量检验的技术人员以及必要的仪器设备。\n第七条 申请设置单采血浆站的，由县级人民政府卫生行政部门初审，经设区的市、自治州人民政府卫生行政部门或者省、自治区人民政府设立的派出机关的卫生行政机构审查同意，报省、自治区、直辖市人民政府卫生行政部门审批；经审查符合条件的，由省、自治区、直辖市人民政府卫生行政部门核发《单采血浆许可证》，并报国务院卫生行政部门备案。\n单采血浆站只能对省、自治区、直辖市人民政府卫生行政部门划定区域内的供血浆者进行筛查和采集血浆。\n第八条 《单采血浆许可证》应当规定有效期。\n第九条 在一个采血浆区域内，只能设置一个单采血浆站。\n严禁单采血浆站采集非划定区域内的供血浆者和其他人员的血浆。\n第十条 单采血浆站必须对供血浆者进行健康检查；检查合格的，由县级人民政府卫生行政部门核发《供血浆证》。\n供血浆者健康检查标准，由国务院卫生行政部门制定。\n第十一条 《供血浆证》由省、自治区、直辖市人民政府卫生行政部门负责设计和印制。《供血浆证》不得涂改、伪造、转让。\n第十二条 单采血浆站在采集血浆前，必须对供血浆者进行身份识别并核实其《供血浆证》，确认无误的，方可按照规定程序进行健康检查和血液化验；对检查、化验合格的，按照有关技术操作标准及程序采集血浆，并建立供血浆者健康检查及供血浆记录档案；对检查、化验不合格的，由单采血浆站收缴《供血浆证》，并由所在地县级人民政府卫生行政部门监督销毁。\n严禁采集无《供血浆证》者的血浆。\n血浆采集技术操作标准及程序，由国务院卫生行政部门制定。\n第十三条 单采血浆站只能向一个与其签订质量责任书的血液制品生产单位供应原料血浆，严禁向其他任何单位供应原料血浆。\n第十四条 单采血浆站必须使用单采血浆机械采集血浆，严禁手工操作采集血浆。采集的血浆必须按单人份冰冻保存，不得混浆。\n严禁单采血浆站采集血液或者将所采集的原料血浆用于临床。\n第十五条 单采血浆站必须使用有产品批准文号并经国家药品生物制品检定机构逐批检定合格的体外诊断试剂以及合格的一次性采血浆器材。\n采血浆器材等一次性消耗品使用后，必须按照国家有关规定予以销毁，并作记录。\n第十六条 单采血浆站采集的原料血浆的包装、储存、运输，必须符合国家规定的卫生标准和要求。\n第十七条 单采血浆站必须依照传染病防治法及其实施办法等有关规定，严格执行消毒管理及疫情上报制度。\n第十八条 单采血浆站应当每半年向所在地的县级人民政府卫生行政部门报告有关原料血浆采集情况，同时抄报设区的市、自治州人民政府卫生行政部门或者省、自治区人民政府设立的派出机关的卫生行政机构及省、自治区、直辖市人民政府卫生行政部门。省、自治区、直辖市人民政府卫生行政部门应当每年向国务院卫生行政部门汇总报告本行政区域内原料血浆的采集情况。\n第十九条 国家禁止出口原料血浆。","level":1},{"name":"第三章 血液制品生产经营单位管理","text":"第二十条 新建、改建或者扩建血液制品生产单位，经国务院卫生行政部门根据总体规划进行立项审查同意后，由省、自治区、直辖市人民政府卫生行政部门依照药品管理法的规定审核批准。\n第二十一条 血液制品生产单位必须达到国务院卫生行政部门制定的《药品生产质量管理规范》规定的标准，经国务院卫生行政部门审查合格，并依法向工商行政管理部门申领营业执照后，方可从事血液制品的生产活动。\n第二十二条 血液制品生产单位应当积极开发新品种，提高血浆综合利用率。\n血液制品生产单位生产国内已经生产的品种，必须依法向国务院卫生行政部门申请产品批准文号；国内尚未生产的品种，必须按照国家有关新药审批的程序和要求申报。\n第二十三条 严禁血液制品生产单位出让、出租、出借以及与他人共用《药品生产企业许可证》和产品批准文号。\n第二十四条 血液制品生产单位不得向无《单采血浆许可证》的单采血浆站或者未与其签订质量责任书的单采血浆站及其他任何单位收集原料血浆。\n血液制品生产单位不得向其他任何单位供应原料血浆。\n第二十五条 血液制品生产单位在原料血浆投料生产前，必须使用有产品批准文号并经国家药品生物制品检定机构逐批检定合格的体外诊断试剂，对每一人份血浆进行全面复检，并作检测记录。\n原料血浆经复检不合格的，不得投料生产，并必须在省级药品监督员监督下按照规定程序和方法予以销毁，并作记录。\n原料血浆经复检发现有经血液途径传播的疾病的，必须通知供应血浆的单采血浆站，并及时上报所在地省、自治区、直辖市人民政府卫生行政部门。\n第二十六条 血液制品出厂前，必须经过质量检验；经检验不符合国家标准的，严禁出厂。\n第二十七条 开办血液制品经营单位，由省、自治区、直辖市人民政府卫生行政部门审核批准。\n第二十八条 血液制品经营单位应当具备与所经营的产品相适应的冷藏条件和熟悉所经营品种的业务人员。\n第二十九条 血液制品生产经营单位生产、包装、储存、运输、经营血液制品，应当符合国家规定的卫生标准和要求。","level":1},{"name":"第四章 监督管理","text":"第三十条 县级以上地方各级人民政府卫生行政部门依照本条例的规定负责本行政区域内的单采血浆站、供血浆者、原料血浆的采集及血液制品经营单位的监督管理。\n省、自治区、直辖市人民政府卫生行政部门依照本条例的规定负责本行政区域内的血液制品生产单位的监督管理。\n县级以上地方各级人民政府卫生行政部门的监督人员执行职务时，可以按照国家有关规定抽取样品和索取有关资料，有关单位不得拒绝和隐瞒。\n第三十一条 省、自治区、直辖市人民政府卫生行政部门每年组织1次对本行政区域内单采血浆站的监督检查并进行年度注册。\n设区的市、自治州人民政府卫生行政部门或者省、自治区人民政府设立的派出机关的卫生行政机构每半年对本行政区域内的单采血浆站进行1次检查。\n第三十二条 国家药品生物制品检定机构及国务院卫生行政部门指定的省级药品检验机构，应当依照本条例和国家规定的标准和要求，对血液制品生产单位生产的产品定期进行检定。\n第三十三条 国务院卫生行政部门负责全国进出口血液制品的审批及监督管理。","level":1},{"name":"第五章 罚则","text":"第三十四条 违反本条例规定，未取得省、自治区、直辖市人民政府卫生行政部门核发的《单采血浆许可证》，非法从事组织、采集、供应、倒卖原料血浆活动的，由县级以上地方人民政府卫生行政部门予以取缔，没收违法所得和从事违法活动的器材、设备，并处违法所得5倍以上10倍以下的罚款，没有违法所得的，并处5万元以上10万元以下的罚款；造成经血液途径传播的疾病传播、人身伤害等危害，构成犯罪的，依法追究刑事责任。\n第三十五条 单采血浆站有下列行为之一的，由县级以上地方人民政府卫生行政部门责令限期改正，处5万元以上10万元以下的罚款；有第八项所列行为的，或者有下列其他行为并且情节严重的，由省、自治区、直辖市人民政府卫生行政部门吊销《单采血浆许可证》；构成犯罪的，对负有直接责任的主管人员和其他直接责任人员依法追究刑事责任：\n(一)采集血浆前，未按照国务院卫生行政部门颁布的健康检查标准对供血浆者进行健康检查和血液化验的；\n(二)采集非划定区域内的供血浆者或者其他人员的血浆的，或者不对供血浆者进行身份识别，采集冒名顶替者、健康检查不合格者或者无《供血浆证》者的血浆的；\n(三)违反国务院卫生行政部门制定的血浆采集技术操作标准和程序，过频过量采集血浆的；\n(四)向医疗机构直接供应原料血浆或者擅自采集血液的；\n(五)未使用单采血浆机械进行血浆采集的；\n(六)未使用有产品批准文号并经国家药品生物制品检定机构逐批检定合格的体外诊断试剂以及合格的一次性采血浆器材的；\n(七)未按照国家规定的卫生标准和要求包装、储存、运输原料血浆的；\n(八) 对国家规定检测项目检测结果呈阳性的血浆不清除、不及时上报的；\n(九) 对污染的注射器、采血浆器材及不合格血浆等不经消毒处理，擅自倾倒，污染环境，造成社会危害的；\n(十) 重复使用一次性采血浆器材的；\n(十一) 向与其签订质量责任书的血液制品生产单位以外的其他单位供应原料血浆的。\n第三十六条 单采血浆站已知其采集的血浆检测结果呈阳性，仍向血液制品生产单位供应的，由省、自治区、直辖市人民政府卫生行政部门吊销《单采血浆许可证》，由县级以上地方人民政府卫生行政部门没收违法所得，并处10万元以上30万元以下的罚款；造成经血液途径传播的疾病传播、人身伤害等危害，构成犯罪的，对负有直接责任的主管人员和其他直接责任人员依法追究刑事责任。\n第三十七条 涂改、伪造、转让《供血浆证》的，由县级人民政府卫生行政部门收缴《供血浆证》，没收违法所得，并处违法所得3倍以上5倍以下的罚款，没有违法所得的，并处1万元以下的罚款；构成犯罪的，依法追究刑事责任。\n第三十八条 血液制品生产单位有下列行为之一的，由省级以上人民政府卫生行政部门依照药品管理法及其实施办法等有关规定，按照生产假药、劣药予以处罚；构成犯罪的，对负有直接责任的主管人员和其他直接责任人员依法追究刑事责任：\n(一)使用无《单采血浆许可证》的单采血浆站或者未与其签订质量责任书的单采血浆站及其他任何单位供应的原料血浆的，或者非法采集原料血浆的；\n(二)投料生产前未对原料血浆进行复检的，或者使用没有产品批准文号或者未经国家药品生物制品检定机构逐批检定合格的体外诊断试剂进行复检的，或者将检测不合格的原料血浆投入生产的；\n(三)擅自更改生产工艺和质量标准的，或者将检验不合格的产品出厂的；\n(四)与他人共用产品批准文号的。\n第三十九条 血液制品生产单位违反本条例规定，擅自向其他单位出让、出租、出借以及与他人共用《药品生产企业许可证》、产品批准文号或者供应原料血浆的，由省级以上人民政府卫生行政部门没收违法所得，并处违法所得5倍以上10倍以下的罚款，没有违法所得的，并处5万元以上10万元以下的罚款。\n第四十条 违反本条例规定，血液制品生产经营单位生产、包装、储存、运输、经营血液制品不符合国家规定的卫生标准和要求的，由省、自治区、直辖市人民政府卫生行政部门责令改正，可以处1万元以下的罚款。\n第四十一条 在血液制品生产单位成品库待出厂的产品中，经抽检有一批次达不到国家规定的指标，经复检仍不合格的，由国务院卫生行政部门撤销该血液制品批准文号。\n第四十二条 违反本条例规定，擅自进出口血液制品或者出口原料血浆的，由省级以上人民政府卫生行政部门没收所进出口的血液制品或者所出口的原料血浆和违法所得，并处所进出口的血液制品或者所出口的原料血浆总值3倍以上5倍以下的罚款。\n第四十三条 血液制品检验人员虚报、瞒报、涂改、伪造检验报告及有关资料的，依法给予行政处分；构成犯罪的，依法追究刑事责任。\n第四十四条 卫生行政部门工作人员滥用职权、玩忽职守、徇私舞弊、索贿受贿，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。","level":1},{"name":"第六章 附则","text":"第四十五条 本条例下列用语的含义：\n血液制品，是特指各种人血浆蛋白制品。\n原料血浆，是指由单采血浆站采集的专用于血液制品生产原料的血浆。\n供血浆者，是指提供血液制品生产用原料血浆的人员。\n单采血浆站，是指根据地区血源资源，按照有关标准和要求并经严格审批设立，采集供应血液制品生产用原料血浆的单位。\n第四十六条 本条例施行前已经设立的单采血浆站和血液制品生产经营单位应当自本条例施行之日起6个月内，依照本条例的规定重新办理审批手续；凡不符合本条例规定的，一律予以关闭。\n本条例施行前已经设立的单采血浆站适用本条例第六条第五项的时间，由国务院卫生行政部门另行规定。\n第四十七条 本条例自发布之日起施行。","level":1}]},{"id":"n0324","sections":[{"name":"","text":"学校卫生工作条例\n(1990年4月25日国务院批准 1990年6月4日国家教育委员会令第10号、卫生部令第1号发布 自发布之日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为加强学校卫生工作，提高学生的健康水平，制定本条例。\n第二条 学校卫生工作的主要任务是：监测学生健康状况；对学生进行健康教育，培养学生良好的卫生习惯；改善学校卫生环境和教学卫生条件；加强对传染病、学生常见病的预防和治疗。\n第三条 本条例所称的学校，是指普通中小学、农业中学、职业中学、中等专业学校、技工学校、普通高等学校。\n第四条 教育行政部门负责学校卫生工作的行政管理。卫生行政部门负责对学校卫生工作的监督指导。","level":1},{"name":"第二章 学校卫生工作要求","text":"第五条 学校应当合理安排学生的学习时间。学生每日学习时间(包括自习)，小学不超过六小时，中学不超过八小时，大学不超过十小时。\n学校或者教师不得以任何理由和方式，增加授课时间和作业量，加重学生学习负担。\n第六条 学校教学建筑、环境噪声、室内微小气候、采光、照明等环境质量以及黑板、课桌椅的设置应当符合国家有关标准。\n新建、改建、扩建校舍，其选址、设计应当符合国家的卫生标准，并取得当地卫生行政部门的许可。竣工验收应当有当地卫生行政部门参加。\n第七条 学校应当按照有关规定为学生设置厕所和洗手设施。寄宿制学校应当为学生提供相应的洗漱、洗澡等卫生设施。\n学校应当为学生提供充足的符合卫生标准的饮用水。\n第八条 学校应当建立卫生制度，加强对学生个人卫生、环境卫生以及教室、宿舍卫生的管理。\n第九条 学校应当认真贯彻执行食品卫生法律、法规，加强饮食卫生管理，办好学生膳食，加强营养指导。\n第十条 学校体育场地和器材应当符合卫生和安全要求。运动项目和运动强度应当适合学生的生理承受能力和体质健康状况，防止发生伤害事故。\n第十一条 学校应当根据学生的年龄，组织学生参加适当的劳动，并对参加劳动的学生，进行安全教育，提供必要的安全和卫生防护措施。\n普通中小学校组织学生参加劳动，不得让学生接触有毒有害物质或者从事不安全工种的作业，不得让学生参加夜班劳动。\n普通高等学校、中等专业学校、技工学校、农业中学、职业中学组织学生参加生产劳动，接触有毒有害物质的，按照国家有关规定，提供保健待遇。学校应当定期对他们进行体格检查，加强卫生防护。\n第十二条 学校在安排体育课以及劳动等体力活动时，应当注意女学生的生理特点，给予必要的照顾。\n第十三条 学校应当把健康教育纳入教学计划。普通中小学必须开设健康教育课，普通高等学校、中等专业学校、技工学校、农业中学、职业中学应当开设健康教育选修课或者讲座。\n学校应当开展学生健康咨询活动。\n第十四条 学校应当建立学生健康管理制度。根据条件定期对学生进行体格检查，建立学生体质健康卡片，纳入学生档案。\n学校对体格检查中发现学生有器质性疾病的，应当配合学生家长做好转诊治疗。\n学校对残疾、体弱学生，应当加强医学照顾和心理卫生工作。\n第十五条 学校应当配备可以处理一般伤病事故的医疗用品。\n第十六条 学校应当积极做好近视眼、弱视、沙眼、龋齿、寄生虫、营养不良、贫血、脊柱弯曲、神经衰弱等学生常见疾病的群体预防和矫治工作。\n第十七条 学校应当认真贯彻执行传染病防治法律、法规，做好急、慢性传染病的预防和控制管理工作，同时做好地方病的预防和控制管理工作。","level":1},{"name":"第三章 学校卫生工作管理","text":"第十八条 各级教育行政部门应当把学校卫生工作纳入学校工作计划，作为考评学校工作的一项内容。\n第十九条 普通高等学校、中等专业学校、技工学校和规模较大的农业中学、职业中学、普通中小学，可以设立卫生管理机构，管理学校的卫生工作。\n第二十条 普通高等学校设校医院或者卫生科。校医院应当设保健科(室)，负责师生的卫生保健工作。\n城市普通中小学、农村中心小学和普通中学设卫生室，按学生人数六百比一的比例配备专职卫生技术人员。\n中等专业学校、技工学校、农业中学、职业中学，可以根据需要，配备专职卫生技术人员。\n学生人数不足六百人的学校，可以配备专职或者兼职保健教师，开展学校卫生工作。\n第二十一条 经本地区卫生行政部门批准，可以成立区域性的中小学生卫生保健机构。\n区域性的中小学生卫生保健机构的主要任务是：\n(一)调查研究本地区中小学生体质健康状况；\n(二)开展中小学生常见疾病的预防与矫治；\n(三)开展中小学卫生技术人员的技术培训和业务指导。\n第二十二条 学校卫生技术人员的专业技术职称考核、评定，按照卫生、教育行政部门制定的考核标准和办法，由教育行政部门组织实施。\n学校卫生技术人员按照国家有关规定，享受卫生保健津贴。\n第二十三条 教育行政部门应当将培养学校卫生技术人员的工作列入招生计划，并通过各种教育形式为学校卫生技术人员和保健教师提供进修机会。\n第二十四条 各级教育行政部门和学校应当将学校卫生经费纳入核定的年度教育经费预算。\n第二十五条 各级卫生行政部门应当组织医疗单位和专业防治机构对学生进行健康检查、传染病防治和常见病矫治，接受转诊治疗。\n第二十六条 各级卫生防疫站，对学校卫生工作承担下列任务：\n(一)实施学校卫生监测，掌握本地区学生生长发育和健康状况，掌握学生常见病、传染病、地方病动态；\n(二)制定学生常见病、传染病、地方病的防治计划；\n(三)对本地区学校卫生工作进行技术指导；\n(四)开展学校卫生服务。\n第二十七条 供学生使用的文具、娱乐器具、保健用品，必须符合国家有关卫生标准。","level":1},{"name":"第四章 学校卫生工作监督","text":"第二十八条 县以上卫生行政部门对学校卫生工作行使监督职权。其职责是：\n(一)对新建、改建、扩建校舍的选址、设计实行卫生监督；\n(二)对学校内影响学生健康的学习、生活、劳动、环境、食品等方面的卫生和传染病防治工作实行卫生监督；\n(三)对学生使用的文具、娱乐器具、保健用品实行卫生监督。\n国务院卫生行政部门可以委托国务院其他有关部门的卫生主管机构，在本系统内对前款所列第(一)、(二)项职责行使学校卫生监督职权。\n第二十九条 行使学校卫生监督职权的机构设立学校卫生监督员，由省级以上卫生行政部门聘任并发给学校卫生监督员证书。\n学校卫生监督员执行卫生行政部门或者其他有关部门卫生主管机构交付的学校卫生监督任务。\n第三十条 学校卫生监督员在执行任务时应出示证件。\n学校卫生监督员在进行卫生监督时，有权查阅与卫生监督有关的资料，搜集与卫生监督有关的情况，被监督的单位或者个人应当给予配合。学校卫生监督员对所掌握的资料、情况负有保密责任。","level":1},{"name":"第五章 奖励与处罚","text":"第三十一条 对在学校卫生工作中成绩显著的单位或者个人，各级教育、卫生行政部门和学校应当给予表彰、奖励。\n第三十二条 违反本条例第六条第二款规定，未经卫生行政部门许可新建、改建、扩建校舍的，由卫生行政部门对直接责任单位或者个人给予警告、责令停止施工或者限期改建。\n第三十三条 违反本条例第六条第一款、第七条和第十条规定的，由卫生行政部门对直接责任单位或者个人给予警告并责令限期改进。情节严重的，可以同时建议教育行政部门给予行政处分。\n第三十四条 违反本条例第十一条规定，致使学生健康受到损害的，由卫生行政部门对直接责任单位或者个人给予警告，责令限期改进。\n第三十五条 违反本条例第二十七条规定的，由卫生行政部门对直接责任单位或者个人给予警告。情节严重的，可以会同工商行政部门没收其不符合国家有关卫生标准的物品，并处以非法所得两倍以下的罚款。\n第三十六条 拒绝或者妨碍学校卫生监督员依照本条例实施卫生监督的，由卫生行政部门对直接责任单位或者个人给予警告。情节严重的，可以建议教育行政部门给予行政处分或者处以二百元以下的罚款。\n第三十七条 当事人对没收、罚款的行政处罚不服的，可以在接到处罚决定书之日起十五日内，向作出处罚决定机关的上一级机关申请复议，也可以直接向人民法院起诉。对复议决定不服的，可以在接到复议决定之日起十五日内，向人民法院起诉。对罚款决定不履行又逾期不起诉的，由作出处罚决定的机关申请人民法院强制执行。","level":1},{"name":"第六章 附则","text":"第三十八条 学校卫生监督办法、学校卫生标准由卫生部会同国家教育委员会制定。\n第三十九条 贫困县不能全部适用本条例第六条第一款和第七条规定的，可以由所在省、自治区的教育、卫生行政部门制定变通的规定。变通的规定，应当报送国家教育委员会、卫生部备案。\n第四十条 本条例由国家教育委员会、卫生部负责解释。\n第四十一条 本条例自发布之日起施行。原教育部、卫生部一九七九年十二月六日颁布的《中、小学卫生工作暂行规定(草案)》和一九八○年八月二十六日颁布的《高等学校卫生工作暂行规定(草案)》同时废止。","level":1}]},{"id":"n0325","sections":[{"name":"","text":"证券公司监督管理条例\n(2008年4月23日中华人民共和国国务院令第522号公布 根据2014年7月29日《国务院关于修改部分行政法规的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强对证券公司的监督管理，规范证券公司的行为，防范证券公司的风险，保护客户的合法权益和社会公共利益，促进证券业健康发展，根据《中华人民共和国公司法》(以下简称《公司法》)、《中华人民共和国证券法》(以下简称《证券法》)，制定本条例。\n第二条 证券公司应当遵守法律、行政法规和国务院证券监督管理机构的规定，审慎经营，履行对客户的诚信义务。\n第三条 证券公司的股东和实际控制人不得滥用权利，占用证券公司或者客户的资产，损害证券公司或者客户的合法权益。\n第四条 国家鼓励证券公司在有效控制风险的前提下，依法开展经营方式创新、业务或者产品创新、组织创新和激励约束机制创新。\n国务院证券监督管理机构、国务院有关部门应当采取有效措施，促进证券公司的创新活动规范、有序进行。\n第五条 证券公司按照国家规定，可以发行、交易、销售证券类金融产品。\n第六条 国务院证券监督管理机构依法履行对证券公司的监督管理职责。国务院证券监督管理机构的派出机构在国务院证券监督管理机构的授权范围内，履行对证券公司的监督管理职责。\n第七条 国务院证券监督管理机构、中国人民银行、国务院其他金融监督管理机构应当建立证券公司监督管理的信息共享机制。\n国务院证券监督管理机构和地方人民政府应当建立证券公司的有关情况通报机制。","level":1},{"name":"第二章 设立与变更","text":"第八条 设立证券公司，应当具备《公司法》、《证券法》和本条例规定的条件，并经国务院证券监督管理机构批准。\n第九条 证券公司的股东应当用货币或者证券公司经营必需的非货币财产出资。证券公司股东的非货币财产出资总额不得超过证券公司注册资本的30%。\n证券公司股东的出资，应当经具有证券、期货相关业务资格的会计师事务所验资并出具证明；出资中的非货币财产，应当经具有证券相关业务资格的资产评估机构评估。\n在证券公司经营过程中，证券公司的债权人将其债权转为证券公司股权的，不受本条第一款规定的限制。\n第十条 有下列情形之一的单位或者个人，不得成为持有证券公司5%以上股权的股东、实际控制人：\n(一)因故意犯罪被判处刑罚，刑罚执行完毕未逾3年；\n(二)净资产低于实收资本的50%，或者或有负债达到净资产的50%；\n(三)不能清偿到期债务；\n(四)国务院证券监督管理机构认定的其他情形。\n证券公司的其他股东应当符合国务院证券监督管理机构的相关要求。\n第十一条 证券公司应当有3名以上在证券业担任高级管理人员满2年的高级管理人员。\n第十二条 证券公司设立时，其业务范围应当与其财务状况、内部控制制度、合规制度和人力资源状况相适应；证券公司在经营过程中，经其申请，国务院证券监督管理机构可以根据其财务状况、内部控制水平、合规程度、高级管理人员业务管理能力、专业人员数量，对其业务范围进行调整。\n第十三条 证券公司增加注册资本且股权结构发生重大调整，减少注册资本，变更业务范围或者公司章程中的重要条款，合并、分立，设立、收购或者撤销境内分支机构，在境外设立、收购、参股证券经营机构，应当经国务院证券监督管理机构批准。\n前款所称公司章程中的重要条款，是指规定下列事项的条款：\n(一)证券公司的名称、住所；\n(二)证券公司的组织机构及其产生办法、职权、议事规则；\n(三)证券公司对外投资、对外提供担保的类型、金额和内部审批程序；\n(四)证券公司的解散事由与清算办法；\n(五)国务院证券监督管理机构要求证券公司章程规定的其他事项。\n本条第一款所称证券公司分支机构，是指从事业务经营活动的分公司、证券营业部等证券公司下属的非法人单位。\n第十四条 任何单位或者个人有下列情形之一的，应当事先告知证券公司，由证券公司报国务院证券监督管理机构批准：\n(一)认购或者受让证券公司的股权后，其持股比例达到证券公司注册资本的5%；\n(二)以持有证券公司股东的股权或者其他方式，实际控制证券公司5%以上的股权。\n未经国务院证券监督管理机构批准，任何单位或者个人不得委托他人或者接受他人委托持有或者管理证券公司的股权。证券公司的股东不得违反国家规定，约定不按照出资比例行使表决权。\n第十五条 证券公司合并、分立的，涉及客户权益的重大资产转让应当经具有证券相关业务资格的资产评估机构评估。\n证券公司停业、解散或者破产的，应当经国务院证券监督管理机构批准，并按照有关规定安置客户、处理未了结的业务。\n第十六条 国务院证券监督管理机构应当对下列申请进行审查，并在下列期限内，作出批准或者不予批准的书面决定：\n(一)对在境内设立证券公司或者在境外设立、收购或者参股证券经营机构的申请，自受理之日起6个月；\n(二)对增加注册资本且股权结构发生重大调整，减少注册资本，合并、分立或者要求审查股东、实际控制人资格的申请，自受理之日起3个月；\n(三)对变更业务范围、公司章程中的重要条款或者要求审查高级管理人员任职资格的申请，自受理之日起45个工作日；\n(四)对设立、收购、撤销境内分支机构，或者停业、解散、破产的申请，自受理之日起30个工作日；\n(五)对要求审查董事、监事任职资格的申请，自受理之日起20个工作日。\n国务院证券监督管理机构审批证券公司及其分支机构的设立申请，应当考虑证券市场发展和公平竞争的需要。\n第十七条 公司登记机关应当依照法律、行政法规的规定，凭国务院证券监督管理机构的批准文件，办理证券公司及其境内分支机构的设立、变更、注销登记。\n证券公司在取得公司登记机关颁发或者换发的证券公司或者境内分支机构的营业执照后，应当向国务院证券监督管理机构申请颁发或者换发经营证券业务许可证。经营证券业务许可证应当载明证券公司或者境内分支机构的证券业务范围。\n未取得经营证券业务许可证，证券公司及其境内分支机构不得经营证券业务。\n证券公司停止全部证券业务、解散、破产或者撤销境内分支机构的，应当在国务院证券监督管理机构指定的报刊上公告，并按照规定将经营证券业务许可证交国务院证券监督管理机构注销。","level":1},{"name":"第三章 组织机构","text":"第十八条 证券公司应当依照《公司法》、《证券法》和本条例的规定，建立健全组织机构，明确决策、执行、监督机构的职权。\n第十九条 证券公司可以设独立董事。证券公司的独立董事，不得在本证券公司担任董事会外的职务，不得与本证券公司存在可能妨碍其做出独立、客观判断的关系。\n第二十条 证券公司经营证券经纪业务、证券资产管理业务、融资融券业务和证券承销与保荐业务中两种以上业务的，其董事会应当设薪酬与提名委员会、审计委员会和风险控制委员会，行使公司章程规定的职权。\n证券公司董事会设薪酬与提名委员会、审计委员会的，委员会负责人由独立董事担任。\n第二十一条 证券公司设董事会秘书，负责股东会和董事会会议的筹备、文件的保管以及股东资料的管理，按照规定或者根据国务院证券监督管理机构、股东等有关单位或者个人的要求，依法提供有关资料，办理信息报送或者信息披露事项。董事会秘书为证券公司高级管理人员。\n第二十二条 证券公司设立行使证券公司经营管理职权的机构，应当在公司章程中明确其名称、组成、职责和议事规则，该机构的成员为证券公司高级管理人员。\n第二十三条 证券公司设合规负责人，对证券公司经营管理行为的合法合规性进行审查、监督或者检查。合规负责人为证券公司高级管理人员，由董事会决定聘任，并应当经国务院证券监督管理机构认可。合规负责人不得在证券公司兼任负责经营管理的职务。\n合规负责人发现违法违规行为，应当向公司章程规定的机构报告，同时按照规定向国务院证券监督管理机构或者有关自律组织报告。\n证券公司解聘合规负责人，应当有正当理由，并自解聘之日起3个工作日内将解聘的事实和理由书面报告国务院证券监督管理机构。\n第二十四条 证券公司的董事、监事、高级管理人员应当在任职前取得经国务院证券监督管理机构核准的任职资格。\n证券公司不得聘任、选任未取得任职资格的人员担任前款规定的职务；已经聘任、选任的，有关聘任、选任的决议、决定无效。\n第二十五条 证券公司的法定代表人或者高级管理人员离任的，证券公司应当对其进行审计，并自其离任之日起2个月内将审计报告报送国务院证券监督管理机构；证券公司的法定代表人或者经营管理的主要负责人离任的，应当聘请具有证券、期货相关业务资格的会计师事务所对其进行审计。\n前款规定的审计报告未报送国务院证券监督管理机构的，离任人员不得在其他证券公司任职。\n业务规则与风险控制","level":1},{"name":"第一节 一般规定","text":"第二十六条 证券公司及其境内分支机构从事《证券法》第一百二十五条规定的证券业务，应当遵守《证券法》和本条例的规定。\n证券公司及其境内分支机构经营的业务应当经国务院证券监督管理机构批准，不得经营未经批准的业务。\n2个以上的证券公司受同一单位、个人控制或者相互之间存在控制关系的，不得经营相同的证券业务，但国务院证券监督管理机构另有规定的除外。\n第二十七条 证券公司应当按照审慎经营的原则，建立健全风险管理与内部控制制度，防范和控制风险。\n证券公司应当对分支机构实行集中统一管理，不得与他人合资、合作经营管理分支机构，也不得将分支机构承包、租赁或者委托给他人经营管理。\n第二十八条 证券公司受证券登记结算机构委托，为客户开立证券账户，应当按照证券账户管理规则，对客户申报的姓名或者名称、身份的真实性进行审查。同一客户开立的资金账户和证券账户的姓名或者名称应当一致。\n证券公司为证券资产管理客户开立的证券账户，应当自开户之日起3个交易日内报证券交易所备案。\n证券公司不得将客户的资金账户、证券账户提供给他人使用。\n第二十九条 证券公司从事证券资产管理业务、融资融券业务，销售证券类金融产品，应当按照规定程序，了解客户的身份、财产与收入状况、证券投资经验和风险偏好，并以书面和电子方式予以记载、保存。证券公司应当根据所了解的客户情况推荐适当的产品或者服务。具体规则由中国证券业协会制定。\n第三十条 证券公司与客户签订证券交易委托、证券资产管理、融资融券等业务合同，应当事先指定专人向客户讲解有关业务规则和合同内容，并将风险揭示书交由客户签字确认。业务合同的必备条款和风险揭示书的标准格式，由中国证券业协会制定，并报国务院证券监督管理机构备案。\n第三十一条 证券公司从事证券资产管理业务、融资融券业务，应当按照规定编制对账单，按月寄送客户。证券公司与客户对对账单送交时间或者方式另有约定的，从其约定。\n第三十二条 证券公司应当建立信息查询制度，保证客户在证券公司营业时间内能够随时查询其委托记录、交易记录、证券和资金余额，以及证券公司业务经办人员和证券经纪人的姓名、执业证书、证券经纪人证书编号等信息。\n客户认为有关信息记录与实际情况不符的，可以向证券公司或者国务院证券监督管理机构投诉。证券公司应当指定专门部门负责处理客户投诉。国务院证券监督管理机构应当根据客户的投诉，采取相应措施。\n第三十三条 证券公司不得违反规定委托其他单位或者个人进行客户招揽、客户服务、产品销售活动。\n第三十四条 证券公司向客户提供投资建议，不得对证券价格的涨跌或者市场走势做出确定性的判断。\n证券公司及其从业人员不得利用向客户提供投资建议而谋取不正当利益。\n第三十五条 证券公司应当建立并实施有效的管理制度，防范其从业人员直接或者以化名、他人名义持有、买卖股票，收受他人赠送的股票。\n第三十六条 证券公司应当按照规定提取一般风险准备金，用于弥补经营亏损。","level":2},{"name":"第二节 证券经纪业务","text":"第三十七条 证券公司从事证券经纪业务，应当对客户账户内的资金、证券是否充足进行审查。客户资金账户内的资金不足的，不得接受其买入委托；客户证券账户内的证券不足的，不得接受其卖出委托。\n第三十八条 证券公司从事证券经纪业务，可以委托证券公司以外的人员作为证券经纪人，代理其进行客户招揽、客户服务等活动。证券经纪人应当具有证券从业资格。\n证券公司应当与接受委托的证券经纪人签订委托合同，颁发证券经纪人证书，明确对证券经纪人的授权范围，并对证券经纪人的执业行为进行监督。\n证券经纪人应当在证券公司的授权范围内从事业务，并应当向客户出示证券经纪人证书。\n第三十九条 证券经纪人应当遵守证券公司从业人员的管理规定，其在证券公司授权范围内的行为，由证券公司依法承担相应的法律责任；超出授权范围的行为，证券经纪人应当依法承担相应的法律责任。\n证券经纪人只能接受一家证券公司的委托，进行客户招揽、客户服务等活动。\n证券经纪人不得为客户办理证券认购、交易等事项。\n第四十条 证券公司向客户收取证券交易费用，应当符合国家有关规定，并将收费项目、收费标准在营业场所的显著位置予以公示。","level":2},{"name":"第三节 证券自营业务","text":"第四十一条 证券公司从事证券自营业务，限于买卖依法公开发行的股票、债券、权证、证券投资基金或者国务院证券监督管理机构认可的其他证券。\n第四十二条 证券公司从事证券自营业务，应当使用实名证券自营账户。\n证券公司的证券自营账户，应当自开户之日起3个交易日内报证券交易所备案。\n第四十三条 证券公司从事证券自营业务，不得有下列行为：\n(一)违反规定购买本证券公司控股股东或者与本证券公司有其他重大利害关系的发行人发行的证券；\n(二)违反规定委托他人代为买卖证券；\n(三)利用内幕信息买卖证券或者操纵证券市场；\n(四)法律、行政法规或者国务院证券监督管理机构禁止的其他行为。\n第四十四条 证券公司从事证券自营业务，自营证券总值与公司净资本的比例、持有一种证券的价值与公司净资本的比例、持有一种证券的数量与该证券发行总量的比例等风险控制指标，应当符合国务院证券监督管理机构的规定。","level":2},{"name":"第四节 证券资产管理业务","text":"第四十五条 证券公司可以依照《证券法》和本条例的规定，从事接受客户的委托、使用客户资产进行投资的证券资产管理业务。投资所产生的收益由客户享有，损失由客户承担，证券公司可以按照约定收取管理费用。\n证券公司从事证券资产管理业务，应当与客户签订证券资产管理合同，约定投资范围、投资比例、管理期限及管理费用等事项。\n第四十六条 证券公司从事证券资产管理业务，不得有下列行为：\n(一)向客户做出保证其资产本金不受损失或者保证其取得最低收益的承诺；\n(二)接受一个客户的单笔委托资产价值，低于国务院证券监督管理机构规定的最低限额；\n(三)使用客户资产进行不必要的证券交易；\n(四)在证券自营账户与证券资产管理账户之间或者不同的证券资产管理账户之间进行交易，且无充分证据证明已依法实现有效隔离；\n(五)法律、行政法规或者国务院证券监督管理机构禁止的其他行为。\n第四十七条 证券公司使用多个客户的资产进行集合投资，应当符合法律、行政法规和国务院证券监督管理机构的有关规定。","level":2},{"name":"第五节 融资融券业务","text":"第四十八条 本条例所称融资融券业务，是指在证券交易所或者国务院批准的其他证券交易场所进行的证券交易中，证券公司向客户出借资金供其买入证券或者出借证券供其卖出，并由客户交存相应担保物的经营活动。\n第四十九条 证券公司经营融资融券业务，应当具备下列条件：\n(一)证券公司治理结构健全，内部控制有效；\n(二)风险控制指标符合规定，财务状况、合规状况良好；\n(三)有经营融资融券业务所需的专业人员、技术条件、资金和证券；\n(四)有完善的融资融券业务管理制度和实施方案；\n(五)国务院证券监督管理机构规定的其他条件。\n第五十条 证券公司从事融资融券业务，应当与客户签订融资融券合同，并按照国务院证券监督管理机构的规定，以证券公司的名义在证券登记结算机构开立客户证券担保账户，在指定商业银行开立客户资金担保账户。客户资金担保账户内的资金应当参照本条例第五十七条的规定进行管理。\n在以证券公司名义开立的客户证券担保账户和客户资金担保账户内，应当为每一客户单独开立授信账户。\n第五十一条 证券公司向客户融资，应当使用自有资金或者依法筹集的资金；向客户融券，应当使用自有证券或者依法取得处分权的证券。\n第五十二条 证券公司向客户融资融券时，客户应当交存一定比例的保证金。保证金可以用证券充抵。\n客户交存的保证金以及通过融资融券交易买入的全部证券和卖出证券所得的全部资金，均为对证券公司的担保物，应当存入证券公司客户证券担保账户或者客户资金担保账户并记入该客户授信账户。\n第五十三条 客户证券担保账户内的证券和客户资金担保账户内的资金为信托财产。证券公司不得违背受托义务侵占客户担保账户内的证券或者资金。除本条例第五十四条规定的情形或者证券公司和客户依法另有约定的情形外，证券公司不得动用客户担保账户内的证券或者资金。\n第五十四条 证券公司应当逐日计算客户担保物价值与其债务的比例。当该比例低于规定的最低维持担保比例时，证券公司应当通知客户在一定的期限内补交差额。客户未能按期交足差额，或者到期未偿还融资融券债务的，证券公司应当立即按照约定处分其担保物。\n第五十五条 客户依照本条例第五十二条第一款规定交存保证金的比例，由国务院证券监督管理机构授权的单位规定。\n证券公司可以向客户融出的证券和融出资金可以买入证券的种类，可充抵保证金的有价证券的种类和折算率，融资融券的期限，最低维持担保比例和补交差额的期限，由证券交易所规定。\n本条第一款、第二款规定由被授权单位或者证券交易所做出的相关规定，应当向国务院证券监督管理机构备案，且不得违反国家货币政策。\n第五十六条 证券公司从事融资融券业务，自有资金或者证券不足的，可以向证券金融公司借入。证券金融公司的设立和解散由国务院决定。","level":2},{"name":"第五章 客户资产的保护","text":"第五十七条 证券公司从事证券经纪业务，其客户的交易结算资金应当存放在指定商业银行，以每个客户的名义单独立户管理。\n指定商业银行应当与证券公司及其客户签订客户的交易结算资金存管合同，约定客户的交易结算资金存取、划转、查询等事项，并按照证券交易净额结算、货银对付的要求，为证券公司开立客户的交易结算资金汇总账户。\n客户的交易结算资金的存取，应当通过指定商业银行办理。指定商业银行应当保证客户能够随时查询客户的交易结算资金的余额及变动情况。\n指定商业银行的名单，由国务院证券监督管理机构会同国务院银行业监督管理机构确定并公告。\n第五十八条 证券公司从事证券资产管理业务，应当将客户的委托资产交由本条例第五十七条第四款规定的指定商业银行或者国务院证券监督管理机构认可的其他资产托管机构托管。\n资产托管机构应当按照国务院证券监督管理机构的规定和证券资产管理合同的约定，履行安全保管客户的委托资产、办理资金收付事项、监督证券公司投资行为等职责。\n第五十九条 客户的交易结算资金、证券资产管理客户的委托资产属于客户，应当与证券公司、指定商业银行、资产托管机构的自有资产相互独立、分别管理。非因客户本身的债务或者法律规定的其他情形，任何单位或者个人不得对客户的交易结算资金、委托资产申请查封、冻结或者强制执行。\n第六十条 除下列情形外，不得动用客户的交易结算资金或者委托资金：\n(一)客户进行证券的申购、证券交易的结算或者客户提款；\n(二)客户支付与证券交易有关的佣金、费用或者税款；\n(三)法律规定的其他情形。\n第六十一条 证券公司不得以证券经纪客户或者证券资产管理客户的资产向他人提供融资或者担保。任何单位或者个人不得强令、指使、协助、接受证券公司以其证券经纪客户或者证券资产管理客户的资产提供融资或者担保。\n第六十二条 指定商业银行、资产托管机构和证券登记结算机构应当对存放在本机构的客户的交易结算资金、委托资金和客户担保账户内的资金、证券的动用情况进行监督，并按照规定定期向国务院证券监督管理机构报送客户的交易结算资金、委托资金和客户担保账户内的资金、证券的存管或者动用情况的有关数据。\n指定商业银行、资产托管机构和证券登记结算机构对超出本条例第五十三条、第五十四条、第六十条规定的范围，动用客户的交易结算资金、委托资金和客户担保账户内的资金、证券的申请、指令，应当拒绝；发现客户的交易结算资金、委托资金和客户担保账户内的资金、证券被违法动用或者有其他异常情况的，应当立即向国务院证券监督管理机构报告，并抄报有关监督管理机构。","level":1},{"name":"第六章 监督管理措施","text":"第六十三条 证券公司应当自每一会计年度结束之日起4个月内，向国务院证券监督管理机构报送年度报告；自每月结束之日起7个工作日内，报送月度报告。\n发生影响或者可能影响证券公司经营管理、财务状况、风险控制指标或者客户资产安全的重大事件的，证券公司应当立即向国务院证券监督管理机构报送临时报告，说明事件的起因、目前的状态、可能产生的后果和拟采取的相应措施。\n第六十四条 证券公司年度报告中的财务会计报告、风险控制指标报告以及国务院证券监督管理机构规定的其他专项报告，应当经具有证券、期货相关业务资格的会计师事务所审计。证券公司年度报告应当附有该会计师事务所出具的内部控制评审报告。\n证券公司的董事、高级管理人员应当对证券公司年度报告签署确认意见；经营管理的主要负责人和财务负责人应当对月度报告签署确认意见。在证券公司年度报告、月度报告上签字的人员，应当保证报告的内容真实、准确、完整；对报告内容持有异议的，应当注明自己的意见和理由。\n第六十五条 对证券公司报送的年度报告、月度报告，国务院证券监督管理机构应当指定专人进行审核，并制作审核报告。审核人员应当在审核报告上签字。审核中发现问题的，国务院证券监督管理机构应当及时采取相应措施。\n国务院证券监督管理机构应当对有关机构报送的客户的交易结算资金、委托资金和客户担保账户内的资金、证券的有关数据进行比对、核查，及时发现资金或者证券被违法动用的情况。\n第六十六条 证券公司应当依法向社会公开披露其基本情况、参股及控股情况、负债及或有负债情况、经营管理状况、财务收支状况、高级管理人员薪酬和其他有关信息。具体办法由国务院证券监督管理机构制定。\n第六十七条 国务院证券监督管理机构可以要求下列单位或者个人，在指定的期限内提供与证券公司经营管理和财务状况有关的资料、信息：\n(一)证券公司及其董事、监事、工作人员；\n(二)证券公司的股东、实际控制人；\n(三)证券公司控股或者实际控制的企业；\n(四)证券公司的开户银行、指定商业银行、资产托管机构、证券交易所、证券登记结算机构；\n(五)为证券公司提供服务的证券服务机构。\n第六十八条 国务院证券监督管理机构有权采取下列措施，对证券公司的业务活动、财务状况、经营管理情况进行检查：\n(一)询问证券公司的董事、监事、工作人员，要求其对有关检查事项做出说明；\n(二)进入证券公司的办公场所或者营业场所进行检查；\n(三)查阅、复制与检查事项有关的文件、资料，对可能被转移、隐匿或者毁损的文件、资料、电子设备予以封存；\n(四)检查证券公司的计算机信息管理系统，复制有关数据资料。\n国务院证券监督管理机构为查清证券公司的业务情况、财务状况，经国务院证券监督管理机构负责人批准，可以查询证券公司及与证券公司有控股或者实际控制关系企业的银行账户。\n第六十九条 证券公司以及有关单位和个人披露、报送或者提供的资料、信息应当真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。\n第七十条 国务院证券监督管理机构对治理结构不健全、内部控制不完善、经营管理混乱、设立账外账或者进行账外经营、拒不执行监督管理决定、违法违规的证券公司，应当责令其限期改正，并可以采取下列措施：\n(一)责令增加内部合规检查的次数并提交合规检查报告；\n(二)对证券公司及其有关董事、监事、高级管理人员、境内分支机构负责人给予谴责；\n(三)责令处分有关责任人员，并报告结果；\n(四)责令更换董事、监事、高级管理人员或者限制其权利；\n(五)对证券公司进行临时接管，并进行全面核查；\n(六)责令暂停证券公司或者其境内分支机构的部分或者全部业务、限期撤销境内分支机构。\n证券公司被暂停业务、限期撤销境内分支机构的，应当按照有关规定安置客户、处理未了结的业务。\n对证券公司的违法违规行为，合规负责人已经依法履行制止和报告职责的，免除责任。\n第七十一条 任何单位或者个人未经批准，持有或者实际控制证券公司5%以上股权的，国务院证券监督管理机构应当责令其限期改正；改正前，相应股权不具有表决权。\n第七十二条 任何人未取得任职资格，实际行使证券公司董事、监事、高级管理人员或者境内分支机构负责人职权的，国务院证券监督管理机构应当责令其停止行使职权，予以公告，并可以按照规定对其采取证券市场禁入的措施。\n第七十三条 证券公司董事、监事、高级管理人员或者境内分支机构负责人不再具备任职资格条件的，证券公司应当解除其职务并向国务院证券监督管理机构报告；证券公司未解除其职务的，国务院证券监督管理机构应当责令其解除。\n第七十四条 证券公司聘请或者解聘会计师事务所的，应当自做出决定之日起3个工作日内报国务院证券监督管理机构备案；解聘会计师事务所的，应当说明理由。\n第七十五条 会计师事务所对证券公司或者其有关人员进行审计，可以查阅、复制与审计事项有关的客户信息或者证券公司的其他有关文件、资料，并可以调取证券公司计算机信息管理系统内的有关数据资料。\n会计师事务所应当对所知悉的信息保密。法律、行政法规另有规定的除外。\n第七十六条 证券交易所应当对证券公司证券自营账户和证券资产管理账户的交易行为进行实时监控；发现异常情况的，应当及时按照交易规则和会员管理规则处理，并向国务院证券监督管理机构报告。","level":1},{"name":"第七章 法律责任","text":"第七十七条 证券公司有下列情形之一的，依照《证券法》第一百九十八条的规定处罚：\n(一)聘任不具有任职资格的人员担任境内分支机构的负责人；\n(二)未按照国务院证券监督管理机构依法做出的决定，解除不再具备任职资格条件的董事、监事、高级管理人员、境内分支机构负责人的职务。\n第七十八条 证券公司从事证券经纪业务，客户资金不足而接受其买入委托，或者客户证券不足而接受其卖出委托的，依照《证券法》第二百零五条的规定处罚。\n第七十九条 证券公司将客户的资金账户、证券账户提供给他人使用的，依照《证券法》第二百零八条的规定处罚。\n第八十条 证券公司诱使客户进行不必要的证券交易，或者从事证券资产管理业务时，使用客户资产进行不必要的证券交易的，依照《证券法》第二百一十条的规定处罚。\n第八十一条 证券公司或者其境内分支机构超出国务院证券监督管理机构批准的范围经营业务的，依照《证券法》第二百一十九条的规定处罚。\n第八十二条 证券公司在证券自营账户与证券资产管理账户之间或者不同的证券资产管理账户之间进行交易，且无充分证据证明已依法实现有效隔离的，依照《证券法》第二百二十条的规定处罚。\n第八十三条 证券公司违反本条例的规定，有下列情形之一的，责令改正，给予警告，没收违法所得，并处以违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不足10万元的，处以10万元以上30万元以下的罚款；情节严重的，暂停或者撤销其相关证券业务许可。对直接负责的主管人员和其他直接责任人员，给予警告，并处以3万元以上10万元以下的罚款；情节严重的，撤销任职资格或者证券从业资格：\n(一)违反规定委托其他单位或者个人进行客户招揽、客户服务或者产品销售活动；\n(二)向客户提供投资建议，对证券价格的涨跌或者市场走势做出确定性的判断；\n(三)违反规定委托他人代为买卖证券；\n(四)从事证券自营业务、证券资产管理业务，投资范围或者投资比例违反规定；\n(五)从事证券资产管理业务，接受一个客户的单笔委托资产价值低于规定的最低限额。\n第八十四条 证券公司违反本条例的规定，有下列情形之一的，责令改正，给予警告，没收违法所得，并处以违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不足3万元的，处以3万元以上30万元以下的罚款。对直接负责的主管人员和其他直接责任人员单处或者并处警告、3万元以上10万元以下的罚款；情节严重的，撤销任职资格或者证券从业资格：\n(一)未按照规定对离任的法定代表人或者高级管理人员进行审计，并报送审计报告；\n(二)与他人合资、合作经营管理分支机构，或者将分支机构承包、租赁或者委托给他人经营管理；\n(三)未按照规定将证券自营账户或者证券资产管理客户的证券账户报证券交易所备案；\n(四)未按照规定程序了解客户的身份、财产与收入状况、证券投资经验和风险偏好；\n(五)推荐的产品或者服务与所了解的客户情况不相适应；\n(六)未按照规定指定专人向客户讲解有关业务规则和合同内容，并以书面方式向其揭示投资风险；\n(七)未按照规定与客户签订业务合同，或者未在与客户签订的业务合同中载入规定的必备条款；\n(八)未按照规定编制并向客户送交对账单，或者未按照规定建立并有效执行信息查询制度；\n(九)未按照规定指定专门部门处理客户投诉；\n(十)未按照规定提取一般风险准备金；\n(十一)未按照规定存放、管理客户的交易结算资金、委托资金和客户担保账户内的资金、证券；\n(十二)聘请、解聘会计师事务所，未按照规定向国务院证券监督管理机构备案，解聘会计师事务所未说明理由。\n第八十五条 证券公司未按照规定为客户开立账户的，责令改正；情节严重的，处以20万元以上50万元以下的罚款，并对直接负责的董事、高级管理人员和其他直接责任人员，处以1万元以上5万元以下的罚款。\n第八十六条 违反本条例的规定，有下列情形之一的，责令改正，给予警告，没收违法所得，并处以违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不足10万元的，处以10万元以上60万元以下的罚款；情节严重的，撤销相关业务许可。对直接负责的主管人员和其他直接责任人员给予警告，撤销任职资格或者证券从业资格，并处以3万元以上30万元以下的罚款：\n(一)未经批准，委托他人或者接受他人委托持有或者管理证券公司的股权，或者认购、受让或者实际控制证券公司的股权；\n(二)证券公司股东、实际控制人强令、指使、协助、接受证券公司以证券经纪客户或者证券资产管理客户的资产提供融资或者担保；\n(三)证券公司、资产托管机构、证券登记结算机构违反规定动用客户的交易结算资金、委托资金和客户担保账户内的资金、证券；\n(四)资产托管机构、证券登记结算机构对违反规定动用委托资金和客户担保账户内的资金、证券的申请、指令予以同意、执行；\n(五)资产托管机构、证券登记结算机构发现委托资金和客户担保账户内的资金、证券被违法动用而未向国务院证券监督管理机构报告。\n第八十七条 指定商业银行有下列情形之一的，由国务院证券监督管理机构责令改正，给予警告，没收违法所得，并处以违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不足10万元的，处以10万元以上60万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以3万元以上30万元以下的罚款：\n(一)违反规定动用客户的交易结算资金；\n(二)对违反规定动用客户的交易结算资金的申请、指令予以同意或者执行；\n(三)发现客户的交易结算资金被违法动用而未向国务院证券监督管理机构报告。\n指定商业银行有前款规定的行为，情节严重的，由国务院证券监督管理机构会同国务院银行业监督管理机构责令其暂停或者终止客户的交易结算资金存管业务；对直接负责的主管人员和其他直接责任人员，国务院证券监督管理机构可以建议国务院银行业监督管理机构依法处罚。\n第八十八条 违反本条例的规定，有下列情形之一的，责令改正，给予警告，并处以3万元以上20万元以下的罚款；对直接负责的主管人员和其他直接责任人员，给予警告，可以处以3万元以下的罚款：\n(一)证券公司未按照本条例第六十六条的规定公开披露信息，或者公开披露的信息中有虚假记载、误导性陈述或者重大遗漏；\n(二)证券公司控股或者实际控制的企业、资产托管机构、证券服务机构未按照规定向国务院证券监督管理机构报送、提供有关信息、资料，或者报送、提供的信息、资料中有虚假记载、误导性陈述或者重大遗漏。\n第八十九条 违反本条例的规定，有下列情形之一的，责令改正，给予警告，没收违法所得，并处以违法所得等值罚款；没有违法所得或者违法所得不足3万元的，处以3万元以下的罚款；情节严重的，撤销任职资格或者证券从业资格：\n(一)合规负责人未按照规定向国务院证券监督管理机构或者有关自律组织报告违法违规行为；\n(二)证券经纪人从事业务未向客户出示证券经纪人证书；\n(三)证券经纪人同时接受多家证券公司的委托，进行客户招揽、客户服务等活动；\n(四)证券经纪人接受客户的委托，为客户办理证券认购、交易等事项。\n第九十条 证券公司违反规定收取费用的，由有关主管部门依法给予处罚。","level":1},{"name":"第八章 附则","text":"第九十一条 证券公司经营证券业务不符合本条例第二十六条第三款规定的，应当在国务院证券监督管理机构规定的期限内达到规定要求。\n第九十二条 证券公司客户的交易结算资金存管方式不符合本条例第五十七条规定的，国务院证券监督管理机构应当责令其限期调整。\n证券公司客户的交易结算资金存管方式，应当自本条例实施之日起1年内达到规定要求。\n第九十三条 证券公司可以向股东或者其他单位借入偿还顺序在普通债务之后的债，具体管理办法由国务院证券监督管理机构制定。\n第九十四条 外商投资证券公司的业务范围、境外股东的资格条件和出资比例，由国务院证券监督管理机构规定，报国务院批准。\n第九十五条 境外证券经营机构在境内经营证券业务或者设立代表机构，应当经国务院证券监督管理机构批准。具体办法由国务院证券监督管理机构制定，报国务院批准。\n第九十六条 本条例所称证券登记结算机构，是指《证券法》第一百五十五条规定的证券登记结算机构。\n第九十七条 本条例自2008年6月1日起施行。","level":1}]},{"id":"n0326","sections":[{"name":"","text":"汶川地震灾后恢复重建条例\n(2008年6月4日国务院第11次常务会议通过 2008年6月8日中华人民共和国国务院令第526号公布 自公布之日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了保障汶川地震灾后恢复重建工作有力、有序、有效地开展，积极、稳妥恢复灾区群众正常的生活、生产、学习、工作条件，促进灾区经济社会的恢复和发展，根据《中华人民共和国突发事件应对法》和《中华人民共和国防震减灾法》，制定本条例。\n第二条 地震灾后恢复重建应当坚持以人为本、科学规划、统筹兼顾、分步实施、自力更生、国家支持、社会帮扶的方针。\n第三条 地震灾后恢复重建应当遵循以下原则：\n(一)受灾地区自力更生、生产自救与国家支持、对口支援相结合；\n(二)政府主导与社会参与相结合；\n(三)就地恢复重建与异地新建相结合；\n(四)确保质量与注重效率相结合；\n(五)立足当前与兼顾长远相结合；\n(六)经济社会发展与生态环境资源保护相结合。\n第四条 各级人民政府应当加强对地震灾后恢复重建工作的领导、组织和协调，必要时成立地震灾后恢复重建协调机构，组织协调地震灾后恢复重建工作。\n县级以上人民政府有关部门应当在本级人民政府的统一领导下，按照职责分工，密切配合，采取有效措施，共同做好地震灾后恢复重建工作。\n第五条 地震灾区的各级人民政府应当自力更生、艰苦奋斗、勤俭节约，多种渠道筹集资金、物资，开展地震灾后恢复重建。\n国家对地震灾后恢复重建给予财政支持、税收优惠和金融扶持，并积极提供物资、技术和人力等方面的支持。\n国家鼓励公民、法人和其他组织积极参与地震灾后恢复重建工作，支持在地震灾后恢复重建中采用先进的技术、设备和材料。\n国家接受外国政府和国际组织提供的符合地震灾后恢复重建需要的援助。\n第六条 对在地震灾后恢复重建工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰和奖励。","level":1},{"name":"第二章 过渡性安置","text":"第七条 对地震灾区的受灾群众进行过渡性安置，应当根据地震灾区的实际情况，采取就地安置与异地安置，集中安置与分散安置，政府安置与投亲靠友、自行安置相结合的方式。\n政府对投亲靠友和采取其他方式自行安置的受灾群众给予适当补助。具体办法由省级人民政府制定。\n第八条 过渡性安置地点应当选在交通条件便利、方便受灾群众恢复生产和生活的区域，并避开地震活动断层和可能发生洪灾、山体滑坡和崩塌、泥石流、地面塌陷、雷击等灾害的区域以及生产、储存易燃易爆危险品的工厂、仓库。\n实施过渡性安置应当占用废弃地、空旷地，尽量不占用或者少占用农田，并避免对自然保护区、饮用水水源保护区以及生态脆弱区域造成破坏。\n第九条 地震灾区的各级人民政府根据实际条件，因地制宜，为灾区群众安排临时住所。临时住所可以采用帐篷、篷布房，有条件的也可以采用简易住房、活动板房。安排临时住所确实存在困难的，可以将学校操场和经安全鉴定的体育场馆等作为临时避难场所。\n国家鼓励地震灾区农村居民自行筹建符合安全要求的临时住所，并予以补助。具体办法由省级人民政府制定。\n第十条 用于过渡性安置的物资应当保证质量安全。生产单位应当确保帐篷、篷布房的产品质量。建设单位、生产单位应当采用质量合格的建筑材料，确保简易住房、活动板房的安全质量和抗震性能。\n第十一条 过渡性安置地点应当配套建设水、电、道路等基础设施，并按比例配备学校、医疗点、集中供水点、公共卫生间、垃圾收集点、日常用品供应点、少数民族特需品供应点以及必要的文化宣传设施等配套公共服务设施，确保受灾群众的基本生活需要。\n过渡性安置地点的规模应当适度，并安装必要的防雷设施和预留必要的消防应急通道，配备相应的消防设施，防范火灾和雷击灾害发生。\n第十二条 临时住所应当具备防火、防风、防雨等功能。\n第十三条 活动板房应当优先用于重灾区和需要异地安置的受灾群众，倒塌房屋在短期内难以恢复重建的重灾户特别是遇难者家庭、孕妇、婴幼儿、孤儿、孤老、残疾人员以及学校、医疗点等公共服务设施。\n第十四条 临时住所、过渡性安置资金和物资的分配和使用，应当公开透明，定期公布，接受有关部门和社会监督。具体办法由省级人民政府制定。\n第十五条 过渡性安置用地按临时用地安排，可以先行使用，事后再依法办理有关用地手续；到期未转为永久性用地的，应当复垦后交还原土地使用者。\n第十六条 过渡性安置地点所在地的县级人民政府，应当组织有关部门加强次生灾害、饮用水水质、食品卫生、疫情的监测和流行病学调查以及环境卫生整治。使用的消毒剂、清洗剂应当符合环境保护要求，避免对土壤、水资源、环境等造成污染。\n过渡性安置地点所在地的公安机关，应当加强治安管理，及时惩处违法行为，维护正常的社会秩序。\n受灾群众应当在过渡性安置地点所在地的县、乡(镇)人民政府组织下，建立治安、消防联队，开展治安、消防巡查等自防自救工作。\n第十七条 地震灾区的各级人民政府，应当组织受灾群众和企业开展生产自救，积极恢复生产，并做好受灾群众的心理援助工作。\n第十八条 地震灾区的各级人民政府及政府农业行政主管部门应当及时组织修复毁损的农业生产设施，开展抢种抢收，提供农业生产技术指导，保障农业投入品和农业机械设备的供应。\n第十九条 地震灾区的各级人民政府及政府有关部门应当优先组织供电、供水、供气等企业恢复生产，并对大型骨干企业恢复生产提供支持，为全面恢复工业、服务业生产经营提供条件。","level":1},{"name":"第三章 调查评估","text":"第二十条 国务院有关部门应当组织开展地震灾害调查评估工作，为编制地震灾后恢复重建规划提供依据。\n第二十一条 地震灾害调查评估应当包括下列事项：\n(一)城镇和乡村受损程度和数量；\n(二)人员伤亡情况，房屋破坏程度和数量，基础设施、公共服务设施、工农业生产设施与商贸流通设施受损程度和数量，农用地毁损程度和数量等；\n(三)需要安置人口的数量，需要救助的伤残人员数量，需要帮助的孤寡老人及未成年人的数量，需要提供的房屋数量，需要恢复重建的基础设施和公共服务设施，需要恢复重建的生产设施，需要整理和复垦的农用地等；\n(四)环境污染、生态损害以及自然和历史文化遗产毁损等情况；\n(五)资源环境承载能力以及地质灾害、地震次生灾害和隐患等情况；\n(六)水文地质、工程地质、环境地质、地形地貌以及河势和水文情势、重大水利水电工程的受影响情况；\n(七)突发公共卫生事件及其隐患；\n(八)编制地震灾后恢复重建规划需要调查评估的其他事项。\n第二十二条 县级以上人民政府应当依据各自职责分工组织有关部门和专家，对毁损严重的水利、道路、电力等基础设施，学校等公共服务设施以及其他建设工程进行工程质量和抗震性能鉴定，保存有关资料和样本，并开展地震活动对相关建设工程破坏机理的调查评估，为改进建设工程抗震设计规范和工程建设标准，采取抗震设防措施提供科学依据。\n第二十三条 地震灾害调查评估应当采用全面调查评估、实地调查评估、综合评估的方法，确保数据资料的真实性、准确性、及时性和评估结论的可靠性。\n地震部门、地震监测台网应当收集、保存地震前、地震中、地震后的所有资料和信息，并建立完整的档案。\n开展地震灾害调查评估工作，应当遵守国家法律、法规以及有关技术标准和要求。\n第二十四条 地震灾害调查评估报告应当及时上报国务院。","level":1},{"name":"第四章 恢复重建规划","text":"第二十五条 国务院发展改革部门会同国务院有关部门与地震灾区的省级人民政府共同组织编制地震灾后恢复重建规划，报国务院批准后组织实施。\n地震灾后恢复重建规划应当包括地震灾后恢复重建总体规划和城镇体系规划、农村建设规划、城乡住房建设规划、基础设施建设规划、公共服务设施建设规划、生产力布局和产业调整规划、市场服务体系规划、防灾减灾和生态修复规划、土地利用规划等专项规划。\n第二十六条 地震灾区的市、县人民政府应当在省级人民政府的指导下，组织编制本行政区域的地震灾后恢复重建实施规划。\n第二十七条 编制地震灾后恢复重建规划，应当全面贯彻落实科学发展观，坚持以人为本，优先恢复重建受灾群众基本生活和公共服务设施；尊重科学、尊重自然，充分考虑资源环境承载能力；统筹兼顾，与推进工业化、城镇化、新农村建设、主体功能区建设、产业结构优化升级相结合，并坚持统一部署、分工负责，区分缓急、突出重点，相互衔接、上下协调，规范有序、依法推进的原则。\n编制地震灾后恢复重建规划，应当遵守法律、法规和国家有关标准。\n第二十八条 地震灾后调查评估获得的地质、勘察、测绘、水文、环境等基础资料，应当作为编制地震灾后恢复重建规划的依据。\n地震工作主管部门应当根据地震地质、地震活动特性的研究成果和地震烈度分布情况，对地震动参数区划图进行复核，为编制地震灾后恢复重建规划和进行建设工程抗震设防提供依据。\n第二十九条 地震灾后恢复重建规划应当包括地震灾害状况和区域分析，恢复重建原则和目标，恢复重建区域范围，恢复重建空间布局，恢复重建任务和政策措施，有科学价值的地震遗址、遗迹保护，受损文物和具有历史价值与少数民族特色的建筑物、构筑物的修复，实施步骤和阶段等主要内容。\n地震灾后恢复重建规划应当重点对城镇和乡村的布局、住房建设、基础设施建设、公共服务设施建设、农业生产设施建设、工业生产设施建设、防灾减灾和生态环境以及自然资源和历史文化遗产保护、土地整理和复垦等做出安排。\n第三十条 地震灾区的中央所属企业生产、生活等设施的恢复重建，纳入地震灾后恢复重建规划统筹安排。\n第三十一条 编制地震灾后恢复重建规划，应当吸收有关部门、专家参加，并充分听取地震灾区受灾群众的意见；重大事项应当组织有关方面专家进行专题论证。\n第三十二条 地震灾区内的城镇和乡村完全毁损，存在重大安全隐患或者人口规模超出环境承载能力，需要异地新建的，重新选址时，应当避开地震活动断层或者生态脆弱和可能发生洪灾、山体滑坡、崩塌、泥石流、地面塌陷等灾害的区域以及传染病自然疫源地。\n地震灾区的县级以上地方人民政府应当组织有关部门、专家对新址进行论证，听取公众意见，并报上一级人民政府批准。\n第三十三条 国务院批准的地震灾后恢复重建规划，是地震灾后恢复重建的基本依据，应当及时公布。任何单位和个人都应当遵守经依法批准公布的地震灾后恢复重建规划，服从规划管理。\n地震灾后恢复重建规划所依据的基础资料修改、其他客观条件发生变化需要修改的，或者因恢复重建工作需要修改的，由规划组织编制机关提出修改意见，报国务院批准。","level":1},{"name":"第五章 恢复重建的实施","text":"第三十四条 地震灾区的省级人民政府，应当根据地震灾后恢复重建规划和当地经济社会发展水平，有计划、分步骤地组织实施地震灾后恢复重建。\n国务院有关部门应当支持、协助、指导地震灾区的恢复重建工作。\n城镇恢复重建应当充分考虑原有城市、镇总体规划，注重体现原有少数民族建筑风格，合理确定城镇的建设规模和标准，并达到抗震设防要求。\n第三十五条 发展改革部门具体负责灾后恢复重建的统筹规划、政策建议、投资计划、组织协调和重大建设项目的安排。\n财政部门会同有关部门负责提出资金安排和政策建议，并具体负责灾后恢复重建财政资金的拨付和管理。\n交通运输、水利、铁路、电力、通信、广播影视等部门按照职责分工，具体组织实施有关基础设施的灾后恢复重建。\n建设部门具体组织实施房屋和市政公用设施的灾后恢复重建。\n民政部门具体组织实施受灾群众的临时基本生活保障、生活困难救助、农村毁损房屋恢复重建补助、社会福利设施恢复重建以及对孤儿、孤老、残疾人员的安置、补助、心理援助和伤残康复。\n教育、科技、文化、卫生、广播影视、体育、人力资源社会保障、商务、工商等部门按照职责分工，具体组织实施公共服务设施的灾后恢复重建、卫生防疫和医疗救治、就业服务和社会保障、重要生活必需品供应以及维护市场秩序。高等学校、科学技术研究开发机构应当加强对有关问题的专题研究，为地震灾后恢复重建提供科学技术支撑。\n农业、林业、水利、国土资源、商务、工业等部门按照职责分工，具体组织实施动物疫情监测、农业生产设施恢复重建和农业生产条件恢复，地震灾后恢复重建用地安排、土地整理和复垦、地质灾害防治，商贸流通、工业生产设施等恢复重建。\n环保、林业、民政、水利、科技、安全生产、地震、气象、测绘等部门按照职责分工，具体负责生态环境保护和防灾减灾、安全生产的技术保障及公共服务设施恢复重建。\n中国人民银行和银行、证券、保险监督管理机构按照职责分工，具体负责地震灾后恢复重建金融支持和服务政策的制定与落实。\n公安部门具体负责维护和稳定地震灾区社会秩序。\n海关、出入境检验检疫部门按照职责分工，依法组织实施进口恢复重建物资、境外捐赠物资的验放、检验检疫。\n外交部会同有关部门按照职责分工，协调开展地震灾后恢复重建的涉外工作。\n第三十六条 国务院地震工作主管部门应当会同文物等有关部门组织专家对地震废墟进行现场调查，对具有典型性、代表性、科学价值和纪念意义的地震遗址、遗迹划定范围，建立地震遗址博物馆。\n第三十七条 地震灾区的省级人民政府应当组织民族事务、建设、环保、地震、文物等部门和专家，根据地震灾害调查评估结果，制定清理保护方案，明确地震遗址、遗迹和文物保护单位以及具有历史价值与少数民族特色的建筑物、构筑物等保护对象及其区域范围，报国务院批准后实施。\n第三十八条 地震灾害现场的清理保护，应当在确定无人类生命迹象和无重大疫情的情况下，按照统一组织、科学规划、统筹兼顾、注重保护的原则实施。发现地震灾害现场有人类生命迹象的，应当立即实施救援。\n第三十九条 对清理保护方案确定的地震遗址、遗迹应当在保护范围内采取有效措施进行保护，抢救、收集具有科学研究价值的技术资料和实物资料，并在不影响整体风貌的情况下，对有倒塌危险的建筑物、构筑物进行必要的加固，对废墟中有毒、有害的废弃物、残留物进行必要的清理。\n对文物保护单位应当实施原址保护。对尚可保留的不可移动文物和具有历史价值与少数民族特色的建筑物、构筑物以及历史建筑，应当采取加固等保护措施；对无法保留但将来可能恢复重建的，应当收集整理影像资料。\n对馆藏文物、民间收藏文物等可移动文物和非物质文化遗产的物质载体，应当及时抢救、整理、登记，并将清理出的可移动文物和非物质文化遗产的物质载体，运送到安全地点妥善保管。\n第四十条 对地震灾害现场的清理，应当按照清理保护方案分区、分类进行。清理出的遇难者遗体处理，应当尊重当地少数民族传统习惯；清理出的财物，应当对其种类、特征、数量、清理时间、地点等情况详细登记造册，妥善保存。有条件的，可以通知遇难者家属和所有权人到场。\n对清理出的废弃危险化学品和其他废弃物、残留物，应当实行分类处理，并遵守国家有关规定。\n第四十一条 地震灾区的各级人民政府应当做好地震灾区的动物疫情防控工作。对清理出的动物尸体，应当采取消毒、销毁等无害化处理措施，防止重大动物疫情的发生。\n第四十二条 对现场清理过程中拆除或者拆解的废旧建筑材料以及过渡安置期结束后不再使用的活动板房等，能回收利用的，应当回收利用。\n第四十三条 地震灾后恢复重建，应当统筹安排交通、铁路、通信、供水、供电、住房、学校、医院、社会福利、文化、广播电视、金融等基础设施和公共服务设施建设。\n城镇的地震灾后恢复重建，应当统筹安排市政公用设施、公共服务设施和其他设施，合理确定建设规模和时序。\n乡村的地震灾后恢复重建，应当尊重农民意愿，发挥村民自治组织的作用，以群众自建为主，政府补助、社会帮扶、对口支援，因地制宜，节约和集约利用土地，保护耕地。\n地震灾区的县级人民政府应当组织有关部门对村民住宅建设的选址予以指导，并提供能够符合当地实际的多种村民住宅设计图，供村民选择。村民住宅应当达到抗震设防要求，体现原有地方特色、民族特色和传统风貌。\n第四十四条 经批准的地震灾后恢复重建项目可以根据土地利用总体规划，先行安排使用土地，实行边建设边报批，并按照有关规定办理用地手续。对因地震灾害毁损的耕地、农田道路、抢险救灾应急用地、过渡性安置用地、废弃的城镇、村庄和工矿旧址，应当依法进行土地整理和复垦，并治理地质灾害。\n第四十五条 国务院有关部门应当组织对地震灾区地震动参数、抗震设防要求、工程建设标准进行复审；确有必要修订的，应当及时组织修订。\n地震灾区的抗震设防要求和有关工程建设标准应当根据修订后的地震灾区地震动参数，进行相应修订。\n第四十六条 对地震灾区尚可使用的建筑物、构筑物和设施，应当按照地震灾区的抗震设防要求进行抗震性能鉴定，并根据鉴定结果采取加固、改造等措施。\n第四十七条 地震灾后重建工程的选址，应当符合地震灾后恢复重建规划和抗震设防、防灾减灾要求，避开地震活动断层、生态脆弱地区、可能发生重大灾害的区域和传染病自然疫源地。\n第四十八条 设计单位应当严格按照抗震设防要求和工程建设强制性标准进行抗震设计，并对抗震设计的质量以及出具的施工图的准确性负责。\n施工单位应当按照施工图设计文件和工程建设强制性标准进行施工，并对施工质量负责。\n建设单位、施工单位应当选用施工图设计文件和国家有关标准规定的材料、构配件和设备。\n工程监理单位应当依照施工图设计文件和工程建设强制性标准实施监理，并对施工质量承担监理责任。\n第四十九条 按照国家有关规定对地震灾后恢复重建工程进行竣工验收时，应当重点对工程是否符合抗震设防要求进行查验；对不符合抗震设防要求的，不得出具竣工验收报告。\n第五十条 对学校、医院、体育场馆、博物馆、文化馆、图书馆、影剧院、商场、交通枢纽等人员密集的公共服务设施，应当按照高于当地房屋建筑的抗震设防要求进行设计，增强抗震设防能力。\n第五十一条 地震灾后恢复重建中涉及文物保护、自然保护区、野生动植物保护和地震遗址、遗迹保护的，依照国家有关法律、法规的规定执行。\n第五十二条 地震灾后恢复重建中，货物、工程和服务的政府采购活动，应当严格依照《中华人民共和国政府采购法》的有关规定执行。","level":1},{"name":"第六章 资金筹集与政策扶持","text":"第五十三条 县级以上人民政府应当通过政府投入、对口支援、社会募集、市场运作等方式筹集地震灾后恢复重建资金。\n第五十四条 国家根据地震的强度和损失的实际情况等因素建立地震灾后恢复重建基金，专项用于地震灾后恢复重建。\n地震灾后恢复重建基金由预算资金以及其他财政资金构成。\n地震灾后恢复重建基金筹集使用管理办法，由国务院财政部门制定。\n第五十五条 国家鼓励公民、法人和其他组织为地震灾后恢复重建捐赠款物。捐赠款物的使用应当尊重捐赠人的意愿，并纳入地震灾后恢复重建规划。\n县级以上人民政府及其部门作为受赠人的，应当将捐赠款物用于地震灾后恢复重建。公益性社会团体、公益性非营利的事业单位作为受赠人的，应当公开接受捐赠的情况和受赠财产的使用、管理情况，接受政府有关部门、捐赠人和社会的监督。\n县级以上人民政府及其部门、公益性社会团体、公益性非营利的事业单位接受捐赠的，应当向捐赠人出具由省级以上财政部门统一印制的捐赠票据。\n外国政府和国际组织提供的地震灾后恢复重建资金、物资和人员服务以及安排实施的多双边地震灾后恢复重建项目等，依照国家有关规定执行。\n第五十六条 国家鼓励公民、法人和其他组织依法投资地震灾区基础设施和公共服务设施的恢复重建。\n第五十七条 国家对地震灾后恢复重建依法实行税收优惠。具体办法由国务院财政部门、国务院税务部门制定。\n地震灾区灾后恢复重建期间，县级以上地方人民政府依法实施地方税收优惠措施。\n第五十八条 地震灾区的各项行政事业性收费可以适当减免。具体办法由有关主管部门制定。\n第五十九条 国家向地震灾区的房屋贷款和公共服务设施恢复重建贷款、工业和服务业恢复生产经营贷款、农业恢复生产贷款等提供财政贴息。具体办法由国务院财政部门会同其他有关部门制定。\n第六十条 国家在安排建设资金时，应当优先考虑地震灾区的交通、铁路、能源、农业、水利、通信、金融、市政公用、教育、卫生、文化、广播电视、防灾减灾、环境保护等基础设施和公共服务设施以及关系国家安全的重点工程设施建设。\n测绘、气象、地震、水文等设施因地震遭受破坏的，地震灾区的人民政府应当采取紧急措施，组织力量修复，确保正常运行。\n第六十一条 各级人民政府及政府有关部门应当加强对受灾群众的职业技能培训、就业服务和就业援助，鼓励企业、事业单位优先吸纳符合条件的受灾群众就业；可以采取以工代赈的方式组织受灾群众参加地震灾后恢复重建。\n第六十二条 地震灾区接受义务教育的学生，其监护人因地震灾害死亡或者丧失劳动能力或者因地震灾害导致家庭经济困难的，由国家给予生活费补贴；地震灾区的其他学生，其父母因地震灾害死亡或者丧失劳动能力或者因地震灾害导致家庭经济困难的，在同等情况下其所在的学校可以优先将其纳入国家资助政策体系予以资助。\n第六十三条 非地震灾区的县级以上地方人民政府及其有关部门应当按照国家和当地人民政府的安排，采取对口支援等多种形式支持地震灾区恢复重建。\n国家鼓励非地震灾区的企业、事业单位通过援建等多种形式支持地震灾区恢复重建。\n第六十四条 对地震灾后恢复重建中需要办理行政审批手续的事项，有审批权的人民政府及有关部门应当按照方便群众、简化手续、提高效率的原则，依法及时予以办理。","level":1},{"name":"第七章 监督管理","text":"第六十五条 县级以上人民政府应当加强对下级人民政府地震灾后恢复重建工作的监督检查。\n县级以上人民政府有关部门应当加强对地震灾后恢复重建建设工程质量和安全以及产品质量的监督。\n第六十六条 地震灾区的各级人民政府在确定地震灾后恢复重建资金和物资分配方案、房屋分配方案前，应当先行调查，经民主评议后予以公布。\n第六十七条 地震灾区的各级人民政府应当定期公布地震灾后恢复重建资金和物资的来源、数量、发放和使用情况，接受社会监督。\n第六十八条 财政部门应当加强对地震灾后恢复重建资金的拨付和使用的监督管理。\n发展改革、建设、交通运输、水利、电力、铁路、工业和信息化等部门按照职责分工，组织开展对地震灾后恢复重建项目的监督检查。国务院发展改革部门组织开展对地震灾后恢复重建的重大建设项目的稽察。\n第六十九条 审计机关应当加强对地震灾后恢复重建资金和物资的筹集、分配、拨付、使用和效果的全过程跟踪审计，定期公布地震灾后恢复重建资金和物资使用情况，并在审计结束后公布最终的审计结果。\n第七十条 地震灾区的各级人民政府及有关部门和单位，应当对建设项目以及地震灾后恢复重建资金和物资的筹集、分配、拨付、使用情况登记造册，建立、健全档案，并在建设工程竣工验收和地震灾后恢复重建结束后，及时向建设主管部门或者其他有关部门移交档案。\n第七十一条 监察机关应当加强对参与地震灾后恢复重建工作的国家机关和法律、法规授权的具有管理公共事务职能的组织及其工作人员的监察。\n第七十二条 任何单位和个人对地震灾后恢复重建中的违法违纪行为，都有权进行举报。\n接到举报的人民政府或者有关部门应当立即调查，依法处理，并为举报人保密。实名举报的，应当将处理结果反馈举报人。社会影响较大的违法违纪行为，处理结果应当向社会公布。","level":1},{"name":"第八章 法律责任","text":"第七十三条 有关地方人民政府及政府部门侵占、截留、挪用地震灾后恢复重建资金或者物资的，由财政部门、审计机关在各自职责范围内，责令改正，追回被侵占、截留、挪用的地震灾后恢复重建资金或者物资，没收违法所得，对单位给予警告或者通报批评；对直接负责的主管人员和其他直接责任人员，由任免机关或者监察机关按照人事管理权限依法给予降级、撤职直至开除的处分；构成犯罪的，依法追究刑事责任。\n第七十四条 在地震灾后恢复重建中，有关地方人民政府及政府有关部门拖欠施工单位工程款，或者明示、暗示设计单位、施工单位违反抗震设防要求和工程建设强制性标准，降低建设工程质量，造成重大安全事故，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，对直接负责的主管人员和其他直接责任人员，由任免机关或者监察机关按照人事管理权限依法给予降级、撤职直至开除的处分。\n第七十五条 在地震灾后恢复重建中，建设单位、勘察单位、设计单位、施工单位或者工程监理单位，降低建设工程质量，造成重大安全事故，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由县级以上地方人民政府建设主管部门或者其他有关部门依照《建设工程质量管理条例》的有关规定给予处罚。\n第七十六条 对毁损严重的基础设施、公共服务设施和其他建设工程，在调查评估中经鉴定确认工程质量存在重大问题，构成犯罪的，对负有责任的建设单位、设计单位、施工单位、工程监理单位的直接责任人员，依法追究刑事责任；尚不构成犯罪的，由县级以上地方人民政府建设主管部门或者其他有关部门依照《建设工程质量管理条例》的有关规定给予处罚。涉嫌行贿、受贿的，依法追究刑事责任。\n第七十七条 在地震灾后恢复重建中，扰乱社会公共秩序，构成违反治安管理行为的，由公安机关依法给予处罚。\n第七十八条 国家工作人员在地震灾后恢复重建工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第九章 附则","text":"第七十九条 地震灾后恢复重建中的其他有关法律的适用和有关政策，由国务院依法另行制定，或者由国务院有关部门、省级人民政府在各自职权范围内做出规定。\n第八十条 本条例自公布之日起施行。","level":1}]},{"id":"n0327","sections":[{"name":"","text":"中华人民共和国防治海岸工程建设项目\n污染损害海洋环境管理条例\n(1990年6月25日中华人民共和国国务院令第62号公布 根据2007年9月25日《国务院关于修改〈中华人民共和国防治海岸工程建设项目污染损害海洋环境管理条例〉的决定》第一次修订 根据2017年3月1日《国务院关于修改和废止部分行政法规的决定》第二次修订 根据2018年3月19日《国务院关于修改和废止部分行政法规的决定》第三次修订)\n第一条 为加强海岸工程建设项目的环境保护管理，严格控制新的污染，保护和改善海洋环境，根据《中华人民共和国海洋环境保护法》，制定本条例。\n第二条 本条例所称海岸工程建设项目，是指位于海岸或者与海岸连接，工程主体位于海岸线向陆一侧，对海洋环境产生影响的新建、改建、扩建工程项目。具体包括：\n(一)港口、码头、航道、滨海机场工程项目；\n(二)造船厂、修船厂；\n(三)滨海火电站、核电站、风电站；\n(四)滨海物资存储设施工程项目；\n(五)滨海矿山、化工、轻工、冶金等工业工程项目；\n(六)固体废弃物、污水等污染物处理处置排海工程项目；\n(七)滨海大型养殖场；\n(八)海岸防护工程、砂石场和入海河口处的水利设施；\n(九)滨海石油勘探开发工程项目；\n(十)国务院环境保护主管部门会同国家海洋主管部门规定的其他海岸工程项目。\n第三条 本条例适用于在中华人民共和国境内兴建海岸工程建设项目的一切单位和个人。\n拆船厂建设项目的环境保护管理，依照《防止拆船污染环境管理条例》执行。\n第四条 建设海岸工程建设项目，应当符合所在经济区的区域环境保护规划的要求。\n第五条 国务院环境保护主管部门，主管全国海岸工程建设项目的环境保护工作。\n沿海县级以上地方人民政府环境保护主管部门，主管本行政区域内的海岸工程建设项目的环境保护工作。\n第六条 新建、改建、扩建海岸工程建设项目，应当遵守国家有关建设项目环境保护管理的规定。\n第七条 海岸工程建设项目的建设单位，应当依法编制环境影响报告书(表)，报环境保护主管部门审批。\n环境保护主管部门在批准海岸工程建设项目的环境影响报告书(表)之前，应当征求海洋、海事、渔业主管部门和军队环境保护部门的意见。\n禁止在天然港湾有航运价值的区域、重要苗种基地和养殖场所及水面、滩涂中的鱼、虾、蟹、贝、藻类的自然产卵场、繁殖场、索饵场及重要的洄游通道围海造地。\n第八条 海岸工程建设项目环境影响报告书的内容，除按有关规定编制外，还应当包括：\n(一)所在地及其附近海域的环境状况；\n(二)建设过程中和建成后可能对海洋环境造成的影响；\n(三)海洋环境保护措施及其技术、经济可行性论证结论；\n(四)建设项目海洋环境影响评价结论。\n海岸工程建设项目环境影响报告表，应当参照前款规定填报。\n第九条 禁止兴建向中华人民共和国海域及海岸转嫁污染的中外合资经营企业、中外合作经营企业和外资企业；海岸工程建设项目引进技术和设备，应当有相应的防治污染措施，防止转嫁污染。\n第十条 在海洋特别保护区、海上自然保护区、海滨风景游览区、盐场保护区、海水浴场、重要渔业水域和其他需要特殊保护的区域内不得建设污染环境、破坏景观的海岸工程建设项目；在其区域外建设海岸工程建设项目的，不得损害上述区域的环境质量。法律法规另有规定的除外。\n第十一条 海岸工程建设项目竣工验收时，建设项目的环境保护设施经验收合格后，该建设项目方可正式投入生产或者使用。\n第十二条 县级以上人民政府环境保护主管部门，按照项目管理权限，可以会同有关部门对海岸工程建设项目进行现场检查，被检查者应当如实反映情况、提供资料。检查者有责任为被检查者保守技术秘密和业务秘密。法律法规另有规定的除外。\n第十三条 设置向海域排放废水设施的，应当合理利用海水自净能力，选择好排污口的位置。采用暗沟或者管道方式排放的，出水管口位置应当在低潮线以下。\n第十四条 建设港口、码头，应当设置与其吞吐能力和货物种类相适应的防污设施。\n港口、油码头、化学危险品码头，应当配备海上重大污染损害事故应急设备和器材。\n现有港口、码头未达到前两款规定要求的，由环境保护主管部门会同港口、码头主管部门责令其限期设置或者配备。\n第十五条 建设岸边造船厂、修船厂，应当设置与其性质、规模相适应的残油、废油接收处理设施，含油废水接收处理设施，拦油、收油、消油设施，工业废水接收处理设施，工业和船舶垃圾接收处理设施等。\n第十六条 建设滨海核电站和其他核设施，应当严格遵守国家有关核环境保护和放射防护的规定及标准。\n第十七条 建设岸边油库，应当设置含油废水接收处理设施，库场地面冲刷废水的集接、处理设施和事故应急设施；输油管线和储油设施应当符合国家关于防渗漏、防腐蚀的规定。\n第十八条 建设滨海矿山，在开采、选矿、运输、贮存、冶炼和尾矿处理等过程中，应当按照有关规定采取防止污染损害海洋环境的措施。\n第十九条 建设滨海垃圾场或者工业废渣填埋场，应当建造防护堤坝和场底封闭层，设置渗液收集、导出、处理系统和可燃性气体防爆装置。\n第二十条 修筑海岸防护工程，在入海河口处兴建水利设施、航道或者综合整治工程，应当采取措施，不得损害生态环境及水产资源。\n第二十一条 兴建海岸工程建设项目，不得改变、破坏国家和地方重点保护的野生动植物的生存环境。不得兴建可能导致重点保护的野生动植物生存环境污染和破坏的海岸工程建设项目；确需兴建的，应当征得野生动植物行政主管部门同意，并由建设单位负责组织采取易地繁育等措施，保证物种延续。\n在鱼、虾、蟹、贝类的洄游通道建闸、筑坝，对渔业资源有严重影响的，建设单位应当建造过鱼设施或者采取其他补救措施。\n第二十二条 集体所有制单位或者个人在全民所有的水域、海涂，建设构不成基本建设项目的养殖工程的，应当在县级以上地方人民政府规划的区域内进行。\n集体所有制单位或者个人零星经营性采挖砂石，应当在县级以上地方人民政府指定的区域内采挖。\n第二十三条 禁止在红树林和珊瑚礁生长的地区，建设毁坏红树林和珊瑚礁生态系统的海岸工程建设项目。\n第二十四条 兴建海岸工程建设项目，应当防止导致海岸非正常侵蚀。\n禁止在海岸保护设施管理部门规定的海岸保护设施的保护范围内从事爆破、采挖砂石、取土等危害海岸保护设施安全的活动。非经国务院授权的有关主管部门批准，不得占用或者拆除海岸保护设施。\n第二十五条 未持有经审核和批准的环境影响报告书(表)，兴建海岸工程建设项目的，依照《中华人民共和国海洋环境保护法》第七十九条的规定予以处罚。\n第二十六条 拒绝、阻挠环境保护主管部门进行现场检查，或者在被检查时弄虚作假的，由县级以上人民政府环境保护主管部门依照《中华人民共和国海洋环境保护法》第七十五条的规定予以处罚。\n第二十七条 海岸工程建设项目的环境保护设施未建成或者未达到规定要求，该项目即投入生产、使用的，依照《中华人民共和国海洋环境保护法》第八十条的规定予以处罚。\n第二十八条 环境保护主管部门工作人员滥用职权、玩忽职守、徇私舞弊的，由其所在单位或者上级主管机关给予行政处分；构成犯罪的，依法追究刑事责任。\n第二十九条 本条例自1990年8月1日起施行。","level":0}]},{"id":"n0328","sections":[{"name":"","text":"残疾人专用品免征进口税收暂行规定\n(1997年1月22日国务院批准 1997年4月10日海关总署第61号令发布 自发布之日起施行)\n第一条 为了支持残疾人康复工作，有利于残疾人专用品进口，制定本规定。\n第二条 进口下列残疾人专用品，免征进口关税和进口环节增值税、消费税：\n(一)肢残者用的支辅具，假肢及其零部件，假眼，假鼻，内脏托带，矫形器，矫形鞋，非机动助行器，代步工具(不包括汽车、摩托车)，生活自助具，特殊卫生用品；\n(二)视力残疾者用的盲杖，导盲镜，助视器，盲人阅读器；\n(三)语言、听力残疾者用的语言训练器；\n(四)智力残疾者用的行为训练器，生活能力训练用品。\n进口前款所列残疾人专用品，由纳税人直接在海关办理免税手续。\n第三条 有关单位进口的国内不能生产的下列残疾人专用品，按隶属关系经民政部或者中国残疾人联合会批准，并报海关总署审核后，免征进口关税和进口环节增值税、消费税：\n(一)残疾人康复及专用设备，包括床房监护设备、中心监护设备、生化分析仪和超声诊断仪；\n(二)残疾人特殊教育设备和职业教育设备；\n(三)残疾人职业能力评估测试设备；\n(四)残疾人专用劳动设备和劳动保护设备；\n(五)残疾人文体活动专用设备；\n(六)假肢专用生产、装配、检测设备，包括假肢专用铣磨机、假肢专用真空成型机、假肢专用平板加热器和假肢综合检测仪；\n(七)听力残疾者用的助听器。\n第四条 本规定第三条规定的有关单位，是指：\n(一)民政部直属企事业单位和省、自治区、直辖市民政部门所属福利机构、假肢厂和荣誉军人康复医院(包括各类革命伤残军人休养院、荣军医院和荣军康复医院)；\n(二)中国残疾人联合会(中国残疾人福利基金会)直属事业单位和省、自治区、直辖市残疾人联合会(残疾人福利基金会)所属福利机构和康复机构。\n第五条 依据本规定免税进口的残疾人专用品，不得擅自移作他用。\n违反前款规定，将免税进口的物品擅自移作他用，构成走私罪的，依法追究刑事责任；尚不构成犯罪的，按走私行为或者违反海关监管规定的行为论处。\n第六条 海关总署根据本规定制定实施办法。\n第七条 本规定自发布之日起施行。","level":0}]},{"id":"n0329","sections":[{"name":"","text":"关于爱国卫生运动委员会\n及其办事机构若干问题的规定\n(1980年5月9日国务院批准)\n爱国卫生运动是提高全民族科学文化水平，保护人民健康，保证社会主义现代化建设的一项重要措施，具有移风易俗，改造国家的作用。由于过去长期受到林彪、“四人帮”的干扰破坏，爱国卫生运动在相当长的一段时间内处于停顿状态。粉碎“四人帮”以后，有了新的发展。 为了贯彻落实“加强领导，动员群众，措施得力，持之以恒”的方针，加强对各级爱国卫生运动委员会（以下简称爱卫会）及其办事机构的组织建设，以适应新的情况，现对有关问题作如下规定：\n爱卫会的性质和任务 中央和各级爱卫会是在党中央、国务院和各级党、政的领导下，负责爱国卫生运动的领导机构。其主要任务是：组织各地区、各部门把爱国卫生运动纳入各自规划；研究解决各行各业在四化建设中出现的影响卫生、危害人体健康的问题；加强城乡卫生基本建设、卫生宣传教育和监督管理；动员广大干部、群众，深入持久地搞好除四害，讲卫生，控制和消灭疾病；防治污染，保护环境和生态平衡，不断改善城乡卫生面貌，提高人民健康水平，以保证社会主义现代化建设顺利进行。\n二、爱卫会的组织\n１．中央爱卫会，在党中央、国务院直接领导下， 由中央军委、计委、建委、农委、科委、工交、财贸、农业、水利、冶金、化工、宣传、文化、教育、卫生、环保、体育、公安、民政和工、青、妇等部门领导组成。 省、自治区、直辖市，地（市）县（旗）爱卫会，可根据实际情况，由同级有关部门领导组成。\n２．中央和地方各级爱卫会设主任一人，由党政主要领导同志担任，副主任和委员若干人。各级爱卫会成员名单抄报上一级爱卫会。\n３．城市各部门、各区、街道办事处，各大中企、事业单位和农村人民公社均设爱卫会并落实人员负责本系统、本单位的爱国卫生运动工作。其他各基层单位也要有相应的组织，有人抓这项工作。\n４．中国人民解放军各级爱卫会的组成，由解放军自定。\n５．各级爱卫会受同级党政领导，县级（中央直辖市的街道办事处）以上的爱卫会设办公室负责日常工作。\n三、爱卫会成员部门的职责 爱国卫生运动是全党全民的事情，应实行条块结合，以块为主。爱卫会成员部门，应分别做好以下工作： 计划、财政、物资部门要把城乡除害灭病、卫生基本建设（包括农村“两管五改”）所需物资、经费纳入国家和地方计划。 农业、水利部门要结合农田、水利基本建设和新农村的发展规划，抓好农村饮用水的改良、粪便无害化处理和大办沼气。卫生部门应密切配合农业、水利部门搞好寄生虫病、地方病的防治工作。 工业部门要制订搞好环境卫生、防治环境污染的规划，抓好文明生产、劳动卫生、“三废”治理和职业危害的防治。 城建部门要把城市卫生基本建设纳入城市建设规划，有计划地增添卫生设施，加强环卫专业队伍的建设，搞好城市粪便、垃圾、污水的无害化处理。抓紧解决城市卫生基本建设中存在的问题。 商业、轻工、粮食、供销、工商等部门要结合经营管理，认真贯彻执行《中华人民共和国食品卫生管理条例》和国家有关食品卫生标准的各项规定，提高食品卫生质量，改善食品结构。搞好集市贸易的卫生管理。 化工、医药部门要负责生产高效低毒低残留的除害消毒药品和器械，以满足供应。 环保部门要根据《中华人民共和国环境保护法》，“全面规划，合理布局，综合利用，化害为利，依靠群众，大家动手，保护环境，造福人民”的方针，搞好环境保护，治理“三废”和噪音，保护自然资源，防治污染和其他公害。与卫生部门紧密配合搞好保护环境的监督工作。 卫生部门要做好除害灭病的技术指导、卫生科学知识的宣传和科研工作，搞好卫生监督，解决好医疗卫生部门的垃圾、污物、污水、粪便的无害化处理。 教育部门要加强对学生的卫生知识教育，认真贯彻中、小学生守则和卫生部、教育部制定的《中小学卫生工作暂行规定》等规定，改善学校环境，培养学生爱清洁、讲卫生的道德风尚，提高学生健康水平。组织学生积极参加爱国卫生运动和卫生宣传活动。 体育部门要坚持体育与卫生相结合，积极开展群众性体育活动，增强人民体质。 公安部门要根据人民警察职责条例、治安管理处罚条例和刑法有关内容的条款，加强对公共卫生和市容的管理。 工会、共青团、妇联要组织工人、共青团员、妇女积极参加爱国卫生运动，搞好个人和家庭卫生，进行社会公德教育，自觉遵守各项卫生规定。 宣传、文化、新闻部门要采取多种形式开展卫生宣传。报纸、电台、电视台以及影剧院要积极配合搞好卫生宣传工作。 上述各成员部门，应把各自承担的爱国卫生运动的任务与生产、工作、教学等各项工作有机结合起来，列入自己的计划，统筹安排，把搞好爱国卫生运动列为考核评奖条件之一。\n四、爱卫会办公室的编制和职责范围 爱卫会办公室设主任、副主任，配备专职干部。 编制人数，由各省、自治区、直辖市根据国家编委、中央爱委会、卫生部《关于健全和加强各级爱国卫生运动委员会办事机构的通知》精神自定。人员列入行政编制或事业编制。 爱卫会办公室的职责是贯彻执行爱卫会决议、指示，向委员会请示、汇报工作；拟订爱国卫生运动计划；深入实际，调查研究，督促检查，落实计划，抓好典型，交流经验；组织开展卫生宣传教育和科学研究，监督执行各项卫生法规。 本规定自国务院批准之日起施行。","level":0}]},{"id":"n0330","sections":[{"name":"","text":"国务院关于鼓励华侨和香港澳门\n同胞投资的规定\n(1990年8月19日中华人民共和国国务院令第64号发布 自发布之日起施行)\n第一条 为促进我国经济发展，鼓励华侨和香港澳门同胞(以下统称华侨、港澳投资者)在境内投资，制定本规定。\n第二条 华侨、港澳投资者可以在境内各省、自治区、直辖市、经济特区投资。\n鼓励华侨、港澳投资者依照国家有关规定从事土地开发经营。\n第三条 华侨、港澳投资者在境内可以下列形式进行投资：\n(一)举办华侨、港澳投资者拥有全部资本的企业；\n(二)举办合资经营企业、合作经营企业；\n(三)开展补偿贸易、来料加工装配、合作生产；\n(四)购买企业的股票和债券；\n(五)购置房产；\n(六)依法取得土地使用权，开发经营；\n(七)法律、法规允许的其他投资形式。\n第四条 华侨、港澳投资者可以在境内的工业、农业、服务业以及其他符合社会和经济发展方向的行业投资。华侨、港澳投资者可以从各地方人民政府有关部门公布的项目中选择投资项目，也可以自行提出投资项目意向，向拟投资地区对外经济贸易部门或者地方人民政府指定的审批机关申请。\n国家鼓励华侨、港澳投资者投资举办产品出口企业和先进技术企业，并给予相应的优惠待遇。\n第五条 华侨、港澳投资者在境内投资举办拥有全部资本的企业、合资经营企业和合作经营企业(以下统称华侨、港澳同胞投资企业)，除适用本规定外，参照执行国家有关涉外经济法律、法规的规定，享受相应的外商投资企业待遇。\n华侨、港澳投资者在境内进行其他形式的投资，以及在境内没有设立营业机构而有来源于境内的股息、利息、租金、特许权使用费和其他所得，除适用本规定外，也可以参照执行国家有关涉外经济法律、法规的规定。\n第六条 华侨、港澳投资者可以用可自由兑换货币、机器设备或者其他实物、工业产权、专有技术等作为投资。\n第七条 华侨、港澳投资者在境内的投资、购置的资产、工业产权、投资所得利润和其他合法权益受国家法律保护，并可以依法转让和继承。\n华侨、港澳投资者在境内的活动应当遵守国家的法律、法规。\n第八条 国家对华侨、港澳投资者的投资和其他资产不实行国有化。\n第九条 国家根据社会公共利益的需要，对华侨、港澳同胞投资企业实行征收时，依照法律程序进行并给予相应的补偿。\n第十条 华侨、港澳投资者投资获得的合法利润，其他合法收入和清算后的资金，可以依法汇往境外。\n第十一条 华侨、港澳同胞投资企业在其投资总额内进口本企业所需的机器设备、生产用车辆和办公设备，以及华侨、港澳同胞个人在企业工作期间运进自用的、合理数量的生活用品和交通工具，免缴进口关税、工商统一税，免领进口许可证。\n华侨、港澳同胞投资企业进口用于生产出口产品的原材料、燃料、散件、零部件、元器件、配套件，免缴进口关税、工商统一税，免领进口许可证，由海关实行监管。上述进口料件，如用于在境内销售的产品，应当按照国家规定补办进口手续，并照章补税。\n华侨、港澳同胞投资企业生产的出口产品，除国家限制出口的外，免缴出口关税和工商统一税。\n第十二条 华侨、港澳同胞投资企业可以向境内的金融机构借款，也可以向境外的金融机构借款，并可以本企业资产和权益抵押、担保。\n第十三条 华侨、港澳投资者拥有全部资本的企业，经营期限由投资者自行确定；合资经营企业和合作经营企业，经营期限由合资或者合作各方协商确定，也可以不规定经营期限。\n第十四条 合资经营企业董事会的组成和董事长的委派、合作经营企业董事会或者联合管理机构的组成和董事长或者联合管理机构主任的委派，可以参照出资比例或者合作条件，由合资或者合作各方协商决定。\n第十五条 华侨、港澳同胞投资企业依照经批准的合同、章程进行经营管理活动。企业的经营管理自主权不受干涉。\n第十六条 在境内投资的华侨、港澳同胞个人以及华侨、港澳同胞投资企业从境外聘请的技术和管理人员，可以申请办理多次入出境的证件。\n第十七条 华侨、港澳投资者在境内投资可以委托境内的亲友为其代理人。代理人应当持有具有法律效力的委托书。\n第十八条 在华侨、港澳同胞投资企业集中的地区，华侨、港澳投资者可以向当地人民政府申请成立华侨、港澳投资者协会。\n第十九条 华侨、港澳投资者在境内投资举办合资经营企业、合作经营企业，由境内的合资、合作方负责申请；举办华侨、港澳投资者拥有全部资本的企业，由华侨、港澳投资者直接申请或者委托在境内的亲友、咨询服务机构等代为申请。华侨、港澳投资者投资举办企业的申请，由当地对外经济贸易部门或者地方人民政府指定的审批机关统一受理。\n华侨、港澳同胞投资企业的审批，按照国务院规定的权限办理。各级对外经济贸易部门或者地方人民政府指定的审批机关应当在收到全部申请文件之日起四十五天内决定批准或者不批准。\n申请人应当在收到批准证书之日起三十天内，按照有关登记管理办法，向工商行政管理机关申请登记，领取营业执照。\n第二十条 华侨、港澳投资者在境内投资因履行合同发生的或者与合同有关的争议，当事人应当尽可能通过协商或者调解解决。\n当事人不愿协商、调解的，或者协商、调解不成的，可以依据合同中的仲裁条款或者事后达成的书面仲裁协议，提交境内或者其他仲裁机构仲裁。\n当事人没有在合同中订立仲裁条款，事后又没有达成书面仲裁协议的，可以向人民法院起诉。\n第二十一条 本规定由对外经济贸易部负责解释。\n第二十二条 本规定自发布之日起施行。","level":0}]},{"id":"n0331","sections":[{"name":"","text":"中华人民共和国劳动合同法实施条例\n(2008年9月3日国务院第25次常务会议通过 2008年9月18日中华人民共和国国务院令第535号公布 自公布之日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了贯彻实施《中华人民共和国劳动合同法》(以下简称劳动合同法)，制定本条例。\n第二条 各级人民政府和县级以上人民政府劳动行政等有关部门以及工会等组织，应当采取措施，推动劳动合同法的贯彻实施，促进劳动关系的和谐。\n第三条 依法成立的会计师事务所、律师事务所等合伙组织和基金会，属于劳动合同法规定的用人单位。","level":1},{"name":"第二章 劳动合同的订立","text":"第四条 劳动合同法规定的用人单位设立的分支机构，依法取得营业执照或者登记证书的，可以作为用人单位与劳动者订立劳动合同；未依法取得营业执照或者登记证书的，受用人单位委托可以与劳动者订立劳动合同。\n第五条 自用工之日起一个月内，经用人单位书面通知后，劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，无需向劳动者支付经济补偿，但是应当依法向劳动者支付其实际工作时间的劳动报酬。\n第六条 用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并与劳动者补订书面劳动合同；劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，并依照劳动合同法第四十七条的规定支付经济补偿。\n前款规定的用人单位向劳动者每月支付两倍工资的起算时间为用工之日起满一个月的次日，截止时间为补订书面劳动合同的前一日。\n第七条 用人单位自用工之日起满一年未与劳动者订立书面劳动合同的，自用工之日起满一个月的次日至满一年的前一日应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并视为自用工之日起满一年的当日已经与劳动者订立无固定期限劳动合同，应当立即与劳动者补订书面劳动合同。\n第八条 劳动合同法第七条规定的职工名册，应当包括劳动者姓名、性别、公民身份号码、户籍地址及现住址、联系方式、用工形式、用工起始时间、劳动合同期限等内容。\n第九条 劳动合同法第十四条第二款规定的连续工作满10年的起始时间，应当自用人单位用工之日起计算，包括劳动合同法施行前的工作年限。\n第十条 劳动者非因本人原因从原用人单位被安排到新用人单位工作的，劳动者在原用人单位的工作年限合并计算为新用人单位的工作年限。原用人单位已经向劳动者支付经济补偿的，新用人单位在依法解除、终止劳动合同计算支付经济补偿的工作年限时，不再计算劳动者在原用人单位的工作年限。\n第十一条 除劳动者与用人单位协商一致的情形外，劳动者依照劳动合同法第十四条第二款的规定，提出订立无固定期限劳动合同的，用人单位应当与其订立无固定期限劳动合同。对劳动合同的内容，双方应当按照合法、公平、平等自愿、协商一致、诚实信用的原则协商确定；对协商不一致的内容，依照劳动合同法第十八条的规定执行。\n第十二条 地方各级人民政府及县级以上地方人民政府有关部门为安置就业困难人员提供的给予岗位补贴和社会保险补贴的公益性岗位，其劳动合同不适用劳动合同法有关无固定期限劳动合同的规定以及支付经济补偿的规定。\n第十三条 用人单位与劳动者不得在劳动合同法第四十四条规定的劳动合同终止情形之外约定其他的劳动合同终止条件。\n第十四条 劳动合同履行地与用人单位注册地不一致的，有关劳动者的最低工资标准、劳动保护、劳动条件、职业危害防护和本地区上年度职工月平均工资标准等事项，按照劳动合同履行地的有关规定执行；用人单位注册地的有关标准高于劳动合同履行地的有关标准，且用人单位与劳动者约定按照用人单位注册地的有关规定执行的，从其约定。\n第十五条 劳动者在试用期的工资不得低于本单位相同岗位最低档工资的80%或者不得低于劳动合同约定工资的80%，并不得低于用人单位所在地的最低工资标准。\n第十六条 劳动合同法第二十二条第二款规定的培训费用，包括用人单位为了对劳动者进行专业技术培训而支付的有凭证的培训费用、培训期间的差旅费用以及因培训产生的用于该劳动者的其他直接费用。\n第十七条 劳动合同期满，但是用人单位与劳动者依照劳动合同法第二十二条的规定约定的服务期尚未到期的，劳动合同应当续延至服务期满；双方另有约定的，从其约定。","level":1},{"name":"第三章 劳动合同的解除和终止","text":"第十八条 有下列情形之一的，依照劳动合同法规定的条件、程序，劳动者可以与用人单位解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同：\n(一)劳动者与用人单位协商一致的；\n(二)劳动者提前30日以书面形式通知用人单位的；\n(三)劳动者在试用期内提前3日通知用人单位的；\n(四)用人单位未按照劳动合同约定提供劳动保护或者劳动条件的；\n(五)用人单位未及时足额支付劳动报酬的；\n(六)用人单位未依法为劳动者缴纳社会保险费的；\n(七)用人单位的规章制度违反法律、法规的规定，损害劳动者权益的；\n(八)用人单位以欺诈、胁迫的手段或者乘人之危，使劳动者在违背真实意思的情况下订立或者变更劳动合同的；\n(九)用人单位在劳动合同中免除自己的法定责任、排除劳动者权利的；\n(十)用人单位违反法律、行政法规强制性规定的；\n(十一)用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动者劳动的；\n(十二)用人单位违章指挥、强令冒险作业危及劳动者人身安全的；\n(十三)法律、行政法规规定劳动者可以解除劳动合同的其他情形。\n第十九条 有下列情形之一的，依照劳动合同法规定的条件、程序，用人单位可以与劳动者解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同：\n(一)用人单位与劳动者协商一致的；\n(二)劳动者在试用期间被证明不符合录用条件的；\n(三)劳动者严重违反用人单位的规章制度的；\n(四)劳动者严重失职，营私舞弊，给用人单位造成重大损害的；\n(五)劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的；\n(六)劳动者以欺诈、胁迫的手段或者乘人之危，使用人单位在违背真实意思的情况下订立或者变更劳动合同的；\n(七)劳动者被依法追究刑事责任的；\n(八)劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的；\n(九)劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的；\n(十)劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的；\n(十一)用人单位依照企业破产法规定进行重整的；\n(十二)用人单位生产经营发生严重困难的；\n(十三)企业转产、重大技术革新或者经营方式调整，经变更劳动合同后，仍需裁减人员的；\n(十四)其他因劳动合同订立时所依据的客观经济情况发生重大变化，致使劳动合同无法履行的。\n第二十条 用人单位依照劳动合同法第四十条的规定，选择额外支付劳动者一个月工资解除劳动合同的，其额外支付的工资应当按照该劳动者上一个月的工资标准确定。\n第二十一条 劳动者达到法定退休年龄的，劳动合同终止。\n第二十二条 以完成一定工作任务为期限的劳动合同因任务完成而终止的，用人单位应当依照劳动合同法第四十七条的规定向劳动者支付经济补偿。\n第二十三条 用人单位依法终止工伤职工的劳动合同的，除依照劳动合同法第四十七条的规定支付经济补偿外，还应当依照国家有关工伤保险的规定支付一次性工伤医疗补助金和伤残就业补助金。\n第二十四条 用人单位出具的解除、终止劳动合同的证明，应当写明劳动合同期限、解除或者终止劳动合同的日期、工作岗位、在本单位的工作年限。\n第二十五条 用人单位违反劳动合同法的规定解除或者终止劳动合同，依照劳动合同法第八十七条的规定支付了赔偿金的，不再支付经济补偿。赔偿金的计算年限自用工之日起计算。\n第二十六条 用人单位与劳动者约定了服务期，劳动者依照劳动合同法第三十八条的规定解除劳动合同的，不属于违反服务期的约定，用人单位不得要求劳动者支付违约金。\n有下列情形之一，用人单位与劳动者解除约定服务期的劳动合同的，劳动者应当按照劳动合同的约定向用人单位支付违约金：\n(一)劳动者严重违反用人单位的规章制度的；\n(二)劳动者严重失职，营私舞弊，给用人单位造成重大损害的；\n(三)劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的；\n(四)劳动者以欺诈、胁迫的手段或者乘人之危，使用人单位在违背真实意思的情况下订立或者变更劳动合同的；\n(五)劳动者被依法追究刑事责任的。\n第二十七条 劳动合同法第四十七条规定的经济补偿的月工资按照劳动者应得工资计算，包括计时工资或者计件工资以及奖金、津贴和补贴等货币性收入。劳动者在劳动合同解除或者终止前12个月的平均工资低于当地最低工资标准的，按照当地最低工资标准计算。劳动者工作不满12个月的，按照实际工作的月数计算平均工资。","level":1},{"name":"第四章 劳务派遣特别规定","text":"第二十八条 用人单位或者其所属单位出资或者合伙设立的劳务派遣单位，向本单位或者所属单位派遣劳动者的，属于劳动合同法第六十七条规定的不得设立的劳务派遣单位。\n第二十九条 用工单位应当履行劳动合同法第六十二条规定的义务，维护被派遣劳动者的合法权益。\n第三十条 劳务派遣单位不得以非全日制用工形式招用被派遣劳动者。\n第三十一条 劳务派遣单位或者被派遣劳动者依法解除、终止劳动合同的经济补偿，依照劳动合同法第四十六条、第四十七条的规定执行。\n第三十二条 劳务派遣单位违法解除或者终止被派遣劳动者的劳动合同的，依照劳动合同法第四十八条的规定执行。","level":1},{"name":"第五章 法律责任","text":"第三十三条 用人单位违反劳动合同法有关建立职工名册规定的，由劳动行政部门责令限期改正；逾期不改正的，由劳动行政部门处2000元以上2万元以下的罚款。\n第三十四条 用人单位依照劳动合同法的规定应当向劳动者每月支付两倍的工资或者应当向劳动者支付赔偿金而未支付的，劳动行政部门应当责令用人单位支付。\n第三十五条 用工单位违反劳动合同法和本条例有关劳务派遣规定的，由劳动行政部门和其他有关主管部门责令改正；情节严重的，以每位被派遣劳动者1000元以上5000元以下的标准处以罚款；给被派遣劳动者造成损害的，劳务派遣单位和用工单位承担连带赔偿责任。","level":1},{"name":"第六章 附则","text":"第三十六条 对违反劳动合同法和本条例的行为的投诉、举报，县级以上地方人民政府劳动行政部门依照《劳动保障监察条例》的规定处理。\n第三十七条 劳动者与用人单位因订立、履行、变更、解除或者终止劳动合同发生争议的，依照《中华人民共和国劳动争议调解仲裁法》的规定处理。\n第三十八条 本条例自公布之日起施行。","level":1}]},{"id":"n0332","sections":[{"name":"","text":"中外合资经营企业合营期限暂行规定\n(1990年9月30日国务院批准 1990年10月22日对外经济贸易部发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》修订)\n第一条 根据《中华人民共和国中外合资经营企业法》的有关规定，制定本规定。\n第二条 举办中外合资经营企业(以下简称合营企业)，属于国家规定鼓励和允许投资项目的，除本规定第三条另有规定外，合营各方可以在合同中约定合营期限，也可以不约定合营期限。\n第三条 举办合营企业，属于下列行业或者情况的，合营各方应当依照国家有关法律、法规的规定，在合营合同中约定合营期限：\n(一)服务性行业的，如饭店、公寓、写字楼、娱乐、饮食、出租汽车、彩扩洗像、维修、咨询等；\n(二)从事土地开发及经营房地产的；\n(三)从事资源勘查开发的；\n(四)国家规定限制投资项目的；\n(五)国家其他法律、法规规定需要约定合营期限的。\n第四条 合营各方在合营合同中不约定合营期限的合营企业，按照国家规定的审批权限和程序审批。除对外经济贸易部直接审批的外，其他审批机关应当在批准后30天内报对外经济贸易部备案。\n第五条 合营各方在合营合同中不约定合营期限的合营企业，经税务机关批准，可以按照国家有关税收的规定享受减税、免税优惠待遇。如实际经营期未达到国家有关税收优惠规定的年限，应当依法补缴已经减免的税款。\n第六条 在本规定施行之前已经批准设立的合营企业，按照批准的合营合同约定的期限执行，但属本规定第三条规定以外的合营企业，合营各方一致同意将合营合同中合营期限条款修改为不约定合营期限的，合营各方应当申报理由，签订修改合营合同的协议，并提出申请，报原审批机关审查。\n原审批机关应当自接到上述申请文件之日起90天内决定批准或者不批准。批准后，按照本规定第四条的规定办理备案手续。\n第七条 本规定自发布之日起施行。","level":0}]},{"id":"n0333","sections":[{"name":"","text":"中华人民共和国内河交通安全管理条例\n(2002年6月28日中华人民共和国国务院令第355号公布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2017年3月1日《国务院关于修改和废止部分行政法规的决定》第二次修订 根据2019年3月2日《国务院关于修改部分行政法规的决定》第三次修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强内河交通安全管理，维护内河交通秩序，保障人民群众生命、财产安全，制定本条例。\n第二条 在中华人民共和国内河通航水域从事航行、停泊和作业以及与内河交通安全有关的活动，必须遵守本条例。\n第三条 内河交通安全管理遵循安全第一、预防为主、方便群众、依法管理的原则，保障内河交通安全、有序、畅通。\n第四条 国务院交通主管部门主管全国内河交通安全管理工作。国家海事管理机构在国务院交通主管部门的领导下，负责全国内河交通安全监督管理工作。\n国务院交通主管部门在中央管理水域设立的海事管理机构和省、自治区、直辖市人民政府在中央管理水域以外的其他水域设立的海事管理机构(以下统称海事管理机构)依据各自的职责权限，对所辖内河通航水域实施水上交通安全监督管理。\n第五条 县级以上地方各级人民政府应当加强本行政区域内的内河交通安全管理工作，建立、健全内河交通安全管理责任制。\n乡(镇)人民政府对本行政区域内的内河交通安全管理履行下列职责：\n(一)建立、健全行政村和船主的船舶安全责任制；\n(二)落实渡口船舶、船员、旅客定额的安全管理责任制；\n(三)落实船舶水上交通安全管理的专门人员；\n(四)督促船舶所有人、经营人和船员遵守有关内河交通安全的法律、法规和规章。","level":1},{"name":"第二章 船舶、浮动设施和船员","text":"第六条 船舶具备下列条件，方可航行：\n(一)经海事管理机构认可的船舶检验机构依法检验并持有合格的船舶检验证书；\n(二)经海事管理机构依法登记并持有船舶登记证书；\n(三)配备符合国务院交通主管部门规定的船员；\n(四)配备必要的航行资料。\n第七条 浮动设施具备下列条件，方可从事有关活动：\n(一)经海事管理机构认可的船舶检验机构依法检验并持有合格的检验证书；\n(二)经海事管理机构依法登记并持有登记证书；\n(三)配备符合国务院交通主管部门规定的掌握水上交通安全技能的船员。\n第八条 船舶、浮动设施应当保持适于安全航行、停泊或者从事有关活动的状态。\n船舶、浮动设施的配载和系固应当符合国家安全技术规范。\n第九条 船员经水上交通安全专业培训，其中客船和载运危险货物船舶的船员还应当经相应的特殊培训，并经海事管理机构考试合格，取得相应的适任证书或者其他适任证件，方可担任船员职务。严禁未取得适任证书或者其他适任证件的船员上岗。\n船员应当遵守职业道德，提高业务素质，严格依法履行职责。\n第十条 船舶、浮动设施的所有人或者经营人，应当加强对船舶、浮动设施的安全管理，建立、健全相应的交通安全管理制度，并对船舶、浮动设施的交通安全负责；不得聘用无适任证书或者其他适任证件的人员担任船员；不得指使、强令船员违章操作。\n第十一条 船舶、浮动设施的所有人或者经营人，应当根据船舶、浮动设施的技术性能、船员状况、水域和水文气象条件，合理调度船舶或者使用浮动设施。\n第十二条 按照国家规定必须取得船舶污染损害责任、沉船打捞责任的保险文书或者财务保证书的船舶，其所有人或者经营人必须取得相应的保险文书或者财务担保证明，并随船携带其副本。\n第十三条 禁止伪造、变造、买卖、租借、冒用船舶检验证书、船舶登记证书、船员适任证书或者其他适任证件。","level":1},{"name":"第三章 航行、停泊和作业","text":"第十四条 船舶在内河航行，应当悬挂国旗，标明船名、船籍港、载重线。\n按照国家规定应当报废的船舶、浮动设施，不得航行或者作业。\n第十五条 船舶在内河航行，应当保持瞭望，注意观察，并采用安全航速航行。船舶安全航速应当根据能见度、通航密度、船舶操纵性能和风、浪、水流、航路状况以及周围环境等主要因素决定。使用雷达的船舶，还应当考虑雷达设备的特性、效率和局限性。\n船舶在限制航速的区域和汛期高水位期间，应当按照海事管理机构规定的航速航行。\n第十六条 船舶在内河航行时，上行船舶应当沿缓流或者航路一侧航行，下行船舶应当沿主流或者航路中间航行；在潮流河段、湖泊、水库、平流区域，应当尽可能沿本船右舷一侧航路航行。\n第十七条 船舶在内河航行时，应当谨慎驾驶，保障安全；对来船动态不明、声号不统一或者遇有紧迫情况时，应当减速、停车或者倒车，防止碰撞。\n船舶相遇，各方应当注意避让。按照船舶航行规则应当让路的船舶，必须主动避让被让路船舶；被让路船舶应当注意让路船舶的行动，并适时采取措施，协助避让。\n船舶避让时，各方避让意图经统一后，任何一方不得擅自改变避让行动。\n船舶航行、避让和信号显示的具体规则，由国务院交通主管部门制定。\n第十八条 船舶进出内河港口，应当向海事管理机构报告船舶的航次计划、适航状态、船员配备和载货载客等情况。\n第十九条 下列船舶在内河航行，应当向引航机构申请引航：\n(一)外国籍船舶；\n(二)1000总吨以上的海上机动船舶，但船长驾驶同一类型的海上机动船舶在同一内河通航水域航行与上一航次间隔2个月以内的除外；\n(三)通航条件受限制的船舶；\n(四)国务院交通主管部门规定应当申请引航的客船、载运危险货物的船舶。\n第二十条 船舶进出港口和通过交通管制区、通航密集区或者航行条件受限制的区域，应当遵守海事管理机构发布的有关通航规定。\n任何船舶不得擅自进入或者穿越海事管理机构公布的禁航区。\n第二十一条 从事货物或者旅客运输的船舶，必须符合船舶强度、稳性、吃水、消防和救生等安全技术要求和国务院交通主管部门规定的载货或者载客条件。\n任何船舶不得超载运输货物或者旅客。\n第二十二条 船舶在内河通航水域载运或者拖带超重、超长、超高、超宽、半潜的物体，必须在装船或者拖带前24小时报海事管理机构核定拟航行的航路、时间，并采取必要的安全措施，保障船舶载运或者拖带安全。船舶需要护航的，应当向海事管理机构申请护航。\n第二十三条 遇有下列情形之一时，海事管理机构可以根据情况采取限时航行、单航、封航等临时性限制、疏导交通的措施，并予公告：\n(一)恶劣天气；\n(二)大范围水上施工作业；\n(三)影响航行的水上交通事故；\n(四)水上大型群众性活动或者体育比赛；\n(五)对航行安全影响较大的其他情形。\n第二十四条 船舶应当在码头、泊位或者依法公布的锚地、停泊区、作业区停泊；遇有紧急情况，需要在其他水域停泊的，应当向海事管理机构报告。\n船舶停泊，应当按照规定显示信号，不得妨碍或者危及其他船舶航行、停泊或者作业的安全。\n船舶停泊，应当留有足以保证船舶安全的船员值班。\n第二十五条 在内河通航水域或者岸线上进行下列可能影响通航安全的作业或者活动的，应当在进行作业或者活动前报海事管理机构批准：\n(一)勘探、采掘、爆破；\n(二)构筑、设置、维修、拆除水上水下构筑物或者设施；\n(三)架设桥梁、索道；\n(四)铺设、检修、拆除水上水下电缆或者管道；\n(五)设置系船浮筒、浮趸、缆桩等设施；\n(六)航道建设，航道、码头前沿水域疏浚；\n(七)举行大型群众性活动、体育比赛。\n进行前款所列作业或者活动，需要进行可行性研究的，在进行可行性研究时应当征求海事管理机构的意见；依照法律、行政法规的规定，需经其他有关部门审批的，还应当依法办理有关审批手续。\n第二十六条 海事管理机构审批本条例第二十五条规定的作业或者活动，应当自收到申请之日起30日内作出批准或者不批准的决定，并书面通知申请人。\n遇有紧急情况，需要对航道进行修复或者对航道、码头前沿水域进行疏浚的，作业人可以边申请边施工。\n第二十七条 航道内不得养殖、种植植物、水生物和设置永久性固定设施。\n划定航道，涉及水产养殖区的，航道主管部门应当征求渔业行政主管部门的意见；设置水产养殖区，涉及航道的，渔业行政主管部门应当征求航道主管部门和海事管理机构的意见。\n第二十八条 在内河通航水域进行下列可能影响通航安全的作业，应当在进行作业前向海事管理机构备案：\n(一)气象观测、测量、地质调查；\n(二)航道日常养护；\n(三)大面积清除水面垃圾；\n(四)可能影响内河通航水域交通安全的其他行为。\n第二十九条 进行本条例第二十五条、第二十八条规定的作业或者活动时，应当在作业或者活动区域设置标志和显示信号，并按照海事管理机构的规定，采取相应的安全措施，保障通航安全。\n前款作业或者活动完成后，不得遗留任何妨碍航行的物体。","level":1},{"name":"第四章 危险货物监管","text":"第三十条 从事危险货物装卸的码头、泊位，必须符合国家有关安全规范要求，并征求海事管理机构的意见，经验收合格后，方可投入使用。\n禁止在内河运输法律、行政法规以及国务院交通主管部门规定禁止运输的危险货物。\n第三十一条 载运危险货物的船舶，必须持有经海事管理机构认可的船舶检验机构依法检验并颁发的危险货物适装证书，并按照国家有关危险货物运输的规定和安全技术规范进行配载和运输。\n第三十二条 船舶装卸、过驳危险货物或者载运危险货物进出港口，应当将危险货物的名称、特性、包装、装卸或者过驳的时间、地点以及进出港时间等事项，事先报告海事管理机构和港口管理机构，经其同意后，方可进行装卸、过驳作业或者进出港口；但是，定船、定线、定货的船舶可以定期报告。\n第三十三条 载运危险货物的船舶，在航行、装卸或者停泊时，应当按照规定显示信号；其他船舶应当避让。\n第三十四条 从事危险货物装卸的码头、泊位和载运危险货物的船舶，必须编制危险货物事故应急预案，并配备相应的应急救援设备和器材。","level":1},{"name":"第五章 渡口管理","text":"第三十五条 设置或者撤销渡口，应当经渡口所在地的县级人民政府审批；县级人民政府审批前，应当征求当地海事管理机构的意见。\n第三十六条 渡口的设置应当具备下列条件：\n(一)选址应当在水流平缓、水深足够、坡岸稳定、视野开阔、适宜船舶停靠的地点，并远离危险物品生产、堆放场所；\n(二)具备货物装卸、旅客上下的安全设施；\n(三)配备必要的救生设备和专门管理人员。\n第三十七条 渡口经营者应当在渡口设置明显的标志，维护渡运秩序，保障渡运安全。\n渡口所在地县级人民政府应当建立、健全渡口安全管理责任制，指定有关部门负责对渡口和渡运安全实施监督检查。\n第三十八条 渡口工作人员应当经培训、考试合格，并取得渡口所在地县级人民政府指定的部门颁发的合格证书。\n渡口船舶应当持有合格的船舶检验证书和船舶登记证书。\n第三十九条 渡口载客船舶应当有符合国家规定的识别标志，并在明显位置标明载客定额、安全注意事项。\n渡口船舶应当按照渡口所在地的县级人民政府核定的路线渡运，并不得超载；渡运时，应当注意避让过往船舶，不得抢航或者强行横越。\n遇有洪水或者大风、大雾、大雪等恶劣天气，渡口应当停止渡运。","level":1},{"name":"第六章 通航保障","text":"第四十条 内河通航水域的航道、航标和其他标志的规划、建设、设置、维护，应当符合国家规定的通航安全要求。\n第四十一条 内河航道发生变迁，水深、宽度发生变化，或者航标发生位移、损坏、灭失，影响通航安全的，航道、航标主管部门必须及时采取措施，使航道、航标保持正常状态。\n第四十二条 内河通航水域内可能影响航行安全的沉没物、漂流物、搁浅物，其所有人和经营人，必须按照国家有关规定设置标志，向海事管理机构报告，并在海事管理机构限定的时间内打捞清除；没有所有人或者经营人的，由海事管理机构打捞清除或者采取其他相应措施，保障通航安全。\n第四十三条 在内河通航水域中拖放竹、木等物体，应当在拖放前24小时报经海事管理机构同意，按照核定的时间、路线拖放，并采取必要的安全措施，保障拖放安全。\n第四十四条 任何单位和个人发现下列情况，应当迅速向海事管理机构报告：\n(一)航道变迁，航道水深、宽度发生变化；\n(二)妨碍通航安全的物体；\n(三)航标发生位移、损坏、灭失；\n(四)妨碍通航安全的其他情况。\n海事管理机构接到报告后，应当根据情况发布航行通告或者航行警告，并通知航道、航标主管部门。\n第四十五条 海事管理机构划定或者调整禁航区、交通管制区、港区外锚地、停泊区和安全作业区，以及对进行本条例第二十五条、第二十八条规定的作业或者活动，需要发布航行通告、航行警告的，应当及时发布。","level":1},{"name":"第七章 救助","text":"第四十六条 船舶、浮动设施遇险，应当采取一切有效措施进行自救。\n船舶、浮动设施发生碰撞等事故，任何一方应当在不危及自身安全的情况下，积极救助遇险的他方，不得逃逸。\n船舶、浮动设施遇险，必须迅速将遇险的时间、地点、遇险状况、遇险原因、救助要求，向遇险地海事管理机构以及船舶、浮动设施所有人、经营人报告。\n第四十七条 船员、浮动设施上的工作人员或者其他人员发现其他船舶、浮动设施遇险，或者收到求救信号后，必须尽力救助遇险人员，并将有关情况及时向遇险地海事管理机构报告。\n第四十八条 海事管理机构收到船舶、浮动设施遇险求救信号或者报告后，必须立即组织力量救助遇险人员，同时向遇险地县级以上地方人民政府和上级海事管理机构报告。\n遇险地县级以上地方人民政府收到海事管理机构的报告后，应当对救助工作进行领导和协调，动员各方力量积极参与救助。\n第四十九条 船舶、浮动设施遇险时，有关部门和人员必须积极协助海事管理机构做好救助工作。\n遇险现场和附近的船舶、人员，必须服从海事管理机构的统一调度和指挥。","level":1},{"name":"第八章 事故调查处理","text":"第五十条 船舶、浮动设施发生交通事故，其所有人或者经营人必须立即向交通事故发生地海事管理机构报告，并做好现场保护工作。\n第五十一条 海事管理机构接到内河交通事故报告后，必须立即派员前往现场，进行调查和取证。\n海事管理机构进行内河交通事故调查和取证，应当全面、客观、公正。\n第五十二条 接受海事管理机构调查、取证的有关人员，应当如实提供有关情况和证据，不得谎报或者隐匿、毁灭证据。\n第五十三条 海事管理机构应当在内河交通事故调查、取证结束后30日内，依据调查事实和证据作出调查结论，并书面告知内河交通事故当事人。\n第五十四条 海事管理机构在调查处理内河交通事故过程中，应当采取有效措施，保证航路畅通，防止发生其他事故。\n第五十五条 地方人民政府应当依照国家有关规定积极做好内河交通事故的善后工作。\n第五十六条 特大内河交通事故的报告、调查和处理，按照国务院有关规定执行。","level":1},{"name":"第九章 监督检查","text":"第五十七条 在旅游、交通运输繁忙的湖泊、水库，在气候恶劣的季节，在法定或者传统节日、重大集会、集市、农忙、学生放学放假等交通高峰期间，县级以上地方各级人民政府应当加强对维护内河交通安全的组织、协调工作。\n第五十八条 海事管理机构必须建立、健全内河交通安全监督检查制度，并组织落实。\n第五十九条 海事管理机构必须依法履行职责，加强对船舶、浮动设施、船员和通航安全环境的监督检查。发现内河交通安全隐患时，应当责令有关单位和个人立即消除或者限期消除；有关单位和个人不立即消除或者逾期不消除的，海事管理机构必须采取责令其临时停航、停止作业，禁止进港、离港等强制性措施。\n第六十条 对内河交通密集区域、多发事故水域以及货物装卸、乘客上下比较集中的港口，对客渡船、滚装客船、高速客轮、旅游船和载运危险货物的船舶，海事管理机构必须加强安全巡查。\n第六十一条 海事管理机构依照本条例实施监督检查时，可以根据情况对违反本条例有关规定的船舶，采取责令临时停航、驶向指定地点，禁止进港、离港，强制卸载、拆除动力装置、暂扣船舶等保障通航安全的措施。\n第六十二条 海事管理机构的工作人员依法在内河通航水域对船舶、浮动设施进行内河交通安全监督检查，任何单位和个人不得拒绝或者阻挠。\n有关单位或者个人应当接受海事管理机构依法实施的安全监督检查，并为其提供方便。\n海事管理机构的工作人员依照本条例实施监督检查时，应当出示执法证件，表明身份。","level":1},{"name":"第十章 法律责任","text":"第六十三条 违反本条例的规定，应当报废的船舶、浮动设施在内河航行或者作业的，由海事管理机构责令停航或者停止作业，并对船舶、浮动设施予以没收。\n第六十四条 违反本条例的规定，船舶、浮动设施未持有合格的检验证书、登记证书或者船舶未持有必要的航行资料，擅自航行或者作业的，由海事管理机构责令停止航行或者作业；拒不停止的，暂扣船舶、浮动设施；情节严重的，予以没收。\n第六十五条 违反本条例的规定，船舶未按照国务院交通主管部门的规定配备船员擅自航行，或者浮动设施未按照国务院交通主管部门的规定配备掌握水上交通安全技能的船员擅自作业的，由海事管理机构责令限期改正，对船舶、浮动设施所有人或者经营人处1万元以上10万元以下的罚款；逾期不改正的，责令停航或者停止作业。\n第六十六条 违反本条例的规定，未经考试合格并取得适任证书或者其他适任证件的人员擅自从事船舶航行的，由海事管理机构责令其立即离岗，对直接责任人员处2000元以上2万元以下的罚款，并对聘用单位处1万元以上10万元以下的罚款。\n第六十七条 违反本条例的规定，按照国家规定必须取得船舶污染损害责任、沉船打捞责任的保险文书或者财务保证书的船舶的所有人或者经营人，未取得船舶污染损害责任、沉船打捞责任保险文书或者财务担保证明的，由海事管理机构责令限期改正；逾期不改正的，责令停航，并处1万元以上10万元以下的罚款。\n第六十八条 违反本条例的规定，船舶在内河航行时，有下列情形之一的，由海事管理机构责令改正，处5000元以上5万元以下的罚款；情节严重的，禁止船舶进出港口或者责令停航，并可以对责任船员给予暂扣适任证书或者其他适任证件3个月至6个月的处罚：\n(一)未按照规定悬挂国旗，标明船名、船籍港、载重线的；\n(二)未按照规定向海事管理机构报告船舶的航次计划、适航状态、船员配备和载货载客等情况的；\n(三)未按照规定申请引航的；\n(四)擅自进出内河港口，强行通过交通管制区、通航密集区、航行条件受限制区域或者禁航区的；\n(五)载运或者拖带超重、超长、超高、超宽、半潜的物体，未申请或者未按照核定的航路、时间航行的。\n第六十九条 违反本条例的规定，船舶未在码头、泊位或者依法公布的锚地、停泊区、作业区停泊的，由海事管理机构责令改正；拒不改正的，予以强行拖离，因拖离发生的费用由船舶所有人或者经营人承担。\n第七十条 违反本条例的规定，在内河通航水域或者岸线上进行有关作业或者活动未经批准或者备案，或者未设置标志、显示信号的，由海事管理机构责令改正，处5000元以上5万元以下的罚款。\n第七十一条 违反本条例的规定，从事危险货物作业，有下列情形之一的，由海事管理机构责令停止作业或者航行，对负有责任的主管人员或者其他直接责任人员处2万元以上10万元以下的罚款；属于船员的，并给予暂扣适任证书或者其他适任证件6个月以上直至吊销适任证书或者其他适任证件的处罚：\n(一)从事危险货物运输的船舶，未编制危险货物事故应急预案或者未配备相应的应急救援设备和器材的；\n(二)船舶装卸、过驳危险货物或者载运危险货物进出港口未经海事管理机构、港口管理机构同意的。\n未持有危险货物适装证书擅自载运危险货物或者未按照安全技术规范进行配载和运输的，依照《危险化学品安全管理条例》的规定处罚。\n第七十二条 违反本条例的规定，未经批准擅自设置或者撤销渡口的，由渡口所在地县级人民政府指定的部门责令限期改正；逾期不改正的，予以强制拆除或者恢复，因强制拆除或者恢复发生的费用分别由设置人、撤销人承担。\n第七十三条 违反本条例的规定，渡口船舶未标明识别标志、载客定额、安全注意事项的，由渡口所在地县级人民政府指定的部门责令改正，处2000元以上1万元以下的罚款；逾期不改正的，责令停航。\n第七十四条 违反本条例的规定，在内河通航水域的航道内养殖、种植植物、水生物或者设置永久性固定设施的，由海事管理机构责令限期改正；逾期不改正的，予以强制清除，因清除发生的费用由其所有人或者经营人承担。\n第七十五条 违反本条例的规定，内河通航水域中的沉没物、漂流物、搁浅物的所有人或者经营人，未按照国家有关规定设置标志或者未在规定的时间内打捞清除的，由海事管理机构责令限期改正；逾期不改正的，海事管理机构强制设置标志或者组织打捞清除；需要立即组织打捞清除的，海事管理机构应当及时组织打捞清除。海事管理机构因设置标志或者打捞清除发生的费用，由沉没物、漂流物、搁浅物的所有人或者经营人承担。\n第七十六条 违反本条例的规定，船舶、浮动设施遇险后未履行报告义务或者不积极施救的，由海事管理机构给予警告，并可以对责任船员给予暂扣适任证书或者其他适任证件3个月至6个月直至吊销适任证书或者其他适任证件的处罚。\n第七十七条 违反本条例的规定，船舶、浮动设施发生内河交通事故的，除依法承担相应的法律责任外，由海事管理机构根据调查结论，对责任船员给予暂扣适任证书或者其他适任证件6个月以上直至吊销适任证书或者其他适任证件的处罚。\n第七十八条 违反本条例的规定，遇险现场和附近的船舶、船员不服从海事管理机构的统一调度和指挥的，由海事管理机构给予警告，并可以对责任船员给予暂扣适任证书或者其他适任证件3个月至6个月直至吊销适任证书或者其他适任证件的处罚。\n第七十九条 违反本条例的规定，伪造、变造、买卖、转借、冒用船舶检验证书、船舶登记证书、船员适任证书或者其他适任证件的，由海事管理机构没收有关的证书或者证件；有违法所得的，没收违法所得，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足2万元的，处1万元以上5万元以下的罚款；触犯刑律的，依照刑法关于伪造、变造、买卖国家机关公文、证件罪或者其他罪的规定，依法追究刑事责任。\n第八十条 违反本条例的规定，船舶、浮动设施的所有人或者经营人指使、强令船员违章操作的，由海事管理机构给予警告，处1万元以上5万元以下的罚款，并可以责令停航或者停止作业；造成重大伤亡事故或者严重后果的，依照刑法关于重大责任事故罪或者其他罪的规定，依法追究刑事责任。\n第八十一条 违反本条例的规定，船舶在内河航行、停泊或者作业，不遵守航行、避让和信号显示规则的，由海事管理机构责令改正，处1000元以上1万元以下的罚款；情节严重的，对责任船员给予暂扣适任证书或者其他适任证件3个月至6个月直至吊销适任证书或者其他适任证件的处罚；造成重大内河交通事故的，依照刑法关于交通肇事罪或者其他罪的规定，依法追究刑事责任。\n第八十二条 违反本条例的规定，船舶不具备安全技术条件从事货物、旅客运输，或者超载运输货物、旅客的，由海事管理机构责令改正，处2万元以上10万元以下的罚款，可以对责任船员给予暂扣适任证书或者其他适任证件6个月以上直至吊销适任证书或者其他适任证件的处罚，并对超载运输的船舶强制卸载，因卸载而发生的卸货费、存货费、旅客安置费和船舶监管费由船舶所有人或者经营人承担；发生重大伤亡事故或者造成其他严重后果的，依照刑法关于重大劳动安全事故罪或者其他罪的规定，依法追究刑事责任。\n第八十三条 违反本条例的规定，船舶、浮动设施发生内河交通事故后逃逸的，由海事管理机构对责任船员给予吊销适任证书或者其他适任证件的处罚；证书或者证件吊销后，5年内不得重新从业；触犯刑律的，依照刑法关于交通肇事罪或者其他罪的规定，依法追究刑事责任。\n第八十四条 违反本条例的规定，阻碍、妨碍内河交通事故调查取证，或者谎报、隐匿、毁灭证据的，由海事管理机构给予警告，并对直接责任人员处1000元以上1万元以下的罚款；属于船员的，并给予暂扣适任证书或者其他适任证件12个月以上直至吊销适任证书或者其他适任证件的处罚；以暴力、威胁方法阻碍内河交通事故调查取证的，依照刑法关于妨害公务罪的规定，依法追究刑事责任。\n第八十五条 违反本条例的规定，海事管理机构不依据法定的安全条件进行审批、许可的，对负有责任的主管人员和其他直接责任人员根据不同情节，给予降级或者撤职的行政处分；造成重大内河交通事故或者致使公共财产、国家和人民利益遭受重大损失的，依照刑法关于滥用职权罪、玩忽职守罪或者其他罪的规定，依法追究刑事责任。\n第八十六条 违反本条例的规定，海事管理机构对审批、许可的安全事项不实施监督检查的，对负有责任的主管人员和其他直接责任人员根据不同情节，给予记大过、降级或者撤职的行政处分；造成重大内河交通事故或者致使公共财产、国家和人民利益遭受重大损失的，依照刑法关于滥用职权罪、玩忽职守罪或者其他罪的规定，依法追究刑事责任。\n第八十七条 违反本条例的规定，海事管理机构发现船舶、浮动设施不再具备安全航行、停泊、作业条件而不及时撤销批准或者许可并予以处理的，对负有责任的主管人员和其他直接责任人员根据不同情节，给予记大过、降级或者撤职的行政处分；造成重大内河交通事故或者致使公共财产、国家和人民利益遭受重大损失的，依照刑法关于滥用职权罪、玩忽职守罪或者其他罪的规定，依法追究刑事责任。\n第八十八条 违反本条例的规定，海事管理机构对未经审批、许可擅自从事旅客、危险货物运输的船舶不实施监督检查，或者发现内河交通安全隐患不及时依法处理，或者对违法行为不依法予以处罚的，对负有责任的主管人员和其他直接责任人员根据不同情节，给予降级或者撤职的行政处分；造成重大内河交通事故或者致使公共财产、国家和人民利益遭受重大损失的，依照刑法关于滥用职权罪、玩忽职守罪或者其他罪的规定，依法追究刑事责任。\n第八十九条 违反本条例的规定，渡口所在地县级人民政府指定的部门，有下列情形之一的，根据不同情节，对负有责任的主管人员和其他直接责任人员，给予降级或者撤职的行政处分；造成重大内河交通事故或者致使公共财产、国家和人民利益遭受重大损失的，依照刑法关于滥用职权罪、玩忽职守罪或者其他罪的规定，依法追究刑事责任：\n(一)对县级人民政府批准的渡口不依法实施监督检查的；\n(二)对未经县级人民政府批准擅自设立的渡口不予以查处的；\n(三)对渡船超载、人与大牲畜混载、人与爆炸品、压缩气体和液化气体、易燃液体、易燃固体、自燃物品和遇湿易燃物品、氧化剂和有机过氧化物、有毒品和腐蚀品等危险品混载以及其他危及安全的行为不及时纠正并依法处理的。\n第九十条 违反本条例的规定，触犯《中华人民共和国治安管理处罚法》，构成违反治安管理行为的，由公安机关给予治安管理处罚。","level":1},{"name":"第十一章 附则","text":"第九十一条 本条例下列用语的含义：\n(一)内河通航水域，是指由海事管理机构认定的可供船舶航行的江、河、湖泊、水库、运河等水域。\n(二)船舶，是指各类排水或者非排水的船、艇、筏、水上飞行器、潜水器、移动式平台以及其他水上移动装置。\n(三)浮动设施，是指采用缆绳或者锚链等非刚性固定方式系固并漂浮或者潜于水中的建筑、装置。\n(四)交通事故，是指船舶、浮动设施在内河通航水域发生的碰撞、触碰、触礁、浪损、搁浅、火灾、爆炸、沉没等引起人身伤亡和财产损失的事件。\n第九十二条 军事船舶在内河通航水域航行，应当遵守内河航行、避让和信号显示规则。军事船舶的检验、登记和船员的考试、发证等管理办法，按照国家有关规定执行。\n第九十三条 渔船的登记以及进出渔港报告，渔船船员的考试、发证，渔船之间交通事故的调查处理，以及渔港水域内渔船的交通安全管理办法，由国务院渔业行政主管部门依据本条例另行规定。\n渔业船舶的检验及相关监督管理，由国务院交通运输主管部门按照相关渔业船舶检验的行政法规执行。\n第九十四条 城市园林水域水上交通安全管理的具体办法，由省、自治区、直辖市人民政府制定；但是，有关船舶检验、登记和船员管理，依照国家有关规定执行。\n第九十五条 本条例自2002年8月1日起施行。1986年12月16日国务院发布的《中华人民共和国内河交通安全管理条例》同时废止。","level":1}]},{"id":"n0334","sections":[{"name":"","text":"传统工艺美术保护条例\n(1997年5月20日中华人民共和国国务院令第217号发布 根据2013年7月18日《国务院关于废止和修改部分行政法规的决定》修订)\n第一条 为了保护传统工艺美术，促进传统工艺美术事业的繁荣与发展，制定本条例。\n第二条 本条例所称传统工艺美术，是指百年以上，历史悠久，技艺精湛，世代相传，有完整的工艺流程，采用天然原材料制作，具有鲜明的民族风格和地方特色，在国内外享有声誉的手工艺品种和技艺。\n第三条 国家对传统工艺美术品种和技艺实行保护、发展、提高的方针。\n地方各级人民政府应当加强对传统工艺美术保护工作的领导，采取有效措施，扶持和促进本地区传统工艺美术事业的繁荣和发展。\n第四条 国务院负责传统工艺美术保护工作的部门负责全国传统工艺美术保护工作。\n第五条 国家对传统工艺美术品种和技艺实行认定制度。符合本条例第二条规定条件的工艺美术品种和技艺，依照本条例的规定认定为传统工艺美术品种和技艺。\n第六条 传统工艺美术品种和技艺，由国务院负责传统工艺美术保护工作的部门聘请专家组成评审委员会进行评审；国务院负责传统工艺美术保护工作的部门根据评审委员会的评审结论，予以认定和公布。\n第七条 制作传统工艺美术产品的企业和个人，可以向当地县级人民政府负责传统工艺美术保护工作的部门提出要求保护的品种和技艺的申请，由省、自治区、直辖市人民政府负责传统工艺美术保护工作的部门审核后，向国务院负责传统工艺美术保护工作的部门推荐。\n第八条 申请认定传统工艺美术品种和技艺的企业和个人，应当按照国务院负责传统工艺美术保护工作的部门的规定，提交完整、详实的资料。\n第九条 国家对认定的传统工艺美术技艺采取下列保护措施：\n(一)搜集、整理、建立档案；\n(二)征集、收藏优秀代表作品；\n(三)对其工艺技术秘密确定密级，依法实施保密；\n(四)资助研究，培养人才。\n第十条 传统工艺美术品种中的卓越作品，经国务院负责传统工艺美术保护工作的部门聘请专家组成评审委员会进行评审后，由国务院负责传统工艺美术保护工作的部门命名为中国工艺美术珍品(以下简称珍品)。\n第十一条 国家对珍品采取下列保护措施：\n(一)国家征集、收购的珍品由中国工艺美术馆或者省、自治区、直辖市工艺美术馆、博物馆珍藏。\n(二)珍品禁止出口。珍品出国展览必须经国务院负责传统工艺美术保护工作的部门会同国务院有关部门批准。\n第十二条 符合下列条件并长期从事传统工艺美术制作的人员，由相关行业协会组织评审，可以授予中国工艺美术大师称号：\n(一)成就卓越，在国内外享有声誉的；\n(二)技艺精湛，自成流派的。\n第十三条 县级以上人民政府有关部门对制作传统工艺美术品种特需的天然原料、材料，应当统筹规划、妥善安排。\n第十四条 对制作传统工艺美术品种特需的宝石、玉石等珍稀矿种，国家依法加强保护，严禁乱采滥挖。\n第十五条 国家鼓励地方各级人民政府根据本地区实际情况，采取必要措施，发掘和抢救传统工艺美术技艺，征集传统工艺美术精品，培养传统工艺美术技艺人才，资助传统工艺美术科学研究。\n第十六条 对于制作经济效益不高、艺术价值很高并且面临失传的工艺美术品种的企业，各级人民政府应当采取必要措施，给予扶持和帮助。\n第十七条 制作传统工艺美术产品的企业应当建立、健全传统工艺美术技艺的保护或者保密制度，切实加强对传统工艺美术技艺的管理。\n从事传统工艺美术产品制作的人员，应当遵守国家有关法律、法规的规定，不得泄露在制作传统工艺美术产品过程中知悉的技术秘密和其他商业秘密。\n第十八条 国家对在继承、保护、发展传统工艺美术事业中做出突出贡献的单位和个人，给予奖励。\n第十九条 违反本条例规定，有下列行为之一的，由有关部门依照有关法律、行政法规的规定，给予行政处分或者行政处罚；构成犯罪的，依法追究刑事责任：\n(一)窃取或者泄露传统工艺美术技艺秘密的；\n(二)非法开采用于制作传统工艺美术的珍稀矿产资源或者盗卖用于制作传统工艺美术的珍稀矿产品的；\n(三)私运珍品出境的。\n制作、出售假冒中国工艺美术大师署名的传统工艺美术作品的，应当依法承担民事责任；有关部门可以依照有关法律、行政法规的规定给予行政处罚。\n第二十条 本条例自发布之日起施行。","level":0}]},{"id":"n0335","sections":[{"name":"","text":"中华人民共和国邮政法实施细则\n(1990年11月12日中华人民共和国国务院令第65号发布 自发布之日起施行)","level":0},{"name":"第一章 总则","text":"第一条 根据《中华人民共和国邮政法》(以下简称《邮政法》)的规定，制定本实施细则。\n第二条 中华人民共和国邮电部(以下简称邮电部)是国务院邮政主管部门，管理全国邮政工作。\n各省、自治区、直辖市邮电管理局(以下简称邮电管理局)是地区邮政管理机构，管理该地区的邮政工作。\n第三条 市、县邮电局(含邮政局，下同)是全民所有制的经营邮政业务的公用企业(以下简称邮政企业)，经邮电管理局授权，管理该地区的邮政工作。\n邮电支局、邮电所、邮政支局、邮政所是办理邮政业务的分支机构(以下简称分支机构)；邮亭、邮政报刊亭等是邮政企业的服务点。\n邮电代办所视同邮政企业所属的分支机构。\n第四条 未经邮政企业委托，任何单位或者个人不得经营信函、明信片或者其他具有信件性质的物品的寄递业务，但国务院另有规定的除外。\n信函是指以套封形式传递的缄封的信息的载体。其他具有信件性质的物品是指以符号、图像、音响等方式传递的信息的载体。具体内容由邮电部规定。\n第五条 邮政企业委托其他单位或者个人代办邮政业务时，应当协商一致，并签订代办合同。\n第六条 凡使用我国邮政业务的一切单位或者个人统称邮政用户(以下简称用户)。\n第七条 邮政企业应当为用户提供迅速、准确、安全、方便的邮政服务，保障用户使用邮政的合法权益。\n任何单位或者个人均负有保护通信自由、通信秘密和邮件安全的责任；任何单位或者个人不得利用邮政业务进行法律、法规和政策所禁止的活动。\n除因国家安全或者追查刑事犯罪需要，由公安机关、国家安全机关或者检察机关依法对通信进行检查外，邮件在运输、传递过程中，任何单位或者个人不得以任何理由检查、扣留。\n第八条 因国家安全或者追查刑事犯罪需要，公安机关、国家安全机关、检察机关检查、扣留邮件，冻结汇款、储蓄存款时，必须依法向相关县或者县级以上的邮政企业、邮电管理局出具相应的检查、扣留、冻结通知书，并开列邮件、汇款、储蓄存款的具体节目，办理检查、扣留、冻结手续后，由邮政企业指派专人负责拣出，逐件登记后办理交接手续；对于不需要继续检查、扣留、冻结或者查明与案件无关的邮件、汇款、储蓄存款，应当及时退还邮政企业。邮件、汇款、储蓄存款在检查、扣留、冻结期间造成丢失、损毁的，由相关的公安机关、国家安全机关、检察机关负责赔偿。\n第九条 人民法院、检察机关依法没收国内邮件、汇款、储蓄存款时，必须出具法律文书，向相关县或者县级以上邮政企业、邮电管理局办理手续。没收进出口国际邮递物品应当由海关作出决定，并办理手续。\n第十条 有关单位依照法律规定需要收集、调取证据、查阅邮政业务档案时，必须凭相关邮政企业所在地的公安机关、国家安全机关、检察机关、人民法院出具的书面证明，并开列邮件具体节目，向相关县或者县级以上的邮政企业、邮电管理局办理手续。\n第十一条 任何单位或者个人不得从事下列行为妨害邮政工作的正常进行：\n(一)损坏邮政设施；\n(二)在邮政企业及分支机构门前或者出入通道设摊、堆物，妨害用户用邮或者影响运邮车辆通行；\n(三)在办理邮政业务的场所无理取闹或者扰乱正常秩序；\n(四)阻碍邮政工作人员依法执行公务或者寻衅滋事；\n(五)拦截邮政运输工具、非法阻碍邮件运递或者强行登乘邮政运输工具；\n(六)非法检查或者截留邮件；\n(七)其他妨害邮政企业及分支机构或者邮政工作人员正常工作的行为。","level":1},{"name":"第二章 邮政企业的设置和邮政设施","text":"第十二条 邮政企业及分支机构的设置标准，由邮电部规定；邮政企业的设置或者撤销，由邮电部批准；分支机构的设置或者撤销，由邮电管理局批准，报邮电部备案。\n第十三条 地方各级人民政府应当将邮政企业及分支机构的设置和邮政设施的建设纳入城乡建设规划。\n第十四条 建设城市新区、独立工矿区、住宅区或者旧城区成片改造，应当同时规划和设置与之配套的邮政企业及分支机构和邮政设施。\n第十五条 邮政企业依法设置邮亭、邮政报刊亭、邮筒、信箱或者流动服务时，有关单位或者个人应当提供方便。\n第十六条 接收邮件的信报箱是居民楼房的配套设施，设计单位应当将其纳入民用住宅建筑设计标准。\n居民楼房每一单元的地面层应当安装与住户房号相适应的信报箱或者在楼房集中处设置信报箱间(群)，供住户接收邮件使用。\n信报箱由居民楼房的产权所有者或者管理单位负责维修、更换，也可以委托当地邮政企业或者其分支机构维修、更换，所需工料费由委托单位支付。\n第十七条 较大的车站、机场、港口、饭店，应当在方便旅客的地方提供办理邮政业务的场所；邮政企业应当提供邮政业务服务。\n第十八条 任何单位因建设需要，征用、拆迁邮政企业及分支机构或者邮政设施时，应当与当地邮政企业协商，在保证邮政通信正常进行的情况下，应当将邮政企业及分支机构、邮政设施迁至适宜的地方或者另建，所需费用由征用、拆迁单位承担。","level":1},{"name":"第三章 邮政业务的种类","text":"第十九条 邮政企业经营国内、国际邮件的寄递业务和邮件的特快专递业务。\n国内邮件是指在中华人民共和国领域内互寄的邮件，其中寄自或者寄往香港、澳门、台湾地区的邮件称港澳台地区邮件；国际邮件是指中华人民共和国与其他国家、地区之间互寄的邮件和其他国家、地区通过中国境内经转的邮件。\n第二十条 国内报刊发行业务是指报刊社委托邮政企业发行报纸、杂志的业务。\n第二十一条 报刊社委托邮政企业发行报刊时，应当根据报刊发行的范围向指定的邮政企业或者邮政报刊发行局，出具有关主管部门批准出版和领有报纸、期刊登记证的证明。邮政企业有接办发行能力的，应当与报刊社遵循平等互利、协商一致、等价有偿的原则，按照国家有关规定签订报刊发行合同。\n第二十二条 邮政储蓄、邮政汇兑业务是邮政企业为国家积聚资金、沟通经济往来所经办的金融业务，由邮电部统一管理，并按照国家有关规定，在金融业务上接受中国人民银行的指导。各相关银行应当为邮政企业办理的储蓄、汇兑业务提供便利。\n第二十三条 各项邮政业务的具体种类和邮件分类，由邮电部规定。","level":1},{"name":"第四章 邮政业务资费和邮资凭证","text":"第二十四条 邮政业务的基本资费是指邮政专营的国内平常信函、明信片的资费；非基本资费是指基本资费以外的邮政业务资费。\n邮政业务的基本资费由国务院物价主管部门制定，报国务院批准；非基本资费由邮电部规定。\n第二十五条 制定和调整邮政业务资费的依据是：\n(一)以保证邮政通信企业的成本费用和自我发展能力为原则，适应社会需要；\n(二)国内邮政业务资费，依据支出费用的变动相应调整；\n(三)国际邮政业务资费，依据“万国邮政联盟”的规定和国际、国内成本费用以及人民币汇率比价的变化作相应调整。\n第二十六条 邮资凭证是邮电部发行的，作为邮件纳费标志的有价证券，包括邮票，印在邮资信封、邮资明信片、邮资邮简上的邮票图案，邮资机打印的邮资符志。\n第二十七条 “万国邮政联盟”发行的国际回信券，可以根据国际统一规定，兑换成等于特定重量级别的特定类别资费的邮票，但是不得兑换现金。\n第二十八条 因工作需要，仿印邮票图案的，必须按照仿印邮票图案的有关规定，报经邮电部邮票主管部门或者有关邮电管理局审核、批准。\n印刷单位不得承印未经批准的仿印邮票图案和与邮票相似的印件。\n第二十九条 印制通信使用的信封必须符合国家标准，并由当地邮电管理局监制。\n第三十条 印制明信片必须符合邮电部规定的规格标准。\n县以上邮政企业，经邮电管理局批准，可以印制、发行带有“中国人民邮政”字样的明信片；其他单位印制明信片，由当地邮电管理局监制，但不得带有“中国人民邮政”字样。","level":1},{"name":"第五章 邮件的寄递和损失赔偿","text":"第三十一条 义务兵从部队发出的平常信函，免费寄递，其他军人不得免费寄递信函。义务兵寄递平常信函的监督管理办法由邮电部会同中国人民解放军有关部门制定。\n第三十二条 用户交寄邮件应当符合邮电部规定的准寄内容、封装规格、书写格式，并正确书写邮政编码，其中，用户交寄信函使用的信封，必须符合国家标准；邮件封面和邮政业务单式上不得印(写)有或者粘贴与邮件无关的文字或者其他物品；邮资凭证正面不得涂抹、覆盖其他物品；不得使用伪造、仿印、剪割拼补、加工去污的邮资凭证。\n第三十三条 禁止寄递或者在邮件内夹带下列物品：\n(一)法律规定禁止流通或者寄递的物品；\n(二)反动报刊书籍、宣传品或者淫秽物品；\n(三)爆炸性、易燃性、腐蚀性、放射性、毒性等危险物品；\n(四)妨害公共卫生的物品；\n(五)容易腐烂的物品；\n(六)各种活的动物；\n(七)各种货币；\n(八)不适合邮寄条件的物品；\n(九)包装不妥，可能危害人身安全、污染或者损毁其他邮件、设备的物品。\n前款物品，符合邮电部特准交寄规定并确保安全的，可以收寄。\n第三十四条 国内限量寄递物品由邮电部会同国务院有关部门规定。\n第三十五条 对于违反禁寄、限寄规定寄递的物品，邮政企业或者分支机构应当根据其种类、性质、数量等分别作出下列处理：\n(一)不予寄递；\n(二)通知寄件人限期领回，逾期不领的就地处理；\n(三)移送相关部门依法处理；\n(四)造成危害人身安全或者污染、损毁其他邮件、设备的，由寄件人承担赔偿责任。\n按照前款(二)项、(三)项处理所需的费用，由寄件人承担。\n第三十六条 新建的企业、事业、居民住宅，应当由单位或者居民住宅的主管部门到当地邮政企业或者分支机构办理邮件投递登记手续；单位更改名称、收件人变更地址，应当事先通知当地邮政企业或者分支机构，也可以办理邮件改寄新址手续。邮政企业应当公布登记地点和电话号码。\n具备下列条件者，有关邮政企业或者分支机构应当予以登记，并自登记之日起九十日内安排投递：\n(一)具备邮政车辆和邮政工作人员执行公务的通行条件；\n(二)有公安机关统一编制的门牌号数；\n(三)已安装接收邮件的信报箱或者已设立收发室；\n(四)按规定需要办理中外文名称登记的，应当办妥手续。\n第三十七条 邮件的投递方式，除邮电部另有规定外，按下列方式投递：\n(一)按址投递\n城镇居民的邮件，按收件人地址投递到平房院落门口或者楼房地面层的信报箱或者收发室。单位、单位内附设的机构和个人以及单位院内宿舍用户的邮件，投递到单位收发室。收发室应当设在楼房的地面层，两个以上单位同在一处的，应当商定统一接收邮件的地点。需要上楼投递邮件、报刊的，用户应当与相关邮政企业或者分支机构协商，并按照规定由用户支付特殊服务费。\n农村、牧区的邮件，根据交通条件和邮件量的具体情况，一般投递到乡或者行政村的固定地点；乡或者行政村以下的邮件，由乡人民政府或者村民委员会与邮政企业或者分支机构协商妥交收件人的方式。\n寄交船舶的邮件，投递到船舶隶属单位的收发室。\n(二)用户领取\n必须凭通知单到邮政企业或者分支机构办理手续才能领取的邮件，以邮政信箱(用户专用信箱)号码为收件人地址的邮件，存局候领的邮件，超出按址投递规定重量的邮件以及大宗邮件，采用用户领取的方式。\n第三十八条 收件人领取给据邮件，收款人兑领汇款，应当向相关邮政企业或者分支机构交验本人有效证件，并在相关单式上盖章或者签名。\n代收人受收件(款)人委托，代收给据邮件(汇款)时，应当交验收件(款)人和代收人的有效证件，经邮政企业或者分支机构确认后，由代收人盖章或者签名接收。\n有效证件包括居民身份证、户口簿、工作证。\n第三十九条 收件人接收给据邮件时发现封皮破损，应当场声明，并核对内件。确属邮政企业或者分支机构的责任而造成内件短少、损毁的，或者由于邮政企业、分支机构的责任造成给据邮件丢失、损毁的，邮政企业或者分支机构应当按照规定予以赔偿。由于收件人所在单位收发人员的过失造成给据邮件丢失、损毁、内件短少者，相关收发人员应当承担规定的赔偿责任。\n邮件运递的具体要求由邮电部规定，并予以公告。邮件运递违反邮电部规定的，邮政企业或者分支机构应当向用户补偿，具体补偿办法由邮电部规定。\n第四十条 用户误收的邮件，应当及时退还邮政企业或者分支机构；用户误拆的邮件应当重封签章后退还邮政企业或者分支机构，并对误拆邮件的内容保守秘密。\n第四十一条 单位收发人员接收给据邮件时，应当认真点核无误后，在相关清单上盖章签收。\n收发人员对于各种邮件负有保护和及时传送的责任，不得私拆、隐匿、毁弃邮件或者撕揭邮票。","level":1},{"name":"第六章 邮件的运输、验关和检疫","text":"第四十二条 邮电部、邮电管理局应当把邮件运输流向流量变化情况及时通告相关运输部门。各运输部门应当根据邮政通信需要，优先提供有效的车次、航班、舱容。\n相关运输部门应当在车站、机场、港口、码头妥善安排装卸、储存邮件和作业所需的场地、出入通道、房屋，以及通报行车或者航行情况的信息设施。\n新建、改建、扩建车站、机场、港口、码头，应当统一规划邮件存放、转运所需的场地和通道，其有关基建费用由邮政企业承担。\n第四十三条 邮政企业委托运输单位运送邮件，应当签订运邮协议。\n第四十四条 运输单位承运的邮件应当先于货物发运。因故临时停运或者改变运行时间、停靠位置时，运输单位应当及时通知邮政企业或者分支机构。\n第四十五条 载有邮件的船舶应当悬挂邮旗，各有关港口对于悬挂邮旗的船舶应当优先放行。\n第四十六条 运输单位承运邮件，除邮政企业或者分支机构派员押运者外，应当与邮政企业或者分支机构办理交接签收手续。\n除不可抗力原因外，邮件在运输单位保管期间或者在运输途中发生丢失、短少、损毁等，相关运输单位应当按照运邮协议的规定予以赔偿。\n运邮船舶发生海难必须抛弃所载货物时，非至最后，不得抛弃所运邮件。\n第四十七条 执行邮件运输和投递任务的车、船、邮政工作人员通过桥梁、渡口、隧道、检查站时，有关方面应当优先放行。带有邮政专用标志的邮政车辆在运递邮件时，凭公安机关核发的通行证，可以不受禁行路线、禁停地段的限制。运邮车辆或者邮政工作人员在运递邮件途中违章，有关主管部门应当记录后放行，待其完成运递任务后，再行处理。\n第四十八条 邮政企业依据运输工具到站(港)、离站(港)时间和运递时限制订的作业时间表应当在变更前三日通知海关。海关应当按照邮政企业通知的作业时间表派员到场监管国际邮袋、查验进出口国际邮递物品；逾时不到场，延误运递时限造成的相关责任，由海关承担。\n海关依法查验国际邮包时，在设关地应当与用户当面查验。收、寄件人不能到场的，由海关开拆查验，邮政工作人员在场配合。被开拆查验的邮包，由海关和邮政企业共同封装，双方加具封签或者戳记。海关依法开拆查验的印刷品，应当重封并加具海关封签或者戳记。\n第四十九条 用户交寄应当施行卫生检疫或者动植物检疫的邮件，必须附有检疫证书。检疫部门应当及时对邮件进行验放，以保证邮件的运递时限。\n第五十条 海关、检疫部门依法查验国际邮递物品或者检疫邮件，应当注意爱护；需要封存时，除向寄件人或者收件人发出通知外，应当同邮政企业或者分支机构履行交接手续，并负责保管，封存期不得超过四十五日。特殊情况需要延长封存期的，应当征得邮政企业或者分支机构及寄件人或者收件人的同意，并以不致造成被封存国际邮递物品或者邮件的损失为前提。被封存国际邮递物品或者邮件退还邮政企业或者分支机构时，邮政工作人员应当核对无误后予以签收。\n依法没收国际邮递物品或者经卫生、动植物检疫必须依法销毁的邮件，海关或者检疫部门应当出具没收或者检疫处理通知单，并及时通知寄件人或者收件人和邮政企业或者分支机构。\n国际邮递物品在依法查验、封存期间，发生丢失、短少、损毁等，由海关或者检疫部门负责赔偿或处理。\n第五十一条 依法查验邮递物品或者对邮件实施检疫需要使用邮政企业或者分支机构的场地和房屋时，由邮政企业与有关部门根据工作需要和实际可能协商解决。\n第五十二条 由海关依法处理的无着进口国际邮包，海关应当支付相关邮政费用。\n第五十三条 出口国际邮件的海关关单的传递方式由海关总署与邮电部商定。","level":1},{"name":"第七章 罚则","text":"第五十四条 违反本细则第十一条规定的，由有关部门按照国家有关规定根据情节轻重，予以处罚；违反治安管理有关规定的，由公安机关依照《中华人民共和国治安管理处罚条例》处罚。\n第五十五条 违反本细则第三十三条第三项规定，尚未造成严重后果的，由公安机关依照《中华人民共和国治安管理处罚条例》处理。\n第五十六条 伪造或者冒用邮政专用标志、邮政标志服或者邮政日戳、邮政夹钳、邮袋等邮政专用品的，由邮电管理局或其授权单位处以一千五百元以下罚款，并没收有关物品。\n第五十七条 以营利为目的，伪造邮资凭证，未经许可仿印邮票图案或者印制带有“中国人民邮政”字样明信片的，由邮电管理局或其授权单位处以五千元以下罚款，并没收非法所得和非法物品。\n由于用户的故意，交寄的邮件使用不符合规定的邮资凭证的，邮政企业或者分支机构不予发寄，通知寄件人限期撤回，并处以应付邮资十倍的罚款；无法通知寄件人或者逾期不办理撤回手续的，作为无着邮件处理。\n第五十八条 邮政工作人员隐匿、毁弃、私拆、盗窃邮件，贪污、冒领用户款项的，邮政企业应当追回赃款赃物，可以并处罚款，还可以根据情节轻重，给予行政处分。具体办法由邮电部规定。\n第五十九条 违反本细则第四十一条第二款规定的，依照《邮政法》第三十六条规定追究责任。\n第六十条 违反本细则规定，构成犯罪的，由司法机关依法追究刑事责任。\n第六十一条 误收、误拆他人信件不予退还或者已退还但泄露信件内容，侵犯他人通信自由权利的，依照《邮政法》第三十六条规定追究责任。","level":1},{"name":"第八章 附则","text":"第六十二条 本细则所称公安机关、国家安全机关、检察机关是指县以上(含县级)公安机关、国家安全机关、检察机关。\n第六十三条 邮电部可以根据本细则制定有关规章。\n第六十四条 本细则由邮电部负责解释。\n第六十五条 本细则自发布之日起施行。","level":1}]},{"id":"n0336","sections":[{"name":"","text":"国务院关于在香港特别行政区\n同时升挂使用国旗区旗的规定\n(1997年6月5日国务院第58次常务会议通过 1997年6月5日中华人民共和国国务院令第219号发布 自1997年7月1日起施行)\n根据《中华人民共和国国旗法》的有关规定，自1997年7月1日起，在香港特别行政区同时升挂、使用国旗和区旗时，按照下列规定执行：\n一、凡国旗和区旗同时升挂、使用时，应当将国旗置于中心、较高或者突出的位置。\n二、凡国旗和区旗同时或者并列升挂、使用时，国旗应当大于区旗，国旗在右，区旗在左。\n三、列队举持国旗和区旗行进时，国旗应当在区旗之前。","level":0}]},{"id":"n0337","sections":[{"name":"","text":"中华人民共和国著作权法实施条例\n(2002年8月2日中华人民共和国国务院令第359号公布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2013年1月30日《国务院关于修改〈中华人民共和国著作权法实施条例〉的决定》第二次修订)\n第一条 根据《中华人民共和国著作权法》(以下简称著作权法)，制定本条例。\n第二条 著作权法所称作品，是指文学、艺术和科学领域内具有独创性并能以某种有形形式复制的智力成果。\n第三条 著作权法所称创作，是指直接产生文学、艺术和科学作品的智力活动。\n为他人创作进行组织工作，提供咨询意见、物质条件，或者进行其他辅助工作，均不视为创作。\n第四条 著作权法和本条例中下列作品的含义：\n(一)文字作品，是指小说、诗词、散文、论文等以文字形式表现的作品；\n(二)口述作品，是指即兴的演说、授课、法庭辩论等以口头语言形式表现的作品；\n(三)音乐作品，是指歌曲、交响乐等能够演唱或者演奏的带词或者不带词的作品；\n(四)戏剧作品，是指话剧、歌剧、地方戏等供舞台演出的作品；\n(五)曲艺作品，是指相声、快书、大鼓、评书等以说唱为主要形式表演的作品；\n(六)舞蹈作品，是指通过连续的动作、姿势、表情等表现思想情感的作品；\n(七)杂技艺术作品，是指杂技、魔术、马戏等通过形体动作和技巧表现的作品；\n(八)美术作品，是指绘画、书法、雕塑等以线条、色彩或者其他方式构成的有审美意义的平面或者立体的造型艺术作品；\n(九)建筑作品，是指以建筑物或者构筑物形式表现的有审美意义的作品；\n(十)摄影作品，是指借助器械在感光材料或者其他介质上记录客观物体形象的艺术作品；\n(十一)电影作品和以类似摄制电影的方法创作的作品，是指摄制在一定介质上，由一系列有伴音或者无伴音的画面组成，并且借助适当装置放映或者以其他方式传播的作品；\n(十二)图形作品，是指为施工、生产绘制的工程设计图、产品设计图，以及反映地理现象、说明事物原理或者结构的地图、示意图等作品；\n(十三)模型作品，是指为展示、试验或者观测等用途，根据物体的形状和结构，按照一定比例制成的立体作品。\n第五条 著作权法和本条例中下列用语的含义：\n(一)时事新闻，是指通过报纸、期刊、广播电台、电视台等媒体报道的单纯事实消息；\n(二)录音制品，是指任何对表演的声音和其他声音的录制品；\n(三)录像制品，是指电影作品和以类似摄制电影的方法创作的作品以外的任何有伴音或者无伴音的连续相关形象、图像的录制品；\n(四)录音制作者，是指录音制品的首次制作人；\n(五)录像制作者，是指录像制品的首次制作人；\n(六)表演者，是指演员、演出单位或者其他表演文学、艺术作品的人。\n第六条 著作权自作品创作完成之日起产生。\n第七条 著作权法第二条第三款规定的首先在中国境内出版的外国人、无国籍人的作品，其著作权自首次出版之日起受保护。\n第八条 外国人、无国籍人的作品在中国境外首先出版后，30日内在中国境内出版的，视为该作品同时在中国境内出版。\n第九条 合作作品不可以分割使用的，其著作权由各合作作者共同享有，通过协商一致行使；不能协商一致，又无正当理由的，任何一方不得阻止他方行使除转让以外的其他权利，但是所得收益应当合理分配给所有合作作者。\n第十条 著作权人许可他人将其作品摄制成电影作品和以类似摄制电影的方法创作的作品的，视为已同意对其作品进行必要的改动，但是这种改动不得歪曲篡改原作品。\n第十一条 著作权法第十六条第一款关于职务作品的规定中的“工作任务”，是指公民在该法人或者该组织中应当履行的职责。\n著作权法第十六条第二款关于职务作品的规定中的“物质技术条件”，是指该法人或者该组织为公民完成创作专门提供的资金、设备或者资料。\n第十二条 职务作品完成两年内，经单位同意，作者许可第三人以与单位使用的相同方式使用作品所获报酬，由作者与单位按约定的比例分配。\n作品完成两年的期限，自作者向单位交付作品之日起计算。\n第十三条 作者身份不明的作品，由作品原件的所有人行使除署名权以外的著作权。作者身份确定后，由作者或者其继承人行使著作权。\n第十四条 合作作者之一死亡后，其对合作作品享有的著作权法第十条第一款第五项至第十七项规定的权利无人继承又无人受遗赠的，由其他合作作者享有。\n第十五条 作者死亡后，其著作权中的署名权、修改权和保护作品完整权由作者的继承人或者受遗赠人保护。\n著作权无人继承又无人受遗赠的，其署名权、修改权和保护作品完整权由著作权行政管理部门保护。\n第十六条 国家享有著作权的作品的使用，由国务院著作权行政管理部门管理。\n第十七条 作者生前未发表的作品，如果作者未明确表示不发表，作者死亡后50年内，其发表权可由继承人或者受遗赠人行使；没有继承人又无人受遗赠的，由作品原件的所有人行使。\n第十八条 作者身份不明的作品，其著作权法第十条第一款第五项至第十七项规定的权利的保护期截止于作品首次发表后第50年的12月31日。作者身份确定后，适用著作权法第二十一条的规定。\n第十九条 使用他人作品的，应当指明作者姓名、作品名称；但是，当事人另有约定或者由于作品使用方式的特性无法指明的除外。\n第二十条 著作权法所称已经发表的作品，是指著作权人自行或者许可他人公之于众的作品。\n第二十一条 依照著作权法有关规定，使用可以不经著作权人许可的已经发表的作品的，不得影响该作品的正常使用，也不得不合理地损害著作权人的合法利益。\n第二十二条 依照著作权法第二十三条、第三十三条第二款、第四十条第三款的规定使用作品的付酬标准，由国务院著作权行政管理部门会同国务院价格主管部门制定、公布。\n第二十三条 使用他人作品应当同著作权人订立许可使用合同，许可使用的权利是专有使用权的，应当采取书面形式，但是报社、期刊社刊登作品除外。\n第二十四条 著作权法第二十四条规定的专有使用权的内容由合同约定，合同没有约定或者约定不明的，视为被许可人有权排除包括著作权人在内的任何人以同样的方式使用作品；除合同另有约定外，被许可人许可第三人行使同一权利，必须取得著作权人的许可。\n第二十五条 与著作权人订立专有许可使用合同、转让合同的，可以向著作权行政管理部门备案。\n第二十六条 著作权法和本条例所称与著作权有关的权益，是指出版者对其出版的图书和期刊的版式设计享有的权利，表演者对其表演享有的权利，录音录像制作者对其制作的录音录像制品享有的权利，广播电台、电视台对其播放的广播、电视节目享有的权利。\n第二十七条 出版者、表演者、录音录像制作者、广播电台、电视台行使权利，不得损害被使用作品和原作品著作权人的权利。\n第二十八条 图书出版合同中约定图书出版者享有专有出版权但没有明确其具体内容的，视为图书出版者享有在合同有效期限内和在合同约定的地域范围内以同种文字的原版、修订版出版图书的专有权利。\n第二十九条 著作权人寄给图书出版者的两份订单在6个月内未能得到履行，视为著作权法第三十二条所称图书脱销。\n第三十条 著作权人依照著作权法第三十三条第二款声明不得转载、摘编其作品的，应当在报纸、期刊刊登该作品时附带声明。\n第三十一条 著作权人依照著作权法第四十条第三款声明不得对其作品制作录音制品的，应当在该作品合法录制为录音制品时声明。\n第三十二条 依照著作权法第二十三条、第三十三条第二款、第四十条第三款的规定，使用他人作品的，应当自使用该作品之日起2个月内向著作权人支付报酬。\n第三十三条 外国人、无国籍人在中国境内的表演，受著作权法保护。\n外国人、无国籍人根据中国参加的国际条约对其表演享有的权利，受著作权法保护。\n第三十四条 外国人、无国籍人在中国境内制作、发行的录音制品，受著作权法保护。\n外国人、无国籍人根据中国参加的国际条约对其制作、发行的录音制品享有的权利，受著作权法保护。\n第三十五条 外国的广播电台、电视台根据中国参加的国际条约对其播放的广播、电视节目享有的权利，受著作权法保护。\n第三十六条 有著作权法第四十八条所列侵权行为，同时损害社会公共利益，非法经营额5万元以上的，著作权行政管理部门可处非法经营额1倍以上5倍以下的罚款；没有非法经营额或者非法经营额5万元以下的，著作权行政管理部门根据情节轻重，可处25万元以下的罚款。\n第三十七条 有著作权法第四十八条所列侵权行为，同时损害社会公共利益的，由地方人民政府著作权行政管理部门负责查处。\n国务院著作权行政管理部门可以查处在全国有重大影响的侵权行为。\n第三十八条 本条例自2002年9月15日起施行。1991年5月24日国务院批准、1991年5月30日国家版权局发布的《中华人民共和国著作权法实施条例》同时废止。","level":0}]},{"id":"n0338","sections":[{"name":"","text":"科学技术档案工作条例\n(1980年12月9日国务院批准 1980年12月27日国家经济委员会、国家基本建设委员会、国家科学技术委员会、国家档案局发布 自发布之日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了建立、健全科学技术档案工作，完整地保存和科学地管理科学技术档案(以下简称科技档案)，充分发挥科技档案在社会主义现代化建设中的作用，特制定本条例。\n第二条 科技档案是指在自然科学研究、生产技术、基本建设(以下简称科研、生产、基建)等活动中形成的应当归档保存的图纸、图表、文字材料、计算材料、照片、影片、录像、录音带等科技文件材料。\n第三条 科技档案工作是生产管理、技术管理、科研管理的重要组成部分，各工业、交通、基建、科研、农林、军事、地质、测绘、水文、气象、教育、卫生等单位(以下简称各单位)，都应当把科技档案工作纳入生产管理工作、技术管理工作、科研管理工作之中，加强领导。\n第四条 各单位应当按照集中统一管理科技档案的基本原则，建立、健全科技档案工作，达到科技档案完整、准确、系统、安全和有效利用的要求。","level":1},{"name":"第二章 科技文件材料的形成和归档","text":"第五条 各单位应当建立、健全科技文件材料的形成、积累、整理、归档制度，做到每一项科研、生产、基建等活动，都有完整、准确、系统的科技文件材料归档保存。\n第六条 各单位应当把科技文件材料的形成、积累、整理和归档纳入科技工作程序和科研、生产、基建等计划中，列入有关部门和有关人员的职责范围。\n第七条 各单位在对每一项科研成果、产品试制、基建工程或其他技术项目进行鉴定、验收的时候，要有科技档案部门参加，对应当归档的科技文件材料加以验收。没有完整、准确、系统的科技文件材料的项目，不能验收。\n第八条 一个科研课题、一个试制产品、一项工程或其他技术项目，在完成或告一段落以后，必须将所形成的科技文件材料加以系统整理，组成保管单位，填写保管期限，注明密级，由课题负责人、产品试制负责人、工程负责人等审查后，及时归档。\n第九条 凡是需要归档的科技文件材料，都应当做到书写材料优良、字迹工整、图样清晰，有利于长久保存。\n第十条 科技档案部门有责任检查和协助科技人员做好科技文件材料的形成、积累、整理和归档的工作。","level":1},{"name":"第三章 科技档案的管理","text":"第十一条 科技档案部门对接收来的科技档案，应当进行分类、编目、登记、统计和必要的加工整理。\n国务院所属各工业、交通、科研、基建等专业主管机关(以下简称专业主管机关)，应当拟定本专业系统的科技档案分类大纲。\n第十二条 各单位应当建立和健全图纸更改、补充的制度。更改、补充图纸，必须履行审批手续。\n第十三条 科技档案部门应当及时地提供科技档案为科研、生产、基建等各项工作服务，并编制必要的检索工具和参考资料。\n借阅和复制科技档案要有一定的批准手续。\n第十四条 各单位应当定期对科技档案的密级进行审查，根据上级的规定，及时调整密级，扩大利用与交流的范围。\n第十五条 科技档案部门对科技档案的利用效果，应当进行必要的调查和建立借阅档案的统计制度。\n第十六条 国务院所属各专业主管机关，应当编制本专业的科技档案保管期限表。科技档案的保管期限，分为永久、长期、定期三种。\n第十七条 各单位应当定期做好科技档案保存价值的鉴定工作。鉴定的方法是直接鉴定档案的内容。鉴定工作要在总工程师或科研负责人的领导下，由科技领导干部、熟悉有关专业的科技人员和科技档案人员共同进行。\n第十八条 要销毁的科技档案，必须造具清册，经单位领导审定，报送上级主管机关备案。销毁科技档案，要指定监销人，防止失密。\n第十九条 保管科技档案必须有专用库房，库房内应当保持适当的温度和湿度，并有防盗、防火、防晒、防虫、防尘等安全措施。科技档案部门应当定期检查科技档案的保管状况。对破损或变质的档案，要及时修补和复制。\n第二十条 科技档案部门对重要的科技档案应当复制副本，分别保存，以保证在非常情况下科技档案的安全和提供利用。\n第二十一条 引进技术和设备的档案，由引进单位的科技档案部门统一管理。\n第二十二条 凡是几个单位分工协作完成的科技项目或工程，由主办单位保存一整套档案，协作单位除保存与自己承担任务有关的档案正本以外，应将复制本送交主办单位保存。\n第二十三条 凡单位撤销或变动，以及建筑物、构筑物、设备、仪器等转移使用关系时，其档案要妥善整理，并经领导人批准后向接受单位办理交接手续。\n第二十四条 科技档案部门增添设备和用品的费用，分别从企业、事业单位的生产费、科研费或事业费中开支。\n第二十五条 新建的企业、事业单位，应当同时建设符合要求的科技档案库房。","level":1},{"name":"第四章 科技档案工作管理体制","text":"第二十六条 国家档案局和各级档案管理机关应当加强对科技档案工作的指导、监督和检查。\n第二十七条 科技档案工作必须按专业实行统一管理。国务院所属的各专业主管机关和省、自治区、直辖市人民政府所属的各专业主管机关，应当建立相应的档案机构，加强对所属企业、事业单位科技档案工作的领导。\n第二十八条 国务院所属的各专业主管机关，根据需要建立专业档案馆，收集和保管本专业需要长期和永久保存的科技档案。\n大中城市应当建立城市基本建设档案馆，收集和保管本城市应当长期和永久保存的基本建设档案。\n专业档案馆和城市基本建设档案馆是科学技术事业单位。\n第二十九条 大中型企业、事业单位要设立直属的科技档案机构；小型企业、事业单位可以设立单独的科技档案室，也可以设立文书档案和科技档案统一管理的档案室，或者配备专(兼)职人员管理。\n各单位的科技档案工作，由领导生产、科研的负责人或者总工程师分工领导。\n第三十条 专业档案馆或各单位的科技档案机构，根据需要可以兼管科技资料工作。","level":1},{"name":"第五章 科技档案干部","text":"第三十一条 国务院所属的各专业主管机关和省、自治区、直辖市人民政府所属的各专业主管机关都应当积极建设一支坚持社会主义道路，具有科技档案专业知识和懂得有关的科学技术，有一定工作能力的科技档案干部队伍。\n第三十二条 科技档案干部要努力学习马列主义、毛泽东思想，认真执行国家的方针政策，刻苦钻研业务，不断总结经验，提高管理工作水平，积极为社会主义现代化建设服务。\n第三十三条 各单位要给科技档案部门配备足够数量和能胜任工作的干部，还应当配备一定数量的科技干部，以保证工作的需要。\n第三十四条 各单位要经常对科技档案干部进行保守国家机密的教育，检查遵守保密制度的情况。","level":1},{"name":"第六章 附则","text":"第三十五条 国务院所属的各专业主管机关和省、自治区、直辖市人民政府所属的各专业主管机关，可以根据本条例的精神，结合本系统、本地区科技档案工作情况，制定实施细则。\n第三十六条 本条例自发布之日起施行。过去有关规定与本条例有抵触的，以本条例为准。","level":1}]},{"id":"n0339","sections":[{"name":"","text":"中华人民共和国契税暂行条例\n(1997年7月7日中华人民共和国国务院令第224号发布 根据2019年3月2日《国务院关于修改部分行政法规的决定》修订)\n第一条 在中华人民共和国境内转移土地、房屋权属，承受的单位和个人为契税的纳税人，应当依照本条例的规定缴纳契税。\n第二条 本条例所称转移土地、房屋权属是指下列行为：\n(一)国有土地使用权出让；\n(二)土地使用权转让，包括出售、赠与和交换；\n(三)房屋买卖；\n(四)房屋赠与；\n(五)房屋交换。\n前款第二项土地使用权转让，不包括农村集体土地承包经营权的转移。\n第三条 契税税率为3—5%。\n契税的适用税率，由省、自治区、直辖市人民政府在前款规定的幅度内按照本地区的实际情况确定，并报财政部和国家税务总局备案。\n第四条 契税的计税依据：\n(一)国有土地使用权出让、土地使用权出售、房屋买卖，为成交价格；\n(二)土地使用权赠与、房屋赠与，由征收机关参照土地使用权出售、房屋买卖的市场价格核定；\n(三)土地使用权交换、房屋交换，为所交换的土地使用权、房屋的价格的差额。\n前款成交价格明显低于市场价格并且无正当理由的，或者所交换土地使用权、房屋的价格的差额明显不合理并且无正当理由的，由征收机关参照市场价格核定。\n第五条 契税应纳税额，依照本条例第三条规定的税率和第四条规定的计税依据计算征收。应纳税额计算公式：\n应纳税额＝计税依据×税率\n应纳税额以人民币计算。转移土地、房屋权属以外汇结算的，按照纳税义务发生之日中国人民银行公布的人民币市场汇率中间价折合成人民币计算。\n第六条 有下列情形之一的，减征或者免征契税：\n(一)国家机关、事业单位、社会团体、军事单位承受土地、房屋用于办公、教学、医疗、科研和军事设施的，免征；\n(二)城镇职工按规定第一次购买公有住房的，免征；\n(三)因不可抗力灭失住房而重新购买住房的，酌情准予减征或者免征；\n(四)财政部规定的其他减征、免征契税的项目。\n第七条 经批准减征、免征契税的纳税人改变有关土地、房屋的用途，不再属于本条例第六条规定的减征、免征契税范围的，应当补缴已经减征、免征的税款。\n第八条 契税的纳税义务发生时间，为纳税人签订土地、房屋权属转移合同的当天，或者纳税人取得其他具有土地、房屋权属转移合同性质凭证的当天。\n第九条 纳税人应当自纳税义务发生之日起10日内，向土地、房屋所在地的契税征收机关办理纳税申报，并在契税征收机关核定的期限内缴纳税款。\n第十条 纳税人办理纳税事宜后，契税征收机关应当向纳税人开具契税完税凭证。\n第十一条 纳税人应当持契税完税凭证和其他规定的文件材料，依法向土地管理部门、房产管理部门办理有关土地、房屋的权属变更登记手续。\n纳税人未出具契税完税凭证的，土地管理部门、房产管理部门不予办理有关土地、房屋的权属变更登记手续。\n第十二条 契税征收机关为土地、房屋所在地的税务机关。\n土地管理部门、房产管理部门应当向契税征收机关提供有关资料，并协助契税征收机关依法征收契税。\n第十三条 契税的征收管理，依照本条例和有关法律、行政法规的规定执行。\n第十四条 财政部根据本条例制定细则。\n第十五条 本条例自1997年10月1日起施行。1950年4月3日中央人民政府政务院发布的《契税暂行条例》同时废止。","level":0}]},{"id":"n0340","sections":[{"name":"","text":"民用机场管理条例\n(2009年4月13日中华人民共和国国务院令第553号公布 根据2019年3月2日《国务院关于修改部分行政法规的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了规范民用机场的建设与管理，积极、稳步推进民用机场发展，保障民用机场安全和有序运营，维护有关当事人的合法权益，依据《中华人民共和国民用航空法》，制定本条例。\n第二条 本条例适用于中华人民共和国境内民用机场的规划、建设、使用、管理及其相关活动。\n民用机场分为运输机场和通用机场。\n第三条 民用机场是公共基础设施。各级人民政府应当采取必要的措施，鼓励、支持民用机场发展，提高民用机场的管理水平。\n第四条 国务院民用航空主管部门依法对全国民用机场实施行业监督管理。地区民用航空管理机构依法对辖区内民用机场实施行业监督管理。\n有关地方人民政府依法对民用机场实施监督管理。\n第五条 全国民用机场布局规划应当根据国民经济和社会发展需求以及国防要求编制，并与综合交通发展规划、土地利用总体规划、城乡规划相衔接，严格控制建设用地规模，节约集约用地，保护生态环境。","level":1},{"name":"第二章 民用机场的建设和使用","text":"第六条 新建运输机场的场址应当符合国务院民用航空主管部门规定的条件。\n运输机场所在地有关地方人民政府应当将运输机场场址纳入土地利用总体规划和城乡规划统筹安排，并对场址实施保护。\n第七条 运输机场的新建、改建和扩建应当依照国家有关规定办理建设项目审批、核准手续。\n第八条 运输机场总体规划由运输机场建设项目法人编制，并经国务院民用航空主管部门或者地区民用航空管理机构(以下统称民用航空管理部门)批准后方可实施。\n飞行区指标为4E以上(含4E)的运输机场的总体规划，由国务院民用航空主管部门批准；飞行区指标为4D以下(含4D)的运输机场的总体规划，由所在地地区民用航空管理机构批准。民用航空管理部门审批运输机场总体规划，应当征求运输机场所在地有关地方人民政府意见。\n运输机场建设项目法人编制运输机场总体规划，应当征求有关军事机关意见。\n第九条 运输机场所在地有关地方人民政府应当将运输机场总体规划纳入城乡规划，并根据运输机场的运营和发展需要，对运输机场周边地区的土地利用和建设实行规划控制。\n第十条 运输机场内的建设项目应当符合运输机场总体规划。任何单位和个人不得在运输机场内擅自新建、改建、扩建建筑物或者构筑物。\n第十一条 运输机场新建、改建和扩建项目的安全设施应当与主体工程同时设计、同时施工、同时验收、同时投入使用。安全设施投资应当纳入建设项目概算。\n第十二条 运输机场内的供水、供电、供气、通信、道路等基础设施由机场建设项目法人负责建设；运输机场外的供水、供电、供气、通信、道路等基础设施由运输机场所在地地方人民政府统一规划，统筹建设。\n第十三条 运输机场专业工程的设计应当符合国家有关标准，并经民用航空管理部门批准。\n飞行区指标为4E以上(含4E)的运输机场专业工程的设计，由国务院民用航空主管部门批准；飞行区指标为4D以下(含4D)的运输机场专业工程的设计，由运输机场所在地地区民用航空管理机构批准。\n运输机场专业工程经民用航空管理部门验收合格后，方可投入使用。\n运输机场专业工程目录由国务院民用航空主管部门会同国务院建设主管部门制定并公布。\n第十四条 通用机场的规划、建设按照国家有关规定执行。\n第十五条 运输机场的安全和运营管理由依法组建的或者受委托的具有法人资格的机构(以下简称机场管理机构)负责。\n第十六条 运输机场投入使用应当具备下列条件：\n(一)有健全的安全运营管理体系、组织机构和管理制度；\n(二)有与其运营业务相适应的飞行区、航站区、工作区以及空中交通服务、航行情报、通信导航监视、气象等相关设施、设备和人员；\n(三)使用空域已经批准；\n(四)飞行程序和运行标准符合国务院民用航空主管部门的规定；\n(五)符合国家规定的民用航空安全保卫条件；\n(六)有处理突发事件的应急预案及相应的设施、设备。\n第十七条 运输机场投入使用的，机场管理机构应当向国务院民用航空主管部门提出申请，并附送符合本条例第十六条规定条件的相关材料。\n国务院民用航空主管部门应当自受理申请之日起45个工作日内审查完毕，作出准予许可或者不予许可的决定。准予许可的，颁发运输机场使用许可证；不予许可的，应当书面通知申请人并说明理由。\n第十八条 通用机场投入使用应当具备下列条件：\n(一)有与运营业务相适应的飞行场地；\n(二)有保证飞行安全的空中交通服务、通信导航监视等设施和设备；\n(三)有健全的安全管理制度、符合国家规定的民用航空安全保卫条件以及处理突发事件的应急预案；\n(四)配备必要的管理人员和专业技术人员。\n第十九条 通用机场投入使用的，通用机场的管理者应当向通用机场所在地地区民用航空管理机构提出申请，并附送符合本条例第十八条规定条件的相关材料。\n地区民用航空管理机构应当自受理申请之日起30个工作日内审查完毕，作出准予许可或者不予许可的决定。准予许可的，颁发通用机场使用许可证；不予许可的，应当书面通知申请人并说明理由。\n第二十条 运输机场作为国际机场使用的，应当按照国家有关规定设立口岸查验机构，配备相应的人员、场地和设施，并经国务院有关部门验收合格。\n国际机场的开放使用，由国务院民用航空主管部门对外公告；国际机场资料由国务院民用航空主管部门统一对外提供。\n第二十一条 机场管理机构应当按照运输机场使用许可证规定的范围开放使用运输机场，不得擅自关闭。\n运输机场因故不能保障民用航空器运行安全，需要临时关闭的，机场管理机构应当及时通知有关空中交通管理部门并及时向社会公告。空中交通管理部门应当按照相关规定发布航行通告。\n机场管理机构拟关闭运输机场的，应当提前45日报颁发运输机场使用许可证的机关，经批准后方可关闭，并向社会公告。\n第二十二条 运输机场的命名或者更名应当符合国家有关法律、行政法规的规定。\n第二十三条 运输机场废弃或者改作他用的，机场管理机构应当按照国家有关规定办理报批手续，并及时向社会公告。","level":1},{"name":"第三章 民用机场安全和运营管理","text":"第二十四条 民用航空管理部门、有关地方人民政府应当加强对运输机场安全运营工作的领导，督促机场管理机构依法履行安全管理职责，协调、解决运输机场安全运营中的问题。\n第二十五条 民用航空管理部门、有关地方人民政府应当按照国家规定制定运输机场突发事件的应急预案。\n第二十六条 机场管理机构应当根据运输机场突发事件应急预案组织运输机场应急救援的演练和人员培训。\n机场管理机构、航空运输企业以及其他驻场单位应当配备必要的应急救援设备和器材，并加强日常管理。\n第二十七条 机场管理机构应当依照国家有关法律、法规和技术标准的规定，保证运输机场持续符合安全运营要求。运输机场不符合安全运营要求的，机场管理机构应当按照国家有关规定及时改正。\n第二十八条 机场管理机构对运输机场的安全运营实施统一协调管理，负责建立健全机场安全运营责任制，组织制定机场安全运营规章制度，保障机场安全投入的有效实施，督促检查安全运营工作，及时消除安全事故隐患，依法报告生产安全事故。\n航空运输企业及其他驻场单位应当按照各自的职责，共同保障运输机场的安全运营并承担相应的责任；发生影响运输机场安全运营情况的，应当立即报告机场管理机构。\n第二十九条 机场管理机构、航空运输企业以及其他驻场单位应当定期对从业人员进行必要的安全运营培训，保证从业人员具备相关的知识和技能。\n第三十条 民用机场专用设备应当符合国家规定的标准和相关技术规范，并经国务院民用航空主管部门认定的机构检验合格后，方可用于民用机场。\n民用航空管理部门应当加强对民用机场专用设备的监督检查。\n民用机场专用设备目录由国务院民用航空主管部门制定并公布。\n第三十一条 在运输机场开放使用的情况下，不得在飞行区及与飞行区临近的航站区内进行施工。确需施工的，应当取得运输机场所在地地区民用航空管理机构的批准。\n第三十二条 发生突发事件，运输机场所在地有关地方人民政府、民用航空管理部门、空中交通管理部门、机场管理机构等单位应当按照应急预案的要求及时、有效地开展应急救援。\n第三十三条 机场管理机构统一协调、管理运输机场的生产运营，维护运输机场的正常秩序，为航空运输企业及其他驻场单位、旅客和货主提供公平、公正、便捷的服务。\n机场管理机构与航空运输企业及其他驻场单位应当签订书面协议，明确各方在生产运营、机场管理过程中以及发生航班延误等情况时的权利和义务。\n第三十四条 机场管理机构应当组织航空运输企业及其他驻场单位制定服务规范并向社会公布。\n第三十五条 机场管理机构应当按照国家规定的标准配备候机、餐饮、停车、医疗急救等设施、设备，并提供相应的服务。\n第三十六条 机场管理机构应当与航空运输企业、空中交通管理部门等单位建立信息共享机制，相互提供必要的生产运营信息，及时为旅客和货主提供准确的信息。\n第三十七条 机场管理机构、航空运输企业以及其他驻场单位应当采取有效措施加强协调和配合，共同保证航班正常运行。\n航班发生延误，机场管理机构应当及时协调航空运输企业及其他有关驻场单位共同做好旅客和货主服务，及时通告相关信息。航空运输企业及其代理人应当按照有关规定和服务承诺为旅客和货主提供相应的服务。\n第三十八条 机场范围内的零售、餐饮、航空地面服务等经营性业务采取有偿转让经营权的方式经营的，机场管理机构应当按照国务院民用航空主管部门的规定与取得经营权的企业签订协议，明确服务标准、收费水平、安全规范和责任等事项。\n对于采取有偿转让经营权的方式经营的业务，机场管理机构及其关联企业不得参与经营。\n第三十九条 机场管理机构应当向民用航空管理部门报送运输机场规划、建设和生产运营的有关资料，接受民用航空管理部门的监督检查。\n第四十条 民用航空管理部门和机场管理机构应当建立投诉受理制度，公布投诉受理单位和投诉方式。对于旅客和货主的投诉，民用航空管理部门或者机场管理机构应当自受理之日起10个工作日内作出书面答复。\n第四十一条 在民用机场内从事航空燃油供应业务的企业，应当具备下列条件：\n(一)取得成品油经营许可和危险化学品经营许可；\n(二)有符合国家有关标准、与经营业务规模相适应的航空燃油供应设施、设备；\n(三)有健全的航空燃油供应安全管理制度、油品检测和监控体系；\n(四)有满足业务经营需要的专业技术和管理人员。\n第四十二条 申请在民用机场内从事航空燃油供应业务的企业，应当向民用机场所在地地区民用航空管理机构提出申请，并附送符合本条例第四十一条规定条件的相关材料。\n地区民用航空管理机构应当自受理申请之日起30个工作日内，作出准予许可或者不予许可的决定。准予许可的，颁发民用机场航空燃油供应安全运营许可证；不予许可的，应当书面通知申请人并说明理由。\n第四十三条 航空燃油供应企业供应的航空燃油应当符合航空燃油适航标准。\n第四十四条 民用机场航空燃油供应设施应当公平地提供给航空燃油供应企业使用。\n第四十五条 运输机场航空燃油供应企业停止运输机场航空燃油供应业务的，应当提前90日告知运输机场所在地地区民用航空管理机构、机场管理机构和相关航空运输企业。","level":1},{"name":"第四章 民用机场安全环境保护","text":"第四十六条 民用机场所在地地区民用航空管理机构和有关地方人民政府，应当按照国家有关规定划定民用机场净空保护区域，并向社会公布。\n第四十七条 县级以上地方人民政府审批民用机场净空保护区域内的建设项目，应当书面征求民用机场所在地地区民用航空管理机构的意见。\n第四十八条 在民用机场净空保护区域内设置22万伏以上(含22万伏)的高压输电塔的，应当按照国务院民用航空主管部门的有关规定设置障碍灯或者标志，保持其正常状态，并向民用机场所在地地区民用航空管理机构、空中交通管理部门和机场管理机构提供有关资料。\n第四十九条 禁止在民用机场净空保护区域内从事下列活动：\n(一)排放大量烟雾、粉尘、火焰、废气等影响飞行安全的物质；\n(二)修建靶场、强烈爆炸物仓库等影响飞行安全的建筑物或者其他设施；\n(三)设置影响民用机场目视助航设施使用或者飞行员视线的灯光、标志或者物体；\n(四)种植影响飞行安全或者影响民用机场助航设施使用的植物；\n(五)放飞影响飞行安全的鸟类，升放无人驾驶的自由气球、系留气球和其他升空物体；\n(六)焚烧产生大量烟雾的农作物秸秆、垃圾等物质，或者燃放烟花、焰火；\n(七)在民用机场围界外5米范围内，搭建建筑物、种植树木，或者从事挖掘、堆积物体等影响民用机场运营安全的活动；\n(八)国务院民用航空主管部门规定的其他影响民用机场净空保护的行为。\n第五十条 在民用机场净空保护区域外从事本条例第四十九条所列活动的，不得影响民用机场净空保护。\n第五十一条 禁止在距离航路两侧边界各30公里以内的地带修建对空射击的靶场和其他可能影响飞行安全的设施。\n第五十二条 民用航空管理部门和机场管理机构应当加强对民用机场净空状况的核查。发现影响民用机场净空保护的情况，应当立即制止，并书面报告民用机场所在地县级以上地方人民政府。接到报告的县级以上地方人民政府应当及时采取有效措施，消除对飞行安全的影响。\n第五十三条 民用机场所在地地方无线电管理机构应当会同地区民用航空管理机构按照国家无线电管理的有关规定和标准确定民用机场电磁环境保护区域，并向社会公布。\n民用机场电磁环境保护区域包括设置在民用机场总体规划区域内的民用航空无线电台(站)电磁环境保护区域和民用机场飞行区电磁环境保护区域。\n第五十四条 设置、使用地面民用航空无线电台(站)，应当经民用航空管理部门审核后，按照国家无线电管理有关规定办理审批手续，领取无线电台执照。\n第五十五条 在民用机场电磁环境保护区域内设置、使用非民用航空无线电台(站)的，无线电管理机构应当在征求民用机场所在地地区民用航空管理机构意见后，按照国家无线电管理的有关规定审批。\n第五十六条 禁止在民用航空无线电台(站)电磁环境保护区域内，从事下列影响民用机场电磁环境的活动：\n(一)修建架空高压输电线、架空金属线、铁路、公路、电力排灌站；\n(二)存放金属堆积物；\n(三)种植高大植物；\n(四)从事掘土、采砂、采石等改变地形地貌的活动；\n(五)国务院民用航空主管部门规定的其他影响民用机场电磁环境的行为。\n第五十七条 任何单位或者个人使用的无线电台(站)和其他仪器、装置，不得对民用航空无线电专用频率的正常使用产生干扰。\n第五十八条 民用航空无线电专用频率受到干扰时，机场管理机构和民用航空管理部门应当立即采取排查措施，及时消除；无法消除的，应当通报民用机场所在地地方无线电管理机构。接到通报的无线电管理机构应当采取措施，依法查处。\n第五十九条 在民用机场起降的民用航空器应当符合国家有关航空器噪声和涡轮发动机排出物的适航标准。\n第六十条 机场管理机构应当会同航空运输企业、空中交通管理部门等有关单位，采取技术手段和管理措施控制民用航空器噪声对运输机场周边地区的影响。\n第六十一条 民用机场所在地有关地方人民政府制定民用机场周边地区的土地利用总体规划和城乡规划，应当充分考虑民用航空器噪声对民用机场周边地区的影响，符合国家有关声环境质量标准。\n机场管理机构应当将民用航空器噪声对运输机场周边地区产生影响的情况，报告有关地方人民政府国土资源、规划建设、环境保护等主管部门。\n第六十二条 民用机场所在地有关地方人民政府应当在民用机场周边地区划定限制建设噪声敏感建筑物的区域并实施控制。确需在该区域内建设噪声敏感建筑物的，建设单位应当采取措施减轻或者避免民用航空器运行时对其产生的噪声影响。\n民用机场所在地有关地方人民政府应当会同地区民用航空管理机构协调解决在民用机场起降的民用航空器噪声影响引发的相关问题。","level":1},{"name":"第五章 法律责任","text":"第六十三条 违反本条例的规定，有下列情形之一的，由民用航空管理部门责令改正，处10万元以上50万元以下的罚款：\n(一)在运输机场内进行不符合运输机场总体规划的建设活动；\n(二)擅自实施未经批准的运输机场专业工程的设计，或者将未经验收合格的运输机场专业工程投入使用；\n(三)在运输机场开放使用的情况下，未经批准在飞行区及与飞行区临近的航站区内进行施工。\n第六十四条 违反本条例的规定，机场管理机构未按照运输机场使用许可证规定的范围使用运输机场的，由运输机场所在地地区民用航空管理机构责令改正，处20万元以上100万元以下的罚款。\n第六十五条 违反本条例的规定，机场管理机构未经批准擅自关闭运输机场的，由运输机场所在地地区民用航空管理机构责令改正，处10万元以上50万元以下的罚款。\n第六十六条 违反本条例的规定，机场管理机构因故不能保障民用航空器飞行安全，临时关闭运输机场，未及时通知有关空中交通管理部门并及时向社会公告，或者经批准关闭运输机场后未及时向社会公告的，由运输机场所在地地区民用航空管理机构责令改正，处2万元以上10万元以下的罚款。\n第六十七条 违反本条例的规定，机场管理机构未按照应急预案的要求进行应急救援演练或者未配备必要的应急救援设备和器材的，由地区民用航空管理机构责令改正，处1万元以上5万元以下的罚款。\n第六十八条 违反本条例的规定，运输机场投入使用后不符合安全运营要求，机场管理机构拒不改正，或者经改正仍不符合安全运营要求的，由民用航空管理部门作出限制使用的决定；情节严重的，吊销运输机场使用许可证。\n第六十九条 机场管理机构未依照本条例的规定履行管理职责，造成运输机场地面事故、民用航空器飞行事故或者严重事故征候的，民用航空管理部门应当责令改正，处20万元以上100万元以下的罚款。\n第七十条 违反本条例的规定，机场管理机构在运输机场内使用不符合国家规定标准和相关技术规范的民用机场专用设备的，由运输机场所在地地区民用航空管理机构责令停止使用，处10万元以上50万元以下的罚款。\n第七十一条 违反本条例的规定，发生突发事件，机场管理机构、空中交通管理部门等单位未按照应急预案的要求及时、有效开展应急救援的，由地区民用航空管理机构责令改正，处10万元以上50万元以下的罚款。\n第七十二条 违反本条例的规定，未取得民用机场航空燃油供应安全运营许可证，在民用机场内从事航空燃油供应业务的，由民用机场所在地地区民用航空管理机构责令改正，处20万元以上100万元以下的罚款；有违法所得的，没收违法所得。\n第七十三条 违反本条例的规定，航空燃油供应企业供应的航空燃油不符合航空燃油适航标准的，由民用机场所在地地区民用航空管理机构责令改正，处20万元以上100万元以下的罚款；情节严重的，吊销民用机场航空燃油供应安全运营许可证。\n第七十四条 违反本条例的规定，运输机场航空燃油供应企业停止运输机场航空燃油供应业务，未提前90日告知地区民用航空管理机构、机场管理机构和相关航空运输企业的，由运输机场所在地地区民用航空管理机构处5万元以上25万元以下的罚款。\n第七十五条 违反本条例的规定，有下列情形之一的，由地区民用航空管理机构责令改正，处2万元以上10万元以下的罚款：\n(一)机场管理机构不按照国家规定的标准配备候机、餐饮、停车、医疗急救等设施、设备，并提供相应的服务；\n(二)航班发生延误时，机场管理机构、航空运输企业以及其他驻场单位不按照有关规定和服务承诺为旅客和货主提供相应的服务。\n第七十六条 违反本条例的规定，机场管理机构及其关联企业参与经营采取有偿转让经营权的方式经营的业务的，由地区民用航空管理机构责令改正，处10万元以上50万元以下的罚款；有违法所得的，没收违法所得。\n第七十七条 违反本条例的规定，机场管理机构未向民用航空管理部门报送运输机场规划、建设和生产运营的有关资料的，由民用航空管理部门责令改正；拒不改正的，处1万元以上5万元以下的罚款。\n第七十八条 违反本条例的规定，在民用机场净空保护区域内设置22万伏以上(含22万伏)的高压输电塔，未依照国务院民用航空主管部门的有关规定设置障碍灯或者标志的，由民用机场所在地地区民用航空管理机构责令改正，处10万元以上50万元以下的罚款。\n第七十九条 违反本条例的规定，有下列情形之一的，由民用机场所在地县级以上地方人民政府责令改正；情节严重的，处2万元以上10万元以下的罚款：\n(一)排放大量烟雾、粉尘、火焰、废气等影响飞行安全的物质；\n(二)修建靶场、强烈爆炸物仓库等影响飞行安全的建筑物或者其他设施；\n(三)设置影响民用机场目视助航设施使用或者飞行员视线的灯光、标志或者物体；\n(四)种植影响飞行安全或者影响民用机场助航设施使用的植物；\n(五)放飞影响飞行安全的鸟类、升放无人驾驶的自由气球、系留气球和其他升空物体；\n(六)焚烧产生大量烟雾的农作物秸秆、垃圾等物质，或者燃放烟花、焰火；\n(七)在民用机场围界外5米范围内，搭建建筑物、种植树木，或者从事挖掘、堆积物体等影响民用机场运营安全的活动；\n(八)国务院民用航空主管部门规定的其他影响民用机场净空保护的行为。\n第八十条 违反本条例的规定，使用的无线电台(站)或者其他仪器、装置，对民用航空无线电专用频率的正常使用产生干扰的，由民用机场所在地无线电管理机构责令改正；情节严重的，处2万元以上10万元以下的罚款。\n第八十一条 违反本条例的规定，在民用航空无线电台(站)电磁环境保护区域内从事下列活动的，由民用机场所在地县级以上地方人民政府责令改正；情节严重的，处2万元以上10万元以下的罚款：\n(一)修建架空高压输电线、架空金属线、铁路、公路、电力排灌站；\n(二)存放金属堆积物；\n(三)从事掘土、采砂、采石等改变地形地貌的活动；\n(四)国务院民用航空主管部门规定的其他影响民用机场电磁环境保护的行为。\n第八十二条 违反本条例的规定，在民用机场起降的民用航空器不符合国家有关航空器噪声和涡轮发动机排出物的适航标准的，由民用航空管理部门责令相关航空运输企业改正，可以处10万元以下的罚款；拒不改正的，处10万元以上50万元以下的罚款。\n第八十三条 国家工作人员违反本条例的规定，有下列情形之一的，由有关部门依法给予处分：\n(一)不依照规定实施行政许可；\n(二)不依法履行监督检查职责；\n(三)不依法实施行政强制措施或者行政处罚；\n(四)滥用职权、玩忽职守的其他行为。","level":1},{"name":"第六章 附则","text":"第八十四条 本条例所称运输机场是指为从事旅客、货物运输等公共航空运输活动的民用航空器提供起飞、降落等服务的机场。\n本条例所称通用机场是指为从事工业、农业、林业、渔业和建筑业的作业飞行，以及医疗卫生、抢险救灾、气象探测、海洋监测、科学实验、教育训练、文化体育等飞行活动的民用航空器提供起飞、降落等服务的机场。\n第八十五条 本条例所称飞行区指标为4D的运输机场是指可供基准飞行场地长度大于1800米、翼展在36米至52米之间、主起落架外轮外侧边间距在9米至14米之间的民用航空器起飞、降落的机场。\n本条例所称飞行区指标为4E的运输机场是指可供基准飞行场地长度大于1800米、翼展在52米至65米之间、主起落架外轮外侧边间距在9米至14米之间的民用航空器起飞、降落的机场。\n第八十六条 军民合用机场民用部分的管理除遵守本条例的有关规定外，还应当遵守国务院、中央军事委员会的有关规定。\n第八十七条 本条例自2009年7月1日起施行。","level":1}]},{"id":"n0341","sections":[{"name":"","text":"中华人民共和国税收征收\n管理法实施细则\n(2002年9月7日中华人民共和国国务院令第362号公布 根据2012年11月9日《国务院关于修改和废止部分行政法规的决定》第一次修订 根据2013年7月18日《国务院关于废止和修改部分行政法规的决定》第二次修订 根据2016年2月6日《国务院关于修改部分行政法规的决定》第三次修订)","level":0},{"name":"第一章 总则","text":"第一条 根据《中华人民共和国税收征收管理法》(以下简称税收征管法)的规定，制定本细则。\n第二条 凡依法由税务机关征收的各种税收的征收管理，均适用税收征管法及本细则；税收征管法及本细则没有规定的，依照其他有关税收法律、行政法规的规定执行。\n第三条 任何部门、单位和个人作出的与税收法律、行政法规相抵触的决定一律无效，税务机关不得执行，并应当向上级税务机关报告。\n纳税人应当依照税收法律、行政法规的规定履行纳税义务；其签订的合同、协议等与税收法律、行政法规相抵触的，一律无效。\n第四条 国家税务总局负责制定全国税务系统信息化建设的总体规划、技术标准、技术方案与实施办法；各级税务机关应当按照国家税务总局的总体规划、技术标准、技术方案与实施办法，做好本地区税务系统信息化建设的具体工作。\n地方各级人民政府应当积极支持税务系统信息化建设，并组织有关部门实现相关信息的共享。\n第五条 税收征管法第八条所称为纳税人、扣缴义务人保密的情况，是指纳税人、扣缴义务人的商业秘密及个人隐私。纳税人、扣缴义务人的税收违法行为不属于保密范围。\n第六条 国家税务总局应当制定税务人员行为准则和服务规范。\n上级税务机关发现下级税务机关的税收违法行为，应当及时予以纠正；下级税务机关应当按照上级税务机关的决定及时改正。\n下级税务机关发现上级税务机关的税收违法行为，应当向上级税务机关或者有关部门报告。\n第七条 税务机关根据检举人的贡献大小给予相应的奖励，奖励所需资金列入税务部门年度预算，单项核定。奖励资金具体使用办法以及奖励标准，由国家税务总局会同财政部制定。\n第八条 税务人员在核定应纳税额、调整税收定额、进行税务检查、实施税务行政处罚、办理税务行政复议时，与纳税人、扣缴义务人或者其法定代表人、直接责任人有下列关系之一的，应当回避：\n(一)夫妻关系；\n(二)直系血亲关系；\n(三)三代以内旁系血亲关系；\n(四)近姻亲关系；\n(五)可能影响公正执法的其他利害关系。\n第九条 税收征管法第十四条所称按照国务院规定设立的并向社会公告的税务机构，是指省以下税务局的稽查局。稽查局专司偷税、逃避追缴欠税、骗税、抗税案件的查处。\n国家税务总局应当明确划分税务局和稽查局的职责，避免职责交叉。","level":1},{"name":"第二章 税务登记","text":"第十条 国家税务局、地方税务局对同一纳税人的税务登记应当采用同一代码，信息共享。\n税务登记的具体办法由国家税务总局制定。\n第十一条 各级工商行政管理机关应当向同级国家税务局和地方税务局定期通报办理开业、变更、注销登记以及吊销营业执照的情况。\n通报的具体办法由国家税务总局和国家工商行政管理总局联合制定。\n第十二条 从事生产、经营的纳税人应当自领取营业执照之日起30日内，向生产、经营地或者纳税义务发生地的主管税务机关申报办理税务登记，如实填写税务登记表，并按照税务机关的要求提供有关证件、资料。\n前款规定以外的纳税人，除国家机关和个人外，应当自纳税义务发生之日起30日内，持有关证件向所在地的主管税务机关申报办理税务登记。\n个人所得税的纳税人办理税务登记的办法由国务院另行规定。\n税务登记证件的式样，由国家税务总局制定。\n第十三条 扣缴义务人应当自扣缴义务发生之日起30日内，向所在地的主管税务机关申报办理扣缴税款登记，领取扣缴税款登记证件；税务机关对已办理税务登记的扣缴义务人，可以只在其税务登记证件上登记扣缴税款事项，不再发给扣缴税款登记证件。\n第十四条 纳税人税务登记内容发生变化的，应当自工商行政管理机关或者其他机关办理变更登记之日起30日内，持有关证件向原税务登记机关申报办理变更税务登记。\n纳税人税务登记内容发生变化，不需要到工商行政管理机关或者其他机关办理变更登记的，应当自发生变化之日起30日内，持有关证件向原税务登记机关申报办理变更税务登记。\n第十五条 纳税人发生解散、破产、撤销以及其他情形，依法终止纳税义务的，应当在向工商行政管理机关或者其他机关办理注销登记前，持有关证件向原税务登记机关申报办理注销税务登记；按照规定不需要在工商行政管理机关或者其他机关办理注册登记的，应当自有关机关批准或者宣告终止之日起15日内，持有关证件向原税务登记机关申报办理注销税务登记。\n纳税人因住所、经营地点变动，涉及改变税务登记机关的，应当在向工商行政管理机关或者其他机关申请办理变更或者注销登记前或者住所、经营地点变动前，向原税务登记机关申报办理注销税务登记，并在30日内向迁达地税务机关申报办理税务登记。\n纳税人被工商行政管理机关吊销营业执照或者被其他机关予以撤销登记的，应当自营业执照被吊销或者被撤销登记之日起15日内，向原税务登记机关申报办理注销税务登记。\n第十六条 纳税人在办理注销税务登记前，应当向税务机关结清应纳税款、滞纳金、罚款，缴销发票、税务登记证件和其他税务证件。\n第十七条 从事生产、经营的纳税人应当自开立基本存款账户或者其他存款账户之日起15日内，向主管税务机关书面报告其全部账号；发生变化的，应当自变化之日起15日内，向主管税务机关书面报告。\n第十八条 除按照规定不需要发给税务登记证件的外，纳税人办理下列事项时，必须持税务登记证件：\n(一)开立银行账户；\n(二)申请减税、免税、退税；\n(三)申请办理延期申报、延期缴纳税款；\n(四)领购发票；\n(五)申请开具外出经营活动税收管理证明；\n(六)办理停业、歇业；\n(七)其他有关税务事项。\n第十九条 税务机关对税务登记证件实行定期验证和换证制度。纳税人应当在规定的期限内持有关证件到主管税务机关办理验证或者换证手续。\n第二十条 纳税人应当将税务登记证件正本在其生产、经营场所或者办公场所公开悬挂，接受税务机关检查。\n纳税人遗失税务登记证件的，应当在15日内书面报告主管税务机关，并登报声明作废。\n第二十一条 从事生产、经营的纳税人到外县(市)临时从事生产、经营活动的，应当持税务登记证副本和所在地税务机关填开的外出经营活动税收管理证明，向营业地税务机关报验登记，接受税务管理。\n从事生产、经营的纳税人外出经营，在同一地累计超过180天的，应当在营业地办理税务登记手续。","level":1},{"name":"第三章 账簿、凭证管理","text":"第二十二条 从事生产、经营的纳税人应当自领取营业执照或者发生纳税义务之日起15日内，按照国家有关规定设置账簿。\n前款所称账簿，是指总账、明细账、日记账以及其他辅助性账簿。总账、日记账应当采用订本式。\n第二十三条 生产、经营规模小又确无建账能力的纳税人，可以聘请经批准从事会计代理记账业务的专业机构或者财会人员代为建账和办理账务。\n第二十四条 从事生产、经营的纳税人应当自领取税务登记证件之日起15日内，将其财务、会计制度或者财务、会计处理办法报送主管税务机关备案。\n纳税人使用计算机记账的，应当在使用前将会计电算化系统的会计核算软件、使用说明书及有关资料报送主管税务机关备案。\n纳税人建立的会计电算化系统应当符合国家有关规定，并能正确、完整核算其收入或者所得。\n第二十五条 扣缴义务人应当自税收法律、行政法规规定的扣缴义务发生之日起10日内，按照所代扣、代收的税种，分别设置代扣代缴、代收代缴税款账簿。\n第二十六条 纳税人、扣缴义务人会计制度健全，能够通过计算机正确、完整计算其收入和所得或者代扣代缴、代收代缴税款情况的，其计算机输出的完整的书面会计记录，可视同会计账簿。\n纳税人、扣缴义务人会计制度不健全，不能通过计算机正确、完整计算其收入和所得或者代扣代缴、代收代缴税款情况的，应当建立总账及与纳税或者代扣代缴、代收代缴税款有关的其他账簿。\n第二十七条 账簿、会计凭证和报表，应当使用中文。民族自治地方可以同时使用当地通用的一种民族文字。外商投资企业和外国企业可以同时使用一种外国文字。\n第二十八条 纳税人应当按照税务机关的要求安装、使用税控装置，并按照税务机关的规定报送有关数据和资料。\n税控装置推广应用的管理办法由国家税务总局另行制定，报国务院批准后实施。\n第二十九条 账簿、记账凭证、报表、完税凭证、发票、出口凭证以及其他有关涉税资料应当合法、真实、完整。\n账簿、记账凭证、报表、完税凭证、发票、出口凭证以及其他有关涉税资料应当保存10年；但是，法律、行政法规另有规定的除外。","level":1},{"name":"第四章 纳税申报","text":"第三十条 税务机关应当建立、健全纳税人自行申报纳税制度。纳税人、扣缴义务人可以采取邮寄、数据电文方式办理纳税申报或者报送代扣代缴、代收代缴税款报告表。\n数据电文方式，是指税务机关确定的电话语音、电子数据交换和网络传输等电子方式。\n第三十一条 纳税人采取邮寄方式办理纳税申报的，应当使用统一的纳税申报专用信封，并以邮政部门收据作为申报凭据。邮寄申报以寄出的邮戳日期为实际申报日期。\n纳税人采取电子方式办理纳税申报的，应当按照税务机关规定的期限和要求保存有关资料，并定期书面报送主管税务机关。\n第三十二条 纳税人在纳税期内没有应纳税款的，也应当按照规定办理纳税申报。\n纳税人享受减税、免税待遇的，在减税、免税期间应当按照规定办理纳税申报。\n第三十三条 纳税人、扣缴义务人的纳税申报或者代扣代缴、代收代缴税款报告表的主要内容包括：税种、税目，应纳税项目或者应代扣代缴、代收代缴税款项目，计税依据，扣除项目及标准，适用税率或者单位税额，应退税项目及税额、应减免税项目及税额，应纳税额或者应代扣代缴、代收代缴税额，税款所属期限、延期缴纳税款、欠税、滞纳金等。\n第三十四条 纳税人办理纳税申报时，应当如实填写纳税申报表，并根据不同的情况相应报送下列有关证件、资料：\n(一)财务会计报表及其说明材料；\n(二)与纳税有关的合同、协议书及凭证；\n(三)税控装置的电子报税资料；\n(四)外出经营活动税收管理证明和异地完税凭证；\n(五)境内或者境外公证机构出具的有关证明文件；\n(六)税务机关规定应当报送的其他有关证件、资料。\n第三十五条 扣缴义务人办理代扣代缴、代收代缴税款报告时，应当如实填写代扣代缴、代收代缴税款报告表，并报送代扣代缴、代收代缴税款的合法凭证以及税务机关规定的其他有关证件、资料。\n第三十六条 实行定期定额缴纳税款的纳税人，可以实行简易申报、简并征期等申报纳税方式。\n第三十七条 纳税人、扣缴义务人按照规定的期限办理纳税申报或者报送代扣代缴、代收代缴税款报告表确有困难，需要延期的，应当在规定的期限内向税务机关提出书面延期申请，经税务机关核准，在核准的期限内办理。\n纳税人、扣缴义务人因不可抗力，不能按期办理纳税申报或者报送代扣代缴、代收代缴税款报告表的，可以延期办理；但是，应当在不可抗力情形消除后立即向税务机关报告。税务机关应当查明事实，予以核准。","level":1},{"name":"第五章 税款征收","text":"第三十八条 税务机关应当加强对税款征收的管理，建立、健全责任制度。\n税务机关根据保证国家税款及时足额入库、方便纳税人、降低税收成本的原则，确定税款征收的方式。\n税务机关应当加强对纳税人出口退税的管理，具体管理办法由国家税务总局会同国务院有关部门制定。\n第三十九条 税务机关应当将各种税收的税款、滞纳金、罚款，按照国家规定的预算科目和预算级次及时缴入国库，税务机关不得占压、挪用、截留，不得缴入国库以外或者国家规定的税款账户以外的任何账户。\n已缴入国库的税款、滞纳金、罚款，任何单位和个人不得擅自变更预算科目和预算级次。\n第四十条 税务机关应当根据方便、快捷、安全的原则，积极推广使用支票、银行卡、电子结算方式缴纳税款。\n第四十一条 纳税人有下列情形之一的，属于税收征管法第三十一条所称特殊困难：\n(一)因不可抗力，导致纳税人发生较大损失，正常生产经营活动受到较大影响的；\n(二)当期货币资金在扣除应付职工工资、社会保险费后，不足以缴纳税款的。\n计划单列市国家税务局、地方税务局可以参照税收征管法第三十一条第二款的批准权限，审批纳税人延期缴纳税款。\n第四十二条 纳税人需要延期缴纳税款的，应当在缴纳税款期限届满前提出申请，并报送下列材料：申请延期缴纳税款报告，当期货币资金余额情况及所有银行存款账户的对账单，资产负债表，应付职工工资和社会保险费等税务机关要求提供的支出预算。\n税务机关应当自收到申请延期缴纳税款报告之日起20日内作出批准或者不予批准的决定；不予批准的，从缴纳税款期限届满之日起加收滞纳金。\n第四十三条 享受减税、免税优惠的纳税人，减税、免税期满，应当自期满次日起恢复纳税；减税、免税条件发生变化的，应当在纳税申报时向税务机关报告；不再符合减税、免税条件的，应当依法履行纳税义务；未依法纳税的，税务机关应当予以追缴。\n第四十四条 税务机关根据有利于税收控管和方便纳税的原则，可以按照国家有关规定委托有关单位和人员代征零星分散和异地缴纳的税收，并发给委托代征证书。受托单位和人员按照代征证书的要求，以税务机关的名义依法征收税款，纳税人不得拒绝；纳税人拒绝的，受托代征单位和人员应当及时报告税务机关。\n第四十五条 税收征管法第三十四条所称完税凭证，是指各种完税证、缴款书、印花税票、扣(收)税凭证以及其他完税证明。\n未经税务机关指定，任何单位、个人不得印制完税凭证。完税凭证不得转借、倒卖、变造或者伪造。\n完税凭证的式样及管理办法由国家税务总局制定。\n第四十六条 税务机关收到税款后，应当向纳税人开具完税凭证。纳税人通过银行缴纳税款的，税务机关可以委托银行开具完税凭证。\n第四十七条 纳税人有税收征管法第三十五条或者第三十七条所列情形之一的，税务机关有权采用下列任何一种方法核定其应纳税额：\n(一)参照当地同类行业或者类似行业中经营规模和收入水平相近的纳税人的税负水平核定；\n(二)按照营业收入或者成本加合理的费用和利润的方法核定；\n(三)按照耗用的原材料、燃料、动力等推算或者测算核定；\n(四)按照其他合理方法核定。\n采用前款所列一种方法不足以正确核定应纳税额时，可以同时采用两种以上的方法核定。\n纳税人对税务机关采取本条规定的方法核定的应纳税额有异议的，应当提供相关证据，经税务机关认定后，调整应纳税额。\n第四十八条 税务机关负责纳税人纳税信誉等级评定工作。纳税人纳税信誉等级的评定办法由国家税务总局制定。\n第四十九条 承包人或者承租人有独立的生产经营权，在财务上独立核算，并定期向发包人或者出租人上缴承包费或者租金的，承包人或者承租人应当就其生产、经营收入和所得纳税，并接受税务管理；但是，法律、行政法规另有规定的除外。\n发包人或者出租人应当自发包或者出租之日起30日内将承包人或者承租人的有关情况向主管税务机关报告。发包人或者出租人不报告的，发包人或者出租人与承包人或者承租人承担纳税连带责任。\n第五十条 纳税人有解散、撤销、破产情形的，在清算前应当向其主管税务机关报告；未结清税款的，由其主管税务机关参加清算。\n第五十一条 税收征管法第三十六条所称关联企业，是指有下列关系之一的公司、企业和其他经济组织：\n(一)在资金、经营、购销等方面，存在直接或者间接的拥有或者控制关系；\n(二)直接或者间接地同为第三者所拥有或者控制；\n(三)在利益上具有相关联的其他关系。\n纳税人有义务就其与关联企业之间的业务往来，向当地税务机关提供有关的价格、费用标准等资料。具体办法由国家税务总局制定。\n第五十二条 税收征管法第三十六条所称独立企业之间的业务往来，是指没有关联关系的企业之间按照公平成交价格和营业常规所进行的业务往来。\n第五十三条 纳税人可以向主管税务机关提出与其关联企业之间业务往来的定价原则和计算方法，主管税务机关审核、批准后，与纳税人预先约定有关定价事项，监督纳税人执行。\n第五十四条 纳税人与其关联企业之间的业务往来有下列情形之一的，税务机关可以调整其应纳税额：\n(一)购销业务未按照独立企业之间的业务往来作价；\n(二)融通资金所支付或者收取的利息超过或者低于没有关联关系的企业之间所能同意的数额，或者利率超过或者低于同类业务的正常利率；\n(三)提供劳务，未按照独立企业之间业务往来收取或者支付劳务费用；\n(四)转让财产、提供财产使用权等业务往来，未按照独立企业之间业务往来作价或者收取、支付费用；\n(五)未按照独立企业之间业务往来作价的其他情形。\n第五十五条 纳税人有本细则第五十四条所列情形之一的，税务机关可以按照下列方法调整计税收入额或者所得额：\n(一)按照独立企业之间进行的相同或者类似业务活动的价格；\n(二)按照再销售给无关联关系的第三者的价格所应取得的收入和利润水平；\n(三)按照成本加合理的费用和利润；\n(四)按照其他合理的方法。\n第五十六条 纳税人与其关联企业未按照独立企业之间的业务往来支付价款、费用的，税务机关自该业务往来发生的纳税年度起3年内进行调整；有特殊情况的，可以自该业务往来发生的纳税年度起10年内进行调整。\n第五十七条 税收征管法第三十七条所称未按照规定办理税务登记从事生产、经营的纳税人，包括到外县(市)从事生产、经营而未向营业地税务机关报验登记的纳税人。\n第五十八条 税务机关依照税收征管法第三十七条的规定，扣押纳税人商品、货物的，纳税人应当自扣押之日起15日内缴纳税款。\n对扣押的鲜活、易腐烂变质或者易失效的商品、货物，税务机关根据被扣押物品的保质期，可以缩短前款规定的扣押期限。\n第五十九条 税收征管法第三十八条、第四十条所称其他财产，包括纳税人的房地产、现金、有价证券等不动产和动产。\n机动车辆、金银饰品、古玩字画、豪华住宅或者一处以外的住房不属于税收征管法第三十八条、第四十条、第四十二条所称个人及其所扶养家属维持生活必需的住房和用品。\n税务机关对单价5000元以下的其他生活用品，不采取税收保全措施和强制执行措施。\n第六十条 税收征管法第三十八条、第四十条、第四十二条所称个人所扶养家属，是指与纳税人共同居住生活的配偶、直系亲属以及无生活来源并由纳税人扶养的其他亲属。\n第六十一条 税收征管法第三十八条、第八十八条所称担保，包括经税务机关认可的纳税保证人为纳税人提供的纳税保证，以及纳税人或者第三人以其未设置或者未全部设置担保物权的财产提供的担保。\n纳税保证人，是指在中国境内具有纳税担保能力的自然人、法人或者其他经济组织。\n法律、行政法规规定的没有担保资格的单位和个人，不得作为纳税担保人。\n第六十二条 纳税担保人同意为纳税人提供纳税担保的，应当填写纳税担保书，写明担保对象、担保范围、担保期限和担保责任以及其他有关事项。担保书须经纳税人、纳税担保人签字盖章并经税务机关同意，方为有效。\n纳税人或者第三人以其财产提供纳税担保的，应当填写财产清单，并写明财产价值以及其他有关事项。纳税担保财产清单须经纳税人、第三人签字盖章并经税务机关确认，方为有效。\n第六十三条 税务机关执行扣押、查封商品、货物或者其他财产时，应当由两名以上税务人员执行，并通知被执行人。被执行人是自然人的，应当通知被执行人本人或者其成年家属到场；被执行人是法人或者其他组织的，应当通知其法定代表人或者主要负责人到场；拒不到场的，不影响执行。\n第六十四条 税务机关执行税收征管法第三十七条、第三十八条、第四十条的规定，扣押、查封价值相当于应纳税款的商品、货物或者其他财产时，参照同类商品的市场价、出厂价或者评估价估算。\n税务机关按照前款方法确定应扣押、查封的商品、货物或者其他财产的价值时，还应当包括滞纳金和拍卖、变卖所发生的费用。\n第六十五条 对价值超过应纳税额且不可分割的商品、货物或者其他财产，税务机关在纳税人、扣缴义务人或者纳税担保人无其他可供强制执行的财产的情况下，可以整体扣押、查封、拍卖。\n第六十六条 税务机关执行税收征管法第三十七条、第三十八条、第四十条的规定，实施扣押、查封时，对有产权证件的动产或者不动产，税务机关可以责令当事人将产权证件交税务机关保管，同时可以向有关机关发出协助执行通知书，有关机关在扣押、查封期间不再办理该动产或者不动产的过户手续。\n第六十七条 对查封的商品、货物或者其他财产，税务机关可以指令被执行人负责保管，保管责任由被执行人承担。\n继续使用被查封的财产不会减少其价值的，税务机关可以允许被执行人继续使用；因被执行人保管或者使用的过错造成的损失，由被执行人承担。\n第六十八条 纳税人在税务机关采取税收保全措施后，按照税务机关规定的期限缴纳税款的，税务机关应当自收到税款或者银行转回的完税凭证之日起1日内解除税收保全。\n第六十九条 税务机关将扣押、查封的商品、货物或者其他财产变价抵缴税款时，应当交由依法成立的拍卖机构拍卖；无法委托拍卖或者不适于拍卖的，可以交由当地商业企业代为销售，也可以责令纳税人限期处理；无法委托商业企业销售，纳税人也无法处理的，可以由税务机关变价处理，具体办法由国家税务总局规定。国家禁止自由买卖的商品，应当交由有关单位按照国家规定的价格收购。\n拍卖或者变卖所得抵缴税款、滞纳金、罚款以及拍卖、变卖等费用后，剩余部分应当在3日内退还被执行人。\n第七十条 税收征管法第三十九条、第四十三条所称损失，是指因税务机关的责任，使纳税人、扣缴义务人或者纳税担保人的合法利益遭受的直接损失。\n第七十一条 税收征管法所称其他金融机构，是指信托投资公司、信用合作社、邮政储蓄机构以及经中国人民银行、中国证券监督管理委员会等批准设立的其他金融机构。\n第七十二条 税收征管法所称存款，包括独资企业投资人、合伙企业合伙人、个体工商户的储蓄存款以及股东资金账户中的资金等。\n第七十三条 从事生产、经营的纳税人、扣缴义务人未按照规定的期限缴纳或者解缴税款的，纳税担保人未按照规定的期限缴纳所担保的税款的，由税务机关发出限期缴纳税款通知书，责令缴纳或者解缴税款的最长期限不得超过15日。\n第七十四条 欠缴税款的纳税人或者其法定代表人在出境前未按照规定结清应纳税款、滞纳金或者提供纳税担保的，税务机关可以通知出入境管理机关阻止其出境。阻止出境的具体办法，由国家税务总局会同公安部制定。\n第七十五条 税收征管法第三十二条规定的加收滞纳金的起止时间，为法律、行政法规规定或者税务机关依照法律、行政法规的规定确定的税款缴纳期限届满次日起至纳税人、扣缴义务人实际缴纳或者解缴税款之日止。\n第七十六条 县级以上各级税务机关应当将纳税人的欠税情况，在办税场所或者广播、电视、报纸、期刊、网络等新闻媒体上定期公告。\n对纳税人欠缴税款的情况实行定期公告的办法，由国家税务总局制定。\n第七十七条 税收征管法第四十九条所称欠缴税款数额较大，是指欠缴税款5万元以上。\n第七十八条 税务机关发现纳税人多缴税款的，应当自发现之日起10日内办理退还手续；纳税人发现多缴税款，要求退还的，税务机关应当自接到纳税人退还申请之日起30日内查实并办理退还手续。\n税收征管法第五十一条规定的加算银行同期存款利息的多缴税款退税，不包括依法预缴税款形成的结算退税、出口退税和各种减免退税。\n退税利息按照税务机关办理退税手续当天中国人民银行规定的活期存款利率计算。\n第七十九条 当纳税人既有应退税款又有欠缴税款的，税务机关可以将应退税款和利息先抵扣欠缴税款；抵扣后有余额的，退还纳税人。\n第八十条 税收征管法第五十二条所称税务机关的责任，是指税务机关适用税收法律、行政法规不当或者执法行为违法。\n第八十一条 税收征管法第五十二条所称纳税人、扣缴义务人计算错误等失误，是指非主观故意的计算公式运用错误以及明显的笔误。\n第八十二条 税收征管法第五十二条所称特殊情况，是指纳税人或者扣缴义务人因计算错误等失误，未缴或者少缴、未扣或者少扣、未收或者少收税款，累计数额在10万元以上的。\n第八十三条 税收征管法第五十二条规定的补缴和追征税款、滞纳金的期限，自纳税人、扣缴义务人应缴未缴或者少缴税款之日起计算。\n第八十四条 审计机关、财政机关依法进行审计、检查时，对税务机关的税收违法行为作出的决定，税务机关应当执行；发现被审计、检查单位有税收违法行为的，向被审计、检查单位下达决定、意见书，责成被审计、检查单位向税务机关缴纳应当缴纳的税款、滞纳金。税务机关应当根据有关机关的决定、意见书，依照税收法律、行政法规的规定，将应收的税款、滞纳金按照国家规定的税收征收管理范围和税款入库预算级次缴入国库。\n税务机关应当自收到审计机关、财政机关的决定、意见书之日起30日内将执行情况书面回复审计机关、财政机关。\n有关机关不得将其履行职责过程中发现的税款、滞纳金自行征收入库或者以其他款项的名义自行处理、占压。","level":1},{"name":"第六章 税务检查","text":"第八十五条 税务机关应当建立科学的检查制度，统筹安排检查工作，严格控制对纳税人、扣缴义务人的检查次数。\n税务机关应当制定合理的税务稽查工作规程，负责选案、检查、审理、执行的人员的职责应当明确，并相互分离、相互制约，规范选案程序和检查行为。\n税务检查工作的具体办法，由国家税务总局制定。\n第八十六条 税务机关行使税收征管法第五十四条第(一)项职权时，可以在纳税人、扣缴义务人的业务场所进行；必要时，经县以上税务局(分局)局长批准，可以将纳税人、扣缴义务人以前会计年度的账簿、记账凭证、报表和其他有关资料调回税务机关检查，但是税务机关必须向纳税人、扣缴义务人开付清单，并在3个月内完整退还；有特殊情况的，经设区的市、自治州以上税务局局长批准，税务机关可以将纳税人、扣缴义务人当年的账簿、记账凭证、报表和其他有关资料调回检查，但是税务机关必须在30日内退还。\n第八十七条 税务机关行使税收征管法第五十四条第(六)项职权时，应当指定专人负责，凭全国统一格式的检查存款账户许可证明进行，并有责任为被检查人保守秘密。\n检查存款账户许可证明，由国家税务总局制定。\n税务机关查询的内容，包括纳税人存款账户余额和资金往来情况。\n第八十八条 依照税收征管法第五十五条规定，税务机关采取税收保全措施的期限一般不得超过6个月；重大案件需要延长的，应当报国家税务总局批准。\n第八十九条 税务机关和税务人员应当依照税收征管法及本细则的规定行使税务检查职权。\n税务人员进行税务检查时，应当出示税务检查证和税务检查通知书；无税务检查证和税务检查通知书的，纳税人、扣缴义务人及其他当事人有权拒绝检查。税务机关对集贸市场及集中经营业户进行检查时，可以使用统一的税务检查通知书。\n税务检查证和税务检查通知书的式样、使用和管理的具体办法，由国家税务总局制定。","level":1},{"name":"第七章 法律责任","text":"第九十条 纳税人未按照规定办理税务登记证件验证或者换证手续的，由税务机关责令限期改正，可以处2000元以下的罚款；情节严重的，处2000元以上1万元以下的罚款。\n第九十一条 非法印制、转借、倒卖、变造或者伪造完税凭证的，由税务机关责令改正，处2000元以上1万元以下的罚款；情节严重的，处1万元以上5万元以下的罚款；构成犯罪的，依法追究刑事责任。\n第九十二条 银行和其他金融机构未依照税收征管法的规定在从事生产、经营的纳税人的账户中登录税务登记证件号码，或者未按规定在税务登记证件中登录从事生产、经营的纳税人的账户账号的，由税务机关责令其限期改正，处2000元以上2万元以下的罚款；情节严重的，处2万元以上5万元以下的罚款。\n第九十三条 为纳税人、扣缴义务人非法提供银行账户、发票、证明或者其他方便，导致未缴、少缴税款或者骗取国家出口退税款的，税务机关除没收其违法所得外，可以处未缴、少缴或者骗取的税款1倍以下的罚款。\n第九十四条 纳税人拒绝代扣、代收税款的，扣缴义务人应当向税务机关报告，由税务机关直接向纳税人追缴税款、滞纳金；纳税人拒不缴纳的，依照税收征管法第六十八条的规定执行。\n第九十五条 税务机关依照税收征管法第五十四条第(五)项的规定，到车站、码头、机场、邮政企业及其分支机构检查纳税人有关情况时，有关单位拒绝的，由税务机关责令改正，可以处1万元以下的罚款；情节严重的，处1万元以上5万元以下的罚款。\n第九十六条 纳税人、扣缴义务人有下列情形之一的，依照税收征管法第七十条的规定处罚：\n(一)提供虚假资料，不如实反映情况，或者拒绝提供有关资料的；\n(二)拒绝或者阻止税务机关记录、录音、录像、照相和复制与案件有关的情况和资料的；\n(三)在检查期间，纳税人、扣缴义务人转移、隐匿、销毁有关资料的；\n(四)有不依法接受税务检查的其他情形的。\n第九十七条 税务人员私分扣押、查封的商品、货物或者其他财产，情节严重，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。\n第九十八条 税务代理人违反税收法律、行政法规，造成纳税人未缴或者少缴税款的，除由纳税人缴纳或者补缴应纳税款、滞纳金外，对税务代理人处纳税人未缴或者少缴税款50%以上3倍以下的罚款。\n第九十九条 税务机关对纳税人、扣缴义务人及其他当事人处以罚款或者没收违法所得时，应当开付罚没凭证；未开付罚没凭证的，纳税人、扣缴义务人以及其他当事人有权拒绝给付。\n第一百条 税收征管法第八十八条规定的纳税争议，是指纳税人、扣缴义务人、纳税担保人对税务机关确定纳税主体、征税对象、征税范围、减税、免税及退税、适用税率、计税依据、纳税环节、纳税期限、纳税地点以及税款征收方式等具体行政行为有异议而发生的争议。","level":1},{"name":"第八章 文书送达","text":"第一百零一条 税务机关送达税务文书，应当直接送交受送达人。\n受送达人是公民的，应当由本人直接签收；本人不在的，交其同住成年家属签收。\n受送达人是法人或者其他组织的，应当由法人的法定代表人、其他组织的主要负责人或者该法人、组织的财务负责人、负责收件的人签收。受送达人有代理人的，可以送交其代理人签收。\n第一百零二条 送达税务文书应当有送达回证，并由受送达人或者本细则规定的其他签收人在送达回证上记明收到日期，签名或者盖章，即为送达。\n第一百零三条 受送达人或者本细则规定的其他签收人拒绝签收税务文书的，送达人应当在送达回证上记明拒收理由和日期，并由送达人和见证人签名或者盖章，将税务文书留在受送达人处，即视为送达。\n第一百零四条 直接送达税务文书有困难的，可以委托其他有关机关或者其他单位代为送达，或者邮寄送达。\n第一百零五条 直接或者委托送达税务文书的，以签收人或者见证人在送达回证上的签收或者注明的收件日期为送达日期；邮寄送达的，以挂号函件回执上注明的收件日期为送达日期，并视为已送达。\n第一百零六条 有下列情形之一的，税务机关可以公告送达税务文书，自公告之日起满30日，即视为送达：\n(一)同一送达事项的受送达人众多；\n(二)采用本章规定的其他送达方式无法送达。\n第一百零七条 税务文书的格式由国家税务总局制定。本细则所称税务文书，包括：\n(一)税务事项通知书；\n(二)责令限期改正通知书；\n(三)税收保全措施决定书；\n(四)税收强制执行决定书；\n(五)税务检查通知书；\n(六)税务处理决定书；\n(七)税务行政处罚决定书；\n(八)行政复议决定书；\n(九)其他税务文书。","level":1},{"name":"第九章 附则","text":"第一百零八条 税收征管法及本细则所称“以上”、“以下”、“日内”、“届满”均含本数。\n第一百零九条 税收征管法及本细则所规定期限的最后一日是法定休假日的，以休假日期满的次日为期限的最后一日；在期限内有连续3日以上法定休假日的，按休假日天数顺延。\n第一百一十条 税收征管法第三十条第三款规定的代扣、代收手续费，纳入预算管理，由税务机关依照法律、行政法规的规定付给扣缴义务人。\n第一百一十一条 纳税人、扣缴义务人委托税务代理人代为办理税务事宜的办法，由国家税务总局规定。\n第一百一十二条 耕地占用税、契税、农业税、牧业税的征收管理，按照国务院的有关规定执行。\n第一百一十三条 本细则自2002年10月15日起施行。1993年8月4日国务院发布的《中华人民共和国税收征收管理法实施细则》同时废止。","level":1}]},{"id":"n0342","sections":[{"name":"","text":"禁止使用童工规定\n(2002年9月18日国务院第63次常务会议通过 2002年10月1日中华人民共和国国务院令第364号公布 自2002年12月1日起施行)\n第一条 为保护未成年人的身心健康，促进义务教育制度的实施，维护未成年人的合法权益，根据宪法和劳动法、未成年人保护法，制定本规定。\n第二条 国家机关、社会团体、企业事业单位、民办非企业单位或者个体工商户(以下统称用人单位)均不得招用不满16周岁的未成年人(招用不满16周岁的未成年人，以下统称使用童工)。\n禁止任何单位或者个人为不满16周岁的未成年人介绍就业。\n禁止不满16周岁的未成年人开业从事个体经营活动。\n第三条 不满16周岁的未成年人的父母或者其他监护人应当保护其身心健康，保障其接受义务教育的权利，不得允许其被用人单位非法招用。\n不满16周岁的未成年人的父母或者其他监护人允许其被用人单位非法招用的，所在地的乡(镇)人民政府、城市街道办事处以及村民委员会、居民委员会应当给予批评教育。\n第四条 用人单位招用人员时，必须核查被招用人员的身份证；对不满16周岁的未成年人，一律不得录用。用人单位录用人员的录用登记、核查材料应当妥善保管。\n第五条 县级以上各级人民政府劳动保障行政部门负责本规定执行情况的监督检查。\n县级以上各级人民政府公安、工商行政管理、教育、卫生等行政部门在各自职责范围内对本规定的执行情况进行监督检查，并对劳动保障行政部门的监督检查给予配合。\n工会、共青团、妇联等群众组织应当依法维护未成年人的合法权益。\n任何单位或者个人发现使用童工的，均有权向县级以上人民政府劳动保障行政部门举报。\n第六条 用人单位使用童工的，由劳动保障行政部门按照每使用一名童工每月处5000元罚款的标准给予处罚；在使用有毒物品的作业场所使用童工的，按照《使用有毒物品作业场所劳动保护条例》规定的罚款幅度，或者按照每使用一名童工每月处5000元罚款的标准，从重处罚。劳动保障行政部门并应当责令用人单位限期将童工送回原居住地交其父母或者其他监护人，所需交通和食宿费用全部由用人单位承担。\n用人单位经劳动保障行政部门依照前款规定责令限期改正，逾期仍不将童工送交其父母或者其他监护人的，从责令限期改正之日起，由劳动保障行政部门按照每使用一名童工每月处1万元罚款的标准处罚，并由工商行政管理部门吊销其营业执照或者由民政部门撤销民办非企业单位登记；用人单位是国家机关、事业单位的，由有关单位依法对直接负责的主管人员和其他直接责任人员给予降级或者撤职的行政处分或者纪律处分。\n第七条 单位或者个人为不满16周岁的未成年人介绍就业的，由劳动保障行政部门按照每介绍一人处5000元罚款的标准给予处罚；职业中介机构为不满16周岁的未成年人介绍就业的，并由劳动保障行政部门吊销其职业介绍许可证。\n第八条 用人单位未按照本规定第四条的规定保存录用登记材料，或者伪造录用登记材料的，由劳动保障行政部门处1万元的罚款。\n第九条 无营业执照、被依法吊销营业执照的单位以及未依法登记、备案的单位使用童工或者介绍童工就业的，依照本规定第六条、第七条、第八条规定的标准加一倍罚款，该非法单位由有关的行政主管部门予以取缔。\n第十条 童工患病或者受伤的，用人单位应当负责送到医疗机构治疗，并负担治疗期间的全部医疗和生活费用。\n童工伤残或者死亡的，用人单位由工商行政管理部门吊销营业执照或者由民政部门撤销民办非企业单位登记；用人单位是国家机关、事业单位的，由有关单位依法对直接负责的主管人员和其他直接责任人员给予降级或者撤职的行政处分或者纪律处分；用人单位还应当一次性地对伤残的童工、死亡童工的直系亲属给予赔偿，赔偿金额按照国家工伤保险的有关规定计算。\n第十一条 拐骗童工，强迫童工劳动，使用童工从事高空、井下、放射性、高毒、易燃易爆以及国家规定的第四级体力劳动强度的劳动，使用不满14周岁的童工，或者造成童工死亡或者严重伤残的，依照刑法关于拐卖儿童罪、强迫劳动罪或者其他罪的规定，依法追究刑事责任。\n第十二条 国家行政机关工作人员有下列行为之一的，依法给予记大过或者降级的行政处分；情节严重的，依法给予撤职或者开除的行政处分；构成犯罪的，依照刑法关于滥用职权罪、玩忽职守罪或者其他罪的规定，依法追究刑事责任：\n(一)劳动保障等有关部门工作人员在禁止使用童工的监督检查工作中发现使用童工的情况，不予制止、纠正、查处的；\n(二)公安机关的人民警察违反规定发放身份证或者在身份证上登录虚假出生年月的；\n(三)工商行政管理部门工作人员发现申请人是不满16周岁的未成年人，仍然为其从事个体经营发放营业执照的。\n第十三条 文艺、体育单位经未成年人的父母或者其他监护人同意，可以招用不满16周岁的专业文艺工作者、运动员。用人单位应当保障被招用的不满16周岁的未成年人的身心健康，保障其接受义务教育的权利。文艺、体育单位招用不满16周岁的专业文艺工作者、运动员的办法，由国务院劳动保障行政部门会同国务院文化、体育行政部门制定。\n学校、其他教育机构以及职业培训机构按照国家有关规定组织不满16周岁的未成年人进行不影响其人身安全和身心健康的教育实践劳动、职业技能培训劳动，不属于使用童工。\n第十四条 本规定自2002年12月1日起施行。1991年4月15日国务院发布的《禁止使用童工规定》同时废止。","level":0}]},{"id":"n0343","sections":[{"name":"","text":"保税区海关监管办法\n(1997年6月10日国务院批准 1997年8月1日海关总署令第65号发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强与完善海关对保税区的监管，促进保税区的健康发展，根据海关法和其他有关法律的规定，制定本办法。\n第二条 在中华人民共和国境内设立保税区，必须经国务院批准。\n第三条 保税区是海关监管的特定区域。海关依照本办法对进出保税区的货物、运输工具、个人携带物品实施监管。\n保税区与中华人民共和国境内的其他地区(以下简称非保税区)之间，应当设置符合海关监管要求的隔离设施。\n第四条 保税区内仅设置保税区行政管理机构和企业。除安全保卫人员外，其他人员不得在保税区内居住。\n第五条 在保税区内设立的企业(以下简称区内企业)，应当向海关办理注册手续。\n区内企业应当依照国家有关法律、行政法规的规定设置账簿、编制报表，凭合法、有效凭证记账并进行核算，记录有关进出保税区货物和物品的库存、转让、转移、销售、加工、使用和损耗等情况。\n第六条 保税区实行海关稽查制度。\n区内企业应当与海关实行电子计算机联网，进行电子数据交换。\n第七条 海关对进出保税区的货物、物品、运输工具、人员及区内有关场所，有权依照海关法的规定进行检查、查验。\n第八条 国家禁止进出口的货物、物品，不得进出保税区。","level":1},{"name":"第二章 对保税区与境外之间进出货物的监管","text":"第九条 海关对保税区与境外之间进出的货物，实施简便、有效的监管。\n第十条 保税区与境外之间进出的货物，由货物的收货人、发货人或其代理人向海关备案。\n第十一条 对保税区与境外之间进出的货物，除实行出口被动配额管理的外，不实行进出口配额、许可证管理。\n第十二条 从境外进入保税区的货物，其进口关税和进口环节税收，除法律、行政法规另有规定外，按照下列规定办理：\n(一)区内生产性的基础设施建设项目所需的机器、设备和其他基建物资，予以免税；\n(二)区内企业自用的生产、管理设备和自用合理数量的办公用品及其所需的维修零配件，生产用燃料，建设生产厂房、仓储设施所需的物资、设备，予以免税；\n(三)保税区行政管理机构自用合理数量的管理设备和办公用品及其所需的维修零配件，予以免税；\n(四)区内企业为加工出口产品所需的原材料、零部件、元器件、包装物件，予以保税。\n前款第(一)项至第(四)项规定范围以外的货物或者物品从境外进入保税区，应当依法纳税。\n转口货物和在保税区内储存的货物按照保税货物管理。","level":1},{"name":"第三章 对保税区与非保税区之间进出货物的监管","text":"第十三条 从保税区进入非保税区的货物，按照进口货物办理手续；从非保税区进入保税区的货物，按照出口货物办理手续，出口退税按照国家有关规定办理。\n海关对保税区与非保税区之间进出的货物，按照国家有关进出口管理的规定实施监管。\n第十四条 从非保税区进入保税区供区内使用的机器、设备、基建物资和物品，使用单位应当向海关提供上述货物或者物品的清单，经海关查验后放行。\n前款货物或者物品，已经缴纳进口关税和进口环节税收的，已纳税款不予退还。\n第十五条 保税区的货物需从非保税区口岸进出口或者保税区内的货物运往另一保税区的，应当事先向海关提出书面申请，经海关批准后，按照海关转关运输及有关规定办理。","level":1},{"name":"第四章 对保税区内货物的监管","text":"第十六条 保税区内的货物可以在区内企业之间转让、转移；双方当事人应当就转让、转移事项向海关备案。\n第十七条 保税区内的转口货物可以在区内仓库或者区内其他场所进行分级、挑选、刷贴标志、改换包装形式等简单加工。\n第十八条 区内企业在保税区内举办境外商品和非保税区商品的展示活动，展示的商品应当接受海关监管。","level":1},{"name":"第五章 对保税区加工贸易货物的管理","text":"第十九条 区内加工企业应当向海关办理所需料、件进出保税区备案手续。\n第二十条 区内加工企业生产属于被动配额管理的出口产品，应当事先经国务院有关主管部门批准。\n第二十一条 区内加工企业加工的制成品及其在加工过程中产生的边角余料运往境外时，应当按照国家有关规定向海关办理手续；除法律、行政法规另有规定外，免征出口关税。\n区内加工企业将区内加工的制成品、副次品或者在加工过程中产生的边角余料运往非保税区时，应当按照国家有关规定向海关办理进口报关手续，并依法纳税。\n第二十二条 区内加工企业全部用境外运入料、件加工的制成品销往非保税区时，海关按照进口制成品征税。\n用含有境外运入料、件加工的制成品销往非保税区时，海关对其制成品按照所含境外运入料、件征税；对所含境外运入料、件的品名、数量、价值申报不实的，海关按照进口制成品征税。\n第二十三条 区内加工企业委托非保税区企业或者接受非保税区企业委托进行加工业务，应当事先经海关批准，并符合下列条件：\n(一)在区内拥有生产场所，并已经正式开展加工业务；\n(二)委托非保税区企业的加工业务，主要工序应当在区内进行；\n(三)委托非保税区企业加工业务的期限为6个月；有特殊情况需要延长期限的，应当向海关申请展期，展期期限为6个月。在非保税区加工完毕的产品应当运回保税区；需要从非保税区直接出口的，应当向海关办理核销手续；\n(四)接受非保税区企业委托加工的，由区内加工企业向海关办理委托加工料、件的备案手续，委托加工的料、件及产品应当与区内企业的料、件及产品分别建立账册并分别使用。加工完毕的产品应当运回非保税区企业，并由区内加工企业向海关销案。\n第二十四条 海关对区内加工企业进料加工、来料加工业务，不实行加工贸易银行保证金台账制度。\n委托非保税区企业进行加工业务的，由非保税区企业向当地海关办理合同登记备案手续，并实行加工贸易银行保证金台账制度。","level":1},{"name":"第六章 对进出保税区运输工具和个人携带物品的监管","text":"第二十五条 运输工具和人员进出保税区，应当经由海关指定的专用通道，并接受海关检查。\n第二十六条 进出保税区的运输工具的负责人，应当持保税区主管机关批准的证件连同运输工具的名称、数量、牌照号码及驾驶员姓名等清单，向海关办理登记备案手续。\n第二十七条 未经海关批准，从保税区到非保税区的运输工具和人员不得运输、携带保税区内的免税货物、物品，保税货物，以及用保税料、件生产的产品。","level":1},{"name":"第七章 附则","text":"第二十八条 违反本办法规定的，由海关依照《中华人民共和国海关法》及《中华人民共和国海关行政处罚实施条例》的规定处理；情节严重的，海关可以取消区内企业在海关的注册资格。\n第二十九条 本办法规定的有关备案的具体办法，由海关总署制定。\n第三十条 本办法自发布之日起施行。《中华人民共和国海关对进出上海外高桥保税区货物、运输工具和个人携带物品的管理办法》同时废止。","level":1}]},{"id":"n0344","sections":[{"name":"","text":"通用航空飞行管制条例\n(2003年1月10日中华人民共和国国务院、中华人民共和国中央军事委员会令第371号公布 自2003年5月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了促进通用航空事业的发展，规范通用航空飞行活动，保证飞行安全，根据《中华人民共和国民用航空法》和《中华人民共和国飞行基本规则》，制定本条例。\n第二条 在中华人民共和国境内从事通用航空飞行活动，必须遵守本条例。\n在中华人民共和国境内从事升放无人驾驶自由气球和系留气球活动，适用本条例的有关规定。\n第三条 本条例所称通用航空，是指除军事、警务、海关缉私飞行和公共航空运输飞行以外的航空活动，包括从事工业、农业、林业、渔业、矿业、建筑业的作业飞行和医疗卫生、抢险救灾、气象探测、海洋监测、科学实验、遥感测绘、教育训练、文化体育、旅游观光等方面的飞行活动。\n第四条 从事通用航空飞行活动的单位、个人，必须按照《中华人民共和国民用航空法》的规定取得从事通用航空活动的资格，并遵守国家有关法律、行政法规的规定。\n第五条 飞行管制部门按照职责分工，负责对通用航空飞行活动实施管理，提供空中交通管制服务。相关飞行保障单位应当积极协调配合，做好有关服务保障工作，为通用航空飞行活动创造便利条件。","level":1},{"name":"第二章 飞行空域的划设与使用","text":"第六条 从事通用航空飞行活动的单位、个人使用机场飞行空域、航路、航线，应当按照国家有关规定向飞行管制部门提出申请，经批准后方可实施。\n第七条 从事通用航空飞行活动的单位、个人，根据飞行活动要求，需要划设临时飞行空域的，应当向有关飞行管制部门提出划设临时飞行空域的申请。\n划设临时飞行空域的申请应当包括下列内容：\n(一)临时飞行空域的水平范围、高度；\n(二)飞入和飞出临时飞行空域的方法；\n(三)使用临时飞行空域的时间；\n(四)飞行活动性质；\n(五)其他有关事项。\n第八条 划设临时飞行空域，按照下列规定的权限批准：\n(一)在机场区域内划设的，由负责该机场飞行管制的部门批准；\n(二)超出机场区域在飞行管制分区内划设的，由负责该分区飞行管制的部门批准；\n(三)超出飞行管制分区在飞行管制区内划设的，由负责该管制区飞行管制的部门批准；\n(四)在飞行管制区间划设的，由中国人民解放军空军批准。\n批准划设临时飞行空域的部门应当将划设的临时飞行空域报上一级飞行管制部门备案，并通报有关单位。\n第九条 划设临时飞行空域的申请，应当在拟使用临时飞行空域7个工作日前向有关飞行管制部门提出；负责批准该临时飞行空域的飞行管制部门应当在拟使用临时飞行空域3个工作日前作出批准或者不予批准的决定，并通知申请人。\n第十条 临时飞行空域的使用期限应当根据通用航空飞行的性质和需要确定，通常不得超过12个月。\n因飞行任务的要求，需要延长临时飞行空域使用期限的，应当报经批准该临时飞行空域的飞行管制部门同意。\n通用航空飞行任务完成后，从事通用航空飞行活动的单位、个人应当及时报告有关飞行管制部门，其申请划设的临时飞行空域即行撤销。\n第十一条 已划设的临时飞行空域，从事通用航空飞行活动的其他单位、个人因飞行需要，经批准划设该临时飞行空域的飞行管制部门同意，也可以使用。","level":1},{"name":"第三章 飞行活动的管理","text":"第十二条 从事通用航空飞行活动的单位、个人实施飞行前，应当向当地飞行管制部门提出飞行计划申请，按照批准权限，经批准后方可实施。\n第十三条 飞行计划申请应当包括下列内容：\n(一)飞行单位；\n(二)飞行任务性质；\n(三)机长(飞行员)姓名、代号(呼号)和空勤组人数；\n(四)航空器型别和架数；\n(五)通信联络方法和二次雷达应答机代码；\n(六)起飞、降落机场和备降场；\n(七)预计飞行开始、结束时间；\n(八)飞行气象条件；\n(九)航线、飞行高度和飞行范围；\n(十)其他特殊保障需求。\n第十四条 从事通用航空飞行活动的单位、个人有下列情形之一的，必须在提出飞行计划申请时，提交有效的任务批准文件：\n(一)飞出或者飞入我国领空的(公务飞行除外)；\n(二)进入空中禁区或者国(边)界线至我方一侧10公里之间地带上空飞行的；\n(三)在我国境内进行航空物探或者航空摄影活动的；\n(四)超出领海(海岸)线飞行的；\n(五)外国航空器或者外国人使用我国航空器在我国境内进行通用航空飞行活动的。\n第十五条 使用机场飞行空域、航路、航线进行通用航空飞行活动，其飞行计划申请由当地飞行管制部门批准或者由当地飞行管制部门报经上级飞行管制部门批准。\n使用临时飞行空域、临时航线进行通用航空飞行活动，其飞行计划申请按照下列规定的权限批准：\n(一)在机场区域内的，由负责该机场飞行管制的部门批准；\n(二)超出机场区域在飞行管制分区内的，由负责该分区飞行管制的部门批准；\n(三)超出飞行管制分区在飞行管制区内的，由负责该区域飞行管制的部门批准；\n(四)超出飞行管制区的，由中国人民解放军空军批准。\n第十六条 飞行计划申请应当在拟飞行前1天15时前提出；飞行管制部门应当在拟飞行前1天21时前作出批准或者不予批准的决定，并通知申请人。\n执行紧急救护、抢险救灾、人工影响天气或者其他紧急任务的，可以提出临时飞行计划申请。临时飞行计划申请最迟应当在拟飞行1小时前提出；飞行管制部门应当在拟起飞时刻15分钟前作出批准或者不予批准的决定，并通知申请人。\n第十七条 在划设的临时飞行空域内实施通用航空飞行活动的，可以在申请划设临时飞行空域时一并提出15天以内的短期飞行计划申请，不再逐日申请；但是每日飞行开始前和结束后，应当及时报告飞行管制部门。\n第十八条 使用临时航线转场飞行的，其飞行计划申请应当在拟飞行2天前向当地飞行管制部门提出；飞行管制部门应当在拟飞行前1天18时前作出批准或者不予批准的决定，并通知申请人，同时按照规定通报有关单位。\n第十九条 飞行管制部门对违反飞行管制规定的航空器，可以根据情况责令改正或者停止其飞行。","level":1},{"name":"第四章 飞行保障","text":"第二十条 通信、导航、雷达、气象、航行情报和其他飞行保障部门应当认真履行职责，密切协同，统筹兼顾，合理安排，提高飞行空域和时间的利用率，保障通用航空飞行顺利实施。\n第二十一条 通信、导航、雷达、气象、航行情报和其他飞行保障部门对于紧急救护、抢险救灾、人工影响天气等突发性任务的飞行，应当优先安排。\n第二十二条 从事通用航空飞行活动的单位、个人组织各类飞行活动，应当制定安全保障措施，严格按照批准的飞行计划组织实施，并按照要求报告飞行动态。\n第二十三条 从事通用航空飞行活动的单位、个人，应当与有关飞行管制部门建立可靠的通信联络。\n在划设的临时飞行空域内从事通用航空飞行活动时，应当保持空地联络畅通。\n第二十四条 在临时飞行空域内进行通用航空飞行活动，通常由从事通用航空飞行活动的单位、个人负责组织实施，并对其安全负责。\n第二十五条 飞行管制部门应当按照职责分工或者协议，为通用航空飞行活动提供空中交通管制服务。\n第二十六条 从事通用航空飞行活动需要使用军用机场的，应当将使用军用机场的申请和飞行计划申请一并向有关部队司令机关提出，由有关部队司令机关作出批准或者不予批准的决定，并通知申请人。\n第二十七条 从事通用航空飞行活动的航空器转场飞行，需要使用军用或者民用机场的，由该机场管理机构按照规定或者协议提供保障；使用军民合用机场的，由从事通用航空飞行活动的单位、个人与机场有关部门协商确定保障事宜。\n第二十八条 在临时机场或者起降点飞行的组织指挥，通常由从事通用航空飞行活动的单位、个人负责。\n第二十九条 从事通用航空飞行活动的民用航空器能否起飞、着陆和飞行，由机长(飞行员)根据适航标准和气象条件等最终确定，并对此决定负责。\n第三十条 通用航空飞行保障收费标准，按照国家有关国内机场收费标准执行。","level":1},{"name":"第五章 升放和系留气球的规定","text":"第三十一条 升放无人驾驶自由气球或者系留气球，不得影响飞行安全。\n本条例所称无人驾驶自由气球，是指无动力驱动、无人操纵、轻于空气、总质量大于4千克自由飘移的充气物体。\n本条例所称系留气球，是指系留于地面物体上、直径大于1.8米或者体积容量大于3.2立方米、轻于空气的充气物体。\n第三十二条 无人驾驶自由气球和系留气球的分类、识别标志和升放条件等，应当符合国家有关规定。\n第三十三条 进行升放无人驾驶自由气球或者系留气球活动，必须经设区的市级以上气象主管机构会同有关部门批准。具体办法由国务院气象主管机构制定。\n第三十四条 升放无人驾驶自由气球，应当在拟升放2天前持本条例第三十三条规定的批准文件向当地飞行管制部门提出升放申请；飞行管制部门应当在拟升放1天前作出批准或者不予批准的决定，并通知申请人。\n第三十五条 升放无人驾驶自由气球的申请，通常应当包括下列内容：\n(一)升放的单位、个人和联系方法；\n(二)气球的类型、数量、用途和识别标志；\n(三)升放地点和计划回收区；\n(四)预计升放和回收(结束)的时间；\n(五)预计飘移方向、上升的速度和最大高度。\n第三十六条 升放无人驾驶自由气球，应当按照批准的申请升放，并及时向有关飞行管制部门报告升放动态；取消升放时，应当及时报告有关飞行管制部门。\n第三十七条 升放系留气球，应当确保系留牢固，不得擅自释放。\n系留气球升放的高度不得高于地面150米，但是低于距其水平距离50米范围内建筑物顶部的除外。\n系留气球升放的高度超过地面50米的，必须加装快速放气装置，并设置识别标志。\n第三十八条 升放的无人驾驶自由气球或者系留气球中发生下列可能危及飞行安全的情况时，升放单位、个人应当及时报告有关飞行管制部门和当地气象主管机构：\n(一)无人驾驶自由气球非正常运行的；\n(二)系留气球意外脱离系留的；\n(三)其他可能影响飞行安全的异常情况。\n加装快速放气装置的系留气球意外脱离系留时，升放系留气球的单位、个人应当在保证地面人员、财产安全的条件下，快速启动放气装置。\n第三十九条 禁止在依法划设的机场范围内和机场净空保护区域内升放无人驾驶自由气球或者系留气球，但是国家另有规定的除外。","level":1},{"name":"第六章 法律责任","text":"第四十条 违反本条例规定，《中华人民共和国民用航空法》、《中华人民共和国飞行基本规则》及有关行政法规对其处罚有规定的，从其规定；没有规定的，适用本章规定。\n第四十一条 从事通用航空飞行活动的单位、个人违反本条例规定，有下列情形之一的，由有关部门按照职责分工责令改正，给予警告；情节严重的，处2万元以上10万元以下罚款，并可给予责令停飞1个月至3个月、暂扣直至吊销经营许可证、飞行执照的处罚；造成重大事故或者严重后果的，依照刑法关于重大飞行事故罪或者其他罪的规定，依法追究刑事责任：\n(一)未经批准擅自飞行的；\n(二)未按批准的飞行计划飞行的；\n(三)不及时报告或者漏报飞行动态的；\n(四)未经批准飞入空中限制区、空中危险区的。\n第四十二条 违反本条例规定，未经批准飞入空中禁区的，由有关部门按照国家有关规定处置。\n第四十三条 违反本条例规定，升放无人驾驶自由气球或者系留气球，有下列情形之一的，由气象主管机构或者有关部门按照职责分工责令改正，给予警告；情节严重的，处1万元以上5万元以下罚款；造成重大事故或者严重后果的，依照刑法关于重大责任事故罪或者其他罪的规定，依法追究刑事责任：\n(一)未经批准擅自升放的；\n(二)未按照批准的申请升放的；\n(三)未按照规定设置识别标志的；\n(四)未及时报告升放动态或者系留气球意外脱离时未按照规定及时报告的；\n(五)在规定的禁止区域内升放的。\n第四十四条 按照本条例实施的罚款，应当全额上缴财政。","level":1},{"name":"第七章 附则","text":"第四十五条 本条例自2003年5月1日起施行。","level":1}]},{"id":"n0345","sections":[{"name":"","text":"工商行政管理所条例\n(1991年4月1日国务院批准 1991年4月22日国家工商行政管理局令第6号发布 自发布之日起施行)\n第一条 为了加强工商行政管理所(以下简称工商所)的组织建设，使工商所工作规范化、制度化，更好地发挥工商行政管理的职能作用，制定本条例。\n第二条 工商所是区、县(含县级市，下同)工商行政管理局(以下简称区、县工商局)的派出机构。工商所的人员编制、经费开支、干部管理和业务工作等由区、县工商局直接领导和管理。\n第三条 工商所的基本任务是：依据法律、法规的规定，对辖区内的企业、个体工商户和市场经济活动进行监督管理，保护合法经营，取缔非法经营，维护正常的经济秩序。\n第四条 工商所按经济区域设立。\n工商所的设立，由区、县工商局根据辖区大小、经济发展情况和管理任务需要，提出具体方案，报区、县人民政府批准。\n第五条 工商所设所长一人；任务较多的，设副所长一至二人；工作人员若干人。\n工商所实行所长负责制。\n第六条 工商所的职责包括：\n(一)办理辖区内由区、县工商局登记管理的企业的登记初审和年检、换照的审查手续，并对区、县工商局核准登记的企业进行监督管理；\n(二)管理辖区内的集贸市场，监督集市贸易经济活动；\n(三)监督检查辖区内经济合同的订立及履行，调解经济合同纠纷；\n(四)受理、初审、呈报辖区内个体工商户的开业、变更、歇业的申请事项，对个体工商户的生产经营活动进行监督管理；\n(五)指导辖区内企业事业单位、个体工商户正确申请商标注册，并对其使用商标进行监督管理；\n(六)对辖区内设置、张贴的广告进行监督管理；\n(七)按规定收取、上缴各项工商收费及罚没款物；\n(八)宣传工商行政管理法律、法规和有关政策；\n(九)法律、法规规定的其他工商行政管理职责。\n第七条 工商所的具体工作范围，由区、县工商局依照工商行政管理的有关法律、法规和规章的规定，根据辖区内管理工作的实际需要，在前条所列职责范围内予以确定，并报上一级工商行政管理机关备案。\n第八条 工商所的具体行政行为是区、县工商局的具体行政行为，但有下列情况之一的，工商所可以以自己的名义作出具体行政行为：\n(一)对个体工商户违法行为的处罚；\n(二)对集市贸易中违法行为的处罚；\n(三)法律、法规和规章规定工商所以自己的名义作出的其他具体行政行为。\n前款第(一)、(二)项处罚不包括吊销营业执照。\n第九条 工商所应当建立健全监督管理和行政执法的工作程序，公开办事制度和办事结果，接受群众监督，做到公正严明，管理有章，处罚有据，廉洁奉公。\n第十条 工商所应当建立健全岗位责任制，对工作人员的德、能、勤、绩进行定期考核，并将考核情况作为任职、奖励、晋升的主要依据。\n第十一条 工商所应当建立健全财务管理和监督制度，配备专职财务人员。各项工商收费和罚没物资、现金、票证，应当分别登记造册，按规定处理。\n工商所的费用开支，按有关财务规定执行。\n第十二条 工商所应当建立健全内勤工作制度。各类文件和资料应当及时登记归档；认真处理来信来访；严格执行用印制度。\n第十三条 工商所工作人员必须清正廉洁，秉公执法，不得以权谋私，索贿受贿。\n第十四条 工商所工作人员必须严格遵守国家及有关部门制定的政府机关工作人员的各项纪律、守则，积极工作，忠于职守。\n第十五条 工商所工作人员执行公务时必须按规定着装，仪表庄重，待人礼貌。\n第十六条 工商所工作人员在工作中取得突出成绩的，工商所可提请区、县工商局给予奖励。对违纪违法的，由区、县工商局依照国家有关规定给予处分；情节严重，构成犯罪的，由司法机关依法追究刑事责任。\n第十七条 工商行政管理系统的其他专业所、队、站参照本条例规定执行。\n第十八条 本条例由国家工商行政管理局负责解释。\n第十九条 本条例自发布之日起施行。","level":0}]},{"id":"n0346","sections":[{"name":"","text":"进口影片管理办法\n(1981年10月13日国务院批准 文化部、海关总署发布)\n第一条 为了加强对进口影片的管理，根据一九八○年四月十四日中共中央、国务院、中央军委《关于制止滥放内部参考影片的通知》精神，特制订本办法。\n第二条 凡属从外国及港澳地区进口发行影片或试映拷贝(包括35毫米、16毫米、超8毫米、影片录相带和影片视盘等，以下统称影片)的业务，统一由中国电影发行放映公司(以下简称中影公司)经营管理。\n影片进口时，由海关凭中影公司填报的进口货物报关单核查放行。属于在全国发行的商业性影片，应在进口时办理纳税手续；属于非商业性影片，应予免税；属于非商业性影片，进口后经过批准在全国发行的，由中影公司按章向北京海关办理补税手续。\n第三条 中国电影资料馆进口的资料影片(包括中国电影资料馆与外国电影资料馆互相选购、交换、赠送或通过其他途径购作资料的影片)，属于非商业性影片，海关凭该馆填报的进口货物报关单核查免税放行。\n进口的资料影片，如经批准，需向全国发行的，由中影公司按章向北京海关办理补税手续。\n第四条 科学技术、工业、农业、教育、卫生、新闻、外贸、外事等单位，因业务需要进口的专业性纪录、科教影片，属于国务院系统的单位进口的，由国务院各部委(总局)审批；属于地方单位进口的，由省、自治区、直辖市人民政府审批。\n影片进口时，海关凭有关部委(总局)或省、自治区、直辖市人民政府的批准文件和申请单位填报的进口货物报关单一式三份核查免税放行，并将盖有海关印章的报关单一份转送文化部电影事业管理局备案。\n第五条 外国、港澳地区及台湾省的团体或个人运进给机关、团体、学校等单位的故事片，凡属国务院系统的单位接受的，须经文化部电影事业管理局审批；属地方单位接受的，须经省、自治区、直辖市文化局(电影局)审批，并抄送文化部电影事业管理局备案。\n影片进口时，海关凭接受单位填报的进口货物报关单和批准文件核查免税放行。\n接受单位应当将接收的影片交中国电影资料馆统一保管。如因业务上特殊需要，接受单位可以凭上级主管部门的批准文件向该馆提取，供有关人员参考借鉴，但不准外借，不准招待映出，不准拿到社会上公开放映。借鉴后仍送回中国电影资料馆保管。\n进口的故事影片，如经批准在全国发行的，应由中影公司向海关办理补税手续。\n第六条 对外国人和华侨、港澳及台湾省同胞等邮寄或者入境随身携带属于赠给我国个人作为业务参考的科教影片，海关应准许进口，并凭接受影片的个人填报的进口货物报关单及其所在单位的证明信件核查免税放行。属于赠给我国个人的故事影片，一般地不准进口，海关予以退运。如遇特殊情况，由文化部和海关总署研究处理。\n对外国驻华使(领)馆人员、外国工商企业派来我国的常驻人员(包括外国常驻记者)和应聘来华工作的外国专家(包括文教、经济、科技专家)携带(或者从国外邮寄给他们)的影片，按海关现行有关规定办理。影片进口后应由有关部门严格控制，只限他们在内部放映；我方单位或个人不许借映。\n第七条 除香港长城、凤凰、新联三公司回内地拍片，由国务院港澳办公室同有关地区和有关单位直接联系外，凡属中外或我与港澳地区及台湾省的合作制片业务，统由中国电影合作制片公司管理。合拍影片的进口，由中国电影合作制片公司向海关办理进口报关手续；其中批准在全国发行的，则由中影公司按章向北京海关办理补税手续。\n第八条 对违反规定进口的或走私进口的影片，海关按有关规定处理；对没收的影片，凡有保留参考价值的可转送文化部电影事业管理局交中国电影资料馆保存。\n第九条 本办法自发布之日起施行。","level":0}]},{"id":"n0347","sections":[{"name":"","text":"中华人民共和国对外合作\n开采海洋石油资源条例\n(1982年1月30日国务院发布 根据2001年9月23日《国务院关于修改〈中华人民共和国对外合作开采海洋石油资源条例〉的决定》第一次修订 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第二次修订 根据2011年9月30日《国务院关于修改〈中华人民共和国对外合作开采海洋石油资源条例〉的决定》第三次修订 根据2013年7月18日《国务院关于废止和修改部分行政法规的决定》第四次修订)","level":0},{"name":"第一章 总则","text":"第一条 为促进国民经济的发展，扩大国际经济技术合作，在维护国家主权和经济利益的前提下允许外国企业参与合作开采中华人民共和国海洋石油资源，特制定本条例。\n第二条 中华人民共和国的内海、领海、大陆架以及其他属于中华人民共和国海洋资源管辖海域的石油资源，都属于中华人民共和国国家所有。\n在前款海域内，为开采石油而设置的建筑物、构筑物、作业船舶，以及相应的陆岸油(气)集输终端和基地，都受中华人民共和国管辖。\n第三条 中国政府依法保护参与合作开采海洋石油资源的外国企业的投资、应得利润和其他合法权益，依法保护外国企业的合作开采活动。\n在本条例范围内，合作开采海洋石油资源的一切活动，都应当遵守中华人民共和国的法律、法令和国家的有关规定；参与实施石油作业的企业和个人，都应当受中国法律的约束，接受中国政府有关主管部门的检查、监督。\n第四条 国家对参加合作开采海洋石油资源的外国企业的投资和收益不实行征收。在特殊情况下，根据社会公共利益的需要，可以对外国企业在合作开采中应得石油的一部分或者全部，依照法律程序实行征收，并给予相应的补偿。\n第五条 国务院指定的部门依据国家确定的合作海区、面积，决定合作方式，划分合作区块；依据国家规定制定同外国企业合作开采海洋石油资源的规划；制定对外合作开采海洋石油资源的业务政策和审批海上油(气)田的总体开发方案。\n第六条 中华人民共和国对外合作开采海洋石油资源的业务，由中国海洋石油总公司全面负责。\n中国海洋石油总公司是具有法人资格的国家公司，享有在对外合作海区内进行石油勘探、开发、生产和销售的专营权。\n中国海洋石油总公司根据工作需要，可以设立地区公司、专业公司、驻外代表机构，执行总公司交付的任务。\n第七条 中国海洋石油总公司就对外合作开采石油的海区、面积、区块，通过组织招标，确定合作开采海洋石油资源的外国企业，签订合作开采石油合同或者其他合作合同，并向中华人民共和国商务部报送合同有关情况。","level":1},{"name":"第二章 石油合同各方的权利和义务","text":"第八条 中国海洋石油总公司通过订立石油合同同外国企业合作开采海洋石油资源，除法律、行政法规另有规定或者石油合同另有约定外，应当由石油合同中的外国企业一方(以下称外国合同者)投资进行勘探，负责勘探作业，并承担全部勘探风险；发现商业性油(气)田后，由外国合同者同中国海洋石油总公司双方投资合作开发，外国合同者并应负责开发作业和生产作业，直至中国海洋石油总公司按照石油合同规定在条件具备的情况下接替生产作业。外国合同者可以按照石油合同规定，从生产的石油中回收其投资和费用，并取得报酬。\n第九条 外国合同者可以将其应得的石油和购买的石油运往国外，也可以依法将其回收的投资、利润和其他正当收益汇往国外。\n第十条 参与合作开采海洋石油资源的中国企业、外国企业，都应当依法纳税。\n第十一条 为执行石油合同所进口的设备和材料，按照国家规定给予减税、免税，或者给予税收方面的其他优惠。\n第十二条 外国合同者开立外汇账户和办理其他外汇事宜，应当遵守《中华人民共和国外汇管理条例》和国家有关外汇管理的其他规定。\n第十三条 石油合同可以约定石油作业所需的人员，作业者可以优先录用中国公民。\n第十四条 外国合同者在执行石油合同从事开发、生产作业过程中，必须及时地、准确地向中国海洋石油总公司报告石油作业情况；完整地、准确地取得各项石油作业的数据、记录、样品、凭证和其他原始资料，并定期向中国海洋石油总公司提交必要的资料和样品以及技术、经济、财会、行政方面的各种报告。\n第十五条 外国合同者为执行石油合同从事开发、生产作业，应当在中华人民共和国境内设立分支机构或者代表机构，并依法履行登记手续。\n前款机构的住所地应当同中国海洋石油总公司共同商量确定。\n第十六条 本条例第三条、第九条、第十条、第十一条、第十五条的规定，对向石油作业提供服务的外国承包者，类推适用。","level":1},{"name":"第三章 石油作业","text":"第十七条 作业者必须根据本条例和国家有关开采石油资源的规定，参照国际惯例，制定油(气)田总体开发方案和实施生产作业，以达到尽可能高的石油采收率。\n第十八条 外国合同者为执行石油合同从事开发、生产作业，应当使用中华人民共和国境内现有的基地；如需设立新基地，必须位于中华人民共和国境内。\n前款新基地的具体地点，以及在特殊情况下需要采取的其他措施，都必须经中国海洋石油总公司书面同意。\n第十九条 中国海洋石油总公司有权派人参加外国作业者为执行石油合同而进行的总体设计和工程设计。\n第二十条 外国合同者为执行石油合同，除租用第三方的设备外，按计划和预算所购置和建造的全部资产，当外国合同者的投资按照规定得到补偿后，其所有权属于中国海洋石油总公司，在合同期内，外国合同者仍然可以依据合同的规定使用这些资产。\n第二十一条 为执行石油合同所取得的各项石油作业的数据、记录、样品、凭证和其他原始资料，其所有权属于中国海洋石油总公司。\n前款数据、记录、样品、凭证和其他原始资料的使用和转让、赠与、交换、出售、公开发表以及运出、传送出中华人民共和国，都必须按照国家有关规定执行。\n第二十二条 作业者和承包者在实施石油作业中，应当遵守中华人民共和国有关环境保护和安全方面的法律规定，并参照国际惯例进行作业，保护渔业资源和其他自然资源，防止对大气、海洋、河流、湖泊和陆地等环境的污染和损害。\n第二十三条 石油合同区产出的石油，应当在中华人民共和国登陆，也可以在海上油(气)外输计量点运出。如需在中华人民共和国以外的地点登陆，必须经国务院指定的部门批准。","level":1},{"name":"第四章 附则","text":"第二十四条 在合作开采海洋石油资源活动中，外国企业和中国企业间发生的争执，应当通过友好协商解决。通过协商不能解决的，由中华人民共和国仲裁机构进行调解、仲裁，也可以由合同双方协议在其他仲裁机构仲裁。\n第二十五条 作业者、承包者违反本条例规定实施石油作业的，由国务院指定的部门依据职权责令限期改正，给予警告；在限期内不改正的，可以责令其停止实施石油作业。由此造成的一切经济损失，由责任方承担。\n第二十六条 本条例所用的术语，其定义如下：\n(一)“石油”是指蕴藏在地下的、正在采出的和已经采出的原油和天然气。\n(二)“开采”是泛指石油的勘探、开发、生产和销售及其有关的活动。\n(三)“石油合同”是指中国海洋石油总公司同外国企业为合作开采中华人民共和国海洋石油资源，依法订立的包括石油勘探、开发和生产的合同。\n(四)“合同区”是指在石油合同中为合作开采石油资源以地理坐标圈定的海域面积。\n(五)“石油作业”是指为执行石油合同而进行的勘探、开发和生产作业及其有关的活动。\n(六)“勘探作业”是指用地质、地球物理、地球化学和包括钻勘探井等各种方法寻找储藏石油的圈闭所做的全部工作，以及在已发现石油的圈闭上为确定它有无商业价值所做的钻评价井、可行性研究和编制油(气)田的总体开发方案等全部工作。\n(七)“开发作业”是指从国务院指定的部门批准油(气)田的总体开发方案之日起，为实现石油生产所进行的设计、建造、安装、钻井工程等及其相应的研究工作，并包括商业性生产开始之前的生产活动。\n(八)“生产作业”是指一个油(气)田从开始商业性生产之日起，为生产石油所进行的全部作业以及与其有关的活动，诸如采出、注入、增产、处理、贮运和提取等作业。\n(九)“外国合同者”是指同中国海洋石油总公司签订石油合同的外国企业。外国企业可以是公司，也可以是公司集团。\n(十)“作业者”是指按照石油合同的规定负责实施作业的实体。\n(十一)“承包者”是指向作业者提供服务的实体。\n第二十七条 本条例自公布之日起施行。","level":1}]},{"id":"n0348","sections":[{"name":"","text":"特种设备安全监察条例\n(2003年3月11日中华人民共和国国务院令第373号公布 根据2009年1月24日《国务院关于修改〈特种设备安全监察条例〉的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强特种设备的安全监察，防止和减少事故，保障人民群众生命和财产安全，促进经济发展，制定本条例。\n第二条 本条例所称特种设备是指涉及生命安全、危险性较大的锅炉、压力容器(含气瓶，下同)、压力管道、电梯、起重机械、客运索道、大型游乐设施和场(厂)内专用机动车辆。\n前款特种设备的目录由国务院负责特种设备安全监督管理的部门(以下简称国务院特种设备安全监督管理部门)制订，报国务院批准后执行。\n第三条 特种设备的生产(含设计、制造、安装、改造、维修，下同)、使用、检验检测及其监督检查，应当遵守本条例，但本条例另有规定的除外。\n军事装备、核设施、航空航天器、铁路机车、海上设施和船舶以及矿山井下使用的特种设备、民用机场专用设备的安全监察不适用本条例。\n房屋建筑工地和市政工程工地用起重机械、场(厂)内专用机动车辆的安装、使用的监督管理，由建设行政主管部门依照有关法律、法规的规定执行。\n第四条 国务院特种设备安全监督管理部门负责全国特种设备的安全监察工作，县以上地方负责特种设备安全监督管理的部门对本行政区域内特种设备实施安全监察(以下统称特种设备安全监督管理部门)。\n第五条 特种设备生产、使用单位应当建立健全特种设备安全、节能管理制度和岗位安全、节能责任制度。\n特种设备生产、使用单位的主要负责人应当对本单位特种设备的安全和节能全面负责。\n特种设备生产、使用单位和特种设备检验检测机构，应当接受特种设备安全监督管理部门依法进行的特种设备安全监察。\n第六条 特种设备检验检测机构，应当依照本条例规定，进行检验检测工作，对其检验检测结果、鉴定结论承担法律责任。\n第七条 县级以上地方人民政府应当督促、支持特种设备安全监督管理部门依法履行安全监察职责，对特种设备安全监察中存在的重大问题及时予以协调、解决。\n第八条 国家鼓励推行科学的管理方法，采用先进技术，提高特种设备安全性能和管理水平，增强特种设备生产、使用单位防范事故的能力，对取得显著成绩的单位和个人，给予奖励。\n国家鼓励特种设备节能技术的研究、开发、示范和推广，促进特种设备节能技术创新和应用。\n特种设备生产、使用单位和特种设备检验检测机构，应当保证必要的安全和节能投入。\n国家鼓励实行特种设备责任保险制度，提高事故赔付能力。\n第九条 任何单位和个人对违反本条例规定的行为，有权向特种设备安全监督管理部门和行政监察等有关部门举报。\n特种设备安全监督管理部门应当建立特种设备安全监察举报制度，公布举报电话、信箱或者电子邮件地址，受理对特种设备生产、使用和检验检测违法行为的举报，并及时予以处理。\n特种设备安全监督管理部门和行政监察等有关部门应当为举报人保密，并按照国家有关规定给予奖励。","level":1},{"name":"第二章 特种设备的生产","text":"第十条 特种设备生产单位，应当依照本条例规定以及国务院特种设备安全监督管理部门制订并公布的安全技术规范(以下简称安全技术规范)的要求，进行生产活动。\n特种设备生产单位对其生产的特种设备的安全性能和能效指标负责，不得生产不符合安全性能要求和能效指标的特种设备，不得生产国家产业政策明令淘汰的特种设备。\n第十一条 压力容器的设计单位应当经国务院特种设备安全监督管理部门许可，方可从事压力容器的设计活动。\n压力容器的设计单位应当具备下列条件：\n(一)有与压力容器设计相适应的设计人员、设计审核人员；\n(二)有与压力容器设计相适应的场所和设备；\n(三)有与压力容器设计相适应的健全的管理制度和责任制度。\n第十二条 锅炉、压力容器中的气瓶(以下简称气瓶)、氧舱和客运索道、大型游乐设施以及高耗能特种设备的设计文件，应当经国务院特种设备安全监督管理部门核准的检验检测机构鉴定，方可用于制造。\n第十三条 按照安全技术规范的要求，应当进行型式试验的特种设备产品、部件或者试制特种设备新产品、新部件、新材料，必须进行型式试验和能效测试。\n第十四条 锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施及其安全附件、安全保护装置的制造、安装、改造单位，以及压力管道用管子、管件、阀门、法兰、补偿器、安全保护装置等(以下简称压力管道元件)的制造单位和场(厂)内专用机动车辆的制造、改造单位，应当经国务院特种设备安全监督管理部门许可，方可从事相应的活动。\n前款特种设备的制造、安装、改造单位应当具备下列条件：\n(一)有与特种设备制造、安装、改造相适应的专业技术人员和技术工人；\n(二)有与特种设备制造、安装、改造相适应的生产条件和检测手段；\n(三)有健全的质量管理制度和责任制度。\n第十五条 特种设备出厂时，应当附有安全技术规范要求的设计文件、产品质量合格证明、安装及使用维修说明、监督检验证明等文件。\n第十六条 锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施、场(厂)内专用机动车辆的维修单位，应当有与特种设备维修相适应的专业技术人员和技术工人以及必要的检测手段，并经省、自治区、直辖市特种设备安全监督管理部门许可，方可从事相应的维修活动。\n第十七条 锅炉、压力容器、起重机械、客运索道、大型游乐设施的安装、改造、维修以及场(厂)内专用机动车辆的改造、维修，必须由依照本条例取得许可的单位进行。\n电梯的安装、改造、维修，必须由电梯制造单位或者其通过合同委托、同意的依照本条例取得许可的单位进行。电梯制造单位对电梯质量以及安全运行涉及的质量问题负责。\n特种设备安装、改造、维修的施工单位应当在施工前将拟进行的特种设备安装、改造、维修情况书面告知直辖市或者设区的市的特种设备安全监督管理部门，告知后即可施工。\n第十八条 电梯井道的土建工程必须符合建筑工程质量要求。电梯安装施工过程中，电梯安装单位应当遵守施工现场的安全生产要求，落实现场安全防护措施。电梯安装施工过程中，施工现场的安全生产监督，由有关部门依照有关法律、行政法规的规定执行。\n电梯安装施工过程中，电梯安装单位应当服从建筑施工总承包单位对施工现场的安全生产管理，并订立合同，明确各自的安全责任。\n第十九条 电梯的制造、安装、改造和维修活动，必须严格遵守安全技术规范的要求。电梯制造单位委托或者同意其他单位进行电梯安装、改造、维修活动的，应当对其安装、改造、维修活动进行安全指导和监控。电梯的安装、改造、维修活动结束后，电梯制造单位应当按照安全技术规范的要求对电梯进行校验和调试，并对校验和调试的结果负责。\n第二十条 锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施的安装、改造、维修以及场(厂)内专用机动车辆的改造、维修竣工后，安装、改造、维修的施工单位应当在验收后30日内将有关技术资料移交使用单位，高耗能特种设备还应当按照安全技术规范的要求提交能效测试报告。使用单位应当将其存入该特种设备的安全技术档案。\n第二十一条 锅炉、压力容器、压力管道元件、起重机械、大型游乐设施的制造过程和锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施的安装、改造、重大维修过程，必须经国务院特种设备安全监督管理部门核准的检验检测机构按照安全技术规范的要求进行监督检验；未经监督检验合格的不得出厂或者交付使用。\n第二十二条 移动式压力容器、气瓶充装单位应当经省、自治区、直辖市的特种设备安全监督管理部门许可，方可从事充装活动。\n充装单位应当具备下列条件：\n(一)有与充装和管理相适应的管理人员和技术人员；\n(二)有与充装和管理相适应的充装设备、检测手段、场地厂房、器具、安全设施；\n(三)有健全的充装管理制度、责任制度、紧急处理措施。\n气瓶充装单位应当向气体使用者提供符合安全技术规范要求的气瓶，对使用者进行气瓶安全使用指导，并按照安全技术规范的要求办理气瓶使用登记，提出气瓶的定期检验要求。","level":1},{"name":"第三章 特种设备的使用","text":"第二十三条 特种设备使用单位，应当严格执行本条例和有关安全生产的法律、行政法规的规定，保证特种设备的安全使用。\n第二十四条 特种设备使用单位应当使用符合安全技术规范要求的特种设备。特种设备投入使用前，使用单位应当核对其是否附有本条例第十五条规定的相关文件。\n第二十五条 特种设备在投入使用前或者投入使用后30日内，特种设备使用单位应当向直辖市或者设区的市的特种设备安全监督管理部门登记。登记标志应当置于或者附着于该特种设备的显著位置。\n第二十六条 特种设备使用单位应当建立特种设备安全技术档案。安全技术档案应当包括以下内容：\n(一)特种设备的设计文件、制造单位、产品质量合格证明、使用维护说明等文件以及安装技术文件和资料；\n(二)特种设备的定期检验和定期自行检查的记录；\n(三)特种设备的日常使用状况记录；\n(四)特种设备及其安全附件、安全保护装置、测量调控装置及有关附属仪器仪表的日常维护保养记录；\n(五)特种设备运行故障和事故记录；\n(六)高耗能特种设备的能效测试报告、能耗状况记录以及节能改造技术资料。\n第二十七条 特种设备使用单位应当对在用特种设备进行经常性日常维护保养，并定期自行检查。\n特种设备使用单位对在用特种设备应当至少每月进行一次自行检查，并作出记录。特种设备使用单位在对在用特种设备进行自行检查和日常维护保养时发现异常情况的，应当及时处理。\n特种设备使用单位应当对在用特种设备的安全附件、安全保护装置、测量调控装置及有关附属仪器仪表进行定期校验、检修，并作出记录。\n锅炉使用单位应当按照安全技术规范的要求进行锅炉水(介)质处理，并接受特种设备检验检测机构实施的水(介)质处理定期检验。\n从事锅炉清洗的单位，应当按照安全技术规范的要求进行锅炉清洗，并接受特种设备检验检测机构实施的锅炉清洗过程监督检验。\n第二十八条 特种设备使用单位应当按照安全技术规范的定期检验要求，在安全检验合格有效期届满前1个月向特种设备检验检测机构提出定期检验要求。\n检验检测机构接到定期检验要求后，应当按照安全技术规范的要求及时进行安全性能检验和能效测试。\n未经定期检验或者检验不合格的特种设备，不得继续使用。\n第二十九条 特种设备出现故障或者发生异常情况，使用单位应当对其进行全面检查，消除事故隐患后，方可重新投入使用。\n特种设备不符合能效指标的，特种设备使用单位应当采取相应措施进行整改。\n第三十条 特种设备存在严重事故隐患，无改造、维修价值，或者超过安全技术规范规定使用年限，特种设备使用单位应当及时予以报废，并应当向原登记的特种设备安全监督管理部门办理注销。\n第三十一条 电梯的日常维护保养必须由依照本条例取得许可的安装、改造、维修单位或者电梯制造单位进行。\n电梯应当至少每15日进行一次清洁、润滑、调整和检查。\n第三十二条 电梯的日常维护保养单位应当在维护保养中严格执行国家安全技术规范的要求，保证其维护保养的电梯的安全技术性能，并负责落实现场安全防护措施，保证施工安全。\n电梯的日常维护保养单位，应当对其维护保养的电梯的安全性能负责。接到故障通知后，应当立即赶赴现场，并采取必要的应急救援措施。\n第三十三条 电梯、客运索道、大型游乐设施等为公众提供服务的特种设备运营使用单位，应当设置特种设备安全管理机构或者配备专职的安全管理人员；其他特种设备使用单位，应当根据情况设置特种设备安全管理机构或者配备专职、兼职的安全管理人员。\n特种设备的安全管理人员应当对特种设备使用状况进行经常性检查，发现问题的应当立即处理；情况紧急时，可以决定停止使用特种设备并及时报告本单位有关负责人。\n第三十四条 客运索道、大型游乐设施的运营使用单位在客运索道、大型游乐设施每日投入使用前，应当进行试运行和例行安全检查，并对安全装置进行检查确认。\n电梯、客运索道、大型游乐设施的运营使用单位应当将电梯、客运索道、大型游乐设施的安全注意事项和警示标志置于易于为乘客注意的显著位置。\n第三十五条 客运索道、大型游乐设施的运营使用单位的主要负责人应当熟悉客运索道、大型游乐设施的相关安全知识，并全面负责客运索道、大型游乐设施的安全使用。\n客运索道、大型游乐设施的运营使用单位的主要负责人至少应当每月召开一次会议，督促、检查客运索道、大型游乐设施的安全使用工作。\n客运索道、大型游乐设施的运营使用单位，应当结合本单位的实际情况，配备相应数量的营救装备和急救物品。\n第三十六条 电梯、客运索道、大型游乐设施的乘客应当遵守使用安全注意事项的要求，服从有关工作人员的指挥。\n第三十七条 电梯投入使用后，电梯制造单位应当对其制造的电梯的安全运行情况进行跟踪调查和了解，对电梯的日常维护保养单位或者电梯的使用单位在安全运行方面存在的问题，提出改进建议，并提供必要的技术帮助。发现电梯存在严重事故隐患的，应当及时向特种设备安全监督管理部门报告。电梯制造单位对调查和了解的情况，应当作出记录。\n第三十八条 锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施、场(厂)内专用机动车辆的作业人员及其相关管理人员(以下统称特种设备作业人员)，应当按照国家有关规定经特种设备安全监督管理部门考核合格，取得国家统一格式的特种作业人员证书，方可从事相应的作业或者管理工作。\n第三十九条 特种设备使用单位应当对特种设备作业人员进行特种设备安全、节能教育和培训，保证特种设备作业人员具备必要的特种设备安全、节能知识。\n特种设备作业人员在作业中应当严格执行特种设备的操作规程和有关的安全规章制度。\n第四十条 特种设备作业人员在作业过程中发现事故隐患或者其他不安全因素，应当立即向现场安全管理人员和单位有关负责人报告。","level":1},{"name":"第四章 检验检测","text":"第四十一条 从事本条例规定的监督检验、定期检验、型式试验以及专门为特种设备生产、使用、检验检测提供无损检测服务的特种设备检验检测机构，应当经国务院特种设备安全监督管理部门核准。\n特种设备使用单位设立的特种设备检验检测机构，经国务院特种设备安全监督管理部门核准，负责本单位核准范围内的特种设备定期检验工作。\n第四十二条 特种设备检验检测机构，应当具备下列条件：\n(一)有与所从事的检验检测工作相适应的检验检测人员；\n(二)有与所从事的检验检测工作相适应的检验检测仪器和设备；\n(三)有健全的检验检测管理制度、检验检测责任制度。\n第四十三条 特种设备的监督检验、定期检验、型式试验和无损检测应当由依照本条例经核准的特种设备检验检测机构进行。\n特种设备检验检测工作应当符合安全技术规范的要求。\n第四十四条 从事本条例规定的监督检验、定期检验、型式试验和无损检测的特种设备检验检测人员应当经国务院特种设备安全监督管理部门组织考核合格，取得检验检测人员证书，方可从事检验检测工作。\n检验检测人员从事检验检测工作，必须在特种设备检验检测机构执业，但不得同时在两个以上检验检测机构中执业。\n第四十五条 特种设备检验检测机构和检验检测人员进行特种设备检验检测，应当遵循诚信原则和方便企业的原则，为特种设备生产、使用单位提供可靠、便捷的检验检测服务。\n特种设备检验检测机构和检验检测人员对涉及的被检验检测单位的商业秘密，负有保密义务。\n第四十六条 特种设备检验检测机构和检验检测人员应当客观、公正、及时地出具检验检测结果、鉴定结论。检验检测结果、鉴定结论经检验检测人员签字后，由检验检测机构负责人签署。\n特种设备检验检测机构和检验检测人员对检验检测结果、鉴定结论负责。\n国务院特种设备安全监督管理部门应当组织对特种设备检验检测机构的检验检测结果、鉴定结论进行监督抽查。县以上地方负责特种设备安全监督管理的部门在本行政区域内也可以组织监督抽查，但是要防止重复抽查。监督抽查结果应当向社会公布。\n第四十七条 特种设备检验检测机构和检验检测人员不得从事特种设备的生产、销售，不得以其名义推荐或者监制、监销特种设备。\n第四十八条 特种设备检验检测机构进行特种设备检验检测，发现严重事故隐患或者能耗严重超标的，应当及时告知特种设备使用单位，并立即向特种设备安全监督管理部门报告。\n第四十九条 特种设备检验检测机构和检验检测人员利用检验检测工作故意刁难特种设备生产、使用单位，特种设备生产、使用单位有权向特种设备安全监督管理部门投诉，接到投诉的特种设备安全监督管理部门应当及时进行调查处理。","level":1},{"name":"第五章 监督检查","text":"第五十条 特种设备安全监督管理部门依照本条例规定，对特种设备生产、使用单位和检验检测机构实施安全监察。\n对学校、幼儿园以及车站、客运码头、商场、体育场馆、展览馆、公园等公众聚集场所的特种设备，特种设备安全监督管理部门应当实施重点安全监察。\n第五十一条 特种设备安全监督管理部门根据举报或者取得的涉嫌违法证据，对涉嫌违反本条例规定的行为进行查处时，可以行使下列职权：\n(一)向特种设备生产、使用单位和检验检测机构的法定代表人、主要负责人和其他有关人员调查、了解与涉嫌从事违反本条例的生产、使用、检验检测有关的情况；\n(二)查阅、复制特种设备生产、使用单位和检验检测机构的有关合同、发票、账簿以及其他有关资料；\n(三)对有证据表明不符合安全技术规范要求的或者有其他严重事故隐患、能耗严重超标的特种设备，予以查封或者扣押。\n第五十二条 依照本条例规定实施许可、核准、登记的特种设备安全监督管理部门，应当严格依照本条例规定条件和安全技术规范要求对有关事项进行审查；不符合本条例规定条件和安全技术规范要求的，不得许可、核准、登记；在申请办理许可、核准期间，特种设备安全监督管理部门发现申请人未经许可从事特种设备相应活动或者伪造许可、核准证书的，不予受理或者不予许可、核准，并在1年内不再受理其新的许可、核准申请。\n未依法取得许可、核准、登记的单位擅自从事特种设备的生产、使用或者检验检测活动的，特种设备安全监督管理部门应当依法予以处理。\n违反本条例规定，被依法撤销许可的，自撤销许可之日起3年内，特种设备安全监督管理部门不予受理其新的许可申请。\n第五十三条 特种设备安全监督管理部门在办理本条例规定的有关行政审批事项时，其受理、审查、许可、核准的程序必须公开，并应当自受理申请之日起30日内，作出许可、核准或者不予许可、核准的决定；不予许可、核准的，应当书面向申请人说明理由。\n第五十四条 地方各级特种设备安全监督管理部门不得以任何形式进行地方保护和地区封锁，不得对已经依照本条例规定在其他地方取得许可的特种设备生产单位重复进行许可，也不得要求对依照本条例规定在其他地方检验检测合格的特种设备，重复进行检验检测。\n第五十五条 特种设备安全监督管理部门的安全监察人员(以下简称特种设备安全监察人员)应当熟悉相关法律、法规、规章和安全技术规范，具有相应的专业知识和工作经验，并经国务院特种设备安全监督管理部门考核，取得特种设备安全监察人员证书。\n特种设备安全监察人员应当忠于职守、坚持原则、秉公执法。\n第五十六条 特种设备安全监督管理部门对特种设备生产、使用单位和检验检测机构实施安全监察时，应当有两名以上特种设备安全监察人员参加，并出示有效的特种设备安全监察人员证件。\n第五十七条 特种设备安全监督管理部门对特种设备生产、使用单位和检验检测机构实施安全监察，应当对每次安全监察的内容、发现的问题及处理情况，作出记录，并由参加安全监察的特种设备安全监察人员和被检查单位的有关负责人签字后归档。被检查单位的有关负责人拒绝签字的，特种设备安全监察人员应当将情况记录在案。\n第五十八条 特种设备安全监督管理部门对特种设备生产、使用单位和检验检测机构进行安全监察时，发现有违反本条例规定和安全技术规范要求的行为或者在用的特种设备存在事故隐患、不符合能效指标的，应当以书面形式发出特种设备安全监察指令，责令有关单位及时采取措施，予以改正或者消除事故隐患。紧急情况下需要采取紧急处置措施的，应当随后补发书面通知。\n第五十九条 特种设备安全监督管理部门对特种设备生产、使用单位和检验检测机构进行安全监察，发现重大违法行为或者严重事故隐患时，应当在采取必要措施的同时，及时向上级特种设备安全监督管理部门报告。接到报告的特种设备安全监督管理部门应当采取必要措施，及时予以处理。\n对违法行为、严重事故隐患或者不符合能效指标的处理需要当地人民政府和有关部门的支持、配合时，特种设备安全监督管理部门应当报告当地人民政府，并通知其他有关部门。当地人民政府和其他有关部门应当采取必要措施，及时予以处理。\n第六十条 国务院特种设备安全监督管理部门和省、自治区、直辖市特种设备安全监督管理部门应当定期向社会公布特种设备安全以及能效状况。\n公布特种设备安全以及能效状况，应当包括下列内容：\n(一)特种设备质量安全状况；\n(二)特种设备事故的情况、特点、原因分析、防范对策；\n(三)特种设备能效状况；\n(四)其他需要公布的情况。","level":1},{"name":"第六章 事故预防和调查处理","text":"第六十一条 有下列情形之一的，为特别重大事故：\n(一)特种设备事故造成30人以上死亡，或者100人以上重伤(包括急性工业中毒，下同)，或者1亿元以上直接经济损失的；\n(二)600兆瓦以上锅炉爆炸的；\n(三)压力容器、压力管道有毒介质泄漏，造成15万人以上转移的；\n(四)客运索道、大型游乐设施高空滞留100人以上并且时间在48小时以上的。\n第六十二条 有下列情形之一的，为重大事故：\n(一)特种设备事故造成10人以上30人以下死亡，或者50人以上100人以下重伤，或者5000万元以上1亿元以下直接经济损失的；\n(二)600兆瓦以上锅炉因安全故障中断运行240小时以上的；\n(三)压力容器、压力管道有毒介质泄漏，造成5万人以上15万人以下转移的；\n(四)客运索道、大型游乐设施高空滞留100人以上并且时间在24小时以上48小时以下的。\n第六十三条 有下列情形之一的，为较大事故：\n(一)特种设备事故造成3人以上10人以下死亡，或者10人以上50人以下重伤，或者1000万元以上5000万元以下直接经济损失的；\n(二)锅炉、压力容器、压力管道爆炸的；\n(三)压力容器、压力管道有毒介质泄漏，造成1万人以上5万人以下转移的；\n(四)起重机械整体倾覆的；\n(五)客运索道、大型游乐设施高空滞留人员12小时以上的。\n第六十四条 有下列情形之一的，为一般事故：\n(一)特种设备事故造成3人以下死亡，或者10人以下重伤，或者1万元以上1000万元以下直接经济损失的；\n(二)压力容器、压力管道有毒介质泄漏，造成500人以上1万人以下转移的；\n(三)电梯轿厢滞留人员2小时以上的；\n(四)起重机械主要受力结构件折断或者起升机构坠落的；\n(五)客运索道高空滞留人员3.5小时以上12小时以下的；\n(六)大型游乐设施高空滞留人员1小时以上12小时以下的。\n除前款规定外，国务院特种设备安全监督管理部门可以对一般事故的其他情形做出补充规定。\n第六十五条 特种设备安全监督管理部门应当制定特种设备应急预案。特种设备使用单位应当制定事故应急专项预案，并定期进行事故应急演练。\n压力容器、压力管道发生爆炸或者泄漏，在抢险救援时应当区分介质特性，严格按照相关预案规定程序处理，防止二次爆炸。\n第六十六条 特种设备事故发生后，事故发生单位应当立即启动事故应急预案，组织抢救，防止事故扩大，减少人员伤亡和财产损失，并及时向事故发生地县以上特种设备安全监督管理部门和有关部门报告。\n县以上特种设备安全监督管理部门接到事故报告，应当尽快核实有关情况，立即向所在地人民政府报告，并逐级上报事故情况。必要时，特种设备安全监督管理部门可以越级上报事故情况。对特别重大事故、重大事故，国务院特种设备安全监督管理部门应当立即报告国务院并通报国务院安全生产监督管理部门等有关部门。\n第六十七条 特别重大事故由国务院或者国务院授权有关部门组织事故调查组进行调查。\n重大事故由国务院特种设备安全监督管理部门会同有关部门组织事故调查组进行调查。\n较大事故由省、自治区、直辖市特种设备安全监督管理部门会同有关部门组织事故调查组进行调查。\n一般事故由设区的市的特种设备安全监督管理部门会同有关部门组织事故调查组进行调查。\n第六十八条 事故调查报告应当由负责组织事故调查的特种设备安全监督管理部门的所在地人民政府批复，并报上一级特种设备安全监督管理部门备案。\n有关机关应当按照批复，依照法律、行政法规规定的权限和程序，对事故责任单位和有关人员进行行政处罚，对负有事故责任的国家工作人员进行处分。\n第六十九条 特种设备安全监督管理部门应当在有关地方人民政府的领导下，组织开展特种设备事故调查处理工作。\n有关地方人民政府应当支持、配合上级人民政府或者特种设备安全监督管理部门的事故调查处理工作，并提供必要的便利条件。\n第七十条 特种设备安全监督管理部门应当对发生事故的原因进行分析，并根据特种设备的管理和技术特点、事故情况对相关安全技术规范进行评估；需要制定或者修订相关安全技术规范的，应当及时制定或者修订。\n第七十一条 本章所称的“以上”包括本数，所称的“以下”不包括本数。","level":1},{"name":"第七章 法律责任","text":"第七十二条 未经许可，擅自从事压力容器设计活动的，由特种设备安全监督管理部门予以取缔，处5万元以上20万元以下罚款；有违法所得的，没收违法所得；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于非法经营罪或者其他罪的规定，依法追究刑事责任。\n第七十三条 锅炉、气瓶、氧舱和客运索道、大型游乐设施以及高耗能特种设备的设计文件，未经国务院特种设备安全监督管理部门核准的检验检测机构鉴定，擅自用于制造的，由特种设备安全监督管理部门责令改正，没收非法制造的产品，处5万元以上20万元以下罚款；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于生产、销售伪劣产品罪、非法经营罪或者其他罪的规定，依法追究刑事责任。\n第七十四条 按照安全技术规范的要求应当进行型式试验的特种设备产品、部件或者试制特种设备新产品、新部件，未进行整机或者部件型式试验的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，处2万元以上10万元以下罚款。\n第七十五条 未经许可，擅自从事锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施、场(厂)内专用机动车辆及其安全附件、安全保护装置的制造、安装、改造以及压力管道元件的制造活动的，由特种设备安全监督管理部门予以取缔，没收非法制造的产品，已经实施安装、改造的，责令恢复原状或者责令限期由取得许可的单位重新安装、改造，处10万元以上50万元以下罚款；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于生产、销售伪劣产品罪、非法经营罪、重大责任事故罪或者其他罪的规定，依法追究刑事责任。\n第七十六条 特种设备出厂时，未按照安全技术规范的要求附有设计文件、产品质量合格证明、安装及使用维修说明、监督检验证明等文件的，由特种设备安全监督管理部门责令改正；情节严重的，责令停止生产、销售，处违法生产、销售货值金额30%以下罚款；有违法所得的，没收违法所得。\n第七十七条 未经许可，擅自从事锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施、场(厂)内专用机动车辆的维修或者日常维护保养的，由特种设备安全监督管理部门予以取缔，处1万元以上5万元以下罚款；有违法所得的，没收违法所得；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于非法经营罪、重大责任事故罪或者其他罪的规定，依法追究刑事责任。\n第七十八条 锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施的安装、改造、维修的施工单位以及场(厂)内专用机动车辆的改造、维修单位，在施工前未将拟进行的特种设备安装、改造、维修情况书面告知直辖市或者设区的市的特种设备安全监督管理部门即行施工的，或者在验收后30日内未将有关技术资料移交锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施的使用单位的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，处2000元以上1万元以下罚款。\n第七十九条 锅炉、压力容器、压力管道元件、起重机械、大型游乐设施的制造过程和锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施的安装、改造、重大维修过程，以及锅炉清洗过程，未经国务院特种设备安全监督管理部门核准的检验检测机构按照安全技术规范的要求进行监督检验的，由特种设备安全监督管理部门责令改正，已经出厂的，没收违法生产、销售的产品，已经实施安装、改造、重大维修或者清洗的，责令限期进行监督检验，处5万元以上20万元以下罚款；有违法所得的，没收违法所得；情节严重的，撤销制造、安装、改造或者维修单位已经取得的许可，并由工商行政管理部门吊销其营业执照；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于生产、销售伪劣产品罪或者其他罪的规定，依法追究刑事责任。\n第八十条 未经许可，擅自从事移动式压力容器或者气瓶充装活动的，由特种设备安全监督管理部门予以取缔，没收违法充装的气瓶，处10万元以上50万元以下罚款；有违法所得的，没收违法所得；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于非法经营罪或者其他罪的规定，依法追究刑事责任。\n移动式压力容器、气瓶充装单位未按照安全技术规范的要求进行充装活动的，由特种设备安全监督管理部门责令改正，处2万元以上10万元以下罚款；情节严重的，撤销其充装资格。\n第八十一条 电梯制造单位有下列情形之一的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，予以通报批评：\n(一)未依照本条例第十九条的规定对电梯进行校验、调试的；\n(二)对电梯的安全运行情况进行跟踪调查和了解时，发现存在严重事故隐患，未及时向特种设备安全监督管理部门报告的。\n第八十二条 已经取得许可、核准的特种设备生产单位、检验检测机构有下列行为之一的，由特种设备安全监督管理部门责令改正，处2万元以上10万元以下罚款；情节严重的，撤销其相应资格：\n(一)未按照安全技术规范的要求办理许可证变更手续的；\n(二)不再符合本条例规定或者安全技术规范要求的条件，继续从事特种设备生产、检验检测的；\n(三)未依照本条例规定或者安全技术规范要求进行特种设备生产、检验检测的；\n(四)伪造、变造、出租、出借、转让许可证书或者监督检验报告的。\n第八十三条 特种设备使用单位有下列情形之一的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，处2000元以上2万元以下罚款；情节严重的，责令停止使用或者停产停业整顿：\n(一)特种设备投入使用前或者投入使用后30日内，未向特种设备安全监督管理部门登记，擅自将其投入使用的；\n(二)未依照本条例第二十六条的规定，建立特种设备安全技术档案的；\n(三)未依照本条例第二十七条的规定，对在用特种设备进行经常性日常维护保养和定期自行检查的，或者对在用特种设备的安全附件、安全保护装置、测量调控装置及有关附属仪器仪表进行定期校验、检修，并作出记录的；\n(四)未按照安全技术规范的定期检验要求，在安全检验合格有效期届满前1个月向特种设备检验检测机构提出定期检验要求的；\n(五)使用未经定期检验或者检验不合格的特种设备的；\n(六)特种设备出现故障或者发生异常情况，未对其进行全面检查、消除事故隐患，继续投入使用的；\n(七)未制定特种设备事故应急专项预案的；\n(八)未依照本条例第三十一条第二款的规定，对电梯进行清洁、润滑、调整和检查的；\n(九)未按照安全技术规范要求进行锅炉水(介)质处理的；\n(十)特种设备不符合能效指标，未及时采取相应措施进行整改的。\n特种设备使用单位使用未取得生产许可的单位生产的特种设备或者将非承压锅炉、非压力容器作为承压锅炉、压力容器使用的，由特种设备安全监督管理部门责令停止使用，予以没收，处2万元以上10万元以下罚款。\n第八十四条 特种设备存在严重事故隐患，无改造、维修价值，或者超过安全技术规范规定的使用年限，特种设备使用单位未予以报废，并向原登记的特种设备安全监督管理部门办理注销的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，处5万元以上20万元以下罚款。\n第八十五条 电梯、客运索道、大型游乐设施的运营使用单位有下列情形之一的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，责令停止使用或者停产停业整顿，处1万元以上5万元以下罚款：\n(一)客运索道、大型游乐设施每日投入使用前，未进行试运行和例行安全检查，并对安全装置进行检查确认的；\n(二)未将电梯、客运索道、大型游乐设施的安全注意事项和警示标志置于易于为乘客注意的显著位置的。\n第八十六条 特种设备使用单位有下列情形之一的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，责令停止使用或者停产停业整顿，处2000元以上2万元以下罚款：\n(一)未依照本条例规定设置特种设备安全管理机构或者配备专职、兼职的安全管理人员的；\n(二)从事特种设备作业的人员，未取得相应特种作业人员证书，上岗作业的；\n(三)未对特种设备作业人员进行特种设备安全教育和培训的。\n第八十七条 发生特种设备事故，有下列情形之一的，对单位，由特种设备安全监督管理部门处5万元以上20万元以下罚款；对主要负责人，由特种设备安全监督管理部门处4000元以上2万元以下罚款；属于国家工作人员的，依法给予处分；触犯刑律的，依照刑法关于重大责任事故罪或者其他罪的规定，依法追究刑事责任：\n(一)特种设备使用单位的主要负责人在本单位发生特种设备事故时，不立即组织抢救或者在事故调查处理期间擅离职守或者逃匿的；\n(二)特种设备使用单位的主要负责人对特种设备事故隐瞒不报、谎报或者拖延不报的。\n第八十八条 对事故发生负有责任的单位，由特种设备安全监督管理部门依照下列规定处以罚款：\n(一)发生一般事故的，处10万元以上20万元以下罚款；\n(二)发生较大事故的，处20万元以上50万元以下罚款；\n(三)发生重大事故的，处50万元以上200万元以下罚款。\n第八十九条 对事故发生负有责任的单位的主要负责人未依法履行职责，导致事故发生的，由特种设备安全监督管理部门依照下列规定处以罚款；属于国家工作人员的，并依法给予处分；触犯刑律的，依照刑法关于重大责任事故罪或者其他罪的规定，依法追究刑事责任：\n(一)发生一般事故的，处上一年年收入30%的罚款；\n(二)发生较大事故的，处上一年年收入40%的罚款；\n(三)发生重大事故的，处上一年年收入60%的罚款。\n第九十条 特种设备作业人员违反特种设备的操作规程和有关的安全规章制度操作，或者在作业过程中发现事故隐患或者其他不安全因素，未立即向现场安全管理人员和单位有关负责人报告的，由特种设备使用单位给予批评教育、处分；情节严重的，撤销特种设备作业人员资格；触犯刑律的，依照刑法关于重大责任事故罪或者其他罪的规定，依法追究刑事责任。\n第九十一条 未经核准，擅自从事本条例所规定的监督检验、定期检验、型式试验以及无损检测等检验检测活动的，由特种设备安全监督管理部门予以取缔，处5万元以上20万元以下罚款；有违法所得的，没收违法所得；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于非法经营罪或者其他罪的规定，依法追究刑事责任。\n第九十二条 特种设备检验检测机构，有下列情形之一的，由特种设备安全监督管理部门处2万元以上10万元以下罚款；情节严重的，撤销其检验检测资格：\n(一)聘用未经特种设备安全监督管理部门组织考核合格并取得检验检测人员证书的人员，从事相关检验检测工作的；\n(二)在进行特种设备检验检测中，发现严重事故隐患或者能耗严重超标，未及时告知特种设备使用单位，并立即向特种设备安全监督管理部门报告的。\n第九十三条 特种设备检验检测机构和检验检测人员，出具虚假的检验检测结果、鉴定结论或者检验检测结果、鉴定结论严重失实的，由特种设备安全监督管理部门对检验检测机构没收违法所得，处5万元以上20万元以下罚款，情节严重的，撤销其检验检测资格；对检验检测人员处5000元以上5万元以下罚款，情节严重的，撤销其检验检测资格，触犯刑律的，依照刑法关于中介组织人员提供虚假证明文件罪、中介组织人员出具证明文件重大失实罪或者其他罪的规定，依法追究刑事责任。\n特种设备检验检测机构和检验检测人员，出具虚假的检验检测结果、鉴定结论或者检验检测结果、鉴定结论严重失实，造成损害的，应当承担赔偿责任。\n第九十四条 特种设备检验检测机构或者检验检测人员从事特种设备的生产、销售，或者以其名义推荐或者监制、监销特种设备的，由特种设备安全监督管理部门撤销特种设备检验检测机构和检验检测人员的资格，处5万元以上20万元以下罚款；有违法所得的，没收违法所得。\n第九十五条 特种设备检验检测机构和检验检测人员利用检验检测工作故意刁难特种设备生产、使用单位，由特种设备安全监督管理部门责令改正；拒不改正的，撤销其检验检测资格。\n第九十六条 检验检测人员，从事检验检测工作，不在特种设备检验检测机构执业或者同时在两个以上检验检测机构中执业的，由特种设备安全监督管理部门责令改正，情节严重的，给予停止执业6个月以上2年以下的处罚；有违法所得的，没收违法所得。\n第九十七条 特种设备安全监督管理部门及其特种设备安全监察人员，有下列违法行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予降级或者撤职的处分；触犯刑律的，依照刑法关于受贿罪、滥用职权罪、玩忽职守罪或者其他罪的规定，依法追究刑事责任：\n(一)不按照本条例规定的条件和安全技术规范要求，实施许可、核准、登记的；\n(二)发现未经许可、核准、登记擅自从事特种设备的生产、使用或者检验检测活动不予取缔或者不依法予以处理的；\n(三)发现特种设备生产、使用单位不再具备本条例规定的条件而不撤销其原许可，或者发现特种设备生产、使用违法行为不予查处的；\n(四)发现特种设备检验检测机构不再具备本条例规定的条件而不撤销其原核准，或者对其出具虚假的检验检测结果、鉴定结论或者检验检测结果、鉴定结论严重失实的行为不予查处的；\n(五)对依照本条例规定在其他地方取得许可的特种设备生产单位重复进行许可，或者对依照本条例规定在其他地方检验检测合格的特种设备，重复进行检验检测的；\n(六)发现有违反本条例和安全技术规范的行为或者在用的特种设备存在严重事故隐患，不立即处理的；\n(七)发现重大的违法行为或者严重事故隐患，未及时向上级特种设备安全监督管理部门报告，或者接到报告的特种设备安全监督管理部门不立即处理的；\n(八)迟报、漏报、瞒报或者谎报事故的；\n(九)妨碍事故救援或者事故调查处理的。\n第九十八条 特种设备的生产、使用单位或者检验检测机构，拒不接受特种设备安全监督管理部门依法实施的安全监察的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，责令停产停业整顿，处2万元以上10万元以下罚款；触犯刑律的，依照刑法关于妨害公务罪或者其他罪的规定，依法追究刑事责任。\n特种设备生产、使用单位擅自动用、调换、转移、损毁被查封、扣押的特种设备或者其主要部件的，由特种设备安全监督管理部门责令改正，处5万元以上20万元以下罚款；情节严重的，撤销其相应资格。","level":1},{"name":"第八章 附则","text":"第九十九条 本条例下列用语的含义是：\n(一)锅炉，是指利用各种燃料、电或者其他能源，将所盛装的液体加热到一定的参数，并对外输出热能的设备，其范围规定为容积大于或者等于30L的承压蒸汽锅炉；出口水压大于或者等于0.1MPa(表压)，且额定功率大于或者等于0.1MW的承压热水锅炉；有机热载体锅炉。\n(二)压力容器，是指盛装气体或者液体，承载一定压力的密闭设备，其范围规定为最高工作压力大于或者等于0.1MPa(表压)，且压力与容积的乘积大于或者等于2.5MPa·L的气体、液化气体和最高工作温度高于或者等于标准沸点的液体的固定式容器和移动式容器；盛装公称工作压力大于或者等于0.2MPa(表压)，且压力与容积的乘积大于或者等于1.0MPa·L的气体、液化气体和标准沸点等于或者低于60℃液体的气瓶；氧舱等。\n(三)压力管道，是指利用一定的压力，用于输送气体或者液体的管状设备，其范围规定为最高工作压力大于或者等于0.1MPa(表压)的气体、液化气体、蒸汽介质或者可燃、易爆、有毒、有腐蚀性、最高工作温度高于或者等于标准沸点的液体介质，且公称直径大于25mm的管道。\n(四)电梯，是指动力驱动，利用沿刚性导轨运行的箱体或者沿固定线路运行的梯级(踏步)，进行升降或者平行运送人、货物的机电设备，包括载人(货)电梯、自动扶梯、自动人行道等。\n(五)起重机械，是指用于垂直升降或者垂直升降并水平移动重物的机电设备，其范围规定为额定起重量大于或者等于0.5t的升降机；额定起重量大于或者等于1t，且提升高度大于或者等于2m的起重机和承重形式固定的电动葫芦等。\n(六)客运索道，是指动力驱动，利用柔性绳索牵引箱体等运载工具运送人员的机电设备，包括客运架空索道、客运缆车、客运拖牵索道等。\n(七)大型游乐设施，是指用于经营目的，承载乘客游乐的设施，其范围规定为设计最大运行线速度大于或者等于2m/s，或者运行高度距地面高于或者等于2m的载人大型游乐设施。\n(八)场(厂)内专用机动车辆，是指除道路交通、农用车辆以外仅在工厂厂区、旅游景区、游乐场所等特定区域使用的专用机动车辆。\n特种设备包括其所用的材料、附属的安全附件、安全保护装置和与安全保护装置相关的设施。\n第一百条 压力管道设计、安装、使用的安全监督管理办法由国务院另行制定。\n第一百零一条 国务院特种设备安全监督管理部门可以授权省、自治区、直辖市特种设备安全监督管理部门负责本条例规定的特种设备行政许可工作，具体办法由国务院特种设备安全监督管理部门制定。\n第一百零二条 特种设备行政许可、检验检测，应当按照国家有关规定收取费用。\n第一百零三条 本条例自2003年6月1日起施行。1982年2月6日国务院发布的《锅炉压力容器安全监察暂行条例》同时废止。","level":1}]},{"id":"n0349","sections":[{"name":"","text":"票据管理实施办法\n(1997年6月23日国务院批准 1997年8月21日中国人民银行令第2号发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》修订)\n第一条 为了加强票据管理，维护金融秩序，根据《中华人民共和国票据法》(以下简称票据法)的规定，制定本办法。\n第二条 在中华人民共和国境内的票据管理，适用本办法。\n第三条 中国人民银行是票据的管理部门。\n票据管理应当遵守票据法和本办法以及有关法律、行政法规的规定，不得损害票据当事人的合法权益。\n第四条 票据当事人应当依法从事票据活动，行使票据权利，履行票据义务。\n第五条 票据当事人应当使用中国人民银行规定的统一格式的票据。\n第六条 银行汇票的出票人，为经中国人民银行批准办理银行汇票业务的银行。\n第七条 银行本票的出票人，为经中国人民银行批准办理银行本票业务的银行。\n第八条 商业汇票的出票人，为银行以外的企业和其他组织。\n向银行申请办理汇票承兑的商业汇票的出票人，必须具备下列条件：\n(一)在承兑银行开立存款账户；\n(二)资信状况良好，并具有支付汇票金额的可靠资金来源。\n第九条 承兑商业汇票的银行，必须具备下列条件：\n(一)与出票人具有真实的委托付款关系；\n(二)具有支付汇票金额的可靠资金。\n第十条 向银行申请办理票据贴现的商业汇票的持票人，必须具备下列条件：\n(一)在银行开立存款账户；\n(二)与出票人、前手之间具有真实的交易关系和债权债务关系。\n第十一条 支票的出票人，为在经中国人民银行批准办理支票存款业务的银行、城市信用合作社和农村信用合作社开立支票存款账户的企业、其他组织和个人。\n第十二条 票据法所称“保证人”，是指具有代为清偿票据债务能力的法人、其他组织或者个人。\n国家机关、以公益为目的的事业单位、社会团体、企业法人的分支机构和职能部门不得为保证人；但是，法律另有规定的除外。\n第十三条 银行汇票上的出票人的签章、银行承兑商业汇票的签章，为该银行的汇票专用章加其法定代表人或者其授权的代理人的签名或者盖章。\n银行本票上的出票人的签章，为该银行的本票专用章加其法定代表人或者其授权的代理人的签名或者盖章。\n银行汇票专用章、银行本票专用章须经中国人民银行批准。\n第十四条 商业汇票上的出票人的签章，为该单位的财务专用章或者公章加其法定代表人或者其授权的代理人的签名或者盖章。\n第十五条 支票上的出票人的签章，出票人为单位的，为与该单位在银行预留签章一致的财务专用章或者公章加其法定代表人或者其授权的代理人的签名或者盖章；出票人为个人的，为与该个人在银行预留签章一致的签名或者盖章。\n第十六条 票据法所称“本名”，是指符合法律、行政法规以及国家有关规定的身份证件上的姓名。\n第十七条 出票人在票据上的签章不符合票据法和本办法规定的，票据无效；背书人、承兑人、保证人在票据上的签章不符合票据法和本办法规定的，其签章无效，但是不影响票据上其他签章的效力。\n第十八条 票据法所称“代理付款人”，是指根据付款人的委托，代其支付票据金额的银行、城市信用合作社和农村信用合作社。\n第十九条 票据法规定可以办理挂失止付的票据丧失的，失票人可以依照票据法的规定及时通知付款人或者代理付款人挂失止付。\n失票人通知票据的付款人或者代理付款人挂失止付时，应当填写挂失止付通知书并签章。挂失止付通知书应当记载下列事项：\n(一)票据丧失的时间和事由；\n(二)票据种类、号码、金额、出票日期、付款日期、付款人名称、收款人名称；\n(三)挂失止付人的名称、营业场所或者住所以及联系方法。\n第二十条 付款人或者代理付款人收到挂失止付通知书，应当立即暂停支付。付款人或者代理付款人自收到挂失止付通知书之日起12日内没有收到人民法院的止付通知书的，自第13日起，挂失止付通知书失效。\n第二十一条 付款人或者代理付款人在收到挂失止付通知书前，已经依法向持票人付款的，不再接受挂失止付。\n第二十二条 申请人申请开立支票存款账户的，银行、城市信用合作社和农村信用合作社可以与申请人约定在支票上使用支付密码，作为支付支票金额的条件。\n第二十三条 保证人应当依照票据法的规定，在票据或者其粘单上记载保证事项。保证人为出票人、付款人、承兑人保证的，应当在票据的正面记载保证事项；保证人为背书人保证的，应当在票据的背面或者其粘单上记载保证事项。\n第二十四条 依法背书转让的票据，任何单位和个人不得冻结票据款项；但是，法律另有规定的除外。\n第二十五条 票据法第五十五条所称“签收”，是指持票人在票据的正面签章，表明持票人已经获得付款。\n第二十六条 通过委托收款银行或者通过票据交换系统向付款人提示付款的，持票人向银行提交票据日为提示付款日。\n第二十七条 票据法第六十二条所称“拒绝证明”应当包括下列事项：\n(一)被拒绝承兑、付款的票据的种类及其主要记载事项；\n(二)拒绝承兑、付款的事实依据和法律依据；\n(三)拒绝承兑、付款的时间；\n(四)拒绝承兑人、拒绝付款人的签章。\n票据法第六十二条所称“退票理由书”应当包括下列事项：\n(一)所退票据的种类；\n(二)退票的事实依据和法律依据；\n(三)退票时间；\n(四)退票人签章。\n第二十八条 票据法第六十三条规定的“其他有关证明”是指：\n(一)医院或者有关单位出具的承兑人、付款人死亡的证明；\n(二)司法机关出具的承兑人、付款人逃匿的证明；\n(三)公证机关出具的具有拒绝证明效力的文书。\n第二十九条 票据法第七十条第一款第(二)项、第七十一条第一款第(二)项规定的“利率”，是指中国人民银行规定的流动资金贷款利率。\n第三十条 有票据法第一百零二条所列行为之一，情节轻微，不构成犯罪的，由公安机关依法予以处罚。\n第三十一条 签发空头支票或者签发与其预留的签章不符的支票，不以骗取财物为目的的，由中国人民银行处以票面金额5%但不低于1000元的罚款；持票人有权要求出票人赔偿支票金额2%的赔偿金。\n第三十二条 金融机构的工作人员在票据业务中玩忽职守，对违反票据法和本办法规定的票据予以承兑、付款、保证或者贴现的，对直接负责的主管人员和其他直接责任人员给予警告、记过、撤职或者开除的处分；造成重大损失，构成犯罪的，依法追究刑事责任。\n第三十三条 票据的付款人对见票即付或者到期的票据，故意压票、拖延支付的，由中国人民银行处以压票、拖延支付期间内每日票据金额0.7‰的罚款；对直接负责的主管人员和其他直接责任人员给予警告、记过、撤职或者开除的处分。\n第三十四条 违反中国人民银行规定，擅自印制票据的，由中国人民银行责令改正，处以1万元以上20万元以下的罚款；情节严重的，中国人民银行有权提请有关部门吊销其营业执照。\n第三十五条 票据的格式、联次、颜色、规格及防伪技术要求和印制，由中国人民银行规定。\n中国人民银行在确定票据格式时，可以根据少数民族地区和外国驻华使领馆的实际需要，在票据格式中增加少数民族文字或者外国文字。\n第三十六条 本办法自1997年10月1日起施行。","level":0}]},{"id":"n0350","sections":[{"name":"","text":"中华人民共和国国境口岸卫生监督办法\n(1981年12月30日国务院批准 1982年2月4日卫生部、交通部、中国民用航空总局、铁道部发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2019年3月2日《国务院关于修改部分行政法规的决定》第二次修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强国境口岸和国际航行交通工具的卫生监督工作，改善国境口岸和交通工具的卫生面貌，控制和消灭传染源，切断传播途径，防止传染病由国外传入和由国内传出，保障人民身体健康，制定本办法。\n第二条 本办法适用于对外开放的港口、机场、车站、关口(下称国境口岸)和停留在这些处所的国际航行的船舶、飞机和车辆(下称交通工具)。","level":1},{"name":"第二章 国境口岸的卫生要求","text":"第三条 国境口岸应当建立卫生清扫制度，消灭蚊蝇孳生场所，设置污物箱，定期进行清理，保持环境整洁。\n第四条 国境口岸的生活垃圾应当日产日清，设置的固定垃圾场，应当定期清除；生活污水不得任意排放，应当做到无害化处理，以防止污染环境和水源。\n第五条 对国境口岸的建筑物，有关部门应当采取切实可行的措施，控制病媒昆虫、啮齿动物，使其数量降低到不足为害的程度。\n第六条 候船室、候机室、候车室、候检室应当做到地面整洁、墙壁无尘土、窗明几净、通风良好，并备有必要的卫生设施。\n第七条 国境口岸的餐厅、食堂、厨房、小卖部应当建立和健全卫生制度，经常保持整洁，做到墙壁、天花板、桌椅清洁无尘土；应当有防蚊、防蝇、防鼠和冷藏设备，做到室内无蚊、无蝇、无鼠、无蟑螂。\n第八条 国境口岸的厕所和浴室应当有专人管理，及时打扫，保持整洁，做到无蝇、无臭味。\n第九条 国境口岸的仓库、货场应当保持清洁、整齐；发现鼠类有反常死亡时，应当及时向卫生检疫机关或地方卫生防疫部门报告。\n第十条 做好国境口岸水源保护，在水源周围直径30米内，不得修建厕所、渗井等污染水源设施。","level":1},{"name":"第三章 交通工具的卫生要求","text":"第十一条 交通工具上必须备有急救药物、急救设备及消毒、杀虫、灭鼠药物。必要时，船舶上还需安排临时隔离室。\n第十二条 交通工具上的病媒昆虫和啮齿动物的防除：\n(一)船舶、飞机、列车上，应当备有足够数量有效的防鼠装置；保持无鼠或鼠类数量保持不足为害的程度。\n(二)应当保持无蚊、无蝇、无其他有害昆虫，一旦发现应当采取杀灭措施。\n第十三条 交通工具上的厕所、浴室必须保持整洁，无臭味。\n第十四条 交通工具上的粪便、垃圾、污水处理的卫生要求：\n(一)生活垃圾应当集中放在带盖的容器内，禁止向港区、机场、站区随意倾倒，应当由污物专用车(船)集中送往指定地点进行无害化处理。必要时，粪便、污水须经过卫生处理后方能排放；\n(二)来自鼠疫疫区交通工具上的固体垃圾必须进行焚化处理，来自霍乱疫区交通工具上的粪便、压舱水、污水，必要时实施消毒。\n第十五条 交通工具的货舱、行李车、邮政车和货车的卫生要求：\n(一)货舱、行李车、邮政车、货车应当消灭蚊、蝇、蟑螂、鼠等病媒昆虫和有害动物及其孳生条件；在装货前或卸货后应当进行彻底清扫，做到无粪便、垃圾；\n(二)凡装载有毒物品和食品的货车，应当分开按指定地点存放，防止污染，货物卸空后应当进行彻底洗刷；\n(三)来自疫区的行李、货物，要严格检查，防止带有病媒昆虫和啮齿动物。\n第十六条 交通工具上的客舱、宿舱、客车的卫生要求：\n(一)客舱、宿舱和客车应当随时擦洗，保持无垃圾尘土，通风良好；\n(二)卧具每次使用后必须换洗。卧具上不得有虱子、跳蚤、臭虫等病媒昆虫。","level":1},{"name":"第四章 食品、饮用水及从业人员的卫生要求","text":"第十七条 供应国境口岸和交通工具上的食品必须符合《中华人民共和国食品安全法》的规定和食品安全标准。\n第十八条 凡供应国境口岸和交通工具上的饮用水必须符合我国规定的“生活饮用水卫生标准”。供应饮用水的运输工具、储存容器及输水管道等设备都应当经常冲洗干净，保持清洁。\n第十九条 供应食品、饮用水的从业人员的卫生要求：\n(一)患有肠道传染病的患者或带菌者，以及活动性结核病、化脓性渗出性皮肤病患者，不得从事食品和饮用水供应工作；\n(二)从事食品、饮用水供应工作的人员，应当每年进行一次健康检查，新参加工作的人员，应当首先进行健康检查，经检查合格者，发给健康证；\n(三)从事食品、饮用水供应工作的人员，要养成良好卫生习惯，工作时要着装整洁，严格遵守卫生操作制度。","level":1},{"name":"第五章 国境口岸和交通工具的负责人的责任","text":"第二十条 国境口岸和交通工具的负责人在卫生工作方面的责任是：\n(一)应当经常抓好卫生工作，接受卫生监督人员的监督和检查，并为其开展工作提供方便条件；\n(二)应当模范地遵守本办法和其他卫生法令、条例和规定；\n(三)应当按照卫生监督人员的建议，对国境口岸和交通工具的不卫生状况，及时采取措施，加以改进；\n(四)在发现检疫传染病和监测传染病时，应当向国境卫生检疫机关或地方防疫部门报告，并立即采取防疫措施。","level":1},{"name":"第六章 卫生监督机关的职责","text":"第二十一条 国境口岸卫生检疫机关对国境口岸和交通工具进行卫生监督，其主要职责是：\n(一)监督和指导国境口岸有关部门和交通工具的负责人对病媒昆虫、啮齿动物进行防除；\n(二)对停留在国境口岸出入国境的交通工具上的食品、饮用水实施检验，并对运输、供应、贮存设施等系统进行卫生监督；\n(三)对国境口岸和交通工具上的所有非因意外伤害致死的尸体，实施检查、监督和卫生处理；\n(四)监督国境口岸有关部门和交通工具的负责人对粪便、垃圾、污水进行清除和无害化处理；\n(五)对与检疫传染病、监测传染病有流行病学意义的环境因素实施卫生监督；\n(六)监督国境口岸周围内采取防蚊措施的执行；\n(七)开展卫生宣传教育，普及卫生知识，提高国境口岸和交通工具上的人员遵守和执行本办法的自觉性。\n第二十二条 国境口岸卫生检疫机关设国境口岸卫生监督员1至5名，执行卫生监督任务，发给统一式样的执法证件。\n第二十三条 国境口岸卫生监督员持其证件，有权对国境口岸和交通工具的负责人，进行卫生监督、检查和技术指导；配合有关部门，对卫生工作情况不良或引起传染病传播的单位或个人，提出改进意见，协同有关部门采取必要措施，进行处理。","level":1},{"name":"第七章 奖励和惩罚","text":"第二十四条 国境口岸卫生检疫机关，对贯彻执行本办法和国家有关卫生法令、条例、规定，做出显著成绩的单位和个人，应当给予表扬和奖励。\n第二十五条 国境口岸卫生检疫机关，对违犯本办法和有关卫生法令、条例、规定的单位和个人，应当根据不同情况，给予警告、罚款，直至提请司法机关依法惩处。","level":1},{"name":"第八章 附则","text":"第二十六条 本办法自发布之日起施行。","level":1}]},{"id":"n0351","sections":[{"name":"","text":"中华人民共和国中医药条例\n(2003年4月2日国务院第3次常务会议通过 2003年4月7日中华人民共和国国务院令第374号公布 自2003年10月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了继承和发展中医药学，保障和促进中医药事业的发展，保护人体健康，制定本条例。\n第二条 在中华人民共和国境内从事中医医疗、预防、保健、康复服务和中医药教育、科研、对外交流以及中医药事业管理活动的单位或者个人，应当遵守本条例。\n中药的研制、生产、经营、使用和监督管理依照《中华人民共和国药品管理法》执行。\n第三条 国家保护、扶持、发展中医药事业，实行中西医并重的方针，鼓励中西医相互学习、相互补充、共同提高，推动中医、西医两种医学体系的有机结合，全面发展我国中医药事业。\n第四条 发展中医药事业应当遵循继承与创新相结合的原则，保持和发扬中医药特色和优势，积极利用现代科学技术，促进中医药理论和实践的发展，推进中医药现代化。\n第五条 县级以上各级人民政府应当将中医药事业纳入国民经济和社会发展计划，使中医药事业与经济、社会协调发展。\n县级以上地方人民政府在制定区域卫生规划时，应当根据本地区社会、经济发展状况和居民医疗需求，统筹安排中医医疗机构的设置和布局，完善城乡中医服务网络。\n第六条 国务院中医药管理部门负责全国中医药管理工作。国务院有关部门在各自的职责范围内负责与中医药有关的工作。\n县级以上地方人民政府负责中医药管理的部门负责本行政区域内的中医药管理工作。县级以上地方人民政府有关部门在各自的职责范围内负责与中医药有关的工作。\n第七条 对在继承和发展中医药事业中做出显著贡献和在边远地区从事中医药工作做出突出成绩的单位和个人，县级以上各级人民政府应当给予奖励。","level":1},{"name":"第二章 中医医疗机构与从业人员","text":"第八条 开办中医医疗机构，应当符合国务院卫生行政部门制定的中医医疗机构设置标准和当地区域卫生规划，并按照《医疗机构管理条例》的规定办理审批手续，取得医疗机构执业许可证后，方可从事中医医疗活动。\n第九条 中医医疗机构从事医疗服务活动，应当充分发挥中医药特色和优势，遵循中医药自身发展规律，运用传统理论和方法，结合现代科学技术手段，发挥中医药在防治疾病、保健、康复中的作用，为群众提供价格合理、质量优良的中医药服务。\n第十条 依法设立的社区卫生服务中心(站)、乡镇卫生院等城乡基层卫生服务机构，应当能够提供中医医疗服务。\n第十一条 中医从业人员，应当依照有关卫生管理的法律、行政法规、部门规章的规定通过资格考试，并经注册取得执业证书后，方可从事中医服务活动。\n以师承方式学习中医学的人员以及确有专长的人员，应当按照国务院卫生行政部门的规定，通过执业医师或者执业助理医师资格考核考试，并经注册取得医师执业证书后，方可从事中医医疗活动。\n第十二条 中医从业人员应当遵守相应的中医诊断治疗原则、医疗技术标准和技术操作规范。\n全科医师和乡村医生应当具备中医药基本知识以及运用中医诊疗知识、技术，处理常见病和多发病的基本技能。\n第十三条 发布中医医疗广告，医疗机构应当按照规定向所在地省、自治区、直辖市人民政府负责中医药管理的部门申请并报送有关材料。省、自治区、直辖市人民政府负责中医药管理的部门应当自收到有关材料之日起10个工作日内进行审查，并作出是否核发中医医疗广告批准文号的决定。对符合规定要求的，发给中医医疗广告批准文号。未取得中医医疗广告批准文号的，不得发布中医医疗广告。\n发布的中医医疗广告，其内容应当与审查批准发布的内容一致。","level":1},{"name":"第三章 中医药教育与科研","text":"第十四条 国家采取措施发展中医药教育事业。\n各类中医药教育机构应当加强中医药基础理论教学，重视中医药基础理论与中医药临床实践相结合，推进素质教育。\n第十五条 设立各类中医药教育机构，应当符合国家规定的设置标准，并建立符合国家规定标准的临床教学基地。\n中医药教育机构的设置标准，由国务院卫生行政部门会同国务院教育行政部门制定；中医药教育机构临床教学基地标准，由国务院卫生行政部门制定。\n第十六条 国家鼓励开展中医药专家学术经验和技术专长继承工作，培养高层次的中医临床人才和中药技术人才。\n第十七条 承担中医药专家学术经验和技术专长继承工作的指导老师应当具备下列条件：\n(一)具有较高学术水平和丰富的实践经验、技术专长和良好的职业品德；\n(二)从事中医药专业工作30年以上并担任高级专业技术职务10年以上。\n第十八条 中医药专家学术经验和技术专长继承工作的继承人应当具备下列条件：\n(一)具有大学本科以上学历和良好的职业品德；\n(二)受聘于医疗卫生机构或者医学教育、科研机构从事中医药工作，并担任中级以上专业技术职务。\n第十九条 中医药专家学术经验和技术专长继承工作的指导老师以及继承人的管理办法，由国务院中医药管理部门会同有关部门制定。\n第二十条 省、自治区、直辖市人民政府负责中医药管理的部门应当依据国家有关规定，完善本地区中医药人员继续教育制度，制定中医药人员培训规划。\n县级以上地方人民政府负责中医药管理的部门应当按照中医药人员培训规划的要求，对城乡基层卫生服务人员进行中医药基本知识和基本技能的培训。\n医疗机构应当为中医药技术人员接受继续教育创造条件。\n第二十一条 国家发展中医药科学技术，将其纳入科学技术发展规划，加强重点中医药科研机构建设。\n县级以上地方人民政府应当充分利用中医药资源，重视中医药科学研究和技术开发，采取措施开发、推广、应用中医药技术成果，促进中医药科学技术发展。\n第二十二条 中医药科学研究应当注重运用传统方法和现代方法开展中医药基础理论研究和临床研究，运用中医药理论和现代科学技术开展对常见病、多发病和疑难病的防治研究。\n中医药科研机构、高等院校、医疗机构应当加强中医药科研的协作攻关和中医药科技成果的推广应用，培养中医药学科带头人和中青年技术骨干。\n第二十三条 捐献对中医药科学技术发展有重大意义的中医诊疗方法和中医药文献、秘方、验方的，参照《国家科学技术奖励条例》的规定给予奖励。\n第二十四条 国家支持中医药的对外交流与合作，推进中医药的国际传播。\n重大中医药科研成果的推广、转让、对外交流，中外合作研究中医药技术，应当经省级以上人民政府负责中医药管理的部门批准，防止重大中医药资源流失。\n属于国家科学技术秘密的中医药科研成果，确需转让、对外交流的，应当符合有关保守国家秘密的法律、行政法规和部门规章的规定。","level":1},{"name":"第四章 保障措施","text":"第二十五条 县级以上地方人民政府应当根据中医药事业发展的需要以及本地区国民经济和社会发展状况，逐步增加对中医药事业的投入，扶持中医药事业的发展。\n任何单位和个人不得将中医药事业经费挪作他用。\n国家鼓励境内外组织和个人通过捐资、投资等方式扶持中医药事业发展。\n第二十六条 非营利性中医医疗机构，依照国家有关规定享受财政补贴、税收减免等优惠政策。\n第二十七条 县级以上地方人民政府劳动保障行政部门确定的城镇职工基本医疗保险定点医疗机构，应当包括符合条件的中医医疗机构。\n获得定点资格的中医医疗机构，应当按照规定向参保人员提供基本医疗服务。\n第二十八条 县级以上各级人民政府应当采取措施加强对中医药文献的收集、整理、研究和保护工作。\n有关单位和中医医疗机构应当加强重要中医药文献资料的管理、保护和利用。\n第二十九条 国家保护野生中药材资源，扶持濒危动植物中药材人工代用品的研究和开发利用。\n县级以上地方人民政府应当加强中药材的合理开发和利用，鼓励建立中药材种植、培育基地，促进短缺中药材的开发、生产。\n第三十条 与中医药有关的评审或者鉴定活动，应当体现中医药特色，遵循中医药自身的发展规律。\n中医药专业技术职务任职资格的评审，中医医疗、教育、科研机构的评审、评估，中医药科研课题的立项和成果鉴定，应当成立专门的中医药评审、鉴定组织或者由中医药专家参加评审、鉴定。","level":1},{"name":"第五章 法律责任","text":"第三十一条 负责中医药管理的部门的工作人员在中医药管理工作中违反本条例的规定，利用职务上的便利收受他人财物或者获取其他利益，滥用职权，玩忽职守，或者发现违法行为不予查处，造成严重后果，构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，依法给予降级或者撤职的行政处分。\n第三十二条 中医医疗机构违反本条例的规定，有下列情形之一的，由县级以上地方人民政府负责中医药管理的部门责令限期改正；逾期不改正的，责令停业整顿，直至由原审批机关吊销其医疗机构执业许可证、取消其城镇职工基本医疗保险定点医疗机构资格，并对负有责任的主管人员和其他直接责任人员依法给予纪律处分：\n(一) 不符合中医医疗机构设置标准的；\n(二) 获得城镇职工基本医疗保险定点医疗机构资格，未按照规定向参保人员提供基本医疗服务的。\n第三十三条 未经批准擅自开办中医医疗机构或者未按照规定通过执业医师或者执业助理医师资格考试取得执业许可，从事中医医疗活动的，依照《中华人民共和国执业医师法》和《医疗机构管理条例》的有关规定给予处罚。\n第三十四条 中医药教育机构违反本条例的规定，有下列情形之一的，由县级以上地方人民政府负责中医药管理的部门责令限期改正；逾期不改正的，由原审批机关予以撤销：\n(一)不符合规定的设置标准的；\n(二)没有建立符合规定标准的临床教学基地的。\n第三十五条 违反本条例规定，造成重大中医药资源流失和国家科学技术秘密泄露，情节严重，构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，由县级以上地方人民政府负责中医药管理的部门责令改正，对负有责任的主管人员和其他直接责任人员依法给予纪律处分。\n第三十六条 违反本条例规定，损毁或者破坏中医药文献的，由县级以上地方人民政府负责中医药管理的部门责令改正，对负有责任的主管人员和其他直接责任人员依法给予纪律处分；损毁或者破坏属于国家保护文物的中医药文献，情节严重，构成犯罪的，依法追究刑事责任。\n第三十七条 篡改经批准的中医医疗广告内容的，由原审批部门撤销广告批准文号，1年内不受理该中医医疗机构的广告审批申请。\n负责中医药管理的部门撤销中医医疗广告批准文号后，应当自作出行政处理决定之日起5个工作日内通知广告监督管理机关。广告监督管理机关应当自收到负责中医药管理的部门通知之日起15个工作日内，依照《中华人民共和国广告法》的有关规定查处。","level":1},{"name":"第六章 附则","text":"第三十八条 本条例所称中医医疗机构，是指依法取得医疗机构执业许可证的中医、中西医结合的医院、门诊部和诊所。\n民族医药的管理参照本条例执行。\n第三十九条 本条例自2003年10月1日起施行。","level":1}]},{"id":"n0352","sections":[{"name":"","text":"中华人民共和国核出口管制条例\n(1997年9月10日中华人民共和国国务院令第230号发布 根据2006年11月9日《国务院关于修改〈中华人民共和国核出口管制条例〉的决定》修订)\n第一条 为了加强对核出口的管制，防止核武器扩散，防范核恐怖主义行为，维护国家安全和社会公共利益，促进和平利用核能的国际合作，制定本条例。\n第二条 本条例所称核出口，是指《核出口管制清单》(以下简称《管制清单》)所列的核材料、核设备和反应堆用非核材料等物项及其相关技术的贸易性出口及对外赠送、展览、科技合作和援助等方式进行的转移。\n第三条 国家对核出口实行严格管制，严格履行所承担的不扩散核武器的国际义务。\n国家严格限制铀浓缩设施、设备，辐照燃料后处理设施、设备，重水生产设施、设备等物项及其相关技术等核扩散敏感物项，以及可以用于核武器或者其他核爆炸装置的材料的出口。\n第四条 核出口应当遵守国家有关法律、行政法规的规定，不得损害国家安全或者社会公共利益。\n第五条 核出口审查、许可，应当遵循下列准则：\n(一)接受方政府保证不将中国供应的核材料、核设备或者反应堆用非核材料以及通过其使用而生产的特种可裂变材料用于任何核爆炸目的。\n(二)接受方政府保证对中国供应的核材料以及通过其使用而生产的特种可裂变材料采取适当的实物保护措施。\n(三)接受方政府同国际原子能机构订有有效的全面保障协定。本项规定不适用于同国际原子能机构订有自愿保障协定的国家。\n(四)接受方保证，未经中国国家原子能机构事先书面同意，不向第三方再转让中国所供应的核材料、核设备或者反应堆用非核材料及其相关技术；经事先同意进行再转让的，接受再转让的第三方应当承担相当于由中国直接供应所承担的义务。\n(五)接受方政府保证，未经中国政府同意，不得利用中国供应的铀浓缩设施、技术或者以此技术为基础的任何设施生产富集度高于20%的浓缩铀。\n第六条 核出口由国务院指定的单位专营，任何其他单位或者个人不得经营。\n第七条 出口《管制清单》所列物项及其相关技术，应当向国家原子能机构提出申请，填写核出口申请表并提交下列文件：\n(一)申请人从事核出口的专营资格证明；\n(二)申请人的法定代表人、主要经营管理人以及经办人的身份证明；\n(三)合同或者协议的副本；\n(四)核材料或者反应堆用非核材料分析报告单；\n(五)最终用户证明；\n(六)接受方依照本条例第五条规定提供的保证证明；\n(七)审查机关要求提交的其他文件。\n第八条 申请人应当如实填写核出口申请表。\n核出口申请表由国家原子能机构统一印制。\n第九条 核出口申请表上填报的事项发生变化的，申请人应当及时提出修正，或者重新提出出口申请。\n申请人中止核出口时，应当及时撤回核出口申请。\n第十条 国家原子能机构应当自收到核出口申请表及本条例第七条所列文件之日起15个工作日内，提出审查意见，并通知申请人；经审查同意的，应当区分情况，依照下列规定处理：\n(一)出口核材料的，转送国防科学技术工业委员会复审或者国防科学技术工业委员会会同有关部门复审；\n(二)出口核设备或者反应堆用非核材料及其相关技术的，转送商务部复审或者商务部会同国防科学技术工业委员会等有关部门复审。\n国防科学技术工业委员会、商务部应当自收到国家原子能机构转送的核出口申请表和本条例第七条所列文件及审查意见之日起15个工作日内提出复审意见，并通知申请人。\n国家原子能机构、国防科学技术工业委员会、商务部因特殊情况，需要延长审查或者复审期限的，可以延长15个工作日，但是应当通知申请人。\n第十一条 对国家安全、社会公共利益或者外交政策有重要影响的核出口，国家原子能机构、国防科学技术工业委员会、商务部审查或者复审时，应当会商外交部等有关部门；必要时，应当报国务院审批。\n报国务院审批的，不受本条例第十条规定时限的限制。\n第十二条 核出口申请依照本条例规定经复审或者审批同意的，由商务部颁发核出口许可证。\n第十三条 核出口许可证持有人改变原申请出口的物项及其相关技术的，应当交回原许可证，并依照本条例的规定，重新申请、领取核出口许可证。\n第十四条 商务部颁发核出口许可证后，应当书面通知国家原子能机构。\n第十五条 核出口专营单位进行核出口时，应当向海关出具核出口许可证，依照海关法的规定办理海关手续，并接受海关监管。\n第十六条 海关可对出口经营者出口的物项及其技术是否需要办理核出口证件提出质疑，并可要求其向商务部申请办理是否属于核出口管制范围的证明文件；属于核出口管制范围的，应当依照本条例的规定申请取得核出口许可证。\n第十七条 接受方或者其政府违反其依照本条例第五条规定作出的保证，或者出现核扩散、核恐怖主义危险时，国防科学技术工业委员会、商务部会同外交部等有关部门，有权作出中止出口有关物项或者相关技术的决定，并书面通知海关执行。\n第十八条 违反本条例规定，出口核材料、核设备、反应堆用非核材料的，依照海关法的规定处罚。\n违反本条例规定，出口《管制清单》所列有关技术的，由商务部给予警告，处违法经营额1倍以上5倍以下罚款；违法经营额不足5万元的，处5万元以上25万元以下罚款；有违法所得的，没收违法所得；构成犯罪的，依法追究刑事责任。\n第十九条 伪造、变造、买卖核出口许可证，或者以欺骗等不正当手段获取核出口许可证的，依照有关法律、行政法规的规定处罚；构成犯罪的，依法追究刑事责任。\n第二十条 国家核出口管制工作人员玩忽职守、徇私舞弊或者滥用职权，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。\n第二十一条 国家原子能机构会同国防科学技术工业委员会、商务部、外交部、海关总署等有关部门根据实际情况，可以对《管制清单》进行调整，并予以公布。\n第二十二条 中华人民共和国缔结或者参加的国际条约同本条例有不同规定的，适用国际条约的规定；但是，中华人民共和国声明保留的条款除外。\n第二十三条 《管制清单》所列物项及其相关技术从保税仓库、保税区、出口加工区等海关特殊监管区域、保税场所出口，适用本条例的规定。\n《管制清单》所列物项及其相关技术的过境、转运、通运，参照本条例的规定执行。\n第二十四条 本条例自发布之日起施行。","level":0}]},{"id":"n0353","sections":[{"name":"","text":"外国人来华登山管理办法\n(1991年7月31日国务院批准 1991年8月29日国家体育运动委员会令第16号发布 自发布之日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了加强对外国人在中国境内登山的管理，有组织地进行国际登山交流，促进我国登山事业发展，制定本办法。\n第二条 外国人在中国境内攀登下列对外开放的山峰以及附带在山峰区域内进行科学考察、测绘活动，适用本办法：\n(一)西藏自治区海拔五千米以上的山峰；\n(二)其他省、自治区海拔三千五百米以上的山峰。\n第三条 外国人在中国境内进行登山活动，应当遵守中国的法律；外国人的正当权益，受中国法律保护。\n第四条 对外国人在中国境内登山的管理，实行统一领导，分级负责的原则。\n第五条 对外开放山峰由中华人民共和国国家体育运动委员会(以下简称国家体委)和公安部公布。","level":1},{"name":"第二章 来华登山手续","text":"第六条 外国人来华登山，可以自行组成团队，也可以由外国团队和中国团队组成联合团队。\n第七条 外国人来华登山，应当向国家体委提出书面申请。\n外国人组成外国团队来华登山的，由外国团队提出申请，也可以委托我国省、自治区登山协会代理申请事宜。\n外国团队和中国团队组成中外联合团队登山的，由中国团队提出申请。\n第八条 国家体委收到外国团队或者中外联合团队的登山申请后，应当在六十日内作出是否批准的决定，并以书面形式通知外国团队或者中外联合团队、代理申请事宜的省、自治区登山协会和登山活动所在省、自治区体委。\n第九条 外国团队接到国家体委批准的登山通知后，应当按照通知要求缴纳注册费，并与通知中指定的单位签订登山议定书。\n与外国团队签订登山议定书的单位(以下简称中方签约单位)应当及时将议定书副本报送国家体委备案。\n第十条 议定书报送国家体委备案后，不得任意变更。如需要变更，应当经签订议定书的中外双方协商确认；如果变更攀登的季节、路线或者山峰，应当重新报国家体委审批。\n第十一条 外国团队应当在入境的一个月前，将在中国境内登山的经费按预算全额汇寄中方签约单位，并按照国家体委的通知在中国驻外使(领)馆办理签证。","level":1},{"name":"第三章 登山活动","text":"第十二条 外国团队在登山前应当为随队的中国公民办理有关保险事项，并根据国家体委的要求落实保护山区自然环境的各项措施。\n第十三条 外国人登山，应当遵守下列规定：\n(一)按照国家体委批准的山峰和路线进行攀登，不得攀登其他山峰，不得越过批准的路线；外国登山团队之间不得互相转让攀登的山峰和路线；\n(二)外国登山团队不得吸收本团队以外的队员；\n(三)如要求展现外国团队所在国国旗，应当经中国国家体委同意，并同时展现规格相当的中国国旗；\n(四)使用山峰的名称和高度，应当以中国政府有关部门公布的为准；\n(五)保持登山路线和营区的环境卫生，不得自行在登山活动区域安放纪念品和其他物品；\n(六)将登山活动的结果和登山过程中的意外情况及时报告国家体委和中方签约单位。\n第十四条 外国人在登山活动结束后，应当以团队为单位写出总结报告书。\n登山活动总结报告书以及在登山期间摄录的音像资料，应当无偿向国家体委和登山活动所在省、自治区体委提供。\n第十五条 外国人在我国境内登顶成功，由国家体委确认后，发给其登顶证明书。\n第十六条 外国人在我国境内登山期间，必须有我国联络人员陪同。联络人员由中方签约单位指定，其职责是：\n(一)协助并监督外国人执行我国的有关规定；\n(二)协助解决外国人在登山活动中的有关问题；\n(三)向中方签约单位报告有关情况；\n(四)调解外国人与中方服务人员的纠纷。\n第十七条 外国人登山，需要我国公民提供服务，由我国联络人员办理。\n中国公民向外国人提供服务，可以收取服务费用。服务费用的项目和标准，由国家体委公布。\n第十八条 外国团队应当为随队的中国公民提供医疗、急救以及必要的宿营、炊事用具。\n未经我国联络人员同意，外国团队不得自行解雇随队的中国公民或者停发津贴。\n中外联合团队向随队的中国公民提供医疗、急救和宿营、炊事用具的办法，由组成中外联合团队的各方协商。","level":1},{"name":"第四章 登山附带科学考察和测绘","text":"第十九条 登山附带科学考察和测绘的，应当在办理登山申请的同时，向国家体委申报科学考察和测绘计划，由国家体委分别转国家科学技术委员会或者国家测绘局审批。\n科学考察和测绘计划未经批准，外国登山人员不得对所经地区的生物、岩石、矿物、冰雪、水样和土样进行系统观测，不得采集标本、样品、化石，不得进行测绘活动。\n第二十条 外国团队、中外联合团队登山附带科学考察的，应当通过中方签约单位向国家科学技术委员会提供下列样品和资料：\n(一)采集的标本、样品和化石的清单；\n(二)发现的动植物新种或者特殊动植物的类群；\n(三)采集的动植物新种正模式标本、特缺动植物类群的标本；\n(四)标本、样品、化石的室内分析结果；\n(五)登山附带科学考察的音像资料复制本。\n外国团队、中外联合团体登山附带测绘的，应当通过中方签约单位向国家测绘局提供测绘成果的副本或复制件。","level":1},{"name":"第五章 登山物资的入境和出境","text":"第二十一条 外国人携带登山所需物资入境，按“特准进口物品”和“暂时进口物品”分别申报。经海关核准后，办理税收、担保手续。\n第二十二条 登山物资中合理数量的专用食品、急救药品、防寒衣物、燃料等消耗性物品，可以特准免税入境；超过合理数量的，应当纳税。\n国家有关部门允许的通讯、摄影、录像、测绘器材和专用运输工具可以暂时免税入境。登山活动结束，上述物资应当复运出境。如因特殊原因无法复运出境的，应当通过国家体委依照国家有关规定办理手续。\n第二十三条 外国团队、中外联合团队登山时采集的标本、样品、化石以及制作的音像资料，经有关部门检验许可后，方可携带出境。","level":1},{"name":"第六章 罚则","text":"第二十四条 外国人来华登山，违反本办法第十二条、第十三条、第十八条、第十九条、第二十条规定或者未经国家体委批准擅自登山的，国家体委或者省、自治区体委视情节轻重，可以分别给予警告、五千元至五万元的罚款以及停止登山活动等处罚。\n违反本办法第十九条、第二十条规定的，国家体委或者省、自治区体委，还可以单处或者并处没收采集的标本、样品、化石和资料的处罚。\n第二十五条 当事人对行政处罚决定不服的，可以依照中国有关法律的规定先申请行政复议。当事人对复议决定不服的，可以依照中国有关法律的规定提起行政诉讼。当事人在规定的期限内不申请复议和不提起行政诉讼，逾期又不履行处罚决定的，作出处罚决定的行政机关可以申请人民法院强制执行。","level":1},{"name":"第七章 附则","text":"第二十六条 台湾、香港、澳门同胞回大陆登山，参照执行本办法的规定。\n第二十七条 本办法由国家体育运动委员会解释。\n第二十八条 本办法自发布之日起施行。","level":1}]},{"id":"n0354","sections":[{"name":"","text":"工伤保险条例\n(2003年4月27日中华人民共和国国务院令第375号公布 根据2010年12月20日《国务院关于修改〈工伤保险条例〉的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了保障因工作遭受事故伤害或者患职业病的职工获得医疗救治和经济补偿，促进工伤预防和职业康复，分散用人单位的工伤风险，制定本条例。\n第二条 中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织和有雇工的个体工商户(以下称用人单位)应当依照本条例规定参加工伤保险，为本单位全部职工或者雇工(以下称职工)缴纳工伤保险费。\n中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织的职工和个体工商户的雇工，均有依照本条例的规定享受工伤保险待遇的权利。\n第三条 工伤保险费的征缴按照《社会保险费征缴暂行条例》关于基本养老保险费、基本医疗保险费、失业保险费的征缴规定执行。\n第四条 用人单位应当将参加工伤保险的有关情况在本单位内公示。\n用人单位和职工应当遵守有关安全生产和职业病防治的法律法规，执行安全卫生规程和标准，预防工伤事故发生，避免和减少职业病危害。\n职工发生工伤时，用人单位应当采取措施使工伤职工得到及时救治。\n第五条 国务院社会保险行政部门负责全国的工伤保险工作。\n县级以上地方各级人民政府社会保险行政部门负责本行政区域内的工伤保险工作。\n社会保险行政部门按照国务院有关规定设立的社会保险经办机构(以下称经办机构)具体承办工伤保险事务。\n第六条 社会保险行政部门等部门制定工伤保险的政策、标准，应当征求工会组织、用人单位代表的意见。","level":1},{"name":"第二章 工伤保险基金","text":"第七条 工伤保险基金由用人单位缴纳的工伤保险费、工伤保险基金的利息和依法纳入工伤保险基金的其他资金构成。\n第八条 工伤保险费根据以支定收、收支平衡的原则，确定费率。\n国家根据不同行业的工伤风险程度确定行业的差别费率，并根据工伤保险费使用、工伤发生率等情况在每个行业内确定若干费率档次。行业差别费率及行业内费率档次由国务院社会保险行政部门制定，报国务院批准后公布施行。\n统筹地区经办机构根据用人单位工伤保险费使用、工伤发生率等情况，适用所属行业内相应的费率档次确定单位缴费费率。\n第九条 国务院社会保险行政部门应当定期了解全国各统筹地区工伤保险基金收支情况，及时提出调整行业差别费率及行业内费率档次的方案，报国务院批准后公布施行。\n第十条 用人单位应当按时缴纳工伤保险费。职工个人不缴纳工伤保险费。\n用人单位缴纳工伤保险费的数额为本单位职工工资总额乘以单位缴费费率之积。\n对难以按照工资总额缴纳工伤保险费的行业，其缴纳工伤保险费的具体方式，由国务院社会保险行政部门规定。\n第十一条 工伤保险基金逐步实行省级统筹。\n跨地区、生产流动性较大的行业，可以采取相对集中的方式异地参加统筹地区的工伤保险。具体办法由国务院社会保险行政部门会同有关行业的主管部门制定。\n第十二条 工伤保险基金存入社会保障基金财政专户，用于本条例规定的工伤保险待遇，劳动能力鉴定，工伤预防的宣传、培训等费用，以及法律、法规规定的用于工伤保险的其他费用的支付。\n工伤预防费用的提取比例、使用和管理的具体办法，由国务院社会保险行政部门会同国务院财政、卫生行政、安全生产监督管理等部门规定。\n任何单位或者个人不得将工伤保险基金用于投资运营、兴建或者改建办公场所、发放奖金，或者挪作其他用途。\n第十三条 工伤保险基金应当留有一定比例的储备金，用于统筹地区重大事故的工伤保险待遇支付；储备金不足支付的，由统筹地区的人民政府垫付。储备金占基金总额的具体比例和储备金的使用办法，由省、自治区、直辖市人民政府规定。","level":1},{"name":"第三章 工伤认定","text":"第十四条 职工有下列情形之一的，应当认定为工伤：\n(一)在工作时间和工作场所内，因工作原因受到事故伤害的；\n(二)工作时间前后在工作场所内，从事与工作有关的预备性或者收尾性工作受到事故伤害的；\n(三)在工作时间和工作场所内，因履行工作职责受到暴力等意外伤害的；\n(四)患职业病的；\n(五)因工外出期间，由于工作原因受到伤害或者发生事故下落不明的；\n(六)在上下班途中，受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的；\n(七)法律、行政法规规定应当认定为工伤的其他情形。\n第十五条 职工有下列情形之一的，视同工伤：\n(一)在工作时间和工作岗位，突发疾病死亡或者在48小时之内经抢救无效死亡的；\n(二)在抢险救灾等维护国家利益、公共利益活动中受到伤害的；\n(三)职工原在军队服役，因战、因公负伤致残，已取得革命伤残军人证，到用人单位后旧伤复发的。\n职工有前款第(一)项、第(二)项情形的，按照本条例的有关规定享受工伤保险待遇；职工有前款第(三)项情形的，按照本条例的有关规定享受除一次性伤残补助金以外的工伤保险待遇。\n第十六条 职工符合本条例第十四条、第十五条的规定，但是有下列情形之一的，不得认定为工伤或者视同工伤：\n(一)故意犯罪的；\n(二)醉酒或者吸毒的；\n(三)自残或者自杀的。\n第十七条 职工发生事故伤害或者按照职业病防治法规定被诊断、鉴定为职业病，所在单位应当自事故伤害发生之日或者被诊断、鉴定为职业病之日起30日内，向统筹地区社会保险行政部门提出工伤认定申请。遇有特殊情况，经报社会保险行政部门同意，申请时限可以适当延长。\n用人单位未按前款规定提出工伤认定申请的，工伤职工或者其近亲属、工会组织在事故伤害发生之日或者被诊断、鉴定为职业病之日起1年内，可以直接向用人单位所在地统筹地区社会保险行政部门提出工伤认定申请。\n按照本条第一款规定应当由省级社会保险行政部门进行工伤认定的事项，根据属地原则由用人单位所在地的设区的市级社会保险行政部门办理。\n用人单位未在本条第一款规定的时限内提交工伤认定申请，在此期间发生符合本条例规定的工伤待遇等有关费用由该用人单位负担。\n第十八条 提出工伤认定申请应当提交下列材料：\n(一)工伤认定申请表；\n(二)与用人单位存在劳动关系(包括事实劳动关系)的证明材料；\n(三)医疗诊断证明或者职业病诊断证明书(或者职业病诊断鉴定书)。\n工伤认定申请表应当包括事故发生的时间、地点、原因以及职工伤害程度等基本情况。\n工伤认定申请人提供材料不完整的，社会保险行政部门应当一次性书面告知工伤认定申请人需要补正的全部材料。申请人按照书面告知要求补正材料后，社会保险行政部门应当受理。\n第十九条 社会保险行政部门受理工伤认定申请后，根据审核需要可以对事故伤害进行调查核实，用人单位、职工、工会组织、医疗机构以及有关部门应当予以协助。职业病诊断和诊断争议的鉴定，依照职业病防治法的有关规定执行。对依法取得职业病诊断证明书或者职业病诊断鉴定书的，社会保险行政部门不再进行调查核实。\n职工或者其近亲属认为是工伤，用人单位不认为是工伤的，由用人单位承担举证责任。\n第二十条 社会保险行政部门应当自受理工伤认定申请之日起60日内作出工伤认定的决定，并书面通知申请工伤认定的职工或者其近亲属和该职工所在单位。\n社会保险行政部门对受理的事实清楚、权利义务明确的工伤认定申请，应当在15日内作出工伤认定的决定。\n作出工伤认定决定需要以司法机关或者有关行政主管部门的结论为依据的，在司法机关或者有关行政主管部门尚未作出结论期间，作出工伤认定决定的时限中止。\n社会保险行政部门工作人员与工伤认定申请人有利害关系的，应当回避。","level":1},{"name":"第四章 劳动能力鉴定","text":"第二十一条 职工发生工伤，经治疗伤情相对稳定后存在残疾、影响劳动能力的，应当进行劳动能力鉴定。\n第二十二条 劳动能力鉴定是指劳动功能障碍程度和生活自理障碍程度的等级鉴定。\n劳动功能障碍分为十个伤残等级，最重的为一级，最轻的为十级。\n生活自理障碍分为三个等级：生活完全不能自理、生活大部分不能自理和生活部分不能自理。\n劳动能力鉴定标准由国务院社会保险行政部门会同国务院卫生行政部门等部门制定。\n第二十三条 劳动能力鉴定由用人单位、工伤职工或者其近亲属向设区的市级劳动能力鉴定委员会提出申请，并提供工伤认定决定和职工工伤医疗的有关资料。\n第二十四条 省、自治区、直辖市劳动能力鉴定委员会和设区的市级劳动能力鉴定委员会分别由省、自治区、直辖市和设区的市级社会保险行政部门、卫生行政部门、工会组织、经办机构代表以及用人单位代表组成。\n劳动能力鉴定委员会建立医疗卫生专家库。列入专家库的医疗卫生专业技术人员应当具备下列条件：\n(一)具有医疗卫生高级专业技术职务任职资格；\n(二)掌握劳动能力鉴定的相关知识；\n(三)具有良好的职业品德。\n第二十五条 设区的市级劳动能力鉴定委员会收到劳动能力鉴定申请后，应当从其建立的医疗卫生专家库中随机抽取3名或者5名相关专家组成专家组，由专家组提出鉴定意见。设区的市级劳动能力鉴定委员会根据专家组的鉴定意见作出工伤职工劳动能力鉴定结论；必要时，可以委托具备资格的医疗机构协助进行有关的诊断。\n设区的市级劳动能力鉴定委员会应当自收到劳动能力鉴定申请之日起60日内作出劳动能力鉴定结论，必要时，作出劳动能力鉴定结论的期限可以延长30日。劳动能力鉴定结论应当及时送达申请鉴定的单位和个人。\n第二十六条 申请鉴定的单位或者个人对设区的市级劳动能力鉴定委员会作出的鉴定结论不服的，可以在收到该鉴定结论之日起15日内向省、自治区、直辖市劳动能力鉴定委员会提出再次鉴定申请。省、自治区、直辖市劳动能力鉴定委员会作出的劳动能力鉴定结论为最终结论。\n第二十七条 劳动能力鉴定工作应当客观、公正。劳动能力鉴定委员会组成人员或者参加鉴定的专家与当事人有利害关系的，应当回避。\n第二十八条 自劳动能力鉴定结论作出之日起1年后，工伤职工或者其近亲属、所在单位或者经办机构认为伤残情况发生变化的，可以申请劳动能力复查鉴定。\n第二十九条 劳动能力鉴定委员会依照本条例第二十六条和第二十八条的规定进行再次鉴定和复查鉴定的期限，依照本条例第二十五条第二款的规定执行。","level":1},{"name":"第五章 工伤保险待遇","text":"第三十条 职工因工作遭受事故伤害或者患职业病进行治疗，享受工伤医疗待遇。\n职工治疗工伤应当在签订服务协议的医疗机构就医，情况紧急时可以先到就近的医疗机构急救。\n治疗工伤所需费用符合工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准的，从工伤保险基金支付。工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准，由国务院社会保险行政部门会同国务院卫生行政部门、食品药品监督管理部门等部门规定。\n职工住院治疗工伤的伙食补助费，以及经医疗机构出具证明，报经办机构同意，工伤职工到统筹地区以外就医所需的交通、食宿费用从工伤保险基金支付，基金支付的具体标准由统筹地区人民政府规定。\n工伤职工治疗非工伤引发的疾病，不享受工伤医疗待遇，按照基本医疗保险办法处理。\n工伤职工到签订服务协议的医疗机构进行工伤康复的费用，符合规定的，从工伤保险基金支付。\n第三十一条 社会保险行政部门作出认定为工伤的决定后发生行政复议、行政诉讼的，行政复议和行政诉讼期间不停止支付工伤职工治疗工伤的医疗费用。\n第三十二条 工伤职工因日常生活或者就业需要，经劳动能力鉴定委员会确认，可以安装假肢、矫形器、假眼、假牙和配置轮椅等辅助器具，所需费用按照国家规定的标准从工伤保险基金支付。\n第三十三条 职工因工作遭受事故伤害或者患职业病需要暂停工作接受工伤医疗的，在停工留薪期内，原工资福利待遇不变，由所在单位按月支付。\n停工留薪期一般不超过12个月。伤情严重或者情况特殊，经设区的市级劳动能力鉴定委员会确认，可以适当延长，但延长不得超过12个月。工伤职工评定伤残等级后，停发原待遇，按照本章的有关规定享受伤残待遇。工伤职工在停工留薪期满后仍需治疗的，继续享受工伤医疗待遇。\n生活不能自理的工伤职工在停工留薪期需要护理的，由所在单位负责。\n第三十四条 工伤职工已经评定伤残等级并经劳动能力鉴定委员会确认需要生活护理的，从工伤保险基金按月支付生活护理费。\n生活护理费按照生活完全不能自理、生活大部分不能自理或者生活部分不能自理3个不同等级支付，其标准分别为统筹地区上年度职工月平均工资的50%、40%或者30%。\n第三十五条 职工因工致残被鉴定为一级至四级伤残的，保留劳动关系，退出工作岗位，享受以下待遇：\n(一)从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：一级伤残为27个月的本人工资，二级伤残为25个月的本人工资，三级伤残为23个月的本人工资，四级伤残为21个月的本人工资；\n(二)从工伤保险基金按月支付伤残津贴，标准为：一级伤残为本人工资的90%，二级伤残为本人工资的85%，三级伤残为本人工资的80%，四级伤残为本人工资的75%。伤残津贴实际金额低于当地最低工资标准的，由工伤保险基金补足差额；\n(三)工伤职工达到退休年龄并办理退休手续后，停发伤残津贴，按照国家有关规定享受基本养老保险待遇。基本养老保险待遇低于伤残津贴的，由工伤保险基金补足差额。\n职工因工致残被鉴定为一级至四级伤残的，由用人单位和职工个人以伤残津贴为基数，缴纳基本医疗保险费。\n第三十六条 职工因工致残被鉴定为五级、六级伤残的，享受以下待遇：\n(一)从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：五级伤残为18个月的本人工资，六级伤残为16个月的本人工资；\n(二)保留与用人单位的劳动关系，由用人单位安排适当工作。难以安排工作的，由用人单位按月发给伤残津贴，标准为：五级伤残为本人工资的70%，六级伤残为本人工资的60%，并由用人单位按照规定为其缴纳应缴纳的各项社会保险费。伤残津贴实际金额低于当地最低工资标准的，由用人单位补足差额。\n经工伤职工本人提出，该职工可以与用人单位解除或者终止劳动关系，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。一次性工伤医疗补助金和一次性伤残就业补助金的具体标准由省、自治区、直辖市人民政府规定。\n第三十七条 职工因工致残被鉴定为七级至十级伤残的，享受以下待遇：\n(一)从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：七级伤残为13个月的本人工资，八级伤残为11个月的本人工资，九级伤残为9个月的本人工资，十级伤残为7个月的本人工资；\n(二)劳动、聘用合同期满终止，或者职工本人提出解除劳动、聘用合同的，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。一次性工伤医疗补助金和一次性伤残就业补助金的具体标准由省、自治区、直辖市人民政府规定。\n第三十八条 工伤职工工伤复发，确认需要治疗的，享受本条例第三十条、第三十二条和第三十三条规定的工伤待遇。\n第三十九条 职工因工死亡，其近亲属按照下列规定从工伤保险基金领取丧葬补助金、供养亲属抚恤金和一次性工亡补助金：\n(一)丧葬补助金为6个月的统筹地区上年度职工月平均工资；\n(二)供养亲属抚恤金按照职工本人工资的一定比例发给由因工死亡职工生前提供主要生活来源、无劳动能力的亲属。标准为：配偶每月40%，其他亲属每人每月30%，孤寡老人或者孤儿每人每月在上述标准的基础上增加10%。核定的各供养亲属的抚恤金之和不应高于因工死亡职工生前的工资。供养亲属的具体范围由国务院社会保险行政部门规定；\n(三)一次性工亡补助金标准为上一年度全国城镇居民人均可支配收入的20倍。\n伤残职工在停工留薪期内因工伤导致死亡的，其近亲属享受本条第一款规定的待遇。\n一级至四级伤残职工在停工留薪期满后死亡的，其近亲属可以享受本条第一款第(一)项、第(二)项规定的待遇。\n第四十条 伤残津贴、供养亲属抚恤金、生活护理费由统筹地区社会保险行政部门根据职工平均工资和生活费用变化等情况适时调整。调整办法由省、自治区、直辖市人民政府规定。\n第四十一条 职工因工外出期间发生事故或者在抢险救灾中下落不明的，从事故发生当月起3个月内照发工资，从第4个月起停发工资，由工伤保险基金向其供养亲属按月支付供养亲属抚恤金。生活有困难的，可以预支一次性工亡补助金的50%。职工被人民法院宣告死亡的，按照本条例第三十九条职工因工死亡的规定处理。\n第四十二条 工伤职工有下列情形之一的，停止享受工伤保险待遇：\n(一)丧失享受待遇条件的；\n(二)拒不接受劳动能力鉴定的；\n(三)拒绝治疗的。\n第四十三条 用人单位分立、合并、转让的，承继单位应当承担原用人单位的工伤保险责任；原用人单位已经参加工伤保险的，承继单位应当到当地经办机构办理工伤保险变更登记。\n用人单位实行承包经营的，工伤保险责任由职工劳动关系所在单位承担。\n职工被借调期间受到工伤事故伤害的，由原用人单位承担工伤保险责任，但原用人单位与借调单位可以约定补偿办法。\n企业破产的，在破产清算时依法拨付应当由单位支付的工伤保险待遇费用。\n第四十四条 职工被派遣出境工作，依据前往国家或者地区的法律应当参加当地工伤保险的，参加当地工伤保险，其国内工伤保险关系中止；不能参加当地工伤保险的，其国内工伤保险关系不中止。\n第四十五条 职工再次发生工伤，根据规定应当享受伤残津贴的，按照新认定的伤残等级享受伤残津贴待遇。","level":1},{"name":"第六章 监督管理","text":"第四十六条 经办机构具体承办工伤保险事务，履行下列职责：\n(一)根据省、自治区、直辖市人民政府规定，征收工伤保险费；\n(二)核查用人单位的工资总额和职工人数，办理工伤保险登记，并负责保存用人单位缴费和职工享受工伤保险待遇情况的记录；\n(三)进行工伤保险的调查、统计；\n(四)按照规定管理工伤保险基金的支出；\n(五)按照规定核定工伤保险待遇；\n(六)为工伤职工或者其近亲属免费提供咨询服务。\n第四十七条 经办机构与医疗机构、辅助器具配置机构在平等协商的基础上签订服务协议，并公布签订服务协议的医疗机构、辅助器具配置机构的名单。具体办法由国务院社会保险行政部门分别会同国务院卫生行政部门、民政部门等部门制定。\n第四十八条 经办机构按照协议和国家有关目录、标准对工伤职工医疗费用、康复费用、辅助器具费用的使用情况进行核查，并按时足额结算费用。\n第四十九条 经办机构应当定期公布工伤保险基金的收支情况，及时向社会保险行政部门提出调整费率的建议。\n第五十条 社会保险行政部门、经办机构应当定期听取工伤职工、医疗机构、辅助器具配置机构以及社会各界对改进工伤保险工作的意见。\n第五十一条 社会保险行政部门依法对工伤保险费的征缴和工伤保险基金的支付情况进行监督检查。\n财政部门和审计机关依法对工伤保险基金的收支、管理情况进行监督。\n第五十二条 任何组织和个人对有关工伤保险的违法行为，有权举报。社会保险行政部门对举报应当及时调查，按照规定处理，并为举报人保密。\n第五十三条 工会组织依法维护工伤职工的合法权益，对用人单位的工伤保险工作实行监督。\n第五十四条 职工与用人单位发生工伤待遇方面的争议，按照处理劳动争议的有关规定处理。\n第五十五条 有下列情形之一的，有关单位或者个人可以依法申请行政复议，也可以依法向人民法院提起行政诉讼：\n(一)申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定申请不予受理的决定不服的；\n(二)申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定结论不服的；\n(三)用人单位对经办机构确定的单位缴费费率不服的；\n(四)签订服务协议的医疗机构、辅助器具配置机构认为经办机构未履行有关协议或者规定的；\n(五)工伤职工或者其近亲属对经办机构核定的工伤保险待遇有异议的。","level":1},{"name":"第七章 法律责任","text":"第五十六条 单位或者个人违反本条例第十二条规定挪用工伤保险基金，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分或者纪律处分。被挪用的基金由社会保险行政部门追回，并入工伤保险基金；没收的违法所得依法上缴国库。\n第五十七条 社会保险行政部门工作人员有下列情形之一的，依法给予处分；情节严重，构成犯罪的，依法追究刑事责任：\n(一)无正当理由不受理工伤认定申请，或者弄虚作假将不符合工伤条件的人员认定为工伤职工的；\n(二)未妥善保管申请工伤认定的证据材料，致使有关证据灭失的；\n(三)收受当事人财物的。\n第五十八条 经办机构有下列行为之一的，由社会保险行政部门责令改正，对直接负责的主管人员和其他责任人员依法给予纪律处分；情节严重，构成犯罪的，依法追究刑事责任；造成当事人经济损失的，由经办机构依法承担赔偿责任：\n(一)未按规定保存用人单位缴费和职工享受工伤保险待遇情况记录的；\n(二)不按规定核定工伤保险待遇的；\n(三)收受当事人财物的。\n第五十九条 医疗机构、辅助器具配置机构不按服务协议提供服务的，经办机构可以解除服务协议。\n经办机构不按时足额结算费用的，由社会保险行政部门责令改正；医疗机构、辅助器具配置机构可以解除服务协议。\n第六十条 用人单位、工伤职工或者其近亲属骗取工伤保险待遇，医疗机构、辅助器具配置机构骗取工伤保险基金支出的，由社会保险行政部门责令退还，处骗取金额2倍以上5倍以下的罚款；情节严重，构成犯罪的，依法追究刑事责任。\n第六十一条 从事劳动能力鉴定的组织或者个人有下列情形之一的，由社会保险行政部门责令改正，处2000元以上1万元以下的罚款；情节严重，构成犯罪的，依法追究刑事责任：\n(一)提供虚假鉴定意见的；\n(二)提供虚假诊断证明的；\n(三)收受当事人财物的。\n第六十二条 用人单位依照本条例规定应当参加工伤保险而未参加的，由社会保险行政部门责令限期参加，补缴应当缴纳的工伤保险费，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，处欠缴数额1倍以上3倍以下的罚款。\n依照本条例规定应当参加工伤保险而未参加工伤保险的用人单位职工发生工伤的，由该用人单位按照本条例规定的工伤保险待遇项目和标准支付费用。\n用人单位参加工伤保险并补缴应当缴纳的工伤保险费、滞纳金后，由工伤保险基金和用人单位依照本条例的规定支付新发生的费用。\n第六十三条 用人单位违反本条例第十九条的规定，拒不协助社会保险行政部门对事故进行调查核实的，由社会保险行政部门责令改正，处2000元以上2万元以下的罚款。","level":1},{"name":"第八章 附则","text":"第六十四条 本条例所称工资总额，是指用人单位直接支付给本单位全部职工的劳动报酬总额。\n本条例所称本人工资，是指工伤职工因工作遭受事故伤害或者患职业病前12个月平均月缴费工资。本人工资高于统筹地区职工平均工资300%的，按照统筹地区职工平均工资的300%计算；本人工资低于统筹地区职工平均工资60%的，按照统筹地区职工平均工资的60%计算。\n第六十五条 公务员和参照公务员法管理的事业单位、社会团体的工作人员因工作遭受事故伤害或者患职业病的，由所在单位支付费用。具体办法由国务院社会保险行政部门会同国务院财政部门规定。\n第六十六条 无营业执照或者未经依法登记、备案的单位以及被依法吊销营业执照或者撤销登记、备案的单位的职工受到事故伤害或者患职业病的，由该单位向伤残职工或者死亡职工的近亲属给予一次性赔偿，赔偿标准不得低于本条例规定的工伤保险待遇；用人单位不得使用童工，用人单位使用童工造成童工伤残、死亡的，由该单位向童工或者童工的近亲属给予一次性赔偿，赔偿标准不得低于本条例规定的工伤保险待遇。具体办法由国务院社会保险行政部门规定。\n前款规定的伤残职工或者死亡职工的近亲属就赔偿数额与单位发生争议的，以及前款规定的童工或者童工的近亲属就赔偿数额与单位发生争议的，按照处理劳动争议的有关规定处理。\n第六十七条 本条例自2004年1月1日起施行。本条例施行前已受到事故伤害或者患职业病的职工尚未完成工伤认定的，按照本条例的规定执行。","level":1}]},{"id":"n0355","sections":[{"name":"","text":"国务院关于开展全民义务植树\n运动的实施办法\n（1982年2月27日）\n为了切实贯彻执行第五届全国人民代表大会第四次会议《关于开展全民义务植树运动的决议》，特制定如下实施办法。\n一、县以上各级人民政府均应成立绿化委员会，统一领导本地区的义务植树运动和整个造林绿化工作。各级绿化委员会由当地政府的主要领导同志，以及有关部门和人民团体的负责同志组成。委员会的办公室设在同级政府的主管部门，不另增加编制。\n个别地方，由于气候、土地等条件限制确实难以开展植树运动的，经省、自治区、直辖市绿化委员会批准，可以不开展全民义务植树运动，不成立绿化委员会。\n二、各级绿化委员会应当组织和推动本地区各部门、各单位，通过各种形式，广泛深入地宣传《关于开展全民义务植树运动的决议》和本实施办法，宣传全民植树、绿化祖国的重大意义，认真做好思想动员，提高认识，造成声势，做到家喻户晓，人人皆知。同时，要努力做好调查研究、规划安排、苗木培育、技术训练等准备工作，有计划有步骤地开展植树运动，要扎扎实实，讲求实效，不搞形式主义和“一刀切”。\n三、凡是中华人民共和国公民，男十一岁至六十岁，女十一岁至五十五岁，除丧失劳动能力者外，均应承担义务植树任务，各单位要将人数据实统计上报当地绿化委员会，作为分配具体任务的依据。\n县级绿化委员会在分配义务植树任务时，要按照每人每年植树三至五棵的要求，确定具体指标，因地制宜地进行灵活多样的安排。可以按单位划分责任地段，承担整地、育苗、栽植和管护任务；也可以按相应劳动量，分配承担造林绿化的某一单项和几个单项的任务。此项任务，可以一年一定，也可以一定几年。\n对十一岁至十七岁的青少年，应当根据他们的实际情况，就近安排力所能及的劳动。\n四、此项义务劳动，限于用在本县、本市所辖范围，营造国有林和集体林。义务植树的地段或参加绿化劳动的项目，各地要经过周密的调查研究，作出统一规划和安排。城市要优先搞好风景游览区、名胜古迹和主要街道等公共场所的绿化。农村要尽快搞好“四旁”绿化和农田防护林建设。机关、团体、企业、学校等单位和居民区，都要大力植树、种草、栽花，美化环境。\n五、使用义务劳动，在国有土地上栽植的树木，林权归现在经营管理这些土地的单位所有；没有明确经营管理单位的，由当地政府指定的部门、单位所有。在集体土地上义务栽植的树木，林权归集体单位所有。如果情况特殊，另有协议或合同，按协议或合同的规定办理。对林权所有单位，县以上人民政府要发给证书，切实保障其合法权益。\n六、为确保义务植树所需苗木，各地应当努力办好现有的国营苗圃和集体苗圃，并安排必需数量的土地和专业人员，扩建和新建苗木基地，培育良种壮苗。凡是有条件的单位，都要积极自办苗圃。提倡城镇家庭和农村社员开展营养钵育苗。\n七、对义务栽植的树木和现有的林木，必须大力加强培育管护，确保成活成林，不受破坏。林木所有的单位或承担管护义务的单位，应当根据情况组织林场、专业队或确定专人负责管护。要严肃法制和纪律，建立爱林护林的乡规民约。采伐更新，必须按照森林法的规定，经过林业或园林部门批准。城市绿地要严加保护，不得侵占破坏。违者要给予经济处罚或法律制裁。\n八、植树绿化，要讲究科学，注重实效。要培训技术骨干，加强技术指导，普及植树绿化的技术知识，严格按照技术规程办事，保证质量。\n九、对义务植树，各单位每年都要进行检查，并将完成情况据实上报。绿化委员会应当定期组织评比，成绩优异的，要给予表扬和奖励；年满十八岁的成年公民无故不履行此项义务的，所在单位要进行批评教育，责令限期补栽，或者给予经济处罚。整个单位没有完成任务的，要追究领导责任，并由当地绿化委员会收缴一定数额的绿化费。\n十、各级林业和园林部门，应当在绿化委员会领导下，会同有关部门，努力搞好规划设计和苗木培育等各项具体工作。基层机构不健全的，应当充实和加强。\n十一、义务植树所需的苗木费、管护费，应当根据自力更生勤俭节约的原则，一般由林权所有单位负责解决。有的单位因绿化任务大，资金困难，确实无力承担全部费用的，按单位隶属关系，由各级财政酌情解决。参加义务植树的单位和个人所需交通等费用，由参加单位自理。\n十二、开展全民义务植树运动是促进整个造林绿化的一个重大措施。各地在开展此项运动时，必须同加快整个造林绿化工作结合起来，在苗木、经费、技术力量的使用和林木管护等方面进行统筹安排，既要搞好义务植树，又要完成年度造林绿化计划。对于一个地方来说，完成了义务植树任务，但整个造林绿化工作没有做好，不能给予表扬和奖励。\n十三、根据《关于开展全民义务植树运动的决议》和本实施办法的规定，各省、自治区、直辖市人民政府可以结合实际情况，制定实施细则。\n人民解放军指战员参加营区外义务植树的办法，按国务院、中央军委《关于军队参加营区外义务植树的指示》(〔1982〕3号)的规定执行；营区内植树办法，由解放军总部另定。但各地人民政府必须密切合作，合理规划，帮助军队解决应解决的实际问题。","level":0}]},{"id":"n0356","sections":[{"name":"","text":"中华人民共和国审计法实施条例\n(1997年10月21日中华人民共和国国务院令第231号公布 2010年2月2日国务院第100次常务会议修订通过 2010年2月11日中华人民共和国国务院令第571号公布 自2010年5月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 根据《中华人民共和国审计法》(以下简称审计法)的规定，制定本条例。\n第二条 审计法所称审计，是指审计机关依法独立检查被审计单位的会计凭证、会计账簿、财务会计报告以及其他与财政收支、财务收支有关的资料和资产，监督财政收支、财务收支真实、合法和效益的行为。\n第三条 审计法所称财政收支，是指依照《中华人民共和国预算法》和国家其他有关规定，纳入预算管理的收入和支出，以及下列财政资金中未纳入预算管理的收入和支出：\n(一)行政事业性收费；\n(二)国有资源、国有资产收入；\n(三)应当上缴的国有资本经营收益；\n(四)政府举借债务筹措的资金；\n(五)其他未纳入预算管理的财政资金。\n第四条 审计法所称财务收支，是指国有的金融机构、企业事业组织以及依法应当接受审计机关审计监督的其他单位，按照国家财务会计制度的规定，实行会计核算的各项收入和支出。\n第五条 审计机关依照审计法和本条例以及其他有关法律、法规规定的职责、权限和程序进行审计监督。\n审计机关依照有关财政收支、财务收支的法律、法规，以及国家有关政策、标准、项目目标等方面的规定进行审计评价，对被审计单位违反国家规定的财政收支、财务收支行为，在法定职权范围内作出处理、处罚的决定。\n第六条 任何单位和个人对依法应当接受审计机关审计监督的单位违反国家规定的财政收支、财务收支行为，有权向审计机关举报。审计机关接到举报，应当依法及时处理。","level":1},{"name":"第二章 审计机关和审计人员","text":"第七条 审计署在国务院总理领导下，主管全国的审计工作，履行审计法和国务院规定的职责。\n地方各级审计机关在本级人民政府行政首长和上一级审计机关的领导下，负责本行政区域的审计工作，履行法律、法规和本级人民政府规定的职责。\n第八条 省、自治区人民政府设有派出机关的，派出机关的审计机关对派出机关和省、自治区人民政府审计机关负责并报告工作，审计业务以省、自治区人民政府审计机关领导为主。\n第九条 审计机关派出机构依照法律、法规和审计机关的规定，在审计机关的授权范围内开展审计工作，不受其他行政机关、社会团体和个人的干涉。\n第十条 审计机关编制年度经费预算草案的依据主要包括：\n(一)法律、法规；\n(二)本级人民政府的决定和要求；\n(三)审计机关的年度审计工作计划；\n(四)定员定额标准；\n(五)上一年度经费预算执行情况和本年度的变化因素。\n第十一条 审计人员实行审计专业技术资格制度，具体按照国家有关规定执行。\n审计机关根据工作需要，可以聘请具有与审计事项相关专业知识的人员参加审计工作。\n第十二条 审计人员办理审计事项，有下列情形之一的，应当申请回避，被审计单位也有权申请审计人员回避：\n(一)与被审计单位负责人或者有关主管人员有夫妻关系、直系血亲关系、三代以内旁系血亲或者近姻亲关系的；\n(二)与被审计单位或者审计事项有经济利益关系的；\n(三)与被审计单位、审计事项、被审计单位负责人或者有关主管人员有其他利害关系，可能影响公正执行公务的。\n审计人员的回避，由审计机关负责人决定；审计机关负责人办理审计事项时的回避，由本级人民政府或者上一级审计机关负责人决定。\n第十三条 地方各级审计机关正职和副职负责人的任免，应当事先征求上一级审计机关的意见。\n第十四条 审计机关负责人在任职期间没有下列情形之一的，不得随意撤换：\n(一)因犯罪被追究刑事责任的；\n(二)因严重违法、失职受到处分，不适宜继续担任审计机关负责人的；\n(三)因健康原因不能履行职责1年以上的；\n(四)不符合国家规定的其他任职条件的。","level":1},{"name":"第三章 审计机关职责","text":"第十五条 审计机关对本级人民政府财政部门具体组织本级预算执行的情况，本级预算收入征收部门征收预算收入的情况，与本级人民政府财政部门直接发生预算缴款、拨款关系的部门、单位的预算执行情况和决算，下级人民政府的预算执行情况和决算，以及其他财政收支情况，依法进行审计监督。经本级人民政府批准，审计机关对其他取得财政资金的单位和项目接受、运用财政资金的真实、合法和效益情况，依法进行审计监督。\n第十六条 审计机关对本级预算收入和支出的执行情况进行审计监督的内容包括：\n(一)财政部门按照本级人民代表大会批准的本级预算向本级各部门(含直属单位)批复预算的情况、本级预算执行中调整情况和预算收支变化情况；\n(二)预算收入征收部门依照法律、行政法规的规定和国家其他有关规定征收预算收入情况；\n(三)财政部门按照批准的年度预算、用款计划，以及规定的预算级次和程序，拨付本级预算支出资金情况；\n(四)财政部门依照法律、行政法规的规定和财政管理体制，拨付和管理政府间财政转移支付资金情况以及办理结算、结转情况；\n(五)国库按照国家有关规定办理预算收入的收纳、划分、留解情况和预算支出资金的拨付情况；\n(六)本级各部门(含直属单位)执行年度预算情况；\n(七)依照国家有关规定实行专项管理的预算资金收支情况；\n(八)法律、法规规定的其他预算执行情况。\n第十七条 审计法第十七条所称审计结果报告，应当包括下列内容：\n(一)本级预算执行和其他财政收支的基本情况；\n(二)审计机关对本级预算执行和其他财政收支情况作出的审计评价；\n(三)本级预算执行和其他财政收支中存在的问题以及审计机关依法采取的措施；\n(四)审计机关提出的改进本级预算执行和其他财政收支管理工作的建议；\n(五)本级人民政府要求报告的其他情况。\n第十八条 审计署对中央银行及其分支机构履行职责所发生的各项财务收支，依法进行审计监督。\n审计署向国务院总理提出的中央预算执行和其他财政收支情况审计结果报告，应当包括对中央银行的财务收支的审计情况。\n第十九条 审计法第二十一条所称国有资本占控股地位或者主导地位的企业、金融机构，包括：\n(一)国有资本占企业、金融机构资本(股本)总额的比例超过50%的；\n(二)国有资本占企业、金融机构资本(股本)总额的比例在50%以下，但国有资本投资主体拥有实际控制权的。\n审计机关对前款规定的企业、金融机构，除国务院另有规定外，比照审计法第十八条第二款、第二十条规定进行审计监督。\n第二十条 审计法第二十二条所称政府投资和以政府投资为主的建设项目，包括：\n(一)全部使用预算内投资资金、专项建设基金、政府举借债务筹措的资金等财政资金的；\n(二)未全部使用财政资金，财政资金占项目总投资的比例超过50%，或者占项目总投资的比例在50%以下，但政府拥有项目建设、运营实际控制权的。\n审计机关对前款规定的建设项目的总预算或者概算的执行情况、年度预算的执行情况和年度决算、单项工程结算、项目竣工决算，依法进行审计监督；对前款规定的建设项目进行审计时，可以对直接有关的设计、施工、供货等单位取得建设项目资金的真实性、合法性进行调查。\n第二十一条 审计法第二十三条所称社会保障基金，包括社会保险、社会救助、社会福利基金以及发展社会保障事业的其他专项基金；所称社会捐赠资金，包括来源于境内外的货币、有价证券和实物等各种形式的捐赠。\n第二十二条 审计法第二十四条所称国际组织和外国政府援助、贷款项目，包括：\n(一)国际组织、外国政府及其机构向中国政府及其机构提供的贷款项目；\n(二)国际组织、外国政府及其机构向中国企业事业组织以及其他组织提供的由中国政府及其机构担保的贷款项目；\n(三)国际组织、外国政府及其机构向中国政府及其机构提供的援助和赠款项目；\n(四)国际组织、外国政府及其机构向受中国政府委托管理有关基金、资金的单位提供的援助和赠款项目；\n(五)国际组织、外国政府及其机构提供援助、贷款的其他项目。\n第二十三条 审计机关可以依照审计法和本条例规定的审计程序、方法以及国家其他有关规定，对预算管理或者国有资产管理使用等与国家财政收支有关的特定事项，向有关地方、部门、单位进行专项审计调查。\n第二十四条 审计机关根据被审计单位的财政、财务隶属关系，确定审计管辖范围；不能根据财政、财务隶属关系确定审计管辖范围的，根据国有资产监督管理关系，确定审计管辖范围。\n两个以上国有资本投资主体投资的金融机构、企业事业组织和建设项目，由对主要投资主体有审计管辖权的审计机关进行审计监督。\n第二十五条 各级审计机关应当按照确定的审计管辖范围进行审计监督。\n第二十六条 依法属于审计机关审计监督对象的单位的内部审计工作，应当接受审计机关的业务指导和监督。\n依法属于审计机关审计监督对象的单位，可以根据内部审计工作的需要，参加依法成立的内部审计自律组织。审计机关可以通过内部审计自律组织，加强对内部审计工作的业务指导和监督。\n第二十七条 审计机关进行审计或者专项审计调查时，有权对社会审计机构出具的相关审计报告进行核查。\n审计机关核查社会审计机构出具的相关审计报告时，发现社会审计机构存在违反法律、法规或者执业准则等情况的，应当移送有关主管机关依法追究责任。","level":1},{"name":"第四章 审计机关权限","text":"第二十八条 审计机关依法进行审计监督时，被审计单位应当依照审计法第三十一条规定，向审计机关提供与财政收支、财务收支有关的资料。被审计单位负责人应当对本单位提供资料的真实性和完整性作出书面承诺。\n第二十九条 各级人民政府财政、税务以及其他部门(含直属单位)应当向本级审计机关报送下列资料：\n(一)本级人民代表大会批准的本级预算和本级人民政府财政部门向本级各部门(含直属单位)批复的预算，预算收入征收部门的年度收入计划，以及本级各部门(含直属单位)向所属各单位批复的预算；\n(二)本级预算收支执行和预算收入征收部门的收入计划完成情况月报、年报，以及决算情况；\n(三)综合性财政税务工作统计年报、情况简报，财政、预算、税务、财务和会计等规章制度；\n(四)本级各部门(含直属单位)汇总编制的本部门决算草案。\n第三十条 审计机关依照审计法第三十三条规定查询被审计单位在金融机构的账户的，应当持县级以上人民政府审计机关负责人签发的协助查询单位账户通知书；查询被审计单位以个人名义在金融机构的存款的，应当持县级以上人民政府审计机关主要负责人签发的协助查询个人存款通知书。有关金融机构应当予以协助，并提供证明材料，审计机关和审计人员负有保密义务。\n第三十一条 审计法第三十四条所称违反国家规定取得的资产，包括：\n(一)弄虚作假骗取的财政拨款、实物以及金融机构贷款；\n(二)违反国家规定享受国家补贴、补助、贴息、免息、减税、免税、退税等优惠政策取得的资产；\n(三)违反国家规定向他人收取的款项、有价证券、实物；\n(四)违反国家规定处分国有资产取得的收益；\n(五)违反国家规定取得的其他资产。\n第三十二条 审计机关依照审计法第三十四条规定封存被审计单位有关资料和违反国家规定取得的资产的，应当持县级以上人民政府审计机关负责人签发的封存通知书，并在依法收集与审计事项相关的证明材料或者采取其他措施后解除封存。封存的期限为7日以内；有特殊情况需要延长的，经县级以上人民政府审计机关负责人批准，可以适当延长，但延长的期限不得超过7日。\n对封存的资料、资产，审计机关可以指定被审计单位负责保管，被审计单位不得损毁或者擅自转移。\n第三十三条 审计机关依照审计法第三十六条规定，可以就有关审计事项向政府有关部门通报或者向社会公布对被审计单位的审计、专项审计调查结果。\n审计机关经与有关主管机关协商，可以在向社会公布的审计、专项审计调查结果中，一并公布对社会审计机构相关审计报告核查的结果。\n审计机关拟向社会公布对上市公司的审计、专项审计调查结果的，应当在5日前将拟公布的内容告知上市公司。","level":1},{"name":"第五章 审计程序","text":"第三十四条 审计机关应当根据法律、法规和国家其他有关规定，按照本级人民政府和上级审计机关的要求，确定年度审计工作重点，编制年度审计项目计划。\n审计机关在年度审计项目计划中确定对国有资本占控股地位或者主导地位的企业、金融机构进行审计的，应当自确定之日起7日内告知列入年度审计项目计划的企业、金融机构。\n第三十五条 审计机关应当根据年度审计项目计划，组成审计组，调查了解被审计单位的有关情况，编制审计方案，并在实施审计3日前，向被审计单位送达审计通知书。\n第三十六条 审计法第三十八条所称特殊情况，包括：\n(一)办理紧急事项的；\n(二)被审计单位涉嫌严重违法违规的；\n(三)其他特殊情况。\n第三十七条 审计人员实施审计时，应当按照下列规定办理：\n(一)通过检查、查询、监督盘点、发函询证等方法实施审计；\n(二)通过收集原件、原物或者复制、拍照等方法取得证明材料；\n(三)对与审计事项有关的会议和谈话内容作出记录，或者要求被审计单位提供会议记录材料；\n(四)记录审计实施过程和查证结果。\n第三十八条 审计人员向有关单位和个人调查取得的证明材料，应当有提供者的签名或者盖章；不能取得提供者签名或者盖章的，审计人员应当注明原因。\n第三十九条 审计组向审计机关提出审计报告前，应当书面征求被审计单位意见。被审计单位应当自接到审计组的审计报告之日起10日内，提出书面意见；10日内未提出书面意见的，视同无异议。\n审计组应当针对被审计单位提出的书面意见，进一步核实情况，对审计组的审计报告作必要修改，连同被审计单位的书面意见一并报送审计机关。\n第四十条 审计机关有关业务机构和专门机构或者人员对审计组的审计报告以及相关审计事项进行复核、审理后，由审计机关按照下列规定办理：\n(一)提出审计机关的审计报告，内容包括：对审计事项的审计评价，对违反国家规定的财政收支、财务收支行为提出的处理、处罚意见，移送有关主管机关、单位的意见，改进财政收支、财务收支管理工作的意见；\n(二)对违反国家规定的财政收支、财务收支行为，依法应当给予处理、处罚的，在法定职权范围内作出处理、处罚的审计决定；\n(三)对依法应当追究有关人员责任的，向有关主管机关、单位提出给予处分的建议；对依法应当由有关主管机关处理、处罚的，移送有关主管机关；涉嫌犯罪的，移送司法机关。\n第四十一条 审计机关在审计中发现损害国家利益和社会公共利益的事项，但处理、处罚依据又不明确的，应当向本级人民政府和上一级审计机关报告。\n第四十二条 被审计单位应当按照审计机关规定的期限和要求执行审计决定。对应当上缴的款项，被审计单位应当按照财政管理体制和国家有关规定缴入国库或者财政专户。审计决定需要有关主管机关、单位协助执行的，审计机关应当书面提请协助执行。\n第四十三条 上级审计机关应当对下级审计机关的审计业务依法进行监督。\n下级审计机关作出的审计决定违反国家有关规定的，上级审计机关可以责成下级审计机关予以变更或者撤销，也可以直接作出变更或者撤销的决定；审计决定被撤销后需要重新作出审计决定的，上级审计机关可以责成下级审计机关在规定的期限内重新作出审计决定，也可以直接作出审计决定。\n下级审计机关应当作出而没有作出审计决定的，上级审计机关可以责成下级审计机关在规定的期限内作出审计决定，也可以直接作出审计决定。\n第四十四条 审计机关进行专项审计调查时，应当向被调查的地方、部门、单位出示专项审计调查的书面通知，并说明有关情况；有关地方、部门、单位应当接受调查，如实反映情况，提供有关资料。\n在专项审计调查中，依法属于审计机关审计监督对象的部门、单位有违反国家规定的财政收支、财务收支行为或者其他违法违规行为的，专项审计调查人员和审计机关可以依照审计法和本条例的规定提出审计报告，作出审计决定，或者移送有关主管机关、单位依法追究责任。\n第四十五条 审计机关应当按照国家有关规定建立、健全审计档案制度。\n第四十六条 审计机关送达审计文书，可以直接送达，也可以邮寄送达或者以其他方式送达。直接送达的，以被审计单位在送达回证上注明的签收日期或者见证人证明的收件日期为送达日期；邮寄送达的，以邮政回执上注明的收件日期为送达日期；以其他方式送达的，以签收或者收件日期为送达日期。\n审计机关的审计文书的种类、内容和格式，由审计署规定。","level":1},{"name":"第六章 法律责任","text":"第四十七条 被审计单位违反审计法和本条例的规定，拒绝、拖延提供与审计事项有关的资料，或者提供的资料不真实、不完整，或者拒绝、阻碍检查的，由审计机关责令改正，可以通报批评，给予警告；拒不改正的，对被审计单位可以处5万元以下的罚款，对直接负责的主管人员和其他直接责任人员，可以处2万元以下的罚款，审计机关认为应当给予处分的，向有关主管机关、单位提出给予处分的建议；构成犯罪的，依法追究刑事责任。\n第四十八条 对本级各部门(含直属单位)和下级人民政府违反预算的行为或者其他违反国家规定的财政收支行为，审计机关在法定职权范围内，依照法律、行政法规的规定，区别情况采取审计法第四十五条规定的处理措施。\n第四十九条 对被审计单位违反国家规定的财务收支行为，审计机关在法定职权范围内，区别情况采取审计法第四十五条规定的处理措施，可以通报批评，给予警告；有违法所得的，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得的，可以处5万元以下的罚款；对直接负责的主管人员和其他直接责任人员，可以处2万元以下的罚款，审计机关认为应当给予处分的，向有关主管机关、单位提出给予处分的建议；构成犯罪的，依法追究刑事责任。\n法律、行政法规对被审计单位违反国家规定的财务收支行为处理、处罚另有规定的，从其规定。\n第五十条 审计机关在作出较大数额罚款的处罚决定前，应当告知被审计单位和有关人员有要求举行听证的权利。较大数额罚款的具体标准由审计署规定。\n第五十一条 审计机关提出的对被审计单位给予处理、处罚的建议以及对直接负责的主管人员和其他直接责任人员给予处分的建议，有关主管机关、单位应当依法及时作出决定，并将结果书面通知审计机关。\n第五十二条 被审计单位对审计机关依照审计法第十六条、第十七条和本条例第十五条规定进行审计监督作出的审计决定不服的，可以自审计决定送达之日起60日内，提请审计机关的本级人民政府裁决，本级人民政府的裁决为最终决定。\n审计机关应当在审计决定中告知被审计单位提请裁决的途径和期限。\n裁决期间，审计决定不停止执行。但是，有下列情形之一的，可以停止执行：\n(一)审计机关认为需要停止执行的；\n(二)受理裁决的人民政府认为需要停止执行的；\n(三)被审计单位申请停止执行，受理裁决的人民政府认为其要求合理，决定停止执行的。\n裁决由本级人民政府法制机构办理。裁决决定应当自接到提请之日起60日内作出；有特殊情况需要延长的，经法制机构负责人批准，可以适当延长，并告知审计机关和提请裁决的被审计单位，但延长的期限不得超过30日。\n第五十三条 除本条例第五十二条规定的可以提请裁决的审计决定外，被审计单位对审计机关作出的其他审计决定不服的，可以依法申请行政复议或者提起行政诉讼。\n审计机关应当在审计决定中告知被审计单位申请行政复议或者提起行政诉讼的途径和期限。\n第五十四条 被审计单位应当将审计决定执行情况书面报告审计机关。审计机关应当检查审计决定的执行情况。\n被审计单位不执行审计决定的，审计机关应当责令限期执行；逾期仍不执行的，审计机关可以申请人民法院强制执行，建议有关主管机关、单位对直接负责的主管人员和其他直接责任人员给予处分。\n第五十五条 审计人员滥用职权、徇私舞弊、玩忽职守，或者泄露所知悉的国家秘密、商业秘密的，依法给予处分；构成犯罪的，依法追究刑事责任。\n审计人员违法违纪取得的财物，依法予以追缴、没收或者责令退赔。","level":1},{"name":"第七章 附则","text":"第五十六条 本条例所称以上、以下，包括本数。\n本条例第五十二条规定的期间的最后一日是法定节假日的，以节假日后的第一个工作日为期间届满日。审计法和本条例规定的其他期间以工作日计算，不含法定节假日。\n第五十七条 实施经济责任审计的规定，另行制定。\n第五十八条 本条例自2010年5月1日起施行。","level":1}]},{"id":"n0357","sections":[{"name":"","text":"彩票管理条例\n(2009年4月22日国务院第58次常务会议通过 2009年5月4日中华人民共和国国务院令第554号公布 自2009年7月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了加强彩票管理，规范彩票市场发展，维护彩票市场秩序，保护彩票参与者的合法权益，促进社会公益事业发展，制定本条例。\n第二条 本条例所称彩票，是指国家为筹集社会公益资金，促进社会公益事业发展而特许发行、依法销售，自然人自愿购买，并按照特定规则获得中奖机会的凭证。\n彩票不返还本金、不计付利息。\n第三条 国务院特许发行福利彩票、体育彩票。未经国务院特许，禁止发行其他彩票。禁止在中华人民共和国境内发行、销售境外彩票。\n第四条 彩票的发行、销售和开奖，应当遵循公开、公平、公正和诚实信用的原则。\n第五条 国务院财政部门负责全国的彩票监督管理工作。国务院民政部门、体育行政部门按照各自的职责分别负责全国的福利彩票、体育彩票管理工作。\n省、自治区、直辖市人民政府财政部门负责本行政区域的彩票监督管理工作。省、自治区、直辖市人民政府民政部门、体育行政部门按照各自的职责分别负责本行政区域的福利彩票、体育彩票管理工作。\n县级以上各级人民政府公安机关和县级以上工商行政管理机关，在各自的职责范围内，依法查处非法彩票，维护彩票市场秩序。","level":1},{"name":"第二章 彩票发行和销售管理","text":"第六条 国务院民政部门、体育行政部门依法设立的福利彩票发行机构、体育彩票发行机构(以下简称彩票发行机构)，分别负责全国的福利彩票、体育彩票发行和组织销售工作。\n省、自治区、直辖市人民政府民政部门、体育行政部门依法设立的福利彩票销售机构、体育彩票销售机构(以下简称彩票销售机构)，分别负责本行政区域的福利彩票、体育彩票销售工作。\n第七条 彩票发行机构申请开设、停止福利彩票、体育彩票的具体品种(以下简称彩票品种)或者申请变更彩票品种审批事项的，应当依照本条例规定的程序报国务院财政部门批准。\n国务院财政部门应当根据彩票市场健康发展的需要，按照合理规划彩票市场和彩票品种结构、严格控制彩票风险的原则，对彩票发行机构的申请进行审查。\n第八条 彩票发行机构申请开设彩票品种，应当经国务院民政部门或者国务院体育行政部门审核同意，向国务院财政部门提交下列申请材料：\n(一)申请书；\n(二)彩票品种的规则；\n(三)发行方式、发行范围；\n(四)市场分析报告及技术可行性分析报告；\n(五)开奖、兑奖操作规程；\n(六)风险控制方案。\n国务院财政部门应当自受理申请之日起90个工作日内，通过专家评审、听证会等方式对开设彩票品种听取社会意见，对申请进行审查并作出书面决定。\n第九条 彩票发行机构申请变更彩票品种的规则、发行方式、发行范围等审批事项的，应当经国务院民政部门或者国务院体育行政部门审核同意，向国务院财政部门提出申请并提交与变更事项有关的材料。国务院财政部门应当自受理申请之日起45个工作日内，对申请进行审查并作出书面决定。\n第十条 彩票发行机构申请停止彩票品种的，应当经国务院民政部门或者国务院体育行政部门审核同意，向国务院财政部门提出书面申请并提交与停止彩票品种有关的材料。国务院财政部门应当自受理申请之日起10个工作日内，对申请进行审查并作出书面决定。\n第十一条 经批准开设、停止彩票品种或者变更彩票品种审批事项的，彩票发行机构应当在开设、变更、停止的10个自然日前，将有关信息向社会公告。\n第十二条 因维护社会公共利益的需要，在紧急情况下，国务院财政部门可以采取必要措施，决定变更彩票品种审批事项或者停止彩票品种。\n第十三条 彩票发行机构、彩票销售机构应当依照政府采购法律、行政法规的规定，采购符合标准的彩票设备和技术服务。\n彩票设备和技术服务的标准，由国务院财政部门会同国务院民政部门、体育行政部门依照国家有关标准化法律、行政法规的规定制定。\n第十四条 彩票发行机构、彩票销售机构应当建立风险管理体系和可疑资金报告制度，保障彩票发行、销售的安全。\n彩票发行机构、彩票销售机构负责彩票销售系统的数据管理、开奖兑奖管理以及彩票资金的归集管理，不得委托他人管理。\n第十五条 彩票发行机构、彩票销售机构可以委托单位、个人代理销售彩票。彩票发行机构、彩票销售机构应当与接受委托的彩票代销者签订彩票代销合同。福利彩票、体育彩票的代销合同示范文本分别由国务院民政部门、体育行政部门制定。\n彩票代销者不得委托他人代销彩票。\n第十六条 彩票销售机构应当为彩票代销者配置彩票投注专用设备。彩票投注专用设备属于彩票销售机构所有，彩票代销者不得转借、出租、出售。\n第十七条 彩票销售机构应当在彩票发行机构的指导下，统筹规划彩票销售场所的布局。彩票销售场所应当按照彩票发行机构的统一要求，设置彩票销售标识，张贴警示标语。\n第十八条 彩票发行机构、彩票销售机构、彩票代销者不得有下列行为：\n(一)进行虚假性、误导性宣传；\n(二)以诋毁同业者等手段进行不正当竞争；\n(三)向未成年人销售彩票；\n(四)以赊销或者信用方式销售彩票。\n第十九条 需要销毁彩票的，由彩票发行机构报国务院财政部门批准后，在国务院民政部门或者国务院体育行政部门的监督下销毁。\n第二十条 彩票发行机构、彩票销售机构应当及时将彩票发行、销售情况向社会全面公布，接受社会公众的监督。","level":1},{"name":"第三章 彩票开奖和兑奖管理","text":"第二十一条 彩票发行机构、彩票销售机构应当按照批准的彩票品种的规则和开奖操作规程开奖。\n国务院民政部门、体育行政部门和省、自治区、直辖市人民政府民政部门、体育行政部门应当加强对彩票开奖活动的监督，确保彩票开奖的公开、公正。\n第二十二条 彩票发行机构、彩票销售机构应当确保彩票销售数据的完整、准确和安全。当期彩票销售数据封存后至开奖活动结束前，不得查阅、变更或者删除销售数据。\n第二十三条 彩票发行机构、彩票销售机构应当加强对开奖设备的管理，确保开奖设备正常运行，并配置备用开奖设备。\n第二十四条 彩票发行机构、彩票销售机构应当在每期彩票销售结束后，及时向社会公布当期彩票的销售情况和开奖结果。\n第二十五条 彩票中奖者应当自开奖之日起60个自然日内，持中奖彩票到指定的地点兑奖，彩票品种的规则规定需要出示身份证件的，还应当出示本人身份证件。逾期不兑奖的视为弃奖。\n禁止使用伪造、变造的彩票兑奖。\n第二十六条 彩票发行机构、彩票销售机构、彩票代销者应当按照彩票品种的规则和兑奖操作规程兑奖。\n彩票中奖奖金应当以人民币现金或者现金支票形式一次性兑付。\n不得向未成年人兑奖。\n第二十七条 彩票发行机构、彩票销售机构、彩票代销者以及其他因职务或者业务便利知悉彩票中奖者个人信息的人员，应当对彩票中奖者个人信息予以保密。","level":1},{"name":"第四章 彩票资金管理","text":"第二十八条 彩票资金包括彩票奖金、彩票发行费和彩票公益金。彩票资金构成比例由国务院决定。\n彩票品种中彩票资金的具体构成比例，由国务院财政部门按照国务院的决定确定。\n随着彩票发行规模的扩大和彩票品种的增加，可以降低彩票发行费比例。\n第二十九条 彩票发行机构、彩票销售机构应当按照国务院财政部门的规定开设彩票资金账户，用于核算彩票资金。\n第三十条 国务院财政部门和省、自治区、直辖市人民政府财政部门应当建立彩票发行、销售和资金管理信息系统，及时掌握彩票销售和资金流动情况。\n第三十一条 彩票奖金用于支付彩票中奖者。彩票单注奖金的最高限额，由国务院财政部门根据彩票市场发展情况决定。\n逾期未兑奖的奖金，纳入彩票公益金。\n第三十二条 彩票发行费专项用于彩票发行机构、彩票销售机构的业务费用支出以及彩票代销者的销售费用支出。\n彩票发行机构、彩票销售机构的业务费实行收支两条线管理，其支出应当符合彩票发行机构、彩票销售机构财务管理制度。\n第三十三条 彩票公益金专项用于社会福利、体育等社会公益事业，不用于平衡财政一般预算。\n彩票公益金按照政府性基金管理办法纳入预算，实行收支两条线管理。\n第三十四条 彩票发行机构、彩票销售机构应当按照国务院财政部门的规定，及时上缴彩票公益金和彩票发行费中的业务费，不得截留或者挪作他用。财政部门应当及时核拨彩票发行机构、彩票销售机构的业务费。\n第三十五条 彩票公益金的分配政策，由国务院财政部门会同国务院民政、体育行政等有关部门提出方案，报国务院批准后执行。\n第三十六条 彩票发行费、彩票公益金的管理、使用单位，应当依法接受财政部门、审计机关和社会公众的监督。\n彩票公益金的管理、使用单位，应当每年向社会公告公益金的使用情况。\n第三十七条 国务院财政部门和省、自治区、直辖市人民政府财政部门应当每年向本级人民政府报告上年度彩票公益金的筹集、分配和使用情况，并向社会公告。","level":1},{"name":"第五章 法律责任","text":"第三十八条 违反本条例规定，擅自发行、销售彩票，或者在中华人民共和国境内发行、销售境外彩票构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由公安机关依法给予治安管理处罚；有违法所得的，没收违法所得。\n第三十九条 彩票发行机构、彩票销售机构有下列行为之一的，由财政部门责令停业整顿；有违法所得的，没收违法所得，并处违法所得3倍的罚款；对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任：\n(一)未经批准开设、停止彩票品种或者未经批准变更彩票品种审批事项的；\n(二)未按批准的彩票品种的规则、发行方式、发行范围、开奖兑奖操作规程发行、销售彩票或者开奖兑奖的；\n(三)将彩票销售系统的数据管理、开奖兑奖管理或者彩票资金的归集管理委托他人管理的；\n(四)违反规定查阅、变更、删除彩票销售数据的；\n(五)以赊销或者信用方式销售彩票的；\n(六)未经批准销毁彩票的；\n(七)截留、挪用彩票资金的。\n第四十条 彩票发行机构、彩票销售机构有下列行为之一的，由财政部门责令改正；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员，依法给予处分：\n(一)采购不符合标准的彩票设备或者技术服务的；\n(二)进行虚假性、误导性宣传的；\n(三)以诋毁同业者等手段进行不正当竞争的；\n(四)向未成年人销售彩票的；\n(五)泄露彩票中奖者个人信息的；\n(六)未将逾期未兑奖的奖金纳入彩票公益金的；\n(七)未按规定上缴彩票公益金、彩票发行费中的业务费的。\n第四十一条 彩票代销者有下列行为之一的，由民政部门、体育行政部门责令改正，处2000元以上1万元以下罚款；有违法所得的，没收违法所得：\n(一)委托他人代销彩票或者转借、出租、出售彩票投注专用设备的；\n(二)进行虚假性、误导性宣传的；\n(三)以诋毁同业者等手段进行不正当竞争的；\n(四)向未成年人销售彩票的；\n(五)以赊销或者信用方式销售彩票的。\n彩票代销者有前款行为受到处罚的，彩票发行机构、彩票销售机构有权解除彩票代销合同。\n第四十二条 伪造、变造彩票或使用伪造、变造的彩票兑奖的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。\n第四十三条 彩票公益金管理、使用单位违反彩票公益金管理、使用规定的，由财政部门责令限期改正；有违法所得的，没收违法所得；在规定期限内不改正的，没收已使用彩票公益金形成的资产，取消其彩票公益金使用资格。\n第四十四条 依照本条例的规定履行彩票管理职责的财政部门、民政部门、体育行政部门的工作人员，在彩票监督管理活动中滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。","level":1},{"name":"第六章 附则","text":"第四十五条 本条例自2009年7月1日起施行。","level":1}]},{"id":"n0358","sections":[{"name":"","text":"突发公共卫生事件应急条例\n(2003年5月9日中华人民共和国国务院令第376号公布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了有效预防、及时控制和消除突发公共卫生事件的危害，保障公众身体健康与生命安全，维护正常的社会秩序，制定本条例。\n第二条 本条例所称突发公共卫生事件(以下简称突发事件)，是指突然发生，造成或者可能造成社会公众健康严重损害的重大传染病疫情、群体性不明原因疾病、重大食物和职业中毒以及其他严重影响公众健康的事件。\n第三条 突发事件发生后，国务院设立全国突发事件应急处理指挥部，由国务院有关部门和军队有关部门组成，国务院主管领导人担任总指挥，负责对全国突发事件应急处理的统一领导、统一指挥。\n国务院卫生行政主管部门和其他有关部门，在各自的职责范围内做好突发事件应急处理的有关工作。\n第四条 突发事件发生后，省、自治区、直辖市人民政府成立地方突发事件应急处理指挥部，省、自治区、直辖市人民政府主要领导人担任总指挥，负责领导、指挥本行政区域内突发事件应急处理工作。\n县级以上地方人民政府卫生行政主管部门，具体负责组织突发事件的调查、控制和医疗救治工作。\n县级以上地方人民政府有关部门，在各自的职责范围内做好突发事件应急处理的有关工作。\n第五条 突发事件应急工作，应当遵循预防为主、常备不懈的方针，贯彻统一领导、分级负责、反应及时、措施果断、依靠科学、加强合作的原则。\n第六条 县级以上各级人民政府应当组织开展防治突发事件相关科学研究，建立突发事件应急流行病学调查、传染源隔离、医疗救护、现场处置、监督检查、监测检验、卫生防护等有关物资、设备、设施、技术与人才资源储备，所需经费列入本级政府财政预算。\n国家对边远贫困地区突发事件应急工作给予财政支持。\n第七条 国家鼓励、支持开展突发事件监测、预警、反应处理有关技术的国际交流与合作。\n第八条 国务院有关部门和县级以上地方人民政府及其有关部门，应当建立严格的突发事件防范和应急处理责任制，切实履行各自的职责，保证突发事件应急处理工作的正常进行。\n第九条 县级以上各级人民政府及其卫生行政主管部门，应当对参加突发事件应急处理的医疗卫生人员，给予适当补助和保健津贴；对参加突发事件应急处理作出贡献的人员，给予表彰和奖励；对因参与应急处理工作致病、致残、死亡的人员，按照国家有关规定，给予相应的补助和抚恤。","level":1},{"name":"第二章 预防与应急准备","text":"第十条 国务院卫生行政主管部门按照分类指导、快速反应的要求，制定全国突发事件应急预案，报请国务院批准。\n省、自治区、直辖市人民政府根据全国突发事件应急预案，结合本地实际情况，制定本行政区域的突发事件应急预案。\n第十一条 全国突发事件应急预案应当包括以下主要内容：\n(一)突发事件应急处理指挥部的组成和相关部门的职责；\n(二)突发事件的监测与预警；\n(三)突发事件信息的收集、分析、报告、通报制度；\n(四)突发事件应急处理技术和监测机构及其任务；\n(五)突发事件的分级和应急处理工作方案；\n(六)突发事件预防、现场控制，应急设施、设备、救治药品和医疗器械以及其他物资和技术的储备与调度；\n(七)突发事件应急处理专业队伍的建设和培训。\n第十二条 突发事件应急预案应当根据突发事件的变化和实施中发现的问题及时进行修订、补充。\n第十三条 地方各级人民政府应当依照法律、行政法规的规定，做好传染病预防和其他公共卫生工作，防范突发事件的发生。\n县级以上各级人民政府卫生行政主管部门和其他有关部门，应当对公众开展突发事件应急知识的专门教育，增强全社会对突发事件的防范意识和应对能力。\n第十四条 国家建立统一的突发事件预防控制体系。\n县级以上地方人民政府应当建立和完善突发事件监测与预警系统。\n县级以上各级人民政府卫生行政主管部门，应当指定机构负责开展突发事件的日常监测，并确保监测与预警系统的正常运行。\n第十五条 监测与预警工作应当根据突发事件的类别，制定监测计划，科学分析、综合评价监测数据。对早期发现的潜在隐患以及可能发生的突发事件，应当依照本条例规定的报告程序和时限及时报告。\n第十六条 国务院有关部门和县级以上地方人民政府及其有关部门，应当根据突发事件应急预案的要求，保证应急设施、设备、救治药品和医疗器械等物资储备。\n第十七条 县级以上各级人民政府应当加强急救医疗服务网络的建设，配备相应的医疗救治药物、技术、设备和人员，提高医疗卫生机构应对各类突发事件的救治能力。\n设区的市级以上地方人民政府应当设置与传染病防治工作需要相适应的传染病专科医院，或者指定具备传染病防治条件和能力的医疗机构承担传染病防治任务。\n第十八条 县级以上地方人民政府卫生行政主管部门，应当定期对医疗卫生机构和人员开展突发事件应急处理相关知识、技能的培训，定期组织医疗卫生机构进行突发事件应急演练，推广最新知识和先进技术。","level":1},{"name":"第三章 报告与信息发布","text":"第十九条 国家建立突发事件应急报告制度。\n国务院卫生行政主管部门制定突发事件应急报告规范，建立重大、紧急疫情信息报告系统。\n有下列情形之一的，省、自治区、直辖市人民政府应当在接到报告1小时内，向国务院卫生行政主管部门报告：\n(一)发生或者可能发生传染病暴发、流行的；\n(二)发生或者发现不明原因的群体性疾病的；\n(三)发生传染病菌种、毒种丢失的；\n(四)发生或者可能发生重大食物和职业中毒事件的。\n国务院卫生行政主管部门对可能造成重大社会影响的突发事件，应当立即向国务院报告。\n第二十条 突发事件监测机构、医疗卫生机构和有关单位发现有本条例第十九条规定情形之一的，应当在2小时内向所在地县级人民政府卫生行政主管部门报告；接到报告的卫生行政主管部门应当在2小时内向本级人民政府报告，并同时向上级人民政府卫生行政主管部门和国务院卫生行政主管部门报告。\n县级人民政府应当在接到报告后2小时内向设区的市级人民政府或者上一级人民政府报告；设区的市级人民政府应当在接到报告后2小时内向省、自治区、直辖市人民政府报告。\n第二十一条 任何单位和个人对突发事件，不得隐瞒、缓报、谎报或者授意他人隐瞒、缓报、谎报。\n第二十二条 接到报告的地方人民政府、卫生行政主管部门依照本条例规定报告的同时，应当立即组织力量对报告事项调查核实、确证，采取必要的控制措施，并及时报告调查情况。\n第二十三条 国务院卫生行政主管部门应当根据发生突发事件的情况，及时向国务院有关部门和各省、自治区、直辖市人民政府卫生行政主管部门以及军队有关部门通报。\n突发事件发生地的省、自治区、直辖市人民政府卫生行政主管部门，应当及时向毗邻省、自治区、直辖市人民政府卫生行政主管部门通报。\n接到通报的省、自治区、直辖市人民政府卫生行政主管部门，必要时应当及时通知本行政区域内的医疗卫生机构。\n县级以上地方人民政府有关部门，已经发生或者发现可能引起突发事件的情形时，应当及时向同级人民政府卫生行政主管部门通报。\n第二十四条 国家建立突发事件举报制度，公布统一的突发事件报告、举报电话。\n任何单位和个人有权向人民政府及其有关部门报告突发事件隐患，有权向上级人民政府及其有关部门举报地方人民政府及其有关部门不履行突发事件应急处理职责，或者不按照规定履行职责的情况。接到报告、举报的有关人民政府及其有关部门，应当立即组织对突发事件隐患、不履行或者不按照规定履行突发事件应急处理职责的情况进行调查处理。\n对举报突发事件有功的单位和个人，县级以上各级人民政府及其有关部门应当予以奖励。\n第二十五条 国家建立突发事件的信息发布制度。\n国务院卫生行政主管部门负责向社会发布突发事件的信息。必要时，可以授权省、自治区、直辖市人民政府卫生行政主管部门向社会发布本行政区域内突发事件的信息。\n信息发布应当及时、准确、全面。","level":1},{"name":"第四章 应急处理","text":"第二十六条 突发事件发生后，卫生行政主管部门应当组织专家对突发事件进行综合评估，初步判断突发事件的类型，提出是否启动突发事件应急预案的建议。\n第二十七条 在全国范围内或者跨省、自治区、直辖市范围内启动全国突发事件应急预案，由国务院卫生行政主管部门报国务院批准后实施。省、自治区、直辖市启动突发事件应急预案，由省、自治区、直辖市人民政府决定，并向国务院报告。\n第二十八条 全国突发事件应急处理指挥部对突发事件应急处理工作进行督察和指导，地方各级人民政府及其有关部门应当予以配合。\n省、自治区、直辖市突发事件应急处理指挥部对本行政区域内突发事件应急处理工作进行督察和指导。\n第二十九条 省级以上人民政府卫生行政主管部门或者其他有关部门指定的突发事件应急处理专业技术机构，负责突发事件的技术调查、确证、处置、控制和评价工作。\n第三十条 国务院卫生行政主管部门对新发现的突发传染病，根据危害程度、流行强度，依照《中华人民共和国传染病防治法》的规定及时宣布为法定传染病；宣布为甲类传染病的，由国务院决定。\n第三十一条 应急预案启动前，县级以上各级人民政府有关部门应当根据突发事件的实际情况，做好应急处理准备，采取必要的应急措施。\n应急预案启动后，突发事件发生地的人民政府有关部门，应当根据预案规定的职责要求，服从突发事件应急处理指挥部的统一指挥，立即到达规定岗位，采取有关的控制措施。\n医疗卫生机构、监测机构和科学研究机构，应当服从突发事件应急处理指挥部的统一指挥，相互配合、协作，集中力量开展相关的科学研究工作。\n第三十二条 突发事件发生后，国务院有关部门和县级以上地方人民政府及其有关部门，应当保证突发事件应急处理所需的医疗救护设备、救治药品、医疗器械等物资的生产、供应；铁路、交通、民用航空行政主管部门应当保证及时运送。\n第三十三条 根据突发事件应急处理的需要，突发事件应急处理指挥部有权紧急调集人员、储备的物资、交通工具以及相关设施、设备；必要时，对人员进行疏散或者隔离，并可以依法对传染病疫区实行封锁。\n第三十四条 突发事件应急处理指挥部根据突发事件应急处理的需要，可以对食物和水源采取控制措施。\n县级以上地方人民政府卫生行政主管部门应当对突发事件现场等采取控制措施，宣传突发事件防治知识，及时对易受感染的人群和其他易受损害的人群采取应急接种、预防性投药、群体防护等措施。\n第三十五条 参加突发事件应急处理的工作人员，应当按照预案的规定，采取卫生防护措施，并在专业人员的指导下进行工作。\n第三十六条 国务院卫生行政主管部门或者其他有关部门指定的专业技术机构，有权进入突发事件现场进行调查、采样、技术分析和检验，对地方突发事件的应急处理工作进行技术指导，有关单位和个人应当予以配合；任何单位和个人不得以任何理由予以拒绝。\n第三十七条 对新发现的突发传染病、不明原因的群体性疾病、重大食物和职业中毒事件，国务院卫生行政主管部门应当尽快组织力量制定相关的技术标准、规范和控制措施。\n第三十八条 交通工具上发现根据国务院卫生行政主管部门的规定需要采取应急控制措施的传染病病人、疑似传染病病人，其负责人应当以最快的方式通知前方停靠点，并向交通工具的营运单位报告。交通工具的前方停靠点和营运单位应当立即向交通工具营运单位行政主管部门和县级以上地方人民政府卫生行政主管部门报告。卫生行政主管部门接到报告后，应当立即组织有关人员采取相应的医学处置措施。\n交通工具上的传染病病人密切接触者，由交通工具停靠点的县级以上各级人民政府卫生行政主管部门或者铁路、交通、民用航空行政主管部门，根据各自的职责，依照传染病防治法律、行政法规的规定，采取控制措施。\n涉及国境口岸和入出境的人员、交通工具、货物、集装箱、行李、邮包等需要采取传染病应急控制措施的，依照国境卫生检疫法律、行政法规的规定办理。\n第三十九条 医疗卫生机构应当对因突发事件致病的人员提供医疗救护和现场救援，对就诊病人必须接诊治疗，并书写详细、完整的病历记录；对需要转送的病人，应当按照规定将病人及其病历记录的复印件转送至接诊的或者指定的医疗机构。\n医疗卫生机构内应当采取卫生防护措施，防止交叉感染和污染。\n医疗卫生机构应当对传染病病人密切接触者采取医学观察措施，传染病病人密切接触者应当予以配合。\n医疗机构收治传染病病人、疑似传染病病人，应当依法报告所在地的疾病预防控制机构。接到报告的疾病预防控制机构应当立即对可能受到危害的人员进行调查，根据需要采取必要的控制措施。\n第四十条 传染病暴发、流行时，街道、乡镇以及居民委员会、村民委员会应当组织力量，团结协作，群防群治，协助卫生行政主管部门和其他有关部门、医疗卫生机构做好疫情信息的收集和报告、人员的分散隔离、公共卫生措施的落实工作，向居民、村民宣传传染病防治的相关知识。\n第四十一条 对传染病暴发、流行区域内流动人口，突发事件发生地的县级以上地方人民政府应当做好预防工作，落实有关卫生控制措施；对传染病病人和疑似传染病病人，应当采取就地隔离、就地观察、就地治疗的措施。对需要治疗和转诊的，应当依照本条例第三十九条第一款的规定执行。\n第四十二条 有关部门、医疗卫生机构应当对传染病做到早发现、早报告、早隔离、早治疗，切断传播途径，防止扩散。\n第四十三条 县级以上各级人民政府应当提供必要资金，保障因突发事件致病、致残的人员得到及时、有效的救治。具体办法由国务院财政部门、卫生行政主管部门和劳动保障行政主管部门制定。\n第四十四条 在突发事件中需要接受隔离治疗、医学观察措施的病人、疑似病人和传染病病人密切接触者在卫生行政主管部门或者有关机构采取医学措施时应当予以配合；拒绝配合的，由公安机关依法协助强制执行。","level":1},{"name":"第五章 法律责任","text":"第四十五条 县级以上地方人民政府及其卫生行政主管部门未依照本条例的规定履行报告职责，对突发事件隐瞒、缓报、谎报或者授意他人隐瞒、缓报、谎报的，对政府主要领导人及其卫生行政主管部门主要负责人，依法给予降级或者撤职的行政处分；造成传染病传播、流行或者对社会公众健康造成其他严重危害后果的，依法给予开除的行政处分；构成犯罪的，依法追究刑事责任。\n第四十六条 国务院有关部门、县级以上地方人民政府及其有关部门未依照本条例的规定，完成突发事件应急处理所需要的设施、设备、药品和医疗器械等物资的生产、供应、运输和储备的，对政府主要领导人和政府部门主要负责人依法给予降级或者撤职的行政处分；造成传染病传播、流行或者对社会公众健康造成其他严重危害后果的，依法给予开除的行政处分；构成犯罪的，依法追究刑事责任。\n第四十七条 突发事件发生后，县级以上地方人民政府及其有关部门对上级人民政府有关部门的调查不予配合，或者采取其他方式阻碍、干涉调查的，对政府主要领导人和政府部门主要负责人依法给予降级或者撤职的行政处分；构成犯罪的，依法追究刑事责任。\n第四十八条 县级以上各级人民政府卫生行政主管部门和其他有关部门在突发事件调查、控制、医疗救治工作中玩忽职守、失职、渎职的，由本级人民政府或者上级人民政府有关部门责令改正、通报批评、给予警告；对主要负责人、负有责任的主管人员和其他责任人员依法给予降级、撤职的行政处分；造成传染病传播、流行或者对社会公众健康造成其他严重危害后果的，依法给予开除的行政处分；构成犯罪的，依法追究刑事责任。\n第四十九条 县级以上各级人民政府有关部门拒不履行应急处理职责的，由同级人民政府或者上级人民政府有关部门责令改正、通报批评、给予警告；对主要负责人、负有责任的主管人员和其他责任人员依法给予降级、撤职的行政处分；造成传染病传播、流行或者对社会公众健康造成其他严重危害后果的，依法给予开除的行政处分；构成犯罪的，依法追究刑事责任。\n第五十条 医疗卫生机构有下列行为之一的，由卫生行政主管部门责令改正、通报批评、给予警告；情节严重的，吊销《医疗机构执业许可证》；对主要负责人、负有责任的主管人员和其他直接责任人员依法给予降级或者撤职的纪律处分；造成传染病传播、流行或者对社会公众健康造成其他严重危害后果，构成犯罪的，依法追究刑事责任：\n(一)未依照本条例的规定履行报告职责，隐瞒、缓报或者谎报的；\n(二)未依照本条例的规定及时采取控制措施的；\n(三)未依照本条例的规定履行突发事件监测职责的；\n(四)拒绝接诊病人的；\n(五)拒不服从突发事件应急处理指挥部调度的。\n第五十一条 在突发事件应急处理工作中，有关单位和个人未依照本条例的规定履行报告职责，隐瞒、缓报或者谎报，阻碍突发事件应急处理工作人员执行职务，拒绝国务院卫生行政主管部门或者其他有关部门指定的专业技术机构进入突发事件现场，或者不配合调查、采样、技术分析和检验的，对有关责任人员依法给予行政处分或者纪律处分；触犯《中华人民共和国治安管理处罚法》，构成违反治安管理行为的，由公安机关依法予以处罚；构成犯罪的，依法追究刑事责任。\n第五十二条 在突发事件发生期间，散布谣言、哄抬物价、欺骗消费者，扰乱社会秩序、市场秩序的，由公安机关或者工商行政管理部门依法给予行政处罚；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第五十三条 中国人民解放军、武装警察部队医疗卫生机构参与突发事件应急处理的，依照本条例的规定和军队的相关规定执行。\n第五十四条 本条例自公布之日起施行。","level":1}]},{"id":"n0359","sections":[{"name":"","text":"中华人民共和国城镇集体所有制企业条例\n(1991年9月9日中华人民共和国国务院令第88号发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2016年2月6日《国务院关于修改部分行政法规的决定》第二次修订)","level":0},{"name":"第一章 总则","text":"第一条 为了保障城镇集体所有制经济的巩固和发展，明确城镇集体所有制企业的权利和义务，维护其合法权益，制定本条例。\n第二条 本条例适用于城镇的各种行业、各种组织形式的集体所有制企业，但乡村农民集体举办的企业除外。\n第三条 城镇集体所有制经济是我国社会主义公有制经济的一个基本组成部分，国家鼓励和扶持城镇集体所有制经济的发展。\n第四条 城镇集体所有制企业(以下简称集体企业)是财产属于劳动群众集体所有、实行共同劳动、在分配方式上以按劳分配为主体的社会主义经济组织。\n前款所称劳动群众集体所有，应当符合下列中任一项的规定：\n(一)本集体企业的劳动群众集体所有；\n(二)集体企业的联合经济组织范围内的劳动群众集体所有；\n(三)投资主体为两个或者两个以上的集体企业，其中前(一)、(二)项劳动群众集体所有的财产应当占主导地位。本项所称主导地位，是指劳动群众集体所有的财产占企业全部财产的比例，一般情况下应不低于51%，特殊情况经过原审批部门批准，可以适当降低。\n第五条 集体企业应当遵循的原则是：自愿组合、自筹资金，独立核算、自负盈亏，自主经营、民主管理，集体积累、自主支配，按劳分配、入股分红。\n集体企业应当发扬艰苦奋斗、勤俭建国的精神，走互助合作、共同富裕的道路。\n第六条 集体企业依法取得法人资格，以其全部财产独立承担民事责任。\n集体企业的财产及其合法权益受国家法律保护，不受侵犯。\n第七条 集体企业的任务是：根据市场和社会需求，在国家计划指导下，发展商品生产，扩大商品经营，开展社会服务，创造财富，增加积累，不断提高经济效益和社会效益，繁荣社会主义经济。\n第八条 集体企业的职工是企业的主人，依照法律、法规和集体企业章程行使管理企业的权力。集体企业职工的合法权益受法律保护。\n第九条 集体企业依照法律规定实行民主管理。职工(代表)大会是集体企业的权力机构，由其选举和罢免企业管理人员，决定经营管理的重大问题。\n集体企业实行厂长(经理)负责制。\n集体企业职工的民主管理权和厂长(经理)依法行使职权，均受法律保护。\n第十条 中国共产党在集体企业的基层组织是集体企业的政治领导核心，领导企业的思想政治工作，保证监督党和国家的方针、政策在本企业的贯彻执行。\n第十一条 集体企业的工会维护职工的合法权益，依法独立自主地开展工作，组织职工参加民主管理和民主监督。","level":1},{"name":"第二章 集体企业的设立、变更和终止","text":"第十二条 集体企业的设立必须具备下列条件：\n(一)有企业名称、组织机构和企业章程；\n(二)有固定的生产经营场所、必要的设施并符合规定的安全卫生条件；\n(三)有符合国家规定并与其生产经营和服务规模相适应的资金数额和从业人员；\n(四)有明确的经营范围；\n(五)能够独立承担民事责任；\n(六)法律、法规规定的其他条件。\n第十三条 集体企业章程必须载明下列事项：\n(一)企业名称和住所；\n(二)经营范围和经营方式；\n(三)注册资金；\n(四)资金来源和投资方式；\n(五)收入分配方式；\n(六)组织机构及其职权和议事规则；\n(七)职工加入和退出企业的条件和程序；\n(八)职工的权利和义务；\n(九)法定代表人的产生程序及其职权范围；\n(十)企业终止的条件和程序；\n(十一)章程的修订程序；\n(十二)章程订立日期；\n(十三)需要明确的其他事项。\n第十四条 设立集体企业应当经省、自治区、直辖市人民政府规定的审批部门批准。\n设立集体企业的审批部门，法律、法规有专门规定的，从其规定。\n集体企业应当在核准登记的经营范围内从事生产经营活动。\n第十五条 集体企业的合并、分立、停业、迁移或者主要登记事项的变更，必须符合国家的有关规定，由企业提出申请，报经原审批部门批准。\n第十六条 集体企业的合并和分立，应当遵照自愿平等的原则，由有关各方依法签订协议，处理好债权债务、其他财产关系和遗留问题，妥善安置企业人员。\n合并、分立前的集体企业的权利和义务，由合并、分立后的法人享有和承担。\n第十七条 集体企业有下列原因之一的，应当予以终止：\n(一)企业无法继续经营而申请解散，经原审批部门批准；\n(二)依法被撤销；\n(三)依法宣告破产；\n(四)其他原因。\n第十八条 集体企业终止，应当依照国家有关规定清算企业财产。企业财产按下列顺序清偿各种债务和费用：\n(一)清算工作所需各项费用；\n(二)所欠职工工资和劳动保险费用；\n(三)所欠税款；\n(四)所欠银行和信用合作社贷款以及其他债务。\n不足清偿同一顺序的清偿要求的，按照比例分配。\n第十九条 集体企业财产清算后的剩余财产，按照下列办法处理：\n(一)有国家、本企业外的单位和个人以及本企业职工个人投资入股的，应当依照其投资入股金额占企业总资产的比例，从企业剩余财产中按相同的比例偿还；\n(二)其余财产，由企业上级管理机构作为该企业职工待业和养老救济、就业安置和职业培训等费用，专款专用，不得挪作他用。\n第二十条 集体企业终止，必须依照《中华人民共和国企业法人登记管理条例》的规定办理注销登记并公告。","level":1},{"name":"第三章 集体企业的权利和义务","text":"第二十一条 集体企业在国家法律、法规的规定范围内享有下列权利：\n(一)对其全部财产享有占有、使用、收益和处分的权利，拒绝任何形式的平调；\n(二)自主安排生产、经营、服务活动；\n(三)除国家规定由物价部门和有关主管部门控制价格的以外，企业有权自行确定产品价格、劳务价格；\n(四)企业有权依照国家规定与外商谈判并签订合同，提取和使用分成的外汇收入；\n(五)依照国家信贷政策的规定向有关专业银行申请贷款；\n(六)依照国家规定确定适合本企业情况的经济责任制形式、工资形式和奖金、分红办法；\n(七)享受国家政策规定的各种优惠待遇；\n(八)吸收职工和其他企业、事业单位、个人集资入股，与其他企业、事业单位联营，向其他企业、事业单位投资，持有其他企业的股份；\n(九)按照国家规定决定本企业的机构设置、人员编制、劳动组织形式和用工办法，录用和辞退职工；\n(十)奖惩职工。\n第二十二条 集体企业应当承担下列义务：\n(一)遵守国家法律、法规，接受国家计划指导；\n(二)依法缴纳税金和交纳费用；\n(三)依法履行合同；\n(四)改善经营管理，推进技术进步，提高经济效益；\n(五)保证产品质量和服务质量，对用户和消费者负责；\n(六)贯彻安全生产制度，落实劳动保护和环境保护措施；\n(七)做好企业内部的安全保卫工作；\n(八)维护职工合法权益，尊重职工的民主管理权利，改善劳动条件，做好计划生育工作，提高职工物质文化生活水平；\n(九)加强对职工的思想政治教育、法制教育、国防教育、科学文化教育和技术业务培训，提高职工队伍素质。\n第二十三条 集体企业有权按照国家规定自愿组建、参加和退出集体企业的联合经济组织，并依照该联合经济组织的章程规定，享受权利，承担义务。","level":1},{"name":"第四章 职工和职工(代表)大会","text":"第二十四条 凡本人提出申请，承认并遵守集体企业章程，被企业招收，即可成为该集体企业的职工。\n第二十五条 职工依照法律、法规的规定，在集体企业内享有下列权利：\n(一)企业各级管理职务的选举权和被选举权；\n(二)参加企业民主管理，监督企业各项活动和管理人员的工作；\n(三)参加劳动并享受劳动报酬、劳动保护、劳动保险、医疗保健和休息、休假的权利；\n(四)接受职业技术教育和培训，按照国家规定评定业务技术职称；\n(五)辞职；\n(六)享受退休养老待遇；\n(七)其他权利。\n第二十六条 职工应当履行下列义务：\n(一)遵守国家的法律、法规和集体企业的规章制度、劳动纪律，以企业主人的态度从事劳动，做好本职工作；\n(二)执行职工(代表)大会决议，完成任务；\n(三)维护企业的集体利益；\n(四)努力学习政治、文化和科技知识，不断提高自身素质；\n(五)法律、法规和企业章程规定的其他义务。\n第二十七条 集体企业必须建立、健全职工(代表)大会制度：\n(一)100人以下的集体企业，建立职工大会制度；\n(二)300人以上的集体企业建立职工代表大会制度；\n(三)100人以上300人以下的集体企业，建立职工大会或者职工代表大会制度，由企业自定。\n职工代表大会代表由职工选举产生。代表应当是思想进步、工作积极、联系群众、有参加民主管理能力的职工。\n第二十八条 集体企业的职工(代表)大会在国家法律、法规的规定范围内行使下列职权：\n(一)制定、修改集体企业章程；\n(二)按照国家规定选举、罢免、聘用、解聘厂长(经理)、副厂长(副经理)；\n(三)审议厂长(经理)提交的各项议案，决定企业经营管理的重大问题；\n(四)审议并决定企业职工工资形式、工资调整方案、奖金和分红方案、职工住宅分配方案和其他有关职工生活福利的重大事项；\n(五)审议并决定企业的职工奖惩办法和其他重要规章制度；\n(六)法律、法规和企业章程规定的其他职权。\n第二十九条 职工(代表)大会依照企业章程规定定期召开，但每年不得少于两次。\n第三十条 集体企业的职工代表大会，可以设立常设机构，负责职工代表大会闭会期间的工作。\n常设机构的人员组成、产生方式、职权范围及名称，由集体企业职工代表大会规定，报上级管理机构备案。","level":1},{"name":"第五章 厂长(经理)","text":"第三十一条 集体企业实行厂长(经理)负责制。厂长(经理)对企业职工(代表)大会负责，是集体企业的法定代表人。\n第三十二条 厂长(经理)由企业职工代表大会选举或者招聘产生。选举和招聘的具体办法，由省、自治区、直辖市人民政府规定。\n由集体企业联合经济组织投资开办的集体企业，其厂长(经理)可以由该联合经济组织任免。\n投资主体多元化的集体企业，其中国家投资达到一定比例的，其厂长(经理)可以由上级管理机构按照国家有关规定任免。\n第三十三条 厂长(经理)应当具备下列条件：\n(一)懂得有关法律、法规和方针、政策，坚持企业的社会主义经营方向；\n(二)熟悉本行业业务，善于经营管理，有组织领导能力；\n(三)热爱集体、廉洁奉公，联系群众，有民主作风；\n(四)法律、法规规定的其他条件。\n第三十四条 厂长(经理)在法律、法规的规定范围内行使下列职权：\n(一)领导和组织企业日常生产经营和行政工作；\n(二)主持编制并向职工(代表)大会提出企业的中长期发展规划、年度生产经营计划、固定资产投资方案；\n(三)主持编制并向职工(代表)大会提出企业机构设置的方案，决定劳动组织的调整方案；\n(四)按照国家规定任免或者聘任、解聘企业中层行政领导干部，但法律、法规另有规定的，从其规定；\n(五)提出企业年度财务预算、决算方案和利润分配方案；\n(六)提出企业的经济责任制方案、工资调整方案、劳动保护措施方案、奖惩办法和其他重要的规章制度；\n(七)奖惩职工；\n(八)遇到特殊情况时，提出召开职工(代表)大会的建议；\n(九)企业章程规定的其他职权。\n第三十五条 厂长(经理)有下列职责：\n(一)贯彻执行党和国家的方针、政策，遵守国家的法律、法规，执行职工(代表)大会的决议；\n(二)组织职工完成企业生产经营任务和各项经济技术指标，推进企业技术进步，提高经济效益，增强企业发展能力；\n(三)严格遵守财经纪律，坚持民主理财，定期向职工公布财务账目；\n(四)保护企业的合法权益和职工在企业内的正当权利；\n(五)办好职工生活福利和逐步开展职工养老、待业等保险；\n(六)组织落实安全卫生措施，实现安全文明生产；\n(七)定期向本企业职工(代表)大会报告工作，听取意见，并接受监督；\n(八)法律、法规和企业章程规定的其他职责。","level":1},{"name":"第六章 财产管理和收益分配","text":"第三十六条 集体企业应当按照本章规定进行清产核资，明确其财产所有权的归属。\n第三十七条 集体企业的公共积累，归本企业劳动群众集体所有。\n第三十八条 集体企业的联合经济组织的投资，归该联合经济组织范围内的劳动群众集体所有。\n集体企业联合经济组织设立的互助合作基金，应当主要用于该组织范围内发展生产和推进共同富裕。\n第三十九条 在企业、事业单位、社会团体等扶持下设立的集体企业，其扶持资金可按下列办法之一处理：\n(一)作为企业向扶持单位的借用款，按双方约定的方法和期限由企业归还扶持单位；\n(二)作为扶持单位对企业的投资，按其投资占企业总资产的比例，参与企业的利润分配。\n企业、事业单位、社会团体等的扶持资金的来源，必须符合国家财政主管部门的有关规定。\n企业、事业单位、社会团体等与其扶持设立的集体企业，应当明确划清产权和财务关系。扶持单位不得干预集体企业的经营管理活动，集体企业也不得依赖扶持单位。\n第四十条 职工股金，归职工个人所有。\n第四十一条 集体企业外的单位和个人的投资，归投资者所有。\n第四十二条 职工股金和集体企业吸收的各种投资，投资者可以依法转让或者继承。\n第四十三条 集体企业必须保证财产的完整性，合理使用、有效经营企业的财产。\n第四十四条 集体企业的收益分配，必须遵循兼顾国家、集体和个人三者利益的原则。\n第四十五条 集体企业必须执行国家有关财务、会计制度，接受审计监督，加强企业内部的财务管理。\n第四十六条 集体企业的税后利润，由企业依法自主支配。企业应当按照国家规定确定公积金、公益金、劳动分红和股金分红的比例。\n第四十七条 集体企业职工的劳动报酬必须坚持按劳分配的原则。具体分配形式和办法由企业自行确定。\n第四十八条 集体企业的股金分红要同企业盈亏相结合。企业盈利，按股分红；企业亏损，在未弥补亏损之前，不得分红。\n第四十九条 集体企业必须依照国家规定提取职工养老、待业等保险基金。职工养老、待业等保险基金按国家规定在征收所得税前提取，专项储存，专款专用。","level":1},{"name":"第七章 集体企业和政府的关系","text":"第五十条 各级人民政府应当把发展城镇集体经济纳入各级政府的国民经济和社会发展计划，从各方面给予扶持和指导，保障城镇集体经济的健康发展。\n第五十一条 国务院城镇集体经济的主管机构，负责全国城镇集体经济的宏观指导和管理，其主要职责是：拟订城镇集体经济的发展政策和法律法规，协调全国城镇集体经济发展中的重大问题，组织有关方面监督、检查集体企业政策、法规的执行情况。\n第五十二条 市(含县级市，下同)以上人民政府应当根据城镇集体经济发展的需要，确定城镇集体企业的指导部门，加强对集体企业的政策指导，协调当地城镇集体经济发展中的问题，组织有关方面监督、检查集体企业政策、法规的执行情况。\n第五十三条 政府有关行业管理部门，应当依照法律、法规的规定，在各自的职责范围内，负责本行业集体企业的行业指导和管理工作。\n第五十四条 各级人民政府的其他有关部门，依法对集体企业进行监督和提供服务。\n第五十五条 国家保护集体企业的合法权益。\n任何政府部门及其他单位和个人不得改变集体企业的集体所有制性质和损害集体企业的财产所有权，不得向集体企业摊派人力、物力、财力，不得干预集体企业的生产经营和民主管理。","level":1},{"name":"第八章 法律责任","text":"第五十六条 集体企业有下列行为之一的，由工商行政管理机关依照国家有关法律、法规的规定给予行政处罚：\n(一)登记时弄虚作假或者不按规定申请变更登记的；\n(二)违反核准登记事项或者超越核准登记的经营范围从事经营活动的；\n(三)利用分立、合并、终止和清算等行为抽逃资金、隐匿和私分财产的；\n(四)其他违法行为。\n第五十七条 集体企业因生产、销售伪劣商品，给用户和消费者造成财产损失和人身伤害的，应当承担赔偿责任；构成犯罪的，对负有直接责任的集体企业领导人员和其他直接责任人员依法追究刑事责任。\n第五十八条 任何单位或者个人违反本条例规定，向集体企业摊派或者侵吞、挪用集体企业财产的，必须赔偿。对负有直接责任的主管人员和其他直接责任人员，由有关主管机关根据情节轻重，给予行政处分；构成犯罪的，依法追究刑事责任。\n第五十九条 集体企业领导人员滥用职权，侵犯职工合法权益，情节严重的，由上级管理机构按照干部管理权限给予行政处分；滥用职权，假公济私，对职工进行报复陷害的，依法追究刑事责任。\n第六十条 集体企业的领导人员或者政府有关部门的工作人员，因工作过失给企业造成损失的，由企业的上级管理机构或者政府有关部门按照干部的管理权限给予行政处分。\n集体企业的领导人员和政府有关部门的工作人员玩忽职守，致使集体企业财产、利益遭受重大损失，构成犯罪的，依法追究刑事责任。\n第六十一条 集体企业违反本条例有关集体企业领导人员的产生、罢免条件和程序规定的，上级管理机构应当予以纠正，并追究直接责任人员的行政责任。\n集体企业上级管理机构违反本条例有关集体企业领导人员产生、罢免条件和程序规定的，其上一级主管部门应当予以纠正；情节严重的，应当追究直接责任人员的行政责任。\n第六十二条 扰乱集体企业的秩序，致使生产、营业、工作不能正常进行或者无法进行的，由公安机关依据《中华人民共和国治安管理处罚法》予以处罚；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第九章 附则","text":"第六十三条 集体企业联合经济组织的组建和管理办法，另行制定。\n第六十四条 集体所有制的各类公司的管理，按照国家有关公司的法律、法规执行。\n第六十五条 城镇中的文教、卫生、科研等集体所有制事业单位参照本条例执行。\n供销合作社的管理办法，另行制定。\n第六十六条 劳动就业服务性集体企业应当遵循本条例规定的原则，具体管理办法按国务院发布的《劳动就业服务企业管理规定》执行。\n集中安置残疾人员的福利性集体企业的管理办法，根据本条例的原则另行制定。\n第六十七条 军队扶持开办的集体企业的管理办法，由中国人民解放军总后勤部根据本条例规定的原则另行制定。\n第六十八条 各省、自治区、直辖市人民政府和国务院各行业主管部门，可以根据本条例并结合本地区、本行业的具体情况，制定本条例的实施细则。\n第六十九条 本条例自1992年1月1日起施行。","level":1}]},{"id":"n0360","sections":[{"name":"","text":"流动人口计划生育工作条例\n(2009年4月29日国务院第60次常务会议通过 2009年5月11日中华人民共和国国务院令第555号公布 自2009年10月1日起施行)\n第一条 为了加强流动人口计划生育工作，寓管理于服务之中，维护流动人口的合法权益，稳定低生育水平，根据《中华人民共和国人口与计划生育法》，制定本条例。\n第二条 本条例所称流动人口，是指离开户籍所在地的县、市或者市辖区，以工作、生活为目的异地居住的成年育龄人员。但是，下列人员除外：\n(一)因出差、就医、上学、旅游、探亲、访友等事由异地居住、预期将返回户籍所在地居住的人员；\n(二)在直辖市、设区的市行政区域内区与区之间异地居住的人员。\n第三条 县级以上地方人民政府领导本行政区域内流动人口计划生育工作，将流动人口计划生育工作纳入本地经济社会发展规划，并提供必要的保障；建立健全流动人口计划生育工作协调机制，组织协调有关部门对流动人口计划生育工作实行综合管理；实行目标管理责任制，对有关部门承担的流动人口计划生育工作进行考核、监督。\n第四条 流动人口计划生育工作由流动人口户籍所在地和现居住地的人民政府共同负责，以现居住地人民政府为主，户籍所在地人民政府予以配合。\n第五条 国务院人口和计划生育部门主管全国流动人口计划生育工作，制定流动人口计划生育工作规划并组织实施；建立流动人口计划生育信息管理系统，实现流动人口户籍所在地和现居住地计划生育信息共享，并与相关部门有关人口的信息管理系统实现信息共享。\n县级以上地方人民政府人口和计划生育部门主管本行政区域内流动人口计划生育工作，落实本级人民政府流动人口计划生育管理和服务措施；组织实施流动人口计划生育工作检查和考核；建立流动人口计划生育信息通报制度，汇总、通报流动人口计划生育信息；受理并及时处理与流动人口计划生育工作有关的举报，保护流动人口相关权益。\n县级以上人民政府公安、民政、人力资源社会保障、住房城乡建设、卫生、价格等部门和县级以上工商行政管理部门在各自职责范围内，负责有关的流动人口计划生育工作。\n第六条 乡(镇)人民政府、街道办事处负责本管辖区域内流动人口计划生育工作，对流动人口实施计划生育管理，开展计划生育宣传教育；组织从事计划生育技术服务的机构指导流动人口中的育龄夫妻(以下称育龄夫妻)选择安全、有效、适宜的避孕节育措施，依法向育龄夫妻免费提供国家规定的基本项目的计划生育技术服务。\n流动人口现居住地和户籍所在地的乡(镇)人民政府、街道办事处之间建立流动人口计划生育信息通报制度，及时采集流动人口计划生育信息，运用流动人口计划生育信息管理系统核实、通报流动人口计划生育信息。\n第七条 流动人口中的成年育龄妇女(以下称成年育龄妇女)在离开户籍所在地前，应当凭本人居民身份证到户籍所在地的乡(镇)人民政府或者街道办事处办理婚育证明；已婚的，办理婚育证明还应当出示结婚证。婚育证明应当载明成年育龄妇女的姓名、年龄、公民身份号码、婚姻状况、配偶信息、生育状况、避孕节育情况等内容。\n流动人口户籍所在地的乡(镇)人民政府、街道办事处应当及时出具婚育证明。\n第八条 成年育龄妇女应当自到达现居住地之日起30日内提交婚育证明。成年育龄妇女可以向现居住地的乡(镇)人民政府或者街道办事处提交婚育证明，也可以通过村民委员会、居民委员会向现居住地的乡(镇)人民政府或者街道办事处提交婚育证明。\n流动人口现居住地的乡(镇)人民政府、街道办事处应当查验婚育证明，督促未办理婚育证明的成年育龄妇女及时补办婚育证明；告知流动人口在现居住地可以享受的计划生育服务和奖励、优待，以及应当履行的计划生育相关义务。\n村民委员会、居民委员会应当协助乡(镇)人民政府、街道办事处开展本条第二款规定的工作，做好流动人口婚育情况登记。\n第九条 流动人口现居住地的县级人民政府公安、民政、人力资源社会保障、卫生等部门和县级工商行政管理部门应当结合部门职责，将流动人口计划生育工作纳入相关管理制度；及时向所在地同级人口和计划生育部门通报在办理有关登记和证照等工作中了解的流动人口婚育证明办理情况等计划生育信息。\n接到通报的人口和计划生育部门应当及时会同乡(镇)人民政府、街道办事处落实流动人口计划生育管理和服务措施。\n第十条 流动人口在现居住地享受下列计划生育服务和奖励、优待：\n(一)免费参加有关人口与计划生育法律知识和生殖健康知识普及活动；\n(二)依法免费获得避孕药具，免费享受国家规定的其他基本项目的计划生育技术服务；\n(三)晚婚晚育或者在现居住地施行计划生育手术的，按照现居住地省、自治区、直辖市或者较大的市的规定，享受休假等；\n(四)实行计划生育的，按照流动人口现居住地省、自治区、直辖市或者较大的市的规定，在生产经营等方面获得支持、优惠，在社会救济等方面享受优先照顾。\n第十一条 流动人口现居住地的地方各级人民政府和县级以上地方人民政府有关部门应当采取措施，落实本条例第十条规定的流动人口计划生育服务和奖励、优待。\n流动人口户籍所在地的地方各级人民政府和县级以上地方人民政府有关部门应当依法落实法律、法规和规章规定的流动人口计划生育服务和奖励、优待。\n第十二条 育龄夫妻应当自觉落实计划生育避孕节育措施，接受户籍所在地和现居住地人民政府的计划生育管理。\n第十三条 流动人口现居住地从事计划生育技术服务的机构应当按照所在地省、自治区、直辖市或者较大的市的规定，为已婚育龄妇女出具避孕节育情况证明。\n流动人口现居住地的乡(镇)人民政府或者街道办事处应当根据已婚育龄妇女的避孕节育情况证明，及时向其户籍所在地的乡(镇)人民政府或者街道办事处通报流动人口避孕节育情况。流动人口户籍所在地的县级人民政府人口和计划生育部门、乡(镇)人民政府或者街道办事处不得要求已婚育龄妇女返回户籍所在地进行避孕节育情况检查。\n第十四条 流动人口现居住地的村民委员会、居民委员会应当协助所在地的乡(镇)人民政府或者街道办事处了解本村或者本居住地区流动人口计划生育情况，及时向乡(镇)人民政府或者街道办事处通报相关信息。\n房屋租赁中介机构、房屋的出租(借)人和物业服务企业等有关组织和个人在村民委员会、居民委员会了解流动人口计划生育情况时，应当如实提供相关信息。\n第十五条 用人单位应当做好本单位流动人口计划生育工作，依法落实法律、法规和规章规定的流动人口计划生育奖励、优待，接受所在地的乡(镇)人民政府或者街道办事处和县级以上地方人民政府人口和计划生育部门的监督、检查。\n第十六条 育龄夫妻生育第一个子女的，可以在现居住地的乡(镇)人民政府或者街道办事处办理生育服务登记。办理生育服务登记，应当提供下列证明材料：\n(一)夫妻双方的居民身份证；\n(二)结婚证；\n(三)女方的婚育证明和男方户籍所在地的乡(镇)人民政府或者街道办事处出具的婚育情况证明材料。\n育龄夫妻现居住地的乡(镇)人民政府或者街道办事处应当自收到女方的婚育证明和男方的婚育情况证明材料之日起7个工作日内，向育龄夫妻户籍所在地的乡(镇)人民政府或者街道办事处核实有关情况。育龄夫妻户籍所在地的乡(镇)人民政府或者街道办事处应当自接到核实要求之日起15个工作日内予以反馈。核查无误的，育龄夫妻现居住地的乡(镇)人民政府或者街道办事处应当在接到情况反馈后即时办理生育服务登记；情况有误、不予办理的，应当书面说明理由。\n现居住地的乡(镇)人民政府或者街道办事处应当自办理生育服务登记之日起15个工作日内向育龄夫妻户籍所在地的乡(镇)人民政府或者街道办事处通报办理结果。\n第十七条 出具婚育证明或者其他计划生育证明材料，不得收取任何费用。\n流动人口计划生育工作所需经费，按照国家有关规定予以保障。\n第十八条 地方各级人民政府和政府有关部门以及协助查验婚育证明的村民委员会、居民委员会及其工作人员，应当对涉及公民隐私的流动人口信息予以保密。\n第十九条 县级以上人民政府人口和计划生育部门未依照本条例的规定履行流动人口计划生育工作职责的，由本级人民政府或者上级人民政府人口和计划生育部门责令改正，通报批评；情节严重的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予处分。\n第二十条 流动人口户籍所在地的乡(镇)人民政府或者街道办事处在流动人口计划生育工作中有下列情形之一的，分别由乡(镇)人民政府的上级人民政府或者设立街道办事处的人民政府责令改正，通报批评；情节严重的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予处分：\n(一)未依照本条例规定为流动人口出具计划生育证明材料，出具虚假计划生育证明材料，或者出具计划生育证明材料收取费用的；\n(二)违反本条例规定，要求已婚育龄妇女返回户籍所在地进行避孕节育情况检查的；\n(三)未依法落实流动人口计划生育奖励、优待的；\n(四)未依照本条例规定向流动人口现居住地的乡(镇)人民政府、街道办事处反馈流动人口计划生育信息的；\n(五)违反本条例规定的其他情形。\n第二十一条 流动人口现居住地的乡(镇)人民政府或者街道办事处在流动人口计划生育工作中有下列情形之一的，分别由乡(镇)人民政府的上级人民政府或者设立街道办事处的人民政府责令改正，通报批评；情节严重的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予处分：\n(一)未依照本条例规定向育龄夫妻免费提供国家规定的基本项目的计划生育技术服务，或者未依法落实流动人口计划生育奖励、优待的；\n(二)未依照本条例规定查验婚育证明的；\n(三)未依照本条例规定为育龄夫妻办理生育服务登记，或者出具虚假计划生育证明材料，或者出具计划生育证明材料收取费用的；\n(四)未依照本条例规定向流动人口户籍所在地的乡(镇)人民政府、街道办事处通报流动人口计划生育信息的；\n(五)违反本条例规定的其他情形。\n第二十二条 流动人口现居住地的县级人民政府公安、民政、人力资源社会保障、卫生等部门和县级工商行政管理部门违反本条例第九条规定的，由本级人民政府或者上级人民政府主管部门责令改正，通报批评。\n第二十三条 流动人口未依照本条例规定办理婚育证明的，现居住地的乡(镇)人民政府或者街道办事处应当通知其在3个月内补办；逾期仍不补办或者拒不提交婚育证明的，由流动人口现居住地的乡(镇)人民政府或者街道办事处予以批评教育。\n第二十四条 用人单位违反本条例第十五条规定的，由所在地县级人民政府人口和计划生育部门责令改正，通报批评。\n房屋租赁中介机构、房屋的出租(借)人和物业服务企业等有关组织或者个人未依照本条例规定如实提供流动人口信息的，由所在地的乡(镇)人民政府或者街道办事处责令改正，予以批评教育。\n第二十五条 本条例自2009年10月1日起施行。1998年8月6日国务院批准、1998年9月22日原国家计划生育委员会发布的《流动人口计划生育工作管理办法》同时废止。","level":0}]},{"id":"n0361","sections":[{"name":"","text":"中华人民共和国文物保护法实施条例\n(2003年5月18日中华人民共和国国务院令第377号公布 根据2013年12月7日《国务院关于修改部分行政法规的决定》第一次修订 根据2016年2月6日《国务院关于修改部分行政法规的决定》第二次修订 根据2017年3月1日《国务院关于修改和废止部分行政法规的决定》第三次修订 根据2017年10月7日《国务院关于修改部分行政法规的决定》第四次修订)","level":0},{"name":"第一章 总则","text":"第一条 根据《中华人民共和国文物保护法》(以下简称文物保护法)，制定本实施条例。\n第二条 国家重点文物保护专项补助经费和地方文物保护专项经费，由县级以上人民政府文物行政主管部门、投资主管部门、财政部门按照国家有关规定共同实施管理。任何单位或者个人不得侵占、挪用。\n第三条 国有的博物馆、纪念馆、文物保护单位等的事业性收入，应当用于下列用途：\n(一)文物的保管、陈列、修复、征集；\n(二)国有的博物馆、纪念馆、文物保护单位的修缮和建设；\n(三)文物的安全防范；\n(四)考古调查、勘探、发掘；\n(五)文物保护的科学研究、宣传教育。\n第四条 文物行政主管部门和教育、科技、新闻出版、广播电视行政主管部门，应当做好文物保护的宣传教育工作。\n第五条 国务院文物行政主管部门和省、自治区、直辖市人民政府文物行政主管部门，应当制定文物保护的科学技术研究规划，采取有效措施，促进文物保护科技成果的推广和应用，提高文物保护的科学技术水平。\n第六条 有文物保护法第十二条所列事迹之一的单位或者个人，由人民政府及其文物行政主管部门、有关部门给予精神鼓励或者物质奖励。","level":1},{"name":"第二章 不可移动文物","text":"第七条 历史文化名城，由国务院建设行政主管部门会同国务院文物行政主管部门报国务院核定公布。\n历史文化街区、村镇，由省、自治区、直辖市人民政府城乡规划行政主管部门会同文物行政主管部门报本级人民政府核定公布。\n县级以上地方人民政府组织编制的历史文化名城和历史文化街区、村镇的保护规划，应当符合文物保护的要求。\n第八条 全国重点文物保护单位和省级文物保护单位自核定公布之日起1年内，由省、自治区、直辖市人民政府划定必要的保护范围，作出标志说明，建立记录档案，设置专门机构或者指定专人负责管理。\n设区的市、自治州级和县级文物保护单位自核定公布之日起1年内，由核定公布该文物保护单位的人民政府划定保护范围，作出标志说明，建立记录档案，设置专门机构或者指定专人负责管理。\n第九条 文物保护单位的保护范围，是指对文物保护单位本体及周围一定范围实施重点保护的区域。\n文物保护单位的保护范围，应当根据文物保护单位的类别、规模、内容以及周围环境的历史和现实情况合理划定，并在文物保护单位本体之外保持一定的安全距离，确保文物保护单位的真实性和完整性。\n第十条 文物保护单位的标志说明，应当包括文物保护单位的级别、名称、公布机关、公布日期、立标机关、立标日期等内容。民族自治地区的文物保护单位的标志说明，应当同时用规范汉字和当地通用的少数民族文字书写。\n第十一条 文物保护单位的记录档案，应当包括文物保护单位本体记录等科学技术资料和有关文献记载、行政管理等内容。\n文物保护单位的记录档案，应当充分利用文字、音像制品、图画、拓片、摹本、电子文本等形式，有效表现其所载内容。\n第十二条 古文化遗址、古墓葬、石窟寺和属于国家所有的纪念建筑物、古建筑，被核定公布为文物保护单位的，由县级以上地方人民政府设置专门机构或者指定机构负责管理。其他文物保护单位，由县级以上地方人民政府设置专门机构或者指定机构、专人负责管理；指定专人负责管理的，可以采取聘请文物保护员的形式。\n文物保护单位有使用单位的，使用单位应当设立群众性文物保护组织；没有使用单位的，文物保护单位所在地的村民委员会或者居民委员会可以设立群众性文物保护组织。文物行政主管部门应当对群众性文物保护组织的活动给予指导和支持。\n负责管理文物保护单位的机构，应当建立健全规章制度，采取安全防范措施；其安全保卫人员，可以依法配备防卫器械。\n第十三条 文物保护单位的建设控制地带，是指在文物保护单位的保护范围外，为保护文物保护单位的安全、环境、历史风貌对建设项目加以限制的区域。\n文物保护单位的建设控制地带，应当根据文物保护单位的类别、规模、内容以及周围环境的历史和现实情况合理划定。\n第十四条 全国重点文物保护单位的建设控制地带，经省、自治区、直辖市人民政府批准，由省、自治区、直辖市人民政府的文物行政主管部门会同城乡规划行政主管部门划定并公布。\n省级、设区的市、自治州级和县级文物保护单位的建设控制地带，经省、自治区、直辖市人民政府批准，由核定公布该文物保护单位的人民政府的文物行政主管部门会同城乡规划行政主管部门划定并公布。\n第十五条 承担文物保护单位的修缮、迁移、重建工程的单位，应当同时取得文物行政主管部门发给的相应等级的文物保护工程资质证书和建设行政主管部门发给的相应等级的资质证书。其中，不涉及建筑活动的文物保护单位的修缮、迁移、重建，应当由取得文物行政主管部门发给的相应等级的文物保护工程资质证书的单位承担。\n第十六条 申领文物保护工程资质证书，应当具备下列条件：\n(一)有取得文物博物专业技术职务的人员；\n(二)有从事文物保护工程所需的技术设备；\n(三)法律、行政法规规定的其他条件。\n第十七条 申领文物保护工程资质证书，应当向省、自治区、直辖市人民政府文物行政主管部门或者国务院文物行政主管部门提出申请。省、自治区、直辖市人民政府文物行政主管部门或者国务院文物行政主管部门应当自收到申请之日起30个工作日内作出批准或者不批准的决定。决定批准的，发给相应等级的文物保护工程资质证书；决定不批准的，应当书面通知当事人并说明理由。文物保护工程资质等级的分级标准和审批办法，由国务院文物行政主管部门制定。\n第十八条 文物行政主管部门在审批文物保护单位的修缮计划和工程设计方案前，应当征求上一级人民政府文物行政主管部门的意见。\n第十九条 危害全国重点文物保护单位安全或者破坏其历史风貌的建筑物、构筑物，由省、自治区、直辖市人民政府负责调查处理。\n危害省级、设区的市、自治州级、县级文物保护单位安全或者破坏其历史风貌的建筑物、构筑物，由核定公布该文物保护单位的人民政府负责调查处理。\n危害尚未核定公布为文物保护单位的不可移动文物安全的建筑物、构筑物，由县级人民政府负责调查处理。","level":1},{"name":"第三章 考古发掘","text":"第二十条 申请从事考古发掘的单位，取得考古发掘资质证书，应当具备下列条件：\n(一)有4名以上接受过考古专业训练且主持过考古发掘项目的人员；\n(二)有取得文物博物专业技术职务的人员；\n(三)有从事文物安全保卫的专业人员；\n(四)有从事考古发掘所需的技术设备；\n(五)有保障文物安全的设施和场所；\n(六)法律、行政法规规定的其他条件。\n第二十一条 申领考古发掘资质证书，应当向国务院文物行政主管部门提出申请。国务院文物行政主管部门应当自收到申请之日起30个工作日内作出批准或者不批准的决定。决定批准的，发给考古发掘资质证书；决定不批准的，应当书面通知当事人并说明理由。\n第二十二条 考古发掘项目实行项目负责人负责制度。\n第二十三条 配合建设工程进行的考古调查、勘探、发掘，由省、自治区、直辖市人民政府文物行政主管部门组织实施。跨省、自治区、直辖市的建设工程范围内的考古调查、勘探、发掘，由建设工程所在地的有关省、自治区、直辖市人民政府文物行政主管部门联合组织实施；其中，特别重要的建设工程范围内的考古调查、勘探、发掘，由国务院文物行政主管部门组织实施。\n建设单位对配合建设工程进行的考古调查、勘探、发掘，应当予以协助，不得妨碍考古调查、勘探、发掘。\n第二十四条 国务院文物行政主管部门应当自收到文物保护法第三十条第一款规定的发掘计划之日起30个工作日内作出批准或者不批准决定。决定批准的，发给批准文件；决定不批准的，应当书面通知当事人并说明理由。\n文物保护法第三十条第二款规定的抢救性发掘，省、自治区、直辖市人民政府文物行政主管部门应当自开工之日起10个工作日内向国务院文物行政主管部门补办审批手续。\n第二十五条 考古调查、勘探、发掘所需经费的范围和标准，按照国家有关规定执行。\n第二十六条 从事考古发掘的单位应当在考古发掘完成之日起30个工作日内向省、自治区、直辖市人民政府文物行政主管部门和国务院文物行政主管部门提交结项报告，并于提交结项报告之日起3年内向省、自治区、直辖市人民政府文物行政主管部门和国务院文物行政主管部门提交考古发掘报告。\n第二十七条 从事考古发掘的单位提交考古发掘报告后，经省、自治区、直辖市人民政府文物行政主管部门批准，可以保留少量出土文物作为科研标本，并应当于提交发掘报告之日起6个月内将其他出土文物移交给由省、自治区、直辖市人民政府文物行政主管部门指定的国有的博物馆、图书馆或者其他国有文物收藏单位收藏。","level":1},{"name":"第四章 馆藏文物","text":"第二十八条 文物收藏单位应当建立馆藏文物的接收、鉴定、登记、编目和档案制度，库房管理制度，出入库、注销和统计制度，保养、修复和复制制度。\n第二十九条 县级人民政府文物行政主管部门应当将本行政区域内的馆藏文物档案，按照行政隶属关系报设区的市、自治州级人民政府文物行政主管部门或者省、自治区、直辖市人民政府文物行政主管部门备案；设区的市、自治州级人民政府文物行政主管部门应当将本行政区域内的馆藏文物档案，报省、自治区、直辖市人民政府文物行政主管部门备案；省、自治区、直辖市人民政府文物行政主管部门应当将本行政区域内的一级文物藏品档案，报国务院文物行政主管部门备案。\n第三十条 文物收藏单位之间借用馆藏文物，借用人应当对借用的馆藏文物采取必要的保护措施，确保文物的安全。\n借用的馆藏文物的灭失、损坏风险，除当事人另有约定外，由借用该馆藏文物的文物收藏单位承担。\n第三十一条 国有文物收藏单位未依照文物保护法第三十六条的规定建立馆藏文物档案并将馆藏文物档案报主管的文物行政主管部门备案的，不得交换、借用馆藏文物。\n第三十二条 修复、复制、拓印馆藏二级文物和馆藏三级文物的，应当报省、自治区、直辖市人民政府文物行政主管部门批准；修复、复制、拓印馆藏一级文物的，应当报国务院文物行政主管部门批准。\n第三十三条 从事馆藏文物修复、复制、拓印的单位，应当具备下列条件：\n(一)有取得中级以上文物博物专业技术职务的人员；\n(二)有从事馆藏文物修复、复制、拓印所需的场所和技术设备；\n(三)法律、行政法规规定的其他条件。\n第三十四条 从事馆藏文物修复、复制、拓印，应当向省、自治区、直辖市人民政府文物行政主管部门提出申请。省、自治区、直辖市人民政府文物行政主管部门应当自收到申请之日起30个工作日内作出批准或者不批准的决定。决定批准的，发给相应等级的资质证书；决定不批准的，应当书面通知当事人并说明理由。\n第三十五条 为制作出版物、音像制品等拍摄馆藏文物的，应当征得文物收藏单位同意，并签署拍摄协议，明确文物保护措施和责任。文物收藏单位应当自拍摄工作完成后10个工作日内，将拍摄情况向文物行政主管部门报告。\n第三十六条 馆藏文物被盗、被抢或者丢失的，文物收藏单位应当立即向公安机关报案，并同时向主管的文物行政主管部门报告；主管的文物行政主管部门应当在接到文物收藏单位的报告后24小时内，将有关情况报告国务院文物行政主管部门。\n第三十七条 国家机关和国有的企业、事业组织等收藏、保管国有文物的，应当履行下列义务：\n(一)建立文物藏品档案制度，并将文物藏品档案报所在地省、自治区、直辖市人民政府文物行政主管部门备案；\n(二)建立、健全文物藏品的保养、修复等管理制度，确保文物安全；\n(三)文物藏品被盗、被抢或者丢失的，应当立即向公安机关报案，并同时向所在地省、自治区、直辖市人民政府文物行政主管部门报告。","level":1},{"name":"第五章 民间收藏文物","text":"第三十八条 文物收藏单位以外的公民、法人和其他组织，可以依法收藏文物，其依法收藏的文物的所有权受法律保护。\n公民、法人和其他组织依法收藏文物的，可以要求文物行政主管部门对其收藏的文物提供鉴定、修复、保管等方面的咨询。\n第三十九条 设立文物商店，应当具备下列条件：\n(一)有200万元人民币以上的注册资本；\n(二)有5名以上取得中级以上文物博物专业技术职务的人员；\n(三)有保管文物的场所、设施和技术条件；\n(四)法律、行政法规规定的其他条件。\n第四十条 设立文物商店，应当向省、自治区、直辖市人民政府文物行政主管部门提出申请。省、自治区、直辖市人民政府文物行政主管部门应当自收到申请之日起30个工作日内作出批准或者不批准的决定。决定批准的，发给批准文件；决定不批准的，应当书面通知当事人并说明理由。\n第四十一条 依法设立的拍卖企业，从事文物拍卖经营活动的，应当有5名以上取得高级文物博物专业技术职务的文物拍卖专业人员，并取得省、自治区、直辖市人民政府文物行政主管部门发给的文物拍卖许可证。\n第四十二条 依法设立的拍卖企业申领文物拍卖许可证，应当向省、自治区、直辖市人民政府文物行政主管部门提出申请。省、自治区、直辖市人民政府文物行政主管部门应当自收到申请之日起30个工作日内作出批准或者不批准的决定。决定批准的，发给文物拍卖许可证；决定不批准的，应当书面通知当事人并说明理由。\n第四十三条 文物商店购买、销售文物，经营文物拍卖的拍卖企业拍卖文物，应当记录文物的名称、图录、来源、文物的出卖人、委托人和买受人的姓名或者名称、住所、有效身份证件号码或者有效证照号码以及成交价格，并报省、自治区、直辖市人民政府文物行政主管部门备案。接受备案的文物行政主管部门应当依法为其保密，并将该记录保存75年。\n文物行政主管部门应当加强对文物商店和经营文物拍卖的拍卖企业的监督检查。","level":1},{"name":"第六章 文物出境进境","text":"第四十四条 国务院文物行政主管部门指定的文物进出境审核机构，应当有5名以上取得中级以上文物博物专业技术职务的文物进出境责任鉴定人员。\n第四十五条 运送、邮寄、携带文物出境，应当在文物出境前依法报文物进出境审核机构审核。文物进出境审核机构应当自收到申请之日起15个工作日内作出是否允许出境的决定。\n文物进出境审核机构审核文物，应当有3名以上文物博物专业技术人员参加；其中，应当有2名以上文物进出境责任鉴定人员。\n文物出境审核意见，由文物进出境责任鉴定员共同签署；对经审核，文物进出境责任鉴定员一致同意允许出境的文物，文物进出境审核机构方可作出允许出境的决定。\n文物出境审核标准，由国务院文物行政主管部门制定。\n第四十六条 文物进出境审核机构应当对所审核进出境文物的名称、质地、尺寸、级别，当事人的姓名或者名称、住所、有效身份证件号码或者有效证照号码，以及进出境口岸、文物去向和审核日期等内容进行登记。\n第四十七条 经审核允许出境的文物，由国务院文物行政主管部门发给文物出境许可证，并由文物进出境审核机构标明文物出境标识。经审核允许出境的文物，应当从国务院文物行政主管部门指定的口岸出境。海关查验文物出境标识后，凭文物出境许可证放行。\n经审核不允许出境的文物，由文物进出境审核机构发还当事人。\n第四十八条 文物出境展览的承办单位，应当在举办展览前6个月向国务院文物行政主管部门提出申请。国务院文物行政主管部门应当自收到申请之日起30个工作日内作出批准或者不批准的决定。决定批准的，发给批准文件；决定不批准的，应当书面通知当事人并说明理由。\n一级文物展品超过120件(套)的，或者一级文物展品超过展品总数的20%的，应当报国务院批准。\n第四十九条 一级文物中的孤品和易损品，禁止出境展览。禁止出境展览文物的目录，由国务院文物行政主管部门定期公布。\n未曾在国内正式展出的文物，不得出境展览。\n第五十条 文物出境展览的期限不得超过1年。因特殊需要，经原审批机关批准可以延期；但是，延期最长不得超过1年。\n第五十一条 文物出境展览期间，出现可能危及展览文物安全情形的，原审批机关可以决定中止或者撤销展览。\n第五十二条 临时进境的文物，经海关将文物加封后，交由当事人报文物进出境审核机构审核、登记。文物进出境审核机构查验海关封志完好无损后，对每件临时进境文物标明文物临时进境标识，并登记拍照。\n临时进境文物复出境时，应当由原审核、登记的文物进出境审核机构核对入境登记拍照记录，查验文物临时进境标识无误后标明文物出境标识，并由国务院文物行政主管部门发给文物出境许可证。\n未履行本条第一款规定的手续临时进境的文物复出境的，依照本章关于文物出境的规定办理。\n第五十三条 任何单位或者个人不得擅自剥除、更换、挪用或者损毁文物出境标识、文物临时进境标识。","level":1},{"name":"第七章 法律责任","text":"第五十四条 公安机关、工商行政管理、文物、海关、城乡规划、建设等有关部门及其工作人员，违反本条例规定，滥用审批权限、不履行职责或者发现违法行为不予查处的，对负有责任的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。\n第五十五条 违反本条例规定，未取得相应等级的文物保护工程资质证书，擅自承担文物保护单位的修缮、迁移、重建工程的，由文物行政主管部门责令限期改正；逾期不改正，或者造成严重后果的，处5万元以上50万元以下的罚款；构成犯罪的，依法追究刑事责任。\n违反本条例规定，未取得建设行政主管部门发给的相应等级的资质证书，擅自承担含有建筑活动的文物保护单位的修缮、迁移、重建工程的，由建设行政主管部门依照有关法律、行政法规的规定予以处罚。\n第五十六条 违反本条例规定，未取得资质证书，擅自从事馆藏文物的修复、复制、拓印活动的，由文物行政主管部门责令停止违法活动；没收违法所得和从事违法活动的专用工具、设备；造成严重后果的，并处1万元以上10万元以下的罚款；构成犯罪的，依法追究刑事责任。\n第五十七条 文物保护法第六十六条第二款规定的罚款，数额为200元以下。\n第五十八条 违反本条例规定，未经批准擅自修复、复制、拓印馆藏珍贵文物的，由文物行政主管部门给予警告；造成严重后果的，处2000元以上2万元以下的罚款；对负有责任的主管人员和其他直接责任人员依法给予行政处分。\n文物收藏单位违反本条例规定，未在规定期限内将文物拍摄情况向文物行政主管部门报告的，由文物行政主管部门责令限期改正；逾期不改正的，对负有责任的主管人员和其他直接责任人员依法给予行政处分。\n第五十九条 考古发掘单位违反本条例规定，未在规定期限内提交结项报告或者考古发掘报告的，由省、自治区、直辖市人民政府文物行政主管部门或者国务院文物行政主管部门责令限期改正；逾期不改正的，对负有责任的主管人员和其他直接责任人员依法给予行政处分。\n第六十条 考古发掘单位违反本条例规定，未在规定期限内移交文物的，由省、自治区、直辖市人民政府文物行政主管部门或者国务院文物行政主管部门责令限期改正；逾期不改正，或者造成严重后果的，对负有责任的主管人员和其他直接责任人员依法给予行政处分。\n第六十一条 违反本条例规定，文物出境展览超过展览期限的，由国务院文物行政主管部门责令限期改正；对负有责任的主管人员和其他直接责任人员依法给予行政处分。\n第六十二条 依照文物保护法第六十六条、第七十三条的规定，单位被处以吊销许可证行政处罚的，应当依法到工商行政管理部门办理变更登记或者注销登记；逾期未办理的，由工商行政管理部门吊销营业执照。\n第六十三条 违反本条例规定，改变国有的博物馆、纪念馆、文物保护单位等的事业性收入的用途的，对负有责任的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第八章 附则","text":"第六十四条 本条例自2003年7月1日起施行。","level":1}]},{"id":"n0362","sections":[{"name":"","text":"中华人民共和国民用航空器\n权利登记条例\n(1997年10月21日中华人民共和国国务院令第233号发布 自发布之日起施行)\n第一条 根据《中华人民共和国民用航空法》，制定本条例。\n第二条 在中华人民共和国办理民用航空器权利登记，应当遵守本条例。\n第三条 国务院民用航空主管部门主管民用航空器权利登记工作，设立民用航空器权利登记簿，统一记载民用航空器权利登记事项。\n同一民用航空器的权利登记事项应当记载于同一权利登记簿中。\n第四条 办理民用航空器所有权、占有权或者抵押权登记的，民用航空器权利人应当按照国务院民用航空主管部门的规定，分别填写民用航空器所有权、占有权或者抵押权登记申请书，并向国务院民用航空主管部门提交本条例第五条至第七条规定的相应文件。\n办理民用航空器优先权登记的，民用航空器优先权的债权人应当自援救或者保管维护工作终了之日起3个月内，按照国务院民用航空主管部门的规定，填写民用航空器优先权登记申请书，并向国务院民用航空主管部门提交足以证明其合法身份的文件和有关债权证明。\n第五条 办理民用航空器所有权登记的，民用航空器的所有人应当提交下列文件或者经核对无误的复印件：\n(一)民用航空器国籍登记证书；\n(二)民用航空器所有权取得的证明文件；\n(三)国务院民用航空主管部门要求提交的其他必要的有关文件。\n第六条 办理民用航空器占有权登记的，民用航空器的占有人应当提交下列文件或者经核对无误的复印件：\n(一)民用航空器国籍登记证书；\n(二)民用航空器所有权登记证书或者相应的所有权证明文件；民用航空器设定抵押的，还应当提供有关证明文件；\n(三)符合《中华人民共和国民用航空法》第十一条第(二)项或者第(三)项规定的民用航空器买卖合同或者租赁合同；\n(四)国务院民用航空主管部门要求提交的其他必要的有关文件。\n第七条 办理民用航空器抵押权登记的，民用航空器的抵押权人和抵押人应当提交下列文件或者经核对无误的复印件：\n(一)民用航空器国籍登记证书；\n(二)民用航空器所有权登记证书或者相应的所有权证明文件；\n(三)民用航空器抵押合同；\n(四)国务院民用航空主管部门要求提交的其他必要的有关文件。\n第八条 就两架以上民用航空器设定一项抵押权或者就同一民用航空器设定两项以上抵押权时，民用航空器的抵押权人和抵押人应当就每一架民用航空器或者每一项抵押权分别办理抵押权登记。\n第九条 国务院民用航空主管部门应当自收到民用航空器权利登记申请之日起7个工作日内，对申请的权利登记事项进行审查。经审查符合本条例规定的，应当向民用航空器权利人颁发相应的民用航空器权利登记证书，并区别情况在民用航空器权利登记簿上载明本条例第十条至第十三条规定的相应事项；经审查不符合本条例规定的，应当书面通知民用航空器权利人。\n第十条 国务院民用航空主管部门向民用航空器所有人颁发民用航空器所有权登记证书时，应当在民用航空器权利登记簿上载明下列事项：\n(一)民用航空器国籍、国籍标志和登记标志；\n(二)民用航空器所有人的姓名或者名称、地址及其法定代表人的姓名；\n(三)民用航空器为数人共有的，载明民用航空器共有人的共有情况；\n(四)民用航空器所有权的取得方式和取得日期；\n(五)民用航空器制造人名称、制造日期和制造地点；\n(六)民用航空器价值、机体材料和主要技术数据；\n(七)民用航空器已设定抵押的，载明其抵押权的设定情况；\n(八)民用航空器所有权登记日期；\n(九)国务院民用航空主管部门规定的其他事项。\n第十一条 国务院民用航空主管部门向民用航空器占有人颁发民用航空器占有权登记证书时，应当在民用航空器权利登记簿上载明下列事项：\n(一)民用航空器的国籍、国籍标志和登记标志；\n(二)民用航空器占有人、所有人或者出租人的姓名或者名称、地址及其法定代表人的姓名；\n(三)民用航空器占有权的取得方式、取得日期和约定的占有条件；\n(四)民用航空器占有权登记日期；\n(五)国务院民用航空主管部门规定的其他事项。\n第十二条 国务院民用航空主管部门向民用航空器抵押权人颁发民用航空器抵押权登记证书时，应当在民用航空器权利登记簿上载明下列事项：\n(一)被抵押的民用航空器的国籍、国籍标志和登记标志；\n(二)抵押权人和抵押人的姓名或者名称、地址及其法定代表人的姓名；\n(三)民用航空器抵押所担保的债权数额、利息率、受偿期限；\n(四)民用航空器抵押权登记日期；\n(五)国务院民用航空主管部门规定的其他事项。\n第十三条 国务院民用航空主管部门向民用航空器优先权的债权人颁发民用航空器优先权登记证书时，应当在民用航空器权利登记簿上载明下列事项：\n(一)发生债权的民用航空器的国籍、国籍标志和登记标志；\n(二)民用航空器优先权的债权人的姓名或者名称、地址及其法定代表人的姓名；\n(三)发生债权的民用航空器的所有人、经营人或者承租人的姓名或者名称、地址及其法定代表人的姓名；\n(四)民用航空器优先权的债权人主张的债权数额和债权发生的时间、原因；\n(五)民用航空器优先权登记日期；\n(六)国务院民用航空主管部门规定的其他事项。\n第十四条 同一民用航空器设定两项以上抵押权的，国务院民用航空主管部门应当按照抵押权登记申请日期的先后顺序进行登记。\n第十五条 民用航空器权利登记事项发生变更时，民用航空器权利人应当持有关的民用航空器权利登记证书和变更证明文件，向国务院民用航空主管部门办理变更登记。\n民用航空器抵押合同变更时，由抵押权人和抵押人共同向国务院民用航空主管部门办理变更登记。\n第十六条 国务院民用航空主管部门应当自收到民用航空器权利变更登记申请之日起7个工作日内，对申请的权利变更登记事项进行审查。经审查符合本条例规定的，在有关权利登记证书和民用航空器权利登记簿上注明变更事项；经审查不符合本条例规定的，应当书面通知民用航空器权利人。\n第十七条 遇有下列情形之一时，民用航空器权利人应当持有关的民用航空器权利登记证书和证明文件，向国务院民用航空主管部门办理注销登记：\n(一)民用航空器所有权转移；\n(二)民用航空器灭失或者失踪；\n(三)民用航空器租赁关系终止或者民用航空器占有人停止占有；\n(四)民用航空器抵押权所担保的债权消灭；\n(五)民用航空器优先权消灭；\n(六)国务院民用航空主管部门规定的其他情形。\n第十八条 国务院民用航空主管部门应当自收到民用航空器注销登记申请之日起7个工作日内，对申请的注销登记事项进行审查。经审查符合本条例规定的，收回有关的民用航空器权利登记证书，相应地注销民用航空器权利登记簿上的权利登记，并根据具体情况向民用航空器权利人出具民用航空器权利登记注销证明书；经审查不符合本条例规定的，应当书面通知民用航空器权利人。\n第十九条 申请人办理民用航空器权利登记，应当缴纳登记费。登记费的收费标准由国务院民用航空主管部门会同国务院价格主管部门制定。\n第二十条 本条例自发布之日起施行。","level":0}]},{"id":"n0363","sections":[{"name":"","text":"基础测绘条例\n(2009年5月6日国务院第62次常务会议通过 2009年5月12日中华人民共和国国务院令第556号公布 自2009年8月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了加强基础测绘管理，规范基础测绘活动，保障基础测绘事业为国家经济建设、国防建设和社会发展服务，根据《中华人民共和国测绘法》，制定本条例。\n第二条 在中华人民共和国领域和中华人民共和国管辖的其他海域从事基础测绘活动，适用本条例。\n本条例所称基础测绘，是指建立全国统一的测绘基准和测绘系统，进行基础航空摄影，获取基础地理信息的遥感资料，测制和更新国家基本比例尺地图、影像图和数字化产品，建立、更新基础地理信息系统。\n在中华人民共和国领海、中华人民共和国领海基线向陆地一侧至海岸线的海域和中华人民共和国管辖的其他海域从事海洋基础测绘活动，按照国务院、中央军事委员会的有关规定执行。\n第三条 基础测绘是公益性事业。\n县级以上人民政府应当加强对基础测绘工作的领导，将基础测绘纳入本级国民经济和社会发展规划及年度计划，所需经费列入本级财政预算。\n国家对边远地区和少数民族地区的基础测绘给予财政支持。具体办法由财政部门会同同级测绘行政主管部门制定。\n第四条 基础测绘工作应当遵循统筹规划、分级管理、定期更新、保障安全的原则。\n第五条 国务院测绘行政主管部门负责全国基础测绘工作的统一监督管理。\n县级以上地方人民政府负责管理测绘工作的行政部门(以下简称测绘行政主管部门)负责本行政区域基础测绘工作的统一监督管理。\n第六条 国家鼓励在基础测绘活动中采用先进科学技术和先进设备，加强基础研究和信息化测绘体系建设，建立统一的基础地理信息公共服务平台，实现基础地理信息资源共享，提高基础测绘保障服务能力。","level":1},{"name":"第二章 基础测绘规划","text":"第七条 国务院测绘行政主管部门会同国务院其他有关部门、军队测绘主管部门，组织编制全国基础测绘规划，报国务院批准后组织实施。\n县级以上地方人民政府测绘行政主管部门会同本级人民政府其他有关部门，根据国家和上一级人民政府的基础测绘规划和本行政区域的实际情况，组织编制本行政区域的基础测绘规划，报本级人民政府批准，并报上一级测绘行政主管部门备案后组织实施。\n第八条 基础测绘规划报送审批前，组织编制机关应当组织专家进行论证，并征求有关部门和单位的意见。其中，地方的基础测绘规划，涉及军事禁区、军事管理区或者作战工程的，还应当征求军事机关的意见。\n基础测绘规划报送审批文件中应当附具意见采纳情况及理由。\n第九条 组织编制机关应当依法公布经批准的基础测绘规划。\n经批准的基础测绘规划是开展基础测绘工作的依据，未经法定程序不得修改；确需修改的，应当按照本条例规定的原审批程序报送审批。\n第十条 国务院发展改革部门会同国务院测绘行政主管部门，编制全国基础测绘年度计划。\n县级以上地方人民政府发展改革部门会同同级测绘行政主管部门，编制本行政区域的基础测绘年度计划，并分别报上一级主管部门备案。\n第十一条 县级以上人民政府测绘行政主管部门应当根据应对自然灾害等突发事件的需要，制定相应的基础测绘应急保障预案。\n基础测绘应急保障预案的内容应当包括：应急保障组织体系，应急装备和器材配备，应急响应，基础地理信息数据的应急测制和更新等应急保障措施。","level":1},{"name":"第三章 基础测绘项目的组织实施","text":"第十二条 下列基础测绘项目，由国务院测绘行政主管部门组织实施：\n(一)建立全国统一的测绘基准和测绘系统；\n(二)建立和更新国家基础地理信息系统；\n(三)组织实施国家基础航空摄影；\n(四)获取国家基础地理信息遥感资料；\n(五)测制和更新全国1∶100万至1∶2.5万国家基本比例尺地图、影像图和数字化产品；\n(六)国家急需的其他基础测绘项目。\n第十三条 下列基础测绘项目，由省、自治区、直辖市人民政府测绘行政主管部门组织实施：\n(一)建立本行政区域内与国家测绘系统相统一的大地控制网和高程控制网；\n(二)建立和更新地方基础地理信息系统；\n(三)组织实施地方基础航空摄影；\n(四)获取地方基础地理信息遥感资料；\n(五)测制和更新本行政区域1∶1万至1∶5000国家基本比例尺地图、影像图和数字化产品。\n第十四条 设区的市、县级人民政府依法组织实施1∶2000至1∶500比例尺地图、影像图和数字化产品的测制和更新以及地方性法规、地方政府规章确定由其组织实施的基础测绘项目。\n第十五条 组织实施基础测绘项目，应当依据基础测绘规划和基础测绘年度计划，依法确定基础测绘项目承担单位。\n第十六条 基础测绘项目承担单位应当具有与所承担的基础测绘项目相应等级的测绘资质，并不得超越其资质等级许可的范围从事基础测绘活动。\n基础测绘项目承担单位应当具备健全的保密制度和完善的保密设施，严格执行有关保守国家秘密法律、法规的规定。\n第十七条 从事基础测绘活动，应当使用全国统一的大地基准、高程基准、深度基准、重力基准，以及全国统一的大地坐标系统、平面坐标系统、高程系统、地心坐标系统、重力测量系统，执行国家规定的测绘技术规范和标准。\n因建设、城市规划和科学研究的需要，确需建立相对独立的平面坐标系统的，应当与国家坐标系统相联系。\n第十八条 县级以上人民政府及其有关部门应当遵循科学规划、合理布局、有效利用、兼顾当前与长远需要的原则，加强基础测绘设施建设，避免重复投资。\n国家安排基础测绘设施建设资金，应当优先考虑航空摄影测量、卫星遥感、数据传输以及基础测绘应急保障的需要。\n第十九条 国家依法保护基础测绘设施。\n任何单位和个人不得侵占、损毁、拆除或者擅自移动基础测绘设施。基础测绘设施遭受破坏的，县级以上地方人民政府测绘行政主管部门应当及时采取措施，组织力量修复，确保基础测绘活动正常进行。\n第二十条 县级以上人民政府测绘行政主管部门应当加强基础航空摄影和用于测绘的高分辨率卫星影像获取与分发的统筹协调，做好基础测绘应急保障工作，配备相应的装备和器材，组织开展培训和演练，不断提高基础测绘应急保障服务能力。\n自然灾害等突发事件发生后，县级以上人民政府测绘行政主管部门应当立即启动基础测绘应急保障预案，采取有效措施，开展基础地理信息数据的应急测制和更新工作。","level":1},{"name":"第四章 基础测绘成果的更新与利用","text":"第二十一条 国家实行基础测绘成果定期更新制度。\n基础测绘成果更新周期应当根据不同地区国民经济和社会发展的需要、测绘科学技术水平和测绘生产能力、基础地理信息变化情况等因素确定。其中，1∶100万至1∶5000国家基本比例尺地图、影像图和数字化产品至少5年更新一次；自然灾害多发地区以及国民经济、国防建设和社会发展急需的基础测绘成果应当及时更新。\n基础测绘成果更新周期确定的具体办法，由国务院测绘行政主管部门会同军队测绘主管部门和国务院其他有关部门制定。\n第二十二条 县级以上人民政府测绘行政主管部门应当及时收集有关行政区域界线、地名、水系、交通、居民点、植被等地理信息的变化情况，定期更新基础测绘成果。\n县级以上人民政府其他有关部门和单位应当对测绘行政主管部门的信息收集工作予以支持和配合。\n第二十三条 按照国家规定需要有关部门批准或者核准的测绘项目，有关部门在批准或者核准前应当书面征求同级测绘行政主管部门的意见，有适宜基础测绘成果的，应当充分利用已有的基础测绘成果，避免重复测绘。\n第二十四条 县级以上人民政府测绘行政主管部门应当采取措施，加强对基础地理信息测制、加工、处理、提供的监督管理，确保基础测绘成果质量。\n第二十五条 基础测绘项目承担单位应当建立健全基础测绘成果质量管理制度，严格执行国家规定的测绘技术规范和标准，对其完成的基础测绘成果质量负责。\n第二十六条 基础测绘成果的利用，按照国务院有关规定执行。","level":1},{"name":"第五章 法律责任","text":"第二十七条 违反本条例规定，县级以上人民政府测绘行政主管部门和其他有关主管部门将基础测绘项目确定由不具有测绘资质或者不具有相应等级测绘资质的单位承担的，责令限期改正，对负有直接责任的主管人员和其他直接责任人员，依法给予处分。\n第二十八条 违反本条例规定，县级以上人民政府测绘行政主管部门和其他有关主管部门的工作人员利用职务上的便利收受他人财物、其他好处，或者玩忽职守，不依法履行监督管理职责，或者发现违法行为不予查处，造成严重后果，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。\n第二十九条 违反本条例规定，未取得测绘资质证书从事基础测绘活动的，责令停止违法行为，没收违法所得和测绘成果，并处测绘约定报酬1倍以上2倍以下的罚款。\n第三十条 违反本条例规定，基础测绘项目承担单位超越资质等级许可的范围从事基础测绘活动的，责令停止违法行为，没收违法所得和测绘成果，处测绘约定报酬1倍以上2倍以下的罚款，并可以责令停业整顿或者降低资质等级；情节严重的，吊销测绘资质证书。\n第三十一条 违反本条例规定，实施基础测绘项目，不使用全国统一的测绘基准和测绘系统或者不执行国家规定的测绘技术规范和标准的，责令限期改正，给予警告，可以并处10万元以下罚款；对负有直接责任的主管人员和其他直接责任人员，依法给予处分。\n第三十二条 违反本条例规定，侵占、损毁、拆除或者擅自移动基础测绘设施的，责令限期改正，给予警告，可以并处5万元以下罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，对负有直接责任的主管人员和其他直接责任人员，依法给予处分。\n第三十三条 违反本条例规定，基础测绘成果质量不合格的，责令基础测绘项目承担单位补测或者重测；情节严重的，责令停业整顿，降低资质等级直至吊销测绘资质证书；给用户造成损失的，依法承担赔偿责任。\n第三十四条 本条例规定的降低资质等级、吊销测绘资质证书的行政处罚，由颁发资质证书的部门决定；其他行政处罚由县级以上人民政府测绘行政主管部门决定。","level":1},{"name":"第六章 附则","text":"第三十五条 本条例自2009年8月1日起施行。","level":1}]},{"id":"n0364","sections":[{"name":"","text":"中华人民共和国军品出口管理条例\n(1997年10月22日中华人民共和国国务院、中华人民共和国中央军事委员会令第234号发布 根据2002年10月15日《国务院、中央军事委员会关于修改〈中华人民共和国军品出口管理条例〉的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强对军品出口的统一管理，维护正常的军品出口秩序，制定本条例。\n第二条 本条例所称军品出口，是指用于军事目的的装备、专用生产设备及其他物资、技术和有关服务的贸易性出口。\n前款所称军品出口，纳入军品出口管理清单。军品出口管理清单由国家军品出口主管部门制定、调整并公布。\n第三条 国家军品出口主管部门在国务院、中央军事委员会的领导下，主管全国的军品出口工作，对全国的军品出口实施监督管理。\n第四条 国家实行统一的军品出口管理制度，禁止任何损害国家的利益和安全的军品出口行为，依法保障正常的军品出口秩序。\n第五条 军品出口应当遵循下列原则：\n(一)有助于接受国的正当自卫能力；\n(二)不损害有关地区的和世界的和平、安全与稳定；\n(三)不干涉接受国的内政。\n第六条 中华人民共和国缔结或者参加的国际条约同本条例有不同规定的，适用国际条约的规定；但是，中华人民共和国声明保留的条款除外。","level":1},{"name":"第二章 军品贸易公司","text":"第七条 本条例所称军品贸易公司，是指依法取得军品出口经营权，并在核定的经营范围内从事军品出口经营活动的企业法人。\n第八条 军品出口经营权由国家军品出口主管部门审查批准。具体办法由国家军品出口主管部门规定。\n第九条 军品贸易公司依法自主经营、自负盈亏。\n第十条 军品贸易公司应当信守合同，保证商品质量，完善售后服务。\n第十一条 军品贸易公司应当按照国家军品出口主管部门的规定，如实提交与其军品出口经营活动有关的文件及资料。国家军品出口主管部门应当为军品贸易公司保守商业秘密，维护军品贸易公司的合法权益。\n第十二条 军品贸易公司可以委托经批准的军品出口运输企业，办理军品出口运输及相关业务。具体办法由国家军品出口主管部门规定。","level":1},{"name":"第三章 军品出口管理","text":"第十三条 国家对军品出口实行许可制度。\n军品出口项目、合同，应当依照本条例的规定申请审查批准。军品出口，应当凭军品出口许可证。\n第十四条 军品出口项目，由国家军品出口主管部门或者由国家军品出口主管部门会同国务院、中央军事委员会的有关部门审查批准。\n第十五条 军品出口项目经批准后，军品贸易公司可以对外签订军品出口合同。军品出口合同签订后，应当向国家军品出口主管部门申请审查批准；国家军品出口主管部门应当自收到申请之日起20日内作出决定。军品出口合同获得批准，方可生效。\n军品贸易公司向国家军品出口主管部门申请批准军品出口合同时，应当附送接受国的有效证明文件。\n第十六条 重大的军品出口项目、合同，应当经国家军品出口主管部门会同国务院、中央军事委员会的有关部门审查，报国务院和中央军事委员会批准。\n第十七条 军品贸易公司在军品出口前，应当凭军品出口合同批准文件，向国家军品出口主管部门申请领取军品出口许可证；符合军品出口合同规定的，国家军品出口主管部门应当自收到申请之日起10日内签发军品出口许可证。\n海关凭军品出口许可证接受申报，并按照国家有关规定验放。\n第十八条 军品出口项目、合同的审查批准办法和军品出口许可证的签发办法，由国家军品出口主管部门制定。\n第十九条 军品出口，由国家军品出口主管部门会同有关部门下达军品出口通知。有关部门和地方人民政府收到军品出口通知后，应当按照国家有关规定认真履行职责，保证军品出口的安全、迅速、准确。","level":1},{"name":"第四章 军品出口秩序","text":"第二十条 未取得军品出口经营权的任何单位或者组织，不得从事军品出口经营活动。\n国家禁止个人从事军品出口经营活动。\n第二十一条 军品贸易公司在军品出口经营活动中，应当遵守法律和行政法规的规定，维护正常的军品出口秩序。\n第二十二条 军品贸易公司在军品出口经营活动中，不得有下列行为：\n(一)危害国家安全或者社会公共利益；\n(二)以不正当竞争手段排挤竞争对手；\n(三)侵害中华人民共和国法律保护的知识产权；\n(四)伪造、变造、骗取或者转让军品出口项目批准文件、合同批准文件、许可证和接受国的有效证明文件等单证；\n(五)超越核定的经营范围经营；\n(六)违反法律和行政法规规定的其他行为。\n第二十三条 国家军品出口主管部门认为必要时或者根据军品贸易公司的请求，可以对妨碍正常的军品出口秩序的行为进行处理。","level":1},{"name":"第五章 法律责任","text":"第二十四条 军品贸易公司违反本条例第十一条规定的，由国家军品出口主管部门责令限期改正，予以警告；逾期不改正的，处2万元以上10万元以下的罚款，暂停直至撤销其军品出口经营权。\n第二十五条 军品贸易公司违反本条例第二十二条第(四)项、第(五)项规定，触犯刑律的，依照刑法关于非法经营罪，伪造、变造、买卖国家机关公文、证件、印章罪或者其他罪的规定，依法追究刑事责任；尚不够刑事处罚的，由国家军品出口主管部门予以警告，没收违法所得，并处违法所得1倍以上3倍以下的罚款，没有违法所得或者违法所得不足10万元的，处10万元以上30万元以下的罚款，暂停直至撤销其军品出口经营权。\n军品贸易公司违反本条例第二十二条第(一)项、第(二)项、第(三)项规定或者其他法律、行政法规规定的，由国家有关主管部门依照有关法律和行政法规的规定予以处罚，国家军品出口主管部门并可以暂停直至撤销其军品出口经营权；触犯刑律的，依照刑法有关规定，依法追究刑事责任。\n第二十六条 违反本条例第二十条规定的，由国家军品出口主管部门取缔非法活动；触犯刑律的，依照刑法关于非法经营罪或者其他罪的规定，依法追究刑事责任；尚不够刑事处罚的，由国家军品出口主管部门予以警告，没收违法所得，并处违法所得1倍以上5倍以下的罚款，没有违法所得或者违法所得不足10万元的，处10万元以上50万元以下的罚款。\n第二十七条 军品贸易公司对国家军品出口主管部门作出的具体行政行为不服的，应当先依法申请行政复议；对行政复议决定仍不服的，可以依法向人民法院提起行政诉讼。\n第二十八条 国家军品出口管理工作人员滥用职权、玩忽职守或者利用职务上的便利收受、索取他人财物，触犯刑律的，依照刑法关于滥用职权罪、玩忽职守罪、受贿罪或者其他罪的规定，依法追究刑事责任；尚不够刑事处罚的，依法给予行政处分。","level":1},{"name":"第六章 附则","text":"第二十九条 警用装备的出口适用本条例。\n第三十条 本条例自1998年1月1日起施行。","level":1}]},{"id":"n0365","sections":[{"name":"","text":"合理化建议和技术改进奖励条例\n(1982年3月16日国务院发布 1986年6月4日国务院修订发布)","level":0},{"name":"第一章 总则","text":"第一条 为了鼓励职工积极提合理化建议，推动技术进步，改善经营管理，增强企业内部活力，促进国民经济发展，特制定本条例。\n第二条 本条例所称合理化建议，是指有关改进和完善企业、事业单位生产技术和经营管理方面的办法和措施；所称技术改进，是指对机械设备、工具、工艺技术等方面所做的改进和革新。\n合理化建议和技术改进的内容是：\n(一) 工业产品质量和工程质量的提高，产品结构改进，生物品种的改良和发展，新产品的开发；\n(二) 更有效地利用和节约能源、原材料，以及利用自然条件；\n(三) 生产工艺和经验、检验方法，劳动保护、环境保护、安全技术，医疗、卫生技术，物资运输、储藏、养护技术以及设计、统计、计算技术等方面的改进；\n(四) 工具、设备、仪器、装置的改进；\n(五) 科技成果的推广，企业现代化管理方法、手段的创新和应用，引进技术、进口设备的消化吸收和革新。\n第三条 对提合理化建议和技术改进者的奖励，实行精神鼓励与物质奖励相结合的原则。\n第四条 本条例适用于全民所有制企业、事业单位。非全民所有制单位可以参照本条例执行。","level":1},{"name":"第二章 奖励的标准和方法","text":"第五条 职工(集体或者个人)提出的合理化建议或者进行的技术改进，必须经过试验研究和实际应用，并在企业、事业单位的生产或者工作中取得成效，方能获得奖励。\n第六条 对被采用的、可以直接计算经济效益的合理化建议和技术改进项目，奖励分为五个等级：\n奖励等级\t年节约或创造价值\t奖金额\t荣誉奖\n一\t一百万元以上\t二千五百元至四千元\t奖状\n二\t五十万元以上一百万元以下\t一千五百元至二千五百元\t奖状\n三\t十万元以上五十万元以下\t五百元至一千五百元\t奖状\n四\t一万元以上十万元以下\t三百元至五百元\t表扬\n五\t一万元以下\t三百元以下\t表扬\n对借鉴已经应用的科技成果，在本单位提出合理化建议或者进行技术改进取得显著经济效益者，应当降低一个等级奖励。\n本条所称“以上”，含本数；所称“以下”，不含本数。\n第七条 对被采用的、不能直接计算经济效益的合理化建议和技术改进项目，根据其作用大小、技术复杂程度和推广范围，参照本条例第六条的规定，评定相应的奖励等级。\n第八条 被采纳的合理化建议和技术改进项目，经评审确定作为技术储备的，采纳项目的单位应当按照本条例第六条的规定，在第五等级的限额内酌情给予奖励；如作为技术储备的项目以后投入实际应用，应当按照应用后的经济效益大小，评定相应的奖励等级。实际应用后增发奖金时，应当剔除已发放的奖金额。\n第九条 被采用的合理化建议和技术改进项目年节约或者创造的价值，自采用之日起，按十二个月为计算单位，并经采用单位财务部门审核。\n第十条 工程技术人员、管理干部在完成本职工作前提下提出的，与本身职责虽有直接关联，但有创新的项目，采用见效后可以按照本条例奖励。厂职干部的奖励，报上级主管部门审批。\n第十一条 获奖项目不得重复得奖。一个合理化建议或者技术改进项目符合两个以上奖励条例时，应当按照奖金额较高的条例奖励；一个合理化建议或者技术改进项目经再次评审提高了奖励等级，再次发放奖金时只补发差额部分。\n第十二条 集体取得的合理化建议和技术改进项目的奖金，按各人贡献大小合理分配。","level":1},{"name":"第三章 审查和处理","text":"第十三条 企业、事业单位应当建立合理化建议和技术改进项目评审委员会或者评审小组，由行政负责，吸收工会等有关部门的人员参加，负责合理化建议和技术改进项目的评议审定工作。\n第十四条 各企业、事业单位的有关科室或者管理人员，应当及时对合理化建议和技术改进项目做出采纳或者不采纳的结论，并连同做结论的说明以书面形式送给主管建议工作的机构或者人员，提交评审委员会或者评审小组审批。\n有关单位对已采用的合理化建议和技术改进项目，应当根据规定及时实施奖励；对未采纳的合理化建议和技术改进项目，必须向建议人说明未采纳的原因。\n第十五条 对合理化建议和技术改进项目奖励等级的确定，由采用单位审查批准，其中：一、二等奖励项目，采用单位批准后报上级主管部门备案。\n第十六条 奖金由采用单位支付。企业单位支付的奖金，计入生产成本；事业单位支付的奖金，在事业费或者收入提成中列支。\n第十七条 对经济效益较高而本单位无法实施的合理化建议和技术改进项目，应当报上级主管部门或者省、自治区、直辖市经济委员会(计划经济委员会)处理；对经济效益显著的合理化建议和技术改进项目，也可以通过技术市场进行有偿转让。\n第十八条 对提高工效和降低物质消耗的合理化建议和技术改进项目，对原定额可以给予六个月至一年的保留期。","level":1},{"name":"第四章 监督检查和争议的解决","text":"第十九条 企业、事业单位的工会和职工代表大会有权监督本条例的执行情况，可以对项目的处理、实施、奖励等问题向有关部门提出质询。\n第二十条 上级主管部门应当对所属单位的合理化建议和技术改进工作进行监督、检查，并负责协调解决所属企业、事业单位在项目评审工作中发生的争议。\n第二十一条 对弄虚作假骗取荣誉者，应当由授奖单位撤销其荣誉称号，扣回其所得奖金；情节严重的，由其所在单位给予行政处分，并追究其经济责任。","level":1},{"name":"第五章 附则","text":"第二十二条 本条例由国家经济委员会负责解释。\n第二十三条 国家经济委员会根据本条例制订实施细则。各企业、事业单位根据本条例和实施细则，制订具体实施办法，并报上级主管部门备案。\n第二十四条 本条例自修订发布之日起施行。","level":1}]},{"id":"n0366","sections":[{"name":"","text":"企业国有资产监督管理暂行条例\n(2003年5月27日中华人民共和国国务院令第378号公布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2019年3月2日《国务院关于修改部分行政法规的决定》第二次修订)","level":0},{"name":"第一章 总则","text":"第一条 为建立适应社会主义市场经济需要的国有资产监督管理体制，进一步搞好国有企业，推动国有经济布局和结构的战略性调整，发展和壮大国有经济，实现国有资产保值增值，制定本条例。\n第二条 国有及国有控股企业、国有参股企业中的国有资产的监督管理，适用本条例。\n金融机构中的国有资产的监督管理，不适用本条例。\n第三条 本条例所称企业国有资产，是指国家对企业各种形式的投资和投资所形成的权益，以及依法认定为国家所有的其他权益。\n第四条 企业国有资产属于国家所有。国家实行由国务院和地方人民政府分别代表国家履行出资人职责，享有所有者权益，权利、义务和责任相统一，管资产和管人、管事相结合的国有资产管理体制。\n第五条 国务院代表国家对关系国民经济命脉和国家安全的大型国有及国有控股、国有参股企业，重要基础设施和重要自然资源等领域的国有及国有控股、国有参股企业，履行出资人职责。国务院履行出资人职责的企业，由国务院确定、公布。\n省、自治区、直辖市人民政府和设区的市、自治州级人民政府分别代表国家对由国务院履行出资人职责以外的国有及国有控股、国有参股企业，履行出资人职责。其中，省、自治区、直辖市人民政府履行出资人职责的国有及国有控股、国有参股企业，由省、自治区、直辖市人民政府确定、公布，并报国务院国有资产监督管理机构备案；其他由设区的市、自治州级人民政府履行出资人职责的国有及国有控股、国有参股企业，由设区的市、自治州级人民政府确定、公布，并报省、自治区、直辖市人民政府国有资产监督管理机构备案。\n国务院，省、自治区、直辖市人民政府，设区的市、自治州级人民政府履行出资人职责的企业，以下统称所出资企业。\n第六条 国务院，省、自治区、直辖市人民政府，设区的市、自治州级人民政府，分别设立国有资产监督管理机构。国有资产监督管理机构根据授权，依法履行出资人职责，依法对企业国有资产进行监督管理。\n企业国有资产较少的设区的市、自治州，经省、自治区、直辖市人民政府批准，可以不单独设立国有资产监督管理机构。\n第七条 各级人民政府应当严格执行国有资产管理法律、法规，坚持政府的社会公共管理职能与国有资产出资人职能分开，坚持政企分开，实行所有权与经营权分离。\n国有资产监督管理机构不行使政府的社会公共管理职能，政府其他机构、部门不履行企业国有资产出资人职责。\n第八条 国有资产监督管理机构应当依照本条例和其他有关法律、行政法规的规定，建立健全内部监督制度，严格执行法律、行政法规。\n第九条 发生战争、严重自然灾害或者其他重大、紧急情况时，国家可以依法统一调用、处置企业国有资产。\n第十条 所出资企业及其投资设立的企业，享有有关法律、行政法规规定的企业经营自主权。\n国有资产监督管理机构应当支持企业依法自主经营，除履行出资人职责以外，不得干预企业的生产经营活动。\n第十一条 所出资企业应当努力提高经济效益，对其经营管理的企业国有资产承担保值增值责任。\n所出资企业应当接受国有资产监督管理机构依法实施的监督管理，不得损害企业国有资产所有者和其他出资人的合法权益。","level":1},{"name":"第二章 国有资产监督管理机构","text":"第十二条 国务院国有资产监督管理机构是代表国务院履行出资人职责、负责监督管理企业国有资产的直属特设机构。\n省、自治区、直辖市人民政府国有资产监督管理机构，设区的市、自治州级人民政府国有资产监督管理机构是代表本级政府履行出资人职责、负责监督管理企业国有资产的直属特设机构。\n上级政府国有资产监督管理机构依法对下级政府的国有资产监督管理工作进行指导和监督。\n第十三条 国有资产监督管理机构的主要职责是：\n(一)依照《中华人民共和国公司法》等法律、法规，对所出资企业履行出资人职责，维护所有者权益；\n(二)指导推进国有及国有控股企业的改革和重组；\n(三)依照规定向所出资企业委派监事；\n(四)依照法定程序对所出资企业的企业负责人进行任免、考核，并根据考核结果对其进行奖惩；\n(五)通过统计、稽核等方式对企业国有资产的保值增值情况进行监管；\n(六)履行出资人的其他职责和承办本级政府交办的其他事项。\n国务院国有资产监督管理机构除前款规定职责外，可以制定企业国有资产监督管理的规章、制度。\n第十四条 国有资产监督管理机构的主要义务是：\n(一)推进国有资产合理流动和优化配置，推动国有经济布局和结构的调整；\n(二)保持和提高关系国民经济命脉和国家安全领域国有经济的控制力和竞争力，提高国有经济的整体素质；\n(三)探索有效的企业国有资产经营体制和方式，加强企业国有资产监督管理工作，促进企业国有资产保值增值，防止企业国有资产流失；\n(四)指导和促进国有及国有控股企业建立现代企业制度，完善法人治理结构，推进管理现代化；\n(五)尊重、维护国有及国有控股企业经营自主权，依法维护企业合法权益，促进企业依法经营管理，增强企业竞争力；\n(六)指导和协调解决国有及国有控股企业改革与发展中的困难和问题。\n第十五条 国有资产监督管理机构应当向本级政府报告企业国有资产监督管理工作、国有资产保值增值状况和其他重大事项。","level":1},{"name":"第三章 企业负责人管理","text":"第十六条 国有资产监督管理机构应当建立健全适应现代企业制度要求的企业负责人的选用机制和激励约束机制。\n第十七条 国有资产监督管理机构依照有关规定，任免或者建议任免所出资企业的企业负责人：\n(一)任免国有独资企业的总经理、副总经理、总会计师及其他企业负责人；\n(二)任免国有独资公司的董事长、副董事长、董事，并向其提出总经理、副总经理、总会计师等的任免建议；\n(三)依照公司章程，提出向国有控股的公司派出的董事、监事人选，推荐国有控股的公司的董事长、副董事长和监事会主席人选，并向其提出总经理、副总经理、总会计师人选的建议；\n(四)依照公司章程，提出向国有参股的公司派出的董事、监事人选。\n国务院，省、自治区、直辖市人民政府，设区的市、自治州级人民政府，对所出资企业的企业负责人的任免另有规定的，按照有关规定执行。\n第十八条 国有资产监督管理机构应当建立企业负责人经营业绩考核制度，与其任命的企业负责人签订业绩合同，根据业绩合同对企业负责人进行年度考核和任期考核。\n第十九条 国有资产监督管理机构应当依照有关规定，确定所出资企业中的国有独资企业、国有独资公司的企业负责人的薪酬；依据考核结果，决定其向所出资企业派出的企业负责人的奖惩。","level":1},{"name":"第四章 企业重大事项管理","text":"第二十条 国有资产监督管理机构负责指导国有及国有控股企业建立现代企业制度，审核批准其所出资企业中的国有独资企业、国有独资公司的重组、股份制改造方案和所出资企业中的国有独资公司的章程。\n第二十一条 国有资产监督管理机构依照法定程序决定其所出资企业中的国有独资企业、国有独资公司的分立、合并、破产、解散、增减资本、发行公司债券等重大事项。其中，重要的国有独资企业、国有独资公司分立、合并、破产、解散的，应当由国有资产监督管理机构审核后，报本级人民政府批准。\n国有资产监督管理机构依照法定程序审核、决定国防科技工业领域其所出资企业中的国有独资企业、国有独资公司的有关重大事项时，按照国家有关法律、规定执行。\n第二十二条 国有资产监督管理机构依照公司法的规定，派出股东代表、董事，参加国有控股的公司、国有参股的公司的股东会、董事会。\n国有控股的公司、国有参股的公司的股东会、董事会决定公司的分立、合并、破产、解散、增减资本、发行公司债券、任免企业负责人等重大事项时，国有资产监督管理机构派出的股东代表、董事，应当按照国有资产监督管理机构的指示发表意见、行使表决权。\n国有资产监督管理机构派出的股东代表、董事，应当将其履行职责的有关情况及时向国有资产监督管理机构报告。\n第二十三条 国有资产监督管理机构决定其所出资企业的国有股权转让。其中，转让全部国有股权或者转让部分国有股权致使国家不再拥有控股地位的，报本级人民政府批准。\n第二十四条 所出资企业投资设立的重要子企业的重大事项，需由所出资企业报国有资产监督管理机构批准的，管理办法由国务院国有资产监督管理机构另行制定，报国务院批准。\n第二十五条 国有资产监督管理机构依照国家有关规定组织协调所出资企业中的国有独资企业、国有独资公司的兼并破产工作，并配合有关部门做好企业下岗职工安置等工作。\n第二十六条 国有资产监督管理机构依照国家有关规定拟订所出资企业收入分配制度改革的指导意见，调控所出资企业工资分配的总体水平。\n第二十七条 国有资产监督管理机构可以对所出资企业中具备条件的国有独资企业、国有独资公司进行国有资产授权经营。\n被授权的国有独资企业、国有独资公司对其全资、控股、参股企业中国家投资形成的国有资产依法进行经营、管理和监督。\n第二十八条 被授权的国有独资企业、国有独资公司应当建立和完善规范的现代企业制度，并承担企业国有资产的保值增值责任。","level":1},{"name":"第五章 企业国有资产管理","text":"第二十九条 国有资产监督管理机构依照国家有关规定，负责企业国有资产的产权界定、产权登记、资产评估监管、清产核资、资产统计、综合评价等基础管理工作。\n国有资产监督管理机构协调其所出资企业之间的企业国有资产产权纠纷。\n第三十条 国有资产监督管理机构应当建立企业国有资产产权交易监督管理制度，加强企业国有资产产权交易的监督管理，促进企业国有资产的合理流动，防止企业国有资产流失。\n第三十一条 国有资产监督管理机构对其所出资企业的企业国有资产收益依法履行出资人职责；对其所出资企业的重大投融资规划、发展战略和规划，依照国家发展规划和产业政策履行出资人职责。\n第三十二条 所出资企业中的国有独资企业、国有独资公司的重大资产处置，需由国有资产监督管理机构批准的，依照有关规定执行。","level":1},{"name":"第六章 企业国有资产监督","text":"第三十三条 国有资产监督管理机构依法对所出资企业财务进行监督，建立和完善国有资产保值增值指标体系，维护国有资产出资人的权益。\n第三十四条 国有及国有控股企业应当加强内部监督和风险控制，依照国家有关规定建立健全财务、审计、企业法律顾问和职工民主监督等制度。\n第三十五条 所出资企业中的国有独资企业、国有独资公司应当按照规定定期向国有资产监督管理机构报告财务状况、生产经营状况和国有资产保值增值状况。","level":1},{"name":"第七章 法律责任","text":"第三十六条 国有资产监督管理机构不按规定任免或者建议任免所出资企业的企业负责人，或者违法干预所出资企业的生产经营活动，侵犯其合法权益，造成企业国有资产损失或者其他严重后果的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。\n第三十七条 所出资企业中的国有独资企业、国有独资公司未按照规定向国有资产监督管理机构报告财务状况、生产经营状况和国有资产保值增值状况的，予以警告；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予纪律处分。\n第三十八条 国有及国有控股企业的企业负责人滥用职权、玩忽职守，造成企业国有资产损失的，应负赔偿责任，并对其依法给予纪律处分；构成犯罪的，依法追究刑事责任。\n第三十九条 对企业国有资产损失负有责任受到撤职以上纪律处分的国有及国有控股企业的企业负责人，5年内不得担任任何国有及国有控股企业的企业负责人；造成企业国有资产重大损失或者被判处刑罚的，终身不得担任任何国有及国有控股企业的企业负责人。","level":1},{"name":"第八章 附则","text":"第四十条 国有及国有控股企业、国有参股企业的组织形式、组织机构、权利和义务等，依照《中华人民共和国公司法》等法律、行政法规和本条例的规定执行。\n第四十一条 国有及国有控股企业、国有参股企业中中国共产党基层组织建设、社会主义精神文明建设和党风廉政建设，依照《中国共产党章程》和有关规定执行。\n国有及国有控股企业、国有参股企业中工会组织依照《中华人民共和国工会法》和《中国工会章程》的有关规定执行。\n第四十二条 国务院国有资产监督管理机构，省、自治区、直辖市人民政府可以依据本条例制定实施办法。\n第四十三条 本条例施行前制定的有关企业国有资产监督管理的行政法规与本条例不一致的，依照本条例的规定执行。\n第四十四条 政企尚未分开的单位，应当按照国务院的规定，加快改革，实现政企分开。政企分开后的企业，由国有资产监督管理机构依法履行出资人职责，依法对企业国有资产进行监督管理。\n第四十五条 本条例自公布之日起施行。","level":1}]},{"id":"n0367","sections":[{"name":"","text":"中华人民共和国传染病防治法实施办法\n(1991年10月4日国务院批准 1991年12月6日卫生部令第17号发布 自发布之日起施行)","level":0},{"name":"第一章 总则","text":"第一条 根据《中华人民共和国传染病防治法》(以下简称《传染病防治法》)的规定，制定本办法。\n第二条 国家对传染病实行预防为主的方针，各级政府在制定社会经济发展规划时，必须包括传染病防治目标，并组织有关部门共同实施。\n第三条 各级政府卫生行政部门对传染病防治工作实施统一监督管理。\n受国务院卫生行政部门委托的其他有关部门卫生主管机构，在本系统内行使《传染病防治法》第三十二条第一款所列职权。\n军队的传染病防治工作，依照《传染病防治法》和本办法中的有关规定以及国家其他有关规定，由中国人民解放军卫生主管部门实施监督管理。\n第四条 各级各类卫生防疫机构按照专业分工承担传染病监测管理的责任和范围，由省级政府卫生行政部门确定。\n铁路、交通、民航、厂(场)矿的卫生防疫机构，承担本系统传染病监测管理工作，并接受本系统上级卫生主管机构和省级政府卫生行政部门指定的卫生防疫机构的业务指导。\n第五条 各级各类医疗保健机构承担传染病防治管理的责任和范围，由当地政府卫生行政部门确定。\n第六条 各级政府对预防、控制传染病做出显著成绩和贡献的单位和个人，应当给予奖励。","level":1},{"name":"第二章 预防","text":"第七条 各级政府应当组织有关部门，开展传染病预防知识和防治措施的卫生健康教育。\n第八条 各级政府组织开展爱国卫生活动。\n铁路、交通、民航部门负责组织消除交通工具的鼠害和各种病媒昆虫的危害。\n农业、林业部门负责组织消除农田、牧场及林区的鼠害。\n国务院各有关部委消除钉螺危害的分工，按照国务院的有关规定办理。\n第九条 集中式供水必须符合国家《生活饮用水卫生标准》。\n各单位自备水源，未经城市建设部门和卫生行政部门批准，不得与城镇集中式供水系统连接。\n第十条 地方各级政府应当有计划地建设和改造公共卫生设施。\n城市应当按照城市环境卫生设施标准修建公共厕所、垃圾粪便的无害化处理场和污水、雨水排放处理系统等公共卫生设施。\n农村应当逐步改造厕所，对粪便进行无害化处理，加强对公共生活用水的卫生管理，建立必要的卫生管理制度。饮用水水源附近禁止有污水池、粪堆(坑)等污染源。禁止在饮用水水源附近洗刷便器和运输粪便的工具。\n第十一条 国家实行有计划的预防接种制度。\n中华人民共和国境内的任何人均应按照有关规定接受预防接种。\n各省、自治区、直辖市政府卫生行政部门可以根据当地传染病的流行情况，增加预防接种项目。\n第十二条 国家对儿童实行预防接种证制度。\n适龄儿童应当按照国家有关规定，接受预防接种。适龄儿童的家长或者监护人应当及时向医疗保健机构申请办理预防接种证。\n托幼机构、学校在办理入托、入学手续时，应当查验预防接种证，未按规定接种的儿童应当及时补种。\n第十三条 各级各类医疗保健机构的预防保健组织或者人员，在本单位及责任地段内承担下列工作：\n(一)传染病疫情报告和管理；\n(二)传染病预防和控制工作；\n(三)卫生行政部门指定的卫生防疫机构交付的传染病防治和监测任务。\n第十四条 医疗保健机构必须按照国务院卫生行政部门的有关规定，严格执行消毒隔离制度，防止医院内感染和医源性感染。\n第十五条 卫生防疫机构和从事致病性微生物实验的科研、教学、生产等单位必须做到：\n(一)建立健全防止致病性微生物扩散的制度和人体防护措施；\n(二)严格执行实验操作规程，对实验后的样品、器材、污染物品等，按照有关规定严格消毒后处理；\n(三)实验动物必须按照国家有关规定进行管理。\n第十六条 传染病的菌(毒)种分为下列三类：\n一类：鼠疫耶尔森氏菌、霍乱弧菌；天花病毒、艾滋病病毒；\n二类：布氏菌、炭疽菌、麻风杆菌；肝炎病毒、狂犬病毒、出血热病毒、登革热病毒；斑疹伤寒立克次体；\n三类：脑膜炎双球菌、链球菌、淋病双球菌、结核杆菌、百日咳嗜血杆菌、白喉棒状杆菌、沙门氏菌、志贺氏菌、破伤风梭状杆菌；钩端螺旋体、梅毒螺旋体；乙型脑炎病毒、脊髓灰质炎病毒、流感病毒、流行性腮腺炎病毒、麻疹病毒、风疹病毒。\n国务院卫生行政部门可以根据情况增加或者减少菌(毒)种的种类。\n第十七条 国家对传染病菌(毒)种的保藏、携带、运输实行严格管理：\n(一)菌(毒)种的保藏由国务院卫生行政部门指定的单位负责。\n(二)一、二类菌(毒)种的供应由国务院卫生行政部门指定的保藏管理单位供应。三类菌(毒)种由设有专业实验室的单位或者国务院卫生行政部门指定的保藏管理单位供应。\n(三)使用一类菌(毒)种的单位，必须经国务院卫生行政部门批准；使用二类菌(毒)种的单位必须经省级政府卫生行政部门批准；使用三类菌(毒)种的单位，应当经县级政府卫生行政部门批准。\n(四)一、二类菌(毒)种，应派专人向供应单位领取，不得邮寄；三类菌(毒)种的邮寄必须持有邮寄单位的证明，并按照菌(毒)种邮寄与包装的有关规定办理。\n第十八条 对患有下列传染病的病人或者病原携带者予以必要的隔离治疗，直至医疗保健机构证明其不具有传染性时，方可恢复工作：\n(一)鼠疫、霍乱；\n(二)艾滋病、病毒性肝炎、细菌性和阿米巴痢疾、伤寒和副伤寒、炭疽、斑疹伤寒、麻疹、百日咳、白喉、脊髓灰质炎、流行性脑脊髓膜炎、猩红热、流行性出血热、登革热、淋病、梅毒；\n(三)肺结核、麻风病、流行性腮腺炎、风疹、急性出血性结膜炎。\n第十九条 从事饮水、饮食、整容、保育等易使传染病扩散工作的从业人员，必须按照国家有关规定取得健康合格证后方可上岗。\n第二十条 招用流动人员二百人以上的用工单位，应当向当地政府卫生行政部门指定的卫生防疫机构报告，并按照要求采取预防控制传染病的卫生措施。\n第二十一条 被甲类传染病病原体污染的污水、污物、粪便，有关单位和个人必须在卫生防疫人员的指导监督下，按照下列要求进行处理：\n(一)被鼠疫病原体污染\n1．被污染的室内空气、地面、四壁必须进行严格消毒，被污染的物品必须严格消毒或者焚烧处理；\n2．彻底消除鼠疫疫区内的鼠类、蚤类；发现病鼠、死鼠应当送检；解剖检验后的鼠尸必须焚化；\n3．疫区内啮齿类动物的皮毛不能就地进行有效的消毒处理时，必须在卫生防疫机构的监督下焚烧。\n(二)被霍乱病原体污染\n1．被污染的饮用水，必须进行严格消毒处理；\n2．污水经消毒处理后排放；\n3．被污染的食物要就地封存，消毒处理；\n4．粪便消毒处理达到无害化；\n5．被污染的物品，必须进行严格消毒或者焚烧处理。\n第二十二条 被伤寒和副伤寒、细菌性痢疾、脊髓灰质炎、病毒性肝炎病原体污染的水、物品、粪便，有关单位和个人应当按照下列要求进行处理：\n(一)被污染的饮用水，应当进行严格消毒处理；\n(二)污水经消毒处理后排放；\n(三)被污染的物品，应当进行严格消毒处理或者焚烧处理；\n(四)粪便消毒处理达到无害化。\n死于炭疽的动物尸体必须就地焚化，被污染的用具必须消毒处理，被污染的土地、草皮消毒后，必须将10厘米厚的表层土铲除，并在远离水源及河流的地方深埋。\n第二十三条 出售、运输被传染病病原体污染或者来自疫区可能被传染病病原体污染的皮毛、旧衣物及生活用品等，必须按照卫生防疫机构的要求进行必要的卫生处理。\n第二十四条 用于预防传染病的菌苗、疫苗等生物制品，由各省、自治区、直辖市卫生防疫机构统一向生物制品生产单位订购，其他任何单位和个人不得经营。\n用于预防传染病的菌苗、疫苗等生物制品必须在卫生防疫机构监督指导下使用。\n第二十五条 凡从事可能导致经血液传播传染病的美容、整容等单位和个人，必须执行国务院卫生行政部门的有关规定。\n第二十六条 血站(库)、生物制品生产单位，必须严格执行国务院卫生行政部门的有关规定，保证血液、血液制品的质量，防止因输入血液、血液制品引起病毒性肝炎、艾滋病、疟疾等疾病的发生。任何单位和个人不准使用国务院卫生行政部门禁止进口的血液和血液制品。\n第二十七条 生产、经营、使用消毒药剂和消毒器械、卫生用品、卫生材料、一次性医疗器材、隐形眼镜、人造器官等必须符合国家有关标准，不符合国家有关标准的不得生产、经营和使用。\n第二十八条 发现人畜共患传染病已在人、畜间流行时，卫生行政部门与畜牧兽医部门应当深入疫区，按照职责分别对人、畜开展防治工作。\n传染病流行区的家畜家禽，未经畜牧兽医部门检疫不得外运。\n进入鼠疫自然疫源地捕猎旱獭应按照国家有关规定执行。\n第二十九条 狂犬病的防治管理工作按照下列规定分工负责：\n(一)公安部门负责县以上城市养犬的审批与违章养犬的处理，捕杀狂犬、野犬。\n(二)畜牧兽医部门负责兽用狂犬病疫苗的研制、生产和供应；对城乡经批准的养犬进行预防接种、登记和发放“家犬免疫证”；对犬类狂犬病的疫情进行监测和负责进出口犬类的检疫、免疫及管理。\n(三)乡(镇)政府负责辖区内养犬的管理，捕杀狂犬、野犬。\n(四)卫生部门负责人用狂犬病疫苗的供应、接种和病人的诊治。\n第三十条 自然疫源地或者可能是自然疫源地的地区计划兴建大型建设项目时，建设单位在设计任务书批准后，应当向当地卫生防疫机构申请对施工环境进行卫生调查，并根据卫生防疫机构的意见采取必要的卫生防疫措施后，方可办理开工手续。\n兴建城市规划内的建设项目，属于在自然疫源地和可能是自然疫源地范围内的，城市规划主管部门在核发建设工程规划许可证明中，必须有卫生防疫部门提出的有关意见及结论。建设单位在施工过程中，必须采取预防传染病传播和扩散的措施。\n第三十一条 卫生防疫机构接到在自然疫源地和可能是自然疫源地范围内兴办大型建设项目的建设单位的卫生调查申请后，应当及时组成调查组到现场进行调查，并提出该地区自然环境中可能存在的传染病病种、流行范围、流行强度及预防措施等意见和结论。\n第三十二条 在自然疫源地或者可能是自然疫源地内施工的建设单位，应当设立预防保健组织负责施工期间的卫生防疫工作。\n第三十三条 凡在生产、工作中接触传染病病原体的工作人员，可以按照国家有关规定申领卫生防疫津贴。","level":1},{"name":"第三章 疫情报告","text":"第三十四条 执行职务的医疗保健人员、卫生防疫人员为责任疫情报告人。\n责任疫情报告人应当按照本办法第三十五条规定的时限向卫生行政部门指定的卫生防疫机构报告疫情，并做疫情登记。\n第三十五条 责任疫情报告人发现甲类传染病和乙类传染病中的艾滋病、肺炭疽的病人、病原携带者和疑似传染病病人时，城镇于六小时内，农村于十二小时内，以最快的通讯方式向发病地的卫生防疫机构报告，并同时报出传染病报告卡。\n责任疫情报告人发现乙类传染病病人、病原携带者和疑似传染病病人时，城镇于十二小时内，农村于二十四小时内向发病地的卫生防疫机构报出传染病报告卡。\n责任疫情报告人在丙类传染病监测区内发现丙类传染病病人时，应当在二十四小时内向发病地的卫生防疫机构报出传染病报告卡。\n第三十六条 传染病暴发、流行时，责任疫情报告人应当以最快的通讯方式向当地卫生防疫机构报告疫情。接到疫情报告的卫生防疫机构应当以最快的通讯方式报告上级卫生防疫机构和当地政府卫生行政部门，卫生行政部门接到报告后，应当立即报告当地政府。\n省级政府卫生行政部门接到发现甲类传染病和发生传染病暴发、流行的报告后，应当于六小时内报告国务院卫生行政部门。\n第三十七条 流动人员中的传染病病人、病原携带者和疑似传染病病人的传染病报告、处理由诊治地负责，其疫情登记、统计由户口所在地负责。\n第三十八条 铁路、交通、民航、厂(场)矿的卫生防疫机构，应当定期向所在地卫生行政部门指定的卫生防疫机构报告疫情。\n第三十九条 军队的传染病疫情，由中国人民解放军卫生主管部门根据军队有关规定向国务院卫生行政部门报告。\n军队的医疗保健和卫生防疫机构，发现地方就诊的传染病病人、病原携带者、疑似传染病病人时，应当按照本办法第三十五条的规定报告疫情，并接受当地卫生防疫机构的业务指导。\n第四十条 国境口岸所在地卫生行政部门指定的卫生防疫机构和港口、机场、铁路卫生防疫机构和国境卫生检疫机关在发现国境卫生检疫法规定的检疫传染病时，应当互相通报疫情。\n发现人畜共患传染病时，卫生防疫机构和畜牧兽医部门应当互相通报疫情。\n第四十一条 各级政府卫生行政部门指定的卫生防疫机构应当对辖区内各类医疗保健机构的疫情登记报告和管理情况定期进行核实、检查、指导。\n第四十二条 传染病报告卡片邮寄信封应当印有明显的“红十字”标志及写明××卫生防疫机构收的字样。\n邮电部门应当及时传递疫情报告的电话或者信卡，并实行邮资总付。\n第四十三条 医务人员未经县级以上政府卫生行政部门批准，不得将就诊的淋病、梅毒、麻风病、艾滋病病人和艾滋病病原携带者及其家属的姓名、住址和个人病史公开。","level":1},{"name":"第四章 控制","text":"第四十四条 卫生防疫机构和医疗保健机构传染病的疫情处理实行分级分工管理。\n第四十五条 艾滋病的监测管理按照国务院有关规定执行。\n第四十六条 淋病、梅毒病人应当在医疗保健机构、卫生防疫机构接受治疗。尚未治愈前，不得进入公共浴池、游泳池。\n第四十七条 医疗保健机构或者卫生防疫机构在诊治中发现甲类传染病的疑似病人，应当在二日内作出明确诊断。\n第四十八条 甲类传染病病人和病原携带者以及乙类传染病中的艾滋病、淋病、梅毒病人的密切接触者必须按照有关规定接受检疫、医学检查和防治措施。\n前款以外的乙类传染病病人及病原携带者的密切接触者，应当接受医学检查和防治措施。\n第四十九条 甲类传染病疑似病人或者病原携带者的密切接触者，经留验排除是病人或者病原携带者后，留验期间的工资福利待遇由所属单位按出勤照发。\n第五十条 发现甲类传染病病人、病原携带者或者疑似病人的污染场所，卫生防疫机构接到疫情报告后，应立即进行严格的卫生处理。\n第五十一条 地方各级政府卫生行政部门发现本地区发生从未有过的传染病或者国家已宣布消除的传染病时，应当立即采取措施，必要时，向当地政府报告。\n第五十二条 在传染病暴发、流行区域，当地政府应当根据传染病疫情控制的需要，组织卫生、医药、公安、工商、交通、水利、城建、农业、商业、民政、邮电、广播电视等部门采取下列预防、控制措施：\n(一)对病人进行抢救、隔离治疗；\n(二)加强粪便管理，清除垃圾、污物；\n(三)加强自来水和其他饮用水的管理，保护饮用水源；\n(四)消除病媒昆虫、钉螺、鼠类及其他染疫动物；\n(五)加强易使传染病传播扩散活动的卫生管理；\n(六)开展防病知识的宣传；\n(七)组织对传染病病人、病原携带者、染疫动物密切接触人群的检疫、预防服药、应急接种等；\n(八)供应用于预防和控制疫情所必需的药品、生物制品、消毒药品、器械等；\n(九)保证居民生活必需品的供应。\n第五十三条 县级以上政府接到下一级政府关于采取《传染病防治法》第二十五条规定的紧急措施报告时，应当在二十四小时内做出决定。下一级政府在上一级政府作出决定前，必要时，可以临时采取《传染病防治法》第二十五条第一款第(一)、(四)项紧急措施，但不得超过二十四小时。\n第五十四条 撤销采取《传染病防治法》第二十五条紧急措施的条件是：\n(一)甲类传染病病人、病原携带者全部治愈，乙类传染病病人、病原携带者得到有效的隔离治疗；病人尸体得到严格消毒处理；\n(二)污染的物品及环境已经过消毒等卫生处理；有关病媒昆虫、染疫动物基本消除；\n(三)暴发、流行的传染病病种，经过最长潜伏期后，未发现新的传染病病人，疫情得到有效的控制。\n第五十五条 因患鼠疫、霍乱和炭疽病死亡的病人尸体，由治疗病人的医疗单位负责消毒处理，处理后应当立即火化。\n患病毒性肝炎、伤寒和副伤寒、艾滋病、白喉、炭疽、脊髓灰质炎死亡的病人尸体，由治疗病人的医疗单位或者当地卫生防疫机构消毒处理后火化。\n不具备火化条件的农村、边远地区，由治疗病人的医疗单位或者当地卫生防疫机构负责消毒后，可选远离居民点五百米以外、远离饮用水源五十米以外的地方，将尸体在距地面两米以下深埋。\n民族自治地方执行前款的规定，依照《传染病防治法》第二十八条第三款的规定办理。\n第五十六条 医疗保健机构、卫生防疫机构经县级以上政府卫生行政部门的批准可以对传染病病人尸体或者疑似传染病病人的尸体进行解剖查验。\n第五十七条 卫生防疫机构处理传染病疫情的人员，可以凭当地政府卫生行政部门出具的处理疫情证明及有效的身份证明，优先在铁路、交通、民航部门购票，铁路、交通、民航部门应当保证售给最近一次通往目的地的车、船、机票。\n交付运输的处理疫情的物品应当有明显标志，铁路、交通、民航部门应当保证用最快通往目的地的交通工具运出。\n第五十八条 用于传染病监督控制的车辆，其标志由国务院卫生行政部门会同有关部门统一制定。任何单位和个人不得阻拦依法执行处理疫情任务的车辆和人员。","level":1},{"name":"第五章 监督","text":"第五十九条 地方各级政府卫生行政部门、卫生防疫机构和受国务院卫生行政部门委托的其他有关部门卫生主管机构推荐的传染病管理监督员，由省级以上政府卫生行政部门聘任并发给证件。\n省级政府卫生行政部门聘任的传染病管理监督员，报国务院卫生行政部门备案。\n第六十条 传染病管理监督员执行下列任务：\n(一)监督检查《传染病防治法》及本办法的执行情况；\n(二)进行现场调查，包括采集必需的标本及查阅、索取、翻印复制必要的文字、图片、声像资料等，并根据调查情况写出书面报告；\n(三)对违法单位或者个人提出处罚建议；\n(四)执行卫生行政部门或者其他有关部门卫生主管机构交付的任务；\n(五)及时提出预防和控制传染病措施的建议。\n第六十一条 各级各类医疗保健机构内设立的传染病管理检查员，由本单位推荐，经县级以上政府卫生行政部门或受国务院卫生行政部门委托的其他部门卫生主管机构批准并发给证件。\n第六十二条 传染病管理检查员执行下列任务：\n(一)宣传《传染病防治法》及本办法，检查本单位和责任地段的传染病防治措施的实施和疫情报告执行情况；\n(二)对本单位和责任地段的传染病防治工作进行技术指导；\n(三)执行卫生行政部门和卫生防疫机构对本单位及责任地段提出的改进传染病防治管理工作的意见；\n(四)定期向卫生行政部门指定的卫生防疫机构汇报工作情况，遇到紧急情况及时报告。\n第六十三条 传染病管理监督员、传染病管理检查员执行任务时，有关单位和个人必须给予协助。\n第六十四条 传染病管理监督员的解聘和传染病管理检查员资格的取消，由原发证机关决定，并通知其所在单位和个人。\n第六十五条 县级以上政府卫生行政部门和受国务院卫生行政部门委托的部门，可以成立传染病技术鉴定组织。","level":1},{"name":"第六章 罚则","text":"第六十六条 有下列行为之一的，由县级以上政府卫生行政部门责令限期改正，可以处五千元以下的罚款；情节较严重的，可以处五千元以上二万元以下的罚款，对主管人员和直接责任人员由其所在单位或者上级机关给予行政处分：\n(一)集中式供水单位供应的饮用水不符合国家规定的《生活饮用水卫生标准》的；\n(二)单位自备水源未经批准与城镇供水系统连接的；\n(三)未按城市环境卫生设施标准修建公共卫生设施致使垃圾、粪便、污水不能进行无害化处理的；\n(四)对被传染病病原体污染的污水、污物、粪便不按规定进行消毒处理的；\n(五)对被甲类和乙类传染病病人、病原携带者、疑似传染病病人污染的场所、物品未按照卫生防疫机构的要求实施必要的卫生处理的；\n(六)造成传染病的医源性感染、医院内感染、实验室感染和致病性微生物扩散的；\n(七)生产、经营、使用消毒药剂和消毒器械、卫生用品、卫生材料、一次性医疗器材、隐形眼镜、人造器官等不符合国家卫生标准，可能造成传染病的传播、扩散或者造成传染病的传播、扩散的；\n(八)准许或者纵容传染病病人、病原携带者和疑似传染病病人，从事国务院卫生行政部门规定禁止从事的易使该传染病扩散的工作的；\n(九)传染病病人、病原携带者故意传播传染病，造成他人感染的；\n(十)甲类传染病病人、病原携带者或者疑似传染病病人，乙类传染病中艾滋病、肺炭疽病人拒绝进行隔离治疗的；\n(十一)招用流动人员的用工单位，未向卫生防疫机构报告并未采取卫生措施，造成传染病传播、流行的；\n(十二)违章养犬或者拒绝、阻挠捕杀违章犬，造成咬伤他人或者导致人群中发生狂犬病的。\n前款所称情节较严重的，是指下列情形之一：\n(一)造成甲类传染病、艾滋病、肺炭疽传播危险的；\n(二)造成除艾滋病、肺炭疽之外的乙、丙类传染病暴发、流行的；\n(三)造成传染病菌(毒)种扩散的；\n(四)造成病人残疾、死亡的；\n(五)拒绝执行《传染病防治法》及本办法的规定，屡经教育仍继续违法的。\n第六十七条 在自然疫源地和可能是自然疫源地的地区兴建大型建设项目未经卫生调查即进行施工的，由县级以上政府卫生行政部门责令限期改正，可以处二千元以上二万元以下的罚款。\n第六十八条 单位和个人出售、运输被传染病病原体污染和来自疫区可能被传染病病原体污染的皮毛、旧衣物及生活用品的，由县级以上政府卫生行政部门责令限期进行卫生处理，可以处出售金额一倍以下的罚款；造成传染病流行的，根据情节，可以处相当出售金额三倍以下的罚款，危害严重，出售金额不满二千元的，以二千元计算；对主管人员和直接责任人员由所在单位或者上级机关给予行政处分。\n第六十九条 单位和个人非法经营、出售用于预防传染病菌苗、疫苗等生物制品的，县级以上政府卫生行政部门可以处相当出售金额三倍以下的罚款，危害严重，出售金额不满五千元的，以五千元计算；对主管人员和直接责任人员由所在单位或者上级机关根据情节，可以给予行政处分。\n第七十条 有下列行为之一的单位和个人，县级以上政府卫生行政部门报请同级政府批准，对单位予以通报批评；对主管人员和直接责任人员由所在单位或者上级机关给予行政处分：\n(一)传染病暴发、流行时，妨碍或者拒绝执行政府采取紧急措施的；\n(二)传染病暴发、流行时，医疗保健人员、卫生防疫人员拒绝执行各级政府卫生行政部门调集其参加控制疫情的决定的；\n(三)对控制传染病暴发、流行负有责任的部门拒绝执行政府有关控制疫情决定的；\n(四)无故阻止和拦截依法执行处理疫情任务的车辆和人员的。\n第七十一条 执行职务的医疗保健人员、卫生防疫人员和责任单位，不报、漏报、迟报传染病疫情的，由县级以上政府卫生行政部门责令限期改正，对主管人员和直接责任人员由其所在单位或者上级机关根据情节，可以给予行政处分。\n个体行医人员在执行职务时，不报、漏报、迟报传染病疫情的，由县级以上政府卫生行政部门责令限期改正，限期内不改的，可以处一百元以上五百元以下罚款；对造成传染病传播流行的，可以处二百元以上二千元以下罚款。\n第七十二条 县级政府卫生行政部门可以作出处一万元以下罚款的决定；决定处一万元以上罚款的，须报上一级政府卫生行政部门批准。\n受国务院卫生行政部门委托的有关部门卫生主管机构可以作出处二千元以下罚款的决定；决定处二千元以上罚款的，须报当地县级以上政府卫生行政部门批准。\n县级以上政府卫生行政部门在收取罚款时，应当出具正式的罚款收据。罚款全部上缴国库。","level":1},{"name":"第七章 附则","text":"第七十三条 《传染病防治法》及本办法的用语含义如下：\n传染病病人、疑似传染病病人：指根据国务院卫生行政部门发布的《中华人民共和国传染病防治法规定管理的传染病诊断标准》，符合传染病病人和疑似传染病病人诊断标准的人。\n病原携带者：指感染病原体无临床症状但能排出病原体的人。\n暴发：指在一个局部地区，短期内，突然发生多例同一种传染病病人。\n流行：指一个地区某种传染病发病率显著超过该病历年的一般发病率水平。\n重大传染病疫情：指《传染病防治法》第二十五条所称的传染病的暴发、流行。\n传染病监测：指对人群传染病的发生、流行及影响因素进行有计划地、系统地长期观察。\n疫区：指传染病在人群中暴发或者流行，其病原体向周围传播时可能波及的地区。\n人畜共患传染病：指鼠疫、流行性出血热、狂犬病、钩端螺旋体病、布鲁氏菌病、炭疽、流行性乙型脑炎、黑热病、包虫病、血吸虫病。\n自然疫源地：指某些传染病的病原体在自然界的野生动物中长期保存并造成动物间流行的地区。\n可能是自然疫源地：指在自然界中具有自然疫源性疾病存在的传染源和传播媒介，但尚未查明的地区。\n医源性感染：指在医学服务中，因病原体传播引起的感染。\n医院内感染：指就诊患者在医疗保健机构内受到的感染。\n实验室感染：指从事实验室工作时，因接触病原体所致的感染。\n消毒：指用化学、物理、生物的方法杀灭或者消除环境中的致病性微生物。\n卫生处理：指消毒、杀虫、灭鼠等卫生措施以及隔离、留验、就地检验等医学措施。\n卫生防疫机构：指卫生防疫站、结核病防治研究所(院)、寄生虫病防治研究所(站)、血吸虫病防治研究所(站)、皮肤病性病防治研究所(站)、地方病防治研究所(站)、鼠疫防治站(所)、乡镇预防保健站(所)及与上述机构专业相同的单位。\n医疗保健机构：指医院、卫生院(所)、门诊部(所)、疗养院(所)、妇幼保健院(站)及与上述机构业务活动相同的单位。\n第七十四条 省、自治区、直辖市政府可以根据《传染病防治法》和本办法制定实施细则。\n第七十五条 本办法由国务院卫生行政部门负责解释。\n第七十六条 本办法自发布之日起施行。","level":1}]},{"id":"n0368","sections":[{"name":"","text":"罚款决定与罚款收缴分离实施办法\n(1997年11月17日中华人民共和国国务院令第235号发布 自1998年1月1日起施行)\n第一条 为了实施罚款决定与罚款收缴分离，加强对罚款收缴活动的监督，保证罚款及时上缴国库，根据《中华人民共和国行政处罚法》(以下简称行政处罚法)的规定，制定本办法。\n第二条 罚款的收取、缴纳及相关活动，适用本办法。\n第三条 作出罚款决定的行政机关应当与收缴罚款的机构分离；但是，依照行政处罚法的规定可以当场收缴罚款的除外。\n第四条 罚款必须全部上缴国库，任何行政机关、组织或者个人不得以任何形式截留、私分或者变相私分。\n行政机关执法所需经费的拨付，按照国家有关规定执行。\n第五条 经中国人民银行批准有代理收付款项业务的商业银行、信用合作社(以下简称代收机构)，可以开办代收罚款的业务。\n具体代收机构由县级以上地方人民政府组织本级财政部门、中国人民银行当地分支机构和依法具有行政处罚权的行政机关共同研究，统一确定。海关、外汇管理等实行垂直领导的依法具有行政处罚权的行政机关作出罚款决定的，具体代收机构由财政部、中国人民银行会同国务院有关部门确定。依法具有行政处罚权的国务院有关部门作出罚款决定的，具体代收机构由财政部、中国人民银行确定。\n代收机构应当具备足够的代收网点，以方便当事人缴纳罚款。\n第六条 行政机关应当依照本办法和国家有关规定，同代收机构签订代收罚款协议。\n代收罚款协议应当包括下列事项：\n(一)行政机关、代收机构名称；\n(二)具体代收网点；\n(三)代收机构上缴罚款的预算科目、预算级次；\n(四)代收机构告知行政机关代收罚款情况的方式、期限；\n(五)需要明确的其他事项。\n自代收罚款协议签订之日起15日内，行政机关应当将代收罚款协议报上一级行政机关和同级财政部门备案；代收机构应当将代收罚款协议报中国人民银行或者其当地分支机构备案。\n第七条 行政机关作出罚款决定的行政处罚决定书应当载明代收机构的名称、地址和当事人应当缴纳罚款的数额、期限等，并明确对当事人逾期缴纳罚款是否加处罚款。\n当事人应当按照行政处罚决定书确定的罚款数额、期限，到指定的代收机构缴纳罚款。\n第八条 代收机构代收罚款，应当向当事人出具罚款收据。\n罚款收据的格式和印制，由财政部规定。\n第九条 当事人逾期缴纳罚款，行政处罚决定书明确需要加处罚款的，代收机构应当按照行政处罚决定书加收罚款。\n当事人对加收罚款有异议的，应当先缴纳罚款和加收的罚款，再依法向作出行政处罚决定的行政机关申请复议。\n第十条 代收机构应当按照代收罚款协议规定的方式、期限，将当事人的姓名或者名称、缴纳罚款的数额、时间等情况书面告知作出行政处罚决定的行政机关。\n第十一条 代收机构应当按照行政处罚法和国家有关规定，将代收的罚款直接上缴国库。\n第十二条 国库应当按照《中华人民共和国国家金库条例》的规定，定期同财政部门和行政机关对账，以保证收受的罚款和上缴国库的罚款数额一致。\n第十三条 代收机构应当在代收网点、营业时间、服务设施、缴款手续等方面为当事人缴纳罚款提供方便。\n第十四条 财政部门应当向代收机构支付手续费，具体标准由财政部制定。\n第十五条 法律、法规授权的具有管理公共事务职能的组织和依法受委托的组织依法作出的罚款决定与罚款收缴，适用本办法。\n第十六条 本办法由财政部会同中国人民银行组织实施。\n第十七条 本办法自1998年1月1日起施行。","level":0}]},{"id":"n0369","sections":[{"name":"","text":"物业管理条例\n(2003年6月8日中华人民共和国国务院令第379号公布 根据2007年8月26日《国务院关于修改〈物业管理条例〉的决定》第一次修订 根据2016年2月6日《国务院关于修改部分行政法规的决定》第二次修订 根据2018年3月19日《国务院关于修改和废止部分行政法规的决定》第三次修订)","level":0},{"name":"第一章 总则","text":"第一条 为了规范物业管理活动，维护业主和物业服务企业的合法权益，改善人民群众的生活和工作环境，制定本条例。\n第二条 本条例所称物业管理，是指业主通过选聘物业服务企业，由业主和物业服务企业按照物业服务合同约定，对房屋及配套的设施设备和相关场地进行维修、养护、管理，维护物业管理区域内的环境卫生和相关秩序的活动。\n第三条 国家提倡业主通过公开、公平、公正的市场竞争机制选择物业服务企业。\n第四条 国家鼓励采用新技术、新方法，依靠科技进步提高物业管理和服务水平。\n第五条 国务院建设行政主管部门负责全国物业管理活动的监督管理工作。\n县级以上地方人民政府房地产行政主管部门负责本行政区域内物业管理活动的监督管理工作。","level":1},{"name":"第二章 业主及业主大会","text":"第六条 房屋的所有权人为业主。\n业主在物业管理活动中，享有下列权利：\n(一)按照物业服务合同的约定，接受物业服务企业提供的服务；\n(二)提议召开业主大会会议，并就物业管理的有关事项提出建议；\n(三)提出制定和修改管理规约、业主大会议事规则的建议；\n(四)参加业主大会会议，行使投票权；\n(五)选举业主委员会成员，并享有被选举权；\n(六)监督业主委员会的工作；\n(七)监督物业服务企业履行物业服务合同；\n(八)对物业共用部位、共用设施设备和相关场地使用情况享有知情权和监督权；\n(九)监督物业共用部位、共用设施设备专项维修资金(以下简称专项维修资金)的管理和使用；\n(十)法律、法规规定的其他权利。\n第七条 业主在物业管理活动中，履行下列义务：\n(一)遵守管理规约、业主大会议事规则；\n(二)遵守物业管理区域内物业共用部位和共用设施设备的使用、公共秩序和环境卫生的维护等方面的规章制度；\n(三)执行业主大会的决定和业主大会授权业主委员会作出的决定；\n(四)按照国家有关规定交纳专项维修资金；\n(五)按时交纳物业服务费用；\n(六)法律、法规规定的其他义务。\n第八条 物业管理区域内全体业主组成业主大会。\n业主大会应当代表和维护物业管理区域内全体业主在物业管理活动中的合法权益。\n第九条 一个物业管理区域成立一个业主大会。\n物业管理区域的划分应当考虑物业的共用设施设备、建筑物规模、社区建设等因素。具体办法由省、自治区、直辖市制定。\n第十条 同一个物业管理区域内的业主，应当在物业所在地的区、县人民政府房地产行政主管部门或者街道办事处、乡镇人民政府的指导下成立业主大会，并选举产生业主委员会。但是，只有一个业主的，或者业主人数较少且经全体业主一致同意，决定不成立业主大会的，由业主共同履行业主大会、业主委员会职责。\n第十一条 下列事项由业主共同决定：\n(一)制定和修改业主大会议事规则；\n(二)制定和修改管理规约；\n(三)选举业主委员会或者更换业主委员会成员；\n(四)选聘和解聘物业服务企业；\n(五)筹集和使用专项维修资金；\n(六)改建、重建建筑物及其附属设施；\n(七)有关共有和共同管理权利的其他重大事项。\n第十二条 业主大会会议可以采用集体讨论的形式，也可以采用书面征求意见的形式；但是，应当有物业管理区域内专有部分占建筑物总面积过半数的业主且占总人数过半数的业主参加。\n业主可以委托代理人参加业主大会会议。\n业主大会决定本条例第十一条第(五)项和第(六)项规定的事项，应当经专有部分占建筑物总面积2/3以上的业主且占总人数2/3以上的业主同意；决定本条例第十一条规定的其他事项，应当经专有部分占建筑物总面积过半数的业主且占总人数过半数的业主同意。\n业主大会或者业主委员会的决定，对业主具有约束力。\n业主大会或者业主委员会作出的决定侵害业主合法权益的，受侵害的业主可以请求人民法院予以撤销。\n第十三条 业主大会会议分为定期会议和临时会议。\n业主大会定期会议应当按照业主大会议事规则的规定召开。经20%以上的业主提议，业主委员会应当组织召开业主大会临时会议。\n第十四条 召开业主大会会议，应当于会议召开15日以前通知全体业主。\n住宅小区的业主大会会议，应当同时告知相关的居民委员会。\n业主委员会应当做好业主大会会议记录。\n第十五条 业主委员会执行业主大会的决定事项，履行下列职责：\n(一)召集业主大会会议，报告物业管理的实施情况；\n(二)代表业主与业主大会选聘的物业服务企业签订物业服务合同；\n(三)及时了解业主、物业使用人的意见和建议，监督和协助物业服务企业履行物业服务合同；\n(四)监督管理规约的实施；\n(五)业主大会赋予的其他职责。\n第十六条 业主委员会应当自选举产生之日起30日内，向物业所在地的区、县人民政府房地产行政主管部门和街道办事处、乡镇人民政府备案。\n业主委员会委员应当由热心公益事业、责任心强、具有一定组织能力的业主担任。\n业主委员会主任、副主任在业主委员会成员中推选产生。\n第十七条 管理规约应当对有关物业的使用、维护、管理，业主的共同利益，业主应当履行的义务，违反管理规约应当承担的责任等事项依法作出约定。\n管理规约应当尊重社会公德，不得违反法律、法规或者损害社会公共利益。\n管理规约对全体业主具有约束力。\n第十八条 业主大会议事规则应当就业主大会的议事方式、表决程序、业主委员会的组成和成员任期等事项作出约定。\n第十九条 业主大会、业主委员会应当依法履行职责，不得作出与物业管理无关的决定，不得从事与物业管理无关的活动。\n业主大会、业主委员会作出的决定违反法律、法规的，物业所在地的区、县人民政府房地产行政主管部门或者街道办事处、乡镇人民政府，应当责令限期改正或者撤销其决定，并通告全体业主。\n第二十条 业主大会、业主委员会应当配合公安机关，与居民委员会相互协作，共同做好维护物业管理区域内的社会治安等相关工作。\n在物业管理区域内，业主大会、业主委员会应当积极配合相关居民委员会依法履行自治管理职责，支持居民委员会开展工作，并接受其指导和监督。\n住宅小区的业主大会、业主委员会作出的决定，应当告知相关的居民委员会，并认真听取居民委员会的建议。","level":1},{"name":"第三章 前期物业管理","text":"第二十一条 在业主、业主大会选聘物业服务企业之前，建设单位选聘物业服务企业的，应当签订书面的前期物业服务合同。\n第二十二条 建设单位应当在销售物业之前，制定临时管理规约，对有关物业的使用、维护、管理，业主的共同利益，业主应当履行的义务，违反临时管理规约应当承担的责任等事项依法作出约定。\n建设单位制定的临时管理规约，不得侵害物业买受人的合法权益。\n第二十三条 建设单位应当在物业销售前将临时管理规约向物业买受人明示，并予以说明。\n物业买受人在与建设单位签订物业买卖合同时，应当对遵守临时管理规约予以书面承诺。\n第二十四条 国家提倡建设单位按照房地产开发与物业管理相分离的原则，通过招投标的方式选聘物业服务企业。\n住宅物业的建设单位，应当通过招投标的方式选聘物业服务企业；投标人少于3个或者住宅规模较小的，经物业所在地的区、县人民政府房地产行政主管部门批准，可以采用协议方式选聘物业服务企业。\n第二十五条 建设单位与物业买受人签订的买卖合同应当包含前期物业服务合同约定的内容。\n第二十六条 前期物业服务合同可以约定期限；但是，期限未满、业主委员会与物业服务企业签订的物业服务合同生效的，前期物业服务合同终止。\n第二十七条 业主依法享有的物业共用部位、共用设施设备的所有权或者使用权，建设单位不得擅自处分。\n第二十八条 物业服务企业承接物业时，应当对物业共用部位、共用设施设备进行查验。\n第二十九条 在办理物业承接验收手续时，建设单位应当向物业服务企业移交下列资料：\n(一)竣工总平面图，单体建筑、结构、设备竣工图，配套设施、地下管网工程竣工图等竣工验收资料；\n(二)设施设备的安装、使用和维护保养等技术资料；\n(三)物业质量保修文件和物业使用说明文件；\n(四)物业管理所必需的其他资料。\n物业服务企业应当在前期物业服务合同终止时将上述资料移交给业主委员会。\n第三十条 建设单位应当按照规定在物业管理区域内配置必要的物业管理用房。\n第三十一条 建设单位应当按照国家规定的保修期限和保修范围，承担物业的保修责任。","level":1},{"name":"第四章 物业管理服务","text":"第三十二条 从事物业管理活动的企业应当具有独立的法人资格。\n国务院建设行政主管部门应当会同有关部门建立守信联合激励和失信联合惩戒机制，加强行业诚信管理。\n第三十三条 一个物业管理区域由一个物业服务企业实施物业管理。\n第三十四条 业主委员会应当与业主大会选聘的物业服务企业订立书面的物业服务合同。\n物业服务合同应当对物业管理事项、服务质量、服务费用、双方的权利义务、专项维修资金的管理与使用、物业管理用房、合同期限、违约责任等内容进行约定。\n第三十五条 物业服务企业应当按照物业服务合同的约定，提供相应的服务。\n物业服务企业未能履行物业服务合同的约定，导致业主人身、财产安全受到损害的，应当依法承担相应的法律责任。\n第三十六条 物业服务企业承接物业时，应当与业主委员会办理物业验收手续。\n业主委员会应当向物业服务企业移交本条例第二十九条第一款规定的资料。\n第三十七条 物业管理用房的所有权依法属于业主。未经业主大会同意，物业服务企业不得改变物业管理用房的用途。\n第三十八条 物业服务合同终止时，物业服务企业应当将物业管理用房和本条例第二十九条第一款规定的资料交还给业主委员会。\n物业服务合同终止时，业主大会选聘了新的物业服务企业的，物业服务企业之间应当做好交接工作。\n第三十九条 物业服务企业可以将物业管理区域内的专项服务业务委托给专业性服务企业，但不得将该区域内的全部物业管理一并委托给他人。\n第四十条 物业服务收费应当遵循合理、公开以及费用与服务水平相适应的原则，区别不同物业的性质和特点，由业主和物业服务企业按照国务院价格主管部门会同国务院建设行政主管部门制定的物业服务收费办法，在物业服务合同中约定。\n第四十一条 业主应当根据物业服务合同的约定交纳物业服务费用。业主与物业使用人约定由物业使用人交纳物业服务费用的，从其约定，业主负连带交纳责任。\n已竣工但尚未出售或者尚未交给物业买受人的物业，物业服务费用由建设单位交纳。\n第四十二条 县级以上人民政府价格主管部门会同同级房地产行政主管部门，应当加强对物业服务收费的监督。\n第四十三条 物业服务企业可以根据业主的委托提供物业服务合同约定以外的服务项目，服务报酬由双方约定。\n第四十四条 物业管理区域内，供水、供电、供气、供热、通信、有线电视等单位应当向最终用户收取有关费用。\n物业服务企业接受委托代收前款费用的，不得向业主收取手续费等额外费用。\n第四十五条 对物业管理区域内违反有关治安、环保、物业装饰装修和使用等方面法律、法规规定的行为，物业服务企业应当制止，并及时向有关行政管理部门报告。\n有关行政管理部门在接到物业服务企业的报告后，应当依法对违法行为予以制止或者依法处理。\n第四十六条 物业服务企业应当协助做好物业管理区域内的安全防范工作。发生安全事故时，物业服务企业在采取应急措施的同时，应当及时向有关行政管理部门报告，协助做好救助工作。\n物业服务企业雇请保安人员的，应当遵守国家有关规定。保安人员在维护物业管理区域内的公共秩序时，应当履行职责，不得侵害公民的合法权益。\n第四十七条 物业使用人在物业管理活动中的权利义务由业主和物业使用人约定，但不得违反法律、法规和管理规约的有关规定。\n物业使用人违反本条例和管理规约的规定，有关业主应当承担连带责任。\n第四十八条 县级以上地方人民政府房地产行政主管部门应当及时处理业主、业主委员会、物业使用人和物业服务企业在物业管理活动中的投诉。","level":1},{"name":"第五章 物业的使用与维护","text":"第四十九条 物业管理区域内按照规划建设的公共建筑和共用设施，不得改变用途。\n业主依法确需改变公共建筑和共用设施用途的，应当在依法办理有关手续后告知物业服务企业；物业服务企业确需改变公共建筑和共用设施用途的，应当提请业主大会讨论决定同意后，由业主依法办理有关手续。\n第五十条 业主、物业服务企业不得擅自占用、挖掘物业管理区域内的道路、场地，损害业主的共同利益。\n因维修物业或者公共利益，业主确需临时占用、挖掘道路、场地的，应当征得业主委员会和物业服务企业的同意；物业服务企业确需临时占用、挖掘道路、场地的，应当征得业主委员会的同意。\n业主、物业服务企业应当将临时占用、挖掘的道路、场地，在约定期限内恢复原状。\n第五十一条 供水、供电、供气、供热、通信、有线电视等单位，应当依法承担物业管理区域内相关管线和设施设备维修、养护的责任。\n前款规定的单位因维修、养护等需要，临时占用、挖掘道路、场地的，应当及时恢复原状。\n第五十二条 业主需要装饰装修房屋的，应当事先告知物业服务企业。\n物业服务企业应当将房屋装饰装修中的禁止行为和注意事项告知业主。\n第五十三条 住宅物业、住宅小区内的非住宅物业或者与单幢住宅楼结构相连的非住宅物业的业主，应当按照国家有关规定交纳专项维修资金。\n专项维修资金属于业主所有，专项用于物业保修期满后物业共用部位、共用设施设备的维修和更新、改造，不得挪作他用。\n专项维修资金收取、使用、管理的办法由国务院建设行政主管部门会同国务院财政部门制定。\n第五十四条 利用物业共用部位、共用设施设备进行经营的，应当在征得相关业主、业主大会、物业服务企业的同意后，按照规定办理有关手续。业主所得收益应当主要用于补充专项维修资金，也可以按照业主大会的决定使用。\n第五十五条 物业存在安全隐患，危及公共利益及他人合法权益时，责任人应当及时维修养护，有关业主应当给予配合。\n责任人不履行维修养护义务的，经业主大会同意，可以由物业服务企业维修养护，费用由责任人承担。","level":1},{"name":"第六章 法律责任","text":"第五十六条 违反本条例的规定，住宅物业的建设单位未通过招投标的方式选聘物业服务企业或者未经批准，擅自采用协议方式选聘物业服务企业的，由县级以上地方人民政府房地产行政主管部门责令限期改正，给予警告，可以并处10万元以下的罚款。\n第五十七条 违反本条例的规定，建设单位擅自处分属于业主的物业共用部位、共用设施设备的所有权或者使用权的，由县级以上地方人民政府房地产行政主管部门处5万元以上20万元以下的罚款；给业主造成损失的，依法承担赔偿责任。\n第五十八条 违反本条例的规定，不移交有关资料的，由县级以上地方人民政府房地产行政主管部门责令限期改正；逾期仍不移交有关资料的，对建设单位、物业服务企业予以通报，处1万元以上10万元以下的罚款。\n第五十九条 违反本条例的规定，物业服务企业将一个物业管理区域内的全部物业管理一并委托给他人的，由县级以上地方人民政府房地产行政主管部门责令限期改正，处委托合同价款30%以上50%以下的罚款。委托所得收益，用于物业管理区域内物业共用部位、共用设施设备的维修、养护，剩余部分按照业主大会的决定使用；给业主造成损失的，依法承担赔偿责任。\n第六十条 违反本条例的规定，挪用专项维修资金的，由县级以上地方人民政府房地产行政主管部门追回挪用的专项维修资金，给予警告，没收违法所得，可以并处挪用数额2倍以下的罚款；构成犯罪的，依法追究直接负责的主管人员和其他直接责任人员的刑事责任。\n第六十一条 违反本条例的规定，建设单位在物业管理区域内不按照规定配置必要的物业管理用房的，由县级以上地方人民政府房地产行政主管部门责令限期改正，给予警告，没收违法所得，并处10万元以上50万元以下的罚款。\n第六十二条 违反本条例的规定，未经业主大会同意，物业服务企业擅自改变物业管理用房的用途的，由县级以上地方人民政府房地产行政主管部门责令限期改正，给予警告，并处1万元以上10万元以下的罚款；有收益的，所得收益用于物业管理区域内物业共用部位、共用设施设备的维修、养护，剩余部分按照业主大会的决定使用。\n第六十三条 违反本条例的规定，有下列行为之一的，由县级以上地方人民政府房地产行政主管部门责令限期改正，给予警告，并按照本条第二款的规定处以罚款；所得收益，用于物业管理区域内物业共用部位、共用设施设备的维修、养护，剩余部分按照业主大会的决定使用：\n(一)擅自改变物业管理区域内按照规划建设的公共建筑和共用设施用途的；\n(二)擅自占用、挖掘物业管理区域内道路、场地，损害业主共同利益的；\n(三)擅自利用物业共用部位、共用设施设备进行经营的。\n个人有前款规定行为之一的，处1000元以上1万元以下的罚款；单位有前款规定行为之一的，处5万元以上20万元以下的罚款。\n第六十四条 违反物业服务合同约定，业主逾期不交纳物业服务费用的，业主委员会应当督促其限期交纳；逾期仍不交纳的，物业服务企业可以向人民法院起诉。\n第六十五条 业主以业主大会或者业主委员会的名义，从事违反法律、法规的活动，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予治安管理处罚。\n第六十六条 违反本条例的规定，国务院建设行政主管部门、县级以上地方人民政府房地产行政主管部门或者其他有关行政管理部门的工作人员利用职务上的便利，收受他人财物或者其他好处，不依法履行监督管理职责，或者发现违法行为不予查处，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。","level":1},{"name":"第七章 附则","text":"第六十七条 本条例自2003年9月1日起施行。","level":1}]},{"id":"n0370","sections":[{"name":"","text":"中华人民共和国食品安全法实施条例\n(2009年7月20日中华人民共和国国务院令第557号公布 根据2016年2月6日《国务院关于修改部分行政法规的决定》修订 2019年3月26日国务院第42次常务会议修订通过 2019年10月11日中华人民共和国国务院令第721号公布 自2019年12月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 根据《中华人民共和国食品安全法》(以下简称食品安全法)，制定本条例。\n第二条 食品生产经营者应当依照法律、法规和食品安全标准从事生产经营活动，建立健全食品安全管理制度，采取有效措施预防和控制食品安全风险，保证食品安全。\n第三条 国务院食品安全委员会负责分析食品安全形势，研究部署、统筹指导食品安全工作，提出食品安全监督管理的重大政策措施，督促落实食品安全监督管理责任。县级以上地方人民政府食品安全委员会按照本级人民政府规定的职责开展工作。\n第四条 县级以上人民政府建立统一权威的食品安全监督管理体制，加强食品安全监督管理能力建设。\n县级以上人民政府食品安全监督管理部门和其他有关部门应当依法履行职责，加强协调配合，做好食品安全监督管理工作。\n乡镇人民政府和街道办事处应当支持、协助县级人民政府食品安全监督管理部门及其派出机构依法开展食品安全监督管理工作。\n第五条 国家将食品安全知识纳入国民素质教育内容，普及食品安全科学常识和法律知识，提高全社会的食品安全意识。","level":1},{"name":"第二章 食品安全风险监测和评估","text":"第六条 县级以上人民政府卫生行政部门会同同级食品安全监督管理等部门建立食品安全风险监测会商机制，汇总、分析风险监测数据，研判食品安全风险，形成食品安全风险监测分析报告，报本级人民政府；县级以上地方人民政府卫生行政部门还应当将食品安全风险监测分析报告同时报上一级人民政府卫生行政部门。食品安全风险监测会商的具体办法由国务院卫生行政部门会同国务院食品安全监督管理等部门制定。\n第七条 食品安全风险监测结果表明存在食品安全隐患，食品安全监督管理等部门经进一步调查确认有必要通知相关食品生产经营者的，应当及时通知。\n接到通知的食品生产经营者应当立即进行自查，发现食品不符合食品安全标准或者有证据证明可能危害人体健康的，应当依照食品安全法第六十三条的规定停止生产、经营，实施食品召回，并报告相关情况。\n第八条 国务院卫生行政、食品安全监督管理等部门发现需要对农药、肥料、兽药、饲料和饲料添加剂等进行安全性评估的，应当向国务院农业行政部门提出安全性评估建议。国务院农业行政部门应当及时组织评估，并向国务院有关部门通报评估结果。\n第九条 国务院食品安全监督管理部门和其他有关部门建立食品安全风险信息交流机制，明确食品安全风险信息交流的内容、程序和要求。","level":1},{"name":"第三章 食品安全标准","text":"第十条 国务院卫生行政部门会同国务院食品安全监督管理、农业行政等部门制定食品安全国家标准规划及其年度实施计划。国务院卫生行政部门应当在其网站上公布食品安全国家标准规划及其年度实施计划的草案，公开征求意见。\n第十一条 省、自治区、直辖市人民政府卫生行政部门依照食品安全法第二十九条的规定制定食品安全地方标准，应当公开征求意见。省、自治区、直辖市人民政府卫生行政部门应当自食品安全地方标准公布之日起30个工作日内，将地方标准报国务院卫生行政部门备案。国务院卫生行政部门发现备案的食品安全地方标准违反法律、法规或者食品安全国家标准的，应当及时予以纠正。\n食品安全地方标准依法废止的，省、自治区、直辖市人民政府卫生行政部门应当及时在其网站上公布废止情况。\n第十二条 保健食品、特殊医学用途配方食品、婴幼儿配方食品等特殊食品不属于地方特色食品，不得对其制定食品安全地方标准。\n第十三条 食品安全标准公布后，食品生产经营者可以在食品安全标准规定的实施日期之前实施并公开提前实施情况。\n第十四条 食品生产企业不得制定低于食品安全国家标准或者地方标准要求的企业标准。食品生产企业制定食品安全指标严于食品安全国家标准或者地方标准的企业标准的，应当报省、自治区、直辖市人民政府卫生行政部门备案。\n食品生产企业制定企业标准的，应当公开，供公众免费查阅。","level":1},{"name":"第四章 食品生产经营","text":"第十五条 食品生产经营许可的有效期为5年。\n食品生产经营者的生产经营条件发生变化，不再符合食品生产经营要求的，食品生产经营者应当立即采取整改措施；需要重新办理许可手续的，应当依法办理。\n第十六条 国务院卫生行政部门应当及时公布新的食品原料、食品添加剂新品种和食品相关产品新品种目录以及所适用的食品安全国家标准。\n对按照传统既是食品又是中药材的物质目录，国务院卫生行政部门会同国务院食品安全监督管理部门应当及时更新。\n第十七条 国务院食品安全监督管理部门会同国务院农业行政等有关部门明确食品安全全程追溯基本要求，指导食品生产经营者通过信息化手段建立、完善食品安全追溯体系。\n食品安全监督管理等部门应当将婴幼儿配方食品等针对特定人群的食品以及其他食品安全风险较高或者销售量大的食品的追溯体系建设作为监督检查的重点。\n第十八条 食品生产经营者应当建立食品安全追溯体系，依照食品安全法的规定如实记录并保存进货查验、出厂检验、食品销售等信息，保证食品可追溯。\n第十九条 食品生产经营企业的主要负责人对本企业的食品安全工作全面负责，建立并落实本企业的食品安全责任制，加强供货者管理、进货查验和出厂检验、生产经营过程控制、食品安全自查等工作。食品生产经营企业的食品安全管理人员应当协助企业主要负责人做好食品安全管理工作。\n第二十条 食品生产经营企业应当加强对食品安全管理人员的培训和考核。食品安全管理人员应当掌握与其岗位相适应的食品安全法律、法规、标准和专业知识，具备食品安全管理能力。食品安全监督管理部门应当对企业食品安全管理人员进行随机监督抽查考核。考核指南由国务院食品安全监督管理部门制定、公布。\n第二十一条 食品、食品添加剂生产经营者委托生产食品、食品添加剂的，应当委托取得食品生产许可、食品添加剂生产许可的生产者生产，并对其生产行为进行监督，对委托生产的食品、食品添加剂的安全负责。受托方应当依照法律、法规、食品安全标准以及合同约定进行生产，对生产行为负责，并接受委托方的监督。\n第二十二条 食品生产经营者不得在食品生产、加工场所贮存依照本条例第六十三条规定制定的名录中的物质。\n第二十三条 对食品进行辐照加工，应当遵守食品安全国家标准，并按照食品安全国家标准的要求对辐照加工食品进行检验和标注。\n第二十四条 贮存、运输对温度、湿度等有特殊要求的食品，应当具备保温、冷藏或者冷冻等设备设施，并保持有效运行。\n第二十五条 食品生产经营者委托贮存、运输食品的，应当对受托方的食品安全保障能力进行审核，并监督受托方按照保证食品安全的要求贮存、运输食品。受托方应当保证食品贮存、运输条件符合食品安全的要求，加强食品贮存、运输过程管理。\n接受食品生产经营者委托贮存、运输食品的，应当如实记录委托方和收货方的名称、地址、联系方式等内容。记录保存期限不得少于贮存、运输结束后2年。\n非食品生产经营者从事对温度、湿度等有特殊要求的食品贮存业务的，应当自取得营业执照之日起30个工作日内向所在地县级人民政府食品安全监督管理部门备案。\n第二十六条 餐饮服务提供者委托餐具饮具集中消毒服务单位提供清洗消毒服务的，应当查验、留存餐具饮具集中消毒服务单位的营业执照复印件和消毒合格证明。保存期限不得少于消毒餐具饮具使用期限到期后6个月。\n第二十七条 餐具饮具集中消毒服务单位应当建立餐具饮具出厂检验记录制度，如实记录出厂餐具饮具的数量、消毒日期和批号、使用期限、出厂日期以及委托方名称、地址、联系方式等内容。出厂检验记录保存期限不得少于消毒餐具饮具使用期限到期后6个月。消毒后的餐具饮具应当在独立包装上标注单位名称、地址、联系方式、消毒日期和批号以及使用期限等内容。\n第二十八条 学校、托幼机构、养老机构、建筑工地等集中用餐单位的食堂应当执行原料控制、餐具饮具清洗消毒、食品留样等制度，并依照食品安全法第四十七条的规定定期开展食堂食品安全自查。\n承包经营集中用餐单位食堂的，应当依法取得食品经营许可，并对食堂的食品安全负责。集中用餐单位应当督促承包方落实食品安全管理制度，承担管理责任。\n第二十九条 食品生产经营者应当对变质、超过保质期或者回收的食品进行显著标示或者单独存放在有明确标志的场所，及时采取无害化处理、销毁等措施并如实记录。\n食品安全法所称回收食品，是指已经售出，因违反法律、法规、食品安全标准或者超过保质期等原因，被召回或者退回的食品，不包括依照食品安全法第六十三条第三款的规定可以继续销售的食品。\n第三十条 县级以上地方人民政府根据需要建设必要的食品无害化处理和销毁设施。食品生产经营者可以按照规定使用政府建设的设施对食品进行无害化处理或者予以销毁。\n第三十一条 食品集中交易市场的开办者、食品展销会的举办者应当在市场开业或者展销会举办前向所在地县级人民政府食品安全监督管理部门报告。\n第三十二条 网络食品交易第三方平台提供者应当妥善保存入网食品经营者的登记信息和交易信息。县级以上人民政府食品安全监督管理部门开展食品安全监督检查、食品安全案件调查处理、食品安全事故处置确需了解有关信息的，经其负责人批准，可以要求网络食品交易第三方平台提供者提供，网络食品交易第三方平台提供者应当按照要求提供。县级以上人民政府食品安全监督管理部门及其工作人员对网络食品交易第三方平台提供者提供的信息依法负有保密义务。\n第三十三条 生产经营转基因食品应当显著标示，标示办法由国务院食品安全监督管理部门会同国务院农业行政部门制定。\n第三十四条 禁止利用包括会议、讲座、健康咨询在内的任何方式对食品进行虚假宣传。食品安全监督管理部门发现虚假宣传行为的，应当依法及时处理。\n第三十五条 保健食品生产工艺有原料提取、纯化等前处理工序的，生产企业应当具备相应的原料前处理能力。\n第三十六条 特殊医学用途配方食品生产企业应当按照食品安全国家标准规定的检验项目对出厂产品实施逐批检验。\n特殊医学用途配方食品中的特定全营养配方食品应当通过医疗机构或者药品零售企业向消费者销售。医疗机构、药品零售企业销售特定全营养配方食品的，不需要取得食品经营许可，但是应当遵守食品安全法和本条例关于食品销售的规定。\n第三十七条 特殊医学用途配方食品中的特定全营养配方食品广告按照处方药广告管理，其他类别的特殊医学用途配方食品广告按照非处方药广告管理。\n第三十八条 对保健食品之外的其他食品，不得声称具有保健功能。\n对添加食品安全国家标准规定的选择性添加物质的婴幼儿配方食品，不得以选择性添加物质命名。\n第三十九条 特殊食品的标签、说明书内容应当与注册或者备案的标签、说明书一致。销售特殊食品，应当核对食品标签、说明书内容是否与注册或者备案的标签、说明书一致，不一致的不得销售。省级以上人民政府食品安全监督管理部门应当在其网站上公布注册或者备案的特殊食品的标签、说明书。\n特殊食品不得与普通食品或者药品混放销售。","level":1},{"name":"第五章 食品检验","text":"第四十条 对食品进行抽样检验，应当按照食品安全标准、注册或者备案的特殊食品的产品技术要求以及国家有关规定确定的检验项目和检验方法进行。\n第四十一条 对可能掺杂掺假的食品，按照现有食品安全标准规定的检验项目和检验方法以及依照食品安全法第一百一十一条和本条例第六十三条规定制定的检验项目和检验方法无法检验的，国务院食品安全监督管理部门可以制定补充检验项目和检验方法，用于对食品的抽样检验、食品安全案件调查处理和食品安全事故处置。\n第四十二条 依照食品安全法第八十八条的规定申请复检的，申请人应当向复检机构先行支付复检费用。复检结论表明食品不合格的，复检费用由复检申请人承担；复检结论表明食品合格的，复检费用由实施抽样检验的食品安全监督管理部门承担。\n复检机构无正当理由不得拒绝承担复检任务。\n第四十三条 任何单位和个人不得发布未依法取得资质认定的食品检验机构出具的食品检验信息，不得利用上述检验信息对食品、食品生产经营者进行等级评定，欺骗、误导消费者。","level":1},{"name":"第六章 食品进出口","text":"第四十四条 进口商进口食品、食品添加剂，应当按照规定向出入境检验检疫机构报检，如实申报产品相关信息，并随附法律、行政法规规定的合格证明材料。\n第四十五条 进口食品运达口岸后，应当存放在出入境检验检疫机构指定或者认可的场所；需要移动的，应当按照出入境检验检疫机构的要求采取必要的安全防护措施。大宗散装进口食品应当在卸货口岸进行检验。\n第四十六条 国家出入境检验检疫部门根据风险管理需要，可以对部分食品实行指定口岸进口。\n第四十七条 国务院卫生行政部门依照食品安全法第九十三条的规定对境外出口商、境外生产企业或者其委托的进口商提交的相关国家(地区)标准或者国际标准进行审查，认为符合食品安全要求的，决定暂予适用并予以公布；暂予适用的标准公布前，不得进口尚无食品安全国家标准的食品。\n食品安全国家标准中通用标准已经涵盖的食品不属于食品安全法第九十三条规定的尚无食品安全国家标准的食品。\n第四十八条 进口商应当建立境外出口商、境外生产企业审核制度，重点审核境外出口商、境外生产企业制定和执行食品安全风险控制措施的情况以及向我国出口的食品是否符合食品安全法、本条例和其他有关法律、行政法规的规定以及食品安全国家标准的要求。\n第四十九条 进口商依照食品安全法第九十四条第三款的规定召回进口食品的，应当将食品召回和处理情况向所在地县级人民政府食品安全监督管理部门和所在地出入境检验检疫机构报告。\n第五十条 国家出入境检验检疫部门发现已经注册的境外食品生产企业不再符合注册要求的，应当责令其在规定期限内整改，整改期间暂停进口其生产的食品；经整改仍不符合注册要求的，国家出入境检验检疫部门应当撤销境外食品生产企业注册并公告。\n第五十一条 对通过我国良好生产规范、危害分析与关键控制点体系认证的境外生产企业，认证机构应当依法实施跟踪调查。对不再符合认证要求的企业，认证机构应当依法撤销认证并向社会公布。\n第五十二条 境外发生的食品安全事件可能对我国境内造成影响，或者在进口食品、食品添加剂、食品相关产品中发现严重食品安全问题的，国家出入境检验检疫部门应当及时进行风险预警，并可以对相关的食品、食品添加剂、食品相关产品采取下列控制措施：\n(一)退货或者销毁处理；\n(二)有条件地限制进口；\n(三)暂停或者禁止进口。\n第五十三条 出口食品、食品添加剂的生产企业应当保证其出口食品、食品添加剂符合进口国家(地区)的标准或者合同要求；我国缔结或者参加的国际条约、协定有要求的，还应当符合国际条约、协定的要求。","level":1},{"name":"第七章 食品安全事故处置","text":"第五十四条 食品安全事故按照国家食品安全事故应急预案实行分级管理。县级以上人民政府食品安全监督管理部门会同同级有关部门负责食品安全事故调查处理。\n县级以上人民政府应当根据实际情况及时修改、完善食品安全事故应急预案。\n第五十五条 县级以上人民政府应当完善食品安全事故应急管理机制，改善应急装备，做好应急物资储备和应急队伍建设，加强应急培训、演练。\n第五十六条 发生食品安全事故的单位应当对导致或者可能导致食品安全事故的食品及原料、工具、设备、设施等，立即采取封存等控制措施。\n第五十七条 县级以上人民政府食品安全监督管理部门接到食品安全事故报告后，应当立即会同同级卫生行政、农业行政等部门依照食品安全法第一百零五条的规定进行调查处理。食品安全监督管理部门应当对事故单位封存的食品及原料、工具、设备、设施等予以保护，需要封存而事故单位尚未封存的应当直接封存或者责令事故单位立即封存，并通知疾病预防控制机构对与事故有关的因素开展流行病学调查。\n疾病预防控制机构应当在调查结束后向同级食品安全监督管理、卫生行政部门同时提交流行病学调查报告。\n任何单位和个人不得拒绝、阻挠疾病预防控制机构开展流行病学调查。有关部门应当对疾病预防控制机构开展流行病学调查予以协助。\n第五十八条 国务院食品安全监督管理部门会同国务院卫生行政、农业行政等部门定期对全国食品安全事故情况进行分析，完善食品安全监督管理措施，预防和减少事故的发生。","level":1},{"name":"第八章 监督管理","text":"第五十九条 设区的市级以上人民政府食品安全监督管理部门根据监督管理工作需要，可以对由下级人民政府食品安全监督管理部门负责日常监督管理的食品生产经营者实施随机监督检查，也可以组织下级人民政府食品安全监督管理部门对食品生产经营者实施异地监督检查。\n设区的市级以上人民政府食品安全监督管理部门认为必要的，可以直接调查处理下级人民政府食品安全监督管理部门管辖的食品安全违法案件，也可以指定其他下级人民政府食品安全监督管理部门调查处理。\n第六十条 国家建立食品安全检查员制度，依托现有资源加强职业化检查员队伍建设，强化考核培训，提高检查员专业化水平。\n第六十一条 县级以上人民政府食品安全监督管理部门依照食品安全法第一百一十条的规定实施查封、扣押措施，查封、扣押的期限不得超过30日；情况复杂的，经实施查封、扣押措施的食品安全监督管理部门负责人批准，可以延长，延长期限不得超过45日。\n第六十二条 网络食品交易第三方平台多次出现入网食品经营者违法经营或者入网食品经营者的违法经营行为造成严重后果的，县级以上人民政府食品安全监督管理部门可以对网络食品交易第三方平台提供者的法定代表人或者主要负责人进行责任约谈。\n第六十三条 国务院食品安全监督管理部门会同国务院卫生行政等部门根据食源性疾病信息、食品安全风险监测信息和监督管理信息等，对发现的添加或者可能添加到食品中的非食品用化学物质和其他可能危害人体健康的物质，制定名录及检测方法并予以公布。\n第六十四条 县级以上地方人民政府卫生行政部门应当对餐具饮具集中消毒服务单位进行监督检查，发现不符合法律、法规、国家相关标准以及相关卫生规范等要求的，应当及时调查处理。监督检查的结果应当向社会公布。\n第六十五条 国家实行食品安全违法行为举报奖励制度，对查证属实的举报，给予举报人奖励。举报人举报所在企业食品安全重大违法犯罪行为的，应当加大奖励力度。有关部门应当对举报人的信息予以保密，保护举报人的合法权益。食品安全违法行为举报奖励办法由国务院食品安全监督管理部门会同国务院财政等有关部门制定。\n食品安全违法行为举报奖励资金纳入各级人民政府预算。\n第六十六条 国务院食品安全监督管理部门应当会同国务院有关部门建立守信联合激励和失信联合惩戒机制，结合食品生产经营者信用档案，建立严重违法生产经营者黑名单制度，将食品安全信用状况与准入、融资、信贷、征信等相衔接，及时向社会公布。","level":1},{"name":"第九章 法律责任","text":"第六十七条 有下列情形之一的，属于食品安全法第一百二十三条至第一百二十六条、第一百三十二条以及本条例第七十二条、第七十三条规定的情节严重情形：\n(一)违法行为涉及的产品货值金额2万元以上或者违法行为持续时间3个月以上；\n(二)造成食源性疾病并出现死亡病例，或者造成30人以上食源性疾病但未出现死亡病例；\n(三)故意提供虚假信息或者隐瞒真实情况；\n(四)拒绝、逃避监督检查；\n(五)因违反食品安全法律、法规受到行政处罚后1年内又实施同一性质的食品安全违法行为，或者因违反食品安全法律、法规受到刑事处罚后又实施食品安全违法行为；\n(六)其他情节严重的情形。\n对情节严重的违法行为处以罚款时，应当依法从重从严。\n第六十八条 有下列情形之一的，依照食品安全法第一百二十五条第一款、本条例第七十五条的规定给予处罚：\n(一)在食品生产、加工场所贮存依照本条例第六十三条规定制定的名录中的物质；\n(二)生产经营的保健食品之外的食品的标签、说明书声称具有保健功能；\n(三)以食品安全国家标准规定的选择性添加物质命名婴幼儿配方食品；\n(四)生产经营的特殊食品的标签、说明书内容与注册或者备案的标签、说明书不一致。\n第六十九条 有下列情形之一的，依照食品安全法第一百二十六条第一款、本条例第七十五条的规定给予处罚：\n(一)接受食品生产经营者委托贮存、运输食品，未按照规定记录保存信息；\n(二)餐饮服务提供者未查验、留存餐具饮具集中消毒服务单位的营业执照复印件和消毒合格证明；\n(三)食品生产经营者未按照规定对变质、超过保质期或者回收的食品进行标示或者存放，或者未及时对上述食品采取无害化处理、销毁等措施并如实记录；\n(四)医疗机构和药品零售企业之外的单位或者个人向消费者销售特殊医学用途配方食品中的特定全营养配方食品；\n(五)将特殊食品与普通食品或者药品混放销售。\n第七十条 除食品安全法第一百二十五条第一款、第一百二十六条规定的情形外，食品生产经营者的生产经营行为不符合食品安全法第三十三条第一款第五项、第七项至第十项的规定，或者不符合有关食品生产经营过程要求的食品安全国家标准的，依照食品安全法第一百二十六条第一款、本条例第七十五条的规定给予处罚。\n第七十一条 餐具饮具集中消毒服务单位未按照规定建立并遵守出厂检验记录制度的，由县级以上人民政府卫生行政部门依照食品安全法第一百二十六条第一款、本条例第七十五条的规定给予处罚。\n第七十二条 从事对温度、湿度等有特殊要求的食品贮存业务的非食品生产经营者，食品集中交易市场的开办者、食品展销会的举办者，未按照规定备案或者报告的，由县级以上人民政府食品安全监督管理部门责令改正，给予警告；拒不改正的，处1万元以上5万元以下罚款；情节严重的，责令停产停业，并处5万元以上20万元以下罚款。\n第七十三条 利用会议、讲座、健康咨询等方式对食品进行虚假宣传的，由县级以上人民政府食品安全监督管理部门责令消除影响，有违法所得的，没收违法所得；情节严重的，依照食品安全法第一百四十条第五款的规定进行处罚；属于单位违法的，还应当依照本条例第七十五条的规定对单位的法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员给予处罚。\n第七十四条 食品生产经营者生产经营的食品符合食品安全标准但不符合食品所标注的企业标准规定的食品安全指标的，由县级以上人民政府食品安全监督管理部门给予警告，并责令食品经营者停止经营该食品，责令食品生产企业改正；拒不停止经营或者改正的，没收不符合企业标准规定的食品安全指标的食品，货值金额不足1万元的，并处1万元以上5万元以下罚款，货值金额1万元以上的，并处货值金额5倍以上10倍以下罚款。\n第七十五条 食品生产经营企业等单位有食品安全法规定的违法情形，除依照食品安全法的规定给予处罚外，有下列情形之一的，对单位的法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员处以其上一年度从本单位取得收入的1倍以上10倍以下罚款：\n(一)故意实施违法行为；\n(二)违法行为性质恶劣；\n(三)违法行为造成严重后果。\n属于食品安全法第一百二十五条第二款规定情形的，不适用前款规定。\n第七十六条 食品生产经营者依照食品安全法第六十三条第一款、第二款的规定停止生产、经营，实施食品召回，或者采取其他有效措施减轻或者消除食品安全风险，未造成危害后果的，可以从轻或者减轻处罚。\n第七十七条 县级以上地方人民政府食品安全监督管理等部门对有食品安全法第一百二十三条规定的违法情形且情节严重，可能需要行政拘留的，应当及时将案件及有关材料移送同级公安机关。公安机关认为需要补充材料的，食品安全监督管理等部门应当及时提供。公安机关经审查认为不符合行政拘留条件的，应当及时将案件及有关材料退回移送的食品安全监督管理等部门。\n第七十八条 公安机关对发现的食品安全违法行为，经审查没有犯罪事实或者立案侦查后认为不需要追究刑事责任，但依法应当予以行政拘留的，应当及时作出行政拘留的处罚决定；不需要予以行政拘留但依法应当追究其他行政责任的，应当及时将案件及有关材料移送同级食品安全监督管理等部门。\n第七十九条 复检机构无正当理由拒绝承担复检任务的，由县级以上人民政府食品安全监督管理部门给予警告，无正当理由1年内2次拒绝承担复检任务的，由国务院有关部门撤销其复检机构资质并向社会公布。\n第八十条 发布未依法取得资质认定的食品检验机构出具的食品检验信息，或者利用上述检验信息对食品、食品生产经营者进行等级评定，欺骗、误导消费者的，由县级以上人民政府食品安全监督管理部门责令改正，有违法所得的，没收违法所得，并处10万元以上50万元以下罚款；拒不改正的，处50万元以上100万元以下罚款；构成违反治安管理行为的，由公安机关依法给予治安管理处罚。\n第八十一条 食品安全监督管理部门依照食品安全法、本条例对违法单位或者个人处以30万元以上罚款的，由设区的市级以上人民政府食品安全监督管理部门决定。罚款具体处罚权限由国务院食品安全监督管理部门规定。\n第八十二条 阻碍食品安全监督管理等部门工作人员依法执行职务，构成违反治安管理行为的，由公安机关依法给予治安管理处罚。\n第八十三条 县级以上人民政府食品安全监督管理等部门发现单位或者个人违反食品安全法第一百二十条第一款规定，编造、散布虚假食品安全信息，涉嫌构成违反治安管理行为的，应当将相关情况通报同级公安机关。\n第八十四条 县级以上人民政府食品安全监督管理部门及其工作人员违法向他人提供网络食品交易第三方平台提供者提供的信息的，依照食品安全法第一百四十五条的规定给予处分。\n第八十五条 违反本条例规定，构成犯罪的，依法追究刑事责任。","level":1},{"name":"第十章 附则","text":"第八十六条 本条例自2019年12月1日起施行。","level":1}]},{"id":"n0371","sections":[{"name":"","text":"对外经济贸易部特派员办事处暂行条例\n(对外经济贸易部制定 1982年7月15日国务院批转)\n在我国继续实行对外经济开放政策和有较多的部门、地方、企业参与对外经济贸易活动的情况下，为了既能正确地调动各方面的积极性，大力发展对外经济贸易，又能防止自相竞争，避免发生混乱现象，必须加强对外经济贸易的经营协调和行政管理，做到统一对外、联合对外。为此，除采取其他协调管理措施外，决定在主要口岸派驻特派员，设立特派员办事处。\n一、特派员办事处是对外经济贸易部的派出机构，其名称为“对外经济贸易部驻××特派员办事处”，受对外经济贸易部直接领导，向对外经济贸易部负责。特派员要与地方党政密切联系，汇报工作情况，取得地方党政的支持帮助，并及时向对外经济贸易部请示报告。\n二、特派员的任务\n(一)根据统一政策、统一计划、统一对外的原则，并有利于对外经济贸易发展，对进出口商品协调小组制订的进出口商品协调方案的贯彻执行进行监督和指导。对执行进出口商品协调方案中发生的问题，属于特派员所辖地区范围内的，可就地协助解决；属于全国性的问题，如市场、数量、价格、客户等大的变动，仍由总公司协调小组解决；\n(二)加强行政管理，根据对外经济贸易部的授权范围，负责审批和签发部分进出口商品的许可证；\n(三)协助专业进出口总公司(包括工贸结合的总公司，下同)对主要出口商品，逐步实行按行业以主要口岸为中心的统一经营和联合经营；\n(四)为了加强统一对外、联合对外，可视情况召集所在口岸及所辖范围内的省、市、自治区的对外经济贸易部门的联系会议，沟通情况，协调解决口岸与内地的关系。有关专业总公司和对外经济贸易部有关单位可派人参加会议；\n(五)对对外经济贸易有关的方针政策贯彻执行情况，对加强进出口管理和对外经济贸易体制改革等问题，开展调查研究，向对外经济贸易部提出建议；\n(六)办理对外经济贸易部交办的其它事项。\n三、特派员的权利\n(一)对进出口企业违反进出口商品经营分工和协调方案的业务活动有权干预和制止；\n(二)对于违反政策或国家有关法令、规章制度的交易，特派员有权制止，有权拒发许可证；\n(三)各专业总公司的进出口商品协调小组应向特派员提供业务资料(包括协调方案、会议纪要、简报、统计资料和报告等)，以便特派员对协调工作进行检查、监督和裁决；\n(四)当地省、市和有关内地省、市、自治区对外经济贸易行政部门关于管理工作的报告，应抄送特派员。特派员为了工作的需要，有权请当地和有关省、市、自治区对外经济贸易行政和企业部门提供关于协调和管理的情况和资料；\n(五)为了履行本条例规定的任务和职责，当地交通运输、港口、银行和海关、商检等有关部门，对特派员的工作要积极配合。\n四、特派员的任命、任期、组织关系和奖惩\n(一)特派员办事处设特派员1名，副特派员1名。均由对外经济贸易部提名，报请国务院任命；\n(二)特派员任期一般为两年，到期轮换，必要时可适当延长。特派员办事处工作人员也实行轮换制；\n(三)特派员办事处的政治思想工作由对外经济贸易部负责。特派员及工作人员中的党、团员，分别建立党、团组织，直属对外经济贸易部党、团委领导。有关紧急、重要的传达报告和文件阅读，请地方党委协助安排；\n(四)对特派员及其办事处工作人员的奖惩，均由对外经济贸易部负责办理。\n五、特派员办事处的人员编制、经费、生活\n(一)根据精简原则确定人员编制，干部由对外经济贸易部派出。内部机构设置要精简，力求提高办事效率；\n(二)办事处的经费开支，纳入对外经济贸易部预算；\n(三)办事处人员的日常生活，请当地人民政府有关部门协助安排。\n六、特派员及其办事处人员的工作作风\n特派员及其办事处工作人员应努力学习党的路线、方针、政策，正确执行对外经济贸易政策和各项规定，促进对外经济贸易的发展；要加强调查研究，虚心听取各方意见，实事求是，加强全局观点；大公无私，办事认真，发扬党的优良传统，全心全意为人民服务，做好承担的各项工作。\n七、本暂行条例，经国务院批准后执行。如需补充、修改，由对外经济贸易部提出，报经国务院批准后实行。","level":0}]},{"id":"n0372","sections":[{"name":"","text":"农民承担费用和劳务管理条例\n(1991年11月5日国务院第92次常务会议通过 1991年12月7日中华人民共和国国务院令第92号发布 自发布之日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了减轻农民负担，保护农民的合法权益，调动农民的生产积极性，促进农村经济持续稳定协调发展，制定本条例。\n第二条 本条例所称农民承担的费用和劳务，是指农民除缴纳税金，完成国家农产品定购任务外，依照法律、法规所承担的村(包括村民小组，下同)提留、乡(包括镇，下同)统筹费、劳务(农村义务工和劳动积累工)以及其他费用。\n向国家缴纳税金，完成国家农产品定购任务，承担前款规定的各项费用和劳务，是农民应尽的义务。除此以外要求农民无偿提供任何财力、物力和劳务的，均为非法行为，农民有权拒绝。\n第三条 国务院农业行政主管部门主管全国农民承担费用和劳务(以下简称农民负担)的监督管理工作。县级以上地方人民政府农业行政主管部门主管本行政区域内的农民负担监督管理工作。\n乡人民政府主管本乡的农民负担监督管理工作，日常工作由乡农村经济经营管理部门负责。\n第四条 各级农民负担监督管理部门负责检查有关农民负担管理的法律、法规和政策的执行情况；会同有关主管部门审核涉及农民负担的文件；协助有关机关处理涉及农民负担的案件；培训农民负担监督管理工作人员。\n第五条 国家鼓励和支持发展农村集体经济，提倡主要依靠集体经营增加的收入，兴办农村社会主义物质文明和精神文明建设事业。","level":1},{"name":"第二章 村提留、乡统筹费、劳务的标准和使用范围","text":"第六条 农民直接向集体经济组织缴纳的村提留和乡统筹费(不含乡村集体所有制企业缴纳的利润)，以乡为单位，以国家统计局批准、农业部制定的农村经济收益分配统计报表和计算方法统计的数字为依据，不得超过上一年农民人均纯收入的5%。对经济发达的地区，经省、自治区、直辖市批准，可以适当提高提取比例。\n乡统筹费的最高限额由省、自治区、直辖市确定。\n第七条 村提留包括公积金、公益金和管理费：\n(一)公积金，用于农田水利基本建设、植树造林、购置生产性固定资产和兴办集体企业。\n(二)公益金，用于五保户供养、特别困难户补助、合作医疗保健以及其他集体福利事业。\n(三)管理费，用于村干部报酬和管理开支。\n村干部报酬实行定额补助和误工补贴两种形式。具体定额补助人数、标准和误工补贴办法，由乡人民政府根据村规模、经济发展水平和实际工作需要制定，报县级人民政府农民负担监督管理部门备案。\n第八条 乡统筹费用于安排乡村两级办学、计划生育、优抚、民兵训练、修建乡村道路等民办公助事业。\n乡统筹费可以用于五保户供养。五保户供养从乡统筹费中列支的，不得在村提留中重复列支。\n第九条 乡统筹费内的乡村两级办学经费(即农村教育事业费附加)用于本乡范围内乡村两级的民办教育事业。\n乡村两级办学经费在乡统筹费内所占比例，由省、自治区、直辖市人民政府教育主管部门提出，经同级农民负担监督管理部门审核，报省、自治区、直辖市人民政府批准，并报国务院农业行政主管部门和教育主管部门备案。\n第十条 农村义务工，主要用于植树造林、防汛、公路建勤、修缮校舍等。按标准工日计算，每个农村劳动力每年承担五至十个农村义务工。\n因抢险救灾，需要增加农村义务工的，由当地人民政府统筹安排。\n第十一条 劳动积累工，主要用于农田水利基本建设和植树造林。按标准工日计算，每个农村劳动力每年承担十至二十个劳动积累工。有条件的地方，经县级以上人民政府批准，可以适当增加。劳动积累工应当主要在农闲期间使用。","level":1},{"name":"第三章 村提留、乡统筹费、劳务的提取和管理","text":"第十二条 村提留和乡统筹费主要按农民从事的产业和经济收入承担。\n承包耕地的农民按其承包的耕地面积或者劳动力向其所属的集体经济组织缴纳村提留和乡统筹费。\n经营个体工商业和私营企业的，应在税后按经营所在地规定的提取比例，缴纳村提留和乡统筹费，但不计算在本条例第六条规定的限额比例之内。\n第十三条 对收入水平在本村平均线以下的革命烈军属、伤残军人、失去劳动能力的复员退伍军人和特别困难户，经村集体经济组织成员大会或者成员代表会议讨论评定，适当减免村提留。\n第十四条 乡人民政府评定的贫困村，经村集体经济组织提出申请，乡农民负担监督管理部门审核、乡人民政府同意，报乡人民代表大会审议通过，可以适当核减乡统筹费。\n第十五条 农村义务工和劳动积累工以出劳为主，本人要求以资代劳的，须经村集体经济组织批准。\n对因病或者伤残不能承担农村义务工、劳动积累工的，经村集体经济组织成员大会或者成员代表会议讨论通过，可以减免。\n第十六条 村提留和乡统筹费，实行全年统算统收制度，由村集体经济组织和乡人民政府组织收取。\n第十七条 村提留，由村集体经济组织每年年底作出当年决算方案并提出下一年度预算方案，经村集体经济组织成员大会或者成员代表会议讨论通过，报乡人民政府备案。讨论通过的预、决算方案，应当张榜公布，接受群众监督。\n村民委员会应当对村提留的收取和使用实施监督。\n第十八条 乡统筹费，由乡人民政府商乡集体经济组织每年年底作出当年决算方案并编制下一年度预算方案，经乡人民代表大会审议通过后，连同本乡范围内的村提留预算方案，一并报县级人民政府农民负担监督管理部门备案。讨论通过后的乡统筹费预、决算方案，应当张榜公布，接受群众监督。\n第十九条 乡统筹费属于集体经济组织范围内全体农民所有，主要用于本乡民办公助事业，不得混淆和改变乡统筹费的集体资金性质和用途。\n第二十条 对村提留和乡统筹费，应当实行严格的财务管理制度。集体经济组织应当对村提留和乡统筹费的使用实行内部审计监督制度。\n第二十一条 农村义务工和劳动积累工，由乡人民政府商村集体经济组织提出用工计划，经乡人民代表大会审议通过后执行，年终由村集体经济组织张榜公布用工情况，接受群众监督。","level":1},{"name":"第四章 其他项目的监督管理","text":"第二十二条 面向农民的行政事业性收费，其项目设置、标准的制定和调整，须经省、自治区、直辖市以上人民政府财政、物价主管部门会同农民负担监督管理部门批准，重要项目须经国务院或者省、自治区、直辖市人民政府批准。\n第二十三条 向农民集资，必须在法律、法规和国务院有关政策允许的范围内进行，并遵循自愿、适度、出资者受益、资金定向使用的原则。集资项目的设置和范围的确定，须经省、自治区、直辖市以上人民政府计划主管部门会同财政主管部门、农民负担监督管理部门批准，重要项目须经国务院或者省、自治区、直辖市人民政府批准。\n第二十四条 在农村建立各种基金，须经国务院财政主管部门会同农民负担监督管理部门和有关主管部门批准，重要项目须经国务院批准。\n第二十五条 向农民发放牌照、证件和簿册，必须依照法律、法规的规定或者经省、自治区、直辖市以上人民政府批准。\n向农民发放牌照、证件和簿册，只准收取工本费。\n第二十六条 向农民发行有价证券、报刊和书籍，应当遵循自愿原则，任何单位不得摊派。\n第二十七条 组织农民参加保险，应当遵守法律、法规的规定。\n第二十八条 严禁非法对农民罚款和没收财物。\n第二十九条 国家机关工作人员在农村执行公务，所需经费不得向农民和集体经济组织摊派。\n第三十条 企业、事业单位为农民和集体经济组织提供经济、技术、劳务、信息等服务，应当遵循自愿原则。收取服务费用，应当按照国家有关规定执行。\n第三十一条 任何行政机关、事业单位在农村设置机构或者配备人员，所需经费不得向农民和集体经济组织摊派。\n第三十二条 任何单位和个人都有权举报违反本条例的行为。农民负担监督管理部门和有关主管部门接到举报后，必须及时查处或者提请同级人民政府依法处理。","level":1},{"name":"第五章 奖励与处罚","text":"第三十三条 有下列事迹之一的单位和个人，可以由人民政府给予表彰或者奖励：\n(一)严格执行本条例规定，切实减轻农民负担的；\n(二)在农民负担监督管理工作中，认真履行本条例规定职责，成绩显著的；\n(三)检举、揭发向农民乱收费、乱集资、乱罚款和各种摊派行为，有突出贡献的。\n第三十四条 违反本条例规定设置的收费、集资和基金项目，由农民负担监督管理部门或者有关部门报请同级人民政府予以撤销。\n第三十五条 违反本条例规定向农民和集体经济组织收费、集资和进行各种摊派的，由农民负担监督管理部门或者有关部门报请同级人民政府责令如数退还非法收取的款物。\n第三十六条 违反本条例和国务院有关规定增加的农村义务工和劳动积累工，经乡农民负担监督管理部门核实，由乡人民政府在下一年度用工计划中扣减，或者由用工单位按标准工日给予农民出工补贴。\n第三十七条 对违反本条例规定的单位负责人和直接责任人员，由农民负担监督管理部门提请上述人员所在单位或者有关主管机关给予行政处分。\n第三十八条 对检举、揭发、控告和抵制向农民乱收费、乱集资、乱罚款和进行各种摊派的单位和人员打击报复，属于违反《中华人民共和国行政监察条例》的，由行政监察机关依法处理；属于违反《中华人民共和国治安管理处罚条例》的，由公安机关依法处罚；构成犯罪的，由司法机关依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第三十九条 各省、自治区、直辖市可以根据本条例，结合本地的实际情况，制定实施细则。\n第四十条 本条例由国务院农业行政主管部门负责解释，并组织实施。\n第四十一条 本条例自发布之日起施行。","level":1}]},{"id":"n0373","sections":[{"name":"","text":"中华人民共和国合伙企业登记管理办法\n(1997年11月19日中华人民共和国国务院令第236号发布 根据2007年5月9日《国务院关于修改〈中华人民共和国合伙企业登记管理办法〉的决定》第一次修订 根据2014年2月19日《国务院关于废止和修改部分行政法规的决定》第二次修订 根据2019年3月2日《国务院关于修改部分行政法规的决定》第三次修订)","level":0},{"name":"第一章 总则","text":"第一条 为了确认合伙企业的经营资格，规范合伙企业登记行为，依据《中华人民共和国合伙企业法》(以下简称合伙企业法)，制定本办法。\n第二条 合伙企业的设立、变更、注销，应当依照合伙企业法和本办法的规定办理企业登记。\n申请办理合伙企业登记，申请人应当对申请材料的真实性负责。\n第三条 合伙企业经依法登记，领取合伙企业营业执照后，方可从事经营活动。\n第四条 工商行政管理部门是合伙企业登记机关(以下简称企业登记机关)。\n国务院工商行政管理部门负责全国的合伙企业登记管理工作。\n市、县工商行政管理部门负责本辖区内的合伙企业登记。\n国务院工商行政管理部门对特殊的普通合伙企业和有限合伙企业的登记管辖可以作出特别规定。\n法律、行政法规对合伙企业登记管辖另有规定的，从其规定。","level":1},{"name":"第二章 设立登记","text":"第五条 设立合伙企业，应当具备合伙企业法规定的条件。\n第六条 合伙企业的登记事项应当包括：\n(一)名称；\n(二)主要经营场所；\n(三)执行事务合伙人；\n(四)经营范围；\n(五)合伙企业类型；\n(六)合伙人姓名或者名称及住所、承担责任方式、认缴或者实际缴付的出资数额、缴付期限、出资方式和评估方式。\n合伙协议约定合伙期限的，登记事项还应当包括合伙期限。\n执行事务合伙人是法人或者其他组织的，登记事项还应当包括法人或者其他组织委派的代表(以下简称委派代表)。\n第七条 合伙企业名称中的组织形式后应当标明“普通合伙”、“特殊普通合伙”或者“有限合伙”字样，并符合国家有关企业名称登记管理的规定。\n第八条 经企业登记机关登记的合伙企业主要经营场所只能有一个，并且应当在其企业登记机关登记管辖区域内。\n第九条 合伙协议未约定或者全体合伙人未决定委托执行事务合伙人的，全体合伙人均为执行事务合伙人。\n有限合伙人不得成为执行事务合伙人。\n第十条 合伙企业类型包括普通合伙企业(含特殊的普通合伙企业)和有限合伙企业。\n第十一条 设立合伙企业，应当由全体合伙人指定的代表或者共同委托的代理人向企业登记机关申请设立登记。\n申请设立合伙企业，应当向企业登记机关提交下列文件：\n(一)全体合伙人签署的设立登记申请书；\n(二)全体合伙人的身份证明；\n(三)全体合伙人指定代表或者共同委托代理人的委托书；\n(四)合伙协议；\n(五)全体合伙人对各合伙人认缴或者实际缴付出资的确认书；\n(六)主要经营场所证明；\n(七)国务院工商行政管理部门规定提交的其他文件。\n法律、行政法规或者国务院规定设立合伙企业须经批准的，还应当提交有关批准文件。\n第十二条 合伙企业的经营范围中有属于法律、行政法规或者国务院规定在登记前须经批准的项目的，应当向企业登记机关提交批准文件。\n第十三条 全体合伙人决定委托执行事务合伙人的，应当向企业登记机关提交全体合伙人的委托书。执行事务合伙人是法人或者其他组织的，还应当提交其委派代表的委托书和身份证明。\n第十四条 以实物、知识产权、土地使用权或者其他财产权利出资，由全体合伙人协商作价的，应当向企业登记机关提交全体合伙人签署的协商作价确认书；由全体合伙人委托法定评估机构评估作价的，应当向企业登记机关提交法定评估机构出具的评估作价证明。\n第十五条 法律、行政法规规定设立特殊的普通合伙企业，需要提交合伙人的职业资格证明的，应当向企业登记机关提交有关证明。\n第十六条 申请人提交的登记申请材料齐全、符合法定形式，企业登记机关能够当场登记的，应予当场登记，发给合伙企业营业执照。\n除前款规定情形外，企业登记机关应当自受理申请之日起20日内，作出是否登记的决定。予以登记的，发给合伙企业营业执照；不予登记的，应当给予书面答复，并说明理由。\n第十七条 合伙企业营业执照的签发之日，为合伙企业的成立日期。","level":1},{"name":"第三章 变更登记","text":"第十八条 合伙企业登记事项发生变更的，执行合伙事务的合伙人应当自作出变更决定或者发生变更事由之日起15日内，向原企业登记机关申请变更登记。\n第十九条 合伙企业申请变更登记，应当向原企业登记机关提交下列文件：\n(一)执行事务合伙人或者委派代表签署的变更登记申请书；\n(二)全体合伙人签署的变更决定书，或者合伙协议约定的人员签署的变更决定书；\n(三)国务院工商行政管理部门规定提交的其他文件。\n法律、行政法规或者国务院规定变更事项须经批准的，还应当提交有关批准文件。\n第二十条 申请人提交的申请材料齐全、符合法定形式，企业登记机关能够当场变更登记的，应予当场变更登记。\n除前款规定情形外，企业登记机关应当自受理申请之日起20日内，作出是否变更登记的决定。予以变更登记的，应当进行变更登记；不予变更登记的，应当给予书面答复，并说明理由。\n合伙企业变更登记事项涉及营业执照变更的，企业登记机关应当换发营业执照。","level":1},{"name":"第四章 注销登记","text":"第二十一条 合伙企业解散，依法由清算人进行清算。清算人应当自被确定之日起10日内，将清算人成员名单向企业登记机关备案。\n第二十二条 合伙企业依照合伙企业法的规定解散的，清算人应当自清算结束之日起15日内，向原企业登记机关办理注销登记。\n第二十三条 合伙企业办理注销登记，应当提交下列文件：\n(一)清算人签署的注销登记申请书；\n(二)人民法院的破产裁定，合伙企业依照合伙企业法作出的决定，行政机关责令关闭、合伙企业依法被吊销营业执照或者被撤销的文件；\n(三)全体合伙人签名、盖章的清算报告；\n(四)国务院工商行政管理部门规定提交的其他文件。\n合伙企业办理注销登记时，应当缴回营业执照。\n第二十四条 经企业登记机关注销登记，合伙企业终止。","level":1},{"name":"第五章 分支机构登记","text":"第二十五条 合伙企业设立分支机构，应当向分支机构所在地的企业登记机关申请设立登记。\n第二十六条 分支机构的登记事项包括：分支机构的名称、经营场所、经营范围、分支机构负责人的姓名及住所。\n分支机构的经营范围不得超出合伙企业的经营范围。\n合伙企业有合伙期限的，分支机构的登记事项还应当包括经营期限。分支机构的经营期限不得超过合伙企业的合伙期限。\n第二十七条 合伙企业设立分支机构，应当向分支机构所在地的企业登记机关提交下列文件：\n(一)分支机构设立登记申请书；\n(二)全体合伙人签署的设立分支机构的决定书；\n(三)加盖合伙企业印章的合伙企业营业执照复印件；\n(四)全体合伙人委派执行分支机构事务负责人的委托书及其身份证明；\n(五)经营场所证明；\n(六)国务院工商行政管理部门规定提交的其他文件。\n法律、行政法规或者国务院规定设立合伙企业分支机构须经批准的，还应当提交有关批准文件。\n第二十八条 分支机构的经营范围中有属于法律、行政法规或者国务院规定在登记前须经批准的项目的，应当向分支机构所在地的企业登记机关提交批准文件。\n第二十九条 申请人提交的登记申请材料齐全、符合法定形式，企业登记机关能够当场登记的，应予当场登记，发给营业执照。\n除前款规定情形外，企业登记机关应当自受理申请之日起20日内，作出是否登记的决定。予以登记的，发给营业执照；不予登记的，应当给予书面答复，并说明理由。\n第三十条 合伙企业申请分支机构变更登记或者注销登记，比照本办法关于合伙企业变更登记、注销登记的规定办理。","level":1},{"name":"第六章 公示和证照管理","text":"第三十一条 企业登记机关应当将合伙企业登记、备案信息通过企业信用信息公示系统向社会公示。\n第三十二条 合伙企业应当于每年1月1日至6月30日，通过企业信用信息公示系统向企业登记机关报送上一年度年度报告，并向社会公示。\n年度报告公示的内容以及监督检查办法由国务院制定。\n第三十三条 合伙企业的营业执照分为正本和副本，正本和副本具有同等法律效力。\n国家推行电子营业执照。电子营业执照与纸质营业执照具有同等法律效力。\n合伙企业根据业务需要，可以向企业登记机关申请核发若干营业执照副本。\n合伙企业应当将营业执照正本置放在经营场所的醒目位置。\n第三十四条 任何单位和个人不得伪造、涂改、出售、出租、出借或者以其他方式转让营业执照。\n合伙企业营业执照遗失或者毁损的，应当在国家企业信用信息公示系统声明作废，并向企业登记机关申请补领或者更换。\n第三十五条 合伙企业及其分支机构营业执照的正本和副本样式，由国务院工商行政管理部门制定。\n第三十六条 企业登记机关吊销合伙企业营业执照的，应当发布公告，并不得收取任何费用。","level":1},{"name":"第七章 法律责任","text":"第三十七条 未领取营业执照，而以合伙企业或者合伙企业分支机构名义从事合伙业务的，由企业登记机关责令停止，处5000元以上5万元以下的罚款。\n第三十八条 提交虚假文件或者采取其他欺骗手段，取得合伙企业登记的，由企业登记机关责令改正，处5000元以上5万元以下的罚款；情节严重的，撤销企业登记，并处5万元以上20万元以下的罚款。\n第三十九条 合伙企业登记事项发生变更，未依照本办法规定办理变更登记的，由企业登记机关责令限期登记；逾期不登记的，处2000元以上2万元以下的罚款。\n第四十条 合伙企业未依照本办法规定在其名称中标明“普通合伙”、“特殊普通合伙”或者“有限合伙”字样的，由企业登记机关责令限期改正，处2000元以上1万元以下的罚款。\n第四十一条 合伙企业未依照本办法规定办理清算人成员名单备案的，由企业登记机关责令限期办理；逾期未办理的，处2000元以下的罚款。\n第四十二条 合伙企业的清算人未向企业登记机关报送清算报告，或者报送的清算报告隐瞒重要事实，或者有重大遗漏的，由企业登记机关责令改正。由此产生的费用和损失，由清算人承担和赔偿。\n第四十三条 合伙企业未将其营业执照正本置放在经营场所醒目位置的，由企业登记机关责令改正；拒不改正的，处1000元以上5000元以下的罚款。\n第四十四条 合伙企业涂改、出售、出租、出借或者以其他方式转让营业执照的，由企业登记机关责令改正，处2000元以上1万元以下的罚款；情节严重的，吊销营业执照。\n第四十五条 企业登记机关的工作人员滥用职权、徇私舞弊、收受贿赂、侵害合伙企业合法权益的，依法给予处分。\n第四十六条 违反本办法规定，构成犯罪的，依法追究刑事责任。","level":1},{"name":"第八章 附则","text":"第四十七条 合伙企业登记收费项目按照国务院财政部门、价格主管部门的有关规定执行，合伙企业登记收费标准按照国务院价格主管部门、财政部门的有关规定执行。\n第四十八条 本办法自发布之日起施行。","level":1}]},{"id":"n0374","sections":[{"name":"","text":"规划环境影响评价条例\n(2009年8月12日国务院第76次常务会议通过 2009年8月17日中华人民共和国国务院令第559号公布 自2009年10月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了加强对规划的环境影响评价工作，提高规划的科学性，从源头预防环境污染和生态破坏，促进经济、社会和环境的全面协调可持续发展，根据《中华人民共和国环境影响评价法》，制定本条例。\n第二条 国务院有关部门、设区的市级以上地方人民政府及其有关部门，对其组织编制的土地利用的有关规划和区域、流域、海域的建设、开发利用规划(以下称综合性规划)，以及工业、农业、畜牧业、林业、能源、水利、交通、城市建设、旅游、自然资源开发的有关专项规划(以下称专项规划)，应当进行环境影响评价。\n依照本条第一款规定应当进行环境影响评价的规划的具体范围，由国务院环境保护主管部门会同国务院有关部门拟订，报国务院批准后执行。\n第三条 对规划进行环境影响评价，应当遵循客观、公开、公正的原则。\n第四条 国家建立规划环境影响评价信息共享制度。\n县级以上人民政府及其有关部门应当对规划环境影响评价所需资料实行信息共享。\n第五条 规划环境影响评价所需的费用应当按照预算管理的规定纳入财政预算，严格支出管理，接受审计监督。\n第六条 任何单位和个人对违反本条例规定的行为或者对规划实施过程中产生的重大不良环境影响，有权向规划审批机关、规划编制机关或者环境保护主管部门举报。有关部门接到举报后，应当依法调查处理。","level":1},{"name":"第二章 评价","text":"第七条 规划编制机关应当在规划编制过程中对规划组织进行环境影响评价。\n第八条 对规划进行环境影响评价，应当分析、预测和评估以下内容：\n(一)规划实施可能对相关区域、流域、海域生态系统产生的整体影响；\n(二)规划实施可能对环境和人群健康产生的长远影响；\n(三)规划实施的经济效益、社会效益与环境效益之间以及当前利益与长远利益之间的关系。\n第九条 对规划进行环境影响评价，应当遵守有关环境保护标准以及环境影响评价技术导则和技术规范。\n规划环境影响评价技术导则由国务院环境保护主管部门会同国务院有关部门制定；规划环境影响评价技术规范由国务院有关部门根据规划环境影响评价技术导则制定，并抄送国务院环境保护主管部门备案。\n第十条 编制综合性规划，应当根据规划实施后可能对环境造成的影响，编写环境影响篇章或者说明。\n编制专项规划，应当在规划草案报送审批前编制环境影响报告书。编制专项规划中的指导性规划，应当依照本条第一款规定编写环境影响篇章或者说明。\n本条第二款所称指导性规划是指以发展战略为主要内容的专项规划。\n第十一条 环境影响篇章或者说明应当包括下列内容：\n(一)规划实施对环境可能造成影响的分析、预测和评估。主要包括资源环境承载能力分析、不良环境影响的分析和预测以及与相关规划的环境协调性分析。\n(二)预防或者减轻不良环境影响的对策和措施。主要包括预防或者减轻不良环境影响的政策、管理或者技术等措施。\n环境影响报告书除包括上述内容外，还应当包括环境影响评价结论。主要包括规划草案的环境合理性和可行性，预防或者减轻不良环境影响的对策和措施的合理性和有效性，以及规划草案的调整建议。\n第十二条 环境影响篇章或者说明、环境影响报告书(以下称环境影响评价文件)，由规划编制机关编制或者组织规划环境影响评价技术机构编制。规划编制机关应当对环境影响评价文件的质量负责。\n第十三条 规划编制机关对可能造成不良环境影响并直接涉及公众环境权益的专项规划，应当在规划草案报送审批前，采取调查问卷、座谈会、论证会、听证会等形式，公开征求有关单位、专家和公众对环境影响报告书的意见。但是，依法需要保密的除外。\n有关单位、专家和公众的意见与环境影响评价结论有重大分歧的，规划编制机关应当采取论证会、听证会等形式进一步论证。\n规划编制机关应当在报送审查的环境影响报告书中附具对公众意见采纳与不采纳情况及其理由的说明。\n第十四条 对已经批准的规划在实施范围、适用期限、规模、结构和布局等方面进行重大调整或者修订的，规划编制机关应当依照本条例的规定重新或者补充进行环境影响评价。","level":1},{"name":"第三章 审查","text":"第十五条 规划编制机关在报送审批综合性规划草案和专项规划中的指导性规划草案时，应当将环境影响篇章或者说明作为规划草案的组成部分一并报送规划审批机关。未编写环境影响篇章或者说明的，规划审批机关应当要求其补充；未补充的，规划审批机关不予审批。\n第十六条 规划编制机关在报送审批专项规划草案时，应当将环境影响报告书一并附送规划审批机关审查；未附送环境影响报告书的，规划审批机关应当要求其补充；未补充的，规划审批机关不予审批。\n第十七条 设区的市级以上人民政府审批的专项规划，在审批前由其环境保护主管部门召集有关部门代表和专家组成审查小组，对环境影响报告书进行审查。审查小组应当提交书面审查意见。\n省级以上人民政府有关部门审批的专项规划，其环境影响报告书的审查办法，由国务院环境保护主管部门会同国务院有关部门制定。\n第十八条 审查小组的专家应当从依法设立的专家库内相关专业的专家名单中随机抽取。但是，参与环境影响报告书编制的专家，不得作为该环境影响报告书审查小组的成员。\n审查小组中专家人数不得少于审查小组总人数的二分之一；少于二分之一的，审查小组的审查意见无效。\n第十九条 审查小组的成员应当客观、公正、独立地对环境影响报告书提出书面审查意见，规划审批机关、规划编制机关、审查小组的召集部门不得干预。\n审查意见应当包括下列内容：\n(一)基础资料、数据的真实性；\n(二)评价方法的适当性；\n(三)环境影响分析、预测和评估的可靠性；\n(四)预防或者减轻不良环境影响的对策和措施的合理性和有效性；\n(五)公众意见采纳与不采纳情况及其理由的说明的合理性；\n(六)环境影响评价结论的科学性。\n审查意见应当经审查小组四分之三以上成员签字同意。审查小组成员有不同意见的，应当如实记录和反映。\n第二十条 有下列情形之一的，审查小组应当提出对环境影响报告书进行修改并重新审查的意见：\n(一)基础资料、数据失实的；\n(二)评价方法选择不当的；\n(三)对不良环境影响的分析、预测和评估不准确、不深入，需要进一步论证的；\n(四)预防或者减轻不良环境影响的对策和措施存在严重缺陷的；\n(五)环境影响评价结论不明确、不合理或者错误的；\n(六)未附具对公众意见采纳与不采纳情况及其理由的说明，或者不采纳公众意见的理由明显不合理的；\n(七)内容存在其他重大缺陷或者遗漏的。\n第二十一条 有下列情形之一的，审查小组应当提出不予通过环境影响报告书的意见：\n(一)依据现有知识水平和技术条件，对规划实施可能产生的不良环境影响的程度或者范围不能作出科学判断的；\n(二)规划实施可能造成重大不良环境影响，并且无法提出切实可行的预防或者减轻对策和措施的。\n第二十二条 规划审批机关在审批专项规划草案时，应当将环境影响报告书结论以及审查意见作为决策的重要依据。\n规划审批机关对环境影响报告书结论以及审查意见不予采纳的，应当逐项就不予采纳的理由作出书面说明，并存档备查。有关单位、专家和公众可以申请查阅；但是，依法需要保密的除外。\n第二十三条 已经进行环境影响评价的规划包含具体建设项目的，规划的环境影响评价结论应当作为建设项目环境影响评价的重要依据，建设项目环境影响评价的内容可以根据规划环境影响评价的分析论证情况予以简化。","level":1},{"name":"第四章 跟踪评价","text":"第二十四条 对环境有重大影响的规划实施后，规划编制机关应当及时组织规划环境影响的跟踪评价，将评价结果报告规划审批机关，并通报环境保护等有关部门。\n第二十五条 规划环境影响的跟踪评价应当包括下列内容：\n(一)规划实施后实际产生的环境影响与环境影响评价文件预测可能产生的环境影响之间的比较分析和评估；\n(二)规划实施中所采取的预防或者减轻不良环境影响的对策和措施有效性的分析和评估；\n(三)公众对规划实施所产生的环境影响的意见；\n(四)跟踪评价的结论。\n第二十六条 规划编制机关对规划环境影响进行跟踪评价，应当采取调查问卷、现场走访、座谈会等形式征求有关单位、专家和公众的意见。\n第二十七条 规划实施过程中产生重大不良环境影响的，规划编制机关应当及时提出改进措施，向规划审批机关报告，并通报环境保护等有关部门。\n第二十八条 环境保护主管部门发现规划实施过程中产生重大不良环境影响的，应当及时进行核查。经核查属实的，向规划审批机关提出采取改进措施或者修订规划的建议。\n第二十九条 规划审批机关在接到规划编制机关的报告或者环境保护主管部门的建议后，应当及时组织论证，并根据论证结果采取改进措施或者对规划进行修订。\n第三十条 规划实施区域的重点污染物排放总量超过国家或者地方规定的总量控制指标的，应当暂停审批该规划实施区域内新增该重点污染物排放总量的建设项目的环境影响评价文件。","level":1},{"name":"第五章 法律责任","text":"第三十一条 规划编制机关在组织环境影响评价时弄虚作假或者有失职行为，造成环境影响评价严重失实的，对直接负责的主管人员和其他直接责任人员，依法给予处分。\n第三十二条 规划审批机关有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予处分：\n(一)对依法应当编写而未编写环境影响篇章或者说明的综合性规划草案和专项规划中的指导性规划草案，予以批准的；\n(二)对依法应当附送而未附送环境影响报告书的专项规划草案，或者对环境影响报告书未经审查小组审查的专项规划草案，予以批准的。\n第三十三条 审查小组的召集部门在组织环境影响报告书审查时弄虚作假或者滥用职权，造成环境影响评价严重失实的，对直接负责的主管人员和其他直接责任人员，依法给予处分。\n审查小组的专家在环境影响报告书审查中弄虚作假或者有失职行为，造成环境影响评价严重失实的，由设立专家库的环境保护主管部门取消其入选专家库的资格并予以公告；审查小组的部门代表有上述行为的，依法给予处分。\n第三十四条 规划环境影响评价技术机构弄虚作假或者有失职行为，造成环境影响评价文件严重失实的，由国务院环境保护主管部门予以通报，处所收费用1倍以上3倍以下的罚款；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第三十五条 省、自治区、直辖市人民政府可以根据本地的实际情况，要求本行政区域内的县级人民政府对其组织编制的规划进行环境影响评价。具体办法由省、自治区、直辖市参照《中华人民共和国环境影响评价法》和本条例的规定制定。\n第三十六条 本条例自2009年10月1日起施行。","level":1}]},{"id":"n0375","sections":[{"name":"","text":"中国公民往来台湾地区管理办法\n(1991年12月17日中华人民共和国国务院令第93号发布 根据2015年6月14日《国务院关于修改〈中国公民往来台湾地区管理办法〉的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为保障台湾海峡两岸人员往来，促进各方交流，维护社会秩序，制定本办法。\n第二条 居住在大陆的中国公民(以下简称大陆居民)往来台湾地区(以下简称台湾)以及居住在台湾地区的中国公民(以下简称台湾居民)来往大陆，适用本办法。\n本办法未规定的事项，其他有关法律、法规有规定的，适用其他法律、法规。\n第三条 大陆居民前往台湾，凭公安机关出入境管理部门签发的旅行证件，从开放的或者指定的出入境口岸通行。\n第四条 台湾居民来大陆，凭国家主管机关签发的旅行证件，从开放的或者指定的入出境口岸通行。\n第五条 中国公民往来台湾与大陆之间，不得有危害国家安全、荣誉和利益的行为。","level":1},{"name":"第二章 大陆居民前往台湾","text":"第六条 大陆居民前往台湾定居、探亲、访友、旅游、接受和处理财产、处理婚丧事宜或者参加经济、科技、文化、教育、体育、学术等活动，须向户口所在地的市、县公安局提出申请。\n第七条 大陆居民申请前往台湾，须履行下列手续：\n(一)交验身份、户口证明；\n(二)填写前往台湾申请表；\n(三)在职、在学人员须提交所在单位对申请人前往台湾的意见；非在职、在学人员须提交户口所在地公安派出所对申请人前往台湾的意见；\n(四)提交与申请事由相应的证明。\n第八条 本办法第七条第四项所称的证明是指：\n(一)前往定居，须提交确能在台湾定居的证明；\n(二)探亲、访友，须提交台湾亲友关系的证明；\n(三)旅游，须提交旅行所需费用的证明；\n(四)接受、处理财产，须提交经过公证的对该项财产有合法权利的有关证明；\n(五)处理婚姻事务，须提交经过公证的有关婚姻状况的证明；\n(六)处理亲友丧事，须提交有关的函件或者通知；\n(七)参加经济、科技、文化、教育、体育、学术等活动，须提交台湾相应机构、团体、个人邀请或者同意参加该项活动的证明；\n(八)主管机关认为需要提交的其他证明。\n第九条 公安机关受理大陆居民前往台湾的申请，应当在30日内，地处偏僻、交通不便的应当在60日内，作出批准或者不予批准的决定，通知申请人。紧急的申请，应当随时办理。\n第十条 经批准前往台湾的大陆居民，由公安机关签发或者签注旅行证件。\n第十一条 经批准前往台湾的大陆居民，应当在所持旅行证件签注的有效期内前往，除定居的以外，应当按期返回。\n大陆居民前往台湾后，因病或者其他特殊情况，旅行证件到期不能按期返回的，可以向原发证的公安机关或者公安部出入境管理局派出的或者委托的有关机构申请办理延期手续；有特殊原因的也可以在入境口岸的公安机关申请办理入境手续。\n第十二条 申请前往台湾的大陆居民有下列情形之一的，不予批准：\n(一)刑事案件的被告人或者犯罪嫌疑人；\n(二)人民法院通知有未了结诉讼事宜不能离境的；\n(三)被判处刑罚尚未执行完毕的；\n(四)正在被劳动教养的；\n(五)国务院有关主管部门认为出境后将对国家安全造成危害或者对国家利益造成重大损失的；\n(六)有编造情况、提供假证明等欺骗行为的。","level":1},{"name":"第三章 台湾居民来大陆","text":"第十三条 台湾居民要求来大陆的，向下列有关机关申请办理旅行证件：\n(一)从台湾地区要求直接来大陆的，向公安部出入境管理局派出的或者委托的有关机构申请；有特殊事由的，也可以向指定口岸的公安机关申请；\n(二)到香港、澳门地区后要求来大陆的，向公安部出入境管理局派出的机构或者委托的在香港、澳门地区的有关机构申请；\n(三)经由外国来大陆的，依据《中华人民共和国护照法》，向中华人民共和国驻外国的外交代表机关、领事机关或者外交部授权的其他驻外机关申请。\n第十四条 台湾居民申请来大陆，须履行下列手续：\n(一)交验表明在台湾居住的有效身份证明和出境入境证件；\n(二)填写申请表；\n(三)提交符合规定的照片。\n国家主管机关可以根据具体情况要求台湾居民提交其他申请材料。\n第十五条 对批准来大陆的台湾居民，由国家主管机关签发旅行证件。\n第十六条 台湾居民来大陆，应当按照户口管理规定，办理暂住登记。在宾馆、饭店、招待所、旅店、学校等企业、事业单位或者机关、团体和其他机构内住宿的，应当填写临时住宿登记表；住在亲友家的，由本人或者亲友在24小时(农村72小时)内到当地公安派出所或者户籍办公室办理暂住登记手续。\n第十七条 台湾居民要求来大陆定居的，应当在入境前向公安部出入境管理局派出的或者委托的有关机构提出申请，或者经由大陆亲属向拟定居地的市、县公安局提出申请。批准定居的，公安机关发给定居证明。\n第十八条 台湾居民来大陆后，应当在所持旅行证件有效期之内按期离境。所持证件有效期即将届满需要继续居留的，应当向市、县公安局申请换发。\n第十九条 申请来大陆的台湾居民有下列情形之一的，不予批准：\n(一)被认为有犯罪行为的；\n(二)被认为来大陆后可能进行危害国家安全、利益等活动的；\n(三)不符合申请条件或者有编造情况、提供假证明等欺骗行为的；\n(四)精神疾病或者严重传染病患者；\n(五)法律、行政法规规定不予批准的其他情形。\n治病或者其他特殊原因可以批准入境的除外。","level":1},{"name":"第四章 出境入境检查","text":"第二十条 大陆居民往来台湾，台湾居民来往大陆，须向开放的或者指定的出入境口岸边防检查站出示证件，填交出境、入境登记卡，接受查验。\n第二十一条 有下列情形之一的，边防检查站有权阻止出境、入境：\n(一)未持有旅行证件的；\n(二)持用伪造、涂改等无效的旅行证件的；\n(三)拒绝交验旅行证件的；\n(四)本办法第十二条、第十九条规定不予批准出境、入境的。","level":1},{"name":"第五章 证件管理","text":"第二十二条 大陆居民往来台湾的旅行证件系指大陆居民往来台湾通行证和其他有效旅行证件。\n第二十三条 台湾居民来往大陆的旅行证件系指台湾居民来往大陆通行证和其他有效旅行证件。\n第二十四条 大陆居民往来台湾通行证有效期为10年；台湾居民来往大陆通行证分为5年有效和3个月一次有效两种。\n第二十五条 大陆居民往来台湾通行证实行逐次签注。签注分一次往返有效和多次往返有效。\n第二十六条 大陆居民遗失旅行证件，应当向原发证的公安机关报失；经调查属实的，可补发给相应的旅行证件。\n第二十七条 台湾居民在大陆遗失旅行证件，应当向当地的市、县公安机关报失；经调查属实的，可以允许重新申请领取相应的旅行证件，或者发给一次有效的出境通行证件。\n第二十八条 大陆居民前往台湾和台湾居民来大陆旅行证件的持有人，有本办法第十二条、第十九条规定情形之一的，其证件应当予以吊销或者宣布作废。\n第二十九条 审批签发旅行证件的机关，对已发出的旅行证件有权吊销或者宣布作废。公安部在必要时，可以变更签注、吊销旅行证件或者宣布作废。","level":1},{"name":"第六章 处罚","text":"第三十条 持用伪造、涂改等无效的旅行证件或者冒用他人的旅行证件出境、入境的，除依照《中华人民共和国公民出境入境管理法实施细则》第二十三条的规定处罚外，可以单处或者并处100元以上、500元以下的罚款。\n第三十一条 伪造、涂改、转让、倒卖旅行证件的，除依照《中华人民共和国公民出境入境管理法实施细则》第二十四条的规定处罚外，可以单处或者并处500元以上、3000元以下的罚款。\n第三十二条 编造情况，提供假证明，或者以行贿等手段获取旅行证件的，除依照《中华人民共和国公民出境入境管理法实施细则》第二十五条的规定处罚外，可以单处或者并处100元以上、500元以下的罚款。\n有前款情形的，在处罚执行完毕6个月以内不受理其出境、入境申请。\n第三十三条 机关、团体、企业、事业单位编造情况、出具假证明为申请人获取旅行证件的，暂停其出证权的行使；情节严重的，取消其出证资格；对直接责任人员，除依照《中华人民共和国公民出境入境管理法实施细则》第二十五条的规定处罚外，可以单处或者并处500元以上、1000元以下的罚款。\n第三十四条 违反本办法第十六条的规定，不办理暂住登记的，处以警告或者100元以上、500元以下的罚款。\n第三十五条 违反本办法第十八条的规定，逾期非法居留的，处以警告，可以单处或者并处每逾期1日100元的罚款。\n第三十六条 被处罚人对公安机关处罚不服的，可以在接到处罚通知之日起15日内，向上一级公安机关申请复议，由上一级公安机关作出最后的裁决；也可以直接向人民法院提起诉讼。\n第三十七条 来大陆的台湾居民违反本办法的规定或者有其他违法犯罪行为的，除依照本办法和其他有关法律、法规的规定处罚外，公安机关可以缩短其停留期限，限期离境，或者遣送出境。\n有本办法第十九条规定不予批准情形之一的，应当立即遣送出境。\n第三十八条 执行本办法的国家工作人员，利用职权索取、收受贿赂或者有其他违法失职行为，情节轻微的，由主管部门予以行政处分；情节严重，构成犯罪的，依照《中华人民共和国刑法》的有关规定追究刑事责任。\n第三十九条 对违反本办法所得的财物，应当予以追缴或者责令退赔；用于犯罪的本人财物应当没收。\n罚款及没收的财物上缴国库。","level":1},{"name":"第七章 附则","text":"第四十条 本办法由公安部负责解释。\n第四十一条 本办法自1992年5月1日起施行。","level":1}]},{"id":"n0376","sections":[{"name":"","text":"计算机信息网络国际联网安全保护管理办法\n(1997年12月11日国务院批准 1997年12月16日公安部令第33号发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强对计算机信息网络国际联网的安全保护，维护公共秩序和社会稳定，根据《中华人民共和国计算机信息系统安全保护条例》、《中华人民共和国计算机信息网络国际联网管理暂行规定》和其他法律、行政法规的规定，制定本办法。\n第二条 中华人民共和国境内的计算机信息网络国际联网安全保护管理，适用本办法。\n第三条 公安部计算机管理监察机构负责计算机信息网络国际联网的安全保护管理工作。\n公安机关计算机管理监察机构应当保护计算机信息网络国际联网的公共安全，维护从事国际联网业务的单位和个人的合法权益和公众利益。\n第四条 任何单位和个人不得利用国际联网危害国家安全、泄露国家秘密，不得侵犯国家的、社会的、集体的利益和公民的合法权益，不得从事违法犯罪活动。\n第五条 任何单位和个人不得利用国际联网制作、复制、查阅和传播下列信息：\n(一)煽动抗拒、破坏宪法和法律、行政法规实施的；\n(二)煽动颠覆国家政权，推翻社会主义制度的；\n(三)煽动分裂国家、破坏国家统一的；\n(四)煽动民族仇恨、民族歧视，破坏民族团结的；\n(五)捏造或者歪曲事实，散布谣言，扰乱社会秩序的；\n(六)宣扬封建迷信、淫秽、色情、赌博、暴力、凶杀、恐怖，教唆犯罪的；\n(七)公然侮辱他人或者捏造事实诽谤他人的；\n(八)损害国家机关信誉的；\n(九)其他违反宪法和法律、行政法规的。\n第六条 任何单位和个人不得从事下列危害计算机信息网络安全的活动：\n(一)未经允许，进入计算机信息网络或者使用计算机信息网络资源的；\n(二)未经允许，对计算机信息网络功能进行删除、修改或者增加的；\n(三)未经允许，对计算机信息网络中存储、处理或者传输的数据和应用程序进行删除、修改或者增加的；\n(四)故意制作、传播计算机病毒等破坏性程序的；\n(五)其他危害计算机信息网络安全的。\n第七条 用户的通信自由和通信秘密受法律保护。任何单位和个人不得违反法律规定，利用国际联网侵犯用户的通信自由和通信秘密。","level":1},{"name":"第二章 安全保护责任","text":"第八条 从事国际联网业务的单位和个人应当接受公安机关的安全监督、检查和指导，如实向公安机关提供有关安全保护的信息、资料及数据文件，协助公安机关查处通过国际联网的计算机信息网络的违法犯罪行为。\n第九条 国际出入口信道提供单位、互联单位的主管部门或者主管单位，应当依照法律和国家有关规定负责国际出入口信道、所属互联网络的安全保护管理工作。\n第十条 互联单位、接入单位及使用计算机信息网络国际联网的法人和其他组织应当履行下列安全保护职责：\n(一)负责本网络的安全保护管理工作，建立健全安全保护管理制度；\n(二)落实安全保护技术措施，保障本网络的运行安全和信息安全；\n(三)负责对本网络用户的安全教育和培训；\n(四)对委托发布信息的单位和个人进行登记，并对所提供的信息内容按照本办法第五条进行审核；\n(五)建立计算机信息网络电子公告系统的用户登记和信息管理制度；\n(六)发现有本办法第四条、第五条、第六条、第七条所列情形之一的，应当保留有关原始记录，并在24小时内向当地公安机关报告；\n(七)按照国家有关规定，删除本网络中含有本办法第五条内容的地址、目录或者关闭服务器。\n第十一条 用户在接入单位办理入网手续时，应当填写用户备案表。备案表由公安部监制。\n第十二条 互联单位、接入单位、使用计算机信息网络国际联网的法人和其他组织(包括跨省、自治区、直辖市联网的单位和所属的分支机构)，应当自网络正式联通之日起30日内，到所在地的省、自治区、直辖市人民政府公安机关指定的受理机关办理备案手续。\n前款所列单位应当负责将接入本网络的接入单位和用户情况报当地公安机关备案，并及时报告本网络中接入单位和用户的变更情况。\n第十三条 使用公用账号的注册者应当加强对公用账号的管理，建立账号使用登记制度。用户账号不得转借、转让。\n第十四条 涉及国家事务、经济建设、国防建设、尖端科学技术等重要领域的单位办理备案手续时，应当出具其行政主管部门的审批证明。\n前款所列单位的计算机信息网络与国际联网，应当采取相应的安全保护措施。","level":1},{"name":"第三章 安全监督","text":"第十五条 省、自治区、直辖市公安厅(局)，地(市)、县(市)公安局，应当有相应机构负责国际联网的安全保护管理工作。\n第十六条 公安机关计算机管理监察机构应当掌握互联单位、接入单位和用户的备案情况，建立备案档案，进行备案统计，并按照国家有关规定逐级上报。\n第十七条 公安机关计算机管理监察机构应当督促互联单位、接入单位及有关用户建立健全安全保护管理制度。监督、检查网络安全保护管理以及技术措施的落实情况。\n公安机关计算机管理监察机构在组织安全检查时，有关单位应当派人参加。公安机关计算机管理监察机构对安全检查发现的问题，应当提出改进意见，作出详细记录，存档备查。\n第十八条 公安机关计算机管理监察机构发现含有本办法第五条所列内容的地址、目录或者服务器时，应当通知有关单位关闭或者删除。\n第十九条 公安机关计算机管理监察机构应当负责追踪和查处通过计算机信息网络的违法行为和针对计算机信息网络的犯罪案件，对违反本办法第四条、第七条规定的违法犯罪行为，应当按照国家有关规定移送有关部门或者司法机关处理。","level":1},{"name":"第四章 法律责任","text":"第二十条 违反法律、行政法规，有本办法第五条、第六条所列行为之一的，由公安机关给予警告，有违法所得的，没收违法所得，对个人可以并处5000元以下的罚款，对单位可以并处1.5万元以下的罚款；情节严重的，并可以给予6个月以内停止联网、停机整顿的处罚，必要时可以建议原发证、审批机构吊销经营许可证或者取消联网资格；构成违反治安管理行为的，依照治安管理处罚法的规定处罚；构成犯罪的，依法追究刑事责任。\n第二十一条 有下列行为之一的，由公安机关责令限期改正，给予警告，有违法所得的，没收违法所得；在规定的限期内未改正的，对单位的主管负责人员和其他直接责任人员可以并处5000元以下的罚款，对单位可以并处1.5万元以下的罚款；情节严重的，并可以给予6个月以内的停止联网、停机整顿的处罚，必要时可以建议原发证、审批机构吊销经营许可证或者取消联网资格。\n(一)未建立安全保护管理制度的；\n(二)未采取安全技术保护措施的；\n(三)未对网络用户进行安全教育和培训的；\n(四)未提供安全保护管理所需信息、资料及数据文件，或者所提供内容不真实的；\n(五)对委托其发布的信息内容未进行审核或者对委托单位和个人未进行登记的；\n(六)未建立电子公告系统的用户登记和信息管理制度的；\n(七)未按照国家有关规定，删除网络地址、目录或者关闭服务器的；\n(八)未建立公用账号使用登记制度的；\n(九)转借、转让用户账号的。\n第二十二条 违反本办法第四条、第七条规定的，依照有关法律、法规予以处罚。\n第二十三条 违反本办法第十一条、第十二条规定，不履行备案职责的，由公安机关给予警告或者停机整顿不超过6个月的处罚。","level":1},{"name":"第五章 附则","text":"第二十四条 与香港特别行政区和台湾、澳门地区联网的计算机信息网络的安全保护管理，参照本办法执行。\n第二十五条 本办法自1997年12月30日起施行。","level":1}]},{"id":"n0377","sections":[{"name":"","text":"城市生活无着的流浪乞讨人员救助管理办法\n(2003年6月18日国务院第12次常务会议通过 2003年6月20日中华人民共和国国务院令第381号公布 自2003年8月1日起施行)\n第一条 为了对在城市生活无着的流浪、乞讨人员(以下简称流浪乞讨人员)实行救助，保障其基本生活权益，完善社会救助制度，制定本办法。\n第二条 县级以上城市人民政府应当根据需要设立流浪乞讨人员救助站。救助站对流浪乞讨人员的救助是一项临时性社会救助措施。\n第三条 县级以上城市人民政府应当采取积极措施及时救助流浪乞讨人员，并应当将救助工作所需经费列入财政预算，予以保障。\n国家鼓励、支持社会组织和个人救助流浪乞讨人员。\n第四条 县级以上人民政府民政部门负责流浪乞讨人员的救助工作，并对救助站进行指导、监督。\n公安、卫生、交通、铁道、城管等部门应当在各自的职责范围内做好相关工作。\n第五条 公安机关和其他有关行政机关的工作人员在执行职务时发现流浪乞讨人员的，应当告知其向救助站求助；对其中的残疾人、未成年人、老年人和行动不便的其他人员，还应当引导、护送到救助站。\n第六条 向救助站求助的流浪乞讨人员，应当如实提供本人的姓名等基本情况并将随身携带物品在救助站登记，向救助站提出求助需求。\n救助站对属于救助对象的求助人员，应当及时提供救助，不得拒绝；对不属于救助对象的求助人员，应当说明不予救助的理由。\n第七条 救助站应当根据受助人员的需要提供下列救助：\n(一)提供符合食品卫生要求的食物；\n(二)提供符合基本条件的住处；\n(三)对在站内突发急病的，及时送医院救治；\n(四)帮助与其亲属或者所在单位联系；\n(五)对没有交通费返回其住所地或者所在单位的，提供乘车凭证。\n第八条 救助站为受助人员提供的住处，应当按性别分室住宿，女性受助人员应当由女性工作人员管理。\n第九条 救助站应当保障受助人员在站内的人身安全和随身携带物品的安全，维护站内秩序。\n第十条 救助站不得向受助人员、其亲属或者所在单位收取费用，不得以任何借口组织受助人员从事生产劳动。\n第十一条 救助站应当劝导受助人员返回其住所地或者所在单位，不得限制受助人员离开救助站。救助站对受助的残疾人、未成年人、老年人应当给予照顾；对查明住址的，及时通知其亲属或者所在单位领回；对无家可归的，由其户籍所在地人民政府妥善安置。\n第十二条 受助人员住所地的县级人民政府应当采取措施，帮助受助人员解决生产、生活困难，教育遗弃残疾人、未成年人、老年人的近亲属或者其他监护人履行抚养、赡养义务。\n第十三条 救助站应当建立、健全站内管理的各项制度，实行规范化管理。\n第十四条 县级以上人民政府民政部门应当加强对救助站工作人员的教育、培训和监督。\n救助站工作人员应当自觉遵守国家的法律法规、政策和有关规章制度，不准拘禁或者变相拘禁受助人员；不准打骂、体罚、虐待受助人员或者唆使他人打骂、体罚、虐待受助人员；不准敲诈、勒索、侵吞受助人员的财物；不准克扣受助人员的生活供应品；不准扣压受助人员的证件、申诉控告材料；不准任用受助人员担任管理工作；不准使用受助人员为工作人员干私活；不准调戏妇女。\n违反前款规定，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予纪律处分。\n第十五条 救助站不履行救助职责的，求助人员可以向当地民政部门举报；民政部门经查证属实的，应当责令救助站及时提供救助，并对直接责任人员依法给予纪律处分。\n第十六条 受助人员应当遵守法律法规。受助人员违反法律法规的，应当依法处理。\n受助人员应当遵守救助站的各项规章制度。\n第十七条 本办法的实施细则由国务院民政部门制定。\n第十八条 本办法自2003年8月1日起施行。1982年5月12日国务院发布的《城市流浪乞讨人员收容遣送办法》同时废止。","level":0}]},{"id":"n0378","sections":[{"name":"","text":"国务院、中央军委关于保护通信线路的规定\n（1982年9月20日发布）\n第一条 通信线路是国家通信网的重要组成部分，担负着党政军民的国内、国际通信任务，在社会主义现代化建设和巩固国防中起着重要作用，为使通信畅通无阻，必须确保通信线路安全。\n第二条 邮电、铁路、军队等部门的各种通信线路设备，都适用本规定。通信线路设备包括：\n(1)架空线路——电杆、电线、电缆、线担、隔电子、拉线及其它附属设备。\n(2)埋设线路——地下、水底、海底、管道电缆，入孔、标石、水线标志牌，无人值守载波增音站，电缆充气站及其它附属设备。\n(3)无线线路——无人值守微波站，微波无源反射板，无线电收、发信天线，微波和卫星通信地面站的天线，天线馈线的杆塔、导线、波导及其它附属设备。\n第三条 各级人民政府要加强对保护通信线路工作的领导，经常开展保护通信线路的宣传教育工作。必要时，应组织沿线各单位的治安保卫组织和民兵组织进行护线联防。\n通信线路遭受自然灾害或战争的破坏时，各级人民政府应立即组织力量协助通信部门进行抢修。\n沿线的机关、厂矿、部队、学校、公社、生产队和人民群众都有保护通信线路安全的责任。对破坏通信线路、危害通信安全的行为，各单位和人民群众有权制止并应及时向当地公安或通信部门报告。\n第四条 各级通信部门及工作人员应加强对通信线路的维护管理，严格执行岗位责任制和各项规章制度，加强巡回检查，经常进行护线宣传，与沿线各单位密切联系，搞好护线联防，协助公安机关侦破破坏通信线路的案件。\n通信部门需要改变其他单位原有设备、设施时，除抢修通信线路障碍等紧急情况外，应事先取得有关单位同意，事后按原标准负责恢复，并负担所需费用。通信部门架设通信线路通过林区时，应事先与有关部门协商确定。\n第五条 偷盗电杆、电线、电缆等通信线路设备或利用技术手段危害通信安全的，都是犯罪行为。公安、司法机关对反革命分子和其他刑事犯罪分子破坏通信线路的案件，应及时组织侦破，依法进行处理。\n第六条 废品回收部门应严格执行国务院一九八○年275号文件精神，不得收购盗窃分子出售的通信线路器材。发现盗卖、变卖通信线路器材的非法行为或可疑线索，应及时向公安机关或通信部门报告。\n第七条 各单位和人民群众都不得损坏通信线路设备或有危害通信安全的行为。\n(1)不准在危及通信线路安全的范围内进行爆破、堆放易爆易燃品或设置易爆易燃品仓库。\n(2)不准在埋有地下电缆的地面上进行钻探、堆放笨重物品、垃圾、矿渣或倾倒含有酸、碱、盐的液体。在埋有地下电缆的地面上开沟、挖渠，应与通信部门协商解决。\n(3)不准在设有过江河电缆标志的水域内抛锚、拖锚、挖沙、炸鱼及进行其他危及电缆安全的作业。\n(4)不准在海图上标明的海底电缆位置两侧各二海里(港内为两侧各一百米)水域内抛锚、拖锚、拖网捕鱼或进行其他危及海底电缆安全的作业。\n(5)不准在地下电缆两侧各一米范围内建屋搭棚，不准在各三米的范围内挖沙取土和设置厕所、粪池、牲畜圈、沼气池等能引起电缆腐蚀的建筑。在市区外电缆两侧各二米、在市区内电缆两侧各零点七五米的范围内，不准植树、种竹。\n(6)不准移动或损坏电杆、拉线、天线、天线馈线杆塔及无人值守载波增音站、微波站。\n(7)不准在危及电杆、拉线安全的范围内取土和架空线路两侧或天线区域内建屋搭棚。\n(8)不准攀登电杆、天线杆塔、拉线及其他附属设备。\n(9)不准在电杆、拉线、天线、天线馈线杆塔、支架及其他附属设备上拴牲口和搭挂电灯线、电力线、广播线；不准在通信电线上搭挂广播喇叭和收音机、电视机的天线。\n(10)不准向电杆、电线、隔电子、电缆、天线、天线馈线及线路附属设备射击、抛掷杂物或进行其他危害线路安全的活动。\n第八条 在通信线路沿线附近建筑施工、筑路、兴修水利、农田建设、植树造林、砍伐树竹、运输超高超大物件、架设线路、敷设管道和进行水下作业等，如有可能危及通信线路安全，应事先取得通信部门同意，并采取技术防范措施以后方可动工。\n对危及通信线路安全的树枝，通信部门应会商有关部门无偿剪除。对已影响通信线路而未修剪的树竹，通信部门可以修剪。\n第九条 通信线路的建设，应考虑线路的安全可靠、经济合理，尽量避免对现有建筑设施构成影响。凡在市、镇、县城和工矿区内新建通信线路，应纳入市镇管线综合规划，尽量和道路及其他管网同步建设。\n设置电杆和埋设电缆应尽量节约用地，少占或不占农田，所需要的土地无偿使用。\n在通信线路施工和检修时应爱护农作物和林木；在施工中损坏青苗、林木，应按规定赔偿。\n第十条 通信线路一般不得迁改。其他单位遇有特殊情况必须迁改通信线路时，应先经通信部门同意，迁改工程所需费用和材料由提出迁改的单位负责。\n第十一条 任何单位和个人，违反本规定，造成损坏线路、阻断通信的，应责令其承担修复线路的费用并赔偿阻断通信所造成的经济损失，直至依法追究刑事责任。\n违反本规定，虽未损坏通信线路，但已危及通信线路安全的，通信部门应进行劝阻或制止；必要时，公安机关应配合通信部门进行劝阻或制止。\n通信工作人员玩忽职守，使设备造成损坏、阻断通信的，应视情节轻重严肃处理。\n第十二条 对保护通信线路、阻止损坏事故、协助侦破案件、抓获犯罪分子、追回被盗通信器材和协助抢修通信线路成绩显著的单位、集体和个人，由通信部门给予表彰或奖励。\n第十三条 本规定自发布之日起施行。以前有关规定如与本规定有抵触，以本规定为准。","level":0}]},{"id":"n0379","sections":[{"name":"","text":"全民健身条例\n(2009年8月30日中华人民共和国国务院令第560号公布 根据2013年7月18日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2016年2月6日《国务院关于修改部分行政法规的决定》第二次修订)","level":0},{"name":"第一章 总则","text":"第一条 为了促进全民健身活动的开展，保障公民在全民健身活动中的合法权益，提高公民身体素质，制定本条例。\n第二条 县级以上地方人民政府应当将全民健身事业纳入本级国民经济和社会发展规划，有计划地建设公共体育设施，加大对农村地区和城市社区等基层公共体育设施建设的投入，促进全民健身事业均衡协调发展。\n国家支持、鼓励、推动与人民群众生活水平相适应的体育消费以及体育产业的发展。\n第三条 国家推动基层文化体育组织建设，鼓励体育类社会团体、体育类民办非企业单位等群众性体育组织开展全民健身活动。\n第四条 公民有依法参加全民健身活动的权利。\n地方各级人民政府应当依法保障公民参加全民健身活动的权利。\n第五条 国务院体育主管部门负责全国的全民健身工作，国务院其他有关部门在各自职责范围内负责有关的全民健身工作。\n县级以上地方人民政府主管体育工作的部门(以下简称体育主管部门)负责本行政区域内的全民健身工作，县级以上地方人民政府其他有关部门在各自职责范围内负责有关的全民健身工作。\n第六条 国家鼓励对全民健身事业提供捐赠和赞助。\n自然人、法人或者其他组织对全民健身事业提供捐赠的，依法享受税收优惠。\n第七条 对在发展全民健身事业中做出突出贡献的组织和个人，按照国家有关规定给予表彰、奖励。","level":1},{"name":"第二章 全民健身计划","text":"第八条 国务院制定全民健身计划，明确全民健身工作的目标、任务、措施、保障等内容。\n县级以上地方人民政府根据本地区的实际情况制定本行政区域的全民健身实施计划。\n制定全民健身计划和全民健身实施计划，应当充分考虑学生、老年人、残疾人和农村居民的特殊需求。\n第九条 国家定期开展公民体质监测和全民健身活动状况调查。\n公民体质监测由国务院体育主管部门会同有关部门组织实施；其中，对学生的体质监测由国务院教育主管部门组织实施。\n全民健身活动状况调查由国务院体育主管部门组织实施。\n第十条 国务院根据公民体质监测结果和全民健身活动状况调查结果，修订全民健身计划。\n县级以上地方人民政府根据公民体质监测结果和全民健身活动状况调查结果，修订全民健身实施计划。\n第十一条 全民健身计划由县级以上人民政府体育主管部门会同有关部门组织实施。县级以上地方人民政府应当加强组织和协调，对本行政区域全民健身计划实施情况负责。\n县级以上人民政府体育主管部门应当在本级人民政府任期届满时会同有关部门对全民健身计划实施情况进行评估，并将评估结果向本级人民政府报告。","level":1},{"name":"第三章 全民健身活动","text":"第十二条 每年8月8日为全民健身日。县级以上人民政府及其有关部门应当在全民健身日加强全民健身宣传。\n国家机关、企业事业单位和其他组织应当在全民健身日结合自身条件组织本单位人员开展全民健身活动。\n县级以上人民政府体育主管部门应当在全民健身日组织开展免费健身指导服务。\n公共体育设施应当在全民健身日向公众免费开放；国家鼓励其他各类体育设施在全民健身日向公众免费开放。\n第十三条 国务院体育主管部门应当定期举办全国性群众体育比赛活动；国务院其他有关部门、全国性社会团体等，可以根据需要举办相应的全国性群众体育比赛活动。\n地方人民政府应当定期举办本行政区域的群众体育比赛活动。\n第十四条 县级人民政府体育主管部门应当在传统节日和农闲季节组织开展与农村生产劳动和文化生活相适应的全民健身活动。\n第十五条 国家机关、企业事业单位和其他组织应当组织本单位人员开展工间(前)操和业余健身活动；有条件的，可以举办运动会，开展体育锻炼测验、体质测定等活动。\n第十六条 工会、共青团、妇联、残联等社会团体应当结合自身特点，组织成员开展全民健身活动。\n单项体育协会应当将普及推广体育项目和组织开展全民健身活动列入工作计划，并对全民健身活动给予指导和支持。\n第十七条 基层文化体育组织、居民委员会和村民委员会应当组织居民开展全民健身活动，协助政府做好相关工作。\n第十八条 鼓励全民健身活动站点、体育俱乐部等群众性体育组织开展全民健身活动，宣传科学健身知识；县级以上人民政府体育主管部门和其他有关部门应当给予支持。\n第十九条 对于依法举办的群众体育比赛等全民健身活动，任何组织或者个人不得非法设置审批和收取审批费用。\n第二十条 广播电台、电视台、报刊和互联网站等应当加强对全民健身活动的宣传报道，普及科学健身知识，增强公民健身意识。\n第二十一条 学校应当按照《中华人民共和国体育法》和《学校体育工作条例》的规定，根据学生的年龄、性别和体质状况，组织实施体育课教学，开展广播体操、眼保健操等体育活动，指导学生的体育锻炼，提高学生的身体素质。\n学校应当保证学生在校期间每天参加1小时的体育活动。\n第二十二条 学校每学年至少举办一次全校性的运动会；有条件的，还可以有计划地组织学生参加远足、野营、体育夏(冬)令营等活动。\n第二十三条 基层文化体育组织、学校、家庭应当加强合作，支持和引导学生参加校外体育活动。\n青少年活动中心、少年宫、妇女儿童中心等应当为学生开展体育活动提供便利。\n第二十四条 组织大型全民健身活动，应当按照国家有关大型群众性活动安全管理的规定，做好安全工作。\n第二十五条 任何组织或者个人不得利用健身活动从事宣扬封建迷信、违背社会公德、扰乱公共秩序、损害公民身心健康的行为。","level":1},{"name":"第四章 全民健身保障","text":"第二十六条 县级以上人民政府应当将全民健身工作所需经费列入本级财政预算，并随着国民经济的发展逐步增加对全民健身的投入。\n按照国家有关彩票公益金的分配政策由体育主管部门分配使用的彩票公益金，应当根据国家有关规定用于全民健身事业。\n第二十七条 公共体育设施的规划、建设、使用、管理、保护和公共体育设施管理单位提供服务，应当遵守《公共文化体育设施条例》的规定。\n公共体育设施的规划、建设应当与当地经济发展水平相适应，方便群众就近参加健身活动；农村地区公共体育设施的规划、建设还应当考虑农村生产劳动和文化生活习惯。\n第二十八条 学校应当在课余时间和节假日向学生开放体育设施。公办学校应当积极创造条件向公众开放体育设施；国家鼓励民办学校向公众开放体育设施。\n县级人民政府对向公众开放体育设施的学校给予支持，为向公众开放体育设施的学校办理有关责任保险。\n学校可以根据维持设施运营的需要向使用体育设施的公众收取必要的费用。\n第二十九条 公园、绿地等公共场所的管理单位，应当根据自身条件安排全民健身活动场地。县级以上地方人民政府体育主管部门根据实际情况免费提供健身器材。\n居民住宅区的设计应当安排健身活动场地。\n第三十条 公园、绿地、广场等公共场所和居民住宅区的管理单位，应当对该公共场所和居民住宅区配置的全民健身器材明确管理和维护责任人。\n第三十一条 国家加强社会体育指导人员队伍建设，对全民健身活动进行科学指导。\n国家对不以收取报酬为目的向公众提供传授健身技能、组织健身活动、宣传科学健身知识等服务的社会体育指导人员实行技术等级制度。县级以上地方人民政府体育主管部门应当免费为其提供相关知识和技能培训，并建立档案。\n国家对以健身指导为职业的社会体育指导人员实行职业资格证书制度。以对高危险性体育项目进行健身指导为职业的社会体育指导人员，应当依照国家有关规定取得职业资格证书。\n第三十二条 企业、个体工商户经营高危险性体育项目的，应当符合下列条件，并向县级以上地方人民政府体育主管部门提出申请：\n(一)相关体育设施符合国家标准；\n(二)具有达到规定数量的取得国家职业资格证书的社会体育指导人员和救助人员；\n(三)具有相应的安全保障制度和措施。\n县级以上地方人民政府体育主管部门应当自收到申请之日起30日内进行实地核查，做出批准或者不予批准的决定。批准的，应当发给许可证；不予批准的，应当书面通知申请人并说明理由。\n国务院体育主管部门应当会同有关部门制定、调整高危险性体育项目目录，经国务院批准后予以公布。\n第三十三条 国家鼓励全民健身活动组织者和健身场所管理者依法投保有关责任保险。\n国家鼓励参加全民健身活动的公民依法投保意外伤害保险。\n第三十四条 县级以上地方人民政府体育主管部门对高危险性体育项目经营活动，应当依法履行监督检查职责。","level":1},{"name":"第五章 法律责任","text":"第三十五条 学校违反本条例规定的，由县级以上人民政府教育主管部门按照管理权限责令改正；拒不改正的，对负有责任的主管人员和其他直接责任人员依法给予处分。\n第三十六条 未经批准，擅自经营高危险性体育项目的，由县级以上地方人民政府体育主管部门按照管理权限责令改正；有违法所得的，没收违法所得；违法所得不足3万元或者没有违法所得的，并处3万元以上10万元以下的罚款；违法所得3万元以上的，并处违法所得2倍以上5倍以下的罚款。\n第三十七条 高危险性体育项目经营者取得许可证后，不再符合本条例规定条件仍经营该体育项目的，由县级以上地方人民政府体育主管部门按照管理权限责令改正；有违法所得的，没收违法所得；违法所得不足3万元或者没有违法所得的，并处3万元以上10万元以下的罚款；违法所得3万元以上的，并处违法所得2倍以上5倍以下的罚款；拒不改正的，由原发证机关吊销许可证。\n第三十八条 利用健身活动从事宣扬封建迷信、违背社会公德、扰乱公共秩序、损害公民身心健康的行为的，由公安机关依照《中华人民共和国治安管理处罚法》的规定给予处罚；构成犯罪的，依法追究刑事责任。\n第三十九条 县级以上人民政府及其有关部门的工作人员在全民健身工作中玩忽职守、滥用职权、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第四十条 本条例自2009年10月1日起施行。","level":1}]},{"id":"n0380","sections":[{"name":"","text":"医疗废物管理条例\n(2003年6月16日中华人民共和国国务院令第380号公布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强医疗废物的安全管理，防止疾病传播，保护环境，保障人体健康，根据《中华人民共和国传染病防治法》和《中华人民共和国固体废物污染环境防治法》，制定本条例。\n第二条 本条例所称医疗废物，是指医疗卫生机构在医疗、预防、保健以及其他相关活动中产生的具有直接或者间接感染性、毒性以及其他危害性的废物。\n医疗废物分类目录，由国务院卫生行政主管部门和环境保护行政主管部门共同制定、公布。\n第三条 本条例适用于医疗废物的收集、运送、贮存、处置以及监督管理等活动。\n医疗卫生机构收治的传染病病人或者疑似传染病病人产生的生活垃圾，按照医疗废物进行管理和处置。\n医疗卫生机构废弃的麻醉、精神、放射性、毒性等药品及其相关的废物的管理，依照有关法律、行政法规和国家有关规定、标准执行。\n第四条 国家推行医疗废物集中无害化处置，鼓励有关医疗废物安全处置技术的研究与开发。\n县级以上地方人民政府负责组织建设医疗废物集中处置设施。\n国家对边远贫困地区建设医疗废物集中处置设施给予适当的支持。\n第五条 县级以上各级人民政府卫生行政主管部门，对医疗废物收集、运送、贮存、处置活动中的疾病防治工作实施统一监督管理；环境保护行政主管部门，对医疗废物收集、运送、贮存、处置活动中的环境污染防治工作实施统一监督管理。\n县级以上各级人民政府其他有关部门在各自的职责范围内负责与医疗废物处置有关的监督管理工作。\n第六条 任何单位和个人有权对医疗卫生机构、医疗废物集中处置单位和监督管理部门及其工作人员的违法行为进行举报、投诉、检举和控告。","level":1},{"name":"第二章 医疗废物管理的一般规定","text":"第七条 医疗卫生机构和医疗废物集中处置单位，应当建立、健全医疗废物管理责任制，其法定代表人为第一责任人，切实履行职责，防止因医疗废物导致传染病传播和环境污染事故。\n第八条 医疗卫生机构和医疗废物集中处置单位，应当制定与医疗废物安全处置有关的规章制度和在发生意外事故时的应急方案；设置监控部门或者专(兼)职人员，负责检查、督促、落实本单位医疗废物的管理工作，防止违反本条例的行为发生。\n第九条 医疗卫生机构和医疗废物集中处置单位，应当对本单位从事医疗废物收集、运送、贮存、处置等工作的人员和管理人员，进行相关法律和专业技术、安全防护以及紧急处理等知识的培训。\n第十条 医疗卫生机构和医疗废物集中处置单位，应当采取有效的职业卫生防护措施，为从事医疗废物收集、运送、贮存、处置等工作的人员和管理人员，配备必要的防护用品，定期进行健康检查；必要时，对有关人员进行免疫接种，防止其受到健康损害。\n第十一条 医疗卫生机构和医疗废物集中处置单位，应当依照《中华人民共和国固体废物污染环境防治法》的规定，执行危险废物转移联单管理制度。\n第十二条 医疗卫生机构和医疗废物集中处置单位，应当对医疗废物进行登记，登记内容应当包括医疗废物的来源、种类、重量或者数量、交接时间、处置方法、最终去向以及经办人签名等项目。登记资料至少保存3年。\n第十三条 医疗卫生机构和医疗废物集中处置单位，应当采取有效措施，防止医疗废物流失、泄漏、扩散。\n发生医疗废物流失、泄漏、扩散时，医疗卫生机构和医疗废物集中处置单位应当采取减少危害的紧急处理措施，对致病人员提供医疗救护和现场救援；同时向所在地的县级人民政府卫生行政主管部门、环境保护行政主管部门报告，并向可能受到危害的单位和居民通报。\n第十四条 禁止任何单位和个人转让、买卖医疗废物。\n禁止在运送过程中丢弃医疗废物；禁止在非贮存地点倾倒、堆放医疗废物或者将医疗废物混入其他废物和生活垃圾。\n第十五条 禁止邮寄医疗废物。\n禁止通过铁路、航空运输医疗废物。\n有陆路通道的，禁止通过水路运输医疗废物；没有陆路通道必需经水路运输医疗废物的，应当经设区的市级以上人民政府环境保护行政主管部门批准，并采取严格的环境保护措施后，方可通过水路运输。\n禁止将医疗废物与旅客在同一运输工具上载运。\n禁止在饮用水源保护区的水体上运输医疗废物。","level":1},{"name":"第三章 医疗卫生机构对医疗废物的管理","text":"第十六条 医疗卫生机构应当及时收集本单位产生的医疗废物，并按照类别分置于防渗漏、防锐器穿透的专用包装物或者密闭的容器内。\n医疗废物专用包装物、容器，应当有明显的警示标识和警示说明。\n医疗废物专用包装物、容器的标准和警示标识的规定，由国务院卫生行政主管部门和环境保护行政主管部门共同制定。\n第十七条 医疗卫生机构应当建立医疗废物的暂时贮存设施、设备，不得露天存放医疗废物；医疗废物暂时贮存的时间不得超过2天。\n医疗废物的暂时贮存设施、设备，应当远离医疗区、食品加工区和人员活动区以及生活垃圾存放场所，并设置明显的警示标识和防渗漏、防鼠、防蚊蝇、防蟑螂、防盗以及预防儿童接触等安全措施。\n医疗废物的暂时贮存设施、设备应当定期消毒和清洁。\n第十八条 医疗卫生机构应当使用防渗漏、防遗撒的专用运送工具，按照本单位确定的内部医疗废物运送时间、路线，将医疗废物收集、运送至暂时贮存地点。\n运送工具使用后应当在医疗卫生机构内指定的地点及时消毒和清洁。\n第十九条 医疗卫生机构应当根据就近集中处置的原则，及时将医疗废物交由医疗废物集中处置单位处置。\n医疗废物中病原体的培养基、标本和菌种、毒种保存液等高危险废物，在交医疗废物集中处置单位处置前应当就地消毒。\n第二十条 医疗卫生机构产生的污水、传染病病人或者疑似传染病病人的排泄物，应当按照国家规定严格消毒；达到国家规定的排放标准后，方可排入污水处理系统。\n第二十一条 不具备集中处置医疗废物条件的农村，医疗卫生机构应当按照县级人民政府卫生行政主管部门、环境保护行政主管部门的要求，自行就地处置其产生的医疗废物。自行处置医疗废物的，应当符合下列基本要求：\n(一)使用后的一次性医疗器具和容易致人损伤的医疗废物，应当消毒并作毁形处理；\n(二)能够焚烧的，应当及时焚烧；\n(三)不能焚烧的，消毒后集中填埋。","level":1},{"name":"第四章 医疗废物的集中处置","text":"第二十二条 从事医疗废物集中处置活动的单位，应当向县级以上人民政府环境保护行政主管部门申请领取经营许可证；未取得经营许可证的单位，不得从事有关医疗废物集中处置的活动。\n第二十三条 医疗废物集中处置单位，应当符合下列条件：\n(一)具有符合环境保护和卫生要求的医疗废物贮存、处置设施或者设备；\n(二)具有经过培训的技术人员以及相应的技术工人；\n(三)具有负责医疗废物处置效果检测、评价工作的机构和人员；\n(四)具有保证医疗废物安全处置的规章制度。\n第二十四条 医疗废物集中处置单位的贮存、处置设施，应当远离居(村)民居住区、水源保护区和交通干道，与工厂、企业等工作场所有适当的安全防护距离，并符合国务院环境保护行政主管部门的规定。\n第二十五条 医疗废物集中处置单位应当至少每2天到医疗卫生机构收集、运送一次医疗废物，并负责医疗废物的贮存、处置。\n第二十六条 医疗废物集中处置单位运送医疗废物，应当遵守国家有关危险货物运输管理的规定，使用有明显医疗废物标识的专用车辆。医疗废物专用车辆应当达到防渗漏、防遗撒以及其他环境保护和卫生要求。\n运送医疗废物的专用车辆使用后，应当在医疗废物集中处置场所内及时进行消毒和清洁。\n运送医疗废物的专用车辆不得运送其他物品。\n第二十七条 医疗废物集中处置单位在运送医疗废物过程中应当确保安全，不得丢弃、遗撒医疗废物。\n第二十八条 医疗废物集中处置单位应当安装污染物排放在线监控装置，并确保监控装置经常处于正常运行状态。\n第二十九条 医疗废物集中处置单位处置医疗废物，应当符合国家规定的环境保护、卫生标准、规范。\n第三十条 医疗废物集中处置单位应当按照环境保护行政主管部门和卫生行政主管部门的规定，定期对医疗废物处置设施的环境污染防治和卫生学效果进行检测、评价。检测、评价结果存入医疗废物集中处置单位档案，每半年向所在地环境保护行政主管部门和卫生行政主管部门报告一次。\n第三十一条 医疗废物集中处置单位处置医疗废物，按照国家有关规定向医疗卫生机构收取医疗废物处置费用。\n医疗卫生机构按照规定支付的医疗废物处置费用，可以纳入医疗成本。\n第三十二条 各地区应当利用和改造现有固体废物处置设施和其他设施，对医疗废物集中处置，并达到基本的环境保护和卫生要求。\n第三十三条 尚无集中处置设施或者处置能力不足的城市，自本条例施行之日起，设区的市级以上城市应当在1年内建成医疗废物集中处置设施；县级市应当在2年内建成医疗废物集中处置设施。县(旗)医疗废物集中处置设施的建设，由省、自治区、直辖市人民政府规定。\n在尚未建成医疗废物集中处置设施期间，有关地方人民政府应当组织制定符合环境保护和卫生要求的医疗废物过渡性处置方案，确定医疗废物收集、运送、处置方式和处置单位。","level":1},{"name":"第五章 监督管理","text":"第三十四条 县级以上地方人民政府卫生行政主管部门、环境保护行政主管部门，应当依照本条例的规定，按照职责分工，对医疗卫生机构和医疗废物集中处置单位进行监督检查。\n第三十五条 县级以上地方人民政府卫生行政主管部门，应当对医疗卫生机构和医疗废物集中处置单位从事医疗废物的收集、运送、贮存、处置中的疾病防治工作，以及工作人员的卫生防护等情况进行定期监督检查或者不定期的抽查。\n第三十六条 县级以上地方人民政府环境保护行政主管部门，应当对医疗卫生机构和医疗废物集中处置单位从事医疗废物收集、运送、贮存、处置中的环境污染防治工作进行定期监督检查或者不定期的抽查。\n第三十七条 卫生行政主管部门、环境保护行政主管部门应当定期交换监督检查和抽查结果。在监督检查或者抽查中发现医疗卫生机构和医疗废物集中处置单位存在隐患时，应当责令立即消除隐患。\n第三十八条 卫生行政主管部门、环境保护行政主管部门接到对医疗卫生机构、医疗废物集中处置单位和监督管理部门及其工作人员违反本条例行为的举报、投诉、检举和控告后，应当及时核实，依法作出处理，并将处理结果予以公布。\n第三十九条 卫生行政主管部门、环境保护行政主管部门履行监督检查职责时，有权采取下列措施：\n(一)对有关单位进行实地检查，了解情况，现场监测，调查取证；\n(二)查阅或者复制医疗废物管理的有关资料，采集样品；\n(三)责令违反本条例规定的单位和个人停止违法行为；\n(四)查封或者暂扣涉嫌违反本条例规定的场所、设备、运输工具和物品；\n(五)对违反本条例规定的行为进行查处。\n第四十条 发生因医疗废物管理不当导致传染病传播或者环境污染事故，或者有证据证明传染病传播或者环境污染的事故有可能发生时，卫生行政主管部门、环境保护行政主管部门应当采取临时控制措施，疏散人员，控制现场，并根据需要责令暂停导致或者可能导致传染病传播或者环境污染事故的作业。\n第四十一条 医疗卫生机构和医疗废物集中处置单位，对有关部门的检查、监测、调查取证，应当予以配合，不得拒绝和阻碍，不得提供虚假材料。","level":1},{"name":"第六章 法律责任","text":"第四十二条 县级以上地方人民政府未依照本条例的规定，组织建设医疗废物集中处置设施或者组织制定医疗废物过渡性处置方案的，由上级人民政府通报批评，责令限期建成医疗废物集中处置设施或者组织制定医疗废物过渡性处置方案；并可以对政府主要领导人、负有责任的主管人员，依法给予行政处分。\n第四十三条 县级以上各级人民政府卫生行政主管部门、环境保护行政主管部门或者其他有关部门，未按照本条例的规定履行监督检查职责，发现医疗卫生机构和医疗废物集中处置单位的违法行为不及时处理，发生或者可能发生传染病传播或者环境污染事故时未及时采取减少危害措施，以及有其他玩忽职守、失职、渎职行为的，由本级人民政府或者上级人民政府有关部门责令改正，通报批评；造成传染病传播或者环境污染事故的，对主要负责人、负有责任的主管人员和其他直接责任人员依法给予降级、撤职、开除的行政处分；构成犯罪的，依法追究刑事责任。\n第四十四条 县级以上人民政府环境保护行政主管部门，违反本条例的规定发给医疗废物集中处置单位经营许可证的，由本级人民政府或者上级人民政府环境保护行政主管部门通报批评，责令收回违法发给的证书；并可以对主要负责人、负有责任的主管人员和其他直接责任人员依法给予行政处分。\n第四十五条 医疗卫生机构、医疗废物集中处置单位违反本条例规定，有下列情形之一的，由县级以上地方人民政府卫生行政主管部门或者环境保护行政主管部门按照各自的职责责令限期改正，给予警告；逾期不改正的，处2000元以上5000元以下的罚款：\n(一)未建立、健全医疗废物管理制度，或者未设置监控部门或者专(兼)职人员的；\n(二)未对有关人员进行相关法律和专业技术、安全防护以及紧急处理等知识的培训的；\n(三)未对从事医疗废物收集、运送、贮存、处置等工作的人员和管理人员采取职业卫生防护措施的；\n(四)未对医疗废物进行登记或者未保存登记资料的；\n(五)对使用后的医疗废物运送工具或者运送车辆未在指定地点及时进行消毒和清洁的；\n(六)未及时收集、运送医疗废物的；\n(七)未定期对医疗废物处置设施的环境污染防治和卫生学效果进行检测、评价，或者未将检测、评价效果存档、报告的。\n第四十六条 医疗卫生机构、医疗废物集中处置单位违反本条例规定，有下列情形之一的，由县级以上地方人民政府卫生行政主管部门或者环境保护行政主管部门按照各自的职责责令限期改正，给予警告，可以并处5000元以下的罚款；逾期不改正的，处5000元以上3万元以下的罚款：\n(一)贮存设施或者设备不符合环境保护、卫生要求的；\n(二)未将医疗废物按照类别分置于专用包装物或者容器的；\n(三)未使用符合标准的专用车辆运送医疗废物或者使用运送医疗废物的车辆运送其他物品的；\n(四)未安装污染物排放在线监控装置或者监控装置未经常处于正常运行状态的。\n第四十七条 医疗卫生机构、医疗废物集中处置单位有下列情形之一的，由县级以上地方人民政府卫生行政主管部门或者环境保护行政主管部门按照各自的职责责令限期改正，给予警告，并处5000元以上1万元以下的罚款；逾期不改正的，处1万元以上3万元以下的罚款；造成传染病传播或者环境污染事故的，由原发证部门暂扣或者吊销执业许可证件或者经营许可证件；构成犯罪的，依法追究刑事责任：\n(一)在运送过程中丢弃医疗废物，在非贮存地点倾倒、堆放医疗废物或者将医疗废物混入其他废物和生活垃圾的；\n(二)未执行危险废物转移联单管理制度的；\n(三)将医疗废物交给未取得经营许可证的单位或者个人收集、运送、贮存、处置的；\n(四)对医疗废物的处置不符合国家规定的环境保护、卫生标准、规范的；\n(五)未按照本条例的规定对污水、传染病病人或者疑似传染病病人的排泄物，进行严格消毒，或者未达到国家规定的排放标准，排入污水处理系统的；\n(六)对收治的传染病病人或者疑似传染病病人产生的生活垃圾，未按照医疗废物进行管理和处置的。\n第四十八条 医疗卫生机构违反本条例规定，将未达到国家规定标准的污水、传染病病人或者疑似传染病病人的排泄物排入城市排水管网的，由县级以上地方人民政府建设行政主管部门责令限期改正，给予警告，并处5000元以上1万元以下的罚款；逾期不改正的，处1万元以上3万元以下的罚款；造成传染病传播或者环境污染事故的，由原发证部门暂扣或者吊销执业许可证件；构成犯罪的，依法追究刑事责任。\n第四十九条 医疗卫生机构、医疗废物集中处置单位发生医疗废物流失、泄漏、扩散时，未采取紧急处理措施，或者未及时向卫生行政主管部门和环境保护行政主管部门报告的，由县级以上地方人民政府卫生行政主管部门或者环境保护行政主管部门按照各自的职责责令改正，给予警告，并处1万元以上3万元以下的罚款；造成传染病传播或者环境污染事故的，由原发证部门暂扣或者吊销执业许可证件或者经营许可证件；构成犯罪的，依法追究刑事责任。\n第五十条 医疗卫生机构、医疗废物集中处置单位，无正当理由，阻碍卫生行政主管部门或者环境保护行政主管部门执法人员执行职务，拒绝执法人员进入现场，或者不配合执法部门的检查、监测、调查取证的，由县级以上地方人民政府卫生行政主管部门或者环境保护行政主管部门按照各自的职责责令改正，给予警告；拒不改正的，由原发证部门暂扣或者吊销执业许可证件或者经营许可证件；触犯《中华人民共和国治安管理处罚法》，构成违反治安管理行为的，由公安机关依法予以处罚；构成犯罪的，依法追究刑事责任。\n第五十一条 不具备集中处置医疗废物条件的农村，医疗卫生机构未按照本条例的要求处置医疗废物的，由县级人民政府卫生行政主管部门或者环境保护行政主管部门按照各自的职责责令限期改正，给予警告；逾期不改正的，处1000元以上5000元以下的罚款；造成传染病传播或者环境污染事故的，由原发证部门暂扣或者吊销执业许可证件；构成犯罪的，依法追究刑事责任。\n第五十二条 未取得经营许可证从事医疗废物的收集、运送、贮存、处置等活动的，由县级以上地方人民政府环境保护行政主管部门责令立即停止违法行为，没收违法所得，可以并处违法所得1倍以下的罚款。\n第五十三条 转让、买卖医疗废物，邮寄或者通过铁路、航空运输医疗废物，或者违反本条例规定通过水路运输医疗废物的，由县级以上地方人民政府环境保护行政主管部门责令转让、买卖双方、邮寄人、托运人立即停止违法行为，给予警告，没收违法所得；违法所得5000元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足5000元的，并处5000元以上2万元以下的罚款。\n承运人明知托运人违反本条例的规定运输医疗废物，仍予以运输的，或者承运人将医疗废物与旅客在同一工具上载运的，按照前款的规定予以处罚。\n第五十四条 医疗卫生机构、医疗废物集中处置单位违反本条例规定，导致传染病传播或者发生环境污染事故，给他人造成损害的，依法承担民事赔偿责任。","level":1},{"name":"第七章 附则","text":"第五十五条 计划生育技术服务、医学科研、教学、尸体检查和其他相关活动中产生的具有直接或者间接感染性、毒性以及其他危害性废物的管理，依照本条例执行。\n第五十六条 军队医疗卫生机构医疗废物的管理由中国人民解放军卫生主管部门参照本条例制定管理办法。\n第五十七条 本条例自公布之日起施行。","level":1}]},{"id":"n0381","sections":[{"name":"","text":"防治船舶污染海洋环境管理条例\n(2009年9月9日中华人民共和国国务院令第561号公布 根据2013年7月18日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2013年12月7日《国务院关于修改部分行政法规的决定》第二次修订 根据2014年7月29日《国务院关于修改部分行政法规的决定》第三次修订 根据2016年2月6日《国务院关于修改部分行政法规的决定》第四次修订 根据2017年3月1日《国务院关于修改和废止部分行政法规的决定》第五次修订 根据2018年3月19日《国务院关于修改和废止部分行政法规的决定》第六次修订)","level":0},{"name":"第一章 总则","text":"第一条 为了防治船舶及其有关作业活动污染海洋环境，根据《中华人民共和国海洋环境保护法》，制定本条例。\n第二条 防治船舶及其有关作业活动污染中华人民共和国管辖海域适用本条例。\n第三条 防治船舶及其有关作业活动污染海洋环境，实行预防为主、防治结合的原则。\n第四条 国务院交通运输主管部门主管所辖港区水域内非军事船舶和港区水域外非渔业、非军事船舶污染海洋环境的防治工作。\n海事管理机构依照本条例规定具体负责防治船舶及其有关作业活动污染海洋环境的监督管理。\n第五条 国务院交通运输主管部门应当根据防治船舶及其有关作业活动污染海洋环境的需要，组织编制防治船舶及其有关作业活动污染海洋环境应急能力建设规划，报国务院批准后公布实施。\n沿海设区的市级以上地方人民政府应当按照国务院批准的防治船舶及其有关作业活动污染海洋环境应急能力建设规划，并根据本地区的实际情况，组织编制相应的防治船舶及其有关作业活动污染海洋环境应急能力建设规划。\n第六条 国务院交通运输主管部门、沿海设区的市级以上地方人民政府应当建立健全防治船舶及其有关作业活动污染海洋环境应急反应机制，并制定防治船舶及其有关作业活动污染海洋环境应急预案。\n第七条 海事管理机构应当根据防治船舶及其有关作业活动污染海洋环境的需要，会同海洋主管部门建立健全船舶及其有关作业活动污染海洋环境的监测、监视机制，加强对船舶及其有关作业活动污染海洋环境的监测、监视。\n第八条 国务院交通运输主管部门、沿海设区的市级以上地方人民政府应当按照防治船舶及其有关作业活动污染海洋环境应急能力建设规划，建立专业应急队伍和应急设备库，配备专用的设施、设备和器材。\n第九条 任何单位和个人发现船舶及其有关作业活动造成或者可能造成海洋环境污染的，应当立即就近向海事管理机构报告。","level":1},{"name":"第二章 防治船舶及其有关作业活动污染海洋环境的一般规定","text":"第十条 船舶的结构、设备、器材应当符合国家有关防治船舶污染海洋环境的技术规范以及中华人民共和国缔结或者参加的国际条约的要求。\n船舶应当依照法律、行政法规、国务院交通运输主管部门的规定以及中华人民共和国缔结或者参加的国际条约的要求，取得并随船携带相应的防治船舶污染海洋环境的证书、文书。\n第十一条 中国籍船舶的所有人、经营人或者管理人应当按照国务院交通运输主管部门的规定，建立健全安全营运和防治船舶污染管理体系。\n海事管理机构应当对安全营运和防治船舶污染管理体系进行审核，审核合格的，发给符合证明和相应的船舶安全管理证书。\n第十二条 港口、码头、装卸站以及从事船舶修造的单位应当配备与其装卸货物种类和吞吐能力或者修造船舶能力相适应的污染监视设施和污染物接收设施，并使其处于良好状态。\n第十三条 港口、码头、装卸站以及从事船舶修造、打捞、拆解等作业活动的单位应当制定有关安全营运和防治污染的管理制度，按照国家有关防治船舶及其有关作业活动污染海洋环境的规范和标准，配备相应的防治污染设备和器材。\n港口、码头、装卸站以及从事船舶修造、打捞、拆解等作业活动的单位，应当定期检查、维护配备的防治污染设备和器材，确保防治污染设备和器材符合防治船舶及其有关作业活动污染海洋环境的要求。\n第十四条 船舶所有人、经营人或者管理人应当制定防治船舶及其有关作业活动污染海洋环境的应急预案，并报海事管理机构备案。\n港口、码头、装卸站的经营人以及有关作业单位应当制定防治船舶及其有关作业活动污染海洋环境的应急预案，并报海事管理机构和环境保护主管部门备案。\n船舶、港口、码头、装卸站以及其他有关作业单位应当按照应急预案，定期组织演练，并做好相应记录。","level":1},{"name":"第三章 船舶污染物的排放和接收","text":"第十五条 船舶在中华人民共和国管辖海域向海洋排放的船舶垃圾、生活污水、含油污水、含有毒有害物质污水、废气等污染物以及压载水，应当符合法律、行政法规、中华人民共和国缔结或者参加的国际条约以及相关标准的要求。\n船舶应当将不符合前款规定的排放要求的污染物排入港口接收设施或者由船舶污染物接收单位接收。\n船舶不得向依法划定的海洋自然保护区、海滨风景名胜区、重要渔业水域以及其他需要特别保护的海域排放船舶污染物。\n第十六条 船舶处置污染物，应当在相应的记录簿内如实记录。\n船舶应当将使用完毕的船舶垃圾记录簿在船舶上保留2年；将使用完毕的含油污水、含有毒有害物质污水记录簿在船舶上保留3年。\n第十七条 船舶污染物接收单位从事船舶垃圾、残油、含油污水、含有毒有害物质污水接收作业，应当编制作业方案，遵守相关操作规程，并采取必要的防污染措施。船舶污染物接收单位应当将船舶污染物接收情况按照规定向海事管理机构报告。\n第十八条 船舶污染物接收单位接收船舶污染物，应当向船舶出具污染物接收单证，经双方签字确认并留存至少2年。污染物接收单证应当注明作业双方名称，作业开始和结束的时间、地点，以及污染物种类、数量等内容。船舶应当将污染物接收单证保存在相应的记录簿中。\n第十九条 船舶污染物接收单位应当按照国家有关污染物处理的规定处理接收的船舶污染物，并每月将船舶污染物的接收和处理情况报海事管理机构备案。","level":1},{"name":"第四章 船舶有关作业活动的污染防治","text":"第二十条 从事船舶清舱、洗舱、油料供受、装卸、过驳、修造、打捞、拆解，污染危害性货物装箱、充罐，污染清除作业以及利用船舶进行水上水下施工等作业活动的，应当遵守相关操作规程，并采取必要的安全和防治污染的措施。\n从事前款规定的作业活动的人员，应当具备相关安全和防治污染的专业知识和技能。\n第二十一条 船舶不符合污染危害性货物适载要求的，不得载运污染危害性货物，码头、装卸站不得为其进行装载作业。\n污染危害性货物的名录由国家海事管理机构公布。\n第二十二条 载运污染危害性货物进出港口的船舶，其承运人、货物所有人或者代理人，应当向海事管理机构提出申请，经批准方可进出港口或者过境停留。\n第二十三条 载运污染危害性货物的船舶，应当在海事管理机构公布的具有相应安全装卸和污染物处理能力的码头、装卸站进行装卸作业。\n第二十四条 货物所有人或者代理人交付船舶载运污染危害性货物，应当确保货物的包装与标志等符合有关安全和防治污染的规定，并在运输单证上准确注明货物的技术名称、编号、类别(性质)、数量、注意事项和应急措施等内容。\n货物所有人或者代理人交付船舶载运污染危害性不明的货物，应当委托有关技术机构进行危害性评估，明确货物的危害性质以及有关安全和防治污染要求，方可交付船舶载运。\n第二十五条 海事管理机构认为交付船舶载运的污染危害性货物应当申报而未申报，或者申报的内容不符合实际情况的，可以按照国务院交通运输主管部门的规定采取开箱等方式查验。\n海事管理机构查验污染危害性货物，货物所有人或者代理人应当到场，并负责搬移货物，开拆和重封货物的包装。海事管理机构认为必要的，可以径行查验、复验或者提取货样，有关单位和个人应当配合。\n第二十六条 进行散装液体污染危害性货物过驳作业的船舶，其承运人、货物所有人或者代理人应当向海事管理机构提出申请，告知作业地点，并附送过驳作业方案、作业程序、防治污染措施等材料。\n海事管理机构应当自受理申请之日起2个工作日内作出许可或者不予许可的决定。2个工作日内无法作出决定的，经海事管理机构负责人批准，可以延长5个工作日。\n第二十七条 依法获得船舶油料供受作业资质的单位，应当向海事管理机构备案。海事管理机构应当对船舶油料供受作业进行监督检查，发现不符合安全和防治污染要求的，应当予以制止。\n第二十八条 船舶燃油供给单位应当如实填写燃油供受单证，并向船舶提供船舶燃油供受单证和燃油样品。\n船舶和船舶燃油供给单位应当将燃油供受单证保存3年，并将燃油样品妥善保存1年。\n第二十九条 船舶修造、水上拆解的地点应当符合环境功能区划和海洋功能区划。\n第三十条 从事船舶拆解的单位在船舶拆解作业前，应当对船舶上的残余物和废弃物进行处置，将油舱(柜)中的存油驳出，进行船舶清舱、洗舱、测爆等工作。\n从事船舶拆解的单位应当及时清理船舶拆解现场，并按照国家有关规定处理船舶拆解产生的污染物。\n禁止采取冲滩方式进行船舶拆解作业。\n第三十一条 禁止船舶经过中华人民共和国内水、领海转移危险废物。\n经过中华人民共和国管辖的其他海域转移危险废物的，应当事先取得国务院环境保护主管部门的书面同意，并按照海事管理机构指定的航线航行，定时报告船舶所处的位置。\n第三十二条 船舶向海洋倾倒废弃物，应当如实记录倾倒情况。返港后，应当向驶出港所在地的海事管理机构提交书面报告。\n第三十三条 载运散装液体污染危害性货物的船舶和1万总吨以上的其他船舶，其经营人应当在作业前或者进出港口前与符合国家有关技术规范的污染清除作业单位签订污染清除作业协议，明确双方在发生船舶污染事故后污染清除的权利和义务。\n与船舶经营人签订污染清除作业协议的污染清除作业单位应当在发生船舶污染事故后，按照污染清除作业协议及时进行污染清除作业。","level":1},{"name":"第五章 船舶污染事故应急处置","text":"第三十四条 本条例所称船舶污染事故，是指船舶及其有关作业活动发生油类、油性混合物和其他有毒有害物质泄漏造成的海洋环境污染事故。\n第三十五条 船舶污染事故分为以下等级：\n(一)特别重大船舶污染事故，是指船舶溢油1000吨以上，或者造成直接经济损失2亿元以上的船舶污染事故；\n(二)重大船舶污染事故，是指船舶溢油500吨以上不足1000吨，或者造成直接经济损失1亿元以上不足2亿元的船舶污染事故；\n(三)较大船舶污染事故，是指船舶溢油100吨以上不足500吨，或者造成直接经济损失5000万元以上不足1亿元的船舶污染事故；\n(四)一般船舶污染事故，是指船舶溢油不足100吨，或者造成直接经济损失不足5000万元的船舶污染事故。\n第三十六条 船舶在中华人民共和国管辖海域发生污染事故，或者在中华人民共和国管辖海域外发生污染事故造成或者可能造成中华人民共和国管辖海域污染的，应当立即启动相应的应急预案，采取措施控制和消除污染，并就近向有关海事管理机构报告。\n发现船舶及其有关作业活动可能对海洋环境造成污染的，船舶、码头、装卸站应当立即采取相应的应急处置措施，并就近向有关海事管理机构报告。\n接到报告的海事管理机构应当立即核实有关情况，并向上级海事管理机构或者国务院交通运输主管部门报告，同时报告有关沿海设区的市级以上地方人民政府。\n第三十七条 船舶污染事故报告应当包括下列内容：\n(一)船舶的名称、国籍、呼号或者编号；\n(二)船舶所有人、经营人或者管理人的名称、地址；\n(三)发生事故的时间、地点以及相关气象和水文情况；\n(四)事故原因或者事故原因的初步判断；\n(五)船舶上污染物的种类、数量、装载位置等概况；\n(六)污染程度；\n(七)已经采取或者准备采取的污染控制、清除措施和污染控制情况以及救助要求；\n(八)国务院交通运输主管部门规定应当报告的其他事项。\n作出船舶污染事故报告后出现新情况的，船舶、有关单位应当及时补报。\n第三十八条 发生特别重大船舶污染事故，国务院或者国务院授权国务院交通运输主管部门成立事故应急指挥机构。\n发生重大船舶污染事故，有关省、自治区、直辖市人民政府应当会同海事管理机构成立事故应急指挥机构。\n发生较大船舶污染事故和一般船舶污染事故，有关设区的市级人民政府应当会同海事管理机构成立事故应急指挥机构。\n有关部门、单位应当在事故应急指挥机构统一组织和指挥下，按照应急预案的分工，开展相应的应急处置工作。\n第三十九条 船舶发生事故有沉没危险，船员离船前，应当尽可能关闭所有货舱(柜)、油舱(柜)管系的阀门，堵塞货舱(柜)、油舱(柜)通气孔。\n船舶沉没的，船舶所有人、经营人或者管理人应当及时向海事管理机构报告船舶燃油、污染危害性货物以及其他污染物的性质、数量、种类、装载位置等情况，并及时采取措施予以清除。\n第四十条 发生船舶污染事故或者船舶沉没，可能造成中华人民共和国管辖海域污染的，有关沿海设区的市级以上地方人民政府、海事管理机构根据应急处置的需要，可以征用有关单位或者个人的船舶和防治污染设施、设备、器材以及其他物资，有关单位和个人应当予以配合。\n被征用的船舶和防治污染设施、设备、器材以及其他物资使用完毕或者应急处置工作结束，应当及时返还。船舶和防治污染设施、设备、器材以及其他物资被征用或者征用后毁损、灭失的，应当给予补偿。\n第四十一条 发生船舶污染事故，海事管理机构可以采取清除、打捞、拖航、引航、过驳等必要措施，减轻污染损害。相关费用由造成海洋环境污染的船舶、有关作业单位承担。\n需要承担前款规定费用的船舶，应当在开航前缴清相关费用或者提供相应的财务担保。\n第四十二条 处置船舶污染事故使用的消油剂，应当符合国家有关标准。","level":1},{"name":"第六章 船舶污染事故调查处理","text":"第四十三条 船舶污染事故的调查处理依照下列规定进行：\n(一)特别重大船舶污染事故由国务院或者国务院授权国务院交通运输主管部门等部门组织事故调查处理；\n(二)重大船舶污染事故由国家海事管理机构组织事故调查处理；\n(三)较大船舶污染事故和一般船舶污染事故由事故发生地的海事管理机构组织事故调查处理。\n船舶污染事故给渔业造成损害的，应当吸收渔业主管部门参与调查处理；给军事港口水域造成损害的，应当吸收军队有关主管部门参与调查处理。\n第四十四条 发生船舶污染事故，组织事故调查处理的机关或者海事管理机构应当及时、客观、公正地开展事故调查，勘验事故现场，检查相关船舶，询问相关人员，收集证据，查明事故原因。\n第四十五条 组织事故调查处理的机关或者海事管理机构根据事故调查处理的需要，可以暂扣相应的证书、文书、资料；必要时，可以禁止船舶驶离港口或者责令停航、改航、停止作业直至暂扣船舶。\n第四十六条 组织事故调查处理的机关或者海事管理机构开展事故调查时，船舶污染事故的当事人和其他有关人员应当如实反映情况和提供资料，不得伪造、隐匿、毁灭证据或者以其他方式妨碍调查取证。\n第四十七条 组织事故调查处理的机关或者海事管理机构应当自事故调查结束之日起20个工作日内制作事故认定书，并送达当事人。\n事故认定书应当载明事故基本情况、事故原因和事故责任。","level":1},{"name":"第七章 船舶污染事故损害赔偿","text":"第四十八条 造成海洋环境污染损害的责任者，应当排除危害，并赔偿损失；完全由于第三者的故意或者过失，造成海洋环境污染损害的，由第三者排除危害，并承担赔偿责任。\n第四十九条 完全属于下列情形之一，经过及时采取合理措施，仍然不能避免对海洋环境造成污染损害的，免予承担责任：\n(一)战争；\n(二)不可抗拒的自然灾害；\n(三)负责灯塔或者其他助航设备的主管部门，在执行职责时的疏忽，或者其他过失行为。\n第五十条 船舶污染事故的赔偿限额依照《中华人民共和国海商法》关于海事赔偿责任限制的规定执行。但是，船舶载运的散装持久性油类物质造成中华人民共和国管辖海域污染的，赔偿限额依照中华人民共和国缔结或者参加的有关国际条约的规定执行。\n前款所称持久性油类物质，是指任何持久性烃类矿物油。\n第五十一条 在中华人民共和国管辖海域内航行的船舶，其所有人应当按照国务院交通运输主管部门的规定，投保船舶油污损害民事责任保险或者取得相应的财务担保。但是，1000总吨以下载运非油类物质的船舶除外。\n船舶所有人投保船舶油污损害民事责任保险或者取得的财务担保的额度应当不低于《中华人民共和国海商法》、中华人民共和国缔结或者参加的有关国际条约规定的油污赔偿限额。\n第五十二条 已依照本条例第五十一条的规定投保船舶油污损害民事责任保险或者取得财务担保的中国籍船舶，其所有人应当持船舶国籍证书、船舶油污损害民事责任保险合同或者财务担保证明，向船籍港的海事管理机构申请办理船舶油污损害民事责任保险证书或者财务保证证书。\n第五十三条 发生船舶油污事故，国家组织有关单位进行应急处置、清除污染所发生的必要费用，应当在船舶油污损害赔偿中优先受偿。\n第五十四条 在中华人民共和国管辖水域接收海上运输的持久性油类物质货物的货物所有人或者代理人应当缴纳船舶油污损害赔偿基金。\n船舶油污损害赔偿基金征收、使用和管理的具体办法由国务院财政部门会同国务院交通运输主管部门制定。\n国家设立船舶油污损害赔偿基金管理委员会，负责处理船舶油污损害赔偿基金的赔偿等事务。船舶油污损害赔偿基金管理委员会由有关行政机关和缴纳船舶油污损害赔偿基金的主要货主组成。\n第五十五条 对船舶污染事故损害赔偿的争议，当事人可以请求海事管理机构调解，也可以向仲裁机构申请仲裁或者向人民法院提起民事诉讼。","level":1},{"name":"第八章 法律责任","text":"第五十六条 船舶、有关作业单位违反本条例规定的，海事管理机构应当责令改正；拒不改正的，海事管理机构可以责令停止作业、强制卸载，禁止船舶进出港口、靠泊、过境停留，或者责令停航、改航、离境、驶向指定地点。\n第五十七条 违反本条例的规定，船舶的结构不符合国家有关防治船舶污染海洋环境的技术规范或者有关国际条约要求的，由海事管理机构处10万元以上30万元以下的罚款。\n第五十八条 违反本条例的规定，有下列情形之一的，由海事管理机构依照《中华人民共和国海洋环境保护法》有关规定予以处罚：\n(一)船舶未取得并随船携带防治船舶污染海洋环境的证书、文书的；\n(二)船舶、港口、码头、装卸站未配备防治污染设备、器材的；\n(三)船舶向海域排放本条例禁止排放的污染物的；\n(四)船舶未如实记录污染物处置情况的；\n(五)船舶超过标准向海域排放污染物的；\n(六)从事船舶水上拆解作业，造成海洋环境污染损害的。\n第五十九条 违反本条例的规定，船舶未按照规定在船舶上留存船舶污染物处置记录，或者船舶污染物处置记录与船舶运行过程中产生的污染物数量不符合的，由海事管理机构处2万元以上10万元以下的罚款。\n第六十条 违反本条例的规定，船舶污染物接收单位从事船舶垃圾、残油、含油污水、含有毒有害物质污水接收作业，未编制作业方案、遵守相关操作规程、采取必要的防污染措施的，由海事管理机构处1万元以上5万元以下的罚款；造成海洋环境污染的，处5万元以上25万元以下的罚款。\n第六十一条 违反本条例的规定，船舶污染物接收单位未按照规定向海事管理机构报告船舶污染物接收情况，或者未按照规定向船舶出具污染物接收单证，或者未按照规定将船舶污染物的接收和处理情况报海事管理机构备案的，由海事管理机构处2万元以下的罚款。\n第六十二条 违反本条例的规定，有下列情形之一的，由海事管理机构处2000元以上1万元以下的罚款：\n(一)船舶未按照规定保存污染物接收单证的；\n(二)船舶燃油供给单位未如实填写燃油供受单证的；\n(三)船舶燃油供给单位未按照规定向船舶提供燃油供受单证和燃油样品的；\n(四)船舶和船舶燃油供给单位未按照规定保存燃油供受单证和燃油样品的。\n第六十三条 违反本条例的规定，有下列情形之一的，由海事管理机构处2万元以上10万元以下的罚款：\n(一)载运污染危害性货物的船舶不符合污染危害性货物适载要求的；\n(二)载运污染危害性货物的船舶未在具有相应安全装卸和污染物处理能力的码头、装卸站进行装卸作业的；\n(三)货物所有人或者代理人未按照规定对污染危害性不明的货物进行危害性评估的。\n第六十四条 违反本条例的规定，未经海事管理机构批准，船舶载运污染危害性货物进出港口、过境停留或者过驳作业的，由海事管理机构处1万元以上5万元以下的罚款。\n第六十五条 违反本条例的规定，有下列情形之一的，由海事管理机构处2万元以上10万元以下的罚款：\n(一)船舶发生事故沉没，船舶所有人或者经营人未及时向海事管理机构报告船舶燃油、污染危害性货物以及其他污染物的性质、数量、种类、装载位置等情况的；\n(二)船舶发生事故沉没，船舶所有人或者经营人未及时采取措施清除船舶燃油、污染危害性货物以及其他污染物的。\n第六十六条 违反本条例的规定，有下列情形之一的，由海事管理机构处1万元以上5万元以下的罚款：\n(一)载运散装液体污染危害性货物的船舶和1万总吨以上的其他船舶，其经营人未按照规定签订污染清除作业协议的；\n(二)污染清除作业单位不符合国家有关技术规范从事污染清除作业的。\n第六十七条 违反本条例的规定，发生船舶污染事故，船舶、有关作业单位未立即启动应急预案的，对船舶、有关作业单位，由海事管理机构处2万元以上10万元以下的罚款；对直接负责的主管人员和其他直接责任人员，由海事管理机构处1万元以上2万元以下的罚款。直接负责的主管人员和其他直接责任人员属于船员的，并处给予暂扣适任证书或者其他有关证件1个月至3个月的处罚。\n第六十八条 违反本条例的规定，发生船舶污染事故，船舶、有关作业单位迟报、漏报事故的，对船舶、有关作业单位，由海事管理机构处5万元以上25万元以下的罚款；对直接负责的主管人员和其他直接责任人员，由海事管理机构处1万元以上5万元以下的罚款。直接负责的主管人员和其他直接责任人员属于船员的，并处给予暂扣适任证书或者其他有关证件3个月至6个月的处罚。瞒报、谎报事故的，对船舶、有关作业单位，由海事管理机构处25万元以上50万元以下的罚款；对直接负责的主管人员和其他直接责任人员，由海事管理机构处5万元以上10万元以下的罚款。直接负责的主管人员和其他直接责任人员属于船员的，并处给予吊销适任证书或者其他有关证件的处罚。\n第六十九条 违反本条例的规定，未按照国家规定的标准使用消油剂的，由海事管理机构对船舶或者使用单位处1万元以上5万元以下的罚款。\n第七十条 违反本条例的规定，船舶污染事故的当事人和其他有关人员，未如实向组织事故调查处理的机关或者海事管理机构反映情况和提供资料，伪造、隐匿、毁灭证据或者以其他方式妨碍调查取证的，由海事管理机构处1万元以上5万元以下的罚款。\n第七十一条 违反本条例的规定，船舶所有人有下列情形之一的，由海事管理机构责令改正，可以处5万元以下的罚款；拒不改正的，处5万元以上25万元以下的罚款：\n(一)在中华人民共和国管辖海域内航行的船舶，其所有人未按照规定投保船舶油污损害民事责任保险或者取得相应的财务担保的；\n(二)船舶所有人投保船舶油污损害民事责任保险或者取得的财务担保的额度低于《中华人民共和国海商法》、中华人民共和国缔结或者参加的有关国际条约规定的油污赔偿限额的。\n第七十二条 违反本条例的规定，在中华人民共和国管辖水域接收海上运输的持久性油类物质货物的货物所有人或者代理人，未按照规定缴纳船舶油污损害赔偿基金的，由海事管理机构责令改正；拒不改正的，可以停止其接收的持久性油类物质货物在中华人民共和国管辖水域进行装卸、过驳作业。\n货物所有人或者代理人逾期未缴纳船舶油污损害赔偿基金的，应当自应缴之日起按日加缴未缴额的万分之五的滞纳金。","level":1},{"name":"第九章 附则","text":"第七十三条 中华人民共和国缔结或者参加的国际条约对防治船舶及其有关作业活动污染海洋环境有规定的，适用国际条约的规定。但是，中华人民共和国声明保留的条款除外。\n第七十四条 县级以上人民政府渔业主管部门负责渔港水域内非军事船舶和渔港水域外渔业船舶污染海洋环境的监督管理，负责保护渔业水域生态环境工作，负责调查处理《中华人民共和国海洋环境保护法》第五条第四款规定的渔业污染事故。\n第七十五条 军队环境保护部门负责军事船舶污染海洋环境的监督管理及污染事故的调查处理。\n第七十六条 本条例自2010年3月1日起施行。1983年12月29日国务院发布的《中华人民共和国防止船舶污染海域管理条例》同时废止。","level":1}]},{"id":"n0382","sections":[{"name":"","text":"公共文化体育设施条例\n(2003年6月18日国务院第12次常务会议通过 2003年6月26日中华人民共和国国务院令第382号公布 自2003年8月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了促进公共文化体育设施的建设，加强对公共文化体育设施的管理和保护，充分发挥公共文化体育设施的功能，繁荣文化体育事业，满足人民群众开展文化体育活动的基本需求，制定本条例。\n第二条 本条例所称公共文化体育设施，是指由各级人民政府举办或者社会力量举办的，向公众开放用于开展文化体育活动的公益性的图书馆、博物馆、纪念馆、美术馆、文化馆(站)、体育场(馆)、青少年宫、工人文化宫等的建筑物、场地和设备。\n本条例所称公共文化体育设施管理单位，是指负责公共文化体育设施的维护，为公众开展文化体育活动提供服务的社会公共文化体育机构。\n第三条 公共文化体育设施管理单位必须坚持为人民服务、为社会主义服务的方向，充分利用公共文化体育设施，传播有益于提高民族素质、有益于经济发展和社会进步的科学技术和文化知识，开展文明、健康的文化体育活动。\n任何单位和个人不得利用公共文化体育设施从事危害公共利益的活动。\n第四条 国家有计划地建设公共文化体育设施。对少数民族地区、边远贫困地区和农村地区的公共文化体育设施的建设予以扶持。\n第五条 各级人民政府举办的公共文化体育设施的建设、维修、管理资金，应当列入本级人民政府基本建设投资计划和财政预算。\n第六条 国家鼓励企业、事业单位、社会团体和个人等社会力量举办公共文化体育设施。\n国家鼓励通过自愿捐赠等方式建立公共文化体育设施社会基金，并鼓励依法向人民政府、社会公益性机构或者公共文化体育设施管理单位捐赠财产。捐赠人可以按照税法的有关规定享受优惠。\n国家鼓励机关、学校等单位内部的文化体育设施向公众开放。\n第七条 国务院文化行政主管部门、体育行政主管部门依据国务院规定的职责负责全国的公共文化体育设施的监督管理。\n县级以上地方人民政府文化行政主管部门、体育行政主管部门依据本级人民政府规定的职责，负责本行政区域内的公共文化体育设施的监督管理。\n第八条 对在公共文化体育设施的建设、管理和保护工作中做出突出贡献的单位和个人，由县级以上地方人民政府或者有关部门给予奖励。","level":1},{"name":"第二章 规划和建设","text":"第九条 国务院发展和改革行政主管部门应当会同国务院文化行政主管部门、体育行政主管部门，将全国公共文化体育设施的建设纳入国民经济和社会发展计划。\n县级以上地方人民政府应当将本行政区域内的公共文化体育设施的建设纳入当地国民经济和社会发展计划。\n第十条 公共文化体育设施的数量、种类、规模以及布局，应当根据国民经济和社会发展水平、人口结构、环境条件以及文化体育事业发展的需要，统筹兼顾，优化配置，并符合国家关于城乡公共文化体育设施用地定额指标的规定。\n公共文化体育设施用地定额指标，由国务院土地行政主管部门、建设行政主管部门分别会同国务院文化行政主管部门、体育行政主管部门制定。\n第十一条 公共文化体育设施的建设选址，应当符合人口集中、交通便利的原则。\n第十二条 公共文化体育设施的设计，应当符合实用、安全、科学、美观等要求，并采取无障碍措施，方便残疾人使用。具体设计规范由国务院建设行政主管部门会同国务院文化行政主管部门、体育行政主管部门制定。\n第十三条 建设公共文化体育设施使用国有土地的，经依法批准可以以划拨方式取得。\n第十四条 公共文化体育设施的建设预留地，由县级以上地方人民政府土地行政主管部门、城乡规划行政主管部门按照国家有关用地定额指标，纳入土地利用总体规划和城乡规划，并依照法定程序审批。任何单位或者个人不得侵占公共文化体育设施建设预留地或者改变其用途。\n因特殊情况需要调整公共文化体育设施建设预留地的，应当依法调整城乡规划，并依照前款规定重新确定建设预留地。重新确定的公共文化体育设施建设预留地不得少于原有面积。\n第十五条 新建、改建、扩建居民住宅区，应当按照国家有关规定规划和建设相应的文化体育设施。\n居民住宅区配套建设的文化体育设施，应当与居民住宅区的主体工程同时设计、同时施工、同时投入使用。任何单位或者个人不得擅自改变文化体育设施的建设项目和功能，不得缩小其建设规模和降低其用地指标。","level":1},{"name":"第三章 使用和服务","text":"第十六条 公共文化体育设施管理单位应当完善服务条件，建立、健全服务规范，开展与公共文化体育设施功能、特点相适应的服务，保障公共文化体育设施用于开展文明、健康的文化体育活动。\n第十七条 公共文化体育设施应当根据其功能、特点向公众开放，开放时间应当与当地公众的工作时间、学习时间适当错开。\n公共文化体育设施的开放时间，不得少于省、自治区、直辖市规定的最低时限。国家法定节假日和学校寒暑假期间，应当适当延长开放时间。\n学校寒暑假期间，公共文化体育设施管理单位应当增设适合学生特点的文化体育活动。\n第十八条 公共文化体育设施管理单位应当向公众公示其服务内容和开放时间。公共文化体育设施因维修等原因需要暂时停止开放的，应当提前7日向公众公示。\n第十九条 公共文化体育设施管理单位应当在醒目位置标明设施的使用方法和注意事项。\n第二十条 公共文化体育设施管理单位提供服务可以适当收取费用，收费项目和标准应当经县级以上人民政府有关部门批准。\n第二十一条 需要收取费用的公共文化体育设施管理单位，应当根据设施的功能、特点对学生、老年人、残疾人等免费或者优惠开放，具体办法由省、自治区、直辖市制定。\n第二十二条 公共文化设施管理单位可以将设施出租用于举办文物展览、美术展览、艺术培训等文化活动。\n公共体育设施管理单位不得将设施的主体部分用于非体育活动。但是，因举办公益性活动或者大型文化活动等特殊情况临时出租的除外。临时出租时间一般不得超过10日；租用期满，租用者应当恢复原状，不得影响该设施的功能、用途。\n第二十三条 公众在使用公共文化体育设施时，应当遵守公共秩序，爱护公共文化体育设施。任何单位或者个人不得损坏公共文化体育设施。","level":1},{"name":"第四章 管理和保护","text":"第二十四条 公共文化体育设施管理单位应当将公共文化体育设施的名称、地址、服务项目等内容报所在地县级人民政府文化行政主管部门、体育行政主管部门备案。\n县级人民政府文化行政主管部门、体育行政主管部门应当向公众公布公共文化体育设施名录。\n第二十五条 公共文化体育设施管理单位应当建立、健全安全管理制度，依法配备安全保护设施、人员，保证公共文化体育设施的完好，确保公众安全。\n公共体育设施内设置的专业性强、技术要求高的体育项目，应当符合国家规定的安全服务技术要求。\n第二十六条 公共文化体育设施管理单位的各项收入，应当用于公共文化体育设施的维护、管理和事业发展，不得挪作他用。\n文化行政主管部门、体育行政主管部门、财政部门和其他有关部门，应当依法加强对公共文化体育设施管理单位收支的监督管理。\n第二十七条 因城乡建设确需拆除公共文化体育设施或者改变其功能、用途的，有关地方人民政府在作出决定前，应当组织专家论证，并征得上一级人民政府文化行政主管部门、体育行政主管部门同意，报上一级人民政府批准。\n涉及大型公共文化体育设施的，上一级人民政府在批准前，应当举行听证会，听取公众意见。\n经批准拆除公共文化体育设施或者改变其功能、用途的，应当依照国家有关法律、行政法规的规定择地重建。重新建设的公共文化体育设施，应当符合规划要求，一般不得小于原有规模。迁建工作应当坚持先建设后拆除或者建设拆除同时进行的原则。迁建所需费用由造成迁建的单位承担。","level":1},{"name":"第五章 法律责任","text":"第二十八条 文化、体育、城乡规划、建设、土地等有关行政主管部门及其工作人员，不依法履行职责或者发现违法行为不予依法查处的，对负有责任的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。\n第二十九条 侵占公共文化体育设施建设预留地或者改变其用途的，由土地行政主管部门、城乡规划行政主管部门依据各自职责责令限期改正；逾期不改正的，由作出决定的机关依法申请人民法院强制执行。\n第三十条 公共文化体育设施管理单位有下列行为之一的，由文化行政主管部门、体育行政主管部门依据各自职责责令限期改正；造成严重后果的，对负有责任的主管人员和其他直接责任人员，依法给予行政处分：\n(一)未按照规定的最低时限对公众开放的；\n(二)未公示其服务项目、开放时间等事项的；\n(三)未在醒目位置标明设施的使用方法或者注意事项的；\n(四)未建立、健全公共文化体育设施的安全管理制度的；\n(五)未将公共文化体育设施的名称、地址、服务项目等内容报文化行政主管部门、体育行政主管部门备案的。\n第三十一条 公共文化体育设施管理单位，有下列行为之一的，由文化行政主管部门、体育行政主管部门依据各自职责责令限期改正，没收违法所得，违法所得5000元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得5000元以下的，可以处1万元以下的罚款；对负有责任的主管人员和其他直接责任人员，依法给予行政处分：\n(一)开展与公共文化体育设施功能、用途不相适应的服务活动的；\n(二)违反本条例规定出租公共文化体育设施的。\n第三十二条 公共文化体育设施管理单位及其工作人员违反本条例规定，挪用公共文化体育设施管理单位的各项收入或者有条件维护而不履行维护义务的，由文化行政主管部门、体育行政主管部门依据各自职责责令限期改正；对负有责任的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第三十三条 国家机关、学校等单位内部的文化体育设施向公众开放的，由国务院文化行政主管部门、体育行政主管部门会同有关部门依据本条例的原则另行制定管理办法。\n第三十四条 本条例自2003年8月1日起施行。","level":1}]},{"id":"n0383","sections":[{"name":"","text":"放射性物品运输安全管理条例\n(2009年9月7日国务院第80次常务会议通过 2009年9月14日中华人民共和国国务院令第562号公布 自2010年1月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了加强对放射性物品运输的安全管理，保障人体健康，保护环境，促进核能、核技术的开发与和平利用，根据《中华人民共和国放射性污染防治法》，制定本条例。\n第二条 放射性物品的运输和放射性物品运输容器的设计、制造等活动，适用本条例。\n本条例所称放射性物品，是指含有放射性核素，并且其活度和比活度均高于国家规定的豁免值的物品。\n第三条 根据放射性物品的特性及其对人体健康和环境的潜在危害程度，将放射性物品分为一类、二类和三类。\n一类放射性物品，是指Ⅰ类放射源、高水平放射性废物、乏燃料等释放到环境后对人体健康和环境产生重大辐射影响的放射性物品。\n二类放射性物品，是指Ⅱ类和Ⅲ类放射源、中等水平放射性废物等释放到环境后对人体健康和环境产生一般辐射影响的放射性物品。\n三类放射性物品，是指Ⅳ类和Ⅴ类放射源、低水平放射性废物、放射性药品等释放到环境后对人体健康和环境产生较小辐射影响的放射性物品。\n放射性物品的具体分类和名录，由国务院核安全监管部门会同国务院公安、卫生、海关、交通运输、铁路、民航、核工业行业主管部门制定。\n第四条 国务院核安全监管部门对放射性物品运输的核与辐射安全实施监督管理。\n国务院公安、交通运输、铁路、民航等有关主管部门依照本条例规定和各自的职责，负责放射性物品运输安全的有关监督管理工作。\n县级以上地方人民政府环境保护主管部门和公安、交通运输等有关主管部门，依照本条例规定和各自的职责，负责本行政区域放射性物品运输安全的有关监督管理工作。\n第五条 运输放射性物品，应当使用专用的放射性物品运输包装容器(以下简称运输容器)。\n放射性物品的运输和放射性物品运输容器的设计、制造，应当符合国家放射性物品运输安全标准。\n国家放射性物品运输安全标准，由国务院核安全监管部门制定，由国务院核安全监管部门和国务院标准化主管部门联合发布。国务院核安全监管部门制定国家放射性物品运输安全标准，应当征求国务院公安、卫生、交通运输、铁路、民航、核工业行业主管部门的意见。\n第六条 放射性物品运输容器的设计、制造单位应当建立健全责任制度，加强质量管理，并对所从事的放射性物品运输容器的设计、制造活动负责。\n放射性物品的托运人(以下简称托运人)应当制定核与辐射事故应急方案，在放射性物品运输中采取有效的辐射防护和安全保卫措施，并对放射性物品运输中的核与辐射安全负责。\n第七条 任何单位和个人对违反本条例规定的行为，有权向国务院核安全监管部门或者其他依法履行放射性物品运输安全监督管理职责的部门举报。\n接到举报的部门应当依法调查处理，并为举报人保密。","level":1},{"name":"第二章 放射性物品运输容器的设计","text":"第八条 放射性物品运输容器设计单位应当建立健全和有效实施质量保证体系，按照国家放射性物品运输安全标准进行设计，并通过试验验证或者分析论证等方式，对设计的放射性物品运输容器的安全性能进行评价。\n第九条 放射性物品运输容器设计单位应当建立健全档案制度，按照质量保证体系的要求，如实记录放射性物品运输容器的设计和安全性能评价过程。\n进行一类放射性物品运输容器设计，应当编制设计安全评价报告书；进行二类放射性物品运输容器设计，应当编制设计安全评价报告表。\n第十条 一类放射性物品运输容器的设计，应当在首次用于制造前报国务院核安全监管部门审查批准。\n申请批准一类放射性物品运输容器的设计，设计单位应当向国务院核安全监管部门提出书面申请，并提交下列材料：\n(一)设计总图及其设计说明书；\n(二)设计安全评价报告书；\n(三)质量保证大纲。\n第十一条 国务院核安全监管部门应当自受理申请之日起45个工作日内完成审查，对符合国家放射性物品运输安全标准的，颁发一类放射性物品运输容器设计批准书，并公告批准文号；对不符合国家放射性物品运输安全标准的，书面通知申请单位并说明理由。\n第十二条 设计单位修改已批准的一类放射性物品运输容器设计中有关安全内容的，应当按照原申请程序向国务院核安全监管部门重新申请领取一类放射性物品运输容器设计批准书。\n第十三条 二类放射性物品运输容器的设计，设计单位应当在首次用于制造前，将设计总图及其设计说明书、设计安全评价报告表报国务院核安全监管部门备案。\n第十四条 三类放射性物品运输容器的设计，设计单位应当编制设计符合国家放射性物品运输安全标准的证明文件并存档备查。","level":1},{"name":"第三章 放射性物品运输容器的制造与使用","text":"第十五条 放射性物品运输容器制造单位，应当按照设计要求和国家放射性物品运输安全标准，对制造的放射性物品运输容器进行质量检验，编制质量检验报告。\n未经质量检验或者经检验不合格的放射性物品运输容器，不得交付使用。\n第十六条 从事一类放射性物品运输容器制造活动的单位，应当具备下列条件：\n(一)有与所从事的制造活动相适应的专业技术人员；\n(二)有与所从事的制造活动相适应的生产条件和检测手段；\n(三)有健全的管理制度和完善的质量保证体系。\n第十七条 从事一类放射性物品运输容器制造活动的单位，应当申请领取一类放射性物品运输容器制造许可证(以下简称制造许可证)。\n申请领取制造许可证的单位，应当向国务院核安全监管部门提出书面申请，并提交其符合本条例第十六条规定条件的证明材料和申请制造的运输容器型号。\n禁止无制造许可证或者超出制造许可证规定的范围从事一类放射性物品运输容器的制造活动。\n第十八条 国务院核安全监管部门应当自受理申请之日起45个工作日内完成审查，对符合条件的，颁发制造许可证，并予以公告；对不符合条件的，书面通知申请单位并说明理由。\n第十九条 制造许可证应当载明下列内容：\n(一)制造单位名称、住所和法定代表人；\n(二)许可制造的运输容器的型号；\n(三)有效期限；\n(四)发证机关、发证日期和证书编号。\n第二十条 一类放射性物品运输容器制造单位变更单位名称、住所或者法定代表人的，应当自工商变更登记之日起20日内，向国务院核安全监管部门办理制造许可证变更手续。\n一类放射性物品运输容器制造单位变更制造的运输容器型号的，应当按照原申请程序向国务院核安全监管部门重新申请领取制造许可证。\n第二十一条 制造许可证有效期为5年。\n制造许可证有效期届满，需要延续的，一类放射性物品运输容器制造单位应当于制造许可证有效期届满6个月前，向国务院核安全监管部门提出延续申请。\n国务院核安全监管部门应当在制造许可证有效期届满前作出是否准予延续的决定。\n第二十二条 从事二类放射性物品运输容器制造活动的单位，应当在首次制造活动开始30日前，将其具备与所从事的制造活动相适应的专业技术人员、生产条件、检测手段，以及具有健全的管理制度和完善的质量保证体系的证明材料，报国务院核安全监管部门备案。\n第二十三条 一类、二类放射性物品运输容器制造单位，应当按照国务院核安全监管部门制定的编码规则，对其制造的一类、二类放射性物品运输容器统一编码，并于每年1月31日前将上一年度的运输容器编码清单报国务院核安全监管部门备案。\n第二十四条 从事三类放射性物品运输容器制造活动的单位，应当于每年1月31日前将上一年度制造的运输容器的型号和数量报国务院核安全监管部门备案。\n第二十五条 放射性物品运输容器使用单位应当对其使用的放射性物品运输容器定期进行保养和维护，并建立保养和维护档案；放射性物品运输容器达到设计使用年限，或者发现放射性物品运输容器存在安全隐患的，应当停止使用，进行处理。\n一类放射性物品运输容器使用单位还应当对其使用的一类放射性物品运输容器每两年进行一次安全性能评价，并将评价结果报国务院核安全监管部门备案。\n第二十六条 使用境外单位制造的一类放射性物品运输容器的，应当在首次使用前报国务院核安全监管部门审查批准。\n申请使用境外单位制造的一类放射性物品运输容器的单位，应当向国务院核安全监管部门提出书面申请，并提交下列材料：\n(一)设计单位所在国核安全监管部门颁发的设计批准文件的复印件；\n(二)设计安全评价报告书；\n(三)制造单位相关业绩的证明材料；\n(四)质量合格证明；\n(五)符合中华人民共和国法律、行政法规规定，以及国家放射性物品运输安全标准或者经国务院核安全监管部门认可的标准的说明材料。\n国务院核安全监管部门应当自受理申请之日起45个工作日内完成审查，对符合国家放射性物品运输安全标准的，颁发使用批准书；对不符合国家放射性物品运输安全标准的，书面通知申请单位并说明理由。\n第二十七条 使用境外单位制造的二类放射性物品运输容器的，应当在首次使用前将运输容器质量合格证明和符合中华人民共和国法律、行政法规规定，以及国家放射性物品运输安全标准或者经国务院核安全监管部门认可的标准的说明材料，报国务院核安全监管部门备案。\n第二十八条 国务院核安全监管部门办理使用境外单位制造的一类、二类放射性物品运输容器审查批准和备案手续，应当同时为运输容器确定编码。","level":1},{"name":"第四章 放射性物品的运输","text":"第二十九条 托运放射性物品的，托运人应当持有生产、销售、使用或者处置放射性物品的有效证明，使用与所托运的放射性物品类别相适应的运输容器进行包装，配备必要的辐射监测设备、防护用品和防盗、防破坏设备，并编制运输说明书、核与辐射事故应急响应指南、装卸作业方法、安全防护指南。\n运输说明书应当包括放射性物品的品名、数量、物理化学形态、危害风险等内容。\n第三十条 托运一类放射性物品的，托运人应当委托有资质的辐射监测机构对其表面污染和辐射水平实施监测，辐射监测机构应当出具辐射监测报告。\n托运二类、三类放射性物品的，托运人应当对其表面污染和辐射水平实施监测，并编制辐射监测报告。\n监测结果不符合国家放射性物品运输安全标准的，不得托运。\n第三十一条 承运放射性物品应当取得国家规定的运输资质。承运人的资质管理，依照有关法律、行政法规和国务院交通运输、铁路、民航、邮政主管部门的规定执行。\n第三十二条 托运人和承运人应当对直接从事放射性物品运输的工作人员进行运输安全和应急响应知识的培训，并进行考核；考核不合格的，不得从事相关工作。\n托运人和承运人应当按照国家放射性物品运输安全标准和国家有关规定，在放射性物品运输容器和运输工具上设置警示标志。\n国家利用卫星定位系统对一类、二类放射性物品运输工具的运输过程实行在线监控。具体办法由国务院核安全监管部门会同国务院有关部门制定。\n第三十三条 托运人和承运人应当按照国家职业病防治的有关规定，对直接从事放射性物品运输的工作人员进行个人剂量监测，建立个人剂量档案和职业健康监护档案。\n第三十四条 托运人应当向承运人提交运输说明书、辐射监测报告、核与辐射事故应急响应指南、装卸作业方法、安全防护指南，承运人应当查验、收存。托运人提交文件不齐全的，承运人不得承运。\n第三十五条 托运一类放射性物品的，托运人应当编制放射性物品运输的核与辐射安全分析报告书，报国务院核安全监管部门审查批准。\n放射性物品运输的核与辐射安全分析报告书应当包括放射性物品的品名、数量、运输容器型号、运输方式、辐射防护措施、应急措施等内容。\n国务院核安全监管部门应当自受理申请之日起45个工作日内完成审查，对符合国家放射性物品运输安全标准的，颁发核与辐射安全分析报告批准书；对不符合国家放射性物品运输安全标准的，书面通知申请单位并说明理由。\n第三十六条 放射性物品运输的核与辐射安全分析报告批准书应当载明下列主要内容：\n(一)托运人的名称、地址、法定代表人；\n(二)运输放射性物品的品名、数量；\n(三)运输放射性物品的运输容器型号和运输方式；\n(四)批准日期和有效期限。\n第三十七条 一类放射性物品启运前，托运人应当将放射性物品运输的核与辐射安全分析报告批准书、辐射监测报告，报启运地的省、自治区、直辖市人民政府环境保护主管部门备案。\n收到备案材料的环境保护主管部门应当及时将有关情况通报放射性物品运输的途经地和抵达地的省、自治区、直辖市人民政府环境保护主管部门。\n第三十八条 通过道路运输放射性物品的，应当经公安机关批准，按照指定的时间、路线、速度行驶，并悬挂警示标志，配备押运人员，使放射性物品处于押运人员的监管之下。\n通过道路运输核反应堆乏燃料的，托运人应当报国务院公安部门批准。通过道路运输其他放射性物品的，托运人应当报启运地县级以上人民政府公安机关批准。具体办法由国务院公安部门商国务院核安全监管部门制定。\n第三十九条 通过水路运输放射性物品的，按照水路危险货物运输的法律、行政法规和规章的有关规定执行。\n通过铁路、航空运输放射性物品的，按照国务院铁路、民航主管部门的有关规定执行。\n禁止邮寄一类、二类放射性物品。邮寄三类放射性物品的，按照国务院邮政管理部门的有关规定执行。\n第四十条 生产、销售、使用或者处置放射性物品的单位，可以依照《中华人民共和国道路运输条例》的规定，向设区的市级人民政府道路运输管理机构申请非营业性道路危险货物运输资质，运输本单位的放射性物品，并承担本条例规定的托运人和承运人的义务。\n申请放射性物品非营业性道路危险货物运输资质的单位，应当具备下列条件：\n(一)持有生产、销售、使用或者处置放射性物品的有效证明；\n(二)有符合本条例规定要求的放射性物品运输容器；\n(三)有具备辐射防护与安全防护知识的专业技术人员和经考试合格的驾驶人员；\n(四)有符合放射性物品运输安全防护要求，并经检测合格的运输工具、设施和设备；\n(五)配备必要的防护用品和依法经定期检定合格的监测仪器；\n(六)有运输安全和辐射防护管理规章制度以及核与辐射事故应急措施。\n放射性物品非营业性道路危险货物运输资质的具体条件，由国务院交通运输主管部门会同国务院核安全监管部门制定。\n第四十一条 一类放射性物品从境外运抵中华人民共和国境内，或者途经中华人民共和国境内运输的，托运人应当编制放射性物品运输的核与辐射安全分析报告书，报国务院核安全监管部门审查批准。审查批准程序依照本条例第三十五条第三款的规定执行。\n二类、三类放射性物品从境外运抵中华人民共和国境内，或者途经中华人民共和国境内运输的，托运人应当编制放射性物品运输的辐射监测报告，报国务院核安全监管部门备案。\n托运人、承运人或者其代理人向海关办理有关手续，应当提交国务院核安全监管部门颁发的放射性物品运输的核与辐射安全分析报告批准书或者放射性物品运输的辐射监测报告备案证明。\n第四十二条 县级以上人民政府组织编制的突发环境事件应急预案，应当包括放射性物品运输中可能发生的核与辐射事故应急响应的内容。\n第四十三条 放射性物品运输中发生核与辐射事故的，承运人、托运人应当按照核与辐射事故应急响应指南的要求，做好事故应急工作，并立即报告事故发生地的县级以上人民政府环境保护主管部门。接到报告的环境保护主管部门应当立即派人赶赴现场，进行现场调查，采取有效措施控制事故影响，并及时向本级人民政府报告，通报同级公安、卫生、交通运输等有关主管部门。\n接到报告的县级以上人民政府及其有关主管部门应当按照应急预案做好应急工作，并按照国家突发事件分级报告的规定及时上报核与辐射事故信息。\n核反应堆乏燃料运输的核事故应急准备与响应，还应当遵守国家核应急的有关规定。","level":1},{"name":"第五章 监督检查","text":"第四十四条 国务院核安全监管部门和其他依法履行放射性物品运输安全监督管理职责的部门，应当依据各自职责对放射性物品运输安全实施监督检查。\n国务院核安全监管部门应当将其已批准或者备案的一类、二类、三类放射性物品运输容器的设计、制造情况和放射性物品运输情况通报设计、制造单位所在地和运输途经地的省、自治区、直辖市人民政府环境保护主管部门。省、自治区、直辖市人民政府环境保护主管部门应当加强对本行政区域放射性物品运输安全的监督检查和监督性监测。\n被检查单位应当予以配合，如实反映情况，提供必要的资料，不得拒绝和阻碍。\n第四十五条 国务院核安全监管部门和省、自治区、直辖市人民政府环境保护主管部门以及其他依法履行放射性物品运输安全监督管理职责的部门进行监督检查，监督检查人员不得少于2人，并应当出示有效的行政执法证件。\n国务院核安全监管部门和省、自治区、直辖市人民政府环境保护主管部门以及其他依法履行放射性物品运输安全监督管理职责的部门的工作人员，对监督检查中知悉的商业秘密负有保密义务。\n第四十六条 监督检查中发现经批准的一类放射性物品运输容器设计确有重大设计安全缺陷的，由国务院核安全监管部门责令停止该型号运输容器的制造或者使用，撤销一类放射性物品运输容器设计批准书。\n第四十七条 监督检查中发现放射性物品运输活动有不符合国家放射性物品运输安全标准情形的，或者一类放射性物品运输容器制造单位有不符合制造许可证规定条件情形的，应当责令限期整改；发现放射性物品运输活动可能对人体健康和环境造成核与辐射危害的，应当责令停止运输。\n第四十八条 国务院核安全监管部门和省、自治区、直辖市人民政府环境保护主管部门以及其他依法履行放射性物品运输安全监督管理职责的部门，对放射性物品运输活动实施监测，不得收取监测费用。\n国务院核安全监管部门和省、自治区、直辖市人民政府环境保护主管部门以及其他依法履行放射性物品运输安全监督管理职责的部门，应当加强对监督管理人员辐射防护与安全防护知识的培训。","level":1},{"name":"第六章 法律责任","text":"第四十九条 国务院核安全监管部门和省、自治区、直辖市人民政府环境保护主管部门或者其他依法履行放射性物品运输安全监督管理职责的部门有下列行为之一的，对直接负责的主管人员和其他直接责任人员依法给予处分；直接负责的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任：\n(一)未依照本条例规定作出行政许可或者办理批准文件的；\n(二)发现违反本条例规定的行为不予查处，或者接到举报不依法处理的；\n(三)未依法履行放射性物品运输核与辐射事故应急职责的；\n(四)对放射性物品运输活动实施监测收取监测费用的；\n(五)其他不依法履行监督管理职责的行为。\n第五十条 放射性物品运输容器设计、制造单位有下列行为之一的，由国务院核安全监管部门责令停止违法行为，处50万元以上100万元以下的罚款；有违法所得的，没收违法所得：\n(一)将未取得设计批准书的一类放射性物品运输容器设计用于制造的；\n(二)修改已批准的一类放射性物品运输容器设计中有关安全内容，未重新取得设计批准书即用于制造的。\n第五十一条 放射性物品运输容器设计、制造单位有下列行为之一的，由国务院核安全监管部门责令停止违法行为，处5万元以上10万元以下的罚款；有违法所得的，没收违法所得：\n(一)将不符合国家放射性物品运输安全标准的二类、三类放射性物品运输容器设计用于制造的；\n(二)将未备案的二类放射性物品运输容器设计用于制造的。\n第五十二条 放射性物品运输容器设计单位有下列行为之一的，由国务院核安全监管部门责令限期改正；逾期不改正的，处1万元以上5万元以下的罚款：\n(一)未对二类、三类放射性物品运输容器的设计进行安全性能评价的；\n(二)未如实记录二类、三类放射性物品运输容器设计和安全性能评价过程的；\n(三)未编制三类放射性物品运输容器设计符合国家放射性物品运输安全标准的证明文件并存档备查的。\n第五十三条 放射性物品运输容器制造单位有下列行为之一的，由国务院核安全监管部门责令停止违法行为，处50万元以上100万元以下的罚款；有违法所得的，没收违法所得：\n(一)未取得制造许可证从事一类放射性物品运输容器制造活动的；\n(二)制造许可证有效期届满，未按照规定办理延续手续，继续从事一类放射性物品运输容器制造活动的；\n(三)超出制造许可证规定的范围从事一类放射性物品运输容器制造活动的；\n(四)变更制造的一类放射性物品运输容器型号，未按照规定重新领取制造许可证的；\n(五)将未经质量检验或者经检验不合格的一类放射性物品运输容器交付使用的。\n有前款第(三)项、第(四)项和第(五)项行为之一，情节严重的，吊销制造许可证。\n第五十四条 一类放射性物品运输容器制造单位变更单位名称、住所或者法定代表人，未依法办理制造许可证变更手续的，由国务院核安全监管部门责令限期改正；逾期不改正的，处2万元的罚款。\n第五十五条 放射性物品运输容器制造单位有下列行为之一的，由国务院核安全监管部门责令停止违法行为，处5万元以上10万元以下的罚款；有违法所得的，没收违法所得：\n(一)在二类放射性物品运输容器首次制造活动开始前，未按照规定将有关证明材料报国务院核安全监管部门备案的；\n(二)将未经质量检验或者经检验不合格的二类、三类放射性物品运输容器交付使用的。\n第五十六条 放射性物品运输容器制造单位有下列行为之一的，由国务院核安全监管部门责令限期改正；逾期不改正的，处1万元以上5万元以下的罚款：\n(一)未按照规定对制造的一类、二类放射性物品运输容器统一编码的；\n(二)未按照规定将制造的一类、二类放射性物品运输容器编码清单报国务院核安全监管部门备案的；\n(三)未按照规定将制造的三类放射性物品运输容器的型号和数量报国务院核安全监管部门备案的。\n第五十七条 放射性物品运输容器使用单位未按照规定对使用的一类放射性物品运输容器进行安全性能评价，或者未将评价结果报国务院核安全监管部门备案的，由国务院核安全监管部门责令限期改正；逾期不改正的，处1万元以上5万元以下的罚款。\n第五十八条 未按照规定取得使用批准书使用境外单位制造的一类放射性物品运输容器的，由国务院核安全监管部门责令停止违法行为，处50万元以上100万元以下的罚款。\n未按照规定办理备案手续使用境外单位制造的二类放射性物品运输容器的，由国务院核安全监管部门责令停止违法行为，处5万元以上10万元以下的罚款。\n第五十九条 托运人未按照规定编制放射性物品运输说明书、核与辐射事故应急响应指南、装卸作业方法、安全防护指南的，由国务院核安全监管部门责令限期改正；逾期不改正的，处1万元以上5万元以下的罚款。\n托运人未按照规定将放射性物品运输的核与辐射安全分析报告批准书、辐射监测报告备案的，由启运地的省、自治区、直辖市人民政府环境保护主管部门责令限期改正；逾期不改正的，处1万元以上5万元以下的罚款。\n第六十条 托运人或者承运人在放射性物品运输活动中，有违反有关法律、行政法规关于危险货物运输管理规定行为的，由交通运输、铁路、民航等有关主管部门依法予以处罚。\n违反有关法律、行政法规规定邮寄放射性物品的，由公安机关和邮政管理部门依法予以处罚。在邮寄进境物品中发现放射性物品的，由海关依照有关法律、行政法规的规定处理。\n第六十一条 托运人未取得放射性物品运输的核与辐射安全分析报告批准书托运一类放射性物品的，由国务院核安全监管部门责令停止违法行为，处50万元以上100万元以下的罚款。\n第六十二条 通过道路运输放射性物品，有下列行为之一的，由公安机关责令限期改正，处2万元以上10万元以下的罚款；构成犯罪的，依法追究刑事责任：\n(一)未经公安机关批准通过道路运输放射性物品的；\n(二)运输车辆未按照指定的时间、路线、速度行驶或者未悬挂警示标志的；\n(三)未配备押运人员或者放射性物品脱离押运人员监管的。\n第六十三条 托运人有下列行为之一的，由启运地的省、自治区、直辖市人民政府环境保护主管部门责令停止违法行为，处5万元以上20万元以下的罚款：\n(一)未按照规定对托运的放射性物品表面污染和辐射水平实施监测的；\n(二)将经监测不符合国家放射性物品运输安全标准的放射性物品交付托运的；\n(三)出具虚假辐射监测报告的。\n第六十四条 未取得放射性物品运输的核与辐射安全分析报告批准书或者放射性物品运输的辐射监测报告备案证明，将境外的放射性物品运抵中华人民共和国境内，或者途经中华人民共和国境内运输的，由海关责令托运人退运该放射性物品，并依照海关法律、行政法规给予处罚；构成犯罪的，依法追究刑事责任。托运人不明的，由承运人承担退运该放射性物品的责任，或者承担该放射性物品的处置费用。\n第六十五条 违反本条例规定，在放射性物品运输中造成核与辐射事故的，由县级以上地方人民政府环境保护主管部门处以罚款，罚款数额按照核与辐射事故造成的直接损失的20%计算；构成犯罪的，依法追究刑事责任。\n托运人、承运人未按照核与辐射事故应急响应指南的要求，做好事故应急工作并报告事故的，由县级以上地方人民政府环境保护主管部门处5万元以上20万元以下的罚款。\n因核与辐射事故造成他人损害的，依法承担民事责任。\n第六十六条 拒绝、阻碍国务院核安全监管部门或者其他依法履行放射性物品运输安全监督管理职责的部门进行监督检查，或者在接受监督检查时弄虚作假的，由监督检查部门责令改正，处1万元以上2万元以下的罚款；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附则","text":"第六十七条 军用放射性物品运输安全的监督管理，依照《中华人民共和国放射性污染防治法》第六十条的规定执行。\n第六十八条 本条例自2010年1月1日起施行。","level":1}]},{"id":"n0384","sections":[{"name":"","text":"证券、期货投资咨询管理暂行办法\n(1997年11月30日国务院批准 1997年12月25日国务院证券委员会发布 自1998年4月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了加强对证券、期货投资咨询活动的管理，保障投资者的合法权益和社会公共利益，制定本办法。\n第二条 在中华人民共和国境内从事证券、期货投资咨询业务，必须遵守本办法。\n本办法所称证券、期货投资咨询，是指从事证券、期货投资咨询业务的机构及其投资咨询人员以下列形式为证券、期货投资人或者客户提供证券、期货投资分析、预测或者建议等直接或者间接有偿咨询服务的活动：\n(一)接受投资人或者客户委托，提供证券、期货投资咨询服务；\n(二)举办有关证券、期货投资咨询的讲座、报告会、分析会等；\n(三)在报刊上发表证券、期货投资咨询的文章、评论、报告，以及通过电台、电视台等公众传播媒体提供证券、期货投资咨询服务；\n(四)通过电话、传真、电脑网络等电信设备系统，提供证券、期货投资咨询服务；\n(五)中国证券监督管理委员会(以下简称中国证监会)认定的其他形式。\n第三条 从事证券、期货投资咨询业务，必须依照本办法的规定，取得中国证监会的业务许可。未经中国证监会许可，任何机构和个人均不得从事本办法第二条所列各种形式证券、期货投资咨询业务。\n证券经营机构、期货经纪机构及其工作人员从事超出本机构范围的证券、期货投资咨询业务，应当遵守本办法的规定。\n第四条 从事证券、期货投资咨询业务，必须遵守有关法律、法规、规章和中国证监会的有关规定，遵循客观、公正和诚实信用的原则。\n第五条 中国证监会及其授权的地方证券、期货监管部门(以下简称地方证管办(证监会))负责对证券、期货投资咨询业务的监督管理，并负责本办法的实施。","level":1},{"name":"第二章 证券、期货投资咨询机构","text":"第六条 申请证券、期货投资咨询从业资格的机构，应当具备下列条件：\n(一)分别从事证券或者期货投资咨询业务的机构，有5名以上取得证券、期货投资咨询从业资格的专职人员；同时从事证券和期货投资咨询业务的机构，有10名以上取得证券、期货投资咨询从业资格的专职人员；其高级管理人员中，至少有1名取得证券或者期货投资咨询从业资格；\n(二)有100万元人民币以上的注册资本；\n(三)有固定的业务场所和与业务相适应的通讯及其他信息传递设施；\n(四)有公司章程；\n(五)有健全的内部管理制度；\n(六)具备中国证监会要求的其他条件。\n第七条 证券经营机构、期货经纪机构应当符合本办法第六条规定的条件，方可申请从事超出本机构范围的证券、期货投资咨询业务。\n其他从事咨询业务的机构，符合本办法第六条规定的条件的，可以申请兼营证券、期货投资咨询业务。\n第八条 申请证券、期货投资咨询从业资格的机构，按照下列程序审批：\n(一)申请人向经中国证监会授权的所在地地方证管办(证监会)提出申请(所在地地方证管办(证监会)未经中国证监会授权的，申请人向中国证监会直接提出申请，下同)，地方证管办(证监会)经审核同意后，提出初审意见；\n(二)地方证管办(证监会)将审核同意的申请文件报送中国证监会，经中国证监会审批后，向申请人颁发业务许可证，并将批准文件抄送地方证管办(证监会)；\n(三)中国证监会将以公告形式向社会公布获得业务许可的申请人的情况。\n第九条 申请证券、期货投资咨询从业资格的机构，应当提交下列文件：\n(一)中国证监会统一印制的申请表；\n(二)公司章程；\n(三)企业法人营业执照；\n(四)机构高级管理人员和从事证券、期货投资咨询业务人员名单及其学历、工作经历和从业资格证书；\n(五)开展投资咨询业务的方式和内部管理规章制度；\n(六)业务场所使用证明文件、机构通讯地址、电话和传真机号码；\n(七)由注册会计师提供的验资报告；\n(八)中国证监会要求提供的其他文件。\n第十条 证券、期货投资咨询机构的业务方式、业务场所、主要负责人以及具有证券、期货投资咨询从业资格的业务人员发生变化的，应当自发生变化之日起5个工作日内，向地方证管办(证监会)提出变更报告，办理变更手续。\n第十一条 证券、期货投资咨询机构应当于每年1月1日至4月30日期间向地方证管办(证监会)申请办理年检。办理年检时，应当提交下列文件：\n(一)年检申请报告；\n(二)年度业务报告；\n(三)经注册会计师审计的财务会计报表。\n地方证管办(证监会)应当自收到前款所列文件之日起20个工作日内对年检申请提出审核意见；审核同意的，上报中国证监会审批。\n证券、期货投资咨询机构逾期未提交年检报告或者经审核未通过年检的，不得继续从事证券、期货投资咨询业务。","level":1},{"name":"第三章 证券、期货投资咨询人员","text":"第十二条 从事证券、期货投资咨询业务的人员，必须取得证券、期货投资咨询从业资格并加入一家有从业资格的证券、期货投资咨询机构后，方可从事证券、期货投资咨询业务。\n任何人未取得证券、期货投资咨询从业资格的，或者取得证券、期货投资咨询从业资格，但是未在证券、期货投资咨询机构工作的，不得从事证券、期货投资咨询业务。\n第十三条 证券、期货投资咨询人员申请取得证券、期货投资咨询从业资格，必须具备下列条件：\n(一)具有中华人民共和国国籍；\n(二)具有完全民事行为能力；\n(三)品行良好、正直诚实，具有良好的职业道德；\n(四)未受过刑事处罚或者与证券、期货业务有关的严重行政处罚；\n(五)具有大学本科以上学历；\n(六)证券投资咨询人员具有从事证券业务两年以上的经历，期货投资咨询人员具有从事期货业务两年以上的经历；\n(七)通过中国证监会统一组织的证券、期货从业人员资格考试；\n(八)中国证监会规定的其他条件。\n第十四条 证券、期货投资咨询人员申请取得证券、期货投资咨询从业资格，按照下列程序审批：\n(一)申请人向经中国证监会授权的所在地地方证管办(证监会)提出申请(所在地地方证管办(证监会)未经中国证监会授权的，申请人向中国证监会直接提出申请，下同)，地方证管办(证监会)经审核同意后，提出初审意见；\n(二)地方证管办(证监会)将审核同意的申请文件报送中国证监会，经中国证监会审批后，向申请人颁发资格证书，并将批准文件抄送地方证管办(证监会)。\n第十五条 证券、期货投资咨询人员申请取得证券、期货投资咨询从业资格，应当提交下列文件：\n(一)中国证监会统一印制的申请表；\n(二)身份证；\n(三)学历证书；\n(四)参加证券、期货从业人员资格考试的成绩单；\n(五)所在单位或者户口所在地街道办事处开具的以往行为说明材料；\n(六)中国证监会要求报送的其他材料。\n第十六条 取得证券、期货投资咨询从业资格的人员申请执业的，由所参加的证券、期货投资咨询机构向所在地地方证管办(证监会)提出申请，地方证管办(证监会)审核同意后，报中国证监会审批；准予执业的，由中国证监会颁发执业证书。\n第十七条 取得证券、期货投资咨询执业资格的人员，应当在所参加的证券、期货投资咨询机构年检时同时办理执业年检。取得证券、期货投资咨询从业资格，但是未在证券、期货投资咨询机构执业的，其从业资格自取得之日起满18个月后自动失效。\n第十八条 证券、期货投资咨询人员不得同时在两个或者两个以上的证券、期货投资咨询机构执业。","level":1},{"name":"第四章 证券、期货投资咨询业务管理","text":"第十九条 证券、期货投资咨询机构及其投资咨询人员，应当以行业公认的谨慎、诚实和勤勉尽责的态度，为投资人或者客户提供证券、期货投资咨询服务。\n第二十条 证券、期货投资咨询机构及其投资咨询人员，应当完整、客观、准确地运用有关信息、资料向投资人或者客户提供投资分析、预测和建议，不得断章取义地引用或者篡改有关信息、资料；引用有关信息、资料时，应当注明出处和著作权人。\n第二十一条 证券、期货投资咨询机构及其投资咨询人员，不得以虚假信息、市场传言或者内幕信息为依据向投资人或者客户提供投资分析、预测或建议。\n第二十二条 证券、期货投资咨询人员在报刊、电台、电视台或者其他传播媒体上发表投资咨询文章、报告或者意见时，必须注明所在证券、期货投资咨询机构的名称和个人真实姓名，并对投资风险作充分说明。证券、期货投资咨询机构向投资人或者客户提供的证券、期货投资咨询传真件必须注明机构名称、地址、联系电话和联系人姓名。\n第二十三条 证券、期货投资咨询机构与报刊、电台、电视台合办或者协办证券、期货投资咨询版面、节目或者与电信服务部门进行业务合作时，应当向地方证管办(证监会)备案，备案材料包括：合作内容、起止时间、版面安排或者节目时间段、项目负责人等，并加盖双方单位的印鉴。\n第二十四条 证券、期货投资咨询机构及其投资咨询人员，不得从事下列活动：\n(一)代理投资人从事证券、期货买卖；\n(二)向投资人承诺证券、期货投资收益；\n(三)与投资人约定分享投资收益或者分担投资损失；\n(四)为自己买卖股票及具有股票性质、功能的证券以及期货；\n(五)利用咨询服务与他人合谋操纵市场或者进行内幕交易；\n(六)法律、法规、规章所禁止的其他证券、期货欺诈行为。\n第二十五条 证券、期货投资咨询机构就同一问题向不同客户提供的投资分析、预测或者建议应当一致。\n具有自营业务的证券经营机构在从事超出本机构范围的证券投资咨询业务时，就同一问题向社会公众和其自营部门提供的咨询意见应当一致，不得为自营业务获利的需要误导社会公众。\n第二十六条 证券经营机构、期货经纪机构编发的供本机构内部使用的证券、期货信息简报、快讯、动态以及信息系统等，只能限于本机构范围内使用，不得通过任何途径向社会公众提供。\n经中国证监会批准的公开发行股票的公司的承销商或者上市推荐人及其所属证券投资咨询机构，不得在公众传播媒体上刊登其为客户撰写的投资价值分析报告。\n第二十七条 中国证监会和地方证管办(证监会)有权对证券、期货投资咨询机构和投资咨询人员的业务活动进行检查，被检查的证券、期货投资咨询机构及其投资咨询人员应当予以配合，不得干扰和阻碍。\n中国证监会和地方证管办(证监会)及其工作人员在业务检查过程中，对所涉及的商业秘密应当注意保护。\n第二十八条 证券、期货投资咨询机构应当将其向投资人或者社会公众提供的投资咨询资料，自提供之日起保存2年。\n第二十九条 地方证管办(证监会)根据投资人或者社会公众的投诉或者举报，有权要求证券、期货投资咨询机构及其投资咨询人员说明情况并提供相关资料。\n第三十条 任何单位和个人发现证券、期货投资咨询机构、投资咨询人员或其他机构和个人有违反本办法规定的行为时，可以向地方证管办(证监会)投诉和举报。\n第三十一条 地方证管办(证监会)对违反本办法的行为，应当进行立案调查并将调查结果报中国证监会备案。","level":1},{"name":"第五章 罚则","text":"第三十二条 未经中国证监会许可，擅自从事本办法第二条规定的证券、期货投资咨询业务的，由地方证管办(证监会)责令停止，并处没收违法所得和违法所得等值以下的罚款。\n第三十三条 证券、期货投资咨询机构有下列行为之一的，由地方证管办(证监会)处1万元以上，5万元以下的罚款；情节严重的，地方证管办(证监会)应当向中国证监会报告，由中国证监会作出暂停或者撤销其业务资格的处罚：\n(一)向证券监管部门报送的文件、资料有虚假陈述或者重大遗漏的；\n(二)未按照本办法规定履行报告和年检义务的；\n(三)未按照本办法规定履行对本机构有关情况发生变化的变更手续的；\n(四)本机构证券、期货投资咨询人员违反本办法规定，受到证券监管部门行政处罚的；\n(五)干扰、阻碍地方证管办(证监会)检查、调查，或者隐瞒、销毁证据的。\n第三十四条 证券、期货投资咨询机构违反本办法第十八条、第十九条、第二十条、第二十一条、第二十二条、第二十三条、第二十四条、第二十五条、第二十八条规定的，由地方证管办(证监会)单处或者并处警告、没收违法所得、1万元以上10万元以下罚款；情节严重的，地方证管办(证监会)应当向中国证监会报告，由中国证监会作出暂停或者撤销业务资格的处罚；构成犯罪的，依法追究刑事责任。\n第三十五条 证券经营机构、期货经纪机构违反本办法第二十六条规定的，由地方证管办(证监会)责令改正，并处以警告或者1万元以上5万元以下罚款。\n第三十六条 证券、期货投资咨询人员违反本办法第十八条、第十九条、第二十条、第二十一条、第二十二条、第二十四条的规定或者未按本办法规定向证券主管部门履行报告、年检义务的，由地方证管办(证监会)单处或者并处警告、没收违法所得、1万元以上3万元以下罚款；情节严重的，地方证管办(证监会)应当向中国证监会报告，由中国证监会作出暂停或者撤销其业务资格的处罚；构成犯罪的，依法追究刑事责任。\n第三十七条 中国证监会和地方证管办(证监会)的工作人员玩忽职守、滥用职权、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。","level":1},{"name":"第六章 附则","text":"第三十八条 本办法自1998年4月1日起施行。","level":1}]},{"id":"n0385","sections":[{"name":"","text":"中华人民共和国陆生野生动物保护实施条例\n(1992年2月12日国务院批准 1992年3月1日林业部发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2016年2月6日《国务院关于修改部分行政法规的决定》第二次修订)","level":0},{"name":"第一章 总则","text":"第一条 根据《中华人民共和国野生动物保护法》(以下简称《野生动物保护法》)的规定，制定本条例。\n第二条 本条例所称陆生野生动物，是指依法受保护的珍贵、濒危、有益的和有重要经济、科学研究价值的陆生野生动物(以下简称野生动物)；所称野生动物产品，是指陆生野生动物的任何部分及其衍生物。\n第三条 国务院林业行政主管部门主管全国陆生野生动物管理工作。\n省、自治区、直辖市人民政府林业行政主管部门主管本行政区域内陆生野生动物管理工作。自治州、县和市人民政府陆生野生动物管理工作的行政主管部门，由省、自治区、直辖市人民政府确定。\n第四条 县级以上各级人民政府有关主管部门应当鼓励、支持有关科研、教学单位开展野生动物科学研究工作。\n第五条 野生动物行政主管部门有权对《野生动物保护法》和本条例的实施情况进行监督检查，被检查的单位和个人应当给予配合。","level":1},{"name":"第二章 野生动物保护","text":"第六条 县级以上地方各级人民政府应当开展保护野生动物的宣传教育，可以确定适当时间为保护野生动物宣传月、爱鸟周等，提高公民保护野生动物的意识。\n第七条 国务院林业行政主管部门和省、自治区、直辖市人民政府林业行政主管部门，应当定期组织野生动物资源调查，建立资源档案，为制定野生动物资源保护发展方案、制定和调整国家和地方重点保护野生动物名录提供依据。\n野生动物资源普查每十年进行一次。\n第八条 县级以上各级人民政府野生动物行政主管部门，应当组织社会各方面力量，采取生物技术措施和工程技术措施，维护和改善野生动物生存环境，保护和发展野生动物资源。\n禁止任何单位和个人破坏国家和地方重点保护野生动物的生息繁衍场所和生存条件。\n第九条 任何单位和个人发现受伤、病弱、饥饿、受困、迷途的国家和地方重点保护野生动物时，应当及时报告当地野生动物行政主管部门，由其采取救护措施；也可以就近送具备救护条件的单位救护。救护单位应当立即报告野生动物行政主管部门，并按照国务院林业行政主管部门的规定办理。\n第十条 有关单位和个人对国家和地方重点保护野生动物可能造成的危害，应当采取防范措施。因保护国家和地方重点保护野生动物受到损失的，可以向当地人民政府野生动物行政主管部门提出补偿要求。经调查属实并确实需要补偿的，由当地人民政府按照省、自治区、直辖市人民政府的有关规定给予补偿。","level":1},{"name":"第三章 野生动物猎捕管理","text":"第十一条 禁止猎捕、杀害国家重点保护野生动物。\n有下列情形之一，需要猎捕国家重点保护野生动物的，必须申请特许猎捕证：\n(一)为进行野生动物科学考察、资源调查，必须猎捕的；\n(二)为驯养繁殖国家重点保护野生动物，必须从野外获取种源的；\n(三)为承担省级以上科学研究项目或者国家医药生产任务，必须从野外获取国家重点保护野生动物的；\n(四)为宣传、普及野生动物知识或者教学、展览的需要，必须从野外获取国家重点保护野生动物的；\n(五)因国事活动的需要，必须从野外获取国家重点保护野生动物的；\n(六)为调控国家重点保护野生动物种群数量和结构，经科学论证必须猎捕的；\n(七)因其他特殊情况，必须捕捉、猎捕国家重点保护野生动物的。\n第十二条 申请特许猎捕证的程序如下：\n(一)需要捕捉国家一级保护野生动物的，必须附具申请人所在地和捕捉地的省、自治区、直辖市人民政府林业行政主管部门签署的意见，向国务院林业行政主管部门申请特许猎捕证；\n(二)需要在本省、自治区、直辖市猎捕国家二级保护野生动物的，必须附具申请人所在地的县级人民政府野生动物行政主管部门签署的意见，向省、自治区、直辖市人民政府林业行政主管部门申请特许猎捕证；\n(三)需要跨省、自治区、直辖市猎捕国家二级保护野生动物的，必须附具申请人所在地的省、自治区、直辖市人民政府林业行政主管部门签署的意见，向猎捕地的省、自治区、直辖市人民政府林业行政主管部门申请特许猎捕证。\n动物园需要申请捕捉国家一级保护野生动物的，在向国务院林业行政主管部门申请特许猎捕证前，须经国务院建设行政主管部门审核同意；需要申请捕捉国家二级保护野生动物的，在向申请人所在地的省、自治区、直辖市人民政府林业行政主管部门申请特许猎捕证前，须经同级政府建设行政主管部门审核同意。\n负责核发特许猎捕证的部门接到申请后，应当在3个月内作出批准或者不批准的决定。\n第十三条 有下列情形之一的，不予发放特许猎捕证：\n(一)申请猎捕者有条件以合法的非猎捕方式获得国家重点保护野生动物的种源、产品或者达到所需目的的；\n(二)猎捕申请不符合国家有关规定或者申请使用的猎捕工具、方法以及猎捕时间、地点不当的；\n(三)根据野生动物资源现状不宜捕捉、猎捕的。\n第十四条 取得特许猎捕证的单位和个人，必须按照特许猎捕证规定的种类、数量、地点、期限、工具和方法进行猎捕，防止误伤野生动物或者破坏其生存环境。猎捕作业完成后，应当在10日内向猎捕地的县级人民政府野生动物行政主管部门申请查验。\n县级人民政府野生动物行政主管部门对在本行政区域内猎捕国家重点保护野生动物的活动，应当进行监督检查，并及时向批准猎捕的机关报告监督检查结果。\n第十五条 猎捕非国家重点保护野生动物的，必须持有狩猎证，并按照狩猎证规定的种类、数量、地点、期限、工具和方法进行猎捕。\n狩猎证由省、自治区、直辖市人民政府林业行政主管部门按照国务院林业行政主管部门的规定印制，县级人民政府野生动物行政主管部门或者其授权的单位核发。\n狩猎证每年验证1次。\n第十六条 省、自治区、直辖市人民政府林业行政主管部门，应当根据本行政区域内非国家重点保护野生动物的资源现状，确定狩猎动物种类，并实行年度猎捕量限额管理。狩猎动物种类和年度猎捕量限额，由县级人民政府野生动物行政主管部门按照保护资源、永续利用的原则提出，经省、自治区、直辖市人民政府林业行政主管部门批准，报国务院林业行政主管部门备案。\n第十七条 县级以上地方各级人民政府野生动物行政主管部门应当组织狩猎者有计划地开展狩猎活动。\n在适合狩猎的区域建立固定狩猎场所的，必须经省、自治区、直辖市人民政府林业行政主管部门批准。\n第十八条 禁止使用军用武器、汽枪、毒药、炸药、地枪、排铳、非人为直接操作并危害人畜安全的狩猎装置、夜间照明行猎、歼灭性围猎、火攻、烟熏以及县级以上各级人民政府或者其野生动物行政主管部门规定禁止使用的其他狩猎工具和方法狩猎。\n第十九条 外国人在中国境内对国家重点保护野生动物进行野外考察、标本采集或者在野外拍摄电影、录像的，必须向国家重点保护野生动物所在地的省、自治区、直辖市人民政府林业行政主管部门提出申请，经其审核后，报国务院林业行政主管部门或者其授权的单位批准。\n第二十条 外国人在中国境内狩猎，必须在国务院林业行政主管部门批准的对外国人开放的狩猎场所内进行，并遵守中国有关法律、法规的规定。","level":1},{"name":"第四章 野生动物驯养繁殖管理","text":"第二十一条 驯养繁殖国家重点保护野生动物的，应当持有驯养繁殖许可证。\n国务院林业行政主管部门和省、自治区、直辖市人民政府林业行政主管部门可以根据实际情况和工作需要，委托同级有关部门审批或者核发国家重点保护野生动物驯养繁殖许可证。动物园驯养繁殖国家重点保护野生动物的，林业行政主管部门可以委托同级建设行政主管部门核发驯养繁殖许可证。\n驯养繁殖许可证由国务院林业行政主管部门印制。\n第二十二条 从国外或者外省、自治区、直辖市引进野生动物进行驯养繁殖的，应当采取适当措施，防止其逃至野外；需要将其放生于野外的，放生单位应当向所在省、自治区、直辖市人民政府林业行政主管部门提出申请，经省级以上人民政府林业行政主管部门指定的科研机构进行科学论证后，报国务院林业行政主管部门或者其授权的单位批准。\n擅自将引进的野生动物放生于野外或者因管理不当使其逃至野外的，由野生动物行政主管部门责令限期捕回或者采取其他补救措施。\n第二十三条 从国外引进的珍贵、濒危野生动物，经国务院林业行政主管部门核准，可以视为国家重点保护野生动物；从国外引进的其他野生动物，经省、自治区、直辖市人民政府林业行政主管部门核准，可以视为地方重点保护野生动物。","level":1},{"name":"第五章 野生动物经营利用管理","text":"第二十四条 收购驯养繁殖的国家重点保护野生动物或者其产品的单位，由省、自治区、直辖市人民政府林业行政主管部门商有关部门提出，经同级人民政府或者其授权的单位批准，凭批准文件向工商行政管理部门申请登记注册。\n依照前款规定经核准登记的单位，不得收购未经批准出售的国家重点保护野生动物或者其产品。\n第二十五条 经营利用非国家重点保护野生动物或者其产品的，应当向工商行政管理部门申请登记注册。\n第二十六条 禁止在集贸市场出售、收购国家重点保护野生动物或者其产品。\n持有狩猎证的单位和个人需要出售依法获得的非国家重点保护野生动物或者其产品的，应当按照狩猎证规定的种类、数量向经核准登记的单位出售，或者在当地人民政府有关部门指定的集贸市场出售。\n第二十七条 县级以上各级人民政府野生动物行政主管部门和工商行政管理部门，应当对野生动物或者其产品的经营利用建立监督检查制度，加强对经营利用野生动物或者其产品的监督管理。\n对进入集贸市场的野生动物或者其产品，由工商行政管理部门进行监督管理；在集贸市场以外经营野生动物或者其产品，由野生动物行政主管部门、工商行政管理部门或者其授权的单位进行监督管理。\n第二十八条 运输、携带国家重点保护野生动物或者其产品出县境的，应当凭特许猎捕证、驯养繁殖许可证，向县级人民政府野生动物行政主管部门提出申请，报省、自治区、直辖市人民政府林业行政主管部门或者其授权的单位批准。动物园之间因繁殖动物，需要运输国家重点保护野生动物的，可以由省、自治区、直辖市人民政府林业行政主管部门授权同级建设行政主管部门审批。\n第二十九条 出口国家重点保护野生动物或者其产品的，以及进出口中国参加的国际公约所限制进出口的野生动物或者其产品的，必须经进出口单位或者个人所在地的省、自治区、直辖市人民政府林业行政主管部门审核，报国务院林业行政主管部门或者国务院批准；属于贸易性进出口活动的，必须由具有有关商品进出口权的单位承担。\n动物园因交换动物需要进出口前款所称野生动物的，国务院林业行政主管部门批准前或者国务院林业行政主管部门报请国务院批准前，应当经国务院建设行政主管部门审核同意。\n第三十条 利用野生动物或者其产品举办出国展览等活动的经济收益，主要用于野生动物保护事业。","level":1},{"name":"第六章 奖励和惩罚","text":"第三十一条 有下列事迹之一的单位和个人，由县级以上人民政府或者其野生动物行政主管部门给予奖励：\n(一)在野生动物资源调查、保护管理、宣传教育、开发利用方面有突出贡献的；\n(二)严格执行野生动物保护法规，成绩显著的；\n(三)拯救、保护和驯养繁殖珍贵、濒危野生动物取得显著成效的；\n(四)发现违反野生动物保护法规行为，及时制止或者检举有功的；\n(五)在查处破坏野生动物资源案件中有重要贡献的；\n(六)在野生动物科学研究中取得重大成果或者在应用推广科研成果中取得显著效益的；\n(七)在基层从事野生动物保护管理工作五年以上并取得显著成绩的；\n(八)在野生动物保护管理工作中有其他特殊贡献的。\n第三十二条 非法捕杀国家重点保护野生动物的，依照刑法有关规定追究刑事责任；情节显著轻微危害不大的，或者犯罪情节轻微不需要判处刑罚的，由野生动物行政主管部门没收猎获物、猎捕工具和违法所得，吊销特许猎捕证，并处以相当于猎获物价值10倍以下的罚款，没有猎获物的处1万元以下罚款。\n第三十三条 违反野生动物保护法规，在禁猎区、禁猎期或者使用禁用的工具、方法猎捕非国家重点保护野生动物，依照《野生动物保护法》第三十二条的规定处以罚款的，按照下列规定执行：\n(一)有猎获物的，处以相当于猎获物价值8倍以下的罚款；\n(二)没有猎获物的，处2000元以下罚款。\n第三十四条 违反野生动物保护法规，未取得狩猎证或者未按照狩猎证规定猎捕非国家重点保护野生动物，依照《野生动物保护法》第三十三条的规定处以罚款的，按照下列规定执行：\n(一)有猎获物的，处以相当于猎获物价值5倍以下的罚款；\n(二)没有猎获物的，处1000元以下罚款。\n第三十五条 违反野生动物保护法规，在自然保护区、禁猎区破坏国家或者地方重点保护野生动物主要生息繁衍场所，依照《野生动物保护法》第三十四条的规定处以罚款的，按照相当于恢复原状所需费用3倍以下的标准执行。\n在自然保护区、禁猎区破坏非国家或者地方重点保护野生动物主要生息繁衍场所的，由野生动物行政主管部门责令停止破坏行为，限期恢复原状，并处以恢复原状所需费用2倍以下的罚款。\n第三十六条 违反野生动物保护法规，出售、收购、运输、携带国家或者地方重点保护野生动物或者其产品的，由工商行政管理部门或者其授权的野生动物行政主管部门没收实物和违法所得，可以并处相当于实物价值10倍以下的罚款。\n第三十七条 伪造、倒卖、转让狩猎证或者驯养繁殖许可证，依照《野生动物保护法》第三十七条的规定处以罚款的，按照5000元以下的标准执行。伪造、倒卖、转让特许猎捕证或者允许进出口证明书，依照《野生动物保护法》第三十七条的规定处以罚款的，按照5万元以下的标准执行。\n第三十八条 违反野生动物保护法规，未取得驯养繁殖许可证或者超越驯养繁殖许可证规定范围驯养繁殖国家重点保护野生动物的，由野生动物行政主管部门没收违法所得，处3000元以下罚款，可以并处没收野生动物、吊销驯养繁殖许可证。\n第三十九条 外国人未经批准在中国境内对国家重点保护野生动物进行野外考察、标本采集或者在野外拍摄电影、录像的，由野生动物行政主管部门没收考察、拍摄的资料以及所获标本，可以并处5万元以下罚款。\n第四十条 有下列行为之一，尚不构成犯罪，应当给予治安管理处罚的，由公安机关依照《中华人民共和国治安管理处罚法》的规定予以处罚：\n(一)拒绝、阻碍野生动物行政管理人员依法执行职务的；\n(二)偷窃、哄抢或者故意损坏野生动物保护仪器设备或者设施的；\n(三)偷窃、哄抢、抢夺非国家重点保护野生动物或者其产品的；\n(四)未经批准猎捕少量非国家重点保护野生动物的。\n第四十一条 违反野生动物保护法规，被责令限期捕回而不捕的，被责令限期恢复原状而不恢复的，野生动物行政主管部门或者其授权的单位可以代为捕回或者恢复原状，由被责令限期捕回者或者被责令限期恢复原状者承担全部捕回或者恢复原状所需的费用。\n第四十二条 违反野生动物保护法规，构成犯罪的，依法追究刑事责任。\n第四十三条 依照野生动物保护法规没收的实物，按照国务院林业行政主管部门的规定处理。","level":1},{"name":"第七章 附则","text":"第四十四条 本条例由国务院林业行政主管部门负责解释。\n第四十五条 本条例自发布之日起施行。","level":1}]},{"id":"n0386","sections":[{"name":"","text":"中华人民共和国渔业船舶检验条例\n(2003年6月11日国务院第11次常务会议通过 2003年6月27日中华人民共和国国务院令第383号公布 自2003年8月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了规范渔业船舶的检验，保证渔业船舶具备安全航行和作业的条件，保障渔业船舶和渔民生命财产的安全，防止污染环境，依照《中华人民共和国渔业法》，制定本条例。\n第二条 在中华人民共和国登记和将要登记的渔业船舶(以下简称渔业船舶)的检验，适用本条例。从事国际航运的渔业辅助船舶除外。\n第三条 国务院渔业行政主管部门主管全国渔业船舶检验及其监督管理工作。\n中华人民共和国渔业船舶检验局(以下简称国家渔业船舶检验机构)行使渔业船舶检验及其监督管理职能。\n地方渔业船舶检验机构依照本条例规定，负责有关的渔业船舶检验工作。\n各级公安边防、质量监督和工商行政管理等部门，应当在各自的职责范围内对渔业船舶检验和监督管理工作予以协助。\n第四条 国家对渔业船舶实行强制检验制度。强制检验分为初次检验、营运检验和临时检验。\n第五条 渔业船舶检验，应当遵循安全第一、保证质量和方便渔民的原则。","level":1},{"name":"第二章 初次检验","text":"第六条 渔业船舶的初次检验，是指渔业船舶检验机构在渔业船舶投入营运前对其所实施的全面检验。\n第七条 下列渔业船舶的所有者或者经营者应当申报初次检验：\n(一)制造的渔业船舶；\n(二)改造的渔业船舶(包括非渔业船舶改为渔业船舶、国内作业的渔业船舶改为远洋作业的渔业船舶)；\n(三)进口的渔业船舶。\n第八条 制造、改造的渔业船舶，其设计图纸、技术文件应当经渔业船舶检验机构审查批准，并在开工制造、改造前申报初次检验。渔业船舶检验机构应当自收到设计图纸、技术文件之日起20个工作日内作出审查决定，并书面通知当事人。\n设计、制造、改造渔业船舶的单位应当符合国家规定的条件，并遵守国家渔业船舶技术规则。\n第九条 制造、改造的渔业船舶的初次检验，应当与渔业船舶的制造、改造同时进行。\n用于制造、改造渔业船舶的有关航行、作业和人身财产安全以及防止污染环境的重要设备、部件和材料，在使用前应当经渔业船舶检验机构检验，检验合格的方可使用。\n前款规定必须检验的重要设备、部件和材料的目录，由国务院渔业行政主管部门制定。\n第十条 进口的渔业船舶，其设计图纸、技术文件应当经渔业船舶检验机构审查确认，并在投入营运前申报初次检验。进口旧渔业船舶，进口前还应当取得国家渔业船舶检验机构出具的旧渔业船舶技术评定证书。\n第十一条 渔业船舶检验机构对检验合格的渔业船舶，应当自检验完毕之日起5个工作日内签发渔业船舶检验证书；经检验不合格的，应当书面通知当事人，并说明理由。\n经检验合格的渔业船舶，任何单位和个人不得擅自改变其吨位、载重线、主机功率、人员定额和适航区域；不得擅自拆除其有关航行、作业和人身财产安全以及防止污染环境的重要设备、部件。确需改变或者拆除的，应当经原渔业船舶检验机构核准。\n第十二条 进口的渔业船舶和远洋渔业船舶的初次检验，由国家渔业船舶检验机构统一组织实施。其他渔业船舶的初次检验，由船籍港渔业船舶检验机构负责实施；渔业船舶的制造地或者改造地与船籍港不一致的，初次检验由制造地或者改造地渔业船舶检验机构实施；该渔业船舶检验机构应当自检验完毕之日起5个工作日内，将检验报告、检验记录等技术资料移交船籍港渔业船舶检验机构。","level":1},{"name":"第三章 营运检验","text":"第十三条 渔业船舶的营运检验，是指渔业船舶检验机构对营运中的渔业船舶所实施的常规性检验。\n第十四条 营运中的渔业船舶的所有者或者经营者应当按照国务院渔业行政主管部门规定的时间申报营运检验。\n渔业船舶检验机构应当按照国务院渔业行政主管部门的规定，根据渔业船舶运行年限和安全要求对下列项目实施检验：\n(一)渔业船舶的结构和机电设备；\n(二)与渔业船舶安全有关的设备、部件；\n(三)与防止污染环境有关的设备、部件；\n(四)国务院渔业行政主管部门规定的其他检验项目。\n第十五条 渔业船舶检验机构应当自申报营运检验的渔业船舶到达受检地之日起3个工作日内实施检验。经检验合格的，应当自检验完毕之日起5个工作日内在渔业船舶检验证书上签署意见或者签发渔业船舶检验证书；签发境外受检的远洋渔业船舶的检验证书，可以延长至15个工作日。经检验不合格的，应当书面通知当事人，并说明理由。\n第十六条 渔业船舶经检验需要维修的，该船舶的所有者或者经营者应当选择符合国家规定条件的维修单位。维修渔业船舶应当遵守国家渔业船舶技术规则。\n用于维修渔业船舶的有关航行、作业和人身财产安全以及防止污染环境的重要设备、部件和材料，在使用前应当经渔业船舶检验机构检验，检验合格的方可使用。\n第十七条 营运中的渔业船舶需要更换有关航行、作业和人身财产安全以及防止污染环境的重要设备、部件和材料的，该船舶的所有者或者经营者应当遵守本条例第十六条第二款的规定。\n第十八条 远洋渔业船舶的营运检验，由国家渔业船舶检验机构统一组织实施。其他渔业船舶的营运检验，由船籍港渔业船舶检验机构负责实施；因故不能回船籍港进行营运检验的渔业船舶，由船籍港渔业船舶检验机构委托船舶的营运地或者维修地渔业船舶检验机构实施检验；实施检验的渔业船舶检验机构应当自检验完毕之日起5个工作日内将检验报告、检验记录等技术资料移交船籍港渔业船舶检验机构。","level":1},{"name":"第四章 临时检验","text":"第十九条 渔业船舶的临时检验，是指渔业船舶检验机构对营运中的渔业船舶出现特定情形时所实施的非常规性检验。\n第二十条 有下列情形之一的渔业船舶，其所有者或者经营者应当申报临时检验：\n(一)因检验证书失效而无法及时回船籍港的；\n(二)因不符合水上交通安全或者环境保护法律、法规的有关要求被责令检验的；\n(三)具有国务院渔业行政主管部门规定的其他特定情形的。\n第二十一条 渔业船舶检验机构应当自申报临时检验的渔业船舶到达受检地之日起2个工作日内实施检验。经检验合格的，应当自检验完毕之日起3个工作日内在渔业船舶检验证书上签署意见或者签发渔业船舶检验证书；经检验不合格的，应当书面通知当事人，并说明理由。\n第二十二条 渔业船舶临时检验的管辖权限划分，依照本条例第十八条关于营运检验管辖权限的规定执行。","level":1},{"name":"第五章 监督管理","text":"第二十三条 有下列情形之一的渔业船舶，渔业船舶检验机构不得受理检验：\n(一)设计图纸、技术文件未经渔业船舶检验机构审查批准或者确认的；\n(二)违反本条例第八条第二款和第九条第二款规定制造、改造的；\n(三)违反本条例第十六条、第十七条规定维修的；\n(四)按照国家有关规定应当报废的。\n第二十四条 地方渔业船舶检验机构应当在国家渔业船舶检验机构核定的范围内开展检验业务。\n第二十五条 从事渔业船舶检验的人员应当经国家渔业船舶检验机构考核合格后，方可从事相应的渔业船舶检验工作。\n第二十六条 渔业船舶检验机构及其检验人员应当严格遵守渔业船舶检验规则，实施现场检验，并对检验结论负责。\n渔业船舶检验规则由国家渔业船舶检验机构制定，经国务院渔业行政主管部门批准后公布实施。\n对具有新颖性的渔业船舶或者船用产品，国家尚未制定相应的检验规则的，可以适用国家渔业船舶检验机构认可的检验规则。\n第二十七条 当事人对地方渔业船舶检验机构的检验结论有异议的，可以按照国务院渔业行政主管部门的规定申请复验。\n第二十八条 渔业船舶的检验收费，按照国务院价格主管部门、财政部门规定的收费标准执行。\n第二十九条 渔业船舶的检验证书、检验记录、检验报告的式样和检验业务印章，由国家渔业船舶检验机构统一规定。\n第三十条 渔业船舶检验人员依法履行职能时，有权对渔业船舶的检验证书和技术状况进行检查，有关单位和个人应当给予配合。\n重大渔业船舶海损事故的调查处理，应当有渔业船舶检验机构的检验人员参加。\n第三十一条 有下列情形之一的渔业船舶，其所有者或者经营者应当在渔业船舶报废、改籍、改造之日前7个工作日内或者自渔业船舶灭失之日起20个工作日内，向渔业船舶检验机构申请注销其渔业船舶检验证书；逾期不申请的，渔业船舶检验证书自渔业船舶改籍、改造完毕之日起或者渔业船舶报废、灭失之日起失效，并由渔业船舶检验机构注销渔业船舶检验证书：\n(一)按照国家有关规定报废的；\n(二)中国籍改为外国籍的；\n(三)渔业船舶改为非渔业船舶的；\n(四)因沉没等原因灭失的。","level":1},{"name":"第六章 法律责任","text":"第三十二条 违反本条例规定，渔业船舶未经检验、未取得渔业船舶检验证书擅自下水作业的，没收该渔业船舶。\n按照规定应当报废的渔业船舶继续作业的，责令立即停止作业，收缴失效的渔业船舶检验证书，强制拆解应当报废的渔业船舶，并处2000元以上5万元以下的罚款；构成犯罪的，依法追究刑事责任。\n第三十三条 违反本条例规定，渔业船舶应当申报营运检验或者临时检验而不申报的，责令立即停止作业，限期申报检验；逾期仍不申报检验的，处1000元以上1万元以下的罚款，并可以暂扣渔业船舶检验证书。\n第三十四条 违反本条例规定，有下列行为之一的，责令立即改正，处2000元以上2万元以下的罚款；正在作业的，责令立即停止作业；拒不改正或者拒不停止作业的，强制拆除非法使用的重要设备、部件和材料或者暂扣渔业船舶检验证书；构成犯罪的，依法追究刑事责任：\n(一)使用未经检验合格的有关航行、作业和人身财产安全以及防止污染环境的重要设备、部件和材料，制造、改造、维修渔业船舶的；\n(二)擅自拆除渔业船舶上有关航行、作业和人身财产安全以及防止污染环境的重要设备、部件的；\n(三)擅自改变渔业船舶的吨位、载重线、主机功率、人员定额和适航区域的。\n第三十五条 渔业船舶检验机构的工作人员未经考核合格从事渔业船舶检验工作的，责令其立即停止检验工作，处1000元以上5000元以下的罚款。\n第三十六条 违反本条例规定，有下列情形之一的，责令立即改正，对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职、取消检验资格的处分；构成犯罪的，依法追究刑事责任；已签发的渔业船舶检验证书无效：\n(一)未按照国务院渔业行政主管部门的有关规定实施检验的；\n(二)所签发的渔业船舶检验证书或者检验记录、检验报告与渔业船舶实际情况不相符的；\n(三)超越规定的权限进行渔业船舶检验的。\n第三十七条 伪造、变造渔业船舶检验证书、检验记录和检验报告，或者私刻渔业船舶检验业务印章的，应当予以没收；构成犯罪的，依法追究刑事责任。\n第三十八条 本条例规定的行政处罚，由县级以上人民政府渔业行政主管部门或者其所属的渔业行政执法机构依据职权决定。\n前款规定的行政处罚决定机关及其工作人员利用职务上的便利收取他人财物、其他好处，或者不履行监督职责、发现违法行为不予查处，或者有其他玩忽职守、滥用职权、徇私舞弊行为，构成犯罪的，依法追究直接负责的主管人员和其他直接责任人员的刑事责任；尚不构成犯罪的，依法给予行政处分。","level":1},{"name":"第七章 附则","text":"第三十九条 外国籍渔业船舶，其船旗国委托中华人民共和国检验的，依照本条例的规定执行。\n第四十条 本条例自2003年8月1日起施行。","level":1}]},{"id":"n0387","sections":[{"name":"","text":"农业机械安全监督管理条例\n(2009年9月17日中华人民共和国国务院令第563号公布 根据2016年2月6日《国务院关于修改部分行政法规的决定》第一次修订 根据2019年3月2日《国务院关于修改部分行政法规的决定》第二次修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强农业机械安全监督管理，预防和减少农业机械事故，保障人民生命和财产安全，制定本条例。\n第二条 在中华人民共和国境内从事农业机械的生产、销售、维修、使用操作以及安全监督管理等活动，应当遵守本条例。\n本条例所称农业机械，是指用于农业生产及其产品初加工等相关农事活动的机械、设备。\n第三条 农业机械安全监督管理应当遵循以人为本、预防事故、保障安全、促进发展的原则。\n第四条 县级以上人民政府应当加强对农业机械安全监督管理工作的领导，完善农业机械安全监督管理体系，增加对农民购买农业机械的补贴，保障农业机械安全的财政投入，建立健全农业机械安全生产责任制。\n第五条 国务院有关部门和地方各级人民政府、有关部门应当加强农业机械安全法律、法规、标准和知识的宣传教育。\n农业生产经营组织、农业机械所有人应当对农业机械操作人员及相关人员进行农业机械安全使用教育，提高其安全意识。\n第六条 国家鼓励和支持开发、生产、推广、应用先进适用、安全可靠、节能环保的农业机械，建立健全农业机械安全技术标准和安全操作规程。\n第七条 国家鼓励农业机械操作人员、维修技术人员参加职业技能培训和依法成立安全互助组织，提高农业机械安全操作水平。\n第八条 国家建立落后农业机械淘汰制度和危及人身财产安全的农业机械报废制度，并对淘汰和报废的农业机械依法实行回收。\n第九条 国务院农业机械化主管部门、工业主管部门、市场监督管理部门等有关部门依照本条例和国务院规定的职责，负责农业机械安全监督管理工作。\n县级以上地方人民政府农业机械化主管部门、工业主管部门和市场监督管理部门等有关部门按照各自职责，负责本行政区域的农业机械安全监督管理工作。","level":1},{"name":"第二章 生产、销售和维修","text":"第十条 国务院工业主管部门负责制定并组织实施农业机械工业产业政策和有关规划。\n国务院标准化主管部门负责制定发布农业机械安全技术国家标准，并根据实际情况及时修订。农业机械安全技术标准是强制执行的标准。\n第十一条 农业机械生产者应当依据农业机械工业产业政策和有关规划，按照农业机械安全技术标准组织生产，并建立健全质量保障控制体系。\n对依法实行工业产品生产许可证管理的农业机械，其生产者应当取得相应资质，并按照许可的范围和条件组织生产。\n第十二条 农业机械生产者应当按照农业机械安全技术标准对生产的农业机械进行检验；农业机械经检验合格并附具详尽的安全操作说明书和标注安全警示标志后，方可出厂销售；依法必须进行认证的农业机械，在出厂前应当标注认证标志。\n上道路行驶的拖拉机，依法必须经过认证的，在出厂前应当标注认证标志，并符合机动车国家安全技术标准。\n农业机械生产者应当建立产品出厂记录制度，如实记录农业机械的名称、规格、数量、生产日期、生产批号、检验合格证号、购货者名称及联系方式、销售日期等内容。出厂记录保存期限不得少于3年。\n第十三条 进口的农业机械应当符合我国农业机械安全技术标准，并依法由出入境检验检疫机构检验合格。依法必须进行认证的农业机械，还应当由出入境检验检疫机构进行入境验证。\n第十四条 农业机械销售者对购进的农业机械应当查验产品合格证明。对依法实行工业产品生产许可证管理、依法必须进行认证的农业机械，还应当验明相应的证明文件或者标志。\n农业机械销售者应当建立销售记录制度，如实记录农业机械的名称、规格、生产批号、供货者名称及联系方式、销售流向等内容。销售记录保存期限不得少于3年。\n农业机械销售者应当向购买者说明农业机械操作方法和安全注意事项，并依法开具销售发票。\n第十五条 农业机械生产者、销售者应当建立健全农业机械销售服务体系，依法承担产品质量责任。\n第十六条 农业机械生产者、销售者发现其生产、销售的农业机械存在设计、制造等缺陷，可能对人身财产安全造成损害的，应当立即停止生产、销售，及时报告当地市场监督管理部门，通知农业机械使用者停止使用。农业机械生产者应当及时召回存在设计、制造等缺陷的农业机械。\n农业机械生产者、销售者不履行本条第一款义务的，市场监督管理部门可以责令生产者召回农业机械，责令销售者停止销售农业机械。\n第十七条 禁止生产、销售下列农业机械：\n(一)不符合农业机械安全技术标准的；\n(二)依法实行工业产品生产许可证管理而未取得许可证的；\n(三)依法必须进行认证而未经认证的；\n(四)利用残次零配件或者报废农业机械的发动机、方向机、变速器、车架等部件拼装的；\n(五)国家明令淘汰的。\n第十八条 从事农业机械维修经营，应当有必要的维修场地，有必要的维修设施、设备和检测仪器，有相应的维修技术人员，有安全防护和环境保护措施。\n第十九条 农业机械维修经营者应当遵守国家有关维修质量安全技术规范和维修质量保证期的规定，确保维修质量。\n从事农业机械维修不得有下列行为：\n(一)使用不符合农业机械安全技术标准的零配件；\n(二)拼装、改装农业机械整机；\n(三)承揽维修已经达到报废条件的农业机械；\n(四)法律、法规和国务院农业机械化主管部门规定的其他禁止性行为。","level":1},{"name":"第三章 使用操作","text":"第二十条 农业机械操作人员可以参加农业机械操作人员的技能培训，可以向有关农业机械化主管部门、人力资源和社会保障部门申请职业技能鉴定，获取相应等级的国家职业资格证书。\n第二十一条 拖拉机、联合收割机投入使用前，其所有人应当按照国务院农业机械化主管部门的规定，持本人身份证明和机具来源证明，向所在地县级人民政府农业机械化主管部门申请登记。拖拉机、联合收割机经安全检验合格的，农业机械化主管部门应当在2个工作日内予以登记并核发相应的证书和牌照。\n拖拉机、联合收割机使用期间登记事项发生变更的，其所有人应当按照国务院农业机械化主管部门的规定申请变更登记。\n第二十二条 拖拉机、联合收割机操作人员经过培训后，应当按照国务院农业机械化主管部门的规定，参加县级人民政府农业机械化主管部门组织的考试。考试合格的，农业机械化主管部门应当在2个工作日内核发相应的操作证件。\n拖拉机、联合收割机操作证件有效期为6年；有效期满，拖拉机、联合收割机操作人员可以向原发证机关申请续展。未满18周岁不得操作拖拉机、联合收割机。操作人员年满70周岁的，县级人民政府农业机械化主管部门应当注销其操作证件。\n第二十三条 拖拉机、联合收割机应当悬挂牌照。拖拉机上道路行驶，联合收割机因转场作业、维修、安全检验等需要转移的，其操作人员应当携带操作证件。\n拖拉机、联合收割机操作人员不得有下列行为：\n(一)操作与本人操作证件规定不相符的拖拉机、联合收割机；\n(二)操作未按照规定登记、检验或者检验不合格、安全设施不全、机件失效的拖拉机、联合收割机；\n(三)使用国家管制的精神药品、麻醉品后操作拖拉机、联合收割机；\n(四)患有妨碍安全操作的疾病操作拖拉机、联合收割机；\n(五)国务院农业机械化主管部门规定的其他禁止行为。\n禁止使用拖拉机、联合收割机违反规定载人。\n第二十四条 农业机械操作人员作业前，应当对农业机械进行安全查验；作业时，应当遵守国务院农业机械化主管部门和省、自治区、直辖市人民政府农业机械化主管部门制定的安全操作规程。","level":1},{"name":"第四章 事故处理","text":"第二十五条 县级以上地方人民政府农业机械化主管部门负责农业机械事故责任的认定和调解处理。\n本条例所称农业机械事故，是指农业机械在作业或者转移等过程中造成人身伤亡、财产损失的事件。\n农业机械在道路上发生的交通事故，由公安机关交通管理部门依照道路交通安全法律、法规处理；拖拉机在道路以外通行时发生的事故，公安机关交通管理部门接到报案的，参照道路交通安全法律、法规处理。农业机械事故造成公路及其附属设施损坏的，由交通主管部门依照公路法律、法规处理。\n第二十六条 在道路以外发生的农业机械事故，操作人员和现场其他人员应当立即停止作业或者停止农业机械的转移，保护现场，造成人员伤害的，应当向事故发生地农业机械化主管部门报告；造成人员死亡的，还应当向事故发生地公安机关报告。造成人身伤害的，应当立即采取措施，抢救受伤人员。因抢救受伤人员变动现场的，应当标明位置。\n接到报告的农业机械化主管部门和公安机关应当立即派人赶赴现场进行勘验、检查，收集证据，组织抢救受伤人员，尽快恢复正常的生产秩序。\n第二十七条 对经过现场勘验、检查的农业机械事故，农业机械化主管部门应当在10个工作日内制作完成农业机械事故认定书；需要进行农业机械鉴定的，应当自收到农业机械鉴定机构出具的鉴定结论之日起5个工作日内制作农业机械事故认定书。\n农业机械事故认定书应当载明农业机械事故的基本事实、成因和当事人的责任，并在制作完成农业机械事故认定书之日起3个工作日内送达当事人。\n第二十八条 当事人对农业机械事故损害赔偿有争议，请求调解的，应当自收到事故认定书之日起10个工作日内向农业机械化主管部门书面提出调解申请。\n调解达成协议的，农业机械化主管部门应当制作调解书送交各方当事人。调解书经各方当事人共同签字后生效。调解不能达成协议或者当事人向人民法院提起诉讼的，农业机械化主管部门应当终止调解并书面通知当事人。调解达成协议后当事人反悔的，可以向人民法院提起诉讼。\n第二十九条 农业机械化主管部门应当为当事人处理农业机械事故损害赔偿等后续事宜提供帮助和便利。因农业机械产品质量原因导致事故的，农业机械化主管部门应当依法出具有关证明材料。\n农业机械化主管部门应当定期将农业机械事故统计情况及说明材料报送上级农业机械化主管部门并抄送同级安全生产监督管理部门。\n农业机械事故构成生产安全事故的，应当依照相关法律、行政法规的规定调查处理并追究责任。","level":1},{"name":"第五章 服务与监督","text":"第三十条 县级以上地方人民政府农业机械化主管部门应当定期对危及人身财产安全的农业机械进行免费实地安全检验。但是道路交通安全法律对拖拉机的安全检验另有规定的，从其规定。\n拖拉机、联合收割机的安全检验为每年1次。\n实施安全技术检验的机构应当对检验结果承担法律责任。\n第三十一条 农业机械化主管部门在安全检验中发现农业机械存在事故隐患的，应当告知其所有人停止使用并及时排除隐患。\n实施安全检验的农业机械化主管部门应当对安全检验情况进行汇总，建立农业机械安全监督管理档案。\n第三十二条 联合收割机跨行政区域作业前，当地县级人民政府农业机械化主管部门应当会同有关部门，对跨行政区域作业的联合收割机进行必要的安全检查，并对操作人员进行安全教育。\n第三十三条 国务院农业机械化主管部门应当定期对农业机械安全使用状况进行分析评估，发布相关信息。\n第三十四条 国务院工业主管部门应当定期对农业机械生产行业运行态势进行监测和分析，并按照先进适用、安全可靠、节能环保的要求，会同国务院农业机械化主管部门、市场监督管理部门等有关部门制定、公布国家明令淘汰的农业机械产品目录。\n第三十五条 危及人身财产安全的农业机械达到报废条件的，应当停止使用，予以报废。农业机械的报废条件由国务院农业机械化主管部门会同国务院市场监督管理部门、工业主管部门规定。\n县级人民政府农业机械化主管部门对达到报废条件的危及人身财产安全的农业机械，应当书面告知其所有人。\n第三十六条 国家对达到报废条件或者正在使用的国家已经明令淘汰的农业机械实行回收。农业机械回收办法由国务院农业机械化主管部门会同国务院财政部门、商务主管部门制定。\n第三十七条 回收的农业机械由县级人民政府农业机械化主管部门监督回收单位进行解体或者销毁。\n第三十八条 使用操作过程中发现农业机械存在产品质量、维修质量问题的，当事人可以向县级以上地方人民政府农业机械化主管部门或者市场监督管理部门投诉。接到投诉的部门对属于职责范围内的事项，应当依法及时处理；对不属于职责范围内的事项，应当及时移交有权处理的部门，有权处理的部门应当立即处理，不得推诿。\n县级以上地方人民政府农业机械化主管部门和市场监督管理部门应当定期汇总农业机械产品质量、维修质量投诉情况并逐级上报。\n第三十九条 国务院农业机械化主管部门和省、自治区、直辖市人民政府农业机械化主管部门应当根据投诉情况和农业安全生产需要，组织开展在用的特定种类农业机械的安全鉴定和重点检查，并公布结果。\n第四十条 农业机械安全监督管理执法人员在农田、场院等场所进行农业机械安全监督检查时，可以采取下列措施：\n(一)向有关单位和个人了解情况，查阅、复制有关资料；\n(二)查验拖拉机、联合收割机证书、牌照及有关操作证件；\n(三)检查危及人身财产安全的农业机械的安全状况，对存在重大事故隐患的农业机械，责令当事人立即停止作业或者停止农业机械的转移，并进行维修；\n(四)责令农业机械操作人员改正违规操作行为。\n第四十一条 发生农业机械事故后企图逃逸的、拒不停止存在重大事故隐患农业机械的作业或者转移的，县级以上地方人民政府农业机械化主管部门可以扣押有关农业机械及证书、牌照、操作证件。案件处理完毕或者农业机械事故肇事方提供担保的，县级以上地方人民政府农业机械化主管部门应当及时退还被扣押的农业机械及证书、牌照、操作证件。存在重大事故隐患的农业机械，其所有人或者使用人排除隐患前不得继续使用。\n第四十二条 农业机械安全监督管理执法人员进行安全监督检查时，应当佩戴统一标志，出示行政执法证件。农业机械安全监督检查、事故勘察车辆应当在车身喷涂统一标识。\n第四十三条 农业机械化主管部门不得为农业机械指定维修经营者。\n第四十四条 农业机械化主管部门应当定期向同级公安机关交通管理部门通报拖拉机登记、检验以及有关证书、牌照、操作证件发放情况。公安机关交通管理部门应当定期向同级农业机械化主管部门通报农业机械在道路上发生的交通事故及处理情况。","level":1},{"name":"第六章 法律责任","text":"第四十五条 县级以上地方人民政府农业机械化主管部门、工业主管部门、市场监督管理部门及其工作人员有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予处分，构成犯罪的，依法追究刑事责任：\n(一)不依法对拖拉机、联合收割机实施安全检验、登记，或者不依法核发拖拉机、联合收割机证书、牌照的；\n(二)对未经考试合格者核发拖拉机、联合收割机操作证件，或者对经考试合格者拒不核发拖拉机、联合收割机操作证件的；\n(三)不依法处理农业机械事故，或者不依法出具农业机械事故认定书和其他证明材料的；\n(四)在农业机械生产、销售等过程中不依法履行监督管理职责的；\n(五)其他未依照本条例的规定履行职责的行为。\n第四十六条 生产、销售利用残次零配件或者报废农业机械的发动机、方向机、变速器、车架等部件拼装的农业机械的，由县级以上人民政府市场监督管理部门责令停止生产、销售，没收违法所得和违法生产、销售的农业机械，并处违法产品货值金额1倍以上3倍以下罚款；情节严重的，吊销营业执照。\n农业机械生产者、销售者违反工业产品生产许可证管理、认证认可管理、安全技术标准管理以及产品质量管理的，依照有关法律、行政法规处罚。\n第四十七条 农业机械销售者未依照本条例的规定建立、保存销售记录的，由县级以上人民政府市场监督管理部门责令改正，给予警告；拒不改正的，处1000元以上1万元以下罚款，并责令停业整顿；情节严重的，吊销营业执照。\n第四十八条 从事农业机械维修经营不符合本条例第十八条规定的，由县级以上地方人民政府农业机械化主管部门责令改正；拒不改正的，处5000元以上1万元以下罚款。\n第四十九条 农业机械维修经营者使用不符合农业机械安全技术标准的配件维修农业机械，或者拼装、改装农业机械整机，或者承揽维修已经达到报废条件的农业机械的，由县级以上地方人民政府农业机械化主管部门责令改正，没收违法所得，并处违法经营额1倍以上2倍以下罚款；拒不改正的，处违法经营额2倍以上5倍以下罚款。\n第五十条 未按照规定办理登记手续并取得相应的证书和牌照，擅自将拖拉机、联合收割机投入使用，或者未按照规定办理变更登记手续的，由县级以上地方人民政府农业机械化主管部门责令限期补办相关手续；逾期不补办的，责令停止使用；拒不停止使用的，扣押拖拉机、联合收割机，并处200元以上2000元以下罚款。\n当事人补办相关手续的，应当及时退还扣押的拖拉机、联合收割机。\n第五十一条 伪造、变造或者使用伪造、变造的拖拉机、联合收割机证书和牌照的，或者使用其他拖拉机、联合收割机的证书和牌照的，由县级以上地方人民政府农业机械化主管部门收缴伪造、变造或者使用的证书和牌照，对违法行为人予以批评教育，并处200元以上2000元以下罚款。\n第五十二条 未取得拖拉机、联合收割机操作证件而操作拖拉机、联合收割机的，由县级以上地方人民政府农业机械化主管部门责令改正，处100元以上500元以下罚款。\n第五十三条 拖拉机、联合收割机操作人员操作与本人操作证件规定不相符的拖拉机、联合收割机，或者操作未按照规定登记、检验或者检验不合格、安全设施不全、机件失效的拖拉机、联合收割机，或者使用国家管制的精神药品、麻醉品后操作拖拉机、联合收割机，或者患有妨碍安全操作的疾病操作拖拉机、联合收割机的，由县级以上地方人民政府农业机械化主管部门对违法行为人予以批评教育，责令改正；拒不改正的，处100元以上500元以下罚款；情节严重的，吊销有关人员的操作证件。\n第五十四条 使用拖拉机、联合收割机违反规定载人的，由县级以上地方人民政府农业机械化主管部门对违法行为人予以批评教育，责令改正；拒不改正的，扣押拖拉机、联合收割机的证书、牌照；情节严重的，吊销有关人员的操作证件。非法从事经营性道路旅客运输的，由交通主管部门依照道路运输管理法律、行政法规处罚。\n当事人改正违法行为的，应当及时退还扣押的拖拉机、联合收割机的证书、牌照。\n第五十五条 经检验、检查发现农业机械存在事故隐患，经农业机械化主管部门告知拒不排除并继续使用的，由县级以上地方人民政府农业机械化主管部门对违法行为人予以批评教育，责令改正；拒不改正的，责令停止使用；拒不停止使用的，扣押存在事故隐患的农业机械。\n事故隐患排除后，应当及时退还扣押的农业机械。\n第五十六条 违反本条例规定，造成他人人身伤亡或者财产损失的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附则","text":"第五十七条 本条例所称危及人身财产安全的农业机械，是指对人身财产安全可能造成损害的农业机械，包括拖拉机、联合收割机、机动植保机械、机动脱粒机、饲料粉碎机、插秧机、铡草机等。\n第五十八条 本条例规定的农业机械证书、牌照、操作证件，由国务院农业机械化主管部门会同国务院有关部门统一规定式样，由国务院农业机械化主管部门监制。\n第五十九条 拖拉机操作证件考试收费、安全技术检验收费和牌证的工本费，应当严格执行国务院价格主管部门核定的收费标准。\n第六十条 本条例自2009年11月1日起施行。","level":1}]},{"id":"n0388","sections":[{"name":"","text":"关于外国人在我国旅行管理的规定\n(公安部、总参谋部、外交部、国家旅游局制定 1982年10月9日国务院、中央军委批转)\n为了适应我国对外开放政策的需要，简化外国人去各地旅行的审批手续，本着既要维护国家安全，保守国家机密，又要有步骤地适当放宽对外国人旅行限制的精神，特规定如下：\n一、开放地区应具备的条件\n1．有开放价值，能吸引外国人去的名胜、古迹旅游点、风景区或有对外贸易、文化、科技交流的大、中城市；2．社会治安稳定，交通情况良好；3．有接待条件(包括翻译导游和住宿、汽车、副食供应等); 4．非军事禁区。\n二、开放地区的审批手续\n凡具备开放条件的地区，由省、自治区、直辖市人民政府商有关大军区同意，报国务院批准，作为全国对外开放地区；凡因自然灾害或重要军事行动等原因，对某些开放城市或地区需要封闭的，由省、自治区、直辖市人民政府和大军区报国务院、中央军委审批。\n地区的开放或封闭的审批工作，由公安部承办并汇总公布。\n三、外国人旅行地区分为以下几类：\n1．甲类地区：外国人前往这类地区，不办旅行证，不需事先通知。现确定为二十九个市、县：\n北京市 天津市 上海市 秦皇岛市\n太原市 沈阳市 长春市 哈尔滨市\n南京市 苏州市 无锡市 杭州市\n济南市 青岛市 郑州市 开封市\n洛阳市 武汉市 长沙市 广州市\n佛山市 肇庆市 南宁市 桂林市\n西安市 成都市 重庆市 昆明市\n路南县(石林)\n2．乙类地区(见附表)：是指除甲类地区外，已经对外开放、控制开放和新增加开放的地区。外国人前往这类地区，仍需办旅行证，一般均可批准。\n3．丙类地区：是指一般性非开放地区，有外国人经常去考察、进行科技交流、现场施工等公务活动的地区。这些地区，可准许有关的外国人前往，但要办旅行证。这类地区的名单，由各大军区审核同意，公安部汇总通报有关部门和各地公安机关掌握。\n4．丁类地区：是指除甲、乙、丙三类地区以外的其它非开放地区。外国人因特殊情况需要去这类地区的，接待单位要事先征得前往地的省、自治区人民政府和大军区的同意，然后向公安机关申领旅行证，方可前往。\n四、甲、乙类地区内如有重要军事设施，则应划为非开放范围。\n五、各国驻华外交代表机关和国际组织驻华机构人员的旅行，一般按本规定办理。必要时，视有关国家对我驻外人员的旅行是否限制而采取对等措施。\n六、外国人旅行，除北京到天津之间允许乘自备汽车外，其他地区不准乘自备交通工具。\n七、外国人在非开放地区的活动，接待单位或有关人员应按事先规定的路线和范围安排，不得随意改变。\n八、凡在非开放地区选定与外国合资、合办、考察项目，涉及几个省、自治区、直辖市的，事先要征求公安部的意见；其中在一个大军区范围内的，应征得所在大军区的同意；超出一个大军区范围的，还应征求总参谋部的意见，尔后按规定报批。\n九、外籍华人去非开放地区探亲、旅行，按一九八○年国务院、中央军委批准的公安部《关于取消对海外华侨、港澳同胞旅行限制的请示》的规定办理。\n十、凡涉及国家安全的地区、单位，都要做好保密工作。凡涉及国家安全的地段和部位以及国家列为重点保护的珍贵文物，不准摄影、录像的，应事先向陪同人员和外国人宣布。\n十一、本规定自批准之日起施行。过去有关规定与本规定有抵触的，以本规定为准。\n附表\n乙 类 地 区\n已经开放、控制开放的地区\t新增加的开放地区\t各省、自治区确定的开放点\n河北 石家庄市、承德市、涿县、遵化县(东陵)、\t锦州市、丹东市、辽阳市、营口市、本溪市\t平山县(西柏坡，岗南水库)、赵县(赵州桥)、遵化县(沙石峪)\n山西 大同市\n内蒙古 包头市、呼和浩特市\t安图县(长白山自然保护区)\n辽宁 大连市、鞍山市、抚顺市\t齐齐哈尔市、牡丹江市、佳木斯市、伊春市\n吉林 吉林市\t蚌埠市、屯溪市\n黑龙江 大庆市\n江苏 徐州市、扬州市、常州市、镇江市、连云港市、淮安县、宜兴县\n浙江 绍兴市、宁波市、温州市、德清县(莫干山)\n安徽 合肥市、芜湖市、马鞍山市、青阳县(九华山)、黄山游览区\n福建 福州市、泉州市、漳州市、厦门市 武夷山游览区\n江西 南昌市、景德镇市、九江市(含庐山)、井冈山县\t彭泽县(龙宫洞)\n续\n已经开放、控制开放的地区\t新增加的开放地区\t各省、自治区确定的开放点\n山东 烟台市、淄博市、泰安市、曲阜县、垦利县(胜利油田)\n河南 安阳市、新乡市、林县、巩县、信阳市(鸡公山) 三门峡市、新乡县、辉县、禹县\n湖北 沙市市、襄樊市、咸宁县、均县(丹江)\t宜昌市、江陵县\n湖南 岳阳市、衡阳市、湘潭市、湘潭县(韶山)\t衡山县(衡山游览区)\n广东\t深圳市、珠海市、江门市、海口市、南海县、中山县、顺德县\t清远县、新会县\n广西 柳州市、武鸣县、宾阳县、桂平县\t梧州市、兴安县\t北海市区、灵川县(青狮潭水库)、邕宁县(五圹公社)\n四川 乐山市、万县市、峨眉县(峨眉山)\t新都县、灌县、眉山县、忠县、云阳县、奉节县、巫山县、大足县\n贵州\t贵阳市、镇宁县(黄果树)\n陕西 延安市\t咸阳市、临潼县\n甘肃 兰州市、嘉峪关市、酒泉县、敦煌县\n新疆 乌鲁木齐市、石河子市、吐鲁番县 喀什市、库车县、阿克苏县(只限登山队途经、食宿)\n注：河北省遵化县东陵七、八、十一月因有军事活动，不对外开放。","level":0}]},{"id":"n0389","sections":[{"name":"","text":"海关关衔标志式样和佩带办法\n(2003年7月8日国务院第14次常务会议通过 2003年7月15日中华人民共和国国务院令第384号公布 自公布之日起施行)\n第一条 根据《中华人民共和国海关关衔条例》的规定，制定本办法。\n第二条 海关工作人员佩带的关衔标志必须与所授予的关衔相符。\n第三条 海关关衔标志：海关总监、海关副总监关衔标志由橄榄叶环绕的海关关徽和五角星下衬五边形的星花组成；关务监督关衔标志由橄榄叶、星花和海关关徽组成；关务督察、关务督办、关务员关衔标志由横杠、星花和海关关徽组成。海关关衔标志为金色。\n第四条 关衔标志缀钉在肩章上，肩章为剑形，版面为黑色，分为硬肩章和软肩章。\n海关工作人员着制式上衣、制式大衣时，佩带硬肩章；着制式短袖衫、制式长袖衫、查验服时，佩带软肩章。\n第五条 海关总监关衔标志为一枚橄榄叶环绕的海关关徽和三枚星花；海关副总监关衔标志为一枚橄榄叶环绕的海关关徽和二枚星花。\n关务监督关衔标志为一枚橄榄叶和一枚海关关徽，一级关务监督关衔标志为三枚星花；二级关务监督关衔标志为二枚星花；三级关务监督关衔标志为一枚星花。\n关务督察关衔标志为三道横杠和一枚海关关徽，一级关务督察关衔标志为三枚星花；二级关务督察关衔标志为二枚星花；三级关务督察关衔标志为一枚星花。\n关务督办关衔标志为二道横杠和一枚海关关徽，一级关务督办关衔标志为三枚星花；二级关务督办关衔标志为二枚星花；三级关务督办关衔标志为一枚星花。\n关务员关衔标志为一道横杠和一枚海关关徽，一级关务员关衔标志为三枚星花；二级关务员关衔标志为二枚星花。\n第六条 海关工作人员晋升或者降低关衔的，由批准机关更换其关衔标志；取消或者不予保留关衔的，由批准机关收回其关衔标志。\n第七条 海关关衔标志由海关总署负责制作和管理。其他单位和个人不得制作、仿造、伪造、变造和买卖、使用关衔标志，也不得使用与关衔标志相类似的标志。\n第八条 本办法自公布之日起施行。\n附图：\n海关关衔标志式样","level":0}]},{"id":"n0390","sections":[{"name":"","text":"法律援助条例\n(2003年7月16日国务院第15次常务会议通过 2003年7月21日中华人民共和国国务院令第385号公布 自2003年9月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了保障经济困难的公民获得必要的法律服务，促进和规范法律援助工作，制定本条例。\n第二条 符合本条例规定的公民，可以依照本条例获得法律咨询、代理、刑事辩护等无偿法律服务。\n第三条 法律援助是政府的责任，县级以上人民政府应当采取积极措施推动法律援助工作，为法律援助提供财政支持，保障法律援助事业与经济、社会协调发展。\n法律援助经费应当专款专用，接受财政、审计部门的监督。\n第四条 国务院司法行政部门监督管理全国的法律援助工作。县级以上地方各级人民政府司法行政部门监督管理本行政区域的法律援助工作。\n中华全国律师协会和地方律师协会应当按照律师协会章程对依据本条例实施的法律援助工作予以协助。\n第五条 直辖市、设区的市或者县级人民政府司法行政部门根据需要确定本行政区域的法律援助机构。\n法律援助机构负责受理、审查法律援助申请，指派或者安排人员为符合本条例规定的公民提供法律援助。\n第六条 律师应当依照律师法和本条例的规定履行法律援助义务，为受援人提供符合标准的法律服务，依法维护受援人的合法权益，接受律师协会和司法行政部门的监督。\n第七条 国家鼓励社会对法律援助活动提供捐助。\n第八条 国家支持和鼓励社会团体、事业单位等社会组织利用自身资源为经济困难的公民提供法律援助。\n第九条 对在法律援助工作中作出突出贡献的组织和个人，有关的人民政府、司法行政部门应当给予表彰、奖励。","level":1},{"name":"第二章 法律援助范围","text":"第十条 公民对下列需要代理的事项，因经济困难没有委托代理人的，可以向法律援助机构申请法律援助：\n(一)依法请求国家赔偿的；\n(二)请求给予社会保险待遇或者最低生活保障待遇的；\n(三)请求发给抚恤金、救济金的；\n(四)请求给付赡养费、抚养费、扶养费的；\n(五)请求支付劳动报酬的；\n(六)主张因见义勇为行为产生的民事权益的。\n省、自治区、直辖市人民政府可以对前款规定以外的法律援助事项作出补充规定。\n公民可以就本条第一款、第二款规定的事项向法律援助机构申请法律咨询。\n第十一条 刑事诉讼中有下列情形之一的，公民可以向法律援助机构申请法律援助：\n(一)犯罪嫌疑人在被侦查机关第一次讯问后或者采取强制措施之日起，因经济困难没有聘请律师的；\n(二)公诉案件中的被害人及其法定代理人或者近亲属，自案件移送审查起诉之日起，因经济困难没有委托诉讼代理人的；\n(三)自诉案件的自诉人及其法定代理人，自案件被人民法院受理之日起，因经济困难没有委托诉讼代理人的。\n第十二条 公诉人出庭公诉的案件，被告人因经济困难或者其他原因没有委托辩护人，人民法院为被告人指定辩护时，法律援助机构应当提供法律援助。\n被告人是盲、聋、哑人或者未成年人而没有委托辩护人的，或者被告人可能被判处死刑而没有委托辩护人的，人民法院为被告人指定辩护时，法律援助机构应当提供法律援助，无须对被告人进行经济状况的审查。\n第十三条 本条例所称公民经济困难的标准，由省、自治区、直辖市人民政府根据本行政区域经济发展状况和法律援助事业的需要规定。\n申请人住所地的经济困难标准与受理申请的法律援助机构所在地的经济困难标准不一致的，按照受理申请的法律援助机构所在地的经济困难标准执行。","level":1},{"name":"第三章 法律援助申请和审查","text":"第十四条 公民就本条例第十条所列事项申请法律援助，应当按照下列规定提出：\n(一)请求国家赔偿的，向赔偿义务机关所在地的法律援助机构提出申请；\n(二)请求给予社会保险待遇、最低生活保障待遇或者请求发给抚恤金、救济金的，向提供社会保险待遇、最低生活保障待遇或者发给抚恤金、救济金的义务机关所在地的法律援助机构提出申请；\n(三)请求给付赡养费、抚养费、扶养费的，向给付赡养费、抚养费、扶养费的义务人住所地的法律援助机构提出申请；\n(四)请求支付劳动报酬的，向支付劳动报酬的义务人住所地的法律援助机构提出申请；\n(五)主张因见义勇为行为产生的民事权益的，向被请求人住所地的法律援助机构提出申请。\n第十五条 本条例第十一条所列人员申请法律援助的，应当向审理案件的人民法院所在地的法律援助机构提出申请。被羁押的犯罪嫌疑人的申请由看守所在24小时内转交法律援助机构，申请法律援助所需提交的有关证件、证明材料由看守所通知申请人的法定代理人或者近亲属协助提供。\n第十六条 申请人为无民事行为能力人或者限制民事行为能力人的，由其法定代理人代为提出申请。\n无民事行为能力人或者限制民事行为能力人与其法定代理人之间发生诉讼或者因其他利益纠纷需要法律援助的，由与该争议事项无利害关系的其他法定代理人代为提出申请。\n第十七条 公民申请代理、刑事辩护的法律援助应当提交下列证件、证明材料：\n(一)身份证或者其他有效的身份证明，代理申请人还应当提交有代理权的证明；\n(二)经济困难的证明；\n(三)与所申请法律援助事项有关的案件材料。\n申请应当采用书面形式，填写申请表；以书面形式提出申请确有困难的，可以口头申请，由法律援助机构工作人员或者代为转交申请的有关机构工作人员作书面记录。\n第十八条 法律援助机构收到法律援助申请后，应当进行审查；认为申请人提交的证件、证明材料不齐全的，可以要求申请人作出必要的补充或者说明，申请人未按要求作出补充或者说明的，视为撤销申请；认为申请人提交的证件、证明材料需要查证的，由法律援助机构向有关机关、单位查证。\n对符合法律援助条件的，法律援助机构应当及时决定提供法律援助；对不符合法律援助条件的，应当书面告知申请人理由。\n第十九条 申请人对法律援助机构作出的不符合法律援助条件的通知有异议的，可以向确定该法律援助机构的司法行政部门提出，司法行政部门应当在收到异议之日起5个工作日内进行审查，经审查认为申请人符合法律援助条件的，应当以书面形式责令法律援助机构及时对该申请人提供法律援助。","level":1},{"name":"第四章 法律援助实施","text":"第二十条 由人民法院指定辩护的案件，人民法院在开庭10日前将指定辩护通知书和起诉书副本或者判决书副本送交其所在地的法律援助机构；人民法院不在其所在地审判的，可以将指定辩护通知书和起诉书副本或者判决书副本送交审判地的法律援助机构。\n第二十一条 法律援助机构可以指派律师事务所安排律师或者安排本机构的工作人员办理法律援助案件；也可以根据其他社会组织的要求，安排其所属人员办理法律援助案件。对人民法院指定辩护的案件，法律援助机构应当在开庭3日前将确定的承办人员名单回复作出指定的人民法院。\n第二十二条 办理法律援助案件的人员，应当遵守职业道德和执业纪律，提供法律援助不得收取任何财物。\n第二十三条 办理法律援助案件的人员遇有下列情形之一的，应当向法律援助机构报告，法律援助机构经审查核实的，应当终止该项法律援助：\n(一)受援人的经济收入状况发生变化，不再符合法律援助条件的；\n(二)案件终止审理或者已被撤销的；\n(三)受援人又自行委托律师或者其他代理人的；\n(四)受援人要求终止法律援助的。\n第二十四条 受指派办理法律援助案件的律师或者接受安排办理法律援助案件的社会组织人员在案件结案时，应当向法律援助机构提交有关的法律文书副本或者复印件以及结案报告等材料。\n法律援助机构收到前款规定的结案材料后，应当向受指派办理法律援助案件的律师或者接受安排办理法律援助案件的社会组织人员支付法律援助办案补贴。\n法律援助办案补贴的标准由省、自治区、直辖市人民政府司法行政部门会同同级财政部门，根据当地经济发展水平，参考法律援助机构办理各类法律援助案件的平均成本等因素核定，并可以根据需要调整。\n第二十五条 法律援助机构对公民申请的法律咨询服务，应当即时办理；复杂疑难的，可以预约择时办理。","level":1},{"name":"第五章 法律责任","text":"第二十六条 法律援助机构及其工作人员有下列情形之一的，对直接负责的主管人员以及其他直接责任人员依法给予纪律处分：\n(一)为不符合法律援助条件的人员提供法律援助，或者拒绝为符合法律援助条件的人员提供法律援助的；\n(二)办理法律援助案件收取财物的；\n(三)从事有偿法律服务的；\n(四)侵占、私分、挪用法律援助经费的。\n办理法律援助案件收取的财物，由司法行政部门责令退还；从事有偿法律服务的违法所得，由司法行政部门予以没收；侵占、私分、挪用法律援助经费的，由司法行政部门责令追回，情节严重，构成犯罪的，依法追究刑事责任。\n第二十七条 律师事务所拒绝法律援助机构的指派，不安排本所律师办理法律援助案件的，由司法行政部门给予警告、责令改正；情节严重的，给予1个月以上3个月以下停业整顿的处罚。\n第二十八条 律师有下列情形之一的，由司法行政部门给予警告、责令改正；情节严重的，给予1个月以上3个月以下停止执业的处罚：\n(一)无正当理由拒绝接受、擅自终止法律援助案件的；\n(二)办理法律援助案件收取财物的。\n有前款第(二)项违法行为的，由司法行政部门责令退还违法所得的财物，可以并处所收财物价值1倍以上3倍以下的罚款。\n第二十九条 律师办理法律援助案件违反职业道德和执业纪律的，按照律师法的规定予以处罚。\n第三十条 司法行政部门工作人员在法律援助的监督管理工作中，有滥用职权、玩忽职守行为的，依法给予行政处分；情节严重，构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第三十一条 本条例自2003年9月1日起施行。","level":1}]},{"id":"n0391","sections":[{"name":"","text":"中华人民共和国国库券条例\n(1992年3月18日中华人民共和国国务院令第95号发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》修订)\n第一条 为了筹集社会资金，进行社会主义现代化建设，制定本条例。\n第二条 国库券的发行对象是：居民个人、个体工商户、企业、事业单位、机关、社会团体和其他组织。\n第三条 国库券以人民币元为计算单位。\n第四条 每年国库券的发行数额、利率、偿还期等，经国务院确定后，由财政部予以公告。\n第五条 国库券发行采取承购包销、认购等方式。\n国家下达的国库券发行计划，应当按期完成。\n第六条 国库券按期偿还本金。国库券利息在偿还本金时一次付给，不计复利。\n第七条 国库券的发行和还本付息事宜，在各级人民政府统一领导下，由财政部门和中国人民银行组织有关部门多渠道办理。\n第八条 国库券可以用于抵押，但是不得作为货币流通。\n第九条 国库券可以转让，但是应当在国家批准的交易场所办理。\n第十条 发行国库券筹集的资金，由国务院统一安排使用。\n第十一条 对伪造国库券的，依法追究刑事责任。\n对倒卖国库券的，按照投机倒把论处。(2011年1月8日删除)\n第十二条 国库券的利息收入享受免税待遇。\n第十三条 本条例由财政部负责解释。实施细则由财政部商中国人民银行制定。\n第十四条 本条例自发布之日起施行。","level":0}]},{"id":"n0392","sections":[{"name":"","text":"乡村医生从业管理条例\n(2003年7月30日国务院第16次常务会议通过 2003年8月5日中华人民共和国国务院令第386号公布 自2004年1月1日起施行)","level":0},{"name":"第一章 总则","text":"第一条 为了提高乡村医生的职业道德和业务素质，加强乡村医生从业管理，保护乡村医生的合法权益，保障村民获得初级卫生保健服务，根据《中华人民共和国执业医师法》(以下称执业医师法)的规定，制定本条例。\n第二条 本条例适用于尚未取得执业医师资格或者执业助理医师资格，经注册在村医疗卫生机构从事预防、保健和一般医疗服务的乡村医生。\n村医疗卫生机构中的执业医师或者执业助理医师，依照执业医师法的规定管理，不适用本条例。\n第三条 国务院卫生行政主管部门负责全国乡村医生的管理工作。\n县级以上地方人民政府卫生行政主管部门负责本行政区域内乡村医生的管理工作。\n第四条 国家对在农村预防、保健、医疗服务和突发事件应急处理工作中做出突出成绩的乡村医生，给予奖励。\n第五条 地方各级人民政府应当加强乡村医生的培训工作，采取多种形式对乡村医生进行培训。\n第六条 具有学历教育资格的医学教育机构，应当按照国家有关规定开展适应农村需要的医学学历教育，定向为农村培养适用的卫生人员。\n国家鼓励乡村医生学习中医药基本知识，运用中医药技能防治疾病。\n第七条 国家鼓励乡村医生通过医学教育取得医学专业学历；鼓励符合条件的乡村医生申请参加国家医师资格考试。\n第八条 国家鼓励取得执业医师资格或者执业助理医师资格的人员，开办村医疗卫生机构，或者在村医疗卫生机构向村民提供预防、保健和医疗服务。","level":1},{"name":"第二章 执业注册","text":"第九条 国家实行乡村医生执业注册制度。\n县级人民政府卫生行政主管部门负责乡村医生执业注册工作。\n第十条 本条例公布前的乡村医生，取得县级以上地方人民政府卫生行政主管部门颁发的乡村医生证书，并符合下列条件之一的，可以向县级人民政府卫生行政主管部门申请乡村医生执业注册，取得乡村医生执业证书后，继续在村医疗卫生机构执业：\n(一)已经取得中等以上医学专业学历的；\n(二)在村医疗卫生机构连续工作20年以上的；\n(三)按照省、自治区、直辖市人民政府卫生行政主管部门制定的培训规划，接受培训取得合格证书的。\n第十一条 对具有县级以上地方人民政府卫生行政主管部门颁发的乡村医生证书，但不符合本条例第十条规定条件的乡村医生，县级人民政府卫生行政主管部门应当进行有关预防、保健和一般医疗服务基本知识的培训，并根据省、自治区、直辖市人民政府卫生行政主管部门确定的考试内容、考试范围进行考试。\n前款所指的乡村医生经培训并考试合格的，可以申请乡村医生执业注册；经培训但考试不合格的，县级人民政府卫生行政主管部门应当组织对其再次培训和考试。不参加再次培训或者再次考试仍不合格的，不得申请乡村医生执业注册。\n本条所指的培训、考试，应当在本条例施行后6个月内完成。\n第十二条 本条例公布之日起进入村医疗卫生机构从事预防、保健和医疗服务的人员，应当具备执业医师资格或者执业助理医师资格。\n不具备前款规定条件的地区，根据实际需要，可以允许具有中等医学专业学历的人员，或者经培训达到中等医学专业水平的其他人员申请执业注册，进入村医疗卫生机构执业。具体办法由省、自治区、直辖市人民政府制定。\n第十三条 符合本条例规定申请在村医疗卫生机构执业的人员，应当持村医疗卫生机构出具的拟聘用证明和相关学历证明、证书，向村医疗卫生机构所在地的县级人民政府卫生行政主管部门申请执业注册。\n县级人民政府卫生行政主管部门应当自受理申请之日起15日内完成审核工作，对符合本条例规定条件的，准予执业注册，发给乡村医生执业证书；对不符合本条例规定条件的，不予注册，并书面说明理由。\n第十四条 乡村医生有下列情形之一的，不予注册：\n(一)不具有完全民事行为能力的；\n(二)受刑事处罚，自刑罚执行完毕之日起至申请执业注册之日止不满2年的；\n(三)受吊销乡村医生执业证书行政处罚，自处罚决定之日起至申请执业注册之日止不满2年的。\n第十五条 乡村医生经注册取得执业证书后，方可在聘用其执业的村医疗卫生机构从事预防、保健和一般医疗服务。\n未经注册取得乡村医生执业证书的，不得执业。\n第十六条 乡村医生执业证书有效期为5年。\n乡村医生执业证书有效期满需要继续执业的，应当在有效期满前3个月申请再注册。\n县级人民政府卫生行政主管部门应当自受理申请之日起15日内进行审核，对符合省、自治区、直辖市人民政府卫生行政主管部门规定条件的，准予再注册，换发乡村医生执业证书；对不符合条件的，不予再注册，由发证部门收回原乡村医生执业证书。\n第十七条 乡村医生应当在聘用其执业的村医疗卫生机构执业；变更执业的村医疗卫生机构的，应当依照本条例第十三条规定的程序办理变更注册手续。\n第十八条 乡村医生有下列情形之一的，由原注册的卫生行政主管部门注销执业注册，收回乡村医生执业证书：\n(一)死亡或者被宣告失踪的；\n(二)受刑事处罚的；\n(三)中止执业活动满2年的；\n(四)考核不合格，逾期未提出再次考核申请或者经再次考核仍不合格的。\n第十九条 县级人民政府卫生行政主管部门应当将准予执业注册、再注册和注销注册的人员名单向其执业的村医疗卫生机构所在地的村民公告，并由设区的市级人民政府卫生行政主管部门汇总，报省、自治区、直辖市人民政府卫生行政主管部门备案。\n第二十条 县级人民政府卫生行政主管部门办理乡村医生执业注册、再注册、注销注册，应当依据法定权限、条件和程序，遵循便民原则，提高办事效率。\n第二十一条 村民和乡村医生发现违法办理乡村医生执业注册、再注册、注销注册的，可以向有关人民政府卫生行政主管部门反映；有关人民政府卫生行政主管部门对反映的情况应当及时核实，调查处理，并将调查处理结果予以公布。\n第二十二条 上级人民政府卫生行政主管部门应当加强对下级人民政府卫生行政主管部门办理乡村医生执业注册、再注册、注销注册的监督检查，及时纠正违法行为。","level":1},{"name":"第三章 执业规则","text":"第二十三条 乡村医生在执业活动中享有下列权利：\n(一)进行一般医学处置，出具相应的医学证明；\n(二)参与医学经验交流，参加专业学术团体；\n(三)参加业务培训和教育；\n(四)在执业活动中，人格尊严、人身安全不受侵犯；\n(五)获取报酬；\n(六)对当地的预防、保健、医疗工作和卫生行政主管部门的工作提出意见和建议。\n第二十四条 乡村医生在执业活动中应当履行下列义务：\n(一)遵守法律、法规、规章和诊疗护理技术规范、常规；\n(二)树立敬业精神，遵守职业道德，履行乡村医生职责，为村民健康服务；\n(三)关心、爱护、尊重患者，保护患者的隐私；\n(四)努力钻研业务，更新知识，提高专业技术水平；\n(五)向村民宣传卫生保健知识，对患者进行健康教育。\n第二十五条 乡村医生应当协助有关部门做好初级卫生保健服务工作；按照规定及时报告传染病疫情和中毒事件，如实填写并上报有关卫生统计报表，妥善保管有关资料。\n第二十六条 乡村医生在执业活动中，不得重复使用一次性医疗器械和卫生材料。对使用过的一次性医疗器械和卫生材料，应当按照规定处置。\n第二十七条 乡村医生应当如实向患者或者其家属介绍病情，对超出一般医疗服务范围或者限于医疗条件和技术水平不能诊治的病人，应当及时转诊；情况紧急不能转诊的，应当先行抢救并及时向有抢救条件的医疗卫生机构求助。\n第二十八条 乡村医生不得出具与执业范围无关或者与执业范围不相符的医学证明，不得进行实验性临床医疗活动。\n第二十九条 省、自治区、直辖市人民政府卫生行政主管部门应当按照乡村医生一般医疗服务范围，制定乡村医生基本用药目录。乡村医生应当在乡村医生基本用药目录规定的范围内用药。\n第三十条 县级人民政府对乡村医生开展国家规定的预防、保健等公共卫生服务，应当按照有关规定予以补助。","level":1},{"name":"第四章 培训与考核","text":"第三十一条 省、自治区、直辖市人民政府组织制定乡村医生培训规划，保证乡村医生至少每2年接受一次培训。县级人民政府根据培训规划制定本地区乡村医生培训计划。\n对承担国家规定的预防、保健等公共卫生服务的乡村医生，其培训所需经费列入县级财政预算。对边远贫困地区，设区的市级以上地方人民政府应当给予适当经费支持。\n国家鼓励社会组织和个人支持乡村医生培训工作。\n第三十二条 县级人民政府卫生行政主管部门根据乡村医生培训计划，负责组织乡村医生的培训工作。\n乡、镇人民政府以及村民委员会应当为乡村医生开展工作和学习提供条件，保证乡村医生接受培训和继续教育。\n第三十三条 乡村医生应当按照培训规划的要求至少每2年接受一次培训，更新医学知识，提高业务水平。\n第三十四条 县级人民政府卫生行政主管部门负责组织本地区乡村医生的考核工作；对乡村医生的考核，每2年组织一次。\n对乡村医生的考核应当客观、公正，充分听取乡村医生执业的村医疗卫生机构、乡村医生本人、所在村村民委员会和村民的意见。\n第三十五条 县级人民政府卫生行政主管部门负责检查乡村医生执业情况，收集村民对乡村医生业务水平、工作质量的评价和建议，接受村民对乡村医生的投诉，并进行汇总、分析。汇总、分析结果与乡村医生接受培训的情况作为对乡村医生进行考核的主要内容。\n第三十六条 乡村医生经考核合格的，可以继续执业；经考核不合格的，在6个月之内可以申请进行再次考核。逾期未提出再次考核申请或者经再次考核仍不合格的乡村医生，原注册部门应当注销其执业注册，并收回乡村医生执业证书。\n第三十七条 有关人民政府卫生行政主管部门对村民和乡村医生提出的意见、建议和投诉，应当及时调查处理，并将调查处理结果告知村民或者乡村医生。","level":1},{"name":"第五章 法律责任","text":"第三十八条 乡村医生在执业活动中，违反本条例规定，有下列行为之一的，由县级人民政府卫生行政主管部门责令限期改正，给予警告；逾期不改正的，责令暂停3个月以上6个月以下执业活动；情节严重的，由原发证部门暂扣乡村医生执业证书：\n(一)执业活动超出规定的执业范围，或者未按照规定进行转诊的；\n(二)违反规定使用乡村医生基本用药目录以外的处方药品的；\n(三)违反规定出具医学证明，或者伪造卫生统计资料的；\n(四)发现传染病疫情、中毒事件不按规定报告的。\n第三十九条 乡村医生在执业活动中，违反规定进行实验性临床医疗活动，或者重复使用一次性医疗器械和卫生材料的，由县级人民政府卫生行政主管部门责令停止违法行为，给予警告，可以并处1000元以下的罚款；情节严重的，由原发证部门暂扣或者吊销乡村医生执业证书。\n第四十条 乡村医生变更执业的村医疗卫生机构，未办理变更执业注册手续的，由县级人民政府卫生行政主管部门给予警告，责令限期办理变更注册手续。\n第四十一条 以不正当手段取得乡村医生执业证书的，由发证部门收缴乡村医生执业证书；造成患者人身损害的，依法承担民事赔偿责任；构成犯罪的，依法追究刑事责任。\n第四十二条 未经注册在村医疗卫生机构从事医疗活动的，由县级以上地方人民政府卫生行政主管部门予以取缔，没收其违法所得以及药品、医疗器械，违法所得5000元以上的，并处违法所得1倍以上3倍以下的罚款；没有违法所得或者违法所得不足5000元的，并处1000元以上3000元以下的罚款；造成患者人身损害的，依法承担民事赔偿责任；构成犯罪的，依法追究刑事责任。\n第四十三条 县级人民政府卫生行政主管部门未按照乡村医生培训规划、计划组织乡村医生培训的，由本级人民政府或者上一级人民政府卫生行政主管部门责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。\n第四十四条 县级人民政府卫生行政主管部门，对不符合本条例规定条件的人员发给乡村医生执业证书，或者对符合条件的人员不发给乡村医生执业证书的，由本级人民政府或者上一级人民政府卫生行政主管部门责令改正，收回或者补发乡村医生执业证书，并对直接负责的主管人员和其他直接责任人员依法给予行政处分。\n第四十五条 县级人民政府卫生行政主管部门对乡村医生执业注册或者再注册申请，未在规定时间内完成审核工作的，或者未按照规定将准予执业注册、再注册和注销注册的人员名单向村民予以公告的，由本级人民政府或者上一级人民政府卫生行政主管部门责令限期改正；逾期不改正的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。\n第四十六条 卫生行政主管部门对村民和乡村医生反映的办理乡村医生执业注册、再注册、注销注册的违法活动未及时核实、调查处理或者未公布调查处理结果的，由本级人民政府或者上一级人民政府卫生行政主管部门责令限期改正；逾期不改正的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。\n第四十七条 寻衅滋事、阻碍乡村医生依法执业，侮辱、诽谤、威胁、殴打乡村医生，构成违反治安管理行为的，由公安机关依法予以处罚；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附则","text":"第四十八条 乡村医生执业证书格式由国务院卫生行政主管部门规定。\n第四十九条 本条例自2004年1月1日起施行。","level":1}]},{"id":"n0393","sections":[{"name":"","text":"矿产资源勘查区块登记管理办法\n(1998年2月12日中华人民共和国国务院令第240号发布 根据2014年7月29日《国务院关于修改部分行政法规的决定》修订)\n第一条 为了加强对矿产资源勘查的管理，保护探矿权人的合法权益，维护矿产资源勘查秩序，促进矿业发展，根据《中华人民共和国矿产资源法》，制定本办法。\n第二条 在中华人民共和国领域及管辖的其他海域勘查矿产资源，必须遵守本办法。\n第三条 国家对矿产资源勘查实行统一的区块登记管理制度。矿产资源勘查工作区范围以经纬度1′×1′划分的区块为基本单位区块。每个勘查项目允许登记的最大范围：\n(一)矿泉水为10个基本单位区块；\n(二)金属矿产、非金属矿产、放射性矿产为40个基本单位区块；\n(三)地热、煤、水气矿产为200个基本单位区块；\n(四)石油、天然气矿产为2500个基本单位区块。\n第四条 勘查下列矿产资源，由国务院地质矿产主管部门审批登记，颁发勘查许可证：\n(一)跨省、自治区、直辖市的矿产资源；\n(二)领海及中国管辖的其他海域的矿产资源；\n(三)外商投资勘查的矿产资源；\n(四)本办法附录所列的矿产资源。\n勘查石油、天然气矿产的，经国务院指定的机关审查同意后，由国务院地质矿产主管部门登记，颁发勘查许可证。\n勘查下列矿产资源，由省、自治区、直辖市人民政府地质矿产主管部门审批登记，颁发勘查许可证，并应当自发证之日起10日内，向国务院地质矿产主管部门备案：\n(一)本条第一款、第二款规定以外的矿产资源；\n(二)国务院地质矿产主管部门授权省、自治区、直辖市人民政府地质矿产主管部门审批登记的矿产资源。\n第五条 勘查出资人为探矿权申请人；但是，国家出资勘查的，国家委托勘查的单位为探矿权申请人。\n第六条 探矿权申请人申请探矿权时，应当向登记管理机关提交下列资料：\n(一)申请登记书和申请的区块范围图；\n(二)勘查单位的资格证书复印件；\n(三)勘查工作计划、勘查合同或者委托勘查的证明文件；\n(四)勘查实施方案及附件；\n(五)勘查项目资金来源证明；\n(六)国务院地质矿产主管部门规定提交的其他资料。\n申请勘查石油、天然气的，还应当提交国务院批准设立石油公司或者同意进行石油、天然气勘查的批准文件以及勘查单位法人资格证明。\n第七条 申请石油、天然气滚动勘探开发的，应当向登记管理机关提交下列资料，经批准，办理登记手续，领取滚动勘探开发的采矿许可证：\n(一)申请登记书和滚动勘探开发矿区范围图；\n(二)国务院计划主管部门批准的项目建议书；\n(三)需要进行滚动勘探开发的论证材料；\n(四)经国务院矿产储量审批机构批准进行石油、天然气滚动勘探开发的储量报告；\n(五)滚动勘探开发利用方案。\n第八条 登记管理机关应当自收到申请之日起40日内，按照申请在先的原则作出准予登记或者不予登记的决定，并通知探矿权申请人。对申请勘查石油、天然气的，登记管理机关还应当在收到申请后及时予以公告或者提供查询。\n登记管理机关应当保证国家地质勘查计划一类项目的登记，具体办法由国务院地质矿产主管部门会同国务院计划主管部门制定。\n需要探矿权申请人修改或者补充本办法第六条规定的资料的，登记管理机关应当通知探矿权申请人限期修改或者补充。\n准予登记时，探矿权申请人应当自收到通知之日起30日内，依照本办法第十二条的规定缴纳探矿权使用费，并依照本办法第十三条的规定缴纳国家出资勘查形成的探矿权价款，办理登记手续，领取勘查许可证，成为探矿权人。\n不予登记的，登记管理机关应当向探矿权申请人说明理由。\n第九条 禁止任何单位和个人进入他人依法取得探矿权的勘查作业区内进行勘查或者采矿活动。\n探矿权人与采矿权人对勘查作业区范围和矿区范围发生争议的，由当事人协商解决；协商不成的，由发证的登记管理机关中级别高的登记管理机关裁决。\n第十条 勘查许可证有效期最长为3年；但是，石油、天然气勘查许可证有效期最长为7年。需要延长勘查工作时间的，探矿权人应当在勘查许可证有效期届满的30日前，到登记管理机关办理延续登记手续，每次延续时间不得超过2年。\n探矿权人逾期不办理延续登记手续的，勘查许可证自行废止。\n石油、天然气滚动勘探开发的采矿许可证有效期最长为15年；但是，探明储量的区块，应当申请办理采矿许可证。\n第十一条 登记管理机关应当自颁发勘查许可证之日起10日内，将登记发证项目的名称、探矿权人、区块范围和勘查许可证期限等事项，通知勘查项目所在地的县级人民政府负责地质矿产管理工作的部门。\n登记管理机关对勘查区块登记发证情况，应当定期予以公告。\n第十二条 国家实行探矿权有偿取得的制度。探矿权使用费以勘查年度计算，逐年缴纳。\n探矿权使用费标准：第一个勘查年度至第三个勘查年度，每平方公里每年缴纳100元；从第四个勘查年度起，每平方公里每年增加100元，但是最高不得超过每平方公里每年500元。\n第十三条 申请国家出资勘查并已经探明矿产地的区块的探矿权的，探矿权申请人除依照本办法第十二条的规定缴纳探矿权使用费外，还应当缴纳国家出资勘查形成的探矿权价款；探矿权价款按照国家有关规定，可以一次缴纳，也可以分期缴纳。\n国家出资勘查形成的探矿权价款，由具有矿业权评估资质的评估机构进行评估；评估报告报登记管理机关备案。\n第十四条 探矿权使用费和国家出资勘查形成的探矿权价款，由登记管理机关收取，全部纳入国家预算管理。具体管理、使用办法，由国务院地质矿产主管部门会同国务院财政部门、计划主管部门制定。\n第十五条 有下列情形之一的，由探矿权人提出申请，经登记管理机关按照国务院地质矿产主管部门会同国务院财政部门制定的探矿权使用费和探矿权价款的减免办法审查批准，可以减缴、免缴探矿权使用费和探矿权价款：\n(一)国家鼓励勘查的矿种；\n(二)国家鼓励勘查的区域；\n(三)国务院地质矿产主管部门会同国务院财政部门规定的其他情形。\n第十六条 探矿权可以通过招标投标的方式有偿取得。\n登记管理机关依照本办法第四条规定的权限确定招标区块，发布招标公告，提出投标要求和截止日期；但是，对境外招标的区块由国务院地质矿产主管部门确定。\n登记管理机关组织评标，采取择优原则确定中标人。中标人缴纳本办法第十二条、第十三条规定的费用后，办理登记手续，领取勘查许可证，成为探矿权人，并履行标书中承诺的义务。\n第十七条 探矿权人应当自领取勘查许可证之日起，按照下列规定完成最低勘查投入：\n(一)第一个勘查年度，每平方公里2000元；\n(二)第二个勘查年度，每平方公里5000元；\n(三)从第三个勘查年度起，每个勘查年度每平方公里10000元。\n探矿权人当年度的勘查投入高于最低勘查投入标准的，高于的部分可以计入下一个勘查年度的勘查投入。\n因自然灾害等不可抗力的原因，致使勘查工作不能正常进行的，探矿权人应当自恢复正常勘查工作之日起30日内，向登记管理机关提交申请核减相应的最低勘查投入的报告；登记管理机关应当自收到报告之日起30日内予以批复。\n第十八条 探矿权人应当自领取勘查许可证之日起6个月内开始施工；在开始勘查工作时，应当向勘查项目所在地的县级人民政府负责地质矿产管理工作的部门报告，并向登记管理机关报告开工情况。\n第十九条 探矿权人在勘查许可证有效期内进行勘查时，发现符合国家边探边采规定要求的复杂类型矿床的，可以申请开采，经登记管理机关批准，办理采矿登记手续。\n第二十条 探矿权人在勘查石油、天然气等流体矿产期间，需要试采的，应当向登记管理机关提交试采申请，经批准后可以试采1年；需要延长试采时间的，必须办理登记手续。\n第二十一条 探矿权人在勘查许可证有效期内探明可供开采的矿体后，经登记管理机关批准，可以停止相应区块的最低勘查投入，并可以在勘查许可证有效期届满的30日前，申请保留探矿权。但是，国家为了公共利益或者因技术条件暂时难以利用等情况，需要延期开采的除外。\n保留探矿权的期限，最长不得超过2年，需要延长保留期的，可以申请延长2次，每次不得超过2年；保留探矿权的范围为可供开采的矿体范围。\n在停止最低勘查投入期间或者探矿权保留期间，探矿权人应当依照本办法的规定，缴纳探矿权使用费。\n探矿权保留期届满，勘查许可证应当予以注销。\n第二十二条 有下列情形之一的，探矿权人应当在勘查许可证有效期内，向登记管理机关申请变更登记：\n(一)扩大或者缩小勘查区块范围的；\n(二)改变勘查工作对象的；\n(三)经依法批准转让探矿权的；\n(四)探矿权人改变名称或者地址的。\n第二十三条 探矿权延续登记和变更登记，其勘查年度、探矿权使用费和最低勘查投入连续计算。\n第二十四条 有下列情形之一的，探矿权人应当在勘查许可证有效期内，向登记管理机关递交勘查项目完成报告或者勘查项目终止报告，报送资金投入情况报表和有关证明文件，由登记管理机关核定其实际勘查投入后，办理勘查许可证注销登记手续：\n(一)勘查许可证有效期届满，不办理延续登记或者不申请保留探矿权的；\n(二)申请采矿权的；\n(三)因故需要撤销勘查项目的。\n自勘查许可证注销之日起90日内，原探矿权人不得申请已经注销的区块范围内的探矿权。\n第二十五条 登记管理机关需要调查勘查投入、勘查工作进展情况，探矿权人应当如实报告并提供有关资料，不得虚报、瞒报，不得拒绝检查。\n对探矿权人要求保密的申请登记资料、勘查工作成果资料和财务报表，登记管理机关应当予以保密。\n第二十六条 违反本办法规定，未取得勘查许可证擅自进行勘查工作的，超越批准的勘查区块范围进行勘查工作的，由县级以上人民政府负责地质矿产管理工作的部门按照国务院地质矿产主管部门规定的权限，责令停止违法行为，予以警告，可以并处10万元以下的罚款。\n第二十七条 违反本办法规定，未经批准，擅自进行滚动勘探开发、边探边采或者试采的，由县级以上人民政府负责地质矿产管理工作的部门按照国务院地质矿产主管部门规定的权限，责令停止违法行为，予以警告，没收违法所得，可以并处10万元以下的罚款。\n第二十八条 违反本办法规定，擅自印制或者伪造、冒用勘查许可证的，由县级以上人民政府负责地质矿产管理工作的部门按照国务院地质矿产主管部门规定的权限，没收违法所得，可以并处10万元以下的罚款；构成犯罪的，依法追究刑事责任。\n第二十九条 违反本办法规定，有下列行为之一的，由县级以上人民政府负责地质矿产管理工作的部门按照国务院地质矿产主管部门规定的权限，责令限期改正；逾期不改正的，处5万元以下的罚款；情节严重的，原发证机关可以吊销勘查许可证：\n(一)不按照本办法的规定备案、报告有关情况、拒绝接受监督检查或者弄虚作假的；\n(二)未完成最低勘查投入的；\n(三)已经领取勘查许可证的勘查项目，满6个月未开始施工，或者施工后无故停止勘查工作满6个月的。\n第三十条 违反本办法规定，不办理勘查许可证变更登记或者注销登记手续的，由登记管理机关责令限期改正；逾期不改正的，由原发证机关吊销勘查许可证。\n第三十一条 违反本办法规定，不按期缴纳本办法规定应当缴纳的费用的，由登记管理机关责令限期缴纳，并从滞纳之日起每日加收2‰的滞纳金；逾期仍不缴纳的，由原发证机关吊销勘查许可证。\n第三十二条 违反本办法规定勘查石油、天然气矿产的，由国务院地质矿产主管部门按照本办法的有关规定给予行政处罚。\n第三十三条 探矿权人被吊销勘查许可证的，自勘查许可证被吊销之日起6个月内，不得再申请探矿权。\n第三十四条 登记管理机关工作人员徇私舞弊、滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。\n第三十五条 勘查许可证由国务院地质矿产主管部门统一印制。申请登记书、变更申请登记书、探矿权保留申请登记书和注销申请登记书的格式，由国务院地质矿产主管部门统一制定。\n第三十六条 办理勘查登记手续，应当按照规定缴纳登记费。收费标准和管理、使用办法，由国务院物价主管部门会同国务院地质矿产主管部门、财政部门规定。\n第三十七条 外商投资勘查矿产资源的，依照本办法的规定办理；法律、行政法规另有特别规定的，从其规定。\n第三十八条 中外合作勘查矿产资源的，中方合作者应当在签订合同后，将合同向原发证机关备案。\n第三十九条 本办法施行前已经取得勘查许可证的，由国务院地质矿产主管部门统一组织换领新的勘查许可证。探矿权使用费、最低勘查投入按照重新登记后的第一个勘查年度计算，并可以依照本办法的规定申请减缴、免缴。\n第四十条 本办法附录的修改，由国务院地质矿产主管部门报国务院批准后公布。\n第四十一条 本办法自发布之日起施行。1987年4月29日国务院发布的《矿产资源勘查登记管理暂行办法》和1987年12月16日国务院批准、石油工业部发布的《石油及天然气勘查、开采登记管理暂行办法》同时废止。","level":0},{"name":"附录","text":"国务院地质矿产主管部门审批发证矿种目录\n1 煤 18 锌\n2 石油 19 铝\n3 油页岩 20 镍\n4 烃类天然气 21 钨\n5 二氧化碳气 22 锡\n6 煤成(层)气 23 锑\n7 地热 24 钼\n8 放射性矿产 25 稀土\n9 金 26 磷\n10 银 27 钾\n11 铂 28 硫\n12 锰 29 锶\n13 铬 30 金刚石\n14 钴 31 铌\n15 铁 32 钽\n16 铜 33 石棉\n17 铅 34 矿泉水","level":1}]},{"id":"n0394","sections":[{"name":"","text":"中央储备粮管理条例\n(2003年8月15日中华人民共和国国务院令第388号公布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2016年2月6日《国务院关于修改部分行政法规的决定》第二次修订)","level":0},{"name":"第一章 总则","text":"第一条 为了加强对中央储备粮的管理，保证中央储备粮数量真实、质量良好和储存安全，保护农民利益，维护粮食市场稳定，有效发挥中央储备粮在国家宏观调控中的作用，制定本条例。\n第二条 本条例所称中央储备粮，是指中央政府储备的用于调节全国粮食供求总量，稳定粮食市场，以及应对重大自然灾害或者其他突发事件等情况的粮食和食用油。\n第三条 从事和参与中央储备粮经营管理、监督活动的单位和个人，必须遵守本条例。\n第四条 国家实行中央储备粮垂直管理体制，地方各级人民政府及有关部门应当对中央储备粮的垂直管理给予支持和协助。\n第五条 中央储备粮的管理应当严格制度、严格管理、严格责任，确保中央储备粮数量真实、质量良好和储存安全，确保中央储备粮储得进、管得好、调得动、用得上并节约成本、费用。\n未经国务院批准，任何单位和个人不得擅自动用中央储备粮。\n第六条 国务院发展改革部门及国家粮食行政管理部门会同国务院财政部门负责拟订中央储备粮规模总量、总体布局和动用的宏观调控意见，对中央储备粮管理进行指导和协调；国家粮食行政管理部门负责中央储备粮的行政管理，对中央储备粮的数量、质量和储存安全实施监督检查。\n第七条 国务院财政部门负责安排中央储备粮的贷款利息、管理费用等财政补贴，并保证及时、足额拨付；负责对中央储备粮有关财务执行情况实施监督检查。\n第八条 中国储备粮管理总公司具体负责中央储备粮的经营管理，并对中央储备粮的数量、质量和储存安全负责。\n中国储备粮管理总公司依照国家有关中央储备粮管理的行政法规、规章、国家标准和技术规范，建立、健全中央储备粮各项业务管理制度，并报国家粮食行政管理部门备案。\n第九条 中国农业发展银行负责按照国家有关规定，及时、足额安排中央储备粮所需贷款，并对发放的中央储备粮贷款实施信贷监管。\n第十条 任何单位和个人不得以任何方式骗取、挤占、截留、挪用中央储备粮贷款或者贷款利息、管理费用等财政补贴。\n第十一条 任何单位和个人不得破坏中央储备粮的仓储设施，不得偷盗、哄抢或者损毁中央储备粮。\n中央储备粮储存地的地方人民政府对破坏中央储备粮仓储设施，偷盗、哄抢或者损毁中央储备粮的违法行为，应当及时组织有关部门予以制止、查处。\n第十二条 任何单位和个人对中央储备粮经营管理中的违法行为，均有权向国家粮食行政管理部门等有关部门举报。国家粮食行政管理部门等有关部门接到举报后，应当及时查处；举报事项的处理属于其他部门职责范围的，应当及时移送其他部门处理。","level":1},{"name":"第二章 中央储备粮的计划","text":"第十三条 中央储备粮的储存规模、品种和总体布局方案，由国务院发展改革部门及国家粮食行政管理部门会同国务院财政部门，根据国家宏观调控需要和财政承受能力提出，报国务院批准。\n第十四条 中央储备粮的收购、销售计划，由国家粮食行政管理部门根据国务院批准的中央储备粮储存规模、品种和总体布局方案提出建议，经国务院发展改革部门、国务院财政部门审核同意后，由国务院发展改革部门及国家粮食行政管理部门会同国务院财政部门和中国农业发展银行共同下达中国储备粮管理总公司。\n第十五条 中国储备粮管理总公司根据中央储备粮的收购、销售计划，具体组织实施中央储备粮的收购、销售。\n第十六条 中央储备粮实行均衡轮换制度，每年轮换的数量一般为中央储备粮储存总量的20%至30%。\n中国储备粮管理总公司应当根据中央储备粮的品质情况和入库年限，提出中央储备粮年度轮换的数量、品种和分地区计划，报国家粮食行政管理部门、国务院财政部门和中国农业发展银行批准。中国储备粮管理总公司在年度轮换计划内根据粮食市场供求状况，具体组织实施中央储备粮的轮换。\n第十七条 中国储备粮管理总公司应当将中央储备粮收购、销售、年度轮换计划的具体执行情况，及时报国务院发展改革部门、国家粮食行政管理部门和国务院财政部门备案，并抄送中国农业发展银行。","level":1},{"name":"第三章 中央储备粮的储存","text":"第十八条 中国储备粮管理总公司直属企业为专门储存中央储备粮的企业。\n中央储备粮也可以依照本条例的规定由具备条件的其他企业代储。\n第十九条 代储中央储备粮的企业，应当具备下列条件：\n(一)仓库容量达到国家规定的规模，仓库条件符合国家标准和技术规范的要求；\n(二)具有与粮食储存功能、仓型、进出粮方式、粮食品种、储粮周期等相适应的仓储设备；\n(三)具有符合国家标准的中央储备粮质量等级检测仪器和场所，具备检测中央储备粮储存期间仓库内温度、水分、害虫密度的条件；\n(四)具有经过专业培训的粮油保管员、粮油质量检验员等管理技术人员；\n(五)经营管理和信誉良好，并无严重违法经营记录。\n选择代储中央储备粮的企业，应当遵循有利于中央储备粮的合理布局，有利于中央储备粮的集中管理和监督，有利于降低中央储备粮成本、费用的原则。\n第二十条 具备本条例第十九条规定代储条件的企业，经国家粮食行政管理部门审核同意，取得代储中央储备粮的资格。\n企业代储中央储备粮的资格认定办法，由国家粮食行政管理部门会同国务院财政部门，并征求中国农业发展银行和中国储备粮管理总公司的意见制定。\n第二十一条 中国储备粮管理总公司负责从取得代储中央储备粮资格的企业中，根据中央储备粮的总体布局方案择优选定中央储备粮代储企业，报国家粮食行政管理部门、国务院财政部门和中国农业发展银行备案，并抄送当地粮食行政管理部门。\n中国储备粮管理总公司应当与中央储备粮代储企业签订合同，明确双方的权利、义务和违约责任等事项。\n中央储备粮代储企业不得将中央储备粮轮换业务与其他业务混合经营。\n第二十二条 中国储备粮管理总公司直属企业、中央储备粮代储企业(以下统称承储企业)储存中央储备粮，应当严格执行国家有关中央储备粮管理的行政法规、规章、国家标准和技术规范，以及中国储备粮管理总公司依照有关行政法规、规章、国家标准和技术规范制定的各项业务管理制度。\n第二十三条 承储企业必须保证入库的中央储备粮达到收购、轮换计划规定的质量等级，并符合国家规定的质量标准。\n第二十四条 承储企业应当对中央储备粮实行专仓储存、专人保管、专账记载，保证中央储备粮账账相符、账实相符、质量良好、储存安全。\n第二十五条 承储企业不得虚报、瞒报中央储备粮的数量，不得在中央储备粮中掺杂掺假、以次充好，不得擅自串换中央储备粮的品种、变更中央储备粮的储存地点，不得因延误轮换或者管理不善造成中央储备粮陈化、霉变。\n第二十六条 承储企业不得以低价购进高价入账、高价售出低价入账、以旧粮顶替新粮、虚增入库成本等手段套取差价，骗取中央储备粮贷款和贷款利息、管理费用等财政补贴。\n第二十七条 承储企业应当建立、健全中央储备粮的防火、防盗、防洪等安全管理制度，并配备必要的安全防护设施。\n地方各级人民政府应当支持本行政区域内的承储企业做好中央储备粮的安全管理工作。\n第二十八条 承储企业应当对中央储备粮的储存管理状况进行经常性检查；发现中央储备粮数量、质量和储存安全等方面的问题，应当及时处理；不能处理的，承储企业的主要负责人必须及时报告中国储备粮管理总公司或者其分支机构。\n第二十九条 承储企业应当在轮换计划规定的时间内完成中央储备粮的轮换。\n中央储备粮的轮换应当遵循有利于保证中央储备粮的数量、质量和储存安全，保持粮食市场稳定，防止造成市场粮价剧烈波动，节约成本、提高效率的原则。\n中央储备粮轮换的具体管理办法，由国务院发展改革部门及国家粮食行政管理部门会同国务院财政部门，并征求中国农业发展银行和中国储备粮管理总公司的意见制定。\n第三十条 中央储备粮的收购、销售、轮换原则上应当通过规范的粮食批发市场公开进行，也可以通过国家规定的其他方式进行。\n第三十一条 承储企业不得以中央储备粮对外进行担保或者对外清偿债务。\n承储企业依法被撤销、解散或者破产的，其储存的中央储备粮由中国储备粮管理总公司负责调出另储。\n第三十二条 中央储备粮的管理费用补贴实行定额包干，由国务院财政部门拨付给中国储备粮管理总公司；中国储备粮管理总公司按照国务院财政部门的有关规定，通过中国农业发展银行补贴专户，及时、足额拨付到承储企业。中国储备粮管理总公司在中央储备粮管理费用补贴包干总额内，可以根据不同储存条件和实际费用水平，适当调整不同地区、不同品种、不同承储企业的管理费用补贴标准；但同一地区、同一品种、储存条件基本相同的承储企业的管理费用补贴标准原则上应当一致。\n中央储备粮的贷款利息实行据实补贴，由国务院财政部门拨付。\n第三十三条 中央储备粮贷款实行贷款与粮食库存值增减挂钩和专户管理、专款专用。\n承储企业应当在中国农业发展银行开立基本账户，并接受中国农业发展银行的信贷监管。\n中国储备粮管理总公司应当创造条件，逐步实行中央储备粮贷款统借统还。\n第三十四条 中央储备粮的入库成本由国务院财政部门负责核定。中央储备粮的入库成本一经核定，中国储备粮管理总公司及其分支机构和承储企业必须遵照执行。\n任何单位和个人不得擅自更改中央储备粮入库成本。\n第三十五条 国家建立中央储备粮损失、损耗处理制度，及时处理所发生的损失、损耗。具体办法由国务院财政部门会同国家粮食行政管理部门，并征求中国储备粮管理总公司和中国农业发展银行的意见制定。\n第三十六条 中国储备粮管理总公司应当定期统计、分析中央储备粮的储存管理情况，并将统计、分析情况报送国务院发展改革部门、国家粮食行政管理部门、国务院财政部门及中国农业发展银行。","level":1},{"name":"第四章 中央储备粮的动用","text":"第三十七条 国务院发展改革部门及国家粮食行政管理部门，应当完善中央储备粮的动用预警机制，加强对需要动用中央储备粮情况的监测，适时提出动用中央储备粮的建议。\n第三十八条 出现下列情况之一的，可以动用中央储备粮：\n(一)全国或者部分地区粮食明显供不应求或者市场价格异常波动；\n(二)发生重大自然灾害或者其他突发事件需要动用中央储备粮；\n(三)国务院认为需要动用中央储备粮的其他情形。\n第三十九条 动用中央储备粮，由国务院发展改革部门及国家粮食行政管理部门会同国务院财政部门提出动用方案，报国务院批准。动用方案应当包括动用中央储备粮的品种、数量、质量、价格、使用安排、运输保障等内容。\n第四十条 国务院发展改革部门及国家粮食行政管理部门，根据国务院批准的中央储备粮动用方案下达动用命令，由中国储备粮管理总公司具体组织实施。\n紧急情况下，国务院直接决定动用中央储备粮并下达动用命令。\n国务院有关部门和有关地方人民政府对中央储备粮动用命令的实施，应当给予支持、配合。\n第四十一条 任何单位和个人不得拒绝执行或者擅自改变中央储备粮动用命令。","level":1},{"name":"第五章 监督检查","text":"第四十二条 国家粮食行政管理部门、国务院财政部门按照各自职责，依法对中国储备粮管理总公司及其分支机构、承储企业执行本条例及有关粮食法规的情况，进行监督检查。在监督检查过程中，可以行使下列职权：\n(一)进入承储企业检查中央储备粮的数量、质量和储存安全；\n(二)向有关单位和人员了解中央储备粮收购、销售、轮换计划及动用命令的执行情况；\n(三)调阅中央储备粮经营管理的有关资料、凭证；\n(四)对违法行为，依法予以处理。\n第四十三条 国家粮食行政管理部门、国务院财政部门在监督检查中，发现中央储备粮数量、质量、储存安全等方面存在问题，应当责成中国储备粮管理总公司及其分支机构、承储企业立即予以纠正或者处理；发现中央储备粮代储企业不再具备代储条件，国家粮食行政管理部门应当取消其代储资格；发现中国储备粮管理总公司直属企业存在不适于储存中央储备粮的情况，国家粮食行政管理部门应当责成中国储备粮管理总公司对有关直属企业限期整改。\n第四十四条 国家粮食行政管理部门、国务院财政部门的监督检查人员应当将监督检查情况作出书面记录，并由监督检查人员和被检查单位的负责人签字。被检查单位的负责人拒绝签字的，监督检查人员应当将有关情况记录在案。\n第四十五条 审计机关依照审计法规定的职权和程序，对有关中央储备粮的财务收支情况实施审计监督；发现问题，应当及时予以处理。\n第四十六条 中国储备粮管理总公司及其分支机构、承储企业，对国家粮食行政管理部门、国务院财政部门、审计机关的监督检查人员依法履行职责，应当予以配合。\n任何单位和个人不得拒绝、阻挠、干涉国家粮食行政管理部门、国务院财政部门、审计机关的监督检查人员依法履行监督检查职责。\n第四十七条 中国储备粮管理总公司及其分支机构应当加强对中央储备粮的经营管理和检查，对中央储备粮的数量、质量存在的问题，应当及时予以纠正；对危及中央储备粮储存安全的重大问题，应当立即采取有效措施予以处理，并报告国家粮食行政管理部门、国务院财政部门及中国农业发展银行。\n第四十八条 中国农业发展银行应当按照资金封闭管理的规定，加强对中央储备粮贷款的信贷监管。中国储备粮管理总公司及其分支机构、承储企业对中国农业发展银行依法进行的信贷监管，应当予以配合，并及时提供有关资料和情况。","level":1},{"name":"第六章 法律责任","text":"第四十九条 国家机关工作人员违反本条例规定，有下列行为之一的，给予警告直至撤职的行政处分；情节严重的，给予降级直至开除的行政处分；构成犯罪的，依法追究刑事责任：\n(一)不及时下达中央储备粮收购、销售及年度轮换计划的；\n(二)给予不具备代储条件的企业代储中央储备粮资格，或者发现中央储备粮代储企业不再具备代储条件不及时取消其代储资格的；\n(三)发现中国储备粮管理总公司直属企业存在不适于储存中央储备粮的情况不责成中国储备粮管理总公司对其限期整改的；\n(四)接到举报、发现违法行为不及时查处的。\n第五十条 中国储备粮管理总公司及其分支机构违反本条例规定，有下列行为之一的，由国家粮食行政管理部门责令改正；对直接负责的主管人员和其他直接责任人员，责成中国储备粮管理总公司给予警告直至撤职的纪律处分；情节严重的，对直接负责的主管人员和其他直接责任人员给予降级直至开除的纪律处分；构成犯罪的，依法追究刑事责任：\n(一)拒不组织实施或者擅自改变中央储备粮收购、销售、年度轮换计划及动用命令的；\n(二)选择未取得代储中央储备粮资格的企业代储中央储备粮的；\n(三)发现中央储备粮的数量、质量存在问题不及时纠正，或者发现危及中央储备粮储存安全的重大问题，不立即采取有效措施处理并按照规定报告的；\n(四)拒绝、阻挠、干涉国家粮食行政管理部门、国务院财政部门、审计机关的监督检查人员依法履行监督检查职责的。\n第五十一条 承储企业违反本条例规定，有下列行为之一的，由国家粮食行政管理部门责成中国储备粮管理总公司对其限期改正；情节严重的，对中央储备粮代储企业，还应当取消其代储资格；对直接负责的主管人员和其他直接责任人员给予警告直至开除的纪律处分；构成犯罪的，依法追究刑事责任：\n(一)入库的中央储备粮不符合质量等级和国家标准要求的；\n(二)对中央储备粮未实行专仓储存、专人保管、专账记载，中央储备粮账账不符、账实不符的；\n(三)发现中央储备粮的数量、质量和储存安全等方面的问题不及时处理，或者处理不了不及时报告的；\n(四)拒绝、阻挠、干涉国家粮食行政管理部门、国务院财政部门、审计机关的监督检查人员或者中国储备粮管理总公司的检查人员依法履行职责的。\n第五十二条 承储企业违反本条例规定，有下列行为之一的，由国家粮食行政管理部门责成中国储备粮管理总公司对其限期改正；有违法所得的，没收违法所得；对直接负责的主管人员给予降级直至开除的纪律处分；对其他直接责任人员给予警告直至开除的纪律处分；构成犯罪的，依法追究刑事责任；对中央储备粮代储企业，取消其代储资格：\n(一)虚报、瞒报中央储备粮数量的；\n(二)在中央储备粮中掺杂掺假、以次充好的；\n(三)擅自串换中央储备粮的品种、变更中央储备粮储存地点的；\n(四)造成中央储备粮陈化、霉变的；\n(五)拒不执行或者擅自改变中央储备粮收购、销售、轮换计划和动用命令的；\n(六)擅自动用中央储备粮的；\n(七)以中央储备粮对外进行担保或者清偿债务的。\n第五十三条 承储企业违反本条例规定，以低价购进高价入账、高价售出低价入账、以旧粮顶替新粮、虚增入库成本等手段套取差价，骗取中央储备粮贷款和贷款利息、管理费用等财政补贴的，由国家粮食行政管理部门、国务院财政部门按照各自职责责成中国储备粮管理总公司对其限期改正，并责令退回骗取的中央储备粮贷款和贷款利息、管理费用等财政补贴；有违法所得的，没收违法所得；对直接负责的主管人员给予降级直至开除的纪律处分；对其他直接责任人员给予警告直至开除的纪律处分；构成犯罪的，依法追究刑事责任；对中央储备粮代储企业，取消其代储资格。\n第五十四条 中央储备粮代储企业将中央储备粮轮换业务与其他业务混合经营的，由国家粮食行政管理部门责成中国储备粮管理总公司对其限期改正；对直接负责的主管人员给予警告直至降级的纪律处分；造成中央储备粮损失的，对直接负责的主管人员给予撤职直至开除的纪律处分，并取消其代储资格。\n第五十五条 违反本条例规定，挤占、截留、挪用中央储备粮贷款或者贷款利息、管理费用等财政补贴，或者擅自更改中央储备粮入库成本的，由国务院财政部门、中国农业发展银行按照各自职责责令改正或者给予信贷制裁；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员依法给予撤职直至开除的纪律处分；构成犯罪的，依法追究刑事责任。\n第五十六条 国家机关和中国农业发展银行的工作人员违反本条例规定，滥用职权、徇私舞弊或者玩忽职守，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予降级直至开除的行政处分或者纪律处分。\n第五十七条 违反本条例规定，破坏中央储备粮仓储设施，偷盗、哄抢、损毁中央储备粮，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依照《中华人民共和国治安管理处罚法》的规定予以处罚；造成财产损失的，依法承担民事赔偿责任。\n第五十八条 本条例规定的对国家机关工作人员的行政处分，依照《中华人民共和国公务员法》的规定执行；对中国储备粮管理总公司及其分支机构、承储企业、中国农业发展银行工作人员的纪律处分，依照国家有关规定执行。","level":1},{"name":"第七章 附则","text":"第五十九条 地方储备粮的管理办法，由省、自治区、直辖市参照本条例制定。\n第六十条 本条例自公布之日起施行。","level":1}]}]);
